INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('26', '2', '26', NULL, '- The Events of Isaac''s Life5.   mshmeret, "charge, ordinance."   mtsvah, "command," special order.   choq, "decree, statute," engraven on stone or metal.   torah, "law," doctrine, system of moral truth.10.   eseq, ''Eseq, "strife."21.   stnah, Sitnah, "opposition."22.   rechobot, Rechoboth, "room."26.   ''achuzat, Achuzzath, "possession."33.   shbah, Shib''ah, "seven; oath."34.   yehudyt, Jehudith, "praised."   be''ery, Beeri, "of a well."   basemat, Basemath, "sweet smell."   ''eylon, Elon, "oak."This chapter presents the leading events in the quiet life of Isaac. It is probable that Abraham was now dead. In that case, Esau and Jacob would be at least fifteen years of age when the following event occurred.Genesis 26:1-5Renewal of the promise to Isaac. "A famine in the land." We left Isaac, after the death of Abraham, at Beer-lahai-roi Genesis 25:11. The preceding events have only brought us up to the same point of time. This well was in the land of the south Genesis 24:62. The present famine is distinguished from what occurred in the time of Abraham Genesis 12:10. The interval between them is at least a hundred years. The author of this, the ninth document, is, we find, acquainted with the seventh document; and the famine to which he refers is among the earliest events recorded in it. There is no reason to doubt, then, that he has the whole history of Abraham before his mind. "Unto Abimelek unto Gerar." The Abimelek with whom Abraham had contact about eighty years before may have been the father of the present sovereign. Both Abimelek and Phikol seem to have been official names. Gerar Genesis 10:19 was apparently on the brook of Mizraim Numbers 34:5, the Wady el-Arish, or the Wady el-Khubarah, a northern affluent of the former, or in the interval between them. It is on the way to Egypt, and is the southern city of the Philistines, who probably came from Egypt Genesis 10:14. Isaac was drawing toward Egypt, when he came to Gerar.', NULL, NULL, '''-5'':108 ''1'':107 ''10'':177,272,328 ''11'':135 ''12'':176 ''14'':329 ''19'':273 ''21'':32 ''22'':36 ''24'':160 ''25'':134 ''26'':40,106 ''33'':44 ''34'':50,282 ''5'':283 ''62'':161 ''abimelek'':237,241,261 ''abraham'':83,127,174,232,244 ''achuzat'':41 ''achuzzath'':42 ''acquaint'':198 ''affluent'':297 ''age'':100 ''ah'':47 ''among'':211 ''appar'':275 ''arish'':288 ''author'':189 ''basemat'':60 ''basemath'':61 ''beer'':130 ''beer-lahai-roi'':129 ''beeri'':56 ''brook'':278 ''brought'':141 ''came'':324,337 ''case'':89 ''chapter'':68 ''charg'':8 ''choq'':14 ''citi'':318 ''command'':11 ''contact'':246 ''dead'':86 ''death'':125 ''decre'':15 ''distinguish'':166 ''doctrin'':24 ''document'':194,202 ''doubt'':223 ''draw'':332 ''earliest'':213 ''egypt'':313,326,334 ''eighti'':248 ''el'':287,293 ''el-arish'':286 ''el-khubarah'':292 ''elon'':65 ''engraven'':17 ''eri'':55 ''esau'':90 ''eseq'':29,30 ''event'':2,72,104,138,214 ''eylon'':64 ''famin'':116,164,205 ''father'':255 ''fifteen'':97 ''find'':197 ''follow'':103 ''former'':300 ''genesi'':133,159,175,271,327 ''gerar'':239,270,339 ''histori'':230 ''hundr'':186 ''interv'':179,304 ''isaac'':4,78,114,122,330 ''jacob'':92 ''jehudith'':52 ''khubarah'':294 ''lahai'':131 ''land'':119,155 ''law'':23 ''lead'':71 ''least'':96,184 ''left'':121 ''life'':76 ''life5'':6 ''may'':251 ''metal'':21 ''mind'':235 ''mizraim'':280 ''moral'':27 ''mshmeret'':7 ''mtsvah'':10 ''name'':269 ''ninth'':193 ''northern'':296 ''number'':281 ''oak'':66 ''oath'':49 ''occur'':169 ''occurred.genesis'':105 ''offici'':268 ''opposit'':35 ''order'':13 ''ordin'':9 ''phikol'':263 ''philistin'':321 ''point'':147 ''possess'':43 ''prais'':53 ''preced'':137 ''present'':69,163,258 ''probabl'':81,323 ''promis'':112 ''quiet'':75 ''reason'':221 ''rechobot'':37 ''rechoboth'':38 ''record'':215 ''refer'':209 ''renew'':109 ''roi'':132 ''roo