INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('79', '2', '79', NULL, 'The "waving" was the more solemn process of the two: it was a movement several times repeated, while "heaving" was simply a "lifting up" once.', NULL, NULL, '''heav'':19 ''lift'':23 ''movement'':14 ''process'':7 ''repeat'':17 ''sever'':15 ''simpli'':21 ''solemn'':6 ''time'':16 ''two'':10 ''wave'':2', NULL, '79');
