INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('250', '2', '250', NULL, 'Now ... - Rather "and," since this verse is in immediate dependence upon the preceding. When Jonathan saw the garrison come out again and again, in defiance "of the armies of the living God," at length "upon a day" he determined to attack them.', NULL, NULL, '''armi'':28 ''attack'':41 ''come'':19 ''day'':37 ''defianc'':25 ''depend'':10 ''determin'':39 ''garrison'':18 ''god'':32 ''immedi'':9 ''jonathan'':15 ''length'':34 ''live'':31 ''preced'':13 ''rather'':2 ''saw'':16 ''sinc'':4 ''upon'':11,35 ''vers'':6', NULL, '250');
