INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('634', '2', '634', NULL, 'Surety - The "pledge," or security for payment, which, for example, David was to bring back from his brothers 1 Samuel 17:18. So the word was used in the primitive trade transactions of the early Israelites.In the warnings against this suretyship, in the Book of Proverbs, we may trace the influence of contact with the Phoenicians. The merchants of Tyre and Zidon seem to have discovered the value of credit as an element of wealth. A man might obtain goods, or escape the pressure of a creditor at an inconvenient season, or obtain a loan on more favorable terms, by finding security. To give such security might be one of the kindest offices which one friend could render to another. Side by side, however, with a legitimate system of credit there sprang up, as in later times, a fraudulent counterfeit. Phoenician or Jewish money-lenders (the "stranger") were ready to make their loans to the spendthrift. He was equally ready to find a companion (the "friend") who would become his surety. It was merely a form, just writing a few words, just "a clasping of the hands" (see the marginal reference) in token that the obligation was accepted, and that was all. It would be unfriendly to refuse. And yet, as the teacher warns his hearers, there might be, in that moment of careless weakness, the first link of a long chain of ignominy, galling, fretting, wearing, depriving life of all its peace. The Jewish law of debt, hard and stern like that of most ancient nations, aright be enforced against him in all its rigour. Money and land might go, the very bed under him might be seized, and his garment torn from his back Proverbs 20:16; Proverbs 22:27, the older and more lenient law Exodus 22:25-27 having apparently fallen into disuse. he might be brought into a life-long bondage, subject only to the possible relief of the year of jubilee, when the people were religious enough to remember and observe it. His wives, his sons, his daughters might be sharers in that slavery Nehemiah 5:3-5. It was doubtful whether he could claim the privilege which under Exodus 21:2 belonged to an Israelite slave that had been bought. Against such an evil, no warnings could be too frequent or to urgent.Stricken thy hand - The natural symbol of the promise to keep a contract; in this case, to pay another man''s debts. Compare Proverbs 17:18; Proverbs 22:26; Job 17:3; Ezekiel 17:18.', NULL, NULL, '''-27'':303 ''-5'':356 ''1'':19 ''16'':290 ''17'':21,416,422,425 ''18'':22,417,426 ''2'':370 ''20'':289 ''21'':369 ''22'':292,301,419 ''25'':302 ''26'':420 ''27'':293 ''3'':355,423 ''5'':354 ''accept'':199 ''ancient'':257 ''anoth'':120,410 ''appar'':305 ''aright'':259 ''back'':15,287 ''becom'':170 ''bed'':275 ''belong'':371 ''bondag'':318 ''book'':44 ''bought'':379 ''bring'':14 ''brother'':18 ''brought'':312 ''careless'':225 ''case'':407 ''chain'':233 ''claim'':363 ''clasp'':185 ''companion'':165 ''compar'':414 ''contact'':53 ''contract'':404 ''could'':117,362,386 ''counterfeit'':140 ''credit'':70,130 ''creditor'':87 ''daughter'':346 ''david'':11 ''debt'':249,413 ''depriv'':239 ''discov'':66 ''disus'':308 ''doubt'':359 ''earli'':35 ''element'':73 ''enforc'':261 ''enough'':335 ''equal'':160 ''escap'':82 ''evil'':383 ''exampl'':10 ''exodus'':300,368 ''ezekiel'':424 ''fallen'':306 ''favor'':98 ''find'':101,163 ''first'':228 ''form'':177 ''fraudul'':139 ''frequent'':389 ''fret'':237 ''friend'':116,167 ''gall'':236 ''garment'':283 ''give'':104 ''go'':272 ''good'':80 ''hand'':188,394 ''hard'':250 ''hearer'':217 ''howev'':124 ''ignomini'':235 ''inconveni'':90 ''influenc'':51 ''israelit'':374 ''israelites.in'':36 ''jewish'':143,246 ''job'':421 ''jubile'':329 ''keep'':402 ''kindest'':112 ''land'':270 ''later'':136 ''law'':247,299 ''legitim'':127 ''lender'':146 ''lenient'':298 ''life'':240,316 ''life-long'':315 ''like'':253 ''link'':229 ''loan'':95,154 ''long'':232,317 ''make'':152 ''man'':77,411 ''margin'':191 ''may'':48 ''merchant'':58 ''mere'':175 ''might'':78,107,219,271,278,310,347 ''moment'':223 ''money'':145,268 ''money-lend'':144 ''nation'':258 ''natur'':396 ''nehemiah'':353 ''oblig'':197 ''observ'':339 ''obtain'':79,93 ''offic'':113 ''older'':295 ''one'':109,115 ''pay'':409 ''payment'':7 ''peac'':244 ''peopl'':332 ''phoenician'':56,141 ''pledg'':3 ''possibl'':323 ''pressur'':84 ''primit'':30 ''privileg'':365 ''promis'':400 ''proverb'':46,288,291,415,418 ''readi'':150,161 ''refer'':192 ''refus'':209 ''relief'':324 ''religi'':334 ''rememb'':337 ''render'':118 ''rigour'':267 ''samuel'':20 ''season'':91 ''secur'':5,102,106 ''see'':189 ''seem'':63 ''seiz'':280 ''sharer'':349 ''side'':121,123 ''slave'':375 ''slaveri'':352 ''son'':344 ''spendthrift'':157 ''sprang'':132 ''stern'':252 ''stranger'':148 ''subject'':319 ''sureti'':1,172 ''suretyship'':41 ''symbol'':397 ''system'':128 ''teacher'':214 ''term'':99 ''thi'':393 ''time'':137 ''token'':194 ''torn'':284 ''trace'':49 ''trade'':31 ''transact'':32 ''tyre'':60 ''unfriend'':207 ''urgent.stricken'':392 ''use'':27 ''valu'':68 ''warn'':38,215,385 ''weak'':226 ''wealth'':75 ''wear'':238 ''whether'':360 ''wive'':342 ''word'':25,182 ''would'':169,205 ''write'':179 ''year'':327 ''yet'':211 ''zidon'':62', NULL, '634');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('667', '2', '667', NULL, 'And who - Rather, and as he who knoweth. The possessor of wisdom excels other people: it imparts serenity to his countenance, and removes the expression of gloom or fierceness (see the marginal reference).', NULL, NULL, '''counten'':21 ''excel'':13 ''express'':25 ''fierc'':29 ''gloom'':27 ''impart'':17 ''knoweth'':8 ''margin'':32 ''peopl'':15 ''possessor'':10 ''rather'':3 ''refer'':33 ''remov'':23 ''see'':30 ''seren'':18 ''wisdom'':12', NULL, '667');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('695', '2', '695', NULL, 'Send ye the lamb - Lowth renders this, ''I will send forth the son from the ruler of the land;'' meaning, as he supposes, that under the Assyrian invasion, even the young prince of Moab would be obliged to flee for his life through the desert, that he might escape to Judea; and "that" thus God says that "he" would send him. The only authority for this, however, is, that the Septuagint reads the word ''send'' in the future tense (&#x3b1;&#x3c0;&#x3bf;&#x3c3;&#x3c4;&#x3b5;&#x3bb;&#x3c9;  apostelo) instead of the imperative; and that the Syraic reads   bar instead of   kar, "a lamb." But assuredly this is too slight an authority for making an alteration in the Hebrew text. This is one of the many instances in which Lowth has ventured to suggest a change in the text of Isaiah without sufficient authority. The Septuagint reads this: ''I will send reptiles (&#x3b5;&#x3c1;&#x3c0;&#x3b5;&#x3c4;&#x3b1;  herpeta) upon the land. Is not the mountain of the daughter of Zion a desolate rock?'' The Chaldee renders it, ''Bear ye tribute to the Messiah, the anointed of Israel, who is powerful over you who were in the desert, to Mount Zion.'' And this, understanding by the Messiah the anointed king of Israel, is probably the true rendering.The word ''lamb'' (  kar) denotes, properly, a pasture lamb, a fat lamb, and is usually applied to the lamb which was slain in sacrifice. Here it probably means a lamb, or "lambs" collectively, as a tribute, or acknowledgment of subjection to Judah. Lambs were used in the daily sacrifice in the temple, and in the other sacrifices of the Jews. Large numbers of them would, therefore, be needed, and it is not improbable that the "tribute" of the nations subject to them was often required to be paid in animals for burnt-offering. Perhaps there might have been this additional reason for that - that the sending of such animals would be a sort of incidental acknowledgment of the truth of the Jewish religion, and an offering to the God of the Hebrews. At all events, the word here seems to be one that designates "tribute;" and the counsel of the prophet is, that they should send their "tribute" to the Jews.To the ruler of the land - To the king of Judah. This is proved by the addition at the close of the verse, ''unto the mount of the daughter o Zion.'' It is evident from 2 Samuel 8:2, that David subdued the Moabites, and laid them under tribute, so that the ''Moabites became David''s servants, and brought gifts.'' That "lambs" were the specific kind of tribute which the Moabites were to render to the Jews as a token of their subjection, is clearly proved in 2 Kings 3:4 : ''And Mesha, king of Moab, was a sheep-master, and rendered unto the king of Israel an hundred thousand rams, with the wool.'' This was in the time of Ahab. But the Moabites after his death revolted from them, and rebelled 2 Kings 4:5. It is probable that as this tribute was laid by "David" before the separation of the kingdoms of Judah and Israel, and as the kings of Judah claimed to be the true successors of David and Solomon, they demanded that the tribute should be rendered to "them," and not to the kings of Israel, and this is the claim which Isaiah enforces in the passage before us. The command of the prophet is to regain the lost favor of Israel by the payment of the tribute that was due. The territory of Moab was in early times, and is still, rich in flocks of sheep. Seetzen made his journey with some inhabitants of Hebron and Jerusalem who had purchased sheep in that region. Lambs and sheep were often demanded in tribute. The Persians received fifty thousand sheep as a tribute annually from the Cappadocians, and one hundred thousand from the Medes (Strabo, ii.362).From Sela in the wilderness - The word ''Sela'' (  sela'') means "a rock;" and by it here there can be no doubt that there is intended the city of that name which was the capital of "Arabia Petrea." The city was situated within the bounds of Arabia or Idumea, but was probably at this time in the possession of the Moabites. It was, therefore, the remotest part of their territory, and the sense may be, ''Send tribute even from the remotest pat of your land;'' or it may be, that the region around that city was particularly favorable to pasturage, and for keeping flocks. To this place they had fled with their flocks on the invasion from the north (see the note at Isaiah 15:7). Vitringa says that that desert around Petra was regarded as a vast common, on which the Moabites and Arabians promiscuously fed their flocks. The situation of the city of Sela, or (&#x3c0;&#x3b5;&#x3c4;&#x3c1;&#x3b1;  petra) Petra, meaning the same as Sela, a rock, was for a long time unknown, but it has lately been discovered.It lies about a journey of a day and a ball southeast of the southern extremity of the Dead Sea. It derived its name from the fact that it was situated in a vast hollow in a rocky mountain, and consisted almost entirely of dwellings hewn out of the rock. It was the capital of the Edomites 2 K', NULL, NULL, '''15'':776 ''2'':398,401,450,496,886 ''3'':452 ''4'':453,498 ''5'':499 ''7'':777 ''8'':400 ''acknowledg'':239,318 ''addit'':302,379 ''ahab'':484 ''almost'':870 ''alter'':107 ''anim'':291,311 ''annual'':640 ''anoint'':171,194 ''apostelo'':80 ''appli'':217 ''arabia'':688,698 ''arabian'':796 ''around'':744,783 ''assur'':97 ''assyrian'':27 ''author'':64,103,135 ''ball'':839 ''bar'':90 ''bear'':164 ''becam'':416 ''bound'':696 ''brought'':421 ''burnt'':294 ''burnt-off'':293 ''capit'':686,882 ''cappadocian'':643 ''chalde'':161 ''chang'':127 ''citi'':679,691,746,805 ''claim'':527,558 ''clear'':447 ''close'':382 ''collect'':234 ''command'':568 ''common'':790 ''consist'':869 ''counsel'':350 ''daili'':249 ''daughter'':154,391 ''david'':403,417,510,534 ''day'':836 ''dead'':847 ''death'':490 ''demand''