INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1102', '2', '1102', NULL, 't the mercy of God, and implored the aid of his Spirit that his heart may be renewed.', NULL, NULL, '''aid'':9 ''god'':5 ''heart'':15 ''implor'':7 ''may'':16 ''merci'':3 ''renew'':18 ''spirit'':12', NULL, '1000');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1130', '2', '1130', NULL, 'The former treatise - The former book. The Gospel of Luke is here evidently intended. Greek: the former &#x3bb;&#x3bf;&#x3b3;&#x3bf;&#x3c2;  logos, meaning "a discourse," or "a narrative."O Theophilus - See the notes on Luke 1:3. Since this book was written to the same individual as the former, it was evidently written with the same design to furnish an authentic and full narrative of events concerning which there would be many imperfect and exaggerated accounts. See Luke 1:1-4. Since these events pertained to the descent of the Spirit, to the spread of the gospel, to the organization of the church, to the kind of preaching by which the church was to be collected and organized, and as the facts in the case constituted a full proof of the truth of the Christian religion, and the conduct of the apostles would be a model for ministers and the church in all future times, it was of great importance that a fair and full narrative of these things should be preserved. Luke was the companion of Paul in his travels, and was an eye-witness of no small part of the transactions recorded in this book. See Acts 16:10, Acts 16:17; Acts 20:1-6; Acts 27; Acts 28. As an eye-witness, he was well qualified to make a record of the leading events of the primitive church. And as he was the companion of Paul, he had every opportunity of obtaining information about the great events of the gospel of Christ.Of all - That is, of the principal, or most important parts of the life and doctrines of Christ. It cannot mean that he recorded all that Jesus did, as he had omitted many things that have been preserved by the other evangelists. The word "all" is frequently thus used to denote the most important or material facts. See Acts 13:10; 1 Timothy 1:16; James 1:2; Matthew 2:3; Matthew 3:5; Acts 2:5; Romans 11:26; Colossians 1:6. In each of these places the word here translated "all" occurs in the original, and means "many, a large part, the principal portion." It has the same use in all languages. "This word often signifies, indefinitely, a large portion or number, or a great part" (Webster).That Jesus - The Syriac Version adds, "Jesus our Messiah." This version was probably made in the second century.Began to do ... - This is a Hebrew form of expression; meaning the same thing as that Jesus did and taught. See Genesis 9:20, "Noah began to be a farmer," that is, was a farmer. Genesis 2:3, in the Septuagint: "Which God began to create and make"; in the Hebrew, "which God created and made." Mark 4:7, "began to send them forth by two and two," that is, sent them forth. See also Mark 10:32; Mark 14:65, "And some began to spit on him"; in the parallel place in Matthew 26:67, "they did spit in his face."To do - This refers to his miracles and his acts of benevolence, including all that he did for man''s salvation. It probably includes, therefore, his sufferings, death, and resurrection, as a part of what he has done to save people.To teach - His doctrines. As the writer had given an account of what the Lord Jesus did, so he was now about to give a narrative of what his apostles did in the same cause, that thus the world might be in possession of an inspired record respecting the establishment of the Christian church. The record of these events preserved in the sacred narrative is one of the greatest blessings that God has conferred on mankind; and one of the highest privileges which people can enjoy is that which has been conferred so abundantly on this age in the possession of the Word of God.', NULL, NULL, '''-4'':77 ''-6'':205 ''1'':32,75,76,204,315,317,320,335 ''10'':198,314,476 ''11'':332 ''13'':313 ''14'':479 ''16'':197,200,318 ''17'':201 ''2'':321,323,329,436 ''20'':203,423 ''26'':333,494 ''27'':207 ''28'':209 ''3'':33,324,326,437 ''32'':477 ''4'':457 ''5'':327,330 ''6'':336 ''65'':480 ''67'':495