INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('123', '2', '123', NULL, 'The law of the Nazarite is appropriately added to other enactments which concern the sanctity of the holy nation. That sanctity found its highest expression in the Nazarite vow, which was the voluntary adoption for a time of obligations to high and strict modes of self-dedication resembling, and indeed in some particulars exceeding, those under which the priests were placed. The present enactments do not institute a new kind of observance, but only regulate one already familiar to the Israelites Numbers 6:2.', NULL, NULL, '''2'':85 ''6'':84 ''add'':8 ''adopt'':34 ''alreadi'':78 ''appropri'':7 ''concern'':13 ''dedic'':48 ''enact'':11,65 ''exceed'':55 ''express'':25 ''familiar'':79 ''found'':22 ''high'':41 ''highest'':24 ''holi'':18 ''inde'':51 ''institut'':68 ''israelit'':82 ''kind'':71 ''law'':2 ''mode'':44 ''nation'':19 ''nazarit'':5,28 ''new'':70 ''number'':83 ''oblig'':39 ''observ'':73 ''one'':77 ''particular'':54 ''place'':62 ''present'':64 ''priest'':60 ''regul'':76 ''resembl'':49 ''sanctiti'':15,21 ''self'':47 ''self-ded'':46 ''strict'':43 ''time'':37 ''voluntari'':33 ''vow'':29', NULL, '123');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('861', '2', '861', NULL, 'Also I-- I the angel. He alludes here to what he had done on a former occasion to promote the interests of the Hebrew people, and to secure those arrangements which were necessary for their welfare - particularly in the favorable disposition of Darius the Mede toward them.In the first year of Darius the Mede - See the notes at Daniel 5:31. He does not here state the things contemplated or done by Darius in which he had confirmed or strengthened him, but there can be no reasonable doubt that it was the purpose which he had conceived to restore the Jews to their own land, and to give them permission to rebuild their city and temple. Compare Daniel 9:1. It was in that year that Daniel offered his solemn prayer, as recorded in Daniel 9; in that year that, according to the time predicted by Jeremiah (see Daniel 9:2), the captivity would terminate; and in that year that an influence from above led the mind of the Persian king to contemplate the restoration of the captive people. Cyrus was, indeed, the one through whom the edict for their return was promulgated; but as he reigned under his uncle Cyaxares or Darius, and as Cyaxares was the source of authority, it is evident that his mind must have been influenced to grant this favor, and it is to this that the angel here refers.I stood to confirm and to strengthen him - Compare the notes at Daniel 10:13. It would seem that the mind of Darius was not wholly decided; that there were adverse influences bearing on it: that there were probably counselors of his realm who advised against the proposed measures, and the angel here says that he stood by him, and confirmed him in his purpose, and secured the execution of his benevolent plan. Who can prove that an angel may not exert an influence on the heart of kings? And what class of men is there who, when they intend to do good and right, are more likely to have their purposes changed by evil counselors than kings; and who are there that more need a heavenly influence to confirm their design to do right?', NULL, NULL, '''1'':120 ''10'':248 ''13'':249 ''2'':151 ''31'':61 ''5'':60 ''9'':119,136,150 ''accord'':141 ''advers'':265 ''advis'':279 ''allud'':7 ''also'':1 ''angel'':5,233,286,313 ''arrang'':30 ''author'':211 ''bear'':267 ''benevol'':306 ''captiv'':153,178 ''chang'':347 ''citi'':114 ''class'':326 ''compar'':117,243 ''conceiv'':97 ''confirm'':78,238,295,364 ''contempl'':69,173 ''counselor'':274,350 ''cyaxar'':201,206 ''cyrus'':180 ''daniel'':59,118,127,135,149,247 ''darius'':43,52,73,203,257 ''decid'':261 ''design'':366 ''disposit'':41 ''done'':13,71 ''doubt'':88 ''edict'':188 ''evid'':214 ''evil'':349 ''execut'':303 ''exert'':316 ''favor'':40,225 ''first'':49 ''former'':16 ''give'':108 ''good'':337 ''grant'':223 ''heart'':321 ''heaven'':361 ''hebrew'':24 ''inde'':182 ''influenc'':162,221,266,318,362 ''intend'':334 ''interest'':21 ''jeremiah'':147 ''jew'':101 ''king'':171,323,352 ''land'':105 ''led'':165 ''like'':342 ''may'':314 ''measur'':283 ''mede'':45,54 ''men'':328 ''mind'':167,217,255 ''must'':218 ''necessari'':33 ''need'':359 ''note'':57,245 ''occas'':17 ''offer'':128 ''one'':184 ''particular'':37 ''peopl'':25,179 ''permiss'':110 ''persian'':170 ''plan'':307 ''prayer'':131 ''predict'':145 ''probabl'':273 ''promot'':19 ''promulg'':193 ''propos'':282 ''prove'':310 ''purpos'':93,299,346 ''realm'':277 ''reason'':87 ''rebuild'':112 ''record'':133 ''refers.i'':235 ''reign'':197 ''restor'':99,175 ''return'':191 ''right'':339,369 ''say'':288 ''secur'':28,301 ''see'':55,148 ''seem'':252 ''solemn'':130 ''sourc'':209 ''state'':66 ''stood'':236,291 ''strengthen'':80,241 ''templ'':116 ''termin'':155 ''them.in'':47 ''thing'':68 ''time'':144 ''toward'':46 ''uncl'':200 ''welfar'':36 ''wholli'':260 ''would'':154,251 ''year'':50,125,139,159', NULL, '861');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1255', '2', '1255', NULL, 'Now faith is the substance of things hoped for - On the general nature of faith, see the notes on Mark 16:16. The margin here is, "ground or confidence." There is scarcely any verse of the New Testament more important than this, for it states what is the nature of all true faith, and is the only definition of it which is attempted in the Scriptures. Eternal life depends on the existence and exercise of faith Mark 16:16, and hence, the importance of an accurate understanding of its nature. The word rendered "substance" - &#x3c5;&#x3c0;&#x3bf;&#x3c3;&#x3c4;&#x3b1;&#x3c3;&#x3b9;&#x3c2;  hupostasis - occurs in the New Testament only in the following places. In 2 Corinthians 9:4; 2 Corinthians 11:17; Hebrews 3:14, where it is rendered "confident" and "confidence;" and in Hebrews 1:3, where it is rendered "person," and in the passage before us; compare the notes on Hebrews 1:3. Prof. Stuart renders it here "confidence;" Chrysostom, "Faith gives reality or substance to things hoped for."The word properly means "that which is placed under" (Germ. Unterstellen); then "ground, basis, foundation, support." Then it means also "reality, substance, existence," in contradistinction from what is unreal, imaginary, or deceptive (tuschung). "Passow." It seems to me, therefore, that the word here has reference to something which imparts reality in the view of the mind to those things which are not seen, and which serves to distinguish them from those things which are unreal and illusive. It is what enables us to feel and act as if they were real, or which causes them to exert an influence over us as if we saw them. Faith does this on all other subjects as well as religion. A belief that there is such a place as London or Calcutta, leads us to act as if this were so, if we have occasion to go to either; a belief that money may be made in a certain undertaking, leads people to act as if this were so; a belief in the veracity of another leads us to act as if this were so. As long as the faith continues, whether it be well-founded or not, it gives all the force of reality to what is believed. We feel and act just as if it were so, or as if we saw the object before our eyes. This, I think, is the clear meaning here. We do not see the things of eternity. We do not see God, or heaven, or the angels, or the redeemed in glory, or the crowns of victory, or the harps of praise; but we have faith in them, and this leads us to act as if we saw them. And this is, undoubtedly, the fact in regard to all who live by faith and who are fairly under its influence.Of things hoped for - In heaven. Faith gives them reality in the view of the mind. The Christian hopes to be admitted into heaven; to be raised up in the last day from the slumbers of the tomb, to be made perfectly free from sin; to be everlastingly happy. Under the influence of faith he allows these things to control his mind as if they were a most affecting reality.The evidence of things not seen - Of the existence of God; of heaven; of angels; of the glories of the world suited for the redeemed. The word rendered "evidence" - &#x3b5;&#x3bb;&#x3b5;&#x3b3;&#x3c7;&#x3bf;&#x3c2;  elengchos - occurs in the New Testament only in this place and in 2 Timothy 3:16, where it is rendered "reproof." It means properly proof, or means of proving, to wit, evidence; then proof which convinces another of error or guilt; then vindication, or defense; then summary or contents; see "Passow." The idea of "evidence" which goes to demonstrate the thing under consideration, or which is adapted to produce "conviction" in the mind, seems to be the elementary idea in the word. So when a proposition is demonstrated; when a man is arraigned and evidence is furnished of his guilt, or when he establishes his innocence; or when one by argument refutes his adversaries, the idea of "convincing argument" enters into the use of the word in each case.This, I think, is clearly the meaning of the word here. "Faith in the divine declarations answers all the purposes of a convincing argument, or is itself a convincing argument to the mind, of the real existence of those things which are not seen." But is it a good argument? Is it rational to rely on such a means of being convinced? Is mere "faith" a consideration which should ever convince a rational mind? The infidel says "no;" and we know there may be a faith which is no argument of the truth of what is believed. But when a man who has never seen it believes that there is such a place as London, his belief in the numerous testimonies respecting it which he has heard and read is to his mind a good and rational proof of its existence, and he would act on that belief without hesitation. When a son credits the declaration or the promise of a father who has never deceived him, and acts as though that declaration and promise were true, his faith is to him a ground of conviction and of action, and he will act as if these things were so.In like manner the Christian believes what ', NULL, NULL, '''1'':128,146 ''11'':113 ''14'':117 ''16'':21,22,78,79,582 ''17'':114 ''2'':107,111,579 ''3'':116,129,147,581 ''4'':110 ''9'':109 ''accur'':86 ''act'':249,296,324,340,374,443,839,863,887 ''action'':883 ''adapt'':633 ''admit'':490 ''adversari'':680 ''affect'':537 ''allow'':524 ''also'':183 ''angel'':416,552 ''anoth'':336,603 ''answer'':711 ''argument'':677,685,718,724,744,784 ''arraign'':659 ''attempt'':63 ''basi'':177 ''belief'':282,311,331,811,842 ''believ'':370,791,801,898 ''calcutta'':292 ''case.this'':695 ''caus'':257 ''certain'':319 ''christian'':486,897 ''chrysostom'':154 ''clear'':396,699 ''compar'':141 ''confid'':29,122,124,153 ''consider'':629,761 ''content'':615 ''continu'':351 ''contradistinct'':188 ''control'':528 ''convict'':636,880 ''convinc'':602,684,717,723,756,765 ''corinthian'':108,112 ''cre