INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('488', '2', '488', NULL, 'Break thou the arm of the wicked - The arm is the instrument by which we effect a purpose, and especially in wielding a sword or a spear, as in battle; and if the arm is broken, we are powerless. The psalmist, therefore, prays that God would render the wicked, in this respect, powerless.And the evil man - Of all the evil, or the wicked. In regard to the prayer here, see the note at Psalm 5:10.Seek out his wickedness until thou find none - Until it is all punished; until there has been a full recompense. This is a wish that no wicked act of his should be forgotten; that exact justice should be rendered. If it is right to punish the wicked at all, it is right to deal with them just as they deserve; if any wickedness may properly be punished, all may be; and, whatever may occur, the sinner may be assured that he will not be punished merely for a part of his sins. If God punishes the wicked at all, there will be nothing left unpunished.', NULL, NULL, '''10.seek'':76 ''5'':75 ''act'':103 ''arm'':4,9,34 ''assur'':154 ''battl'':30 ''break'':1 ''broken'':36 ''deal'':129 ''deserv'':135 ''effect'':16 ''especi'':20 ''evil'':55,60 ''exact'':110 ''find'':82 ''forgotten'':108 ''full'':94 ''god'':45,169 ''instrument'':12 ''justic'':111 ''left'':179 ''man'':56 ''may'':139,144,148,152 ''mere'':161 ''none'':83 ''note'':72 ''noth'':178 ''occur'':149 ''part'':164 ''powerless'':39 ''powerless.and'':53 ''pray'':43 ''prayer'':68 ''proper'':140 ''psalm'':74 ''psalmist'':41 ''punish'':88,120,142,160,170 ''purpos'':18 ''recompens'':95 ''regard'':65 ''render'':47,114 ''respect'':52 ''right'':118,127 ''see'':70 ''sin'':167 ''sinner'':151 ''spear'':27 ''sword'':24 ''therefor'':42 ''thou'':2,81 ''unpunish'':180 ''whatev'':147 ''wick'':7,49,63,102,122,172 ''wicked'':79,138 ''wield'':22 ''wish'':99 ''would'':46', NULL, '488');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('625', '2', '625', NULL, 'Sing unto the Lord with thanksgiving - Accompany the praise of God - the expression of worship - with a grateful remembrance of the past. The one will aid the other, and the two will constitute acceptable and proper worship. The first word here means properly to answer, or respond; and the idea would seem to be, that we are to make a suitable response or answer to the manifold layouts which we have received at the hand of God.Sing praise upon the harp unto our God - On the word harp, see the notes at Isaiah 5:12. The harp was an instrument commonly employed in divine worship. See the notes at Psalm 33:2 : "Praise the Lord with harp." Compare Psalm 43:4; Psalm 49:4; Psalm 57:8; Psalm 71:22.', NULL, NULL, '''12'':95 ''2'':112 ''22'':130 ''33'':111 ''4'':121,124 ''43'':120 ''49'':123 ''5'':94 ''57'':126 ''71'':129 ''8'':127 ''accept'':34 ''accompani'':7 ''aid'':26 ''answer'':45,64 ''common'':101 ''compar'':118 ''constitut'':33 ''divin'':104 ''employ'':102 ''express'':13 ''first'':39 ''god'':11,84 ''god.sing'':77 ''grate'':18 ''hand'':75 ''harp'':81,88,97,117 ''idea'':50 ''instrument'':100 ''isaiah'':93 ''layout'':68 ''lord'':4,115 ''make'':59 ''manifold'':67 ''mean'':42 ''note'':91,108 ''one'':24 ''past'':22 ''prais'':9,78,113 ''proper'':36,43 ''psalm'':110,119,122,125,128 ''receiv'':72 ''remembr'':19 ''respond'':47 ''respons'':62 ''see'':89,106 ''seem'':52 ''sing'':1 ''suitabl'':61 ''thanksgiv'':6 ''two'':31 ''unto'':2,82 ''upon'':79 ''word'':40,87 ''worship'':15,37,105 ''would'':51', NULL, '625');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('626', '2', '626', NULL, 'Praise ye the Lord - See the notes at Psalm 146:1.Praise ye the Lord from the heavens - On the part of the heavens. Let those who dwell in heaven begin the song.Praise him in the heights - All that are in the heights; to wit, in the highest parts of the universe, or the heavens.', NULL, NULL, '''1.praise'':11 ''146'':10 ''begin'':30 ''dwell'':27 ''heaven'':17,23,29,54 ''height'':36,42 ''highest'':47 ''let'':24 ''lord'':4,14 ''note'':7 ''part'':20,48 ''prais'':1 ''psalm'':9 ''see'':5 ''song.praise'':32 ''univers'':51 ''wit'':44 ''ye'':2,12', NULL, '626');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('563', '2', '563', NULL, 'Lord, thou hast been favorable unto thy land - Margin, "well pleased with." The idea is that he had been kind or propitious to the nation; to wit, on some former occasion. So Luther, (vormals) "formerly." The reference is to some previous period in their history, when he had exercised his power in their behalf.Thou hast brought back the captivity of Jacob - That is, at the time referred to. It is not necessary to suppose that the allusion is to the period immediately preceding the time when the psalm was composed, but it may have been any period in their history. Nor is it necessary to suppose that the people had been removed from their land at the time, for all that would be necessary to suppose in interpreting the language would be that the land had been invaded, even though the inhabitants still remained in it.', NULL, NULL, '''allus'':77 ''back'':57 ''behalf.thou'':54 ''brought'':56 ''captiv'':59 ''compos'':90 ''even'':139 ''exercis'':49 ''favor'':5 ''former'':30,35 ''hast'':3,55 ''histori'':45,100 ''idea'':14 ''immedi'':82 ''inhabit'':142 ''interpret'':128 ''invad'':138 ''jacob'':61 ''kind'':20 ''land'':8,115,135 ''languag'':130 ''lord'':1 ''luther'':33 ''margin'':9 ''may'':93 ''nation'':25 ''necessari'':72,104,124 ''occas'':31 ''peopl'':109 ''period'':42,81,97 ''pleas'':11 ''power'':51 ''preced'':83 ''previous'':41 ''propiti'':22 ''psalm'':88 ''refer'':37,67 ''remain'':144 ''remov'':112 ''still'':143 ''suppos'':74,106,126 ''thi'':7 ''thou'':2 ''though'':140 ''time'':66,85,118 ''unto'':6 ''vormal'':34 ''well'':10 ''wit'':27 ''would'':122,131', NULL, '563');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('570', '2', '570', NULL, 'It is a good thing to give thanks unto the Lord - literally, "Good is it to give thanks unto Jehovah." That is, the act is appropriate; the effect is good.(1) The thing itself is appropriate, for there is much, under all circumstances, to be thankful for: life, health, food, raiment, air, water, friends, recollections, hopes - and, above all, the blessings of redemption, and the assurance that we may be happy forever. Many of these things may be found in the condition of all; but if all else fail, the hope of heaven - the assurance that the Redeemer died - the offer of salvation - cannot fail. That is ours, and cannot be taken away.(2) The effect is good. It is a desirable state of mind. It tends to happiness, contentment, peace. A gloomy mind makes all things around more gloomy; an unthankful mind is an unhappy mind; a murmuring, complaining, dissatisfied mind makes its possessor wretched, and all around him miserable.(3) it is good as it is due to God. For all his favor we should be thankful - and all that we enjoy is his gift.(4) it tends much to lessen the real troubles and afflictions of life to dwell on those things for which we should be thankful.And to sing praises unto thy name - Unto thee. As this psalm was designed for the "Sabbath day," this proves that one of the appropriate services of the Sabbath is "praise." It is a day when it is fit to recall the mercies of God to our recollection; and the remembrance of those mercies, and their celebration by appropriate songs, tend to diffuse joy over all the coming days of the week.O Most High - God exalted over all. The fact that "he" is exalted over all - over us - over our friends - over all worlds - is an appropriate thought when we come before him to praise him; appropriate at all times, and in all circumstances of life.', NULL, NULL, '''1'':31 ''2'':114 ''3'':162 ''4'':188 ''act'':24 ''afflict'':198 ''air'':52 ''appropri'':26,36,235,269,307,317 ''around'':138,159 ''assur'':66,95 ''away'':113 ''bless'':61 ''cannot'':104,110 ''celebr'':267 ''circumst'':43,324 ''come'':278,311 ''complain'':150 ''condit'':82 ''content'':130 ''day'':228,245,279 ''design'':224 ''desir'':122 ''die'':99 ''diffus'':273 ''dissatisfi'':151 ''due'':169 ''dwell'':202 ''effect'':28,116 ''els'':88 ''enjoy'':184 ''exalt'':286,294 ''fact'':290 ''fail'':89,105 ''favor'':175 ''fit'':249 ''food'':50 ''forev'':72 ''found'':79 ''friend'':54,301 ''gift'':187 ''give'':7,17 ''gloomi'':133,140 ''god'':171,255,285 ''good'':4,13,30,118,165 ''happi'':71,129 ''health'':49 ''heaven'':93 ''high'':284 ''hope'':56,91 ''jehovah'':20 ''joy'':274 ''lessen'':193 ''life'':48,200,326 ''liter'':12 ''lord'':11 ''make'':135,153 ''mani'':73 ''may'':69,77 ''merci'':253,264 ''mind'':125,134,143,147,152 ''miser'':161 ''much'':40,191 ''murmur'':149 ''name'':217 ''offer'':101 ''one'':232 ''peac'':131 ''possessor'':155 ''prais'':214,241,315 ''prove'':230 ''psalm'':222 ''raiment'':51 ''real'':195 ''recal'':251 ''recollect'':55,258 ''redeem'':98 ''redempt'':63 ''remembr'':261 ''sabbath'':227,239 ''salvat'':103 ''servic'':236 ''sing'':213 ''song'':270 ''state'':123 ''taken'':112 ''tend'':127,190,271 ''thank'':8,18,46,179 ''thankful.and'':211 ''thee'':219 ''thi'':216 ''thing'':5,33,76,137,205 ''thought'':308 ''time'':320 ''troubl'':196 ''unhappi'':146 ''unthank'':142 ''unto'':9,19,215,218 ''us'':298 ''water'':53 ''week.o'':282 ''world'':304 ''wretch'':156', NULL, '570');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('571', '2', '571', NULL, 'The Lord reigneth - The same commencement of a psalm occurs in Psalm 97:1-12; Psalm 99:1-9. The same idea is often found in the Scriptures. 1 Chronicles 16:31; Psalm 47:8; Isaiah 52:7; Revelation 19:6. The thought seems abrupt here. It would appear as if the psalmist had been meditating on the dark things which occur in the world; the mysteries which abound; the things which seem irreconcilable with the idea that there is a just government over the world, and that suddenly the idea occurs, as a flash of lightning in a storm, that Yahweh reigns over all, and that all must be right. Amidst all these things God sits upon the throne; he orders all events; he sways his scepter over all; he orders all things according to his own will; he secures the accomplishment of his own purposes.He is clothed with majesty - That is, he puts on, or wears this; he appears in this as a garb, or robe. The word rendered "majesty" means properly "loftiness," and is applied to the swelling of the sea Psalm 89:9, or to a column of smoke, Isaiah 9:18. The idea here is, that God is exalted; and that he appears in such a manner as to indicate his proper dignity. See the notes at Isaiah 6:1.The Lord is clothed with strength, wherewith he hath girded himself - There is an allusion here to the mode of dress among the Orientals - the custom of girding the loins when one labored, or walked, or ran. See the notes at Matthew 5:38-41.The world also is stablished - Is firm; is on a solid foundation. It cannot be shaken or destroyed by natural convulsions, or by the power of man.That it cannot be moved - Moved out of its place; overthrown; destroyed. This seems to have been spoken in view of some impending calamity, as if everything were to be swept away. The psalmist consoles himself with the thought that the world was firmly established; that no storm or tempest could be so violent as to remove it out of its place. The ground of consolation is the essential stability of what God has ordained.', NULL, NULL, '''-12'':15 ''-9'':19 ''1'':14,18,29 ''1.the'':225 ''16'':31 ''18'':196 ''19'':40 ''31'':32 ''38-41.the'':268 ''47'':34 ''5'':267 ''52'':37 ''6'':41,224 ''7'':38 ''8'':35 ''89'':186 ''9'':187,195 ''97'':13 ''99'':17 ''abound'':69 ''abrupt'':45 ''accomplish'':143 ''accord'':135 ''allus'':239 ''also'':270 ''amidst'':112 ''among'':246 ''appear'':49,161,208 ''appli'':178 ''away'':325 ''calam'':317 ''cannot'':281,296 ''chronicl'':30 ''cloth'':149,228 ''column'':191 ''commenc'':6 ''consol'':328,359 ''convuls'':288 ''could'':344 ''custom'':250 ''dark'':59 ''destroy'':285,305 ''digniti'':218 ''dress'':245 ''essenti'':362 ''establish'':338 ''event'':124 ''everyth'':320 ''exalt'':204 ''firm'':274,337 ''flash'':95 ''found'':25 ''foundat'':279 ''garb'':166 ''gird'':234,252 ''god'':116,202,366 ''govern'':83 ''ground'':357 ''hath'':233 ''idea'':22,77,91,198 ''impend'':316 ''indic'':215 ''irreconcil'':74 ''isaiah'':36,194,223 ''labor'':257 ''lightn'':97 ''lofti'':175 ''loin'':254 ''lord'':2,226 ''majesti'':151,172 ''man.that'':294 ''manner'':212 ''matthew'':266 ''mean'':173 ''medit'':56 ''mode'':243 ''move'':298,299 ''must'':109 ''mysteri'':67 ''natur'':287 ''note'':221,264 ''occur'':10,62,92 ''often'':24 ''one'':256 ''ordain'':368 ''order'':122,132 ''orient'':248 ''overthrown'':304 ''place'':303,355 ''power'':292 ''proper'':174,217 ''psalm'':9,12,16,33,185 ''psalmist'':53,327 ''purposes.he'':147 ''put'':155 ''ran'':261 ''reign'':103 ''reigneth'':3 ''remov'':350 ''render'':171 ''revel'':39 ''right'':111 ''robe'':168 ''scepter'':128 ''scriptur'':28 ''sea'':184 ''secur'':141 ''see'':219,262 ''seem'':44,73,307 ''shaken'':283 ''sit'':117 ''smoke'':193 ''solid'':278 ''spoken'':311 ''stabil'':363 ''stablish'':272 ''storm'':100,341 ''strength'':230 ''sudden'':89 ''sway'':126 ''swell'':181 ''swept'':324 ''tempest'':343 ''thing'':60,71,115,134 ''thought'':43,332 ''throne'':120 ''upon'':118 ''view'':313 ''violent'':347 ''walk'':259 ''wear'':158 ''wherewith'':231 ''word'':170 ''world'':65,86,269,335 ''would'':48 ''yahweh'':102', NULL, '571');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('577', '2', '577', NULL, 'The Lord reigneth - The Lord, Yahweh, is king. See Psalm 93:1.Let the people tremble - The Septuagint and the Latin Vulgate render this, "Let the people rage" - or, be angry: as if the idea were that God reigned, although the people were enraged, and were opposed to him. The true meaning of the word used here, however, is "tremble," properly signifying to be moved, disturbed, disquieted, thrown into commotion; and then it may mean to be moved with anger, Proverbs 29:9; Isaiah 28:21; or with grief, 2 Samuel 18:33 : or with fear, Psalm 4:4; or with joy, Jeremiah 33:9. Hence, it means to be agitated or moved with fear or reverence; and it refers here to the reverence or awe which one has in the conscious presence of God.He sitteth between the cherubims - See the notes at Psalm 80:1.Let the earth be moved - Margin, "stagger." The word means to move or quake. It occurs nowhere else. Compare the notes at Psalm 18:7. See also Habakkuk 3:6, Habakkuk 3:10.', NULL, NULL, '''1.let'':12,145 ''10'':177 ''18'':91,168 ''2'':89 ''21'':85 ''28'':84 ''29'':81 ''3'':173,176 ''33'':92,103 ''4'':97,98 ''6'':174 ''7'':169 ''80'':144 ''9'':82,104 ''93'':11 ''agit'':110 ''also'':171 ''although'':39 ''anger'':79 ''angri'':30 ''awe'':125 ''cherubim'':138 ''commot'':69 ''compar'':163 ''conscious'':131 ''disquiet'':66 ''disturb'':65 ''earth'':147 ''els'':162 ''enrag'':43 ''fear'':95,114 ''god'':37 ''god.he'':134 ''grief'':88 ''habakkuk'':172,175 ''henc'':105 ''howev'':57 ''idea'':34 ''isaiah'':83 ''jeremiah'':102 ''joy'':101 ''king'':8 ''latin'':20 ''let'':24 ''lord'':2,5 ''margin'':150 ''may'':73 ''mean'':51,74,107,154 ''move'':64,77,112,149,156 ''note'':141,165 ''nowher'':161 ''occur'':160 ''one'':127 ''oppos'':46 ''peopl'':14,26,41 ''presenc'':132 ''proper'':60 ''proverb'':80 ''psalm'':10,96,143,167 ''quak'':158 ''rage'':27 ''refer'':119 ''reign'':38 ''reigneth'':3 ''render'':22 ''rever'':116,123 ''samuel'':90 ''see'':9,139,170 ''septuagint'':17 ''signifi'':61 ''sitteth'':135 ''stagger'':151 ''thrown'':67 ''trembl'':15,59 ''true'':50 ''use'':55 ''vulgat'':21 ''word'':54,153 ''yahweh'':6', NULL, '577');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('578', '2', '578', NULL, 'Serve the Lord with gladness - That is, In your worship, and in all your acts of obedience. Let there be joy in this service. Let it not be with the fear of slaves; not as a matter of compulsion and force; not with reluctance, moroseness, or gloom. Let it be a cheerful, happy service; let it be freely rendered, let it be an occasion of joy to the soul. The service of God is a source of the highest joy that man knows.Come before his presence with singing - As expressive of joy. So the birds sing; so nature rejoices; so should man - intelligent, redeemed, immortal man, be joyful.', NULL, NULL, '''act'':15 ''bird'':95 ''cheer'':52 ''compuls'':39 ''express'':90 ''fear'':31 ''forc'':41 ''freeli'':58 ''glad'':5 ''gloom'':47 ''god'':73 ''happi'':53 ''highest'':79 ''immort'':105 ''intellig'':103 ''joy'':21,66,80,92,108 ''knows.come'':83 ''let'':18,25,48,55,60 ''lord'':3 ''man'':82,102,106 ''matter'':37 ''moros'':45 ''natur'':98 ''obedi'':17 ''occas'':64 ''presenc'':86 ''redeem'':104 ''rejoic'':99 ''reluct'':44 ''render'':59 ''serv'':1 ''servic'':24,54,71 ''sing'':88,96 ''slave'':33 ''soul'':69 ''sourc'':76 ''worship'':10', NULL, '578');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('627', '2', '627', NULL, 'Praise ye the Lord - Margin, Hallelujah. See the notes at Psalm 146:1.Sing unto the Lord a new song - As if there was a new and a special occasion for praise. This would be so if the psalm was composed on the return from the exile; on the rebuilding of the city; and on the re-dedication of the temple. On the meaning of the language, see Psalm 33:3, note; Revelation 5:9, note; Revelation 14:3, note; see also Psalm 96:1; Isaiah 42:10.And his praise in the congregation of saints - In the assembly of the people of God. See Psalm 148:14, note; Psalm 111:1, note.', NULL, NULL, '''1'':85,111 ''1.sing'':13 ''10.and'':88 ''111'':110 ''14'':78,107 ''146'':12 ''148'':106 ''3'':71,79 ''33'':70 ''42'':87 ''5'':74 ''9'':75 ''96'':84 ''also'':82 ''assembl'':98 ''citi'':52 ''compos'':40 ''congreg'':93 ''dedic'':58 ''exil'':46 ''god'':103 ''hallelujah'':6 ''isaiah'':86 ''languag'':67 ''lord'':4,16 ''margin'':5 ''mean'':64 ''new'':18,25 ''note'':9,72,76,80,108,112 ''occas'':29 ''peopl'':101 ''prais'':1,31,90 ''psalm'':11,38,69,83,105,109 ''re'':57 ''re-ded'':56 ''rebuild'':49 ''return'':43 ''revel'':73,77 ''saint'':95 ''see'':7,68,81,104 ''song'':19 ''special'':28 ''templ'':61 ''unto'':14 ''would'':33 ''ye'':2', NULL, '627');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('628', '2', '628', NULL, 'Praise ye the Lord - See the notes at Psalm 146:1.Praise God in his sanctuary - His holy place; the place where he dwells. The allusion here is, probably, to the temple, the place of his abode on earth.Praise him in the firmament of his power - The whole expression is equivalent to earth and heaven; Praise him on earth; praise him in heaven. The word rendered firmament is the same which is used in Genesis 1:6. It properly means an expanse - a thing spread out. The verb from which the word is derived means to beat; then, to beat out - that is, to spread out by beating, as gold is; and then, simply to spread out, to expand. Compare Psalm 136:6; Isaiah 42:5; Isaiah 44:24. In Syriac the word means to make firm; but this idea is not necessarily in the Hebrew word. The idea of a firmament as something firm is derived from the Septuagint - in Genesis 1:6, &#x3c3;&#x3c4;&#x3b5;&#x3c1;&#x3b5;&#x3c9;&#x3bc;&#x3b1;  stereoma - in this place, &#x3b5;&#x3bd; &#x3c3;&#x3c4;&#x3b5;&#x3c1;&#x3b5;&#x3c9;&#x3bc;&#x3b1;&#x3c4;&#x3b9;  en stereomati. The Hebrew, however, merely means "an expanse" - something spread out, as the heavens seem to us to be "stretched out;" and the call here is on all that dwell above that expanse - in heaven - to unite with those on earth in his praise. It is called "the expanse of his power" because it is in the heavens - in the sun, the moon, the stars - that the power of God seems to be principally displayed.', NULL, NULL, '''1'':75,162 ''1.praise'':11 ''136'':121 ''146'':10 ''24'':128 ''42'':124 ''44'':127 ''5'':125 ''6'':76,122,163 ''abod'':36 ''allus'':25 ''beat'':96,99,107 ''call'':192,215 ''compar'':119 ''deriv'':93,156 ''display'':243 ''dwell'':23,198 ''earth'':52,58,209 ''earth.praise'':38 ''en'':168 ''equival'':50 ''expand'':118 ''expans'':81,176,201,217 ''express'':48 ''firm'':136,154 ''firmament'':42,66,151 ''genesi'':74,161 ''god'':12,238 ''gold'':109 ''heaven'':54,62,182,203,226 ''hebrew'':145,171 ''holi'':17 ''howev'':172 ''idea'':139,148 ''isaiah'':123,126 ''lord'':4 ''make'':135 ''mean'':79,94,133,174 ''mere'':173 ''moon'':231 ''necessarili'':142 ''note'':7 ''place'':18,20,33,167 ''power'':45,220,236 ''prais'':1,55,59,212 ''princip'':242 ''probabl'':28 ''proper'':78 ''psalm'':9,120 ''render'':65 ''sanctuari'':15 ''see'':5 ''seem'':183,239 ''septuagint'':159 ''simpli'':113 ''someth'':153,177 ''spread'':84,104,115,178 ''star'':233 ''stereoma'':164 ''stereomati'':169 ''stretch'':188 ''sun'':229 ''syriac'':130 ''templ'':31 ''thing'':83 ''unit'':205 ''us'':185 ''use'':72 ''verb'':87 ''whole'':47 ''word'':64,91,132,146 ''ye'':2', NULL, '628');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('629', '2', '629', NULL, 'The long exhortation Proverbs 1-9, characterized by the frequent recurrence of the words "my son," is of the nature of a preface to the collection of the "Proverbs of Solomon" Proverbs 10:1. On Proverbs 1:1-7, see the introduction to Proverbs.', NULL, NULL, '''-7'':39 ''-9'':6 ''1'':5,34,37,38 ''10'':33 ''character'':7 ''collect'':26 ''exhort'':3 ''frequent'':10 ''introduct'':42 ''long'':2 ''natur'':20 ''prefac'':23 ''proverb'':4,29,32,36,44 ''recurr'':11 ''see'':40 ''solomon'':31 ''son'':16 ''word'':14', NULL, '629');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('579', '2', '579', NULL, 'I will sing of mercy and judgment - That is, In the psalm which he was about to compose, he would make these the burden of his song; he would, in fact, by stating his views as to the regulation of his own conduct, commend these virtues - mercy and justice - to mankind, and celebrate their value. He who himself "adopts" the principles of mercy, kindness, truth, and justice, as his own guide, commends these virtues to mankind in the best way possible. No language can do it effectually, unless a man practices these virtues himself.Unto thee, O Lord, will I sing - As commending and approving these things; as having put it into my heart to practice them; as displaying them in thine own higher administration: for a father of a family, or a magistrate, is but the representative of God.', NULL, NULL, '''administr'':124 ''adopt'':59 ''approv'':104 ''best'':79 ''burden'':24 ''celebr'':53 ''commend'':44,72,102 ''compos'':18 ''conduct'':43 ''display'':118 ''effectu'':87 ''fact'':31 ''famili'':130 ''father'':127 ''god'':139 ''guid'':71 ''heart'':113 ''higher'':123 ''himself.unto'':94 ''judgment'':7 ''justic'':49,67 ''kind'':64 ''languag'':83 ''lord'':97 ''magistr'':133 ''make'':21 ''man'':90 ''mankind'':51,76 ''merci'':5,47,63 ''o'':96 ''possibl'':81 ''practic'':91,115 ''principl'':61 ''psalm'':12 ''put'':109 ''regul'':39 ''repres'':137 ''sing'':3,100 ''song'':27 ''state'':33 ''thee'':95 ''thine'':121 ''thing'':106 ''truth'':65 ''unless'':88 ''valu'':55 ''view'':35 ''virtu'':46,74,93 ''way'':80 ''would'':20,29', NULL, '579');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('516', '2', '516', NULL, 'For I am ready to halt - Margin, as in Hebrew, "for halting." The word from which the word used here is derived means properly to lean on one side, and then to halt or limp. The meaning here is, that he was like one who was limping along, and who was ready to fall; that is, in the case here referred to, he felt that his strength was almost gone, and that he was in continual danger of falling into sin, or sinking under his accumulated burdens, and of thus giving occasion for all that his enemies said of him, or occasion for their triumphing over him. Men often have this feeling - that their sorrows are so great that they cannot hope to hold out much longer, and that if God does not interpose they must fall.And my sorrow is continually before me - That is, my grief or suffering is unintermitted. Probably the reference here is particularly to that which "caused" his grief, or which was the source of his trouble - his sin. The fact that he was a sinner was never absent from his mind; that was the source of all his trouble; that was what so pressed upon him that it was likely to crush him to the dust.', NULL, NULL, '''absent'':183 ''accumul'':86 ''almost'':69 ''along'':48 ''burden'':87 ''cannot'':121 ''case'':59 ''caus'':161 ''continu'':76,141 ''crush'':207 ''danger'':77 ''deriv'':22 ''dust'':211 ''enemi'':97 ''fact'':175 ''fall'':54,79 ''fall.and'':137 ''feel'':112 ''felt'':64 ''give'':91 ''god'':131 ''gone'':70 ''great'':118 ''grief'':147,163 ''halt'':6,12,33 ''hebrew'':10 ''hold'':124 ''hope'':122 ''interpos'':134 ''lean'':26 ''like'':43,205 ''limp'':35,47 ''longer'':127 ''margin'':7 ''mean'':23,37 ''men'':108 ''mind'':186 ''much'':126 ''must'':136 ''never'':182 ''occas'':92,102 ''often'':109 ''one'':28,44 ''particular'':157 ''press'':199 ''probabl'':152 ''proper'':24 ''readi'':4,52 ''refer'':61,154 ''said'':98 ''side'':29 ''sin'':81,173 ''sink'':83 ''sinner'':180 ''sorrow'':115,139 ''sourc'':168,190 ''strength'':67 ''suffer'':149 ''thus'':90 ''triumph'':105 ''troubl'':171,194 ''unintermit'':151 ''upon'':200 ''use'':19 ''word'':14,18', NULL, '516');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('518', '2', '518', NULL, 'I waited patiently for the Lord - Margin, as in Hebrew, "In waiting I waited." That is, "I continued to wait." It was not a single, momentary act of expectation or hope; it was continuous; or, was persevered in. The idea is, that his prayer was not answered at once, but that it was answered after he had made repeated prayers, or when it seemed as if his prayers would not be answered. It is earnest, persevering prayer that is referred to; it is continued supplication and hope when there seemed to be no answer to prayer, and no prospect that it would be answered.And he inclined unto me - That is, ultimately he heard and answered me; or he turned himself favorably toward me, as the result of "persevering" prayer. The word "inclined" here means properly "bowed;" that is, he "bent forward" to hearken, or to place his ear near my mouth and to hear me. At first, he seemed as one that would not hear; as one that throws his head backward or turns his head away. Ultimately, however, he bent forward to receive my prayer.And heard my cry - The cry or supplication which I made for help; the cry which I directed to him in the depth of my sorrows and my danger, Psalm 40:2. As applied to the Redeemer, this would refer to the fact that in his sorrows, in the deep sorrows connected with the work of redemption, he persevered in calling on God, and that God heard him, and raised him up to glory and joy. See Matthew 26:36-46. Compare the notes at Hebrews 5:7. The time supposed to be referred to, is after his sufferings were closed; after his work was done; "after" he rose from the dead. It is the language of grateful remembrance which we may suppose he uttered in the review of the amazing sorrows through which he had passed in making the atonement, and in the recollection that God had kept him in those sorrows, and had brought him up from such a depth of woe to such a height of glory.', NULL, NULL, '''-46'':266 ''2'':217 ''26'':264 ''36'':265 ''40'':216 ''5'':272 ''7'':273 ''act'':27 ''amaz'':316 ''answer'':47,54,72,94,115 ''answered.and'':104 ''appli'':219 ''aton'':326 ''away'':177 ''backward'':172 ''bent'':140,181 ''bow'':136 ''brought'':341 ''call'':246 ''close'':286 ''compar'':267 ''connect'':237 ''continu'':18,34,84 ''cri'':189,191,200 ''danger'':214 ''dead'':297 ''deep'':235 ''depth'':208,347 ''direct'':203 ''done'':291 ''ear'':148 ''earnest'':75 ''expect'':29 ''fact'':228 ''favor'':121 ''first'':157 ''forward'':141,182 ''glori'':259,355 ''god'':248,251,332 ''grate'':303 ''head'':171,176 ''hear'':154,165 ''heard'':113,187,252 ''hearken'':143 ''hebrew'':10,271 ''height'':353 ''help'':198 ''hope'':31,87 ''howev'':179 ''idea'':40 ''inclin'':106,132 ''joy'':261 ''kept'':334 ''languag'':301 ''lord'':6 ''made'':58,196 ''make'':324 ''margin'':7 ''matthew'':263 ''may'':307 ''mean'':134 ''momentari'':26 ''mouth'':151 ''near'':149 ''note'':269 ''one'':161,167 ''pass'':322 ''patient'':3 ''persev'':37,76,128,244 ''place'':146 ''prayer'':44,60,68,77,96,129 ''prayer.and'':186 ''proper'':135 ''prospect'':99 ''psalm'':215 ''rais'':255 ''receiv'':184 ''recollect'':330 ''redeem'':222 ''redempt'':242 ''refer'':80,225,279 ''remembr'':304 ''repeat'':59 ''result'':126 ''review'':313 ''rose'':294 ''see'':262 ''seem'':64,90,159 ''singl'':25 ''sorrow'':211,232,236,317,338 ''suffer'':284 ''supplic'':85,193 ''suppos'':276,308 ''throw'':169 ''time'':275 ''toward'':122 ''turn'':119,174 ''ultim'':111,178 ''unto'':107 ''utter'':310 ''wait'':2,12,14,20 ''woe'':349 ''word'':131 ''work'':240,289 ''would'':69,102,163,224', NULL, '518');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('580', '2', '580', NULL, 'Hear my prayer, O Lord - The prayer which I offer in view of my personal trials; the prayer which I offer as one of an afflicted people. Compare Psalm 4:1; Psalm 17:1; Psalm 18:6.And let my cry come unto thee - My prayer, accompanied with an outward expression of my earnestness. It was not a silent, or a mental prayer; it was a loud and earnest cry. Psalm 5:2; Psalm 18:6, Psalm 18:41; Psalm 30:2; Psalm 72:12; Job 35:9; Job 36:13.', NULL, NULL, '''1'':31,34 ''12'':84 ''13'':90 ''17'':33 ''18'':36,74,77 ''2'':72,81 ''30'':80 ''35'':86 ''36'':89 ''4'':30 ''41'':78 ''5'':71 ''6'':75 ''6.and'':37 ''72'':83 ''9'':87 ''accompani'':46 ''afflict'':26 ''come'':41 ''compar'':28 ''cri'':40,69 ''earnest'':53,68 ''express'':50 ''hear'':1 ''job'':85,88 ''let'':38 ''lord'':5 ''loud'':66 ''mental'':61 ''o'':4 ''offer'':10,21 ''one'':23 ''outward'':49 ''peopl'':27 ''person'':15 ''prayer'':3,7,18,45,62 ''psalm'':29,32,35,70,73,76,79,82 ''silent'':58 ''thee'':43 ''trial'':16 ''unto'':42 ''view'':12', NULL, '580');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('581', '2', '581', NULL, 'Bless the Lord, O my soul - The word "bless," as applied to God, means to praise, implying always a strong affection for him as well as a sense of gratitude. As used with reference to people, the word implies a "wish" that they may be blessed or happy, accompanied often with a prayer that they may be so. Such is the purport of the "blessing" addressed to a congregation of worshippers. Compare Numbers 6:23-27. The word "soul" here is equivalent to mind or heart: my mental and moral powers, as capable of understanding and appreciating his favors. The soul of man was "made" to praise and bless God; to enjoy his friendship; to delight in his favor; to contemplate his perfections. It can never be employed in a more appropriate or a more elevated act than when engaged in his praise.And all that is within me ... - All my powers and faculties; all that can be employed in his praise: the heart, the will, the affections, the emotions. The idea is, that God is worthy of all the praise and adoration which the entire man can render. No one of his faculties or powers should be exempt from the duty and the privilege of praise.', NULL, NULL, '''-27'':76 ''23'':75 ''6'':74 ''accompani'':49 ''act'':137 ''address'':66 ''ador'':182 ''affect'':21,167 ''alway'':18 ''appli'':11 ''appreci'':97 ''appropri'':132 ''bless'':1,9,46,65,109 ''capabl'':93 ''compar'':72 ''congreg'':69 ''contempl'':121 ''delight'':116 ''duti'':201 ''elev'':136 ''emot'':169 ''employ'':128,158 ''engag'':140 ''enjoy'':112 ''entir'':185 ''equival'':82 ''exempt'':198 ''faculti'':153,193 ''favor'':99,119 ''friendship'':114 ''god'':13,110,174 ''gratitud'':30 ''happi'':48 ''heart'':86,163 ''idea'':171 ''impli'':17,39 ''lord'':3 ''made'':105 ''man'':103,186 ''may'':44,56 ''mean'':14 ''mental'':88 ''mind'':84 ''moral'':90 ''never'':126 ''number'':73 ''o'':4 ''often'':50 ''one'':190 ''peopl'':36 ''perfect'':123 ''power'':91,151,195 ''prais'':16,107,161,180,206 ''praise.and'':143 ''prayer'':53 ''privileg'':204 ''purport'':62 ''refer'':34 ''render'':188 ''sens'':28 ''soul'':6,79,101 ''strong'':20 ''understand'':95 ''use'':32 ''well'':25 ''wish'':41 ''within'':147 ''word'':8,38,78 ''worshipp'':71 ''worthi'':176', NULL, '581');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('489', '2', '489', NULL, 'In the Lord put I my trust - This, in general, expresses the state of mind of the author - a state of feeling which runs through the entire psalm. It is designed to be an answer to the counsel which others had been giving him to escape, and it implies that he was determined at that time, and always, to put his trust in God. They advised him to flee. In the existing circumstances he felt that that would have implied a want of confidence in God. He determined, therefore, to maintain his present position, and to rely upon the interposition of God in due time.How say ye to my soul - How say ye to "me" - the soul being put for the person himself. "Why" do you say this to me? how can you give me such counsel, as if I were to run away from danger, and to put no trust in God? He seems to have supposed that such an act of flight would have been construed by his enemies, and by the enemies of religion, as evidence that he had no faith or confidence in God. Such circumstances often occur in the world; and when that would be the "fair" and "natural" construction of one''s conduct, the path of duty is plain. We are to remain where we are; we are boldly to face the danger, and commit the whole matter to God.Flee as a bird to your mountain - This implies that it was supposed there was no longer any safety where he then was. The use of the plural number here - "Flee ye," by a change not uncommon in the Hebrew writings - seems designed to refer to the whole class of persons in those circumstances. The mind turns from his own particular case to that of others in the same circumstances; and the language may be designed to imply that this was the usual counsel given to such persons; that, on the same principle on which they now advised flight in this particular case, they would also advise flight in all similar cases. That is, they would counsel persons to flee to a place of safety when they were in danger of their life from persecution. This is the common counsel of the world; this would be the ordinary teaching of human prudence. The mountains in Palestine were regarded as places of safety, and were the common refuge of those who were in danger. In their caves and fastnesses, and on their heights, those who were in danger found security, for they could there hide themselves, or could more easily defend themselves, than they could in the plains and in the vallies. Hence, they became the place of retreat for robbers and banditti, as well as for the persecuted. The allusion to the bird here does not imply that birds sought a refuge in the mountains, and that he was to resemble them in this respect; but the point of the comparison turns on the rapidity with which this refuge should be sought:" Fly to the mountains as swiftly as a bird flies from danger." Compare Matthew 24:16; Judges 6:2; Hebrews 11:38.', NULL, NULL, '''11'':528 ''16'':523 ''2'':526 ''24'':522 ''38'':529 ''6'':525 ''act'':162 ''advis'':66,333,342 ''allus'':465 ''also'':341 ''alway'':58 ''answer'':35 ''author'':18 ''away'':144 ''banditti'':457 ''becam'':449 ''bird'':239,468,474,516 ''bold'':225 ''case'':297,338,347 ''cave'':411 ''chang'':270 ''circumst'':73,190,289,305 ''class'':284 ''commit'':231 ''common'':374,401 ''compar'':520 ''comparison'':496 ''conduct'':209 ''confid'':84,186 ''constru'':168 ''construct'':205 ''could'':427,432,439 ''counsel'':38,137,319,352,375 ''danger'':146,229,365,408,422,519 ''defend'':435 ''design'':31,278,311 ''determin'':53,88 ''due'':104 ''duti'':213 ''easili'':434 ''enemi'':171,175 ''entir'':27 ''escap'':46 ''evid'':179 ''exist'':72 ''express'':11 ''face'':227 ''fair'':202 ''faith'':184 ''fast'':413 ''feel'':22 ''felt'':75 ''flee'':69,266,355 ''fli'':508,517 ''flight'':164,334,343 ''found'':423 ''general'':10 ''give'':43,134 ''given'':320 ''god'':64,86,102,153,188 ''god.flee'':236 ''hebrew'':275,527 ''height'':417 ''henc'':447 ''hide'':429 ''human'':386 ''impli'':49,80,244,313,472 ''interposit'':100 ''judg'':524 ''languag'':308 ''life'':368 ''longer'':252 ''lord'':3 ''maintain'':91 ''matter'':234 ''matthew'':521 ''may'':309 ''mind'':15,291 ''mountain'':242,389,480,511 ''natur'':204 ''number'':264 ''occur'':192 ''often'':191 ''one'':207 ''ordinari'':383 ''other'':40,301 ''palestin'':391 ''particular'':296,337 ''path'':211 ''persecut'':370,463 ''person'':122,286,323,353 ''place'':358,395,451 ''plain'':215,442 ''plural'':263 ''point'':493 ''posit'':94 ''present'':93 ''principl'':328 ''prudenc'':387 ''psalm'':28 ''put'':4,60,119,149 ''rapid'':500 ''refer'':280 ''refug'':402,477,504 ''regard'':393 ''reli'':97 ''religion'':177 ''remain'':219 ''resembl'':486 ''respect'':490 ''retreat'':453 ''robber'':455 ''run'':24,143 ''safeti'':254,360,397 ''say'':106,112,127 ''secur'':424 ''seem'':155,277 ''similar'':346 ''sought'':475,507 ''soul'':110,117 ''state'':13,20 ''suppos'':158,248 ''swift'':513 ''teach'':384 ''therefor'':89 ''time'':56 ''time.how'':105 ''trust'':7,62,151 ''turn'':292,497 ''uncommon'':272 ''upon'':98 ''use'':260 ''usual'':318 ''valli'':446 ''want'':82 ''well'':459 ''whole'':233,283 ''world'':195,378 ''would'':78,165,199,340,351,380 ''write'':276 ''ye'':107,113,267', NULL, '489');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('582', '2', '582', NULL, 'Bless the Lord, O my soul - See Psalm 103:1.O Lord my God, thou art very great - This is a reason why the psalmist calls on his soul to bless God; namely, for the fact that he is so exalted; so vast in his perfections; so powerful, so wise, so great.Thou art clothed with honor and majesty - That is, with the emblems of honor and majesty, as a king is arrayed in royal robes. Creation is the garment with which God has invested himself. Compare the notes at Psalm 93:1.', NULL, NULL, '''1'':10,92 ''103'':9 ''93'':91 ''array'':72 ''art'':16,53 ''bless'':1,31 ''call'':26 ''cloth'':54 ''compar'':86 ''creation'':76 ''emblem'':63 ''exalt'':41 ''fact'':36 ''garment'':79 ''god'':14,32,82 ''great'':18 ''great.thou'':52 ''honor'':56,65 ''invest'':84 ''king'':70 ''lord'':3,12 ''majesti'':58,67 ''name'':33 ''note'':88 ''o'':4,11 ''perfect'':46 ''power'':48 ''psalm'':8,90 ''psalmist'':25 ''reason'':22 ''robe'':75 ''royal'':74 ''see'':7 ''soul'':6,29 ''thou'':15 ''vast'':43 ''wise'':50', NULL, '582');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('519', '2', '519', NULL, 'Blessed is he - See the notes at Psalm 1:1. Literally, "Oh the blessings of him that considers the poor." The object is to describe the advantages of doing what is here said; or the excellence of the spirit which would be manifested in such a case, and the effect which this would have on his own happiness. These happy effects are described in the remainder of this verse, and in the two following verses.That considereth - The word used here - from   sakal - means properly to look at, to behold; then, to be prudent or circumspect; then, to attend to; and then in general to act prudently, wisely, intelligently, in any case. Here it means to attend to; to show an interest in; to care for. The idea is that of not neglecting; not passing by; not being indifferent to; not being hard-hearted and uncharitable toward.The poor - Margin, "the weak," or "the sick." The word used in the Hebrew -   dal - means properly something hanging or swinging, as of pendulous boughs or branches; and then, that which is weak, feeble, powerless. Thus it comes to denote those who are feeble and helpless either by poverty or by disease, and is used with a general reference to those who are in slow or humble condition, and who need the aid of others. The statement here is of a general nature - that he is blessed who shows proper sympathy for all of that class: for those who need the sympathy of others from any cause - poverty, sickness, a low condition, or trouble. The particular thing here referred to was a case of sickness; where one was borne down by disease, perhaps brought on by mental sorrow, and when he particularly needed the sympathy of his friends. See Psalm 41:5-8.The Lord will deliver him in time of trouble - Margin, as in Hebrew: "in the day of evil." This is the first happy effect or result of showing proper sympathy with others in their troubles. It is a statement of the general principle that the Lord will deal with us as we do with others. See this principle stated and illustrated in Psalm 18:24-26.', NULL, NULL, '''-26'':363 ''1'':9,10 ''18'':361 ''24'':362 ''41'':297 ''5-8.the'':298 ''act'':105 ''advantag'':27 ''aid'':219 ''attend'':98,116 ''behold'':89 ''bless'':1,14,233 ''born'':275 ''bough'':171 ''branch'':173 ''brought'':280 ''care'':124 ''case'':47,111,269 ''caus'':253 ''circumspect'':95 ''class'':242 ''come'':184 ''condit'':214,258 ''consid'':18 ''considereth'':76 ''dal'':161 ''day'':313 ''deal'':345 ''deliv'':301 ''denot'':186 ''describ'':25,63 ''diseas'':198,278 ''effect'':50,61,321 ''either'':193 ''evil'':315 ''excel'':36 ''feebl'':180,190 ''first'':319 ''follow'':74 ''friend'':294 ''general'':103,204,228,339 ''hang'':165 ''happi'':58,60,320 ''hard'':143 ''hard-heart'':142 ''heart'':144 ''hebrew'':160,310 ''helpless'':192 ''humbl'':213 ''idea'':127 ''illustr'':358 ''indiffer'':138 ''intellig'':108 ''interest'':121 ''liter'':11 ''look'':86 ''lord'':299,343 ''low'':257 ''manifest'':43 ''margin'':149,307 ''mean'':83,114,162 ''mental'':283 ''natur'':229 ''need'':217,246,289 ''neglect'':132 ''note'':6 ''object'':22 ''oh'':12 ''one'':273 ''other'':221,250,329,352 ''particular'':262,288 ''pass'':134 ''pendul'':170 ''perhap'':279 ''poor'':20,148 ''poverti'':195,254 ''powerless'':181 ''principl'':340,355 ''proper'':84,163,236,326 ''prudent'':93,106 ''psalm'':8,296,360 ''refer'':205,265 ''remaind'':66 ''result'':323 ''said'':33 ''sakal'':82 ''see'':4,295,353 ''show'':119,235,325 ''sick'':154,255,271 ''slow'':211 ''someth'':164 ''sorrow'':284 ''spirit'':39 ''state'':356 ''statement'':223,336 ''swing'':167 ''sympathi'':237,248,291,327 ''thing'':263 ''thus'':182 ''time'':304 ''toward.the'':147 ''troubl'':260,306,332 ''two'':73 ''uncharit'':146 ''us'':347 ''use'':79,157,201 ''vers'':69 ''verses.that'':75 ''weak'':151,179 ''wise'':107 ''word'':78,156 ''would'':41,53', NULL, '519');
