INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('631', '2', '631', NULL, '"Ways" and "paths" describe the two kinds of roads, the "highway" and the "byway." In both these he who was guided by Wisdom would walk securely.', NULL, NULL, '''byway'':14 ''describ'':4 ''guid'':21 ''highway'':11 ''kind'':7 ''path'':3 ''road'':9 ''secur'':26 ''two'':6 ''walk'':25 ''way'':1 ''wisdom'':23 ''would'':24', NULL, '631');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('632', '2', '632', NULL, 'The words "ye children" indicate as usual a new section returning, after the break of Proverbs 3:27-35, to the old strain of fatherly counsel.', NULL, NULL, '''-35'':19 ''27'':18 ''3'':17 ''break'':14 ''children'':4 ''counsel'':26 ''father'':25 ''indic'':5 ''new'':9 ''old'':22 ''proverb'':16 ''return'':11 ''section'':10 ''strain'':23 ''usual'':7 ''word'':2 ''ye'':3', NULL, '632');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('633', '2', '633', NULL, 'Better, "A loving hind (is she) and pleasant roe." As in the whole circle of Arab and Persian poetry the antelope and the gazelle are the chosen images of beauty, so they served with equal fitness for the masculine and feminine types of it. (Compare the names Tabitha and Dorcas Acts 9:36.', NULL, NULL, '''36'':53 ''9'':52 ''act'':51 ''antelop'':21 ''arab'':16 ''beauti'':30 ''better'':1 ''chosen'':27 ''circl'':14 ''compar'':45 ''dorca'':50 ''equal'':35 ''feminin'':41 ''fit'':36 ''gazell'':24 ''hind'':4 ''imag'':28 ''love'':3 ''masculin'':39 ''name'':47 ''persian'':18 ''pleasant'':8 ''poetri'':19 ''roe'':9 ''serv'':33 ''tabitha'':48 ''type'':42 ''whole'':13', NULL, '633');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('635', '2', '635', NULL, 'The harlot adulteress of an Eastern city is contrasted with the true feminine ideal of the Wisdom who is to be the "sister" and "kinswoman" Proverbs 7:4 of the young man as he goes on his way through life. See Proverbs 8 in the introduction.', NULL, NULL, '''4'':28 ''7'':27 ''8'':43 ''adulteress'':3 ''citi'':7 ''contrast'':9 ''eastern'':6 ''feminin'':13 ''goe'':35 ''harlot'':2 ''ideal'':14 ''introduct'':46 ''kinswoman'':25 ''life'':40 ''man'':32 ''proverb'':26,42 ''see'':41 ''sister'':23 ''true'':12 ''way'':38 ''wisdom'':17 ''young'':31', NULL, '635');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('521', '2', '521', NULL, 'Judge me, O God - This does not mean, Pronounce sentence upon me; but, Undertake my cause; interpose in my behalf; do justice in the case. He regarded his own cause as right; he felt that he was greatly wronged by the treatment which he received from people, and he asks to have it shown that he was not guilty of what his enemies charged on him; that he was an upright man, and a friend of God. See Psalm 7:8, note; Psalm 26:1, note.And plead my cause - See the notes at Psalm 35:1. "Against an ungodly nation." Margin, unmerciful. Literally, "from a nation not merciful," or not; religious. The idea is, that the nation or people referred to manifested none of the spirit of religion in their conduct toward him; that he was treated with severity and injustice. This entire description would agree well with the state of things in the time of the rebellion of Absalom, when David was driven from his home and his throne: 2 Samuel 15, following.O deliver me from the deceitful and unjust man - Margin, as in Hebrew, from a man of deceit and iniquity. This would apply well to the case and character of Absalom, or perhaps more directly and properly to the character and counsel of Ahithophel, among the leading conspirators in the rebellion of Absalom, to whose counsels much of the rebellion was owing: 2 Samuel 15:31; compare 2 Samuel 16:23; 2 Samuel 17:14, 2 Samuel 17:23.', NULL, NULL, '''1'':85,96 ''14'':248 ''15'':173,238 ''16'':243 ''17'':247,251 ''2'':171,236,241,245,249 ''23'':244,252 ''26'':84 ''31'':239 ''35'':95 ''7'':80 ''8'':81 ''absalom'':160,204,226 ''agre'':146 ''ahithophel'':217 ''among'':218 ''appli'':196 ''ask'':50 ''behalf'':20 ''case'':25,200 ''caus'':16,30,89 ''charact'':202,213 ''charg'':64 ''compar'':240 ''conduct'':131 ''conspir'':221 ''counsel'':215,229 ''david'':162 ''deceit'':179,191 ''deliv'':175 ''descript'':144 ''direct'':208 ''driven'':164 ''enemi'':63 ''entir'':143 ''felt'':34 ''following.o'':174 ''friend'':75 ''god'':4,77 ''great'':38 ''guilti'':59 ''hebrew'':186 ''home'':167 ''idea'':113 ''iniqu'':193 ''injustic'':141 ''interpos'':17 ''judg'':1 ''justic'':22 ''lead'':220 ''liter'':103 ''man'':72,182,189 ''manifest'':122 ''margin'':101,183 ''mean'':8 ''merci'':108 ''much'':230 ''nation'':100,106,117 ''none'':123 ''note'':82,92 ''note.and'':86 ''o'':3 ''owe'':235 ''peopl'':47,119 ''perhap'':206 ''plead'':87 ''pronounc'':9 ''proper'':210 ''psalm'':79,83,94 ''rebellion'':158,224,233 ''receiv'':45 ''refer'':120 ''regard'':27 ''religi'':111 ''religion'':128 ''right'':32 ''samuel'':172,237,242,246,250 ''see'':78,90 ''sentenc'':10 ''sever'':139 ''shown'':54 ''spirit'':126 ''state'':150 ''thing'':152 ''throne'':170 ''time'':155 ''toward'':132 ''treat'':137 ''treatment'':42 ''undertak'':14 ''ungod'':99 ''unjust'':181 ''unmerci'':102 ''upon'':11 ''upright'':71 ''well'':147,197 ''whose'':228 ''would'':145,195 ''wrong'':39', NULL, '521');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('522', '2', '522', NULL, 'We have heard with our ears - That is, it has been handed down by tradition.Our fathers have told us - Our ancestors. They have delivered it down from generation to generation. The word rendered "told" means properly to grave, or to insculp on a stone; and thence, to write. Then it comes to mean to number, to count, to recount, to tell, to declare. The word would be applicable to any method of making the thing known, either by hieroglyphic figures in sculpture, by writing, or by oral tradition, though it seems probable that the latter mode is particularly referred to here. Compare Exodus 10:2; Exodus 12:26-27.What work thou didst in their days - The great work which thou didst accomplish for them; or, how thou didst interpose in their behalf. The reference is to what God accomplished for them in delivering them from Egyptian bondage, and bringing them into the land of Canaan.In the times of old - In ancient times; in the beginning of our history. The idea here is, that we may properly appeal to the past - to what God has done in former ages - as an argument for his interposition in similar circumstances now, for,(a) His former interposition showed his power to save;(b) it was such an illustration of his character that we may appeal to that as a reason for asking him to interpose again.', NULL, NULL, '''10'':104 ''12'':107 ''2'':105 ''26-27.what'':108 ''accomplish'':121,138 ''age'':187 ''ancestor'':21 ''ancient'':160 ''appeal'':176,220 ''applic'':68 ''argument'':190 ''ask'':227 ''b'':208 ''begin'':164 ''behalf'':131 ''bondag'':146 ''bring'':148 ''canaan.in'':154 ''charact'':216 ''circumst'':196 ''come'':51 ''compar'':102 ''count'':57 ''day'':114 ''declar'':63 ''deliv'':24,142 ''didst'':111,120,127 ''done'':184 ''ear'':6 ''egyptian'':145 ''either'':77 ''exodus'':103,106 ''father'':16 ''figur'':80 ''former'':186,201 ''generat'':28,30 ''god'':137,182 ''grave'':38 ''great'':116 ''hand'':12 ''heard'':3 ''hieroglyph'':79 ''histori'':167 ''idea'':169 ''illustr'':213 ''insculp'':41 ''interpos'':128,230 ''interposit'':193,202 ''known'':76 ''land'':152 ''latter'':95 ''make'':73 ''may'':174,219 ''mean'':35,53 ''method'':71 ''mode'':96 ''number'':55 ''old'':158 ''oral'':87 ''particular'':98 ''past'':179 ''power'':205 ''probabl'':92 ''proper'':36,175 ''reason'':225 ''recount'':59 ''refer'':99,133 ''render'':33 ''save'':207 ''sculptur'':82 ''seem'':91 ''show'':203 ''similar'':195 ''stone'':44 ''tell'':61 ''thenc'':46 ''thing'':75 ''thou'':110,119,126 ''though'':89 ''time'':156,161 ''told'':18,34 ''tradit'':88 ''tradition.our'':15 ''us'':19 ''word'':32,65 ''work'':109,117 ''would'':66 ''write'':48,84', NULL, '522');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('490', '2', '490', NULL, 'Help, Lord - Hebrew, "Save, Yahweh." The idea is that there was no human help, and, therefore, the divine help is implored. The psalmist saw that those on whom reliance was usually placed for the promotion of the cause of truth and virtue now failed, and hence, he invites the divine interposition.For the godly man - The word used here properly denotes the "merciful" man -   chasyd. It is a term applied to the righteous, because it is a prominent trait in the character of a pious man that he is merciful, kind, benignant. Hence, the general character is often denoted by the special characteristic; in the same way as we speak of a pious man as a good man, a just man, a righteous man. The idea suggested by the use of the term here is, that it is always a characteristic of a pious man that he is merciful or benignant. Compare Psalm 4:3; Psalm 32:6, where the same word is rendered "godly;" Psalm 30:4; Psalm 31:23; Psalm 37:28; Psalm 50:5; Psalm 52:9; Psalm 79:2; Psalm 85:8, where it is rendered saints; and Deuteronomy 33:8; Psalm 16:10; Psalm 86:2; Psalm 89:19, where it is rendered "holy." "Ceaseth." The word used here -   gamar - means properly to bring to an end; to complete; to perfect. Hence, it means to come to an end, to cease, to fail.Gesenius. - This might occur either by their being cut off by death; or by their ceasing to exert their influence in favor of religion; that is, by a general prevalence of wickedness among those who professed to be the friends of God. The latter seems to be the meaning here, since, in the following verses, the psalmist proceeds to specify the manner in which they "fail;" not by death, but by speaking vanity, falsehood, and flattery. That is, their conduct was such that their influence failed, or was lost to the community. No reliance could be placed on them, and, therefore, the psalmist so earnestly calls on God for his interposition. The idea is, that when men professing religion become conformed to the world - when they live like other men - when they cease to exert an influence in favor of piety - when they fall into habits of sin, it is a time to call on God with special earnestness for his aid. Often such conduct on the part of the professed friends of religion makes such an appeal to God more proper than even the death of good men does, for, in the latter case, their influence is simply withdrawn; in the former, not only is this influence which they might exert lost to the church, but there is a positive bad influence to be counteracted. The fall of a professor of religion into sin is a greater loss to the church than his death would be.For the faithful - Those who profess faith; those who are bound by their vows to be faithful to God and to his cause. The word is equivalent to the believing, and is properly expressive of trust or faith in God.Fail from among the children of men - Fail, as above noted, by their misconduct; by being false to the trust committed to them.', NULL, NULL, '''10'':197 ''16'':196 ''19'':203 ''2'':182,200 ''23'':170 ''28'':173 ''3'':154 ''30'':166 ''31'':169 ''32'':156 ''33'':193 ''37'':172 ''4'':153,167 ''5'':176 ''50'':175 ''52'':178 ''6'':157 ''79'':181 ''8'':185,194 ''85'':184 ''86'':199 ''89'':202 ''9'':179 ''aid'':398 ''alway'':138 ''among'':269,524 ''appeal'':414 ''appli'':69 ''bad'':458 ''be.for'':483 ''becom'':356 ''believ'':512 ''benign'':91,150 ''bound'':493 ''bring'':218 ''call'':342,390 ''case'':431 ''caus'':38,505 ''ceas'':235,252,369 ''ceaseth'':209 ''charact'':81,95 ''characterist'':102,140 ''chasyd'':64 ''children'':526 ''church'':452,478 ''come'':230 ''commit'':542 ''communiti'':328 ''compar'':151 ''complet'':223 ''conduct'':316,401 ''conform'':357 ''could'':331 ''counteract'':462 ''cut'':245 ''death'':248,305,422,481 ''denot'':60,98 ''deuteronomi'':192 ''divin'':18,50 ''earnest'':341,395 ''either'':241 ''end'':221,233 ''equival'':509 ''even'':420 ''exert'':254,371,448 ''express'':516 ''fail'':44,302,322,529 ''fail.gesenius'':237 ''faith'':485,489,499,520 ''fall'':380,464 ''fals'':538 ''falsehood'':310 ''favor'':258,375 ''flatteri'':312 ''follow'':290 ''former'':439 ''friend'':276,408 ''gamar'':214 ''general'':94,265 ''god'':53,164,278,344,392,416,501 ''god.fail'':522 ''good'':116,424 ''greater'':474 ''habit'':382 ''hebrew'':3 ''help'':1,14,19 ''henc'':46,92,226 ''holi'':208 ''human'':13 ''idea'':7,125,349 ''implor'':21 ''influenc'':256,321,373,433,444,459 ''interposit'':347 ''interposition.for'':51 ''invit'':48 ''kind'':90 ''latter'':280,430 ''like'':364 ''live'':363 ''lord'':2 ''loss'':475 ''lost'':325,449 ''make'':411 ''man'':54,63,85,113,117,120,123,144 ''manner'':298 ''mean'':215,228,285 ''men'':353,366,425,528 ''merci'':62,89,148 ''might'':239,447 ''misconduct'':535 ''note'':532 ''occur'':240 ''often'':97,399 ''part'':404 ''perfect'':225 ''pieti'':377 ''pious'':84,112,143 ''place'':32,333 ''posit'':457 ''preval'':266 ''proceed'':294 ''profess'':272,354,407,488 ''professor'':467 ''promin'':77 ''promot'':35 ''proper'':59,216,418,515 ''psalm'':152,155,165,168,171,174,177,180,183,195,198,201 ''psalmist'':23,293,339 ''relianc'':29,330 ''religion'':260,355,410,469 ''render'':163,189,207 ''righteous'':72,122 ''saint'':190 ''save'':4 ''saw'':24 ''seem'':281 ''simpli'':435 ''sin'':384,471 ''sinc'':287 ''speak'':109,308 ''special'':101,394 ''specifi'':296 ''suggest'':126 ''term'':68,132 ''therefor'':16,337 ''time'':388 ''trait'':78 ''trust'':518,541 ''truth'':40 ''use'':57,129,212 ''usual'':31 ''vaniti'':309 ''vers'':291 ''virtu'':42 ''vow'':496 ''way'':106 ''wicked'':268 ''withdrawn'':436 ''word'':56,161,211,507 ''world'':360 ''would'':482 ''yahweh'':5', NULL, '490');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('636', '2', '636', NULL, 'A companion picture to that in Proverbs 7, and serving in some measure to generalize and idealize it. Wisdom also calls Proverbs 8:5 to the "simple" and the "fools," and they have to choose between her voice and that of the temptress.', NULL, NULL, '''5'':24 ''7'':8 ''8'':23 ''also'':20 ''call'':21 ''choos'':35 ''companion'':2 ''fool'':30 ''general'':15 ''ideal'':17 ''measur'':13 ''pictur'':3 ''proverb'':7,22 ''serv'':10 ''simpl'':27 ''temptress'':43 ''voic'':38 ''wisdom'':19', NULL, '636');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('637', '2', '637', NULL, 'A parable full of beauty, and interesting in its parallelism to the parables of our Lord Matthew 22:3-4; Luke 14:16.Seven pillars - The number is chosen as indicating completeness and perfection. God revealing Himself in nature, resting in His work, entering into covenant with human beings - these were the ideas conveyed by it.', NULL, NULL, '''-4'':20 ''14'':22 ''16.seven'':23 ''22'':18 ''3'':19 ''be'':48 ''beauti'':5 ''chosen'':28 ''complet'':31 ''convey'':53 ''coven'':45 ''enter'':43 ''full'':3 ''god'':34 ''human'':47 ''idea'':52 ''indic'':30 ''interest'':7 ''lord'':16 ''luke'':21 ''matthew'':17 ''natur'':38 ''number'':26 ''parabl'':2,13 ''parallel'':10 ''perfect'':33 ''pillar'':24 ''rest'':39 ''reveal'':35 ''work'':42', NULL, '637');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('51', '2', '51', NULL, 'Now - Literally, "And," indicating a close connection with the preceding narrative. In fact this chapter contains a fulfillment of the predictions recorded in Genesis 46:3 and in Genesis 15:13.Every man and his household - It may be inferred from various notices that the total number of dependents was considerable, a point of importance in its bearings upon the history of the Exodus (compare Genesis 13:6; Genesis 14:14).', NULL, NULL, '''13'':66 ''13.every'':31 ''14'':69,70 ''15'':30 ''3'':26 ''46'':25 ''6'':67 ''bear'':57 ''chapter'':15 ''close'':6 ''compar'':64 ''connect'':7 ''consider'':50 ''contain'':16 ''depend'':48 ''exodus'':63 ''fact'':13 ''fulfil'':18 ''genesi'':24,29,65,68 ''histori'':60 ''household'':35 ''import'':54 ''indic'':4 ''infer'':39 ''liter'':2 ''man'':32 ''may'':37 ''narrat'':11 ''notic'':42 ''number'':46 ''point'':52 ''preced'':10 ''predict'':21 ''record'':22 ''total'':45 ''upon'':58 ''various'':41', NULL, '51');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('638', '2', '638', NULL, 'Righteousness - Including, perhaps, the idea of benevolence. Compare the use of &#x3b4;&#x3b9;&#x3ba;&#x3b1;&#x3b9;&#x3bf;&#x3c3;&#x3c5;&#x3bd;&#x3b7;  dikaiosune, in Matthew 6:1 (the older reading), and 2 Corinthians 9:9-10.', NULL, NULL, '''-10'':25 ''1'':16 ''2'':21 ''6'':15 ''9'':23,24 ''benevol'':7 ''compar'':8 ''corinthian'':22 ''dikaiosun'':12 ''idea'':5 ''includ'':2 ''matthew'':14 ''older'':18 ''perhap'':3 ''read'':19 ''righteous'':1 ''use'':10', NULL, '638');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('491', '2', '491', NULL, 'How long wilt thou forget me, O Lord? - literally, "until when." The psalmist breaks out into this cry "in the midst" of his troubles. He had apparently borne them as long as he could. It seemed as if they would never come to an end. We may presume that he had been patient and uncomplaining; that he had borne his trials long with the hope and belief that they would soon terminate; that he had waited patiently for deliverance, uttering no words of complaint; but now he begins to despair. He feels that his troubles will never end. He sees no prospect of deliverance; no signs or tokens that God would interpose; and he breaks out, therefore, in this language of tender complaint, as if he was utterly forsaken, and would be forever. The mind, even of a good man, is not unfrequently in this condition. He is borne down with troubles. He has no disposition to murmur or complain. He bears all patiently and long. He hopes for relief. He looks for it. But relief does not come; and it seems now that his troubles never will terminate. The darkness deepens; his mind is overwhelmed; he goes to God, and asks - not with complaining or murmuring, but with feelings bordering on despair - whether these troubles never will cease; whether he may never hope for deliverance.Forever? - He had been forgotten so long, and there appeared to be so little prospect of deliverance, that it seemed as if God never would return and visit him with mercy. The expression denotes a state of mind on the verge of despair.How long - Referring to a second aspect or phase of his troubles. The first was, that he seemed to be "forgotten." The second referred to here is, that God seemed to hide his face from him, and he asked how long this was to continue.Wilt thou hide thy face from me - Favour - friendship - is shown by turning the face benignantly toward one; by smiling upon him; in Scriptural language, by "lifting up the light of the countenance" upon one. See the note at Psalm 4:6. Aversion, hatred, displeasure, are shown by turning away the countenance. God seemed to the psalmist thus to show marks of displeasure toward him, and he earnestly asks how long this was to continue.', NULL, NULL, '''4'':352 ''6'':353 ''appar'':27 ''appear'':235 ''ask'':202,306,380 ''aspect'':274 ''avers'':354 ''away'':361 ''bear'':162 ''begin'':88 ''belief'':67 ''benign'':327 ''border'':211 ''born'':28,59,149 ''break'':14,115 ''ceas'':219 ''come'':42,179 ''complain'':160,205 ''complaint'':84,123 ''condit'':146 ''continu'':386 ''continue.wilt'':312 ''could'':34 ''counten'':344,363 ''cri'':18 ''dark'':191 ''deepen'':192 ''deliver'':79,104,242 ''deliverance.forever'':226 ''denot'':259 ''despair'':90,213 ''despair.how'':268 ''displeasur'':356,374 ''disposit'':156 ''earnest'':379 ''end'':45,98 ''even'':136 ''express'':258 ''face'':301,316,326 ''favour'':319 ''feel'':92,210 ''first'':281 ''forev'':133 ''forget'':5 ''forgotten'':230,288 ''forsaken'':129 ''friendship'':320 ''god'':110,200,248,296,364 ''goe'':198 ''good'':139 ''hatr'':355 ''hide'':299,314 ''hope'':65,168,224 ''interpos'':112 ''languag'':120,336 ''lift'':338 ''light'':341 ''liter'':9 ''littl'':239 ''long'':2,31,62,166,232,269,308,382 ''look'':172 ''lord'':8 ''man'':140 ''mark'':372 ''may'':47,222 ''merci'':256 ''midst'':21 ''mind'':135,194,263 ''murmur'':158,207 ''never'':41,97,187,217,223,249 ''note'':349 ''o'':7 ''one'':329,346 ''overwhelm'':196 ''patient'':53,77,164 ''phase'':276 ''presum'':48 ''prospect'':102,240 ''psalm'':351 ''psalmist'':13,368 ''refer'':270,291 ''relief'':170,176 ''return'':251 ''scriptur'':335 ''second'':273,290 ''see'':100,347 ''seem'':36,182,245,285,297,365 ''show'':371 ''shown'':322,358 ''sign'':106 ''smile'':331 ''soon'':71 ''state'':261 ''tender'':122 ''termin'':72,189 ''therefor'':117 ''thi'':315 ''thou'':4,313 ''thus'':369 ''token'':108 ''toward'':328,375 ''trial'':61 ''troubl'':24,95,152,186,216,279 ''turn'':324,360 ''uncomplain'':55 ''unfrequ'':143 ''upon'':332,345 ''utter'':80,128 ''verg'':266 ''visit'':253 ''wait'':76 ''whether'':214,220 ''wilt'':3 ''word'':82 ''would'':40,70,111,131,250', NULL, '491');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('493', '2', '493', NULL, 'Lord, who shall abide in thy tabernacle? - Margin, "sojourn." The Hebrew word means properly to "sojourn;" that is, to abide in a place as a sojourner or stranger; not permanently, but only for a while. The idea in this place is taken from the word "tabernacle" or "tent," with which one naturally associates the thought of sojourning, rather than that of a permanent abode. Compare Hebrews 11:9. It should not be inferred, however, that it is meant here that the residence with God would be "temporary." The idea of permanency is fully expressed in the other member of the sentence, and the language here is only such as was customary in speaking of the righteous - language derived from the fact that in early times men dwelt in tents rather than in permanent habitations.Who shall dwell in thy holy hill? - Zion, regarded as the dwelling-place of God, and the type of heaven - the eternal abode of the Most High. See the note at Psalm 2:6. The question is equivalent to asking, who is qualified to dwell with God? who may properly be regarded as his friend? who has a title to his favor? who is truly pious? By us the same question would be put in another form, though implying the same thing: Who is qualified to become a member of the church; who has evidence of true conversion and real piety? who is he who is prepared for heaven?', NULL, NULL, '''11'':67 ''2'':167 ''6'':168 ''9'':68 ''abid'':4,20 ''abod'':64,157 ''anoth'':210 ''ask'':174 ''associ'':53 ''becom'':221 ''church'':226 ''compar'':65 ''convers'':232 ''customari'':111 ''deriv'':118 ''dwell'':136,146,179 ''dwelling-plac'':145 ''dwelt'':127 ''earli'':124 ''equival'':172 ''etern'':156 ''evid'':229 ''express'':94 ''fact'':121 ''favor'':196 ''form'':211 ''friend'':189 ''fulli'':93 ''god'':84,149,181 ''habitations.who'':134 ''heaven'':154,243 ''hebrew'':11,66 ''high'':161 ''hill'':140 ''holi'':139 ''howev'':74 ''idea'':37,89 ''impli'':213 ''infer'':73 ''languag'':104,117 ''lord'':1 ''margin'':8 ''may'':183 ''mean'':13 ''meant'':78 ''member'':98,223 ''men'':126 ''natur'':52 ''note'':164 ''one'':51 ''perman'':30,63,91,133 ''pieti'':235 ''pious'':200 ''place'':23,40,147 ''prepar'':241 ''proper'':14,184 ''psalm'':166 ''put'':208 ''qualifi'':177,219 ''question'':170,205 ''rather'':58,130 ''real'':234 ''regard'':142,186 ''resid'':82 ''righteous'':116 ''see'':162 ''sentenc'':101 ''shall'':3,135 ''sojourn'':9,16,26,57 ''speak'':113 ''stranger'':28 ''tabernacl'':7,46 ''taken'':42 ''temporari'':87 ''tent'':48,129 ''thi'':6,138 ''thing'':216 ''though'':212 ''thought'':55 ''time'':125 ''titl'':193 ''true'':231 ''truli'':199 ''type'':152 ''us'':202 ''word'':12,45 ''would'':85,206 ''zion'':141', NULL, '493');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('494', '2', '494', NULL, 'Preserve me, O God - Keep me; guard me; save me. This language implies that there was imminent danger of some kind - perhaps, as the subsequent part of the psalm would seem to indicate, danger of death. See Psalm 16:8-10. The idea here is, that God was able to preserve him from the impending danger, and that he might hope he would do it.For in thee do I put my trust - That is, my hope is in thee. He had no other reliance than God; but he had confidence in him - he felt assured that there was safety there.', NULL, NULL, '''-10'':41 ''16'':39 ''8'':40 ''abl'':49 ''assur'':95 ''confid'':90 ''danger'':18,34,56 ''death'':36 ''felt'':94 ''god'':4,47,86 ''guard'':7 ''hope'':61,76 ''idea'':43 ''immin'':17 ''impend'':55 ''impli'':13 ''indic'':33 ''it.for'':65 ''keep'':5 ''kind'':21 ''languag'':12 ''might'':60 ''o'':3 ''part'':26 ''perhap'':22 ''preserv'':1,51 ''psalm'':29,38 ''put'':70 ''relianc'':84 ''safeti'':99 ''save'':9 ''see'':37 ''seem'':31 ''subsequ'':25 ''thee'':67,79 ''trust'':72 ''would'':30,63', NULL, '494');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('495', '2', '495', NULL, 'Hear the right - Margin, as in Hebrew, "justice." The prayer is, that God would regard that which was "right" in the case, or that he would vindicate the psalmist from that which was wrong. It is the expression of his confident assurance even in the presence of God that his cause was right, and that he was asking only that which it would be consistent for a "just" God to do. We can offer an acceptable prayer only when we are sure that it would be right for God to answer it, or that it would be consistent with perfect and eternal justice to grant our requests. It is to be observed here, however, that the ground of the petition of the psalmist is not that "he" was righteous, that is, he did not base his petition on the ground of his own merits, but that his "cause" was righteous; that he was unjustly oppressed and persecuted by his enemies. We cannot ask God to interpose in our behalf because we have a claim to his favor on the ground of our own merit; we may ask him to interpose because wrong is done, and his glory will be promoted in securing that which is just and right.Attend unto my cry - The word used here -   rinnah - means either a shout of joy, Psalm 30:5; Psalm 42:4; Psalm 47:1; or a mournful cry, outcry, wailing, Psalm 61:1; et soepe. It is expressive, in either case, of deep feeling which vents itself in an audible manner. Here it denotes the earnest "utterance" of prayer.Give ear unto my prayer - See the notes at Psalm 5:1.That goeth not out of feigned lips - Margin, as in Hebrew, "without lips of deceit." That is, that is sincere, or that proceeds from the heart. The utterance of the lips does not misrepresent the feelings of the heart. True prayer is that in which the lips "do" represent the real feelings of the soul. In hypocritical prayer the one is no proper representation of the other. It is evident that the prayer here was not mere mental prayer, or a mere desire of the heart. It was uttered prayer, or oral prayer; and, though private, it was in the form of uttered words. The feeling was so great that it was expressed in an audible cry to God. Deep emotion usually finds vent in such audible and fervent expressions. Compare the Saviour''s earnest prayer in the garden of Gethsemane, Luke 22:41 ff.', NULL, NULL, '''1'':231,240 ''1.that'':277 ''22'':419 ''30'':224 ''4'':228 ''41'':420 ''42'':227 ''47'':230 ''5'':225,276 ''61'':239 ''accept'':76 ''answer'':91 ''ask'':58,163,187 ''assur'':42 ''audibl'':257,392,403 ''base'':135 ''behalf'':169 ''cannot'':162 ''case'':22,248 ''caus'':51,148 ''claim'':174 ''compar'':407 ''confid'':41 ''consist'':65,98 ''cri'':211,235,393 ''deceit'':291 ''deep'':250,396 ''denot'':261 ''desir'':359 ''done'':194 ''ear'':267 ''earnest'':263,411 ''either'':218,247 ''emot'':397 ''enemi'':160 ''et'':241 ''etern'':102 ''even'':43 ''evid'':346 ''express'':38,245,389,406 ''favor'':177 ''feel'':251,312,328,382 ''feign'':282 ''fervent'':405 ''ff'':421 ''find'':399 ''form'':377 ''garden'':415 ''gethseman'':417 ''glori'':197 ''god'':13,48,69,89,164,395 ''goeth'':278 ''grant'':105 ''great'':385 ''ground'':117,140,180 ''hear'':1 ''heart'':302,315,362 ''hebrew'':7,287 ''howev'':114 ''hypocrit'':333 ''interpos'':166,190 ''joy'':222 ''justic'':8,103 ''lip'':283,289,307,323 ''luke'':418 ''manner'':258 ''margin'':4,284 ''may'':186 ''mean'':217 ''mental'':354 ''mere'':353,358 ''merit'':144,184 ''misrepres'':310 ''mourn'':234 ''note'':273 ''observ'':112 ''offer'':74 ''one'':336 ''oppress'':155 ''oral'':368 ''outcri'':236 ''perfect'':100 ''persecut'':157 ''petit'':120,137 ''prayer'':10,77,270,317,334,349,355,366,369,412 ''prayer.give'':266 ''presenc'':46 ''privat'':372 ''proceed'':299 ''promot'':200 ''proper'':339 ''psalm'':223,226,229,238,275 ''psalmist'':29,123 ''real'':327 ''regard'':15 ''repres'':325 ''represent'':340 ''request'':107 ''right'':3,19,53,87 ''right.attend'':208 ''righteous'':129,150 ''rinnah'':216 ''saviour'':409 ''secur'':202 ''see'':271 ''shout'':220 ''sincer'':296 ''soep'':242 ''soul'':331 ''sure'':82 ''though'':371 ''true'':316 ''unjust'':154 ''unto'':209,268 ''use'':214 ''usual'':398 ''utter'':264,304,365,379 ''vent'':253,400 ''vindic'':27 ''wail'':237 ''without'':288 ''word'':213,380 ''would'':14,26,63,85,96 ''wrong'':34,192', NULL, '495');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('523', '2', '523', NULL, 'My heart is inditing - That is, I am engaged in inditing a good matter; though implying at the same time that it was a work of the heart - a work in which the heart was engaged. It was not a mere production of the intellect; not a mere work of skill; not a mere display of the beauty of song, but a work in which the affections particularly were engaged, and which would express the feelings of the heart: the result or effusion of sincere love. The word rendered is "inditing" -   rachash - is rendered in the margin, boileth or bubbleth up. It means properly to boil up or over, as a fountain; and the idea here is that his heart boiled over with emotions of love; it was full and overflowing; it found expression in the words of this song. The Hebrew word does not occur elsewhere in the Bible.A good matter - literally, a good word; that is, it was something which he was about to say which was good; something interesting, pure, important; not only a subject on which his heart was engaged, but also which was worthy of attention.I speak of the things which I have made - literally, "I say my works to the king." That is, My work - that which I meditate and am about to compose - pertains to the king.Touching the king - He is to be the main subject of my song. Compare the notes at Isaiah 5:1. If the remarks made in the introduction to the psalm are correct, then the "king" here referred to was the future Messiah - the great personage to whom all the writers of the Old Testament looked forward, and whose glory they were so anxious to see and to describe. Compare the notes at 1 Peter 1:10-12.My tongue is the pen of a ready writer - Let my tongue in speaking of him be as the pen of a rapid writer. That is, let my tongue rapidly and freely express my thoughts and feelings. The word rendered "pen" -   et - means a stylus, usually made of iron, used for the purpose of inscribing letters on lead or wax. See the notes at Job 19:24. The idea is that the psalmist''s mind was full of his subject, and that he desired to express his thoughts in warm, free, gushing language - the language of overflowing emotion.', NULL, NULL, '''1'':243,296,298 ''10-12.my'':299 ''19'':364 ''24'':365 ''5'':242 ''affect'':67 ''also'':186 ''anxious'':286 ''attention.i'':191 ''beauti'':58 ''bible.a'':150 ''boil'':106,121 ''boileth'':98 ''bubbleth'':100 ''compar'':237,292 ''compos'':220 ''correct'':255 ''describ'':291 ''desir'':382 ''display'':55 ''effus'':83 ''elsewher'':147 ''emot'':124,396 ''engag'':9,36,70,184 ''et'':340 ''express'':74,134,331,384 ''feel'':76,335 ''forward'':279 ''found'':133 ''fountain'':112 ''free'':389 ''freeli'':330 ''full'':129,375 ''futur'':264 ''glori'':282 ''good'':13,151,155,170 ''great'':267 ''gush'':390 ''heart'':2,28,34,79,120,182 ''hebrew'':142 ''idea'':115,367 ''impli'':16 ''import'':174 ''indit'':4,11,91 ''inscrib'':353 ''intellect'':45 ''interest'':172 ''introduct'':250 ''iron'':347 ''isaiah'':241 ''job'':363 ''king'':207,226,258 ''king.touching'':224 ''languag'':391,393 ''lead'':356 ''let'':308,325 ''letter'':354 ''liter'':153,200 ''look'':278 ''love'':86,126 ''made'':199,247,345 ''main'':232 ''margin'':97 ''matter'':14,152 ''mean'':103,341 ''medit'':215 ''mere'':41,48,54 ''messiah'':265 ''mind'':373 ''note'':239,294,361 ''occur'':146 ''old'':276 ''overflow'':131,395 ''particular'':68 ''pen'':303,318,339 ''personag'':268 ''pertain'':221 ''peter'':297 ''product'':42 ''proper'':104 ''psalm'':253 ''psalmist'':371 ''pure'':173 ''purpos'':351 ''rachash'':92 ''rapid'':321,328 ''readi'':306 ''refer'':260 ''remark'':246 ''render'':89,94,338 ''result'':81 ''say'':167,202 ''see'':288,359 ''sincer'':85 ''skill'':51 ''someth'':161,171 ''song'':60,140,236 ''speak'':192,312 ''stylus'':343 ''subject'':178,233,378 ''testament'':277 ''thing'':195 ''though'':15 ''thought'':333,386 ''time'':20 ''to