INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('524', '2', '524', NULL, 'God is our refuge and strength - God is for us as a place to which we may flee for safety; a source of strength to us in danger. The first word, "refuge," from a verb meaning to "flee," and then "to flee to" -   chasah - or to take shelter in - denotes a place to which one would flee in time of danger - as a lofty wall; a high tower; a fort; a fortress. See the notes at Psalm 18:2. The idea here is, that the people of God, in time of danger, may find him to be what such a place of refuge would be. Compare Proverbs 18:10. The word "strength" implies that God is the source of strength to those who are weak and defenseless; or that we may rely on his strength "as if" it were our own; or that we may feel as safe in his strength as though we had that strength ourselves. We may make it the basis of our confidence as really as though the strength resided in our own arm. See the notes at Psalm 18:2.A very present help - The word "help" here means aid, assistance. The word "trouble" would cover all that can come upon us which would give us anxiety or sorrow. The word rendered "present" -   nimetsa'' - means rather, "is found," or "has been found;" that is, he has "proved" himself to be a help in trouble. The word "present," as if he were near to us, or close by us, does not accurately express the idea, which is rather, that "he has been found" to be such, or that he has always "proved" himself to be such a help, and that, therefore, we may now confide in him. The word "very," or "exceedingly," is added to qualify the whole proposition, as if this were "emphatically true." It was true in the most eminent sense that God had always been found to be such a helper, and, "therefore," there was nothing to fear in the present distress. Psalm 46:2.', NULL, NULL, '''10'':109 ''18'':78,108,184 ''2'':79,185,342 ''46'':341 ''accur'':256 ''add'':298 ''aid'':195 ''alway'':275,321 ''anxieti'':212 ''arm'':178 ''assist'':196 ''basi'':164 ''chasah'':44 ''close'':251 ''come'':205 ''compar'':106 ''confid'':167,289 ''cover'':201 ''danger'':28,61,92 ''defenseless'':127 ''denot'':50 ''distress'':339 ''emin'':316 ''emphat'':308 ''exceed'':296 ''express'':257 ''fear'':335 ''feel'':146 ''find'':94 ''first'':30 ''flee'':18,38,42,57 ''fort'':70 ''fortress'':72 ''found'':223,227,267,323 ''give'':210 ''god'':1,7,88,115,319 ''help'':189,192,237,282 ''helper'':328 ''high'':67 ''idea'':81,259 ''impli'':113 ''lofti'':64 ''make'':161 ''may'':17,93,131,145,160,287 ''mean'':36,194,220 ''near'':247 ''nimetsa'':219 ''note'':75,181 ''noth'':333 ''one'':55 ''peopl'':86 ''place'':13,52,101 ''present'':188,218,242,338 ''proposit'':303 ''prove'':232,276 ''proverb'':107 ''psalm'':77,183,340 ''qualifi'':300 ''rather'':221,262 ''realli'':169 ''refug'':4,32,103 ''reli'':132 ''render'':217 ''resid'':174 ''safe'':148 ''safeti'':20 ''see'':73,179 ''sens'':317 ''shelter'':48 ''sorrow'':214 ''sourc'':22,118 ''strength'':6,24,112,120,135,151,157,173 ''take'':47 ''therefor'':285,330 ''though'':153,171 ''time'':59,90 ''tower'':68 ''troubl'':199,239 ''true'':309,312 ''upon'':206 ''us'':10,26,207,211,249,253 ''verb'':35 ''wall'':65 ''weak'':125 ''whole'':302 ''word'':31,111,191,198,216,241,293 ''would'':56,104,200,209', NULL, '524');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('496', '2', '496', NULL, 'I will love thee, O Lord - This verse is not found in the song in 2 Samuel 22. It appears to have been added after the first composition of the psalm, either by David as expressive of his ardent love for the Lord in view of his merciful interpositions in his behalf, and on the most careful and most mature review of those mercies, or by the collector of the Psalms when they were adapted to purposes of public worship, as a proper commencement of the psalm - expressive of the feeling which the general tenor of the psalm was fitted to inspire. It is impossible now to determine by whom it was added; but no one can doubt that it is a proper commencement of a psalm that is designed to recount so many mercies. It is the feeling which all should have when they recall the goodness of God to them in their past lives.My strength - The source of my strength, or from whom all my strength is derived. So Psalm 27:1, "The Lord is the strength of my life." Psalm 28:8, "he is the saving strength of his anointed." Compare Psalm 29:11; Psalm 46:1; Psalm 73:26; Psalm 81:1; Psalm 140:7.', NULL, NULL, '''1'':174,200,206 ''11'':197 ''140'':208 ''2'':16 ''22'':18 ''26'':203 ''27'':173 ''28'':184 ''29'':196 ''46'':199 ''7'':209 ''73'':202 ''8'':185 ''81'':205 ''adapt'':75 ''add'':24,113 ''anoint'':193 ''appear'':20 ''ardent'':39 ''behalf'':52 ''care'':57 ''collector'':68 ''commenc'':84,124 ''compar'':194 ''composit'':28 ''david'':34 ''deriv'':170 ''design'':130 ''determin'':108 ''doubt'':118 ''either'':32 ''express'':36,88 ''feel'':91,139 ''first'':27 ''fit'':100 ''found'':11 ''general'':94 ''god'':150 ''good'':148 ''imposs'':105 ''inspir'':102 ''interposit'':49 ''life'':182 ''lives.my'':156 ''lord'':6,43,176 ''love'':3,40 ''mani'':134 ''matur'':60 ''merci'':48,64,135 ''o'':5 ''one'':116 ''past'':155 ''proper'':83,123 ''psalm'':31,71,87,98,127,172,183,195,198,201,204,207 ''public'':79 ''purpos'':77 ''recal'':146 ''recount'':132 ''review'':61 ''samuel'':17 ''save'':189 ''song'':14 ''sourc'':159 ''strength'':157,162,168,179,190 ''tenor'':95 ''thee'':4 ''vers'':8 ''view'':45 ''worship'':80', NULL, '496');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('884', '2', '884', NULL, 'In order to impress Israel the more, Amos begins this his third appeal by a "dirge" over its destruction, mourning over those who were full of joy, and thought themselves safe and enviable. As if a living man, in the midst of his pride and luxury and buoyant recklessness of heart, could see his own funeral procession, and hear, as it were, over himself the "earth to earth, ashes to ashes, dust to dust." It would give solemn thoughts, even though he should impatiently put them from him. So must it to Israel, when after the tide of victories of Jeroboam II, Amos said, "Hear this word which I am lifting up," as a heavy weight, to cast it down "against" or "upon you," a funeral "dirge," O house of Israel. Human greatness is so unstable, human strength so fleeting, that the prophet of decay finds a response in man''s own conscience, however he may silence or resent it. He would not resent it, unless he felt its force.Dionysius: "Amos, an Israelite, mourneth over Israel, as Samuel did over Saul 1 Samuel 15:35, or as Isaiah says, "I will weep bitterly; labor not to comfort me, because of the spoiling of the daughter of my people" Isaiah 22:4; images of Him who wept over Jerusalem." "So are they bewailed, who know not why they are bewailed, the more miserable, because they know not their own misery."', NULL, NULL, '''1'':182 ''15'':184 ''22'':210 ''35'':185 ''4'':211 ''amo'':8,103,171 ''appeal'':13 ''ash'':69,71 ''begin'':9 ''bewail'':222,229 ''bitter'':193 ''buoyant'':48 ''cast'':118 ''comfort'':197 ''conscienc'':153 ''could'':52 ''daughter'':205 ''decay'':145 ''destruct'':19 ''dirg'':16,127 ''dust'':72,74 ''earth'':66,68 ''enviabl'':33 ''even'':80 ''felt'':168 ''find'':146 ''fleet'':140 ''force.dionysius'':170 ''full'':25 ''funer'':56,126 ''give'':77 ''great'':133 ''hear'':59,105 ''heart'':51 ''heavi'':115 ''hous'':129 ''howev'':154 ''human'':132,137 ''ii'':102 ''imag'':212 ''impati'':84 ''impress'':4 ''isaiah'':188,209 ''israel'':5,93,131,176 ''israelit'':173 ''jeroboam'':101 ''jerusalem'':218 ''joy'':27 ''know'':224,235 ''labor'':194 ''lift'':111 ''live'':37 ''luxuri'':46 ''man'':38,150 ''may'':156 ''midst'':41 ''miser'':232 ''miseri'':239 ''mourn'':20 ''mourneth'':174 ''must'':90 ''o'':128 ''order'':2 ''peopl'':208 ''pride'':44 ''process'':57 ''prophet'':143 ''put'':85 ''reckless'':49 ''resent'':159,164 ''respons'':148 ''safe'':31 ''said'':104 ''samuel'':178,183 ''saul'':181 ''say'':189 ''see'':53 ''silenc'':157 ''solemn'':78 ''spoil'':202 ''strength'':138 ''third'':12 ''though'':81 ''thought'':29,79 ''tide'':97 ''unless'':166 ''unstabl'':136 ''upon'':123 ''victori'':99 ''weep'':192 ''weight'':116 ''wept'':216 ''word'':107 ''would'':76,162', NULL, '884');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('885', '2', '885', NULL, 'Woe to them that are at ease - The word always means such as are recklessly at their ease, "the careless ones," such as those whom Isaiah bids Isaiah 32:9-11, "rise up, tremble, be troubled, for many days and years shall ye be troubled." It is that luxury and ease, which sensualize the soul, and make it dull, stupid, hard-hearted. By one earnest, passing word, the prophet warns his own land, that present sinful ease ends in future woe. "Woe unto them that laugh now: for they shall mourn and weep" Luke 6:25. Rup.: "He foretells the destruction and captivity of both Judah and Israel at once; and not only that captivity at Babylon, but that whereby they are dispersed unto this day." Luxury and deepest sins of the flesh were rife in that generation (see John 8:9; Romans 2:21-24; Luke 11:39, Luke 11:42; Matthew 23:14, Matthew 23:23, Matthew 23:26), which killed Him who for our sakes became poor.And trust in the mountain of Samaria - Not in God. Samaria was strong (see the note above at Amos 3:9), resisted for three years, and was the last city of Israel which was taken. "The king of Assyria came up throughout all the land and went up to Samaria, and besieged it 2 Kings 17:5. Benhadad, in that former siege, when God delivered them 2 Kings 7:6, attempted no assault, but famine only.Which are named the chief of the nations - Literally, "the named of the chief of the nations," that is, those who, in Israel, which by the distinguishing favor of God were "chief of the nations," were themselves, marked, distinguished, "named." The prophet, by one word, refers them back to those first princes of the congregation, of whom Moses used that same word Numbers 1:17. They were "heads of the houses of their fathers Numbers 1:4, renowned of the congregation, heads of thousands in Israel Numbers 1:16. As, if anyone were to call the Peers, "Barons of England," he would carry us back to the days of Magna Charta, although six centuries and a half ago, so this word, occurring at that time , here only in any Scripture since Moses, carried back the thoughts of the degenerate aristocracy of Israel to the faith and zeal of their forefathers, "what" they ought to have been, and "what" they were. As Amalek of old was "first of the nations" Numbers 24:20 in its enmity against the people of God , having, first of all, shown that implacable hatred, which Ammon, Moab, Edom, evinced afterward, so was Israel "first of nations," as by God. It became, in an evil way, "first of nations," that is, distinguished above the heat by rejecting Him.To whom the house of Israel came, or have come - They were, like those princes of old, raised above others. Israel "came" to them for judgment; and they, regardless of duty, lived only for self-indulgence, effeminacy, and pride. Jerome renders in the same sense, "that enter pompously the house of Israel," literally, "enter for themselves," as if they were lords of it, and it was made for them.', NULL, NULL, '''-11'':31 ''-24'':147 ''1'':309,321,333 ''11'':149,152 ''14'':156 ''16'':334 ''17'':226,310 ''2'':145,224,237 ''20'':417 ''21'':146 ''23'':155,158,159,161 ''24'':416 ''25'':97 ''26'':162 ''3'':190 ''32'':29 ''39'':150 ''4'':322 ''42'':153 ''5'':227 ''6'':96,240 ''7'':239 ''8'':142 ''9'':30,143,191 ''afterward'':439 ''ago'':363 ''although'':357 ''alway'':10 ''amalek'':407 ''ammon'':435 ''amo'':189 ''anyon'':337 ''aristocraci'':385 ''assault'':243 ''assyria'':209 ''attempt'':241 ''babylon'':118 ''back'':293,350,379 ''baron'':343 ''becam'':170,450 ''benhadad'':228 ''besieg'':222 ''bid'':27 ''call'':340 ''came'':210,472,487 ''captiv'':104,116 ''careless'':20 ''carri'':348,378 ''centuri'':359 ''charta'':356 ''chief'':250,259,277 ''citi'':200 ''come'':475 ''congreg'':300,326 ''day'':39,127,353 ''deepest'':130 ''degener'':384 ''deliv'':235 ''destruct'':102 ''dispers'':124 '