INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('98', '2', '98', NULL, 'A bullock ... two rams ... a basket - compare Exodus 29:1-3. This shows the coherence of this part of Leviticus with the latter part of Exodus. The basket of unleavened bread used on this occasion appears to have contained:(1) cakes or loaves of the ordinary unleavened bread;(2) cakes of oiled bread, rather, oil bread (see Leviticus 2:1, Leviticus 2:4); and(3) oiled wafers (see Leviticus 2:4, Leviticus 2:6).Rabbinical tradition says that there were six cakes of each sort.', NULL, NULL, '''-3'':11 ''1'':10,40,60 ''2'':49,59,62,70,73 ''29'':9 ''3'':65 ''4'':63,71 ''6'':74 ''appear'':36 ''basket'':6,28 ''bread'':31,48,53,56 ''bullock'':2 ''cake'':41,50,82 ''coher'':15 ''compar'':7 ''contain'':39 ''exodus'':8,26 ''latter'':23 ''leviticus'':20,58,61,69,72 ''loav'':43 ''occas'':35 ''oil'':52,55,66 ''ordinari'':46 ''part'':18,24 ''rabbin'':75 ''ram'':4 ''rather'':54 ''say'':77 ''see'':57,68 ''show'':13 ''six'':81 ''sort'':85 ''tradit'':76 ''two'':3 ''unleaven'':30,47 ''use'':32 ''wafer'':67', NULL, '98');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('124', '2', '124', NULL, 'On the day that - i. e. "at the time that," compare Genesis 2:4. The presentation of the gifts in fact occupied twelve days, as the sequel shows.The enactments set forth in the chapters from Leviticus 10 to Numbers 6 inclusive, were doubtless promulgated at various times between the consecration of the tabernacle and the departure from Sinai, but are for convenience set out connectedly. The contents of the present chapter are accordingly placed after them. The order pursued throughout is justly noted as one which would naturally suggest itself to a narrator who was contemporary with the events.', NULL, NULL, '''10'':37 ''2'':13 ''4'':14 ''6'':40 ''accord'':73 ''chapter'':34,71 ''compar'':11 ''connect'':65 ''consecr'':50 ''contemporari'':96 ''content'':67 ''conveni'':62 ''day'':3,24 ''departur'':56 ''doubtless'':43 ''e'':6 ''enact'':29 ''event'':99 ''fact'':21 ''forth'':31 ''genesi'':12 ''gift'':19 ''inclus'':41 ''just'':82 ''leviticus'':36 ''narrat'':93 ''natur'':88 ''note'':83 ''number'':39 ''occupi'':22 ''one'':85 ''order'':78 ''place'':74 ''present'':16,70 ''promulg'':44 ''pursu'':79 ''sequel'':27 ''set'':30,63 ''shows.the'':28 ''sinai'':58 ''suggest'':89 ''tabernacl'':53 ''throughout'':80 ''time'':9,47 ''twelv'':23 ''various'':46 ''would'':87', NULL, '124');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('125', '2', '125', NULL, 'The actual lighting of the lamps (compare the marginal references) was to be done to set forth symbolically the special presence which God had now Numbers 7:89 actually established among His people.', NULL, NULL, '''7'':27 ''89'':28 ''actual'':2,29 ''among'':31 ''compar'':7 ''done'':14 ''establish'':30 ''forth'':17 ''god'':23 ''lamp'':6 ''light'':3 ''margin'':9 ''number'':26 ''peopl'':33 ''presenc'':21 ''refer'':10 ''set'':16 ''special'':20 ''symbol'':18', NULL, '125');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('126', '2', '126', NULL, 'Passover at Sinai. This, as being kept in the first month, was prior in time to the numbering of Numbers 1:1 ff, and to the other events narrated in this book. It is, however, recorded here as introductory to the ordinance of Numbers 9:6-14 in this chapter respecting the supplementary Passover; the observance of which was one of the last occurrences during the halt at Sinai.', NULL, NULL, '''-14'':47 ''1'':21,22 ''6'':46 ''9'':45 ''book'':32 ''chapter'':50 ''event'':28 ''ff'':23 ''first'':10 ''halt'':67 ''howev'':35 ''introductori'':39 ''kept'':7 ''last'':63 ''month'':11 ''narrat'':29 ''number'':18,20,44 ''observ'':56 ''occurr'':64 ''one'':60 ''ordin'':42 ''passov'':1,54 ''prior'':13 ''record'':36 ''respect'':51 ''sinai'':3,69 ''supplementari'':53 ''time'':15', NULL, '126');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('127', '2', '127', NULL, 'The trumpet was a straight instrument, differing in this respect from the curved horn or cornet; and is represented, among the other spoils of the temple, on the Arch of Titus. See Exodus 25:23 cut. From Egyptian monuments it appears that the Jewish trumpet was copied from that used in the armies of the Pharaohs. The cornet was at first a simple ram''s horn Joshua 6:4, and the metal instrument of later times preserved the original shape.', NULL, NULL, '''23'':35 ''25'':34 ''4'':69 ''6'':68 ''among'':20 ''appear'':41 ''arch'':29 ''armi'':53 ''copi'':47 ''cornet'':16,58 ''curv'':13 ''cut'':36 ''differ'':7 ''egyptian'':38 ''exodus'':33 ''first'':61 ''horn'':14,66 ''instrument'':6,73 ''jewish'':44 ''joshua'':67 ''later'':75 ''metal'':72 ''monument'':39 ''origin'':79 ''pharaoh'':56 ''preserv'':77 ''ram'':64 ''repres'':19 ''respect'':10 ''see'':32 ''shape'':80 ''simpl'':63 ''spoil'':23 ''straight'':5 ''templ'':26 ''time'':76 ''titus'':31 ''trumpet'':2,45 ''use'':50', NULL, '127');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('128', '2', '128', NULL, 'See the marginal rendering. They murmured against the privations of the march.The fire of the Lord - Probably lightning; compare Psalm 78:21.In the uttermost parts - Rather, in the end. The fire did not reach far into the camp. It was quickly quenched at the intercession of Moses.', NULL, NULL, '''21.in'':22 ''78'':21 ''camp'':38 ''compar'':19 ''end'':29 ''far'':35 ''fire'':13,31 ''intercess'':45 ''lightn'':18 ''lord'':16 ''march.the'':12 ''margin'':3 ''mose'':47 ''murmur'':6 ''part'':25 ''privat'':9 ''probabl'':17 ''psalm'':20 ''quench'':42 ''quick'':41 ''rather'':26 ''reach'':34 ''render'':4 ''see'':1 ''uttermost'':24', NULL, '128');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('99', '2', '99', NULL, 'It is to be remarked that Aaron offers no peace-offering for himself. It was enough that he should participate in the peace-offerings of the consecration Leviticus 8:31, and in the two peace-offerings about to be sacrificed for the people.His sin-offering was probably regarded not so much as a sacrifice for his own actual sins as a typical acknowledgment of his sinful nature and of his future duty to offer for his own sins and those of the People. See marginal references. "The law maketh men high priests which have infirmity; but the word of the oath, which was since the law, maketh the Son, who is consecrated (in the margin perfected, see Leviticus 8:22 note) forevermore, Hebrews 7:28.', NULL, NULL, '''22'':124 ''28'':129 ''31'':32 ''7'':128 ''8'':31,123 ''aaron'':7 ''acknowledg'':67 ''actual'':62 ''consecr'':29,116 ''duti'':76 ''enough'':17 ''forevermor'':126 ''futur'':75 ''hebrew'':127 ''high'':95 ''infirm'':99 ''law'':92,110 ''leviticus'':30,122 ''maketh'':93,111 ''margin'':89,119 ''men'':94 ''much'':55 ''natur'':71 ''note'':125 ''oath'':105 ''offer'':8,12,26,39,49,78 ''particip'':21 ''peac'':11,25,38 ''peace-off'':10,24,37 ''peopl'':87 ''people.his'':46 ''perfect'':120 ''priest'':96 ''probabl'':51 ''refer'':90 ''regard'':52 ''remark'':5 ''sacrif'':43 ''sacrific'':58 ''see'':88,121 ''sin'':48,63,70,82 ''sin-off'':47 ''sinc'':108 ''son'':113 ''two'':36 ''typic'':66 ''word'':102', NULL, '99');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('639', '2', '639', NULL, 'This emphatic reproduction of the old rule of Deuteronomy 25:13-14 is perhaps a trace of the danger of dishonesty incidental to the growing commerce of the Israelites. The stress laid upon the same sin in Proverbs 16:11; Proverbs 20:10; bears witness to the desire of the teacher to educate the youth of Israel to a high standard of integrity, just as the protest of Hosea against it Hosea 12:7 shows the zeal of the prophet in rebuking what was becoming more and more a besetting sin.A just weight - literally, as in the margin, indicating a time when stones rather than metal were used as a standard of weight. Compare Deuteronomy 25:13.', NULL, NULL, '''-14'':12 ''10'':43 ''11'':40 ''12'':73 ''13'':11,117 ''16'':39 ''20'':42 ''25'':10,116 ''7'':74 ''bear'':44 ''becom'':85 ''beset'':90 ''commerc'':26 ''compar'':114 ''danger'':19 ''desir'':48 ''deuteronomi'':9,115 ''dishonesti'':21 ''educ'':53 ''emphat'':2 ''grow'':25 ''high'':60 ''hosea'':69,72 ''incident'':22 ''indic'':99 ''integr'':63 ''israel'':57 ''israelit'':29 ''laid'':32 ''liter'':94 ''margin'':98 ''metal'':106 ''old'':6 ''perhap'':14 ''prophet'':80 ''protest'':67 ''proverb'':38,41 ''rather'':104 ''rebuk'':82 ''reproduct'':3 ''rule'':7 ''show'':75 ''sin'':36 ''sin.a'':91 ''standard'':61,111 ''stone'':103 ''stress'':31 ''teacher'':51 ''time'':101 ''trace'':16 ''upon'':33 ''use'':108 ''weight'':93,113 ''wit'':45 ''youth'':55 ''zeal'':77', NULL, '639');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('640', '2', '640', NULL, 'The thought which lies below the surface is that of the inseparable union between truth and justice. The end does not justify the means, and only he who breathes and utters truth makes the righteous cause clear.', NULL, NULL, '''breath'':29 ''caus'':36 ''clear'':37 ''end'':19 ''insepar'':12 ''justic'':17 ''justifi'':22 ''lie'':4 ''make'':33 ''mean'':24 ''righteous'':35 ''surfac'':7 ''thought'':2 ''truth'':15,32 ''union'':13 ''utter'':31', NULL, '640');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('641', '2', '641', NULL, 'Heareth - The verb of the second clause is inserted in the first, just as in the next verse that of the first is inserted in the second. Stress is laid upon the obstinacy of the scorner who refuses to hear, not only "instruction," but also the much stronger "rebuke."', NULL, NULL, '''also'':45 ''claus'':7 ''first'':12,22 ''hear'':40 ''heareth'':1 ''insert'':9,24 ''instruct'':43 ''laid'':30 ''much'':47 ''next'':17 ''obstinaci'':33 ''rebuk'':49 ''refus'':38 ''scorner'':36 ''second'':6,27 ''stress'':28 ''stronger'':48 ''upon'':31 ''verb'':3 ''vers'':18', NULL, '641');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('642', '2', '642', NULL, 'Every wise woman - literally, Wise women. The fullest recognition that has as yet met us of the importance of woman, for good or evil, in all human society.', NULL, NULL, '''everi'':1 ''evil'':24 ''fullest'':8 ''good'':22 ''human'':27 ''import'':18 ''liter'':4 ''met'':14 ''recognit'':9 ''societi'':28 ''us'':15 ''wise'':2,5 ''woman'':3,20 ''women'':6 ''yet'':13', NULL, '642');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('583', '2', '583', NULL, 'O give thanks unto the Lord - The design here is to show that thanks should be given to the Lord in view of his dealings with his people, as stated in the subsequent portions of the psalm.Call upon his name - More literally, "Call him by his name;" that is, Address him by his proper title; ascribe to him the attributes which properly belong to him; or, address him in a proper manner.Make known his deeds among the people - What he has done in former times. The allusion is to his acts in behalf of his people in delivering them from Egyptian bondage, and bringing them to the promised land. The word "people" here refers to the Hebrew people; and the exhortation is, that the knowledge of these deeds should be diffused and kept up among them. One of the ways of doing this was that proposed by the psalmist, to wit, by a psalm of praise - by recording and celebrating these acts in their devotions. One of the most effective modes of keeping up the knowledge of what God has done in our world is by songs of praise in worshipping assemblies.', NULL, NULL, '''act'':91,162 ''address'':50,67 ''allus'':87 ''among'':76,135 ''ascrib'':56 ''assembl'':192 ''attribut'':60 ''behalf'':93 ''belong'':63 ''bondag'':102 ''bring'':104 ''call'':43 ''celebr'':160 ''deal'':25 ''deed'':75,128 ''deliv'':98 ''design'':8 ''devot'':165 ''diffus'':131 ''done'':82,181 ''effect'':170 ''egyptian'':101 ''exhort'':121 ''former'':84 ''give'':2 ''given'':17 ''god'':179 ''hebrew'':117 ''keep'':173 ''kept'':133 ''knowledg'':125,176 ''known'':73 ''land'':109 ''liter'':42 ''lord'':6,20 ''manner.make'':72 ''mode'':171 ''name'':40,47 ''o'':1 ''one'':137,166 ''peopl'':28,78,96,112,118 ''portion'':34 ''prais'':156,189 ''promis'':108 ''proper'':54,62,71 ''propos'':146 ''psalm'':154 ''psalm.call'':37 ''psalmist'':149 ''record'':158 ''refer'':114 ''show'':12 ''song'':187 ''state'':30 ''subsequ'':33 ''thank'':3,14 ''time'':85 ''titl'':55 ''unto'':4 ''upon'':38 ''view'':22 ''way'':140 ''wit'':151 ''word'':111 ''world'':184 ''worship'':191', NULL, '583');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('584', '2', '584', NULL, 'They did not destroy the nations - The Canaanites, Hivites, Jebusites, etc.; the nations that inhabited the land of Canaan.Concerning whom the Lord commanded them - The command on this subject was positive; and it was to destroy them, to spare none of them. Numbers 33:52; Deuteronomy 7:5, Deuteronomy 7:16.', NULL, NULL, '''16'':51 ''33'':44 ''5'':48 ''52'':45 ''7'':47,50 ''canaan.concerning'':19 ''canaanit'':8 ''command'':23,26 ''destroy'':4,36 ''deuteronomi'':46,49 ''etc'':11 ''hivit'':9 ''inhabit'':15 ''jebusit'':10 ''land'':17 ''lord'':22 ''nation'':6,13 ''none'':40 ''number'':43 ''posit'':31 ''spare'':39 ''subject'':29', NULL, '584');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('643', '2', '643', NULL, 'Useth knowledge aright - Rather, makes knowledge goodly. The power of well-considered speech to commend true wisdom, is contrasted with the pouring (literally as in the margin) forth of folly.', NULL, NULL, '''aright'':3 ''commend'':16 ''consid'':13 ''contrast'':20 ''folli'':31 ''forth'':29 ''good'':7 ''knowledg'':2,6 ''liter'':24 ''make'':5 ''margin'':28 ''pour'':23 ''power'':9 ''rather'':4 ''speech'':14 ''true'':17 ''useth'':1 ''well'':12 ''well-consid'':11 ''wisdom'':18', NULL, '643');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('644', '2', '644', NULL, 'Good as it is to "handle a matter wisely," it is far better to "trust in the Lord." The former is really impossible except through the latter.', NULL, NULL, '''better'':13 ''except'':24 ''far'':12 ''former'':20 ''good'':1 ''handl'':6 ''imposs'':23 ''latter'':27 ''lord'':18 ''matter'':8 ''realli'':22 ''trust'':15 ''wise'':9', NULL, '644');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('645', '2', '645', NULL, 'The reciprocity of good in sustained family relationships. A long line of children''s children is the glory of old age, a long line of ancestors the glory of their descendants.', NULL, NULL, '''age'':21 ''ancestor'':26 ''children'':13,15 ''descend'':31 ''famili'':7 ''glori'':18,28 ''good'':4 ''line'':11,24 ''long'':10,23 ''old'':20 ''reciproc'':2 ''relationship'':8 ''sustain'':6', NULL, '645');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('585', '2', '585', NULL, 'They wandered in the wilderness - On their return from Babylon; or, when God was conducting them again to their own land. The word "wilderness" in the Scriptures means a desolate, barren, uninhabited region, usually destitute of trees, of springs, and of water-courses. It does not denote, as it does with us, a region of extensive "forests." Compare the notes at Matthew 4:1.In a solitary way - Rather, in a "waste" way; a land that was desolate and uncultivated.They found no city to dwell in - In their journeyings. This was true of the region between Babylon and Palestine; a wide, barren, desolate waste.', NULL, NULL, '''1.in'':65 ''4'':64 ''babylon'':10,97 ''barren'':31,102 ''citi'':83 ''compar'':59 ''conduct'':15 ''cours'':44 ''denot'':48 ''desol'':30,78,103 ''destitut'':35 ''dwell'':85 ''extens'':57 ''forest'':58 ''found'':81 ''god'':13 ''journey'':89 ''land'':21,75 ''matthew'':63 ''mean'':28 ''note'':61 ''palestin'':99 ''rather'':69 ''region'':33,55,95 ''return'':8 ''scriptur'':27 ''solitari'':67 ''spring'':39 ''tree'':37 ''true'':92 ''uncultivated.they'':80 ''uninhabit'':32 ''us'':53 ''usual'':34 ''wander'':2 ''wast'':72,104 ''water'':43 ''water-cours'':42 ''way'':68,73 ''wide'':101 ''wilder'':5,24 ''word'':23', NULL, '585');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('592', '2', '592', NULL, 'When Israel went out of Egypt - literally, "In the going out of Israel from Egypt." This is not to be confined to the exact act of the exodus, but embraces all that properly entered into that migration - the whole train of events which resuited in their being brought into the promised land.The house of Jacob - The family of Jacob - a name appropriately used here, since it was the family of Jacob that had gone down into Egypt, and that had increased to these great numbers.From a people of strange language - Speaking a foreign or a barbarian tongue. See the notes at Psalm 81:5.', NULL, NULL, '''5'':104 ''81'':103 ''act'':25 ''appropri'':62 ''barbarian'':96 ''brought'':48 ''confin'':21 ''egypt'':6,15,77 ''embrac'':30 ''enter'':34 ''event'':42 ''exact'':24 ''exodus'':28 ''famili'':57,69 ''foreign'':93 ''go'':10 ''gone'':74 ''great'':84 ''hous'':53 ''increas'':81 ''israel'':2,13 ''jacob'':55,59,71 ''land.the'':52 ''languag'':90 ''liter'':7 ''migrat'':37 ''name'':61 ''note'':100 ''numbers.from'':85 ''peopl'':87 ''promis'':51 ''proper'':33 ''psalm'':102 ''resuit'':44 ''see'':98 ''sinc'':65 ''speak'':91 ''strang'':89 ''tongu'':97 ''train'':40 ''use'':63 ''went'':3 ''whole'':39', NULL, '592');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('100', '2', '100', NULL, 'Nadab and Abihu - The two elder sons of Aaron Exodus 6:23; Numbers 3:2, who were among those invited to accompany Moses when he was going up Mount Sinai, but who were "to worship afar off," and not "come near the Lord." Exodus 24:1-2.Censer - See Exodus 25:38 note.Strange fire - The point of their offence is evidently expressed in this term. This may very probably mean that the incense was lighted at an unauthorized time. And we may reasonably unite with this the supposition that they were intoxicated (compare Leviticus 10:9), as well as another conjecture, that they made their offering of incense an accompaniment to the exultation of the people on the manifestation of the glory of the Lord Leviticus 9:24. As they perished not within the tabernacle, but in front of it, it seems likely that they may have been making an ostentatious and irreverent display of their ministration to accompany the shouts of the people on their way toward the tabernacle. The offence for which they were immediately visited with outward punishment was thus a flagrant outrage on the solemn order of the divine service, while the cause of their offence may have been their guilty excess.', NULL, NULL, '''1-2.censer'':46 ''10'':93 ''2'':15 ''23'':12 ''24'':45,126 ''25'':49 ''3'':14 ''38'':50 ''6'':11 ''9'':94,125 ''aaron'':9 ''abihu'':3 ''accompani'':22,108,157 ''afar'':36 ''among'':18 ''anoth'':98 ''caus'':195 ''come'':40 ''compar'':91 ''conjectur'':99 ''display'':152 ''divin'':191 ''elder'':6 ''evid'':59 ''excess'':204 ''exodus'':10,44,48 ''express'':60 ''exult'':111 ''fire'':52 ''flagrant'':183 ''front'':136 ''glori'':120 ''go'':27 ''guilti'':203 ''immedi'':175 ''incens'':71,106 ''intox'':90 ''invit'':20 ''irrever'':151 ''leviticus'':92,124 ''light'':73 ''like'':141 ''lord'':43,123 ''made'':102 ''make'':147 ''manifest'':117 ''may'':65,80,144,199 ''mean'':68 ''ministr'':155 ''mose'':23 ''mount'':29 ''nadab'':1 ''near'':41 ''note.strange'':51 ''number'':13 ''offenc'':57,170,198 ''offer'':104 ''order'':188 ''ostentati'':149 ''outrag'':184 ''outward'':178 ''peopl'':114,162 ''perish'':129 ''point'':54 ''probabl'':67 ''punish'':179 ''reason'':81 ''see'':47 ''seem'':140 ''servic'':192 ''shout'':159 ''sinai'':30 ''solemn'':187 ''son'':7 ''supposit'':86 ''tabernacl'':133,168 ''term'':63 ''thus'':181 ''time'':77 ''toward'':166 ''two'':5 ''unauthor'':76 ''unit'':82 ''visit'':176 ''way'':165 ''well'':96 ''within'':131 ''worship'':35', NULL, '100');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('101', '2', '101', NULL, 'Divideth not the hoof - The toes of the camel are divided above, but they are united below in a sort of cushion or pad resting upon the hard bottom of the foot, which is "like the sole of a shoe." The Moslems eat the flesh of the camel, but it is said not to be wholesome.', NULL, NULL, '''bottom'':29 ''camel'':9,48 ''cushion'':22 ''divid'':11 ''divideth'':1 ''eat'':43 ''flesh'':45 ''foot'':32 ''hard'':28 ''hoof'':4 ''like'':35 ''moslem'':42 ''pad'':24 ''rest'':25 ''said'':52 ''shoe'':40 ''sole'':37 ''sort'':20 ''toe'':6 ''unit'':16 ''upon'':26 ''wholesom'':56', NULL, '101');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('102', '2', '102', NULL, 'This chapter would more naturally follow the 15th chapter of Leviticus. See the note to Leviticus 15:1.', NULL, NULL, '''1'':18 ''15'':17 ''15th'':8 ''chapter'':2,9 ''follow'':6 ''leviticus'':11,16 ''natur'':5 ''note'':14 ''see'':12 ''would'':3', NULL, '102');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('103', '2', '103', NULL, 'The skin of his flesh - An expression found nowhere but in this chapter. It probably denotes the cuticle or scarf skin, as distinguished from the curls or true skin.Rising ... scab ... bright spot - The Hebrew words are the technical names applied to the common external signs of incipient elephantiasis.Like the plague of leprosy - Like a stroke of leprosy.', NULL, NULL, '''appli'':40 ''bright'':31 ''chapter'':13 ''common'':43 ''curl'':26 ''cuticl'':18 ''denot'':16 ''distinguish'':23 ''elephantiasis.like'':48 ''express'':7 ''extern'':44 ''flesh'':5 ''found'':8 ''hebrew'':34 ''incipi'':47 ''leprosi'':52,57 ''like'':53 ''name'':39 ''nowher'':9 ''plagu'':50 ''probabl'':15 ''scab'':30 ''scarf'':20 ''sign'':45 ''skin'':2,21 ''skin.rising'':29 ''spot'':32 ''stroke'':55 ''technic'':38 ''true'':28 ''word'':35', NULL, '103');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('104', '2', '104', NULL, 'The leper was excluded not only from the sanctuary but from the camp. The ceremony of restoration which he had to undergo was therefore twofold. The first part, performed outside the camp, entitled him to come within and to mix with his brethren, Leviticus 14:3-9. The second part, performed in the court of the tabernacle and separated from the first by an interval of seven days, restored him to all the privileges of the covenant with Yahweh, Leviticus 14:10-32.', NULL, NULL, '''-32'':83 ''-9'':47 ''10'':82 ''14'':45,81 ''3'':46 ''brethren'':43 ''camp'':13,32 ''ceremoni'':15 ''come'':36 ''court'':54 ''coven'':77 ''day'':68 ''entitl'':33 ''exclud'':4 ''first'':27,62 ''interv'':65 ''leper'':2 ''leviticus'':44,80 ''mix'':40 ''outsid'':30 ''part'':28,50 ''perform'':29,51 ''privileg'':74 ''restor'':17,69 ''sanctuari'':9 ''second'':49 ''separ'':59 ''seven'':67 ''tabernacl'':57 ''therefor'':24 ''twofold'':25 ''undergo'':22 ''within'':37 ''yahweh'':79', NULL, '104');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('105', '2', '105', NULL, 'This chapter would seem to take its place more naturally before Leviticus 12:1-8, with the subject of which it is inmediately connected. Compare especially Leviticus 12:2 with Leviticus 15:19. It stands here between two chapters, with neither of which has it any close connection.', NULL, NULL, '''-8'':15 ''1'':14 ''12'':13,28 ''15'':32 ''19'':33 ''2'':29 ''chapter'':2,39 ''close'':47 ''compar'':25 ''connect'':24,48 ''especi'':26 ''inmedi'':23 ''leviticus'':12,27,31 ''natur'':10 ''neither'':41 ''place'':8 ''seem'':4 ''stand'':35 ''subject'':18 ''take'':6 ''two'':38 ''would'':3', NULL, '105');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('106', '2', '106', NULL, 'The reference to the death of Nadab and Abihu is a notice of the occasion on which the instructions were given, well calculated to add point and emphasis to the solemn admonition to the high priest in the second verse. The death of his sons Leviticus 10:2, for drawing near to Yahweh in an unauthorized manner, was to serve as a warning to Aaron himself never to transgress in this respect.', NULL, NULL, '''10'':47 ''2'':48 ''aaron'':65 ''abihu'':9 ''add'':25 ''admonit'':32 ''calcul'':23 ''death'':5,42 ''draw'':50 ''emphasi'':28 ''given'':21 ''high'':35 ''instruct'':19 ''leviticus'':46 ''manner'':57 ''nadab'':7 ''near'':51 ''never'':67 ''notic'':12 ''occas'':15 ''point'':26 ''priest'':36 ''refer'':2 ''respect'':72 ''second'':39 ''serv'':60 ''solemn'':31 ''son'':45 ''transgress'':69 ''unauthor'':56 ''vers'':40 ''warn'':63 ''well'':22 ''yahweh'':53', NULL, '106');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('107', '2', '107', NULL, 'This chapter, in its immediate bearing on the daily life of the Israelites, stands as the first of four Leviticus 17-20 which set forth practical duties, directing the Israelites to walk, not in the way of the pagan, but according to the ordinances of Yahweh.', NULL, NULL, '''-20'':22 ''17'':21 ''accord'':41 ''bear'':6 ''chapter'':2 ''daili'':9 ''direct'':28 ''duti'':27 ''first'':17 ''forth'':25 ''four'':19 ''immedi'':5 ''israelit'':13,30 ''leviticus'':20 ''life'':10 ''ordin'':44 ''pagan'':39 ''practic'':26 ''set'':24 ''stand'':14 ''walk'':32 ''way'':36 ''yahweh'':46', NULL, '107');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('108', '2', '108', NULL, 'I am, the Lord your God - The frequent repetition of this formula in these parts of the Law may be intended to keep the Israelites in mind of their covenant with Yahweh in connection with the common affairs of life, in which they might be tempted to look at legal restrictions in a mere secular light.', NULL, NULL, '''affair'':38 ''common'':37 ''connect'':34 ''coven'':30 ''formula'':12 ''frequent'':8 ''god'':6 ''intend'':21 ''israelit'':25 ''keep'':23 ''law'':18 ''legal'':50 ''life'':40 ''light'':56 ''look'':48 ''lord'':4 ''may'':19 ''mere'':54 ''might'':44 ''mind'':27 ''part'':15 ''repetit'':9 ''restrict'':51 ''secular'':55 ''tempt'':46 ''yahweh'':32', NULL, '108');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('109', '2', '109', NULL, 'Ye shall be holy ... - These words express the keynote to the whole book of Leviticus, being addressed to the whole nation. There does not appear to be any systematic arrangement in the laws which follow. They were intended as guards to the sanctity of the elect people, enforcing common duties by immediate appeal to the highest authority. Compare Leviticus 18:24-30 note.', NULL, NULL, '''-30'':62 ''18'':60 ''24'':61 ''address'':17 ''appeal'':53 ''appear'':25 ''arrang'':30 ''author'':57 ''book'':13 ''common'':49 ''compar'':58 ''duti'':50 ''elect'':46 ''enforc'':48 ''express'':7 ''follow'':35 ''guard'':40 ''highest'':56 ''holi'':4 ''immedi'':52 ''intend'':38 ''keynot'':9 ''law'':33 ''leviticus'':15,59 ''nation'':21 ''note'':63 ''peopl'':47 ''sanctiti'':43 ''shall'':2 ''systemat'':29 ''whole'':12,20 ''word'':6 ''ye'':1', NULL, '109');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('110', '2', '110', NULL, 'The crimes which are condemned in Leviticus 18; 19 on purely spiritual ground, have here special punishments allotted to them as offences against the well-being of the nation.', NULL, NULL, '''18'':8 ''19'':9 ''allot'':18 ''condemn'':5 ''crime'':2 ''ground'':13 ''leviticus'':7 ''nation'':30 ''offenc'':22 ''punish'':17 ''pure'':11 ''special'':16 ''spiritu'':12 ''well'':26 ''well-b'':25', NULL, '110');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('111', '2', '111', NULL, 'The sense seems to be that, owing to his position in the nation, the priest is not to defile himself in any cases except those named in Leviticus 21:2-3. The Septuagint appear to have followed a different reading of the text which would mean, "he shall not defile himself for a moment." The explanation in the margin of our version is hardly in keeping with the prohibition to Ezekiel on a special occasion. See Ezekiel 24:16.', NULL, NULL, '''-3'':31 ''16'':79 ''2'':30 ''21'':29 ''24'':78 ''appear'':34 ''case'':23 ''defil'':19,50 ''differ'':39 ''except'':24 ''explan'':56 ''ezekiel'':71,77 ''follow'':37 ''hard'':64 ''keep'':66 ''leviticus'':28 ''margin'':59 ''mean'':46 ''moment'':54 ''name'':26 ''nation'':13 ''occas'':75 ''owe'':7 ''posit'':10 ''priest'':15 ''prohibit'':69 ''read'':40 ''see'':76 ''seem'':3 ''sens'':2 ''septuagint'':33 ''shall'':48 ''special'':74 ''text'':43 ''version'':62 ''would'':45', NULL, '111');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('646', '2', '646', NULL, 'The text and the marginal readings indicate the two chief constructions of this somewhat difficult verse. Other renderings are(1) He who separateth himself from others seeks his own desire, and rushes forward against all wise counsel: a warning against self-will and the self-assertion which exults in differing from the received customs and opinions of mankind.(2) he who separates himself (from the foolish, unlearned multitude) seeks his own desire (that which is worthy to be desired), and mingleth himself with all wisdom. So the Jewish commentators generally.Between (1) blaming and (2) commending the life of isolation, the decision must be that (1) is most in harmony with the temper of the Book of Proverbs; but it is not strange that Pharisaism, in its very name, separating and self-exalting, should have adopted (2).', NULL, NULL, '''1'':20,93,107 ''2'':61,96,139 ''adopt'':138 ''assert'':48 ''blame'':94 ''book'':117 ''chief'':10 ''commend'':97 ''comment'':91 ''construct'':11 ''counsel'':37 ''custom'':56 ''decis'':103 ''desir'':30,74,81 ''differ'':52 ''difficult'':15 ''exalt'':135 ''exult'':50 ''foolish'':68 ''forward'':33 ''generally.between'':92 ''harmoni'':111 ''indic'':7 ''isol'':101 ''jewish'':90 ''life'':99 ''mankind'':60 ''margin'':5 ''mingleth'':83 ''multitud'':70 ''must'':104 ''name'':130 ''opinion'':58 ''other'':26 ''pharisa'':126 ''proverb'':119 ''read'':6 ''receiv'':55 ''render'':18 ''rush'':32 ''seek'':27,71 ''self'':42,47,134 ''self-assert'':46 ''self-exalt'':133 ''self-wil'':41 ''separ'':64,131 ''separateth'':23 ''somewhat'':14 ''strang'':124 ''temper'':114 ''text'':2 ''two'':9 ''unlearn'':69 ''vers'':16 ''warn'':39 ''wisdom'':87 ''wise'':36 ''worthi'':78', NULL, '646');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('647', '2', '647', NULL, 'The "perverse" man is the rich fool, as contrasted with the poor man who is upright.Proverbs 19:1-2 are missing in the Septuagint.', NULL, NULL, '''-2'':19 ''1'':18 ''19'':17 ''contrast'':9 ''fool'':7 ''man'':3,13 ''miss'':21 ''pervers'':2 ''poor'':12 ''rich'':6 ''septuagint'':24 ''upright.proverbs'':16', NULL, '647');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('112', '2', '112', NULL, '"Speak ... that they so abstain from touching the holy things (i. e. the sacrificial food of all kinds) of the children of Israel which they consecrate unto me, that they profane not my holy name." This law related to the daily life and the ordinary food of the priests.', NULL, NULL, '''abstain'':5 ''children'':21 ''consecr'':26 ''daili'':41 ''e'':12 ''food'':15,46 ''holi'':9,34 ''israel'':23 ''kind'':18 ''law'':37 ''life'':42 ''name'':35 ''ordinari'':45 ''priest'':49 ''profan'':31 ''relat'':38 ''sacrifici'':14 ''speak'':1 ''thing'':10 ''touch'':7 ''unto'':27', NULL, '112');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('52', '2', '52', NULL, 'Bare a son - Not her firstborn; Aaron and Miriam were older than Moses. The object of the writer is simply to narrate the events which led to the Exodus, and he mentions nothing that had no direct bearing upon his purpose.A goodly child - See the marginal references. Probably Jochebed did not call in a midwife Exodus 1:15, and she was of course cautious not to show herself to Egyptians. The hiding of the child is spoken of as an act of faith in Hebrews 11:23. It was done in the belief that God would watch over the child.', NULL, NULL, '''1'':57 ''11'':86 ''15'':58 ''23'':87 ''aaron'':7 ''act'':81 ''bare'':1 ''bear'':38 ''belief'':93 ''call'':52 ''cautious'':64 ''child'':43,75,100 ''cours'':63 ''direct'':37 ''done'':90 ''egyptian'':70 ''event'':24 ''exodus'':29,56 ''faith'':83 ''firstborn'':6 ''god'':95 ''good'':42 ''hebrew'':85 ''hide'':72 ''jocheb'':49 ''led'':26 ''margin'':46 ''mention'':32 ''midwif'':55 ''miriam'':9 ''mose'':13 ''narrat'':22 ''noth'':33 ''object'':15 ''older'':11 ''probabl'':48 ''purpose.a'':41 ''refer'':47 ''see'':44 ''show'':67 ''simpli'':20 ''son'':3 ''spoken'':77 ''upon'':39 ''watch'':97 ''would'':96 ''writer'':18', NULL, '52');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('648', '2', '648', NULL, '"Wine" and "strong drink" are personified as themselves doing what they make men do. The latter (see Leviticus 10:9 note) is here, probably, the "palm-wine" of Syria.', NULL, NULL, '''10'':19 ''9'':20 ''drink'':4 ''latter'':16 ''leviticus'':18 ''make'':12 ''men'':13 ''note'':21 ''palm'':27 ''palm-win'':26 ''personifi'':6 ''probabl'':24 ''see'':17 ''strong'':3 ''syria'':30 ''wine'':1,28', NULL, '648');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('649', '2', '649', NULL, 'Rivers of water - See the Psalm 1:3 note. As the cultivator directs the stream into the channels where it is most wanted, so Yahweh directs the thoughts of the true king, that his favors may fall, not at random, but in harmony with a divine order.', NULL, NULL, '''1'':7 ''3'':8 ''channel'':18 ''cultiv'':12 ''direct'':13,26 ''divin'':46 ''fall'':37 ''favor'':35 ''harmoni'':43 ''king'':32 ''may'':36 ''note'':9 ''order'':47 ''psalm'':6 ''random'':40 ''river'':1 ''see'':4 ''stream'':15 ''thought'':28 ''true'':31 ''want'':23 ''water'':3 ''yahweh'':25', NULL, '649');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('113', '2', '113', NULL, 'On the morrow after the sabbath - It is most probable that these words denote the 16th of Abib, the day after the first day of holy convocation (see Leviticus 23:5-8 note), and that this was called "the Sabbath of the Passover", or, "the Sabbath of unleavened bread".', NULL, NULL, '''-8'':32 ''16th'':16 ''23'':30 ''5'':31 ''abib'':18 ''bread'':49 ''call'':38 ''convoc'':27 ''day'':20,24 ''denot'':14 ''first'':23 ''holi'':26 ''leviticus'':29 ''morrow'':3 ''note'':33 ''passov'':43 ''probabl'':10 ''sabbath'':6,40,46 ''see'':28 ''unleaven'':48 ''word'':13', NULL, '113');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('114', '2', '114', NULL, 'The oil for the lamps of the tabernacle and the meal for the showbread were to be offerings from the Congregation, like the meal for the Pentecostal loaves, Leviticus 23:17. It appears that the responsibility of keeping up the lights rested on the high priest, but the actual service might be performed, on ordinary occasions, by the common priests. Compare margin reference.', NULL, NULL, '''17'':31 ''23'':30 ''actual'':49 ''appear'':33 ''common'':59 ''compar'':61 ''congreg'':21 ''high'':45 ''keep'':38 ''lamp'':5 ''leviticus'':29 ''light'':41 ''like'':22 ''loav'':28 ''margin'':62 ''meal'':11,24 ''might'':51 ''occas'':56 ''offer'':18 ''oil'':2 ''ordinari'':55 ''pentecost'':27 ''perform'':53 ''priest'':46,60 ''refer'':63 ''respons'':36 ''rest'':42 ''servic'':50 ''showbread'':14 ''tabernacl'':8', NULL, '114');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('115', '2', '115', NULL, 'The sabbatical year and the year of Jubilee belong to that great sabbatical system which runs through the religious observances of the Law, but rest upon moral rather than upon formally religious ground. It is not, therefore, without reason that they are here set apart from the set times which fell strictly within the sphere of religious observances.', NULL, NULL, '''apart'':45 ''belong'':9 ''fell'':51 ''formal'':31 ''great'':12 ''ground'':33 ''jubile'':8 ''law'':23 ''moral'':27 ''observ'':20,58 ''rather'':28 ''reason'':39 ''religi'':19,32,57 ''rest'':25 ''run'':16 ''sabbat'':2,13 ''set'':44,48 ''sphere'':55 ''strict'':52 ''system'':14 ''therefor'':37 ''time'':49 ''upon'':26,30 ''within'':53 ''without'':38 ''year'':3,6', NULL, '115');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('913', '2', '913', NULL, 'A man with a measuring line in his hand - Probably the Angel of the Lord, of whom Ezekiel has a like vision. Jerome: "He who before, when he lift up his eyes, had seen in the four horns things mournful, now again lifts up his eves to see a man, of whom it is written, "Behold a man whose name is the Branch" Zechariah 6:12; of whom we read above, "Behold a man riding upon a red horse, and he stood among the myrtle trees, which were in the bottom" Zechariah 1:8. Of whom too the Father saith; He builded My city, "whose builder and maker is God" Hebrews 11:10. He too is seen by Ezekiel in a description like this, "a man whose appearance was like the appearance of brass" Ezekiel 40:3, that is, "burnished and shining as fire, with a line of flax in his hand and a measuring reed" Ezekiel 1:7. The office also seems to be one of authority, not to measure the actual length and breadth of Jerusalem, but to lay down what it should be, (Cyril), "to mark it out broad and very long."', NULL, NULL, '''1'':93,158 ''10'':113 ''11'':112 ''12'':66 ''3'':137 ''40'':136 ''6'':65 ''7'':159 ''8'':94 ''actual'':173 ''also'':162 ''among'':83 ''angel'':12 ''appear'':128,132 ''author'':168 ''behold'':56,72 ''bottom'':91 ''branch'':63 ''brass'':134 ''breadth'':176 ''broad'':192 ''build'':102 ''builder'':106 ''burnish'':140 ''citi'':104 ''cyril'':187 ''descript'':122 ''eve'':46 ''eye'':32 ''ezekiel'':18,119,135,157 ''father'':99 ''fire'':144 ''flax'':149 ''four'':37 ''god'':110 ''hand'':9,152 ''hebrew'':111 ''horn'':38 ''hors'':79 ''jerom'':23 ''jerusalem'':178 ''lay'':181 ''length'':174 ''lift'':29,43 ''like'':21,123,130 ''line'':6,147 ''long'':195 ''lord'':15 ''maker'':108 ''man'':2,50,58,74,126 ''mark'':189 ''measur'':5,155,171 ''mourn'':40 ''myrtl'':85 ''name'':60 ''offic'':161 ''one'':166 ''probabl'':10 ''read'':70 ''red'':78 ''reed'':156 ''ride'':75 ''saith'':100 ''see'':48 ''seem'':163 ''seen'':34,117 ''shine'':142 ''stood'':82 ''thing'':39 ''tree'':86 ''upon'':76 ''vision'':22 ''whose'':59,105,127 ''written'':55 ''zechariah'':64,92', NULL, '913');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('914', '2', '914', NULL, 'And the angel of the Lord protested - Solemnly (etymologically, called God to witness) as in, "Did I not make thee swear by the Lord and protested unto thee" 1 Kings 2:42, laying it as an obligation upon him. The charge is given to Joshua, and in him to all successive high priests, while Israel should continue to be God''s people, as the condition of their acceptance.', NULL, NULL, '''1'':29 ''2'':31 ''42'':32 ''accept'':68 ''angel'':3 ''call'':10 ''charg'':41 ''condit'':65 ''continu'':57 ''etymolog'':9 ''given'':43 ''god'':11,60 ''high'':52 ''israel'':55 ''joshua'':45 ''king'':30 ''lay'':33 ''lord'':6,24 ''make'':19 ''oblig'':37 ''peopl'':62 ''priest'':53 ''protest'':7,26 ''solemn'':8 ''success'':51 ''swear'':21 ''thee'':20,28 ''unto'':27 ''upon'':38 ''wit'':13', NULL, '914');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('497', '2', '497', NULL, 'The heavens declare the glory of God - They announce, proclaim, make known his glory. The word heavens here refers to the material heavens as they appear to the eye - the region of the sun, moon, and stars. The Hebrew word is used in the Scriptures uniformly in the plural number, though in our common translation the singular number is often used. Genesis 1:1, Genesis 1:8-9, Genesis 1:14, Genesis 1:17, Genesis 1:20; Genesis 6:17; Genesis 7:11, Genesis 7:19, Genesis 7:23; et soepe. The plural, however, is often retained, but without any special reason why it should be retained in one place rather than in another. Genesis 2:1, Genesis 2:4; Deuteronomy 10:14; Ezra 9:6; Psalm 2:4; Psalm 8:1, Psalm 8:3; Psalm 18:13. The original idea may have been that there was one heaven above another - one in which the sun was placed, another in which the moon was placed, then the planets, the fixed stars, etc. Above all was supposed to be the place where God dwells. The word glory here means that which constitutes the glory or honor of God - his wisdom, power, skill, faithfulness, benevolence, as seen in the starry worlds above us, the silent, but solemn movements by day and by night. The idea is, that these convey to the mind a true impression of the greatness and majesty of God. The reference here is to these heavens as they appear to the naked eye, and as they are observed by all men. It may be added that the impression is far more solemn and grand when we take into the estimate the disclosures of the modern astronomy, and when we look at the heavens, not merely by the naked eye, but through the revelations of the telescope.And the firmament - See the note at Daniel 12:3. The word rendered firmament -   raqya, means properly "an expanse" - that which is spread out - and is applied to the heavens as they appear to be spread out or expanded above us. The word occurs elsewhere in the following places, and is always rendered "firmament" in our common version, Genesis 1:6, Genesis 1:7 (twice), Genesis 1:8, Genesis 1:14, Genesis 1:15, Genesis 1:17, Genesis 1:20; Psalm 150:1; Ezekiel 1:22-23, Ezekiel 1:25-26; Ezekiel 10:1; Daniel 12:3. The word "firmament" - that which is firm or fixed - is taken from the word used by the translators of the Septuagint, &#x3c3;&#x3c4;&#x3b5;&#x3c1;&#x3b5;&#x3c9;&#x3bc;&#x3b1;  stereoma, from the idea that the heavens above us are a solid concave. In the Scriptures the stars are represented as placed in that expanse, so that if it should be rolled together as a tent is rolled up, they would fall down to the earth. See the note at Isaiah 34:4. The reference in the passage before us is to the heavens as they appear to be spread out over our heads, and in which the stars are fixed.Showeth his handywork - The heavens make known the work of his hands. The idea is that God had made those heavens by his own hands, and that the firmament, thus adorned with sun, and moon, and stars, showed the wisdom and skill with which it was done. Compare Psalm 8:3.', NULL, NULL, '''-23'':393 ''-26'':397 ''-9'':68 ''1'':63,64,66,70,73,76,117,132,366,369,373,376,379,382,385,389,391,395,400 ''10'':122,399 ''11'':83 ''12'':315,402 ''13'':138 ''14'':71,123,377 ''15'':380 ''150'':388 ''17'':74,80,383 ''18'':137 ''19'':86 ''2'':116,119,128 ''20'':77,386 ''22'':392 ''23'':89 ''25'':396 ''3'':135,316,403,555 ''34'':476 ''4'':120,129,477 ''6'':79,126,367 ''7'':82,85,88,370 ''8'':67,131,134,374,554 ''9'':125 ''add'':266 ''adorn'':535 ''alway'':358 ''announc'':9 ''anoth'':114,151,159 ''appear'':26,250,339,491 ''appli'':333 ''astronomi'':287 ''benevol'':203 ''common'':54,363 ''compar'':552 ''concav'':437 ''constitut'':191 ''convey'':227 ''daniel'':314,401 ''day'':218 ''declar'':3 ''deuteronomi'':121 ''disclosur'':283 ''done'':551 ''dwell'':183 ''earth'':470 ''elsewher'':351 ''estim'':281 ''et'':90 ''etc'':172 ''expand'':345 ''expans'':325,449 ''eye'':29,254,300 ''ezekiel'':390,394,398 ''ezra'':124 ''faith'':202 ''fall'':466 ''far'':271 ''firm'':410 ''firmament'':309,320,360,406,533 ''fix'':170,412 ''fixed.showeth'':505 ''follow'':354 ''genesi'':62,65,69,72,75,78,81,84,87,115,118,365,368,372,375,378,381,384 ''glori'':5,14,186,193 ''god'':7,182,197,240,521 ''grand'':275 ''great'':236 ''hand'':516,529 ''handywork'':507 ''head'':498 ''heaven'':2,17,23,149,247,294,336,431,488,509,525 ''hebrew'':39 ''honor'':195 ''howev'':94 ''idea'':141,223,428,518 ''impress'':233,269 ''isaiah'':475 ''known'':12,511 ''look'':291 ''made'':523 ''majesti'':238 ''make'':11,510 ''materi'':22 ''may'':142,264 ''mean'':188,322 ''men'':262 ''mere'':296 ''mind'':230 ''modern'':286 ''moon'':35,163,539 ''movement'':216 ''nake'':253,299 ''night'':221 ''note'':312,473 ''number'':50,58 ''observ'':259 ''occur'':350 ''often'':60,96 ''one'':109,148,152 ''origin'':140 ''passag'':482 ''place'':110,158,165,180,355,446 ''planet'':168 ''plural'':49,93 ''power'':200 ''proclaim'':10 ''proper'':323 ''psalm'':127,130,133,136,387,553 ''raqya'':321 ''rather'':111 ''reason'':102 ''refer'':19,242,479 ''region'':31 ''render'':319,359 ''repres'':444 ''retain'':97,107 ''revel'':304 ''roll'':456,462 ''scriptur'':45,440 ''see'':310,471 ''seen'':205 ''septuagint'':424 ''show'':542 ''silent'':213 ''singular'':57 ''skill'':201,546 ''soep'':91 ''solemn'':215,273 ''solid'':436 ''special'':101 ''spread'':329,342,494 ''star'':37,171,442,503,541 ''starri'':208 ''stereoma'':425 ''sun'':34,156,537 ''suppos'':176 ''take'':278 ''taken'':414 ''telescope.and'':307 ''tent'':460 ''though'':51 ''thus'':534 ''togeth'':457 ''translat'':55,421 ''true'':232 ''twice'':371 ''uniform'':46 ''us'':211,347,433,484 ''use'':42,61,418 ''version'':364 ''wisdom'':199,544 ''without'':99 ''word'':16,40,185,318,349,405,417 ''work'':513 ''world'':209 ''would'':465', NULL, '497');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('498', '2', '498', NULL, 'The Lord hear thee in the day of trouble - According to the view expressed in the introduction to the psalm, this is the language of the people praying for their king, or expressing the hope that he would be delivered from trouble, and would be successful in what he had undertaken, in the prosecution of a war apparently of defense. The word" trouble" here used would seem to imply that he was beset with difficulties and dangers; perhaps, that he was surrounded by foes. It seems that he was going forth to war to deliver his country from trouble, having offered sacrifices and prayers Psalm 20:3 for the purpose of securing the divine favor on the expedition. The point or the moment of the psalm is when those sacrifices had been offered, and when he was about to embark on his enterprise. At that moment the people lift up the voice of sympathy and of encouragement, and pray that those sacrifices might be accepted, and that he might find the deliverance which he had desired.The name of the God of Jacob - The word name is often put in the Scriptures for the person himself; and hence, this is equivalent to saying, "May the God of Jacob defend thee." See Psalm 5:11; Psalm 9:10; Psalm 44:5; Psalm 54:1; Exodus 23:21. Jacob was the one of the patriarchs from whom, after his other name, the Hebrew people derived their name Israel, and the word seems here to be used with reference to the people rather than to the ancestor. Compare Isaiah 44:2. The God of Jacob, or the God of Israel, would be synonymous terms, and either would denote that he was the Protector of the nation. As such he is invoked here; and the prayer is, that the Great Protector of the Hebrew people would now defend the king in the dangers which beset him, and in the enterprise which he had undertaken.Defend thee - Margin, as in Hebrew, set thee on a high place. The word means the same as defend him, for the idea is that of being set on a high place, a tower, a mountain, a lofty rock, where his enemies could not reach or assail him.', NULL, NULL, '''1'':222 ''10'':216 ''11'':213 ''2'':267 ''20'':106 ''21'':225 ''23'':224 ''3'':107 ''44'':218,266 ''5'':212,219 ''54'':221 ''9'':215 ''accept'':165 ''accord'':10 ''ancestor'':263 ''appar'':58 ''assail'':375 ''beset'':73,320 ''compar'':264 ''could'':371 ''countri'':97 ''danger'':77,318 ''day'':7 ''defend'':208,313,347 ''defens'':60 ''deliv'':40,95 ''deliver'':172 ''denot'':284 ''deriv'':242 ''desired.the'':176 ''difficulti'':75 ''divin'':114 ''either'':282 ''embark'':140 ''encourag'':157 ''enemi'':370 ''enterpris'':143,325 ''equival'':200 ''exodus'':223 ''expedit'':118 ''express'':14,33 ''favor'':115 ''find'':170 ''foe'':84 ''forth'':91 ''go'':90 ''god'':180,205,269,274 ''great'':305 ''hear'':3 ''hebrew'':240,309,334 ''henc'':197 ''high'':339,359 ''hope'':35 ''idea'':351 ''impli'':69 ''introduct'':17 ''invok'':297 ''isaiah'':265 ''israel'':245,276 ''jacob'':182,207,226,271 ''king'':31,315 ''languag'':24 ''lift'':149 ''lofti'':366 ''lord'':2 ''margin'':331 ''may'':203 ''mean'':343 ''might'':163,169 ''moment'':123,146 ''mountain'':364 ''name'':177,185,238,244 ''nation'':292 ''offer'':101,133 ''often'':187 ''one'':229 ''patriarch'':232 ''peopl'':27,148,241,258,310 ''perhap'':78 ''person'':194 ''place'':340,360 ''point'':120 ''pray'':28,159 ''prayer'':104,301 ''prosecut'':54 ''protector'':289,306 ''psalm'':20,105,126,211,214,217,220 ''purpos'':110 ''put'':188 ''rather'':259 ''reach'':373 ''refer'':255 ''rock'':367 ''sacrific'':102,130,162 ''say'':202 ''scriptur'':191 ''secur'':112 ''see'':210 ''seem'':67,86,249 ''set'':335,356 ''success'':46 ''surround'':82 ''sympathi'':154 ''synonym'':279 ''term'':280 ''thee'':4,209,330,336 ''tower'':362 ''troubl'':9,42,63,99 ''undertaken'':51 ''undertaken.defend'':329 ''use'':65,253 ''view'':13 ''voic'':152 ''war'':57,93 ''word'':62,184,248,342 ''would'':38,44,66,277,283,311', NULL, '498');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('650', '2', '650', NULL, 'Excellent things - A meaning of the word derived from "the third," i. e., "the chief of three warriors in a chariot" (compare Exodus 14:7 note). Another reading of the Hebrew text gives "Have I not written to thee long ago?" and this would form a natural antithesis to "this day" of Proverbs 22:19. The rendering of the Septuagint is: "write them for thyself three times;" that of the Vulgate, "I have written it (i. e., my counsel) In threefold form;" the "three times" or "threefold form" being referred either to the Proverbs, Ecclesiastes, the Song of Solomon, or to the division of the Old Testament into the Law, the prophets, and the Hagiographa.', NULL, NULL, '''14'':24 ''19'':55 ''22'':54 ''7'':25 ''ago'':41 ''anoth'':27 ''antithesi'':48 ''chariot'':21 ''chief'':15 ''compar'':22 ''counsel'':79 ''day'':51 ''deriv'':8 ''divis'':103 ''e'':13,77 ''ecclesiast'':95 ''either'':91 ''excel'':1 ''exodus'':23 ''form'':45,82,88 ''give'':33 ''hagiographa'':115 ''hebrew'':31 ''law'':110 ''long'':40 ''mean'':4 ''natur'':47 ''note'':26 ''old'':106 ''prophet'':112 ''proverb'':53,94 ''read'':28 ''refer'':90 ''render'':57 ''septuagint'':60 ''solomon'':99 ''song'':97 ''testament'':107 ''text'':32 ''thee'':39 ''thing'':2 ''third'':11 ''three'':17,66,84 ''threefold'':81,87 ''thyself'':65 ''time'':67,85 ''vulgat'':71 ''warrior'':18 ''word'':7 ''would'':44 ''write'':62 ''written'':37,74', NULL, '650');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('651', '2', '651', NULL, 'Set thine eyes - literally, as in the margin, i. e., "gaze eagerly upon;" and then we get an emphatic parallelism with the words that follow, "they fly away as an eagle toward heaven;" "certainly make themselves wings."', NULL, NULL, '''away'':28 ''certain'':34 ''e'':10 ''eager'':12 ''eagl'':31 ''emphat'':19 ''eye'':3 ''fli'':27 ''follow'':25 ''gaze'':11 ''get'':17 ''heaven'':33 ''liter'':4 ''make'':35 ''margin'':8 ''parallel'':20 ''set'':1 ''thine'':2 ''toward'':32 ''upon'':13 ''wing'':37 ''word'':23', NULL, '651');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('652', '2', '652', NULL, 'A lesson given before, now combined with another. True followers after wisdom will admit neither envy of evil on the one hand, nor admiration or fellowship with it on the other.', NULL, NULL, '''admir'':24 ''admit'':14 ''anoth'':8 ''combin'':6 ''envi'':16 ''evil'':18 ''fellowship'':26 ''follow'':10 ''given'':3 ''hand'':22 ''lesson'':2 ''neither'':15 ''one'':21 ''true'':9 ''wisdom'':12', NULL, '652');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('653', '2', '653', NULL, 'The earthly monarch might be, in some respects, the type of the heavenly, but here there is a marked contrast. The king presses further and further into all knowledge; God surrounds Himself as in "thick darkness," and there are secrets unrevealed even after the fullest revelation.', NULL, NULL, '''contrast'':20 ''dark'':36 ''earth'':2 ''even'':42 ''fullest'':45 ''god'':30 ''heaven'':13 ''king'':22 ''knowledg'':29 ''mark'':19 ''might'':4 ''monarch'':3 ''press'':23 ''respect'':8 ''revel'':46 ''secret'':40 ''surround'':31 ''thick'':35 ''type'':10 ''unrev'':41', NULL, '653');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('654', '2', '654', NULL, 'In Palestine there is commonly hardly any rain from the early showers of spring to October. Hence, "rain in harvest" became sometimes (see the marginal reference) a supernatural sign, sometimes, as here, a proverb for whatever was strange and incongruous.', NULL, NULL, '''becam'':21 ''common'':5 ''earli'':11 ''hard'':6 ''harvest'':20 ''henc'':17 ''incongru'':40 ''margin'':25 ''octob'':16 ''palestin'':2 ''proverb'':34 ''rain'':8,18 ''refer'':26 ''see'':23 ''shower'':12 ''sign'':29 ''sometim'':22,30 ''spring'':14 ''strang'':38 ''supernatur'':28 ''whatev'':36', NULL, '654');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('655', '2', '655', NULL, 'Another - An "alienus" rather than "alius." Praise to be worth anything must be altogether independent.', NULL, NULL, '''alienus'':3 ''alius'':6 ''altogeth'':14 ''anoth'':1 ''anyth'':11 ''independ'':15 ''must'':12 ''prais'':7 ''rather'':4 ''worth'':10', NULL, '655');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('656', '2', '656', NULL, 'Transgression - Better, rebellion. A revolt against a ruler leads to rapid changes of dynasty (the whole history of the kingdom of Israel was a proof of this), but "with men of understanding and knowledge thus shall he (the prince) continue." True wisdom will lead people to maintain an existing order. The King James Version implies that political disorders may come as the punishment of any national sin.The state - Better, it (the land) shall surely prolong its days in stability.', NULL, NULL, '''better'':2,69 ''chang'':12 ''come'':60 ''continu'':40 ''day'':77 ''disord'':58 ''dynasti'':14 ''exist'':49 ''histori'':17 ''impli'':55 ''israel'':22 ''jame'':53 ''king'':52 ''kingdom'':20 ''knowledg'':34 ''land'':72 ''lead'':9,44 ''maintain'':47 ''may'':59 ''men'':30 ''nation'':66 ''order'':50 ''peopl'':45 ''polit'':57 ''princ'':39 ''prolong'':75 ''proof'':25 ''punish'':63 ''rapid'':11 ''rebellion'':3 ''revolt'':5 ''ruler'':8 ''shall'':36,73 ''sin.the'':67 ''stabil'':79 ''state'':68 ''sure'':74 ''thus'':35 ''transgress'':1 ''true'':41 ''understand'':32 ''version'':54 ''whole'':16 ''wisdom'':42', NULL, '656');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('657', '2', '657', NULL, 'Shall be destroyed - literally, "shall be broken" Proverbs 6:15. Stress is laid on the suddenness in such a case of the long-delayed retribution.', NULL, NULL, '''15'':10 ''6'':9 ''broken'':7 ''case'':20 ''delay'':25 ''destroy'':3 ''laid'':13 ''liter'':4 ''long'':24 ''long-delay'':23 ''proverb'':8 ''retribut'':26 ''shall'':1,5 ''stress'':11 ''sudden'':16', NULL, '657');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('915', '2', '915', NULL, 'The angel came again - The angel (as before Zechariah 2:3) had gone forth to receive some fresh instruction from a higher angel or from God.And awakened me - As a man is awakened out of sleep. Zechariah, overwhelmed by the greatness of the visions, must have sunk down in a sort of stupor, as after the vision of the ram and he-goat, as Gabriel was speaking with him, Daniel says, "I was in a deep sleep on my face toward the ground, and he touched me and set me upright" Daniel 8:18; and again at the voice of the angel, who, after his three weeks'' fast Daniel 10:9, came to declare to him Daniel 10:21 the scripture of truth; and at the Transfiguration, "Peter and they that were with him were heavy with sleep, and when they were awake, they saw His glory." Luke 9:32. Osorius: "Wondrous and stupendous mysteries were they which were shown to the divine man. He saw the Branch of the Lord; he saw His invincible might; he saw His brightness of Divine Intelligence and Providence; he saw the amplitude of beauty and dignity. Nailed then and struck still with amazement, while he revolved these things in his mind, sunk in a sort of sleep, he is borne out of himself and, mantled around with darkness, understands that the secret things of Divine Wisdom cannot be perfectly comprehended by the mind of any. This then he attained that, his senses being overpowered, he should see nothing, save that wherein is the sum of wisdom, that this immensity of the divine excellence cannot be searched out. By this sleep he was seized, when he was roused by the angel to see further mysteries."', NULL, NULL, '''10'':111,119 ''18'':95 ''2'':10 ''21'':120 ''3'':11 ''32'':151 ''8'':94 ''9'':112,150 ''amaz'':201 ''amplitud'':190 ''angel'':2,6,23,103,288 ''around'':224 ''attain'':247 ''awak'':144 ''awaken'':27,33 ''beauti'':192 ''born'':218 ''branch'':169 ''bright'':181 ''came'':3,113 ''cannot'':235,272 ''comprehend'':238 ''daniel'':71,93,110,118 ''dark'':226 ''declar'':115 ''deep'':77 ''digniti'':194 ''divin'':164,183,233,270 ''excel'':271 ''face'':81 ''fast'':109 ''forth'':14 ''fresh'':18 ''gabriel'':66 ''glori'':148 ''goat'':64 ''god.and'':26 ''gone'':13 ''great'':41 ''ground'':84 ''he-goat'':62 ''heavi'':137 ''higher'':22 ''immens'':267 ''instruct'':19 ''intellig'':184 ''invinc'':176 ''lord'':172 ''luke'':149 ''man'':31,165 ''mantl'':223 ''might'':177 ''mind'':209,241 ''must'':45 ''mysteri'':156,292 ''nail'':195 ''noth'':256 ''osorius'':152 ''overpow'':252 ''overwhelm'':38 ''perfect'':237 ''peter'':129 ''provid'':186 ''ram'':60 ''receiv'':16 ''revolv'':204 ''rous'':285 ''save'':257 ''saw'':146,167,174,179,188 ''say'':72 ''scriptur'':122 ''search'':274 ''secret'':230 ''see'':255,290 ''seiz'':281 ''sens'':250 ''set'':90 ''shown'':161 ''sleep'':36,78,139,215,278 ''sort'':51,213 ''speak'':68 ''still'':199 ''struck'':198 ''stupend'':155 ''stupor'':53 ''sum'':262 ''sunk'':47,210 ''thing'':206,231 ''three'':107 ''touch'':87 ''toward'':82 ''transfigur'':128 ''truth'':124 ''understand'':227 ''upright'':92 ''vision'':44,57 ''voic'':100 ''week'':108 ''wherein'':259 ''wisdom'':234,264 ''wondrous'':153 ''zechariah'':9,37', NULL, '915');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('53', '2', '53', NULL, 'Jethro his father-in-law - Or "brother-in-law." The word in the Hebrew is a word signifying relative by marriage. When Moses arrived in Midian, Reuel was an elderly man Exodus 2:16; 40 years later (Exodus 2:23 note), Reuel''s son, Jethro, had probably succeeded him.The backside - i. e. "to the west of the district." Among the Hebrews the East is before a man, the west behind him, the south and north on the right and left hand.Desert - Or wilderness, not a barren waste, but a district supplying pasturage. The district near Sherm, on the west of the gulf of Akabah, where Jethro may have resided, is described as barren and parched; on the west and east are rocky tracts, but to the northwest lies the district of Sinai, where the pasturage is good and water abundant. The Bedouins drive their flocks there from the lowlands at the approach of summer. From this it may be inferred that the events here recorded took place at that season.To Horeb - More exactly, toward Horeb. Moses came to the mountain of God, i. e. Sinai, on his way toward Horeb, a name given to the northern part of the Sinaitic range. Moses calls Sinai "mountain of God" by anticipation, with reference to the manifestation of God. There is no authority for assuming that the spot was previously held sacred (see Exodus 5:5); but it has been lately shown that the whole Peninsula was regarded by the Egyptians as specially consecrated to the gods from a very early time.', NULL, NULL, '''16'':36 ''2'':35,41 ''23'':42 ''40'':37 ''5'':234,235 ''abund'':142 ''akabah'':106 ''among'':61 ''anticip'':211 ''approach'':154 ''arriv'':26 ''assum'':224 ''author'':222 ''backsid'':52 ''barren'':88,115 ''bedouin'':144 ''behind'':72 ''brother'':9 ''brother-in-law'':8 ''call'':205 ''came'':179 ''consecr'':253 ''describ'':113 ''district'':60,92,96,132 ''drive'':145 ''e'':54,186 ''earli'':260 ''east'':65,122 ''egyptian'':250 ''elder'':32 ''event'':165 ''exact'':175 ''exodus'':34,40,233 ''father'':4 ''father-in-law'':3 ''flock'':147 ''given'':195 ''god'':184,209,218,256 ''good'':139 ''gulf'':104 ''hand.desert'':83 ''hebrew'':16,63 ''held'':230 ''him.the'':51 ''horeb'':173,177,192 ''infer'':162 ''jethro'':1,47,108 ''late'':240 ''later'':39 ''law'':6,11 ''left'':82 ''lie'':130 ''lowland'':151 ''man'':33,69 ''manifest'':216 ''marriag'':23 ''may'':109,160 ''midian'':28 ''mose'':25,178,204 ''mountain'':182,207 ''name'':194 ''near'':97 ''north'':77 ''northern'':198 ''northwest'':129 ''note'':43 ''parch'':117 ''part'':199 ''pasturag'':94,137 ''peninsula'':245 ''place'':169 ''previous'':229 ''probabl'':49 ''rang'':203 ''record'':167 ''refer'':213 ''regard'':247 ''relat'':21 ''resid'':111 ''reuel'':29,44 ''right'':80 ''rocki'':124 ''sacr'':231 ''season.to'':172 ''see'':232 ''sherm'':98 ''shown'':241 ''signifi'':20 ''sinai'':134,187,206 ''sinait'':202 ''son'':46 ''south'':75 ''special'':252 ''spot'':227 ''succeed'':50 ''summer'':156 ''suppli'':93 ''time'':261 ''took'':168 ''toward'':176,191 ''tract'':125 ''wast'':89 ''water'':141 ''way'':190 ''west'':57,71,101,120 ''whole'':244 ''wilder'':85 ''word'':13,19 ''year'':38', NULL, '53');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('658', '2', '658', NULL, 'See the introduction to Proverbs. According to the different reading, there noted, the inscription ends with: "the man spake," and the words that follow, are the beginning of the confession, "I have wearied myself after God and have fainted."Spake - The Hebrew word is that commonly used of the utterance of a divine oracle.', NULL, NULL, '''accord'':6 ''begin'':27 ''common'':46 ''confess'':30 ''differ'':9 ''divin'':53 ''end'':15 ''faint'':39 ''follow'':24 ''god'':36 ''hebrew'':42 ''inscript'':14 ''introduct'':3 ''man'':18 ''note'':12 ''oracl'':54 ''proverb'':5 ''read'':10 ''see'':1 ''spake'':19,40 ''use'':47 ''utter'':50 ''weari'':33 ''word'':22,43', NULL, '658');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('659', '2', '659', NULL, 'That his mother taught him - Compare Proverbs 1:8; Proverbs 6:20. If we refer the chapter to Israelite authorship, we may remember the honor paid to the wisdom of Miriam, Deborah, and Huldah; if it was the honor paid to an Edomite or an Arabian, we may think of the Queen of Sheba, whose love of Wisdom led her to sit at the feet of the son of David.', NULL, NULL, '''1'':8 ''20'':12 ''6'':11 ''8'':9 ''arabian'':46 ''authorship'':20 ''chapter'':17 ''compar'':6 ''david'':70 ''deborah'':32 ''edomit'':43 ''feet'':65 ''honor'':25,39 ''huldah'':34 ''israelit'':19 ''led'':59 ''love'':56 ''may'':22,48 ''miriam'':31 ''mother'':3 ''paid'':26,40 ''proverb'':7,10 ''queen'':52 ''refer'':15 ''rememb'':23 ''sheba'':54 ''sit'':62 ''son'':68 ''taught'':4 ''think'':49 ''whose'':55 ''wisdom'':29,58', NULL, '659');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('54', '2', '54', NULL, 'With this chapter begins the series of miracles which resulted in the deliverance of Israel. The first miracle was performed to remove the first obstacle, namely, the reluctance of Moses, conscious of his own weakness, and of the enormous power with which he would have to contend.', NULL, NULL, '''begin'':4 ''chapter'':3 ''conscious'':31 ''contend'':47 ''deliver'':13 ''enorm'':39 ''first'':17,24 ''israel'':15 ''miracl'':8,18 ''mose'':30 ''name'':26 ''obstacl'':25 ''perform'':20 ''power'':40 ''reluct'':28 ''remov'':22 ''result'':10 ''seri'':6 ''weak'':35 ''would'':44', NULL, '54');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('55', '2', '55', NULL, 'Pharaoh - This king, probably Tothmosis II, the great grandson of Aahmes Exodus 1:8, the original persecutor of the Israelites, must have been resident at this time in a city, probably Tanis Exodus 2:5, of Lower Egypt, situated on the Nile.The Lord God - Yahweh God of Israel demanded the services of His people. The demand, according to the general views of the pagans, was just and natural; the Israelites could not offer the necessary sacrifices in the presence of Egyptians.', NULL, NULL, '''1'':13 ''2'':34 ''5'':35 ''8'':14 ''aahm'':11 ''accord'':57 ''citi'':30 ''could'':71 ''demand'':49,56 ''egypt'':38 ''egyptian'':81 ''exodus'':12,33 ''general'':60 ''god'':44,46 ''grandson'':9 ''great'':8 ''ii'':6 ''israel'':48 ''israelit'':20,70 ''king'':3 ''lord'':43 ''lower'':37 ''must'':21 ''natur'':68 ''necessari'':75 ''nile.the'':42 ''offer'':73 ''origin'':16 ''pagan'':64 ''peopl'':54 ''persecutor'':17 ''pharaoh'':1 ''presenc'':79 ''probabl'':4,31 ''resid'':24 ''sacrific'':76 ''servic'':51 ''situat'':39 ''tani'':32 ''time'':27 ''tothmosi'':5 ''view'':61 ''yahweh'':45', NULL, '55');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('926', '2', '926', NULL, 'The burden of the word of the Lord to Israel - o "The word of the Lord is heavy, because it is called a burden, yet it hath something of consolation, because it is not ''against,'' but to Israel. For it is one thing when we write to this or that person; another, when we write ''against'' this or that person; the one being the part of friendship, the other, the open admission of enmity.""By the hand of Malachi;" through him, as the instrument of God, deposited with him; as Paul speaks of 1 Corinthians 9:17; Titus 1:3, "the dispensation of the Gospel 2 Corinthians 5:19, the Lord of reconciliation; Galatians 2:7, the Gospel of the uncircumcision, being committed to him."', NULL, NULL, '''1'':94,99 ''17'':97 ''19'':109 ''2'':106,115 ''3'':100 ''5'':108 ''7'':116 ''9'':96 ''admiss'':72 ''anoth'':52 ''burden'':2,24 ''call'':22 ''commit'':123 ''consol'':30 ''corinthian'':95,107 ''deposit'':87 ''dispens'':102 ''enmiti'':74 ''friendship'':67 ''galatian'':114 ''god'':86 ''gospel'':105,118 ''hand'':77 ''hath'':27 ''heavi'':18 ''instrument'':84 ''israel'':10,38 ''lord'':8,16,111 ''malachi'':79 ''o'':11 ''one'':42,62 ''open'':71 ''part'':65 ''paul'':91 ''person'':51,60 ''reconcili'':113 ''someth'':28 ''speak'':92 ''thing'':43 ''titus'':98 ''uncircumcis'':121 ''word'':5,13 ''write'':46,55 ''yet'':25', NULL, '926');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('975', '2', '975', NULL, 'sense with some addition or modification. See the Introduction to the Book of Job. Sometimes this was alternate, and sometimes it was introverted - where the first and fourth lines would correspond, and the second and third. This is the case here. The dogs would tear, and not the swine; the swine would trample the pearls under their feet, and not the dogs. It may be thus expressed:Give not that which is holy unto the dogs,Neither cast ye your pearls before swine,Lest they (that is, the swine) trample them under their feet,And turn again (that is, the dogs) and rend you.', NULL, NULL, '''addit'':4 ''altern'':18 ''book'':12 ''case'':40 ''cast'':78 ''correspond'':31 ''dog'':43,62,76,101 ''express'':67 ''feet'':58,94 ''first'':26 ''fourth'':28 ''give'':68 ''holi'':73 ''introduct'':9 ''introvert'':23 ''job'':14 ''lest'':84 ''line'':29 ''may'':64 ''modif'':6 ''neither'':77 ''pearl'':55,81 ''rend'':103 ''second'':34 ''see'':7 ''sens'':1 ''sometim'':15,20 ''swine'':49,51,83,89 ''tear'':45 ''third'':36 ''thus'':66 ''trampl'':53,90 ''turn'':96 ''unto'':74 ''would'':30,44,52 ''ye'':79', NULL, '936');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('974', '2', '974', NULL, 'nd the same sentiment was common among the Greeks, and deserves to be expressed in every language.', NULL, NULL, '''among'':7 ''common'':6 ''deserv'':11 ''everi'':16 ''express'':14 ''greek'':9 ''languag'':17 ''nd'':1 ''sentiment'':4', NULL, '936');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('118', '2', '118', NULL, 'A month had passed away since the setting up of the tabernacle Exodus 40:2, Exodus 40:17 : and the Sinaitic legislation was now complete (compare Leviticus 27:34).A census ("sum") was commanded, to be based not upon any fresh registration of individuals, but upon that which had accompanied the previous collection of the offerings. Compare Exodus 30:11, etc.; Exodus 38:25-28. The offerings had been probably tendered by the people in groups, and if certificates of registration were furnished to such groups, the new census might be easily carried out by means of these documents, and got through Numbers 1:18 in a single day. The present registration enrolled persons "after their families, by the house of their fathers;" and was superintended not by the Levites (see Exodus 38:21 and note), but by Numbers 1:4 an assessor for each tribe to act in the business with Moses and Aaron. The purpose now in view was not religious only. The census now taken would serve as a basis for various civil and military arrangements.', NULL, NULL, '''-28'':65 ''1'':104,140 ''11'':60 ''17'':18 ''18'':105 ''2'':15 ''21'':134 ''25'':64 ''27'':28 ''30'':59 ''34'':29 ''38'':63,133 ''4'':141 ''40'':14,17 ''aaron'':155 ''accompani'':50 ''act'':148 ''arrang'':179 ''assessor'':143 ''away'':5 ''base'':37 ''basi'':173 ''busi'':151 ''carri'':93 ''census'':31,89,166 ''certif'':79 ''civil'':176 ''collect'':53 ''command'':34 ''compar'':26,57 ''complet'':25 ''day'':109 ''document'':99 ''easili'':92 ''enrol'':113 ''etc'':61 ''exodus'':13,16,58,62,132 ''famili'':117 ''father'':123 ''fresh'':41 ''furnish'':83 ''got'':101 ''group'':76,86 ''hous'':120 ''individu'':44 ''legisl'':22 ''levit'':130 ''leviticus'':27 ''mean'':96 ''might'':90 ''militari'':178 ''month'':2 ''mose'':153 ''new'':88 ''note'':136 ''number'':103,139 ''offer'':56,67 ''pass'':4 ''peopl'':74 ''person'':114 ''present'':111 ''previous'':52 ''probabl'':70 ''purpos'':157 ''registr'':42,81,112 ''religi'':163 ''see'':131 ''serv'':170 ''set'':8 ''sinait'':21 ''sinc'':6 ''singl'':108 ''sum'':32 ''superintend'':126 ''tabernacl'':12 ''taken'':168 ''tender'':71 ''tribe'':146 ''upon'':39,46 ''various'':175 ''view'':160 ''would'':169', NULL, '118');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('56', '2', '56', NULL, 'There appears to have been an interval of some months between the preceding events and this renewal of the promise to Moses. The oppression in the meantime was not merely driving the people to desperation, but preparing them by severe labor, varied by hasty wanderings in search of stubble, for the exertions and privations of the wilderness. Hence, the formal and solemn character of the announcements in the whole chapter.Exodus 6:2I am the Lord ... - The meaning seems to be this: "I am Jehovah (Yahweh), and I appeared to Abraham, Isaac, and Jacob as El Shaddai, but as to my name Jehovah, I was not made known to them." In other words, the full import of that name was not disclosed to them. See Exodus 3:14.', NULL, NULL, '''14'':127 ''2i'':72 ''3'':126 ''6'':71 ''abraham'':90 ''announc'':66 ''appear'':2,88 ''chapter.exodus'':70 ''charact'':63 ''desper'':35 ''disclos'':121 ''drive'':31 ''el'':95 ''event'':14 ''exert'':52 ''exodus'':125 ''formal'':60 ''full'':114 ''hasti'':44 ''henc'':58 ''import'':115 ''interv'':7 ''isaac'':91 ''jacob'':93 ''jehovah'':84,102 ''known'':107 ''labor'':41 ''lord'':75 ''made'':106 ''mean'':77 ''meantim'':27 ''mere'':30 ''month'':10 ''mose'':22 ''name'':101,118 ''oppress'':24 ''peopl'':33 ''preced'':13 ''prepar'':37 ''privat'':54 ''promis'':20 ''renew'':17 ''search'':47 ''see'':124 ''seem'':78 ''sever'':40 ''shaddai'':96 ''solemn'':62 ''stubbl'':49 ''vari'':42 ''wander'':45 ''whole'':69 ''wilder'':57 ''word'':112 ''yahweh'':85', NULL, '56');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1016', '2', '1016', NULL, 'Herod the tetrarch - See also Mark 6:14-16; Luke 9:7-9. This was a son of Herod the Great. Herod the Great died probably in the first year after the birth of Christ, and left his kingdom to his three sons, of whom this "Herod Antipas" was one. He ruled over Galilee and Perea. See the notes at Matthew 2:15. The title "tetrarch" literally denotes one who rules over a "fourth" part of any country. It came, however, to signify the governor or ruler of any province subject to the Roman emperor - Robinson, Lexicon.Heard of the fame of Jesus - Jesus had been a considerable time engaged in the work of the ministry, and it may seem remarkable that he had not before heard of him. Herod might, however, have been absent on some expedition to a remote part of the country. It is to be remembered, also, that he was a man of much dissoluteness of morals, and that he paid little attention to the affairs of the people. He might have heard of Jesus before, but it had not arrested his attention. He did not think it a matter worthy of much regard.', NULL, NULL, '''-16'':9 ''-9'':13 ''14'':8 ''15'':63 ''2'':62 ''6'':7 ''7'':12 ''9'':11 ''absent'':134 ''affair'':169 ''also'':5,150 ''antipa'':48 ''arrest'':184 ''attent'':166,186 ''birth'':33 ''came'':80 ''christ'':35 ''consider'':107 ''countri'':78,144 ''denot'':68 ''die'':25 ''dissolut'':158 ''emperor'':95 ''engag'':109 ''expedit'':137 ''fame'':100 ''first'':29 ''fourth'':74 ''galile'':54 ''governor'':85 ''great'':21,24 ''heard'':126,176 ''herod'':1,19,22,47,129 ''howev'':81,131 ''jesus'':102,103,178 ''kingdom'':39 ''left'':37 ''lexicon.heard'':97 ''liter'':67 ''littl'':165 ''luke'':10 ''man'':155 ''mark'':6 ''matter'':193 ''matthew'':61 ''may'':118 ''might'':130,174 ''ministri'':115 ''moral'':160 ''much'':157,196 ''note'':59 ''one'':50,69 ''paid'':164 ''part'':75,141 ''peopl'':172 ''perea'':56 ''probabl'':26 ''provinc'':90 ''regard'':197 ''remark'':120 ''rememb'':149 ''remot'':140 ''robinson'':96 ''roman'':94 ''rule'':52,71 ''ruler'':87 ''see'':4,57 ''seem'':119 ''signifi'':83 ''son'':17,43 ''subject'':91 ''tetrarch'':3,66 ''think'':190 ''three'':42 ''time'':108 ''titl'':65 ''work'':112 ''worthi'':194 ''year'':30', NULL, '943');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('129', '2', '129', NULL, 'Miriam, as a prophetess (compare Exodus 15:20-21) no less than as the sister of Moses and Aaron, took the first rank among the women of Israel; and Aaron may be regarded as the ecclesiastical head of the whole nation. But instead of being grateful for these high dignities they challenged the special vocation of Moses and the exclusive authority which God had assigned to him. Miriam was the instigator, from the fact that her name stands conspicuously first Numbers 12:1, and that the punishment Numbers 12:10 fell on her alone. She probably considered herself as supplanted, and that too by a foreigner. Aaron was misled this time by the urgency of his sister, as once before Exodus 32 by that of the people.Numbers 12:1The Ethiopian woman whom he had married - (Hebrew, "Cushite," compare Genesis 2:13; Genesis 10:6) It is likely that Zipporah Exodus 2:21 was dead, and that Miriam in consequence expected to have greater influence than ever with Moses. Her disappointment at his second marriage would consequently be very great.The marriage of Moses with a woman descended from Ham was not prohibited, so long as she was not of the stock of Canaan (compare Exodus 34:11-16); but it would at any time have been offensive to that intense nationality which characterized the Jews. The Christian fathers note in the successive marriage of Moses with a Midianite and an Ethiopian a foreshadowing of the future extension to the Gentiles of God''s covenant and its promises (compare Psalm 45:9 ff; Sol 1:4 ff); and in the complaining of Miriam and Aaron a type of the discontent of the Jews because of such extension: compare Luke 15:29-30.', NULL, NULL, '''-16'':207 ''-21'':9 ''-30'':290 ''1'':83,263 ''10'':90,143 ''11'':206 ''12'':82,89,128 ''13'':141 ''15'':7,288 ''1the'':129 ''2'':140,151 ''20'':8 ''21'':152 ''29'':289 ''32'':122 ''34'':205 ''4'':264 ''45'':259 ''6'':144 ''9'':260 ''aaron'':19,30,107,273 ''alon'':94 ''among'':24 ''assign'':65 ''author'':61 ''canaan'':202 ''challeng'':52 ''character'':222 ''christian'':226 ''compar'':5,138,203,257,286 ''complain'':269 ''consequ'':159,176 ''consid'':97 ''conspicu'':79 ''coven'':253 ''cushit'':137 ''dead'':154 ''descend'':186 ''digniti'':50 ''disappoint'':170 ''discont'':278 ''ecclesiast'':36 ''ethiopian'':130,240 ''ever'':166 ''exclus'':60 ''exodus'':6,121,150,204 ''expect'':160 ''extens'':246,285 ''fact'':74 ''father'':227 ''fell'':91 ''ff'':261,265 ''first'':22,80 ''foreign'':106 ''foreshadow'':242 ''futur'':245 ''genesi'':139,142 ''gentil'':249 ''god'':63,251 ''grate'':46 ''great.the'':179 ''greater'':163 ''ham'':188 ''head'':37 ''hebrew'':136 ''high'':49 ''influenc'':164 ''instead'':43 ''instig'':71 ''intens'':219 ''israel'':28 ''jew'':224,281 ''less'':11 ''like'':147 ''long'':193 ''luke'':287 ''marri'':135 ''marriag'':174,180,232 ''may'':31 ''midianit'':237 ''miriam'':1,68,157,271 ''misl'':109 ''mose'':17,57,168,182,234 ''name'':77 ''nation'':41,220 ''note'':228 ''number'':81,88 ''offens'':216 ''people.numbers'':127 ''probabl'':96 ''prohibit'':191 ''promis'':256 ''prophetess'':4 ''psalm'':258 ''punish'':87 ''rank'':23 ''regard'':33 ''second'':173 ''sister'':15,117 ''sol'':262 ''special'':54 ''stand'':78 ''stock'':200 ''success'':231 ''supplant'':100 ''time'':111,213 ''took'':20 ''type'':275 ''urgenc'':114 ''vocat'':55 ''whole'':40 ''woman'':131,185 ''women'':26 ''would'':175,210 ''zipporah'':149', NULL, '129');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('130', '2', '130', NULL, 'A ruler - A comparison of the list with that of Numbers 13:1 :5 following shows that they were not the princes of the tribes, but heads of houses or families Numbers 12:4.Of the names here given those of Joshua and Caleb alone are otherwise known to us.', NULL, NULL, '''1'':13 ''12'':33 ''13'':12 ''4.of'':34 ''5'':14 ''alon'':44 ''caleb'':43 ''comparison'':4 ''famili'':31 ''follow'':15 ''given'':38 ''head'':27 ''hous'':29 ''joshua'':41 ''known'':47 ''list'':7 ''name'':36 ''number'':11,32 ''otherwis'':46 ''princ'':22 ''ruler'':2 ''show'':16 ''tribe'':25 ''us'':49', NULL, '130');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('131', '2', '131', NULL, 'Already Caleb had endeavored to still the people before Moses Numbers 13:30; already Moses himself (Deuteronomy 1:29 ff) had endeavored to recall the people to obedience. After the failure of these efforts Moses and Aaron cast themselves down in solemn prayer before God (compare Numbers 16:22); and the appearance of the glory of the Lord in the "tabernacle of the congregation" Numbers 14:10 was the immediate answer.', NULL, NULL, '''1'':18 ''10'':67 ''13'':12 ''14'':66 ''16'':48 ''22'':49 ''29'':19 ''30'':13 ''aaron'':37 ''alreadi'':1,14 ''answer'':71 ''appear'':52 ''caleb'':2 ''cast'':38 ''compar'':46 ''congreg'':64 ''deuteronomi'':17 ''effort'':34 ''endeavor'':4,22 ''failur'':31 ''ff'':20 ''glori'':55 ''god'':45 ''immedi'':70 ''lord'':58 ''mose'':10,15,35 ''number'':11,47,65 ''obedi'':28 ''peopl'':8,26 ''prayer'':43 ''recal'':24 ''solemn'':42 ''still'':6 ''tabernacl'':61', NULL, '131');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('132', '2', '132', NULL, 'The contents of the next five chapters must apparently be referred to the long period of wandering to which Numbers 14:33 the people were condemned.', NULL, NULL, '''14'':21 ''33'':22 ''appar'':9 ''chapter'':7 ''condemn'':26 ''content'':2 ''five'':6 ''long'':14 ''must'':8 ''next'':5 ''number'':20 ''peopl'':24 ''period'':15 ''refer'':11 ''wander'':17', NULL, '132');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('799', '2', '799', NULL, 'Thy prophets have seen vain and foolish things for thee - The Septuagint and Vulgate give the true meaning, "stupidity" (see Jeremiah 23:13 note).To turn away thy captivity - The right sense is, "They have not disclosed to thee thy sins, that so thou mightest repent, and I might have turned away thy captivity."Burdens - Applied contemptuously to predictions which proved "false" or "empty," i. e. failed of accomplishment. On the deduction to be drawn from this, see Jeremiah 28:9.Causes of banishment - The result of the teaching of the false prophets would be that God would "drive out" the Jews from their land.Some render the words "false ... banishment" by "oracles of falsehood and seduction."', NULL, NULL, '''13'':23 ''23'':22 ''28'':80 ''9.causes'':81 ''accomplish'':69 ''appli'':56 ''away'':27,52 ''banish'':83,109 ''burden'':55 ''captiv'':29,54 ''contemptu'':57 ''deduct'':72 ''disclos'':37 ''drawn'':75 ''drive'':98 ''e'':66 ''empti'':64 ''fail'':67 ''fals'':62,91,108 ''falsehood'':113 ''foolish'':7 ''give'':15 ''god'':96 ''jeremiah'':21,79 ''jew'':101 ''land.some'':104 ''mean'':18 ''might'':49 ''mightest'':45 ''note'':24 ''oracl'':111 ''predict'':59 ''prophet'':2,92 ''prove'':61 ''render'':105 ''repent'':46 ''result'':85 ''right'':31 ''seduct'':115 ''see'':20,78 ''seen'':4 ''sens'':32 ''septuagint'':12 ''sin'':41 ''stupid'':19 ''teach'':88 ''thee'':10,39 ''thi'':1,28,40,53 ''thing'':8 ''thou'':44 ''true'':17 ''turn'':26,51 ''vain'':5 ''vulgat'':14 ''word'':107 ''would'':93,97', NULL, '799');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('800', '2', '800', NULL, 'Is he turned; he turneth - Or, "surely against me" hath he turned "his hand" again and again "all the day long."', NULL, NULL, '''day'':20 ''hand'':14 ''hath'':10 ''long'':21 ''sure'':7 ''turn'':3,12 ''turneth'':5', NULL, '800');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('801', '2', '801', NULL, 'The stones of the sanctuary - Or, the hallowed stones, literally stones of holiness, a metaphor for the people themselves. The actual stones of the temple would not be thus widely thrown about as to be seen everywhere, but the prophet has already affirmed this of the young children dying of hunger (compare Lamentations 2:19).', NULL, NULL, '''19'':55 ''2'':54 ''actual'':21 ''affirm'':43 ''alreadi'':42 ''children'':48 ''compar'':52 ''die'':49 ''everywher'':37 ''hallow'':8 ''holi'':13 ''hunger'':51 ''lament'':53 ''liter'':10 ''metaphor'':15 ''peopl'':18 ''prophet'':40 ''sanctuari'':5 ''seen'':36 ''stone'':2,9,11,22 ''templ'':25 ''thrown'':31 ''thus'':29 ''wide'':30 ''would'':26 ''young'':47', NULL, '801');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('802', '2', '802', NULL, 'Turned - "transferred." The inheritance was the land of Canaan Leviticus 20:24.Aliens - Or, "foreigners:" i. e. the Chaldaeans upon their conquest of the country.', NULL, NULL, '''20'':11 ''24.aliens'':12 ''canaan'':9 ''chaldaean'':18 ''conquest'':21 ''countri'':24 ''e'':16 ''foreign'':14 ''inherit'':4 ''land'':7 ''leviticus'':10 ''transfer'':2 ''turn'':1 ''upon'':19', NULL, '802');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('803', '2', '803', NULL, 'The thirtieth year - being closely connected with as I, is rather in favor of considering this a personal date. It is not improbable that Ezekiel was called to his office at the age prescribed in the Law for Levites Numbers 4:23, Numbers 4:30, at which age both John the Baptist and our Lord began their ministry. His call is probably to be connected with the letter sent by Jeremiah to the captives Jeremiah 29 written a few months previously. Some reckon this date from the accession of Nabopolassar, father of Nebuchadnezzar, 625 b.c., and suppose that Ezekiel here gives a Babylonian, as in Ezekiel 1:2 a Jewish, date; but it is not certain that this accession formed an era in Babylon and Ezekiel does not elsewhere give a double date, or even a Babylonian date. Others date from the 18th year of Josiah, when Hilkiah discovered the Book of the Law (supposed to be a jubilee year): this would give 594 b.c. as the 30th year, but there is no other instance in Ezekiel of reckoning from this year.The captives - Not in confinement, but restricted to the place of their settlement.The fourth month - "Month" is not expressed in the original. This is the common method. Before the captivity the months were described not by proper names but by their order, "the first, the second," etc.; the first month corresponding nearly with our "April." After the captivity, the Jews brought back with them the proper names of the months, "Nisan" etc. (probably those used in Chaldaea).Chebar - The modern "Khabour" rises near Nisibis and flows into the Euphrates near "Kerkesiah," 200 miles north of Babylon.Visions of God - The exposition of the fundamental principles of the existence and nature of a Supreme God, and of the created angels, was called by the rabbis "the Matter of the Chariot" (compare 1 Chronicles 28:18) in reference to the form of Ezekiel''s vision of the Almighty; and the subject was deemed so mysterious as to call for special caution in its study. The vision must be compared with other manifestations of the divine glory Exodus 3; Exodus 24:10; Isaiah 6:1; Daniel 7:9; Revelation 4:2. Each of these visions has some of the outward signs or symbols here recorded. If we examine these symbols we shall find them to fall readily into two classes,(1) Those which we employ in common with the writers of all ages and countries. "Gold, sapphire, burnished brass," the "terrible crystal" are familiar images of majestic glory, "thunders, lightnings" and "the rushing storm" of awful power. But(2) We come to images to our minds strange and almost grotesque. That the "Four Living Creatures" had their groundwork in the cherubim there can be no doubt. And yet their shapes were very different. Because they were symbols not likenesses, they could yet be the same though their appearance was varied.Of what are they symbolic? They may, according to the Talmudists, have symbolized orders of Angels and not persons; according to others they were figures of the Four Gospels actuated by one spirit spread over the four quarters of the globe, upon which, as on pillars, the Church is borne up, and over whom the Word of God sits enthroned. The general scope of the vision gives the best interpretation of the meaning.Ezekiel saw "the likeness of the glory of God." Here His glory is manifested in the works of creation; and as light and fire, lightning and cloud, are the usual marks which in inanimate creation betoken the presence of God Psalm 18:6-14 - so the four living ones symbolize animate creation. The forms are typical, "the lion" and "the ox" of the beasts of the field (wild and tame), "the eagle" of the birds of the air, while "man" is the rational being supreme upon the earth. And the human type predominates over all, and gives character and unity to the four, who thus form one creation. Further, these four represent the constitutive parts of man''s nature: "the ox" (the animal of sacrifice), his faculty of suffering; "the lion" (the king of beasts), his faculty of ruling; "the eagle" (of keen eye and soaring wing), his faculty of imagination; "the man," his spiritual faculty, which actuates all the rest.Christ is the Perfect Man, so these four in their perfect harmony typify Him who came to earth to do His Father''s will; and as man is lord in the kingdom of nature, so is Christ Lord in the kingdom of grace. The "wings" represent the power by which all creation rises and falls at God''s will; the "one spirit," the unity and harmony of His works; the free motion in all directions, the universality of His Providence. The number "four" is the symbol of the world with its "four quarters;" the "veiled" bodies, the inability of all creatures to stand in the presence of God; the "noise of the wings," the testimony borne by creation to God Psalm 19:1-3; the "wheels" connect the vision with the earth, the wings with heaven, while above them is the throne of God in heaven. Since the eye of the seer is turned upward, the lines of the vision become less distinct. It ', NULL, NULL, '''-14'':602 ''-3'':842 ''1'':107,311,362,398,841 ''10'':359 ''18'':314,600 ''18th'':143 ''19'':840 ''2'':108,368,436 ''200'':273 ''23'':42 ''24'':358 ''28'':313 ''29'':76 ''3'':356 ''30'':45 ''30th'':168 ''4'':41,44,367 ''594'':164 ''6'':361,601 ''625'':94 ''7'':364 ''9'':365 ''access'':88,119 ''accord'':494,506 ''actuat'':516,716 ''age'':33,48,410 ''air'':636 ''almighti'':326 ''almost'':446 ''angel'':299,502 ''anim'':609,681 ''appear'':485 ''april'':236 ''aw'':433 ''b.c'':95,165 ''babylon'':124 ''babylon.visions'':277 ''babylonian'':103,137 ''back'':243 ''baptist'':52 ''beast'':622,693 ''becom'':879 ''began'':56 ''best'':555 ''betoken'':594 ''bird'':633 ''bodi'':814 ''book'':151 ''born'':536,834 ''brass'':416 ''brought'':242 ''burnish'':415 ''call'':27,60,301,336 ''came'':734 ''captiv'':74,183,211,239 ''ca