INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('804', '2', '804', NULL, 'Son of man - This phrase (which occurs elsewhere in Scripture) is applied especially to Ezekiel and Daniel, the prophets of the captivity. Ezekiel is thus reminded of his humanity, at the time when he is especially permitted to have contact with God.', NULL, NULL, '''appli'':12 ''captiv'':22 ''contact'':40 ''daniel'':17 ''elsewher'':8 ''especi'':13,36 ''ezekiel'':15,23 ''god'':42 ''human'':29 ''man'':3 ''occur'':7 ''permit'':37 ''phrase'':5 ''prophet'':19 ''remind'':26 ''scriptur'':10 ''son'':1 ''thus'':25 ''time'':32', NULL, '804');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('805', '2', '805', NULL, 'Before, there was a direct commission, now there is a symbolic action. John has the same vision (Revelation 10:8 ff), but there that is expressed, which is here left to be inferred, namely, that "as soon as he had eaten it his belly was bitter." The sweetness in the mouth denoted that it was good to be a messenger of the Lord (compare the margin reference), but the bitterness which accompanied it, denoted that the commission brought with it much sorrow.', NULL, NULL, '''10'':19 ''8'':20 ''accompani'':72 ''action'':12 ''belli'':44 ''bitter'':46,70 ''brought'':78 ''commiss'':6,77 ''compar'':64 ''denot'':52,74 ''direct'':5 ''eaten'':41 ''express'':26 ''ff'':21 ''good'':56 ''infer'':33 ''john'':13 ''left'':30 ''lord'':63 ''margin'':66 ''messeng'':60 ''mouth'':51 ''much'':81 ''name'':34 ''refer'':67 ''revel'':18 ''soon'':37 ''sorrow'':82 ''sweet'':48 ''symbol'':11 ''vision'':17', NULL, '805');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('806', '2', '806', NULL, 'A tile - Rather, a brick. Sun-dried or kiln-burned bricks were from very early times used for building walls throughout the plain of Mesopotamia. The bricks of Nineveh and Babylon are sometimes stamped with what appears to be the device of the king in whose reign they were made, and often covered with a kind of enamel on which various scenes are portrayed. Among the subjects depicted on such bricks discovered at Nimroud are castles and forts.', NULL, NULL, '''among'':67 ''appear'':39 ''babylon'':33 ''brick'':5,13,29,73 ''build'':21 ''burn'':12 ''castl'':78 ''cover'':55 ''depict'':70 ''devic'':43 ''discov'':74 ''dri'':8 ''earli'':17 ''enamel'':60 ''fort'':80 ''kiln'':11 ''kiln-burn'':10 ''kind'':58 ''king'':46 ''made'':52 ''mesopotamia'':27 ''nimroud'':76 ''nineveh'':31 ''often'':54 ''plain'':25 ''portray'':66 ''rather'':3 ''reign'':49 ''scene'':64 ''sometim'':35 ''stamp'':36 ''subject'':69 ''sun'':7 ''sun-dri'':6 ''throughout'':23 ''tile'':2 ''time'':18 ''use'':19 ''various'':63 ''wall'':22 ''whose'':48', NULL, '806');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('525', '2', '525', NULL, 'O clap your hands, all ye people - A common way of expressing joy, or indicating applause. Compare the notes at Isaiah 55:12. The "people" here referred to are probably the Jewish people, and the call on them is to rejoice, with the customary marks of joy, in view of the great victory which God had gained over their enemies.Shout unto God - Make a joyful noise in praise of God; that is, in acknowledgment that this victory has been gained by his interposition.With a voice of triumph - With such a shout as is usually raised when a victory is obtained; such a shout as occurs in a triumphal procession. Compare 2 Samuel 6:15; 1 Chronicles 15:28; Job 39:25; Zechariah 4:7; Exodus 32:18; Isaiah 12:6; Isaiah 42:11; Isaiah 44:23; Jeremiah 50:15. There are doubtless times when loud shouts, as expressive of joy, are proper.', NULL, NULL, '''1'':115 ''11'':133 ''12'':23,129 ''15'':114,117,139 ''18'':127 ''2'':111 ''23'':136 ''25'':121 ''28'':118 ''32'':126 ''39'':120 ''4'':123 ''42'':132 ''44'':135 ''50'':138 ''55'':22 ''6'':113,130 ''7'':124 ''acknowledg'':74 ''applaus'':16 ''call'':36 ''chronicl'':116 ''clap'':2 ''common'':9 ''compar'':17,110 ''customari'':44 ''doubtless'':142 ''enemies.shout'':60 ''exodus'':125 ''express'':12,148 ''gain'':57,80 ''god'':55,62,70 ''great'':52 ''hand'':4 ''indic'':15 ''interposition.with'':83 ''isaiah'':21,128,131,134 ''jeremiah'':137 ''jewish'':32 ''job'':119 ''joy'':13,47,65,150 ''loud'':145 ''make'':63 ''mark'':45 ''nois'':66 ''note'':19 ''o'':1 ''obtain'':100 ''occur'':105 ''peopl'':7,25,33 ''prais'':68 ''probabl'':30 ''process'':109 ''proper'':152 ''rais'':95 ''refer'':27 ''rejoic'':41 ''samuel'':112 ''shout'':91,103,146 ''time'':143 ''triumph'':87 ''triumphal'':108 ''unto'':61 ''usual'':94 ''victori'':53,77,98 ''view'':49 ''voic'':85 ''way'':10 ''ye'':6 ''zechariah'':122', NULL, '525');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('539', '2', '539', NULL, 'Hear my cry, O God - See the notes at Psalm 5:2. The word rendered cry in this place sometimes denotes a joyful shout - a shout of triumph; but the connection makes it certain that it here refers to the voice of prayer. It is implied that it was audible prayer, or that the psalmist gave utterance to his desires in words. It is language such as would be produced by deep distress; when a sad and burdened heart gives vent to its feelings in a loud cry for mercy.Attend unto my prayer - Give ear; incline the ear to me, Psalm 5:1; Psalm 17:1, Psalm 17:6; Psalm 39:12; Psalm 71:2.', NULL, NULL, '''1'':103,106 ''12'':112 ''17'':105,108 ''2'':12,115 ''39'':111 ''5'':11,102 ''6'':109 ''71'':114 ''audibl'':50 ''burden'':78 ''certain'':34 ''connect'':31 ''cri'':3,16,88 ''deep'':72 ''denot'':21 ''desir'':60 ''distress'':73 ''ear'':95,98 ''feel'':84 ''gave'':56 ''give'':80,94 ''god'':5 ''hear'':1 ''heart'':79 ''impli'':46 ''inclin'':96 ''joy'':23 ''languag'':65 ''loud'':87 ''make'':32 ''mercy.attend'':90 ''note'':8 ''o'':4 ''place'':19 ''prayer'':43,51,93 ''produc'':70 ''psalm'':10,101,104,107,110,113 ''psalmist'':55 ''refer'':38 ''render'':15 ''sad'':76 ''see'':6 ''shout'':24,26 ''sometim'':20 ''triumph'':28 ''unto'':91 ''utter'':57 ''vent'':81 ''voic'':41 ''word'':14,62 ''would'':68', NULL, '539');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('540', '2', '540', NULL, 'Truly - Indeed; really. The state of mind indicated by this particle is that of one who had been seriously contemplating a subject; who had looked round on his own actual condition; who had taken an estimate of all his resources, and of all his means of reliance, and who had carefully examined his own state of mind to see what was his real trust, and what were his real feelings toward God. Having done all this, he, at last, breaks out with the expression - "My soul does sincerely confide in God; I have no other resource; I have no power to meet my foes, and I am sure - my inmost soul testifies - that my real trust is, where it ought to be, in God; I see nothing in myself on which to rely; I see so much crime, falsehood, treachery in people, that I cannot confide in them; I have had so much painful experience of their insincerity and baseness that I cannot rely on them; but I do see that in God which leads me to trust in him, and I am sure that my heart truly does rely on him."My soul waiteth upon God - Margin, is silent. Septuagint, "Is not my soul subject to God?" So the Latin Vulgate. Luther, "My soul is still (calm) in God." The Hebrew word -   dumyah - means "silence, quiet, rest"; and then, a silent expectation or hope. The idea here is, "Truly toward God is the silent waiting of my soul"; that is, "In him alone do I trust; there is calmness of mind; I have no apprehension as to what can happen. My mind is at peace, for I feel that all is in the hands of God, and that lie is worthy of entire trust and confidence." The feeling is that which exists when we have entrusted all to God; when, having entire confidence in his power, his goodness, his wisdom, his mercy, we commit the whole case to him as if it were no longer our own. Such is the calmness - the peace - the quiet - the silence of the soul - when all is left with God. See the notes at Isaiah 26:3, and Philippians 4:6-7.From him cometh my salvation - That is, My safety is from him; my security is with him. It is true, also, that all that is ever implied in this word salvation, whether pertaining to this life or the life to come, is derived from God.', NULL, NULL, '''26'':363 ''3'':364 ''4'':367 ''6-7.from'':368 ''actual'':30 ''alon'':254 ''also'':388 ''apprehens'':266 ''base'':160 ''break'':80 ''calm'':218,260,342 ''cannot'':145,163 ''care'':51 ''case'':328 ''come'':408 ''cometh'':370 ''commit'':325 ''condit'':31 ''confid'':89,146,297,314 ''contempl'':20 ''crime'':138 ''deriv'':410 ''done'':74 ''dumyah'':224 ''entir'':294,313 ''entrust'':307 ''estim'':36 ''ever'':393 ''examin'':52 ''exist'':303 ''expect'':233 ''experi'':155 ''express'':84 ''falsehood'':139 ''feel'':70,279,299 ''foe'':104 ''god'':72,91,124,173,197,208,220,242,287,310,357,412 ''good'':319 ''hand'':285 ''happen'':271 ''heart'':187 ''hebrew'':222 ''hope'':235 ''idea'':237 ''impli'':394 ''inde'':2 ''indic'':8 ''inmost'':110 ''insincer'':158 ''isaiah'':362 ''last'':79 ''latin'':211 ''lead'':175 ''left'':355 ''lie'':290 ''life'':403,406 ''longer'':336 ''look'':25 ''luther'':213 ''margin'':198 ''mean'':45,225 ''meet'':102 ''merci'':323 ''mind'':7,57,262,273 ''much'':137,153 ''note'':360 ''noth'':127 ''one'':15 ''ought'':120 ''pain'':154 ''particl'':11 ''peac'':276,344 ''peopl'':142 ''pertain'':400 ''philippian'':366 ''power'':100,317 ''quiet'':227,346 ''real'':63,69,115 ''realli'':3 ''reli'':133,164,190 ''relianc'':47 ''resourc'':40,96 ''rest'':228 ''round'':26 ''safeti'':376 ''salvat'':372,398 ''secur'':381 ''see'':59,126,135,170,358 ''septuagint'':201 ''serious'':19 ''silenc'':226,348 ''silent'':200,232,245 ''sincer'':88 ''soul'':86,111,194,205,215,249,351 ''state'':5,55 ''still'':217 ''subject'':22,206 ''sure'':108,184 ''taken'':34 ''testifi'':112 ''toward'':71,241 ''treacheri'':140 ''true'':387 ''truli'':1,188,240 ''trust'':64,116,178,257,295 ''upon'':196 ''vulgat'':212 ''wait'':246 ''waiteth'':195 ''whether'':399 ''whole'':327 ''wisdom'':321 ''word'':223,397 ''worthi'':292', NULL, '540');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('542', '2', '542', NULL, 'Hear my voice, O God, in my prayer - The use of the word voice here would seem to imply that this was audible prayer, or that, though alone, he gave utterance to his petitions aloud. We have this same use of the word often in the Psalms, making it probable that even private prayers were uttered in an audible manner. In most cases, when there is no danger of being overheard, or of its being construed as ostentation or Pharisaism, this is favorable to the spirit of secret devotion. Compare the notes at Daniel 6:10. The word here rendered prayer means properly speech, discourse; then, complaint; then, meditation. It is most commonly rendered complaint. See Job 7:13; Job 9:27; Job 10:1; Job 21:4; Psalm 55:2 (notes); Psalm 102 (Title); Psalm 142:2. It refers here to a state of mind caused by trouble and danger, when the deep meditation on his troubles and dangers found expression in audible words - whether those words were complaint or petition. As there are no indications in the psalm that David was disposed to complain in the sense of blaming God, the proper interpretation here is that his deep meditations took the form of prayer.Preserve my life from fear of the enemy - Either Saul or Absalom. He prayed that his life might be made so secure that he would not have occasion to be afraid of his enemy.', NULL, NULL, '''1'':125 ''10'':96,124 ''102'':134 ''13'':119 ''142'':137 ''2'':131,138 ''21'':127 ''27'':122 ''4'':128 ''55'':130 ''6'':95 ''7'':118 ''9'':121 ''absalom'':217 ''afraid'':236 ''alon'':28 ''aloud'':35 ''audibl'':23,59,164 ''blame'':191 ''case'':63 ''caus'':147 ''common'':113 ''compar'':90 ''complain'':186 ''complaint'':107,115,170 ''constru'':76 ''danger'':68,151,160 ''daniel'':94 ''david'':182 ''deep'':154,200 ''devot'':89 ''discours'':105 ''dispos'':184 ''either'':214 ''enemi'':213,239 ''even'':52 ''express'':162 ''favor'':83 ''fear'':210 ''form'':204 ''found'':161 ''gave'':30 ''god'':5,192 ''hear'':1 ''impli'':19 ''indic'':177 ''interpret'':195 ''job'':117,120,123,126 ''life'':208,222 ''made'':225 ''make'':48 ''manner'':60 ''mean'':102 ''medit'':109,155,201 ''might'':223 ''mind'':146 ''note'':92,132 ''o'':4 ''occas'':233 ''often'':44 ''ostent'':78 ''overheard'':71 ''petit'':34,172 ''pharisa'':80 ''pray'':219 ''prayer'':8,24,54,101 ''prayer.preserve'':206 ''privat'':53 ''probabl'':50 ''proper'':103,194 ''psalm'':47,129,133,136,180 ''refer'':140 ''render'':100,114 ''saul'':215 ''secret'':88 ''secur'':227 ''see'':116 ''seem'':17 ''sens'':189 ''speech'':104 ''spirit'':86 ''state'':144 ''though'':27 ''titl'':135 ''took'':202 ''troubl'':149,158 ''use'':10,40 ''utter'':31,56 ''voic'':3,14 ''whether'':166 ''word'':13,43,98,165,168 ''would'':16,230', NULL, '542');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('818', '2', '818', NULL, 'Idolatry is frequently represented by the prophets under the figure of a wife''s unfaithfulness to her husband. This image is here so portrayed, as to exhibit the aggravation of Israel''s guilt by reason of her origin and early history. The original abode of the progenitors of the race was the land of Canaan, defiled with idolatry and moral corruption. Israel itself was like a child born in a polluted land, abandoned from its birth, left by its parents in the most utter neglect to the chance regard of any passer-by. Such was the state of the people in Egypt Ezekiel 16:3-5. On such a child the Lord looked with pity, tended, and adopted it. Under His care it grew up to be comely and beautiful, and the Lord joined it to Himself in that close union, which is figured by the bonds of wedlock. The covenants made under Moses and Joshua represent this alliance Ezekiel 16:6-8. In the reigns of David and Solomon, Israel shone with all the glory of temporal prosperity Ezekiel 16:9-14. The remainder of the history of the people when divided is, in the prophet''s eye, a succession of defection and degradation marked by the erection of high places Ezekiel 16:16-20; by unholy alliances with foreign nations Ezekiel 16:26-33. Such sins were soon to meet their due punishment. As an unfaithful wife was brought before the people, convicted, and stoned, so should the Lord make His people a gazing-stock to all the nations round about, deprive them of all their possessions and of their city, and cast them forth as exiles to be spoiled and destroyed in a foreign land Ezekiel 16:35-43.', NULL, NULL, '''-14'':184 ''-20'':217 ''-33'':227 ''-43'':294 ''-5'':107 ''-8'':164 ''16'':105,162,182,215,216,225,292 ''26'':226 ''3'':106 ''35'':293 ''6'':163 ''9'':183 ''abandon'':73 ''abod'':44 ''adopt'':119 ''aggrav'':29 ''allianc'':160,220 ''be