INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('819', '2', '819', NULL, 'Ezekiel, after describing by a figure the circumstances and conditions of the Jews and Zedekiah, the vassal of the Assyrian monarch, warns them of the delusive character of their hopes of help from Egypt, protests against the perfidy which must accompany such alliance, and points out that the restoration of the people of God will be effected by a very different son of David. The close of this chapter is a striking prediction of the kingdom of the Messiah.', NULL, NULL, '''accompani'':41 ''allianc'':43 ''assyrian'':20 ''chapter'':69 ''charact'':27 ''circumst'':8 ''close'':66 ''condit'':10 ''david'':64 ''delus'':26 ''describ'':3 ''differ'':61 ''effect'':57 ''egypt'':34 ''ezekiel'':1 ''figur'':6 ''god'':54 ''help'':32 ''hope'':30 ''jew'':13 ''kingdom'':76 ''messiah'':79 ''monarch'':21 ''must'':40 ''peopl'':52 ''perfidi'':38 ''point'':45 ''predict'':73 ''protest'':35 ''restor'':49 ''son'':62 ''strike'':72 ''vassal'':17 ''warn'':22 ''zedekiah'':15', NULL, '819');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('820', '2', '820', NULL, 'The last verse of Ezekiel 17 gives occasion for a declaration of the principle upon which God''s providential dispensations proceed, namely, that every individual shall be equitably dealt with - a principle that precludes the children from either presuming on the father''s merits or despairing on account of the father''s guilt. This chapter is an enlargement of Jeremiah 31:29, and sets forth fully the doctrine of individual responsibility.', NULL, NULL, '''17'':6 ''29'':62 ''31'':61 ''account'':48 ''chapter'':55 ''children'':36 ''dealt'':29 ''declar'':11 ''despair'':46 ''dispens'':20 ''doctrin'':68 ''either'':38 ''enlarg'':58 ''equit'':28 ''everi'':24 ''ezekiel'':5 ''father'':42,51 ''forth'':65 ''fulli'':66 ''give'':7 ''god'':17 ''guilt'':53 ''individu'':25,70 ''jeremiah'':60 ''last'':2 ''merit'':44 ''name'':22 ''occas'':8 ''preclud'':34 ''presum'':39 ''principl'':14,32 ''proceed'':21 ''providenti'':19 ''respons'':71 ''set'':64 ''shall'':26 ''upon'':15 ''vers'':3', NULL, '820');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('821', '2', '821', NULL, 'Princes of Israel - Israel is the whole nation over which the king of Judah was the rightful sovereign. Compare Ezekiel 2:3; Ezekiel 3:1, Ezekiel 3:7.', NULL, NULL, '''1'':25 ''2'':21 ''3'':22,24,27 ''7'':28 ''compar'':19 ''ezekiel'':20,23,26 ''israel'':3,4 ''judah'':14 ''king'':12 ''nation'':8 ''princ'':1 ''right'':17 ''sovereign'':18 ''whole'':7', NULL, '821');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('822', '2', '822', NULL, 'The elders of Israel - These were as in Ezekiel 14:1, some of Ezekiel''s fellow-exiles, designated in general terms by the name of Israel, though more properly belonging to the kingdom of Judah.', NULL, NULL, '''1'':11 ''14'':10 ''belong'':31 ''design'':19 ''elder'':2 ''exil'':18 ''ezekiel'':9,14 ''fellow'':17 ''fellow-exil'':16 ''general'':21 ''israel'':4,27 ''judah'':36 ''kingdom'':34 ''name'':25 ''proper'':30 ''term'':22 ''though'':28', NULL, '822');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('823', '2', '823', NULL, 'The first word of judgment Ezekiel 21:1-7. Ezekiel speaks first to the people of Israel, shows the universality of the coming destructions, and indicates by a sign (that of sighing) the sadness of the calamity.The words and order of words are identical with Ezekiel 20:45-46, except that for "south," there are substituted:(1) "Jerusalem;"(2) "the holy place," i. e., the temple and its various parts;(3) "the land of Israel."No subterfuge is left for the people to pretend misunderstanding.', NULL, NULL, '''-46'':49 ''-7'':9 ''1'':8,57 ''2'':59 ''20'':47 ''21'':7 ''3'':71 ''45'':48 ''calamity.the'':37 ''come'':23 ''destruct'':24 ''e'':64 ''except'':50 ''ezekiel'':6,10,46 ''first'':2,12 ''holi'':61 ''ident'':44 ''indic'':26 ''israel'':17,75 ''jerusalem'':58 ''judgment'':5 ''land'':73 ''left'':79 ''misunderstand'':85 ''order'':40 ''part'':70 ''peopl'':15,82 ''place'':62 ''pretend'':84 ''sad'':34 ''show'':18 ''sigh'':32 ''sign'':29 ''south'':53 ''speak'':11 ''substitut'':56 ''subterfug'':77 ''templ'':66 ''univers'':20 ''various'':69 ''word'':3,38,42', NULL, '823');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('824', '2', '824', NULL, 'The fourth word of judgment Ezekiel 22:1-16. The sins which have brought ruin upon Jerusalem are the sins which disgraced the pagan inhabitants of Canaan, whom the Israelites were to cast out (compare Leviticus 18). The commission of like sins would insure like judgment.', NULL, NULL, '''-16'':9 ''1'':8 ''18'':37 ''22'':7 ''brought'':14 ''canaan'':27 ''cast'':33 ''commiss'':39 ''compar'':35 ''disgrac'':22 ''ezekiel'':6 ''fourth'':2 ''inhabit'':25 ''insur'':44 ''israelit'':30 ''jerusalem'':17 ''judgment'':5,46 ''leviticus'':36 ''like'':41,45 ''pagan'':24 ''ruin'':15 ''sin'':11,20,42 ''upon'':16 ''word'':3 ''would'':43', NULL, '824');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('825', '2', '825', NULL, 'Aholah ... and Aholibah - More correctly "Oholah" ("her own tent or tabernacle") and "Oholibah" ("My tent or tabernacle is in her"): names chosen to express that after the division Israel set up her own tabernacle in the place of the temple in which God dwelt 1 Kings 12:32, while with Judah the Temple of God still remained. The presence of God aggravated Judah''s sins. In the times of the captivity it was customary among the Jews to give their children names connected with the temple or tabernacle.', NULL, NULL, '''1'':45 ''12'':47 ''32'':48 ''aggrav'':62 ''aholah'':1 ''aholibah'':3 ''among'':75 ''captiv'':71 ''children'':81 ''chosen'':22 ''connect'':83 ''correct'':5 ''customari'':74 ''divis'':28 ''dwelt'':44 ''express'':24 ''give'':79 ''god'':43,55,61 ''israel'':29 ''jew'':77 ''judah'':51,63 ''king'':46 ''name'':21,82 ''oholah'':6 ''oholibah'':13 ''place'':37 ''presenc'':59 ''remain'':57 ''set'':30 ''sin'':65 ''still'':56 ''tabernacl'':11,17,34,88 ''templ'':40,53,86 ''tent'':9,15 ''time'':68', NULL, '825');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('826', '2', '826', NULL, 'The prophecies in this chapter were delivered two years and five months after those of the previous section Ezekiel 20:1. The day mentioned here was the very day on which Nebuchadnezzar completed his arrangements for the siege, and closed in the city (marginal references). After the captivity this day was regularly observed as a fast day Zechariah 8:19.', NULL, NULL, '''1'':21 ''19'':60 ''20'':20 ''8'':59 ''arrang'':35 ''captiv'':48 ''chapter'':5 ''citi'':43 ''close'':40 ''complet'':33 ''day'':23,29,50,57 ''deliv'':7 ''ezekiel'':19 ''fast'':56 ''five'':11 ''margin'':44 ''mention'':24 ''month'':12 ''nebuchadnezzar'':32 ''observ'':53 ''previous'':17 ''propheci'':2 ''refer'':45 ''regular'':52 ''section'':18 ''sieg'':38 ''two'':8 ''year'':9 ''zechariah'':58', NULL, '826');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('543', '2', '543', NULL, 'Praise waiteth for thee, O God, in Sion - That is, all the arrangements are made; the people are assembled; their hearts are prepared to praise thee. The fact that Zion is mentioned here as the seat of praise would seem to imply that this psalm was composed before the building of the temple, contrary to the opinion of DeWette and others, as noticed in the Introduction to the psalm, for after the building of the temple the seat of worship was transferred from Mount Zion, where David had placed the ark and prepared a tent for it 1 Chronicles 15:1; 1 Chronicles 16:1; 2 Chronicles 1:4, to Mount Moriah. It is true that the general name Zion was given familiarly to Jerusalem as a city, but it is also true that the particular place for the worship of God in the time of David was Mount Zion strictly so called. See the notes at Psalm 2:6. The margin in this place is, "Praise is silent." The Hebrew is, "To thee is silence-praise," - a kind of compound phrase, not meaning "silent praise," but referring to a condition where everything is ready; where the preparations have been entirely made; where the noise usually attendant on preparation has ceased, and all is in readiness as if waiting for that for which the arrangements had been carried forward. The noise of building - of preparation - was now hushed, and all was calm. The language here would also denote the state of feeling in an individual or an assembly, when the heart was prepared for praise; when it was filled with a deep sense of the majesty and goodness of God; when all feelings of anxiety were calmed down, or were in a state of rest; when the soul was ready to burst forth in expressions of thanksgiving, and nothing would meet its needs but praise.And unto thee shall the vow be performed - See Psalm 22:25, note; Psalm 50:14, note; Psalm 56:12, note. The reference here is to the vows or promises which the people had made in view of the manifested judgments of God and the proofs of his goodness. Those vows they were now ready to carry out in expressions of praise.', NULL, NULL, '''1'':98,101,102,105,108 ''12'':335 ''14'':331 ''15'':100 ''16'':104 ''2'':106,159 ''22'':326 ''25'':327 ''4'':109 ''50'':330 ''56'':334 ''6'':160 ''also'':132,248 ''anxieti'':286 ''ark'':91 ''arrang'':13,226 ''assembl'':19,259 ''attend'':208 ''build'':50,73,234 ''burst'':303 ''call'':153 ''calm'':243,288 ''carri'':229,372 ''ceas'':212 ''chronicl'':99,103,107 ''citi'':128 ''compos'':47 ''compound'':182 ''condit'':192 ''contrari'':54 ''david'':87,147 ''deep'':273 ''denot'':249 ''dewett'':59 ''entir'':202 ''everyth'':194 ''express'':306,375 ''fact'':28 ''familiar'':123 ''feel'':253,284 ''fill'':270 ''forth'':304 ''forward'':230 ''general'':118 ''given'':122 ''god'':6,142,281,358 ''good'':279,364 ''heart'':21,262 ''hebrew'':171 ''hush'':239 ''impli'':42 ''individu'':256 ''introduct'':66 ''jerusalem'':125 ''judgment'':356 ''kind'':180 ''languag'':245 ''made'':15,203,350 ''majesti'':277 ''manifest'':355 ''margin'':162 ''mean'':185 ''meet'':312 ''mention'':32 ''moriah'':112 ''mount'':84,111,149 ''name'':119 ''need'':314 ''nois'':206,232 ''note'':156,328,332,336 ''noth'':310 ''notic'':63 ''o'':5 ''opinion'':57 ''other'':61 ''particular'':136 ''peopl'':17,348 ''perform'':323 ''phrase'':183 ''place'':89,137,165 ''prais'':1,25,38,167,178,187,266,377 ''praise.and'':316 ''prepar'':23,93,199,210,236,264 ''promis'':345 ''proof'':361 ''psalm'':45,69,158,325,329,333 ''readi'':196,217,301,370 ''refer'':189,338 ''rest'':296 ''seat'':36,78 ''see'':154,324 ''seem'':40 ''sens'':274 ''shall'':319 ''silenc'':177 ''silence-prais'':176 ''silent'':169,186 ''sion'':8 ''soul'':299 ''state'':251,294 ''strict'':151 ''templ'':53,76 ''tent'':95 ''thanksgiv'':308 ''thee'':4,26,174,318 ''time'':145 ''transfer'':82 ''true'':115,133 ''unto'':317 ''usual'':207 ''view'':352 ''vow'':321,343,366 ''wait'':220 ''waiteth'':2 ''worship'':80,140 ''would'':39,247,311 ''zion'':30,85,120,150', NULL, '543');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('834', '2', '834', NULL, 'In the twelfth month - About one year and seven months after the destruction of Jerusalem. In the meantime had occurred the murder of Gedaliah and the flight into Egypt of the Jews left behind by the Chaldaeans Jeremiah 41-43. Jeremiah, who had accompanied them, foretold their ruin Jeremiah 44 in a prophecy probably contemporaneous with the present - the sixth against Egypt, delivered in the form of a dirge Ezekiel 44:2-16.', NULL, NULL, '''-16'':73 ''-43'':40 ''2'':72 ''41'':39 ''44'':50,71 ''accompani'':44 ''behind'':34 ''chaldaean'':37 ''contemporan'':55 ''deliv'':63 ''destruct'':13 ''dirg'':69 ''egypt'':29,62 ''ezekiel'':70 ''flight'':27 ''foretold'':46 ''form'':66 ''gedaliah'':24 ''jeremiah'':38,41,49 ''jerusalem'':15 ''jew'':32 ''left'':33 ''meantim'':18 ''month'':4,10 ''murder'':22 ''occur'':20 ''one'':6 ''present'':58 ''probabl'':54 ''propheci'':53 ''ruin'':48 ''seven'':9 ''sixth'':60 ''twelfth'':3 ''year'':7', NULL, '834');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('544', '2', '544', NULL, 'Make a joyful noise unto God - literally, "Shout." It is a call for exultation and praise.All ye lands - Margin, as in Hebrew, all the earth. The occasion was one that made universal exultation and praise proper. They who had been so deeply affected by the gracious interposition of God, could not but call on all the nations of the earth to unite with them in the expression of joy. The deliverance was so great that they wished all to rejoice with them (compare Luke 15:6, Luke 15:9); and the intervention of God in the case of his people, furnished lessons about his character which gave occasion to all men to rejoice.', NULL, NULL, '''15'':85,88 ''6'':86 ''9'':89 ''affect'':43 ''call'':12,53 ''case'':97 ''charact'':105 ''compar'':83 ''could'':50 ''deepli'':42 ''deliver'':71 ''earth'':25,60 ''express'':67 ''exult'':14,33 ''furnish'':101 ''gave'':107 ''god'':6,49,94 ''gracious'':46 ''great'':74 ''hebrew'':22 ''interposit'':47 ''intervent'':92 ''joy'':3,69 ''land'':18 ''lesson'':102 ''liter'':7 ''luke'':84,87 ''made'':31 ''make'':1 ''margin'':19 ''men'':111 ''nation'':57 ''nois'':4 ''occas'':27,108 ''one'':29 ''peopl'':100 ''prais'':35 ''praise.all'':16 ''proper'':36 ''rejoic'':80,113 ''shout'':8 ''unit'':62 ''univers'':32 ''unto'':5 ''wish'':77 ''ye'':17', NULL, '544');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('835', '2', '835', NULL, 'The date shows an interval of 112 years from the taking of Jerusalem Jeremiah 52:12. The general news that the city was taken must have reached them, but it was only when the messenger arrived that the prophet''s mouth was opened. It is not improbable that a body of men after the destruction of the city joined their brethren in Chaldaea; if so this would account for the lapse of time, and supply a reason why Ezekiel on their arrival should commence a new series of prophecies.', NULL, NULL, '''112'':7 ''12'':16 ''52'':15 ''account'':68 ''arriv'':36,82 ''bodi'':50 ''brethren'':61 ''chaldaea'':63 ''citi'':22,58 ''commenc'':84 ''date'':2 ''destruct'':55 ''ezekiel'':79 ''general'':18 ''improb'':47 ''interv'':5 ''jeremiah'':14 ''jerusalem'':13 ''join'':59 ''laps'':71 ''men'':52 ''messeng'':35 ''mouth'':41 ''must'':25 ''new'':86 ''news'':19 ''open'':43 ''propheci'':89 ''prophet'':39 ''reach'':27 ''reason'':77 ''seri'':87 ''show'':3 ''suppli'':75 ''take'':11 ''taken'':24 ''time'':73 ''would'':67 ''year'':8', NULL, '835');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('836', '2', '836', NULL, 'The prophet has yet to pronounce a judgment upon unfaithful rulers, whose punishment will further the good of those whom they have misguided. He shows what the rulers should have been, what they have been, and what in the coming times they shall be when the True King shall reign in the true kingdom. Hence, follows a description of Messiah''s reign.', NULL, NULL, '''come'':40 ''descript'':58 ''follow'':56 ''good'':17 ''henc'':55 ''judgment'':8 ''king'':48 ''kingdom'':54 ''messiah'':60 ''misguid'':23 ''pronounc'':6 ''prophet'':2 ''punish'':13 ''reign'':50,62 ''ruler'':11,28 ''shall'':43,49 ''show'':25 ''time'':41 ''true'':47,53 ''unfaith'':10 ''upon'':9 ''whose'':12 ''yet'':4', NULL, '836');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('837', '2', '837', NULL, 'In Ezekiel 35-36 we see the devastation of Edom, and the restoration of Israel. Edom was included among the nations against which Ezekiel prophesied Ezekiel 25:12-14. But its fuller doom was reserved for this place, because Edom was one of the surrounding nations that profited at first by Judah''s fall, and because it helps by way of contrast to bring out in a marked way the better future designed for Israel. Edom is the God-hating, God-opposing power, ever distinguished for its bitter hatred against Israel; and so the ruin of Edom is the triumph of Israel in the power of God.', NULL, NULL, '''-14'':29 ''-36'':4 ''12'':28 ''25'':27 ''35'':3 ''among'':19 ''better'':71 ''bitter'':90 ''bring'':64 ''contrast'':62 ''design'':73 ''devast'':8 ''distinguish'':87 ''doom'':33 ''edom'':10,16,40,76,99 ''ever'':86 ''ezekiel'':2,24,26 ''fall'':54 ''first'':50 ''fuller'':32 ''futur'':72 ''god'':80,83,109 ''god-hat'':79 ''god-oppos'':82 ''hate'':81 ''hatr'':91 ''help'':58 ''includ'':18 ''israel'':15,75,93,104 ''judah'':52 ''mark'':68 ''nation'':21,46 ''one'':42 ''oppos'':84 ''place'':38 ''power'':85,107 ''profit'':48 ''prophesi'':25 ''reserv'':35 ''restor'':13 ''ruin'':97 ''see'':6 ''surround'':45 ''triumph'':102 ''way'':60,69', NULL, '837');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('838', '2', '838', NULL, 'The residue of the pagan - Those of the surrounding nations which had survived Jerusalem''s fall, and may have profited by it.', NULL, NULL, '''fall'':16 ''jerusalem'':14 ''may'':18 ''nation'':10 ''pagan'':5 ''profit'':20 ''residu'':2 ''surround'':9 ''surviv'':13', NULL, '838');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('839', '2', '839', NULL, 'The valley - The same word as "the plain" Ezekiel 3:22; Ezekiel 8:4. The "dry bones" represented the Israelites dispersed abroad, destitute of life national and spiritual.', NULL, NULL, '''22'':11 ''3'':10 ''4'':14 ''8'':13 ''abroad'':22 ''bone'':17 ''destitut'':23 ''dispers'':21 ''dri'':16 ''ezekiel'':9,12 ''israelit'':20 ''life'':25 ''nation'':26 ''plain'':8 ''repres'':18 ''spiritu'':28 ''valley'':2 ''word'':5', NULL, '839');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('840', '2', '840', NULL, 'The last conflict of the world with God, and the complete overthrow of the former. This section Ezekiel 38-39 refers to times subsequent to the restoration of Israel. As the Church (the true Israel) waxes stronger and stronger, more distant nations will come into collision and must be overthrown before the triumph is complete. Some have thought that this prophecy is directed against the Scythians who had possession of Asia twenty-three years, and in the course of this time had overrun Syria, and had probably made their appearance in the holy land. But in this prophecy there is little distinctive of one nation. It is a gathering together of the enemies of Yahweh to make their last effort, and to be overthrown. The seer passes to the final struggle between Good and Evil, and the triumphant establishment of the divine rule. It is the same struggle which is depicted in the Book of Revelation EZechariah 20:7-10, where John adopts words and phrases of Ezekiel.There are four main divisions of this prophecy:-1Eze 38:1-13, describing Gog''s march;-2Eze 38:14-23, describing his punishment;(3) Ezekiel 39:1-16, describing his ruin;-4Eze 39:17-29, the issue of Gog''s ruin in Israel''s redemption and sanctification.Each division is broken up like a poem into stanzas.', NULL, NULL, '''-1'':177 ''-10'':161 ''-13'':181 ''-16'':198 ''-2'':186 ''-23'':190 ''-29'':206 ''-39'':20 ''-4'':202 ''1'':180,197 ''14'':189 ''17'':205 ''20'':159 ''3'':194 ''38'':19,179,188 ''39'':196,204 ''7'':160 ''adopt'':164 ''appear'':91 ''asia'':71 ''book'':155 ''broken'':221 ''church'':32 ''collis'':46 ''come'':44 ''complet'':11,55 ''conflict'':3 ''cours'':79 ''depict'':152 ''describ'':182,191,199 ''direct'':63 ''distant'':41 ''distinct'':103 ''divin'':143 ''divis'':173,219 ''effort'':121 ''enemi'':114 ''establish'':140 ''evil'':136 ''eze'':178,187,203 ''ezechariah'':158 ''ezekiel'':18,195 ''ezekiel.there'':169 ''final'':131 ''former'':15 ''four'':171 ''gather'':110 ''god'':8 ''gog'':183,210 ''good'':134 ''holi'':94 ''israel'':29,35,214 ''issu'':208 ''john'':163 ''land'':95 ''last'':2,120 ''like'':223 ''littl'':102 ''made'':89 ''main'':172 ''make'':118 ''march'':185 ''must'':48 ''nation'':42,106 ''one'':105 ''overrun'':84 ''overthrow'':12 ''overthrown'':50,125 ''pass'':128 ''phrase'':167 ''poem'':225 ''possess'':69 ''probabl'':88 ''propheci'':61,99,176 ''punish'':193 ''redempt'':216 ''refer'':21 ''restor'':27 ''revel'':157 ''ruin'':201,212 ''rule'':144 ''sanctification.each'':218 ''scythian'':66 ''section'':17 ''seer'':127 ''stanza'':227 ''stronger'':37,39 ''struggl'':132,149 ''subsequ'':24 ''syria'':85 ''thought'':58 ''three'':74 ''time'':23,82 ''togeth'':111 ''triumph'':53 ''triumphant'':139 ''true'':34 ''twenti'':73 ''twenty-thre'':72 ''wax'':36 ''word'':165 ''world'':6 ''yahweh'':116 ''year'':75', NULL, '840');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('841', '2', '841', NULL, 'The present chapter describes the defeat of Evil and the triumph of God and His people. As the prophet predicted the advance of Evil under the figure of the invasion of an actual army; so he declares the overthrow of Evil by the figure of a host routed and slain, and the consequent purification of a land, partially overrun and disturbed. Some forgetting that this is a figure, have searched history to find out some campaign in the land of Israel, some overthrow of invaders, on which to fix this prophecy, and have assigned localities to the burial-place "Hamon-Gog" Ezekiel 39:11.', NULL, NULL, '''11'':106 ''39'':105 ''actual'':33 ''advanc'':22 ''armi'':34 ''assign'':94 ''burial'':99 ''burial-plac'':98 ''campaign'':76 ''chapter'':3 ''consequ'':53 ''declar'':37 ''defeat'':6 ''describ'':4 ''disturb'':61 ''evil'':8,24,41 ''ezekiel'':104 ''figur'':27,44,68 ''find'':73 ''fix'':89 ''forget'':63 ''god'':13 ''gog'':103 ''hamon'':102 ''hamon-gog'':101 ''histori'':71 ''host'':47 ''invad'':85 ''invas'':30 ''israel'':81 ''land'':57,79 ''local'':95 ''overrun'':59 ''overthrow'':39,83 ''partial'':58 ''peopl'':16 ''place'':100 ''predict'':20 ''present'':2 ''propheci'':91 ''prophet'':19 ''purif'':54 ''rout'':48 ''search'':70 ''slain'':50 ''triumph'':11', NULL, '841');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('842', '2', '842', NULL, 'In the first and twentieth year - This was the fiftieth year from the 18th of Josiah, the year of his memorable Passover 2 Kings 23:22. See the Ezekiel 1:1 note. If that was a jubilee year, which is highly probable, this vision also falls in a jubilee year, which seems appropriate. The jubilee year began with the month of Tisri, a sufficient reason for speaking of the time as "the beginning of the year." The tenth day of this month was the day of atonement Leviticus 16:29-30.', NULL, NULL, '''-30'':91 ''1'':30,31 ''16'':89 ''18th'':14 ''2'':23 ''22'':26 ''23'':25 ''29'':90 ''also'':45 ''appropri'':53 ''aton'':87 ''began'':57 ''begin'':73 ''day'':79,85 ''ezekiel'':29 ''fall'':46 ''fiftieth'':10 ''first'':3 ''high'':41 ''josiah'':16 ''jubile'':37,49,55 ''king'':24 ''leviticus'':88 ''memor'':21 ''month'':60,82 ''note'':32 ''passov'':22 ''probabl'':42 ''reason'':65 ''see'':27 ''seem'':52 ''speak'':67 ''suffici'':64 ''tenth'':78 ''time'':70 ''tisri'':62 ''twentieth'':5 ''vision'':44 ''year'':6,11,18,38,50,56,76', NULL, '842');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('57', '2', '57', NULL, 'With this chapter begins the series of miracles performed in Egypt. They are progressive. The first miracle is performed to accredit the mission of the brothers; it is simply credential, and unaccompanied by any infliction. Then come signs which show that the powers of nature are subject to the will of Yahweh, each plague being attended with grave consequences to the Egyptians, yet not inflicting severe loss or suffering; then in rapid succession come ruinous and devastating plagues, murrain, boils, hail and lightning, locusts, darkness, and lastly, the death of the firstborn. Each of the inflictions has a demonstrable connection with Egyptian customs and phenomena; each is directly aimed at some Egyptian superstition; all are marvelous, not, for the most part, as reversing, but as developing forces inherent in nature, and directing them to a special end. The effects correspond with these characteristics; the first miracles are neglected; the following plagues first alarm, and then for a season, subdue, the king, who does not give way until his firstborn is struck. Even that blow leaves him capable of a last effort, which completes his ruin, and the deliverance of the Israelites.I have made thee a god - Or "appointed thee." See the margin reference. Moses will stand in this special relation to Pharaoh, that God will address him by a prophet, i. e. by one appointed to speak in His name. The passage is an important one as illustrating the primary and essential characteristic of a prophet, he is the declarer of God''s will and purpose.', NULL, NULL, '''accredit'':21 ''address'':216 ''aim'':109 ''alarm'':153 ''appoint'':198,225 ''attend'':56 ''begin'':4 ''blow'':174 ''boil'':80 ''brother'':26 ''capabl'':177 ''chapter'':3 ''characterist'':143,243 ''come'':37,74 ''complet'':183 ''connect'':100 ''consequ'':59 ''correspond'':140 ''credenti'':30 ''custom'':103 ''dark'':85 ''death'':89 ''declar'':250 ''deliver'':188 ''demonstr'':99 ''devast'':77 ''develop'':126 ''direct'':108,132 ''e'':222 ''effect'':139 ''effort'':181 ''egypt'':11 ''egyptian'':62,102,112 ''end'':137 ''essenti'':242 ''even'':172 ''first'':16,145,152 ''firstborn'':92,169 ''follow'':150 ''forc'':127 ''give'':165 ''god'':196,214,252 ''grave'':58 ''hail'':81 ''illustr'':238 ''import'':235 ''inflict'':35,65,96 ''inher'':128 ''israelites.i'':191 ''king'':161 ''last'':87,180 ''leav'':175 ''lightn'':83 ''locust'':84 ''loss'':67 ''made'':193 ''margin'':202 ''marvel'':116 ''miracl'':8,17,146 ''mission'':23 ''mose'':204 ''murrain'':79 ''name'':230 ''natur'':45,130 ''neglect'':148 ''one'':224,236 ''part'':121 ''passag'':232 ''perform'':9,19 ''pharaoh'':212 ''phenomena'':105 ''plagu'':54,78,151 ''power'':43 ''primari'':240 ''progress'':14 ''prophet'':220,246 ''purpos'':256 ''rapid'':72 ''refer'':203 ''relat'':210 ''revers'':123 ''ruin'':185 ''ruinous'':75 ''season'':158 ''see'':200 ''seri'':6 ''sever'':66 ''show'':40 ''sign'':38 ''simpli'':29 ''speak'':227 ''special'':136,209 ''stand'':206 ''struck'':171 ''subdu'':159 ''subject'':47 ''success'':73 ''suffer'':69 ''superstit'':113 ''thee'':194,199 ''unaccompani'':32 ''way'':166 ''yahweh'':52 ''yet'':63', NULL, '57');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('843', '2', '843', NULL, 'The Temple - Properly the holy place (a), as distinguished from the porch (G) and the holy of holies (B) 1 Kings 6:17; 1 Kings 7:50.The posts - The outer wall of the temple was six cubits thick Ezekiel 41:5. The eastern posts of this wall forming part of the front of the temple were ornamented with pillars, six cubits on each side.He measured the breadth - This breadth was twenty cubits Ezekiel 41:2. Omit "which was." "tabernacle" is here the interior (the covered portion) of the temple.', NULL, NULL, '''1'':20,24 ''17'':23 ''2'':75 ''41'':40,74 ''5'':41 ''50.the'':27 ''6'':22 ''7'':26 ''b'':19 ''breadth'':67,69 ''cover'':85 ''cubit'':37,61,72 ''distinguish'':9 ''eastern'':43 ''ezekiel'':39,73 ''form'':48 ''front'':52 ''g'':13 ''holi'':5,16,18 ''interior'':83 ''king'':21,25 ''measur'':65 ''omit'':76 ''ornament'':57 ''outer'':30 ''part'':49 ''pillar'':59 ''place'':6 ''porch'':12 ''portion'':86 ''post'':28,44 ''proper'':3 ''side.he'':64 ''six'':36,60 ''tabernacl'':79 ''templ'':2,34,55,89 ''thick'':38 ''twenti'':71 ''wall'':31,47', NULL, '843');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('603', '2', '603', NULL, 'They that trust in the Lord - His people; his friends. It is, and has been always, a characteristic of the people of God that they trust or confide in him.Shall be as mount Zion - The mountain which David fortified, and on which the city was at first built, 2 Samuel 5:6-9. The name Zion became also the name by which the entire city was known.Which cannot be removed, but abideth for ever - A mountain is an emblem of firmness and stability; and it is natural to speak of it as that which could not be removed. There is something more than this, however, intended here, as there is some ground of comparison especially in regard to Mount Zion. This must have been either the idea that Zion was particularly strong by position, or that it was under the divine protection, and was therefore safe. Most probably it refers to Zion as a place secure by nature, and rendered more so by art.', NULL, NULL, '''-9'':53 ''2'':49 ''5'':51 ''6'':52 ''abideth'':72 ''also'':58 ''alway'':16 ''art'':164 ''becam'':57 ''built'':48 ''cannot'':68 ''characterist'':18 ''citi'':44,65 ''comparison'':114 ''confid'':28 ''could'':95 ''david'':38 ''divin'':141 ''either'':125 ''emblem'':79 ''entir'':64 ''especi'':115 ''ever'':74 ''firm'':81 ''first'':47 ''fortifi'':39 ''friend'':10 ''god'':23 ''ground'':112 ''him.shall'':30 ''howev'':105 ''idea'':127 ''intend'':106 ''known.which'':67 ''lord'':6 ''mount'':33,119 ''mountain'':36,76 ''must'':122 ''name'':55,60 ''natur'':87,158 ''particular'':131 ''peopl'':8,21 ''place'':155 ''posit'':134 ''probabl'':148 ''protect'':142 ''refer'':150 ''regard'':117 ''remov'':70,98 ''render'':160 ''safe'':146 ''samuel'':50 ''secur'':156 ''someth'':101 ''speak'':89 ''stabil'':83 ''strong'':132 ''therefor'':145 ''trust'':3,26 ''zion'':34,56,120,129,152', NULL, '603');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('58', '2', '58', NULL, 'With frogs - Some months appear to have elapsed between this and the former plague, if the frogs made their appearance at the usual time, that is in September. The special species mentioned here is of Egyptian origin. This plague was, like the preceding, in general accordance with natural phenomena, but marvelous both for its extent and intensity, and for its direct connection with the words and acts of God''s messengers. It had also apparently, like the other plagues, a direct bearing upon Egyptian superstitions. There was a female deity with a frog''s head, and the frog was connected with the most ancient forms of nature-worship in Egypt.', NULL, NULL, '''accord'':46 ''act'':67 ''also'':74 ''ancient'':104 ''appar'':75 ''appear'':5,20 ''bear'':82 ''connect'':62,100 ''deiti'':90 ''direct'':61,81 ''egypt'':111 ''egyptian'':36,84 ''elaps'':8 ''extent'':55 ''femal'':89 ''form'':105 ''former'':13 ''frog'':2,17,93,98 ''general'':45 ''god'':69 ''head'':95 ''intens'':57 ''like'':41,76 ''made'':18 ''marvel'':51 ''mention'':32 ''messeng'':71 ''month'':4 ''natur'':48,108 ''nature-worship'':107 ''origin'':37 ''phenomena'':49 ''plagu'':14,39,79 ''preced'':43 ''septemb'':28 ''speci'':31 ''special'':30 ''superstit'':85 ''time'':24 ''upon'':83 ''usual'':23 ''word'':65 ''worship'':109', NULL, '58');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('59', '2', '59', NULL, 'A very grievous murrain - Or "pestilence;" but the word "murrain," i. e. "a great mortality," exactly expresses the meaning. This terrible visitation struck far more severely than the preceding, which had caused distress and suffering; it attacked the resources of the nation.The camels - These animals are only twice mentioned, here and Genesis 12:16, in connection with Egypt. Though camels are never represented on the monuments, they were known to the Egyptians, and were probably used on the frontier.', NULL, NULL, '''12'':53 ''16'':54 ''anim'':45 ''attack'':37 ''camel'':43,60 ''caus'':32 ''connect'':56 ''distress'':33 ''e'':12 ''egypt'':58 ''egyptian'':72 ''exact'':16 ''express'':17 ''far'':24 ''frontier'':79 ''genesi'':52 ''great'':14 ''grievous'':3 ''known'':69 ''mean'':19 ''mention'':49 ''monument'':66 ''mortal'':15 ''murrain'':4,10 ''nation.the'':42 ''never'':62 ''pestil'':6 ''preced'':29 ''probabl'':75 ''repres'':63 ''resourc'':39 ''sever'':26 ''struck'':23 ''suffer'':35 ''terribl'':21 ''though'':59 ''twice'':48 ''use'':76 ''visit'':22 ''word'':9', NULL, '59');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('604', '2', '604', NULL, 'When the Lord turned again the captivity of Zion - Margin, as in Hebrew, "returned the returning of Zion." The Hebrew word which is rendered in the text captivity means properly return; and then, those returning. The ancient versions render it captivity. The reference clearly is to those who were returning to Zion, and the psalmist fixes his eye on them as returning, and immediately says that it was the Lord who had thus restored them. The whole was to be traced to God.We were like them that dream - The Latin Vulgate and the Septuagint render this, "we were comforted." The meaning is, "It seemed like a dream; we could hardly realize that it was so; it was so marvelous, so good, so full of joy, that we could scarcely believe it was real." This state of mind is not uncommon, when, in sudden and overpowering joy, we ask whether it can be real; whether it is not all a dream. We fear that it is; we apprehend that it will all vanish away like a dream.', NULL, NULL, '''ancient'':37 ''apprehend'':167 ''ask'':148 ''away'':173 ''believ'':130 ''captiv'':7,28,41 ''clear'':44 ''comfort'':99 ''could'':109,128 ''dream'':88,107,160,176 ''eye'':58 ''fear'':162 ''fix'':56 ''full'':123 ''god.we'':83 ''good'':121 ''hard'':110 ''hebrew'':13,20 ''immedi'':64 ''joy'':125,146 ''latin'':90 ''like'':85,105,174 ''lord'':3,70 ''margin'':10 ''marvel'':119 ''mean'':29,101 ''mind'':137 ''overpow'':145 ''proper'':30 ''psalmist'':55 ''real'':133,153 ''realiz'':111 ''refer'':43 ''render'':24,39,95 ''restor'':74 ''return'':14,16,31,35,50,62 ''say'':65 ''scarc'':129 ''seem'':104 ''septuagint'':94 ''state'':135 ''sudden'':143 ''text'':27 ''thus'':73 ''trace'':81 ''turn'':4 ''uncommon'':140 ''vanish'':172 ''version'':38 ''vulgat'':91 ''whether'':149,154 ''whole'':77 ''word'':21 ''zion'':9,18,52', NULL, '604');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('844', '2', '844', NULL, 'Utter court - Outward court, so Ezekiel 42:3.Into the chamber ... before the building - to the chambers (See L, Plan II)... over against etc. "The building" is the temple-building, for this row of chambers was built against eighty cubits of the wall bounding "the separate place" and twenty cubits of the wall of the temple-court.', NULL, NULL, '''3.into'':8 ''42'':7 ''bound'':44 ''build'':13,25,30 ''built'':37 ''chamber'':10,16,35 ''court'':2,4,58 ''cubit'':40,50 ''eighti'':39 ''etc'':23 ''ezekiel'':6 ''ii'':20 ''l'':18 ''outward'':3 ''place'':47 ''plan'':19 ''row'':33 ''see'':17 ''separ'':46 ''templ'':29,57 ''temple-build'':28 ''temple-court'':56 ''twenti'':49 ''utter'':1 ''wall'':43,53', NULL, '844');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('606', '2', '606', NULL, 'Behold, that thus shall the man be blessed ... - As if he had said, "Look upon this picture. See the farmer cultivating his fields; see him gathering in the grain; see him at his own table calmly, quietly, and gratefully enjoying the fruit of his toil. Look upon that picture of a happy family - numerous, cheerful, beloved - giving promise of upholding the name of the family in future years - and see all this as coming from the Lord - and you have an illustration of the blessedness which follows a religious life."', NULL, NULL, '''behold'':1 ''belov'':56 ''bless'':8 ''blessed'':85 ''calm'':36 ''cheer'':55 ''come'':74 ''cultiv'':21 ''enjoy'':40 ''famili'':53,65 ''farmer'':20 ''field'':23 ''follow'':87 ''fruit'':42 ''futur'':67 ''gather'':26 ''give'':57 ''grain'':29 ''grate'':39 ''happi'':52 ''illustr'':82 ''life'':90 ''look'':14,46 ''lord'':77 ''man'':6 ''name'':62 ''numer'':54 ''pictur'':17,49 ''promis'':58 ''quiet'':37 ''religi'':89 ''said'':13 ''see'':18,24,30,70 ''shall'':4 ''tabl'':35 ''thus'':3 ''toil'':45 ''uphold'':60 ''upon'':15,47 ''year'':68', NULL, '606');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('845', '2', '845', NULL, 'The man - A "man." Probably an angel different from "the man" who had hitherto accompanied the seer. That angel guided, measured, and explained; this is present only to guide.', NULL, NULL, '''accompani'':15 ''angel'':7,19 ''differ'':8 ''explain'':23 ''guid'':20,29 ''hitherto'':14 ''man'':2,4,11 ''measur'':21 ''present'':26 ''probabl'':5 ''seer'':17', NULL, '845');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('846', '2', '846', NULL, 'Outward sanctuary - The court of the priests, as distinguished from the temple itself. This gate was reserved for the prince, to whom it was opened on certain days. Only a prince of the house of David might sit down in the priests'' court (compare Ezekiel 46:1-2).', NULL, NULL, '''-2'':48 ''1'':47 ''46'':46 ''certain'':27 ''compar'':44 ''court'':4,43 ''david'':36 ''day'':28 ''distinguish'':9 ''ezekiel'':45 ''gate'':15 ''hous'':34 ''might'':37 ''open'':25 ''outward'':1 ''priest'':7,42 ''princ'':20,31 ''reserv'':17 ''sanctuari'':2 ''sit'':38 ''templ'':12', NULL, '846');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('607', '2', '607', NULL, 'Many a time - Margin, as in Hebrew, "much." Probably, however, the idea is, as expressed in our translation, "many a time;" "often." So it is in the Latin Vulgate and the Septuagint; and this accords better with the connection.Have they afflicted me from my youth - Have I been afflicted; have others dealt unjustly by me. The youth here is the beginning. of the history of that people: since we began to be a people; since the nation was founded.May Israel now say - May the nation now say. It is clear from this that the psalm was not written at an early period of their history.', NULL, NULL, '''accord'':35 ''afflict'':41,49 ''began'':70 ''begin'':61 ''better'':36 ''clear'':90 ''connection.have'':39 ''dealt'':52 ''earli'':101 ''express'':15 ''founded.may'':79 ''hebrew'':7 ''histori'':64,105 ''howev'':10 ''idea'':12 ''israel'':80 ''latin'':28 ''mani'':1,19 ''margin'':4 ''may'':83 ''much'':8 ''nation'':77,85 ''often'':22 ''other'':51 ''peopl'':67,74 ''period'':102 ''probabl'':9 ''psalm'':95 ''say'':82,87 ''septuagint'':32 ''sinc'':68,75 ''time'':3,21 ''translat'':18 ''unjust'':53 ''vulgat'':29 ''written'':98 ''youth'':45,57', NULL, '607');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('608', '2', '608', NULL, 'Out of the depths - The word rendered "depths" is from a verb -   amaq - which means to be deep; then, to be unsearchable; then, to make deep; and it would apply to anything low, deep, or profound, as the ocean, a pit, or a valley. The word used here occurs elsewhere only in the following places: Psalm 69:2, Psalm 69:14, where it is rendered "deep," applied to waters; and Isaiah 51:10; Ezekiel 27:34, where it is rendered "depths." The word, as used here, would be applicable to deep affliction, dejection, or distress. It would be applicable(a) to affliction - the depths of sorrow from loss of friends, property, or bodily suffering;(b) sin - the depths into which the soul is plunged under the consciousness of guilt;(c) mental trouble - low spirits - melancholy - darkness of mind - loss of comfort in religion - powerful temptation - disappointment - the anguish caused by ingratitude - or sadness of heart in view of the crimes and the sorrows of people - or grief at the coldness, the hardness, the insensibility of our friends to their spiritual condition.From all these depths of sorrow it is our privilege to call upon the Lord; in those depths of sorrow it is proper thus to implore his help. Often he brings us into these "depths" that we may be led to call upon him; always when we are brought there, we should call upon him.Have I cried unto thee, O Lord - Or rather, "do I now invoke thee," or call earnestly upon thee. The language does not refer so much to the past as the present. I now cry for mercy; I now implore thy blessing. The condition is that of one who in deep sorrow, or under deep conviction for sin, pleads earnestly that God would have compassion on him.', NULL, NULL, '''10'':73 ''14'':61 ''2'':58 ''27'':75 ''34'':76 ''51'':72 ''69'':57,60 ''afflict'':92,102 ''alway'':225 ''amaq'':13 ''anguish'':148 ''anyth'':32 ''appli'':30,67 ''applic'':89,99 ''b'':115 ''bless'':276 ''bodili'':113 ''bring'':211 ''brought'':229 ''c'':130 ''call'':192,222,233,250 ''caus'':149 ''cold'':170 ''comfort'':141 ''compass'':299 ''condit'':278 ''condition.from'':181 ''conscious'':127 ''convict'':290 ''cri'':237,269 ''crime'':160 ''dark'':136 ''deep'':18,26,34,66,91,285,289 ''deject'':93 ''depth'':4,8,81,104,118,184,198,215 ''disappoint'':146 ''distress'':95 ''earnest'':251,294 ''elsewher'':50 ''ezekiel'':74 ''follow'':54 ''friend'':110,177 ''god'':296 ''grief'':167 ''guilt'':129 ''hard'':172 ''heart'':155 ''help'':208 ''him.have'':235 ''implor'':206,274 ''ingratitud'':151 ''insens'':174 ''invok'':247 ''isaiah'':71 ''languag'':255 ''led'':220 ''lord'':195,241 ''loss'':108,139 ''low'':33,133 ''make'':25 ''may'':218 ''mean'':15 ''melancholi'':135 ''mental'':131 ''merci'':271 ''mind'':138 ''much'':260 ''o'':240 ''occur'':49 ''ocean'':39 ''often'':209 ''one'':282 ''past'':263 ''peopl'':165 ''pit'':41 ''place'':55 ''plead'':293 ''plung'':124 ''power'':144 ''present'':266 ''privileg'':190 ''profound'':36 ''proper'':203 ''properti'':111 ''psalm'':56,59 ''rather'':243 ''refer'':258 ''religion'':143 ''render'':7,65,80 ''sad'':153 ''sin'':116,292 ''sorrow'':106,163,186,200,286 ''soul'':122 ''spirit'':134 ''spiritu'':180 ''suffer'':114 ''temptat'':145 ''thee'':239,248,253 ''thi'':275 ''thus'':204 ''troubl'':132 ''unsearch'':22 ''unto'':238 ''upon'':193,223,234,252 ''us'':212 ''use'':47,85 ''valley'':44 ''verb'':12 ''view'':157 ''water'':69 ''word'':6,46,83 ''would'':29,87,97,297', NULL, '608');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('60', '2', '60', NULL, 'The locusts - The locust is less common in Egypt than in many eastern countries, yet it is well known, and dreaded as the most terrible of scourges. They come generally from the western deserts, but sometimes from the east and the southeast. No less than nine names are given to the locust in the Bible, of which the word used here is the most common (  ''arbeh); it signifies "multitudinous," and whenever it occurs reference is made to its terrible devastations.', NULL, NULL, '''arbeh'':66 ''bibl'':55 ''come'':29 ''common'':7,65 ''countri'':14 ''desert'':34 ''devast'':80 ''dread'':21 ''east'':39 ''eastern'':13 ''egypt'':9 ''general'':30 ''given'':49 ''known'':19 ''less'':6,44 ''locust'':2,4,52 ''made'':76 ''mani'':12 ''multitudin'':69 ''name'':47 ''nine'':46 ''occur'':73 ''refer'':74 ''scourg'':27 ''signifi'':68 ''sometim'':36 ''southeast'':42 ''terribl'':25,79 ''use'':60 ''well'':18 ''western'':33 ''whenev'':71 ''word'':59 ''yet'':15', NULL, '60');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('609', '2', '609', NULL, 'Lord, my heart is not haughty - Though this is charged upon me; though I may have said things which seem to imply it; though this might appear a just inference from my conduct - yet I am conscious that this is not my real character. What I have said was not the result of ambition.Nor mine eyes lofty - I am conscious that I am not ambitious and aspiring - as I am accused of being. What I have said is not the result of such a feeling, nor should such a charge be brought against me.Neither do I exercise myself - Margin, as in Hebrew, walk. I do not walk about among such things; I do not pry into them; I do not meddle with them. What I have said or done is not, as has been said concerning me, the result of a meddlesome and interfering spirit. It may seem to be so; my own consciousness tells me it is not so. The interpretation put upon my conduct may be natural; but I am conscious to myself that it is not the right interpretation.In great matters, or in things too high for me - Margin, as in Hebrew, wonderful. The word wonderful would apply to matters suited to excite astonishment by their vastness, or their unusual nature - as prodigies or miracles; and then, great and lofty truths. It would apply also to things which might be regarded as far above the capacity of a child, or of one in obscure life, and with slight advantages of education; and, as above suggested, it may have been the accusation brought against him, that, in respect to public matters, matters of state - or to the more elevated doctrines of religion - he had manifested a spirit unbecoming one in early years, and of humble rank, and that this indicated a desire to meddle with matters which he could not understand, and which could not pertain to him. He was conscious, he says, that he was not actuated by that spirit.', NULL, NULL, '''accus'':71,264 ''actuat'':330 ''advantag'':252 ''also'':228 ''ambiti'':65 ''ambition.nor'':54 ''among'':109 ''appear'':27 ''appli'':201,227 ''aspir'':67 ''astonish'':207 ''brought'':92,265 ''capac'':239 ''charact'':44 ''charg'':10,90 ''child'':242 ''concern'':136 ''conduct'':33,166 ''conscious'':37,60,154,173,323 ''could'':311,316 ''desir'':304 ''doctrin'':282 ''done'':129 ''earli'':293 ''educ'':254 ''elev'':281 ''excit'':206 ''exercis'':97 ''eye'':56 ''far'':236 ''feel'':85 ''great'':183,221 ''haughti'':6 ''heart'':3 ''hebrew'':102,195 ''high'':189 ''humbl'':297 ''impli'':22 ''indic'':302 ''infer'':30 ''interf'':144 ''interpret'':162 ''interpretation.in'':182 ''life'':248 ''lofti'':57,223 ''lord'':1 ''manifest'':287 ''margin'':99,192 ''matter'':184,203,273,274,308 ''may'':15,147,167,260 ''me.neither'':94 ''meddl'':121,306 ''meddlesom'':142 ''might'':26,232 ''mine'':55 ''miracl'':218 ''natur'':169,214 ''obscur'':247 ''one'':245,291 ''pertain'':318 ''pri'':115 ''prodigi'':216 ''public'':272 ''put'':163 ''rank'':298 ''real'':43 ''regard'':234 ''religion'':284 ''respect'':270 ''result'':52,81,139 ''right'':181 ''said'':17,48,77,127,135 ''say'':325 ''seem'':20,148 ''slight'':251 ''spirit'':145,289,333 ''state'':276 ''suggest'':258 ''suit'':204 ''tell'':155 ''thing'':18,111,187,230 ''though'':7,13,24 ''truth'':224 ''unbecom'':290 ''understand'':313 ''unusu'':213 ''upon'':11,164 ''vast'':210 ''walk'':103,107 ''wonder'':196,199 ''word'':198 ''would'':200,226 ''year'':294 ''yet'':34', NULL, '609');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('67', '2', '67', NULL, 'According to their journeys - The Israelites rested at two stations before they reached Rephidim, namely, Dophkah and Alush Numbers 33:12-14. Dophkah was in the Wady Sih, a day''s journey from the Wady Nasb. The wilderness of Sin Exodus 16:1 properly speaking ends here, the sandstone ceases, and is replaced by the porphyry and granite which belong to the central formation of the Sinaitic group. Alush may have been near the entrance to the Wady Sheikh.Rephidim - (Variously placed at Feiran at the base of Mount Serbal, or at the pass of El Watiyeh.)', NULL, NULL, '''-14'':22 ''1'':43 ''12'':21 ''16'':42 ''33'':20 ''accord'':1 ''alush'':18,69 ''base'':86 ''belong'':60 ''ceas'':50 ''central'':63 ''day'':30 ''dophkah'':16,23 ''el'':95 ''end'':46 ''entranc'':75 ''exodus'':41 ''feiran'':83 ''format'':64 ''granit'':58 ''group'':68 ''israelit'':6 ''journey'':4,32 ''may'':70 ''mount'':88 ''name'':15 ''nasb'':36 ''near'':73 ''number'':19 ''pass'':93 ''place'':81 ''porphyri'':56 ''proper'':44 ''reach'':13 ''rephidim'':14 ''replac'':53 ''rest'':7 ''sandston'':49 ''serbal'':89 ''sheikh.rephidim'':79 ''sih'':28 ''sin'':40 ''sinait'':67 ''speak'':45 ''station'':10 ''two'':9 ''various'':80 ''wadi'':27,35,78 ''watiyeh'':96 ''wilder'':38', NULL, '67');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('68', '2', '68', NULL, 'Jethro was, in all probability, the "brother-in-law" of Moses Exodus 3:1. On the parting from Zipporah, see Exodus 4:26.', NULL, NULL, '''1'':15 ''26'':24 ''3'':14 ''4'':23 ''brother'':8 ''brother-in-law'':7 ''exodus'':13,22 ''jethro'':1 ''law'':10 ''mose'':12 ''part'':18 ''probabl'':5 ''see'':21 ''zipporah'':20', NULL, '68');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('69', '2', '69', NULL, 'The wilderness ... the desert of Sinai - If the mount from which the law was delivered be the rock of Ras Safsafeh, then the spacious plain of Er Rahah would be the "desert" of Sinai (see Exodus 5:17).', NULL, NULL, '''17'':38 ''5'':37 ''deliv'':15 ''desert'':4,32 ''er'':27 ''exodus'':36 ''law'':13 ''mount'':9 ''plain'':25 ''rahah'':28 ''ras'':20 ''rock'':18 ''safsafeh'':21 ''see'':35 ''sinai'':6,34 ''spacious'':24 ''wilder'':2 ''would'':29', NULL, '69');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('77', '2', '77', NULL, 'His horns shall be of the same - These horns were projections pointing upward in the form either of a small obelisk, or of the horn of an ox. They were to be actually parts of the altar, not merely superadded to it. On them the blood of the sin-offering was smeared Exodus 29:12; Leviticus 4:7; Leviticus 8:15; Leviticus 9:9; Leviticus 16:18. To take hold of them appears to have been regarded as an emphatic mode of laying claim to the supposed right of sanctuary (Exodus 21:14 note; 1 Kings 1:50).', NULL, NULL, '''1'':96,98 ''12'':56 ''14'':94 ''15'':62 ''16'':67 ''18'':68 ''21'':93 ''29'':55 ''4'':58 ''50'':99 ''7'':59 ''8'':61 ''9'':64,65 ''actual'':33 ''altar'':37 ''appear'':74 ''blood'':46 ''claim'':85 ''either'':17 ''emphat'':81 ''exodus'':54,92 ''form'':16 ''hold'':71 ''horn'':2,9,25 ''king'':97 ''lay'':84 ''leviticus'':57,60,63,66 ''mere'':39 ''mode'':82 ''note'':95 ''obelisk'':21 ''offer'':51 ''ox'':28 ''part'':34 ''point'':12 ''project'':11 ''regard'':78 ''right'':89 ''sanctuari'':91 ''shall'':3 ''sin'':50 ''sin-off'':49 ''small'':20 ''smear'':53 ''superad'':40 ''suppos'':88 ''take'':70 ''upward'':13', NULL, '77');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('847', '2', '847', NULL, 'By lot - Not by casting lots, but by "allotment," the several portions being assigned by rule Joshua 13:6.Oblation - The oblation (properly "heaveoffering") was regarded as the Lord''s portion Leviticus 27:30. This "oblation" is given here as part of the provision made for the priests, and was probably in lieu of tithes Leviticus 27:30; Numbers 18:21, just as the prince had his definite portion of land instead of being supported by the contributions of the people. The priests and Levites had, in addition, the sacrifices (Ezekiel 44:28, note). This provision for them, out of proportion in any actual arrangement, is no doubt intended to symbolize the reverence and honor due to God, and expressed by liberality to His services and His ministers. The Septuagint read "the breadth twenty thousand;" and those who adopt this, read Ezekiel 45:3 "and from this" whole measure is to be deducted the priests'' special portion 25,000 from east to west, and 10,000 from north to south. Others, retaining the reading of the text, suppose the term oblation here to denote the portion assigned to the priests alone (as in Ezekiel 48:9), and "of this measure" Ezekiel 45:3 to mean not "deducted from this measure," but "computed by this measure." The King James Version rightly supplies "reeds," since the precincts Ezekiel 42:20 were 500 "reeds" square. 25,000 reeds  equals about 42 12 statute miles, 36 12 geographic miles.', NULL, NULL, '''000'':158,165,233 ''10'':164 ''12'':238,242 ''13'':18 ''18'':59 ''20'':227 ''21'':60 ''25'':157,232 ''27'':32,56 ''28'':92 ''3'':143,202 ''30'':33,57 ''36'':241 ''42'':226,237 ''44'':91 ''45'':142,201 ''48'':194 ''500'':229 ''6.oblation'':19 ''9'':195 ''actual'':103 ''addit'':87 ''adopt'':138 ''allot'':9 ''alon'':190 ''arrang'':104 ''assign'':14,186 ''breadth'':132 ''cast'':5 ''comput'':211 ''contribut'':77 ''deduct'':152,206 ''definit'':67 ''denot'':183 ''doubt'':107 ''due'':115 ''east'':160 ''equal'':235 ''express'':119 ''ezekiel'':90,141,193,200,225 ''geograph'':243 ''given'':37 ''god'':117 ''heaveoff'':23 ''honor'':114 ''instead'':71 ''intend'':108 ''jame'':217 ''joshua'':17 ''king'':216 ''land'':70 ''levit'':84 ''leviticus'':31,55 ''liber'':121 ''lieu'':52 ''lord'':28 ''lot'':2,6 ''made'':44 ''mean'':204 ''measur'':148,199,209,214 ''mile'':240,244 ''minist'':127 ''north'':167 ''note'':93 ''number'':58 ''oblat'':21,35,180 ''other'':170 ''part'':40 ''peopl'':80 ''portion'':12,30,68,156,185 ''precinct'':224 ''priest'':47,82,154,189 ''princ'':64 ''probabl'':50 ''proper'':22 ''proport'':100 ''provis'':43,95 ''read'':130,140,173 ''reed'':221,230,234 ''regard'':25 ''retain'':171 ''rever'':112 ''right'':219 ''rule'':16 ''sacrific'':89 ''septuagint'':129 ''servic'':124 ''sever'':11 ''sinc'':222 ''south'':169 ''special'':155 ''squar'':231 ''statut'':239 ''suppli'':220 ''support'':74 ''suppos'':177 ''symbol'':110 ''term'':179 ''text'':176 ''thousand'':134 ''tith'':54 ''twenti'':133 ''version'':218 ''west'':162 ''whole'':147', NULL, '847');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('848', '2', '848', NULL, 'The prophet beholds in vision people, priest, and prince uniting in most solemn worship before the throne of God. The character of the rites here described is symbolic.', NULL, NULL, '''behold'':3 ''charact'':21 ''describ'':26 ''god'':19 ''peopl'':6 ''priest'':7 ''princ'':9 ''prophet'':2 ''rite'':24 ''solemn'':13 ''symbol'':28 ''throne'':17 ''unit'':10 ''vision'':5 ''worship'':14', NULL, '848');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('78', '2', '78', NULL, '(Compare Exodus 39:1-31.) Moses is now commanded to commit all that pertains to the offerings made to the Lord in the sanctuary to the exclusive charge of the members of a single family, who were to hold their office from generation to generation. In the patriarchal times, the external rites of worship had generally been conducted by the head of the tribe or family, in accordance with the principle involved in the dedication of the firstborn Exodus 13:2; Numbers 3:12-13. Moses, as the divinely-appointed and acknowledged leader of the nation, had, on a special occasion, appointed those who were to offer sacrifice, and had himself sprinkled the consecrating blood of the victims on the people Exodus 24:5-6, Exodus 24:8. On the completion of the tabernacle, after Aaron and his sons had been called to the priesthood, he took chief part in the daily service of the sanctuary Exodus 40:23-29, Exodus 40:31-32 until the consecration of the family of Aaron, on which occasion he appears to have exercised the priest''s office for the last time (Leviticus 8:14-29; compare Exodus 29:10-26). The setting apart of the whole tribe of Levi for the entire cycle of religious services is mentioned Numbers 3:5-13; Numbers 8:5-26; Numbers 18:1-32.Exodus 28:1Nadab and Abihu, the two older sons of Aaron, had accompanied their father and the seventy Elders when they went a part of the way with Moses up the mountain Exodus 24:1, Exodus 24:9. Soon after their consecration they were destroyed for offering "strange fire before the Lord" Leviticus 10:1-2. Eleazar and Ithamar are here mentioned for the first time, except in the genealogy, Exodus 6:23. Eleazar succeeded his father in the High priesthood, and was himself succeeded by his son Phinehas Judges 20:28. But Eli, the next high priest named in the history, was of the line of Ithamar. The representatives of both families held office at the same time in the days of David. See 1 Chronicles 24:1-3; 2 Samuel 8:17.', NULL, NULL, '''-13'':85,220 ''-2'':282 ''-26'':198,224 ''-29'':161,193 ''-3'':356 ''-31'':5 ''-32'':165 ''-6'':126 ''1'':4,261,281,352,355 ''1-32.exodus'':227 ''10'':197,280 ''12'':84 ''13'':80 ''14'':192 ''17'':360 ''18'':226 ''1nadab'':229 ''2'':81,357 ''20'':317 ''23'':160,299 ''24'':124,128,260,263,354 ''28'':228,318 ''29'':196 ''3'':83,218 ''31'':164 ''39'':3 ''40'':159,163 ''5'':125,219,223 ''6'':298 ''8'':129,191,222,359 ''9'':264 ''aaron'':137,173,237 ''abihu'':231 ''accompani'':239 ''accord'':68 ''acknowledg'':93 ''apart'':201 ''appear'':178 ''appoint'':91,103 ''blood'':116 ''call'':143 ''charg'':28 ''chief'':149 ''chronicl'':353 ''command'':9 ''commit'':11 ''compar'':1,194 ''complet'':132 ''conduct'':58 ''consecr'':115,168,268 ''cycl'':211 ''daili'':153 ''david'':350 ''day'':348 ''dedic'':75 ''destroy'':271 ''divin'':90 ''divinely-appoint'':89 ''elder'':245 ''eleazar'':283,300 ''eli'':320 ''entir'':210 ''except'':293 ''exclus'':27 ''exercis'':181 ''exodus'':2,79,123,127,158,162,195,259,262,297 ''extern'':51 ''famili'':35,66,171,339 ''father'':241,303 ''fire'':275 ''first'':291 ''firstborn'':78 ''genealog'':296 ''general'':56 ''generat'':43,45 ''head'':61 ''held'':340 ''high'':306,323 ''histori'':328 ''hold'':39 ''involv'':72 ''ithamar'':285,334 ''judg'':316 ''last'':188 ''leader'':94 ''levi'':207 ''leviticus'':190,279 ''line'':332 ''lord'':21,278 ''made'':18 ''member'':31 ''mention'':216,288 ''mose'':6,86,255 ''mountain'':258 ''name'':325 ''nation'':97 ''next'':322 ''number'':82,217,221,225 ''occas'':102,176 ''offer'':17,108,273 ''offic'':41,185,341 ''older'':234 ''part'':150,250 ''patriarch'':48 ''peopl'':122 ''pertain'':14 ''phineha'':315 ''priest'':183,324 ''priesthood'':146,307 ''principl'':71 ''religi'':213 ''repres'':336 ''rite'':52 ''sacrific'':109 ''samuel'':358 ''sanctuari'':24,157 ''see'':351 ''servic'':154,214 ''set'':200 ''seventi'':244 ''singl'':34 ''son'':140,235,314 ''soon'':265 ''special'':101 ''sprinkl'':113 ''strang'':274 ''succeed'':301,311 ''tabernacl'':135 ''time'':49,189,292,345 ''took'':148 ''tribe'':64,205 ''two'':233 ''victim'':119 ''way'':253 ''went'':248 ''whole'':204 ''worship'':54', NULL, '78');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('80', '2', '80', NULL, 'Exodus 37:25-28; Exodus 40:26-27. The altar of incense was to be a casing of boards of shittim wood Exodus 25:5, Exodus 25:18 inches square and three feet in height (taking the cubit as 18 inches), entirely covered with plates of gold. Four "horns" were to project upward at the corners like those of the altar of burnt-offering Exodus 27:2. A crown or moulding of gold was to run round the top. On each of two opposite sides there was to be a gold ring through which the staves were to be put when it was moved from place to place.', NULL, NULL, '''-27'':8 ''-28'':4 ''18'':28,40 ''2'':68 ''25'':3,24,27 ''26'':7 ''27'':67 ''37'':2 ''40'':6 ''5'':25 ''altar'':10,61 ''board'':19 ''burnt'':64 ''burnt-off'':63 ''case'':17 ''corner'':56 ''cover'':43 ''crown'':70 ''cubit'':38 ''entir'':42 ''exodus'':1,5,23,26,66 ''feet'':33 ''four'':48 ''gold'':47,74,92 ''height'':35 ''horn'':49 ''incens'':12 ''inch'':29,41 ''like'':57 ''mould'':72 ''move'':105 ''offer'':65 ''opposit'':85 ''place'':107,109 ''plate'':45 ''project'':52 ''put'':101 ''ring'':93 ''round'':78 ''run'':77 ''shittim'':21 ''side'':86 ''squar'':30 ''stave'':97 ''take'':36 ''three'':32 ''top'':80 ''two'':84 ''upward'':53 ''wood'':22', NULL, '80');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('133', '2', '133', NULL, 'Amram and Izhar were brothers (compare Exodus 6:18), and thus Korah, the "son," i. e. descendant of Izhar, was connected by distant cousinship with Moses and Aaron. Though being a Kohathite, he was of that division of the Levites which had the most honorable charge, yet as Elizaphan, who had been made "chief of the families of the Kohathites" Numbers 3:30, belonged to the youngest branch descended from Uzziel Numbers 3:27, Korah probably regarded himself as injured; and therefore took the lead in this rebellion. Of the others, On is not again mentioned. He probably withdrew from the conspiracy. Dathan, Abiram, and On were Reubenites; and were probably discontented because the birthright had been taken away from their ancestor Genesis 49:3, and with it the primacy of their own tribe among the tribes of Israel. The Reubenites encamped near to the Kohathites (compare Numbers 2:25 and plan), and thus the two families were conveniently situated for taking counsel together. One pretext of the insurrection probably was to assert the rights of primogeniture - on the part of the Reubenites against Moses, on the part of Korah against the appointment of Uzziel.', NULL, NULL, '''18'':9 ''2'':149 ''25'':150 ''27'':74 ''3'':62,73,125 ''30'':63 ''49'':124 ''6'':8 ''aaron'':28 ''abiram'':104 ''among'':135 ''amram'':1 ''ancestor'':122 ''appoint'':193 ''assert'':173 ''away'':119 ''belong'':64 ''birthright'':115 ''branch'':68 ''brother'':5 ''charg'':46 ''chief'':54 ''compar'':6,147 ''connect'':21 ''conspiraci'':102 ''conveni'':159 ''counsel'':163 ''cousinship'':24 ''dathan'':103 ''descend'':17,69 ''discont'':112 ''distant'':23 ''divis'':37 ''e'':16 ''elizaphan'':49 ''encamp'':142 ''exodus'':7 ''famili'':57,157 ''genesi'':123 ''honor'':45 ''injur'':80 ''insurrect'':169 ''israel'':139 ''izhar'':3,19 ''kohathit'':32,60,146 ''korah'':12,75,190 ''lead'':85 ''levit'':40 ''made'':53 ''mention'':96 ''mose'':26,185 ''near'':143 ''number'':61,72,148 ''one'':165 ''other'':91 ''part'':180,188 ''plan'':152 ''pretext'':166 ''primaci'':130 ''primogenitur'':177 ''probabl'':76,98,111,170 ''rebellion'':88 ''regard'':77 ''reubenit'':108,141,183 ''right'':175 ''situat'':160 ''son'':14 ''take'':162 ''taken'':118 ''therefor'':82 ''though'':29 ''thus'':11,154 ''togeth'':164 ''took'':83 ''tribe'':134,137 ''two'':156 ''uzziel'':71,195 ''withdrew'':99 ''yet'':47 ''youngest'':67', NULL, '133');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('134', '2', '134', NULL, 'Thou shalt write Aaron''s name upon the rod of Levi - The Levites had taken part in the late outbreak. It was therefore necessary to vindicate the supremacy of the house of Aaron over them; and accordingly his name was written on the rod of Levi, although being the son of Kohath, the second son of Levi (Exodus 6:16 ff), he would not be the natural head of the tribe.', NULL, NULL, '''16'':60 ''6'':59 ''aaron'':4,33 ''accord'':37 ''although'':47 ''exodus'':58 ''ff'':61 ''head'':68 ''hous'':31 ''kohath'':52 ''late'':19 ''levi'':11,46,57 ''levit'':13 ''name'':6,39 ''natur'':67 ''necessari'':24 ''outbreak'':20 ''part'':16 ''rod'':9,44 ''second'':54 ''shalt'':2 ''son'':50,55 ''supremaci'':28 ''taken'':15 ''therefor'':23 ''thou'':1 ''tribe'':71 ''upon'':7 ''vindic'':26 ''would'':63 ''write'':3 ''written'':41', NULL, '134');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('81', '2', '81', NULL, 'Exodus 35:30-35. This solemn call of Bezaleel and Aholiab is full of instruction. Their work was to be only that of handicraftsmen. Still it was Yahweh Himself who called them by name to their tasks, and the powers which they were now called upon to exercise in their respective crafts, were declared to have been given them by the Holy Spirit. Thus is every effort of skill, every sort of well-ordered labor, when directed to a right end, brought into the very highest sphere of association.There appears to be sufficient reason for identifying Hur, the grandfather of Bezaleel, with the Hur who assisted Aaron in supporting the hands of Moses during the battle with Amalek at Rephidim Exodus 17:10, and who was associated with Aaron in the charge of the people while Moses was on the mountain Exodus 24:14. Josephus says that he was the husband of Miriam. It is thus probable that Bezaleel was related to Moses. He was the chief artificer in metal, stone, and wood; he had also to perform the apothecary''s work in the composition of the anointing oil and the incense Exodus 37:29. He had precedence of all the artificers, but Aholiab appears to have had the entire charge of the textile work Exodus 35:35; Exodus 38:23.', NULL, NULL, '''-35'':4 ''10'':124 ''14'':145 ''17'':123 ''23'':222 ''24'':144 ''29'':196 ''30'':3 ''35'':2,218,219 ''37'':195 ''38'':221 ''aaron'':108,130 ''aholiab'':11,205 ''also'':177 ''amalek'':119 ''anoint'':189 ''apothecari'':181 ''appear'':91,206 ''artific'':169,203 ''assist'':107 ''associ'':128 ''association.there'':90 ''battl'':117 ''bezaleel'':9,102,160 ''brought'':83 ''call'':7,31,45 ''charg'':133,212 ''chief'':168 ''composit'':186 ''craft'':52 ''declar'':54 ''direct'':78 ''effort'':67 ''end'':82 ''entir'':211 ''everi'':66,70 ''exercis'':48 ''exodus'':1,122,143,194,217,220 ''full'':13 ''given'':58 ''grandfath'':100 ''hand'':112 ''handicraftsmen'':24 ''highest'':87 ''holi'':62 ''hur'':98,105 ''husband'':152 ''identifi'':97 ''incens'':193 ''instruct'':15 ''josephus'':146 ''labor'':76 ''metal'':171 ''miriam'':154 ''mose'':114,138,164 ''mountain'':142 ''name'':34 ''oil'':190 ''order'':75 ''peopl'':136 ''perform'':179 ''power'':40 ''preced'':199 ''probabl'':158 ''reason'':95 ''relat'':162 ''rephidim'':121 ''respect'':51 ''right'':81 ''say'':147 ''skill'':69 ''solemn'':6 ''sort'':71 ''sphere'':88 ''spirit'':63 ''still'':25 ''stone'':172 ''suffici'':94 ''support'':110 ''task'':37 ''textil'':215 ''thus'':64,157 ''upon'':46 ''well'':74 ''well-ord'':73 ''wood'':174 ''work'':17,183,216 ''yahweh'':28', NULL, '81');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('610', '2', '610', NULL, 'Lord, remember David - Call to remembrance his zeal, his labor, his trials in order that there might be a permanent place for thy worship. Call this to remembrance in order that his purpose in thy cause may not be frustrated; in order that the promises made to him may be accomplished.And all his afflictions - The particular trial here referred to was his care and toil, that there might be a settled home for the ark. The word used would not refer merely to what is specified in the following verses (his bringing up the ark to Mount Zion), but to his purpose to build a house for God, and - since he was not permitted himself to build it because he was a man of war, and had been engaged in scenes of blood, 1 Kings 5:3; 1 Chronicles 22:8 - to his care and toil in collecting materials for the temple to be erected by his son and successor. It is not, therefore, his general afflictions which are here meant, but his anxiety, and his efforts to secure a lasting place for the worship of God.', NULL, NULL, '''1'':134,138 ''22'':140 ''3'':137 ''5'':136 ''8'':141 ''accomplished.and'':51 ''afflict'':54,167 ''anxieti'':174 ''ark'':75,95 ''blood'':133 ''bring'':92 ''build'':104,117 ''call'':4,25 ''care'':63,144 ''caus'':36 ''chronicl'':139 ''collect'':148 ''david'':3 ''effort'':177 ''engag'':129 ''erect'':155 ''follow'':89 ''frustrat'':40 ''general'':166 ''god'':108,187 ''home'':72 ''hous'':106 ''king'':135 ''labor'':10 ''last'':181 ''lord'':1 ''made'':46 ''man'':123 ''materi'':149 ''may'':37,49 ''meant'':171 ''mere'':82 ''might'':17,68 ''mount'':97 ''order'':14,30,42 ''particular'':56 ''perman'':20 ''permit'':114 ''place'':21,182 ''promis'':45 ''purpos'':33,102 ''refer'':59,81 ''rememb'':2 ''remembr'':6,28 ''scene'':131 ''secur'':179 ''settl'':71 ''sinc'':110 ''son'':158 ''specifi'':86 ''successor'':160 ''templ'':152 ''therefor'':164 ''thi'':23,35 ''toil'':65,146 ''trial'':12,57 ''use'':78 ''vers'':90 ''war'':125 ''word'':77 ''worship'':24,185 ''would'':79 ''zeal'':8 ''zion'':98', NULL, '610');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('611', '2', '611', NULL, 'Behold - As if he looked upon such a gathering, and saw there the expressions of mutual love. This may have been uttered in the actual contemplation of such an assemblage; or it may have been a picture of the imagination.How good - How good in itself; how proper; how suited to promote happiness, and to diffuse good influences abroad.And how pleasant - The word used here means lovely, charming, attractive; that which fills the mind with delight, spoken of one beloved, Sol 7:6; of a friend, 2 Samuel 1:26; of a place, Genesis 49:15; of words, Proverbs 15:26; of beauty or glory, as of Yahweh, Psalm 27:4. It is descriptive of the pleasure which we derive from a picture, from a landscape, from sweet sounds and gentle voices, or from love.For brethren to dwell together in unity - Margin, even together. Hebrew, "The dwelling of brethren also together." Perhaps the idea in the word "also" may be, that while the unity of brethren when separate, or as they were seen when scattered in their habitations, was beautiful, it was also pleasant to see them when actually assembled, or when they actually came together to worship God. As applicable to the church, it may be remarked(1) that all the people of God - all the followers of the Redeemer - are brethren, members of the same family, fellow-heirs of the same inheritance, Matthew 23:8.(2) There is a special fitness that they should be united, or dwell in unity.(3) There is much that is beautiful and lovely in their unity and harmony. They are redeemed by the same Saviour; they serve the same Master; they cherish the same hope; they are looking forward to the same heaven; they are subject to the same trials, temptations, and sorrows; they have the same precious consolations. There is, therefore, the beauty, the "goodness," the "pleasantness" of obvious fitness and propriety in their dwelling together in unity.(4) Their unity is adapted to produce an important influence on the world, John 17:21. No small part of the obstructions to the progress of religion in the world has been caused by the strifes and contentions of the professed friends of God. A new impulse would be given at once to the cause of religion if all the followers of the Lord Jesus acted in harmony: if every Christian would properly recognize every other Christian as his brother; if every true church would recognize every other church as a church; if all ministers of the Gospel would recognize all other ministers as such; and if all who are Christians, and who walk worthy of the Christian name, were admitted freely to partake with all others in the solemn ordinance which commemorates the Saviour''s dying love. Until this is done, all that is said about Christian union in the church is a subject of just derision to the world - for how can there be union when one class of ministers refuse to recognize the Christian standing, and the validity of the acts, of other ministers of the Lord Jesus - when one part of the Christian church solemnly refuses to admit another portion to the privileges of the Lord''s table - when by their actions large portions of the professed followers of the Redeemer regard and treat others as having no claims to a recognition as belonging to the church of God, and as left for salvation to his "uncovenanted mercies."', NULL, NULL, '''1'':88,208 ''15'':95,99 ''17'':342 ''2'':86,238 ''21'':343 ''23'':236 ''26'':89,100 ''27'':109 ''3'':253 ''4'':110,328 ''49'':94 ''6'':82 ''7'':81 ''8'':237 ''abroad.and'':58 ''act'':393,511 ''action'':543 ''actual'':25,188,193 ''adapt'':332 ''admit'':448,529 ''also'':149,157,182 ''anoth'':530 ''applic'':200 ''assembl'':189 ''assemblag'':30 ''attract'':68 ''beauti'':102,179,259,312 ''behold'':1 ''belong'':565 ''belov'':79 ''brethren'':135,148,165,222 ''brother'':407 ''came'':194 ''caus'':360,382 ''charm'':67 ''cherish'':