INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('711', '2', '711', NULL, 'Behold, a king - That is, Hezekiah. That it refers to him is apparent from the connection. The reign of Ahaz had been one of oppression and idolatry. This was to be succeeded by the reign of one under whom the rights of the people would be secured, and under whom there would be a state of general prosperity. This may have been uttered while Ahaz was on the throne, or it may have been when Hezekiah began to reign. Perhaps the latter is the more probable, as Ahaz might not have tolerated anything that would have looked like a reflection on his own reign; nor, perhaps, while he was on the throne would Isaiah have given a description that would have been a contrast between his reign and that of his successor.Shall reign in righteousness - That is, a righteous king shall reign; or his administration shall be one of justice, and strongly in contrast with that of his predecessor. This was certainly the general characteristic of the reign of Hezekiah.And princes shall rule - Hebrew, ''For princes, or, ''as to princes'' (  les''arym). Lowth proposes to read this without the   (l), as the ancient versions do. But it is not necessary to change the text. It may be rendered, ''As to princes, they shall rule'' (compare Psalm 16:3). The ''princes'' here denote the various officers of government, or those to whom the administration was confided.In judgment - That this is a just description of the reign of Hezekiah is apparent from the history, see 2 Kings 18:3-6 : ''He removed the high places, and broke the images, and cut down the grove. He trusted in the Lord God of Israel, so that after him was none like him among all the kings of Judah, nor any that were before him, for he clave unto the Lord, and departed not from following him.''', NULL, NULL, '''-6'':258 ''16'':217 ''18'':256 ''2'':254 ''3'':218,257 ''administr'':145,233 ''ahaz'':20,65,88 ''among'':289 ''ancient'':193 ''anyth'':93 ''appar'':13,249 ''arym'':182 ''began'':77 ''behold'':1 ''broke'':265 ''certain'':162 ''chang'':202 ''characterist'':165 ''clave'':303 ''compar'':215 ''confided.in'':235 ''connect'':16 ''contrast'':124,154 ''cut'':269 ''denot'':222 ''depart'':308 ''descript'':118,242 ''follow'':311 ''general'':57,164 ''given'':116 ''god'':278 ''govern'':227 ''grove'':272 ''hebrew'':174 ''hezekiah'':6,76,247 ''hezekiah.and'':170 ''high'':262 ''histori'':252 ''idolatri'':27 ''imag'':267 ''isaiah'':114 ''israel'':280 ''judah'':294 ''judgment'':236 ''justic'':150 ''king'':3,140,255,292 ''l'':190 ''latter'':82 ''les'':181 ''like'':98,287 ''look'':97 ''lord'':277,306 ''lowth'':183 ''may'':60,72,206 ''might'':89 ''necessari'':200 ''none'':286 ''offic'':225 ''one'':23,37,148 ''oppress'':25 ''peopl'':44 ''perhap'':80,106 ''place'':263 ''predecessor'':159 ''princ'':171,176,180,211,220 ''probabl'':86 ''propos'':184 ''prosper'':58 ''psalm'':216 ''read'':186 ''refer'':9 ''reflect'':100 ''reign'':18,35,79,104,127,133,142,168,245 ''remov'':260 ''render'':208 ''right'':41 ''righteous'':135,139 ''rule'':173,214 ''secur'':47 ''see'':253 ''shall'':141,146,172,213 ''state'':55 ''strong'':152 ''succeed'':32 ''successor.shall'':132 ''text'':204 ''throne'':69,112 ''toler'':92 ''trust'':274 ''unto'':304 ''utter'':63 ''various'':224 ''version'':194 ''without'':188 ''would'':45,52,95,113,120', NULL, '711');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('171', '2', '171', NULL, 'Better, "there shall not be to the priests, the Levites, yea the whole tribe of Levi, any inheritance, etc."And his inheritance - i. e., God''s inheritance, that which in making a grant to His people of the promised land with its earthly blessings He had reserved for Himself; more particularly the sacrifices and the holy gifts, such as tithes and first-fruits. These were God''s portion of the substance of Israel; and as the Levites were His portion of the persons of Israel, it was fitting that the Levites should be sustained from these. On the principle here laid down, compare 1 Corinthians 9:13-14.', NULL, NULL, '''-14'':109 ''1'':105 ''13'':108 ''9'':107 ''better'':1 ''bless'':44 ''compar'':104 ''corinthian'':106 ''e'':24 ''earth'':43 ''etc'':19 ''first'':63 ''first-fruit'':62 ''fit'':89 ''fruit'':64 ''gift'':57 ''god'':25,67 ''grant'':33 ''holi'':56 ''inherit'':18,22,27 ''israel'':74,86 ''laid'':102 ''land'':40 ''levi'':16 ''levit'':10,78,92 ''make'':31 ''particular'':51 ''peopl'':36 ''person'':84 ''portion'':69,81 ''priest'':8 ''principl'':100 ''promis'':39 ''reserv'':47 ''sacrific'':53 ''shall'':3 ''substanc'':72 ''sustain'':95 ''tith'':60 ''tribe'':14 ''whole'':13 ''yea'':11', NULL, '171');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('179', '2', '179', NULL, 'Two liturgical enactments having a clear and close reference to the whole of the preceding legislation, form a most appropriate and significant conclusion to it, namely,(1) the formal acknowledgment in deed and symbol of God''s faithfulness, by presentment of a basket filled with firstfruits, and in word by recitation of the solemn formula prescribed in Deuteronomy 26:3, Deuteronomy 26:5-10; and(2) the solemn declaration and profession on the part of each Israelite on the occasion of the third tithe Deuteronomy 26:12.', NULL, NULL, '''-10'':64 ''1'':27 ''12'':87 ''2'':66 ''26'':59,62,86 ''3'':60 ''5'':63 ''acknowledg'':30 ''appropri'':20 ''basket'':43 ''clear'':6 ''close'':8 ''conclus'':23 ''declar'':69 ''deed'':32 ''deuteronomi'':58,61,85 ''enact'':3 ''faith'':38 ''fill'':44 ''firstfruit'':46 ''form'':17 ''formal'':29 ''formula'':55 ''god'':36 ''israelit'':77 ''legisl'':16 ''liturg'':2 ''name'':26 ''occas'':80 ''part'':74 ''preced'':15 ''prescrib'':56 ''present'':40 ''profess'':71 ''recit'':51 ''refer'':9 ''signific'':22 ''solemn'':54,68 ''symbol'':34 ''third'':83 ''tith'':84 ''two'':1 ''whole'':12 ''word'':49', NULL, '179');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1242', '2', '1242', NULL, 'But speak thou - In thine own ministry. In the previous chapter he had given him instructions as to the kind of persons who were to be put into the sacred office. Here he gives him special instructions in regard to his own preaching. "The things which become sound doctrine." To wit, those which he proceeds immediately to specify. On the phrase sound doctrine, see the notes at 1 Timothy 1:10; compare 2 Timothy 4:3.', NULL, NULL, '''1'':68,70 ''10'':71 ''2'':73 ''3'':76 ''4'':75 ''becom'':47 ''chapter'':11 ''compar'':72 ''doctrin'':49,63 ''give'':34 ''given'':14 ''immedi'':56 ''instruct'':16,37 ''kind'':20 ''ministri'':7 ''note'':66 ''offic'':31 ''person'':22 ''phrase'':61 ''preach'':43 ''previous'':10 ''proceed'':55 ''put'':27 ''regard'':39 ''sacr'':30 ''see'':64 ''sound'':48,62 ''speak'':2 ''special'':36 ''specifi'':58 ''thine'':5 ''thing'':45 ''thou'':3 ''timothi'':69,74 ''wit'':51', NULL, '1131');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('731', '2', '731', NULL, 'Awake, awake - (See the notes at Isaiah 51:9). This address to Jerusalem is intimately connected with the closing verses of the preceding chapter. Jerusalem is there represented as down-trodden in the dust before her enemies. Here she is described under the image of a female that had been clad in the habiliments of mourning, and she is now called on to arise from this condition, and to put on the garments that would be indicative of gladness and of joy. The idea is, that the time had come now in which she was to be delivered from her long captivity, and was to be restored to her former prosperity and splendor.Put on thy strength - Hebrew, ''Clothe thyself with thy strength.'' The idea is, exert thyself, be strong, bold, confident; arise from thy dejection, and become courageous as one does when he is about to engage in an enterprise that promises success, and that demands effort.Put on thy beautiful garments - Jerusalem is here addressed, as she often is, as a female (see the note at Isaiah 1:8). She was to lay aside the garments expressive of grief and of captivity, and deck herself with those which were appropriate to a state of prosperity.The uncircumcised and the unclean - The idea is, that those only should enter Jerusalem and dwell there who would be worshippers of the true God. The uncircumcised are emblems of the impure, the unconverted, and the idolatrous; and the meaning is, that in future times the church would be pure and holy. It cannot mean that no uncircumcised man or idolater would ever again enter the city of Jerusalem, for this would not be true. It was a fact that Antiochus and his armies, and Titus and his army entered Jerusalem, and undoubtedly hosts of others did also who were not circumcised. But this refers to the future times, when the church of God would be pure. Its members would, in the main, be possessors of the true religion, and would adorn it. Probably, therefore, the view of the prophet extended to the purer and happier times under the Messiah, when the church should be characteristically and eminently holy, and when, as a great law of that church, none should be admitted, who did not profess that they were converted.', NULL, NULL, '''1'':179 ''51'':8 ''8'':180 ''9'':9 ''address'':11,166 ''admit'':377 ''adorn'':337 ''also'':303 ''antiochus'':286 ''appropri'':201 ''aris'':65,133 ''armi'':289,294 ''asid'':185 ''awak'':1,2 ''beauti'':161 ''becom'':138 ''bold'':131 ''call'':62 ''cannot'':259 ''captiv'':103,193 ''chapter'':24 ''characterist'':361 ''church'':252,317,358,373 ''circumcis'':307 ''citi'':272 ''clad'':52 ''close'':19 ''cloth'':119 ''come'':91 ''condit'':68 ''confid'':132 ''connect'':16 ''convert'':385 ''courag'':139 ''deck'':195 ''deject'':136 ''deliv'':99 ''demand'':157 ''describ'':42 ''down-trodden'':30 ''dust'':35 ''dwell'':221 ''effort.put'':158 ''emblem'':234 ''emin'':363 ''enemi'':38 ''engag'':148 ''enter'':218,270,295 ''enterpris'':151 ''ever'':268 ''exert'':127 ''express'':188 ''extend'':346 ''fact'':284 ''femal'':48,173 ''former'':111 ''futur'':249,313 ''garment'':74,162,187 ''glad'':80 ''god'':230,319 ''great'':369 ''grief'':190 ''habili'':55 ''happier'':351 ''hebrew'':118 ''holi'':257,364 ''host'':299 ''idea'':85,125,212 ''idolat'':266 ''idolatr'':242 ''imag'':45 ''impur'':237 ''indic'':78 ''intim'':15 ''isaiah'':7,178 ''jerusalem'':13,25,163,219,274,296 ''joy'':83 ''law'':370 ''lay'':184 ''long'':102 ''main'':328 ''man'':264 ''mean'':245,260 ''member'':324 ''messiah'':355 ''mourn'':57 ''none'':374 ''note'':5,176 ''often'':169 ''one'':141 ''other'':301 ''possessor'':330 ''preced'':23 ''probabl'':339 ''profess'':381 ''promis'':153 ''prophet'':345 ''prosper'':112 ''prosperity.the'':206 ''pure'':255,322 ''purer'':349 ''put'':71 ''refer'':310 ''religion'':334 ''repres'':28 ''restor'':108 ''see'':3,174 ''splendor.put'':114 ''state'':204 ''strength'':117,123 ''strong'':130 ''success'':154 ''therefor'':340 ''thi'':116,122,135,160 ''thyself'':120,128 ''time'':89,250,314,352 ''titus'':291 ''trodden'':32 ''true'':229,280,333 ''uncircumcis'':207,232,263 ''unclean'':210 ''unconvert'':239 ''undoubt'':298 ''vers'':20 ''view'':342 ''worshipp'':226 ''would'':76,224,253,267,277,320,325,336', NULL, '731');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('732', '2', '732', NULL, 'He was oppressed - (  niggas''). Lowth renders this, ''It was exacted.'' Hengstenberg, ''He was abased.'' Jerome (the Vulgate), ''He was offered because he was willing.'' The Septuagint ''He, on account of his affliction, opened not his mouth,'' implying that his silence arose from the extremity of his sorrows. The Chaldee renders it, ''He prayed, and he was heard, and before he opened his mouth he was accepted.'' The Syriac, ''He came and humbled himself, neither did he open his mouth.'' Kimchi supposes that it means, ''it was exacted;'' and that it refers to the fact that taxes were demanded of the exiles, when they were in a foreign land. The word used here (  nagas'') properly means, "to drive," to impel, to urge; and then to urge a debtor, to exact payment; or to exact tribute, a ransom, etc. (see Deuteronomy 15:2-3; 2 Kings 23:35.) Compare Job 3:18; Zechariah 9:8; Zechariah 10:4, where one form of the word is rendered ''oppressor;'' Job 39:7, the ''driver;'' Exodus 5:6, ''taskmasters;'' Daniel 11:20, ''a raiser of taxes.'' The idea is that of urgency, oppression, vexation, of being hard pressed, and ill treated. It does not refer here necessarily to what was exacted by God, or to sufferings inflicted by him - though it may include those - but it refers to all his oppressions, and the severity of his sufferings from all quarters. He was urged impelled, oppressed, and yet he was patient as a lamb.And he was afflicted - Jahn and Steudel propose to render this, ''He suffered himself to be afflicted.'' Hengstenberg renders it, ''He suffered patiently, and opened not his mouth.'' Lowth, ''He was made answerable; and he opened not his mouth.'' According to this, the idea is, that he had voluntarily taken upon himself the sins of people, and that having done so, he was held answerable as a surety. But it is doubtful whether the Hebrew will bear this construction. According to Jerome, the idea is that he voluntarily submitted, and that this was the cause of his sufferings. Hensler renders it, ''God demands the debt, and he the great and righteous one suffers.'' It is probable, however, that our translation has retained the correct sense. The word   anah, in Niphil, means to be afflicted, to suffer, be oppressed or depressed Psalm 119:107, and the idea here is, probably, that he was greatly distressed and afflicted. He was subjected to pains and sorrows which were hard to be borne, and which are usually accompanied with expressions of impatience and lamentation. The fact that he did not open his mouth in complaint was therefore the more remarkable, and made the merit of his sufferings the greater.Yet he opened not his mouth - This means that he was perfectly quiet, meek, submissive, patient, He did not open his mouth to complain of God on account of the great sorrows which he had appointed to him; nor to God on account of his being ill-treated by man. He did not use the language of reviling when he was reviled, nor return upon people the evils which they were inflicting on him (compare Psalm 39:9). How strikingly and literally was this fulfilled in the life of the Lord Jesus! It would seem almost as if it had been written after he lived, and was history rather than prophecy. In no other instance was there ever so striking an example of perfect patience; no other person ever so entirely accorded with the description of the prophet.He is brought as a lamb to the slaughter - This does not mean that he was led to the slaughter as a lamb is, but that as a lamb which is led to be killed is patient and silent, so was he. He made no resistance. He uttered no complaint. He suffered himself to be led quietly along to be put to death. What a striking and beautiful description! How tender and how true! We can almost see here the meek and patient Redeemer led along without resistance; and amidst the clamor of the multitude that were assembled with various feelings to conduct him to death, himself perfectly silent and composed. With all power at his disposal, yet as quiet and gentle as though he had no power; and with a perfect consciousness that he was going to die, as calm and as gentle as though he were ignorant of the design for which they were leading him forth. This image occurs also in Jeremiah, Jeremiah 11:19, ''But I was like a lamb or an ox that is brought to the slaughter.''As a sheep - As a sheep submits quietly to the operation of shearing. Compare 1 Peter 2:23, ''Who when he was reviled, reviled not again.'' Jesus never opened his mouth to revile or complain. It was opened only to bless those that cursed him, and to pray for his enemies and murderers.', NULL, NULL, '''-3'':142 ''1'':787 ''10'':155 ''107'':390 ''11'':176,756 ''119'':389 ''15'':140 ''18'':150 ''19'':757 ''2'':141,143,789 ''20'':177 ''23'':145,790 ''3'':149 ''35'':146 ''39'':167,529 ''4'':156 ''5'':172 ''6'':173 ''7'':168 ''8'':153 ''9'':152,530 ''abas'':14 ''accept'':66 ''accompani'':421 ''accord'':287,327,584 ''account'':29,479,494 ''afflict'':32,251,264,381,403 ''almost'':548,666 ''along'':647,675 ''also'':752 ''amidst'':679 ''anah'':375 ''answer'':280,312 ''appoint'':487 ''aros'':41 ''assembl'':687 ''bear'':324 ''beauti'':657 ''bless'':813 ''born'':416 ''brought'':592,769 ''calm'':730 ''came'':70 ''caus'':342 ''chalde'':49 ''clamor'':681 ''compar'':147,527,786 ''complain'':475,807 ''complaint'':438,639 ''compos'':700 ''conduct'':692 ''conscious'':722 ''construct'':326 ''correct'':371 ''curs'':816 ''daniel'':175 ''death'':652,695 ''debt'':352 ''debtor'':127 ''demand'':98,350 ''depress'':387 ''descript'':587,658 ''design'':741 ''deuteronomi'':139 ''die'':728 ''dispos'':706 ''distress'':401 ''done'':307 ''doubt'':319 ''drive'':117 ''driver'':170 ''enemi'':823 ''entir'':583 ''etc'':137 ''ever'':570,581 ''evil'':520 ''exact'':10,87,129,133,206 ''exampl'':574 ''exil'':10