INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('784', '2', '784', NULL, '"The Capture of Jerusalem" - The majority of the particulars given in Jeremiah 39:1-14 occur again (marginal reference); and are by some regarded as an interpolation. The external evidence (that of the versions) is, however, in favor of their authenticity. Jeremiah 39:14 is to be reconciled with Jeremiah 40:1-4 by remembering that Gedaliah had left Jerusalem and gone to Mizpah Jeremiah 40:6, a city in the immediate neighborhood; and as he was not at home to protect the prophet, nothing is more probable than that Jeremiah in company with the main body of captives was brought to Ramah in chains.', NULL, NULL, '''-14'':15 ''-4'':53 ''1'':14,52 ''14'':44 ''39'':13,43 ''40'':51,66 ''6'':67 ''authent'':41 ''bodi'':97 ''brought'':101 ''captiv'':99 ''captur'':2 ''chain'':105 ''citi'':69 ''compani'':93 ''evid'':30 ''extern'':29 ''favor'':38 ''gedaliah'':57 ''given'':10 ''gone'':62 ''home'':80 ''howev'':36 ''immedi'':72 ''interpol'':27 ''jeremiah'':12,42,50,65,91 ''jerusalem'':4,60 ''left'':59 ''main'':96 ''major'':6 ''margin'':18 ''mizpah'':64 ''neighborhood'':73 ''noth'':85 ''occur'':16 ''particular'':9 ''probabl'':88 ''prophet'':84 ''protect'':82 ''ramah'':103 ''reconcil'':48 ''refer'':19 ''regard'':24 ''rememb'':55 ''version'':34', NULL, '784');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('785', '2', '785', NULL, 'As what follows is mainly a historical narrative, it seems that the title "The word ..." was appropriate not merely to a prediction of the future, but to an account of the past, if written by a prophet. The Jews regarded history as inspired if written by a seer, and thus their historical books are called "the early prophets."Ramah - Probably all the prisoners of note were collected at Ramah indiscriminately, and examined there.Bound in chains - The prisoners were probably fastened together in couples by one hand, and a rope passed down the center to bind them in a long line, and prevent attempts at escape.', NULL, NULL, '''account'':29 ''appropri'':17 ''attempt'':103 ''bind'':95 ''book'':53 ''call'':55 ''center'':93 ''chain'':75 ''collect'':67 ''coupl'':83 ''earli'':57 ''escap'':105 ''examin'':72 ''fasten'':80 ''follow'':3 ''futur'':25 ''hand'':86 ''histor'':7,52 ''histori'':41 ''indiscrimin'':70 ''inspir'':43 ''jew'':39 ''line'':100 ''long'':99 ''main'':5 ''mere'':19 ''narrat'':8 ''note'':65 ''one'':85 ''pass'':90 ''past'':32 ''predict'':22 ''prevent'':102 ''prison'':63,77 ''probabl'':60,79 ''prophet'':37,58 ''ramah'':59,69 ''regard'':40 ''rope'':89 ''seem'':10 ''seer'':48 ''there.bound'':73 ''thus'':50 ''titl'':13 ''togeth'':81 ''word'':15 ''written'':34,45', NULL, '785');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('545', '2', '545', NULL, 'God be merciful unto us, and bless us - There is, perhaps (as Prof. Alexander suggests), an allusion, in the language used here, to the sacerdotal benediction in Numbers 6:24-26 : "The Lord bless thee, and keep thee; the Lord make his face shine upon thee, and be gracious unto thee: the Lord lift up his countenance upon thee, and give thee peace." The prayer is that God would bestow upon his people the blessing implied in the form of benediction which he had directed the ministers of his religion to use. The first cry is, of course, for mercy or favor. The beginning of all blessings to mankind is the favor or mercy of God. There is no higher blessing than his favor; there is none that comes from him which should not be regarded as mercy.And cause his face to shine upon us - Margin, With us. That is, among us. It is an invocation of his presence and favor. On the phrase "cause his face to shine," see the notes at Psalm 4:6.', NULL, NULL, '''-26'':31 ''24'':30 ''4'':175 ''6'':29,176 ''alexand'':14 ''allus'':17 ''among'':151 ''begin'':104 ''benedict'':26,81 ''bestow'':70 ''bless'':7,34,75,107,121 ''caus'':139,165 ''come'':129 ''counten'':57 ''cours'':98 ''cri'':95 ''direct'':85 ''face'':43,141,167 ''favor'':102,112,124,161 ''first'':94 ''form'':79 ''give'':61 ''god'':1,68,116 ''gracious'':49 ''higher'':120 ''impli'':76 ''invoc'':156 ''keep'':37 ''languag'':20 ''lift'':54 ''lord'':33,40,53 ''make'':41 ''mankind'':109 ''margin'':146 ''merci'':3,100,114 ''mercy.and'':138 ''minist'':87 ''none'':127 ''note'':172 ''number'':28 ''peac'':63 ''peopl'':73 ''perhap'':11 ''phrase'':164 ''prayer'':65 ''presenc'':159 ''prof'':13 ''psalm'':174 ''regard'':136 ''religion'':90 ''sacerdot'':25 ''see'':170 ''shine'':44,143,169 ''suggest'':15 ''thee'':35,38,46,51,59,62 ''unto'':4,50 ''upon'':45,58,71,144 ''us'':5,8,145,148,152 ''use'':21,92 ''would'':69', NULL, '545');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('786', '2', '786', NULL, 'The seventh month - Gedaliah''s government lasted less than two months.Even - Rather, and. Ishmael was descended probably from Elishama the son of David 2 Samuel 5:16. Ten grandees each with his retinue would have aroused suspicion, but the smallness of Ishmael''s following put Gedaliah completely off his guard.', NULL, NULL, '''16'':27 ''2'':24 ''5'':26 ''arous'':36 ''complet'':47 ''david'':23 ''descend'':16 ''elishama'':19 ''follow'':44 ''gedaliah'':4,46 ''govern'':6 ''grande'':29 ''guard'':50 ''ishmael'':14,42 ''last'':7 ''less'':8 ''month'':3 ''months.even'':11 ''probabl'':17 ''put'':45 ''rather'':12 ''retinu'':33 ''samuel'':25 ''seventh'':2 ''small'':40 ''son'':21 ''suspicion'':37 ''ten'':28 ''two'':10 ''would'':34', NULL, '786');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('546', '2', '546', NULL, 'Let God arise - See the notes at Psalm 3:7. There is an obvious reterence here to the words used by Moses on the removal of the ark in Numbers 10:35. The same language was also employed by Solomon when the ark was removed to the temple, and deposited in the most holy place 2 Chronicles 6:41 :" Now therefore arise, O Lord God, into thy resting place, thou, and the ark of thy strength." It would seem probable, therefore, that this psalm was composed on some such occasion.Let his enemies be scattered - So in Numbers 10:35 : "Rise up, Lord, and let thine enemies be scattered; and let them that hate thee flee before thee." The ark was the symbol of the divine presence, and the idea is, that whereever that was, the enemies of God would be subdued, or that it was only by the power of Him who was supposed to reside there that his enemies could be overcome.Let them also that hate him flee before him - Almost the exact language used by Moses in Numbers 10:35. It is possible that this may have been used on some occasion when the Hebrews were going out to war; but the more probable supposition is that it is general language designed to illustrate the power of God, or to state that his rising up, at any time, would be followed by the discomfiture of his enemies. The placing of the ark where it was designed to remain permanently would be a proper occasion for suggesting this general truth, that all the enemies of God must be scattered when he rose up in his majesty and power.', NULL, NULL, '''10'':31,98,181 ''2'':56 ''3'':9 ''35'':32,99,182 ''41'':59 ''6'':58 ''7'':10 ''almost'':172 ''also'':37,165 ''aris'':3,62 ''ark'':28,43,73,119,244 ''chronicl'':57 ''compos'':86 ''could'':161 ''deposit'':50 ''design'':214,248 ''discomfitur'':236 ''divin'':125 ''employ'':38 ''enemi'':92,106,136,160,239,265 ''exact'':174 ''flee'':115,169 ''follow'':233 ''general'':212,260 ''go'':199 ''god'':2,65,138,220,267 ''hate'':113,167 ''hebrew'':197 ''holi'':54 ''idea'':129 ''illustr'':216 ''languag'':35,175,213 ''let'':1,104,110 ''lord'':64,102 ''majesti'':277 ''may'':188 ''mose'':22,178 ''must'':268 ''note'':6 ''number'':30,97,180 ''o'':63 ''obvious'':14 ''occas'':194,256 ''occasion.let'':90 ''overcome.let'':163 ''perman'':251 ''place'':55,69,241 ''possibl'':185 ''power'':149,218,279 ''presenc'':126 ''probabl'':80,206 ''proper'':255 ''psalm'':8,84 ''remain'':250 ''remov'':25,45 ''resid'':156 ''rest'':68 ''reter'':15 ''rise'':100,226 ''rose'':273 ''scatter'':94,108,270 ''see'':4 ''seem'':79 ''solomon'':40 ''state'':223 ''strength'':76 ''subdu'':141 ''suggest'':258 ''suppos'':154 ''supposit'':207 ''symbol'':122 ''templ'':48 ''thee'':114,117 ''therefor'':61,81 ''thi'':67,75 ''thine'':105 ''thou'':70 ''time'':230 ''truth'':261 ''use'':20,176,191 ''war'':202 ''whereev'':132 ''word'':19 ''would'':78,139,231,252', NULL, '546');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('547', '2', '547', NULL, 'I am weary of my crying - The word "crying" here does not mean weeping, or shedding tears, but calling upon God for help. He had grown weary; his strength had been exhausted in the act of calling upon God to assist him. See the notes at Psalm 6:6. This was an instance where one had called so long on God, and prayed so much and so earnestly, that his strength was gone. Compare Matthew 26:41.My throat is dried - Or, "is parched up." The Hebrew word denotes to burn; to be enkindled; and then, to be inflamed. Here it means that by the excessive exertion of his voice, his throat had become parched, so that he could not speak.Mine eyes fail - That is, become dim from exhaustion. I have looked so long in that one direction that the power of vision begins to fail, and I see nothing clearly. See the notes at Psalm 6:7. Compare Job 17:7; Psalm 31:9; Psalm 38:10.While I wait for my God - That is, by continued "looking" to God. The word "wait" is not used here, nor is it generally in the Bible, as it is now with us, in the sense of looking for "future" interposition, or of doing nothing ourselves in expectation of what "may" occur; but it is used in the sense of looking to God alone; of exercising dependence on him; of seeking his aid. This is indeed connnected with the ordinary idea of abiding his will, but it is also an "active" state of mind - a state expressive of intense interest and desire. See the notes at Psalm 62:5.', NULL, NULL, '''10.while'':167 ''17'':160 ''26'':76 ''31'':163 ''38'':166 ''41.my'':77 ''5'':275 ''6'':48,49,156 ''62'':274 ''7'':157,161 ''9'':164 ''abid'':249 ''act'':35 ''activ'':257 ''aid'':239 ''alon'':230 ''also'':255 ''assist'':41 ''becom'':113,125 ''begin'':143 ''bibl'':193 ''burn'':90 ''call'':19,37,57 ''clear'':150 ''compar'':74,158 ''connnect'':243 ''continu'':176 ''could'':118 ''cri'':6,9 ''denot'':88 ''depend'':233 ''desir'':268 ''dim'':126 ''direct'':137 ''dri'':80 ''earnest'':68 ''enkindl'':93 ''excess'':105 ''exercis'':232 ''exert'':106 ''exhaust'':32,128 ''expect'':214 ''express'':263 ''eye'':121 ''fail'':122,145 ''futur'':206 ''general'':190 ''god'':21,39,61,172,179,229 ''gone'':73 ''grown'':26 ''hebrew'':86 ''help'':23 ''idea'':247 ''inde'':242 ''inflam'':98 ''instanc'':53 ''intens'':265 ''interest'':266 ''interposit'':207 ''job'':159 ''long'':59,133 ''look'':131,177,204,227 ''matthew'':75 ''may'':217 ''mean'':13,101 ''mind'':260 ''much'':65 ''note'':45,153,271 ''noth'':149,211 ''occur'':218 ''one'':55,136 ''ordinari'':246 ''parch'':83,114 ''power'':140 ''pray'':63 ''psalm'':47,155,162,165,273 ''see'':43,148,151,269 ''seek'':237 ''sens'':202,225 ''shed'':16 ''speak.mine'':120 ''state'':258,262 ''strength'':29,71 ''tear'':17 ''throat'':78,111 ''upon'':20,38 ''us'':199 ''use'':185,222 ''vision'':142 ''voic'':109 ''wait'':169,182 ''weari'':3,27 ''weep'':14 ''word'':8,87,181', NULL, '547');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('548', '2', '548', NULL, 'Make haste - These words are supplied by our translators. The first word in Psalm 40:13, rendered "be pleased," is here omitted in the original. The psalm in the Hebrew begins abruptly - "O God, to deliver me," - leaving the impression that this is a fragment - a fragment commencing without even the care necessary to make the grammatical construction complete.O God - Hebrew,   ''Elohiym. In the corresponding place in Psalm 40:13 the word is "Yahweh." Why the change was made is unknown. The remainder of the verse is the same as in Psalm 40.', NULL, NULL, '''13'':16,70 ''40'':15,69,93 ''abrupt'':32 ''begin'':31 ''care'':52 ''chang'':77 ''commenc'':48 ''complete.o'':59 ''construct'':58 ''correspond'':65 ''deliv'':36 ''elohiym'':62 ''even'':50 ''first'':11 ''fragment'':45,47 ''god'':34,60 ''grammat'':57 ''hast'':2 ''hebrew'':30,61 ''impress'':40 ''leav'':38 ''made'':79 ''make'':1,55 ''necessari'':53 ''o'':33 ''omit'':22 ''origin'':25 ''place'':66 ''pleas'':19 ''psalm'':14,27,68,92 ''remaind'':83 ''render'':17 ''suppli'':6 ''translat'':9 ''unknown'':81 ''vers'':86 ''without'':49 ''word'':4,12,72 ''yahweh'':74', NULL, '548');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('549', '2', '549', NULL, 'In thee, O Lord, do I put my trust - See the notes at Psalm 25:2. Compare Psalm 22:4-5; Psalm 31:1.Let me never be put to confusion - Let me never be ashamed; that is, Let me not be so disappointed in the trust that I repose in thee as to have occasion to feel ashamed that I have done it.', NULL, NULL, '''-5'':21 ''1.let'':24 ''2'':16 ''22'':19 ''25'':15 ''31'':23 ''4'':20 ''asham'':35,58 ''compar'':17 ''confus'':30 ''disappoint'':43 ''done'':62 ''feel'':57 ''let'':31,38 ''lord'':4 ''never'':26,33 ''note'':12 ''o'':3 ''occas'':55 ''psalm'':14,18,22 ''put'':7,28 ''repos'':49 ''see'':10 ''thee'':2,51 ''trust'':9,46', NULL, '549');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('550', '2', '550', NULL, 'Give the king - Supposing the psalm to have been composed by David in view of the inauguration of his son and successor, this is a prayer that God would bestow on him the qualifications which would tend to secure a just, a protracted, and a peaceful reign. Though it is to be admitted that the psalm was designed to refer ultimately to the Messiah, and to be descriptive of "his" reign, yet there is no impropriety in supposing that the psalmist believed the reign of Solomon would be, in some proper sense emblematic of that reign, and that it was his desire the reign of the one "might," as far as possible, resemble that of the other. There is no improbability, therefore, in supposing that the mind of the psalmist might have been directed to both in the composition of the psalm, and that while he used the language of prayer for the one, his eye was mainly directed to the characteristics of the other.Thy judgments - Knowledge; authority; ability to execute thy judgments, or thy laws. That is, he speaks of the king as appointed to administer justice; to maintain the laws of God, and to exercise judicial power. It is one of the primary ideas in the character of a king that he is the fountain of justice; the maker of the laws; the dispenser of right to all his subjects. The officers of the law administer justice "under" him; the last appeal is to him.And thy righteousness - That is, Clothe him, in the administration of justice, with a righteousness like thine own. Let it be seen that he represents "thee;" that his government may be regarded as thine own administration through him.Unto the king''s son - Not only to him, but to his successor; that is, let the administration of justice in the government be perpetuated. There is no improbability in supposing that in this the psalmist may have designed also to refer to the last and the greatest of his successors in the line - the Messiah.', NULL, NULL, '''abil'':169 ''administ'':187,238 ''administr'':256,282,301 ''admit'':53 ''also'':323 ''appeal'':244 ''appoint'':185 ''author'':168 ''believ'':82 ''bestow'':30 ''charact'':209 ''characterist'':162 ''cloth'':252 ''compos'':10 ''composit'':139 ''david'':12 ''descript'':68 ''design'':58,322 ''desir'':102 ''direct'':134,159 ''dispens'':226 ''emblemat'':93 ''execut'':171 ''exercis'':197 ''eye'':156 ''far'':110 ''fountain'':217 ''give'':1 ''god'':28,194 ''govern'':275,306 ''greatest'':331 ''him.and'':247 ''him.unto'':284 ''idea'':206 ''improb'':121,312 ''improprieti'':76 ''inaugur'':17 ''judgment'':166,173 ''judici'':198 ''justic'':188,219,239,258,303 ''king'':3,183,212,286 ''knowledg'':167 ''languag'':149 ''last'':243,328 ''law'':176,192,224,237 ''let'':265,299 ''like'':262 ''line'':337 ''main'':158 ''maintain'':190 ''maker'':221 ''may'':276,320 ''messiah'':64,339 ''might'':108,131 ''mind'':127 ''offic'':234 ''one'':107,154,202 ''other.thy'':165 ''peac'':46 ''perpetu'':308 ''possibl'':112 ''power'':199 ''prayer'':26,151 ''primari'':205 ''proper'':91 ''protract'':43 ''psalm'':6,56,142 ''psalmist'':81,130,319 ''qualif'':34 ''refer'':60,325 ''regard'':278 ''reign'':47,71,84,96,104 ''repres'':271 ''resembl'':113 ''right'':228 ''righteous'':249,261 ''secur'':39 ''seen'':268 ''sens'':92 ''solomon'':86 ''son'':20,288 ''speak'':180 ''subject'':232 ''successor'':22,296,334 ''suppos'':4,78,124,314 ''tend'':37 ''thee'':272 ''therefor'':122 ''thi'':172,175,248 ''thine'':263,280 ''though'':48 ''ultim'':61 ''use'':147 ''view'':14 ''would'':29,36,87 ''yet'':72', NULL, '550');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('556', '2', '556', NULL, 'Give ear, O my people - This is not an address of God, but an address of the king or ruler of the people, calling their attention to an important subject; to wit, his right to rule over them, or showing why the power had been vested in him.To my law - The word law here seems to mean what he would say, as if what he should choose to say would have the force and authority of law. What follows is not exactly law in the sense that it was a rule to be obeyed; but it is something that is authoritatively said, and should have the force of law.Incline your ears ... - Be attentive. What is to be said is worthy of your particular regard. Compare the notes at Psalm 5:1.', NULL, NULL, '''1'':131 ''5'':130 ''address'':10,15 ''attent'':26,113 ''author'':75 ''authorit'':101 ''call'':24 ''choos'':67 ''compar'':125 ''ear'':2,111 ''exact'':82 ''follow'':79 ''forc'':73,107 ''give'':1 ''god'':12 ''him.to'':48 ''import'':29 ''king'':18 ''law'':50,53,77,83 ''law.incline'':109 ''mean'':57 ''note'':127 ''o'':3 ''obey'':94 ''particular'':123 ''peopl'':5,23 ''power'':43 ''psalm'':129 ''regard'':124 ''right'':34 ''rule'':36,91 ''ruler'':20 ''said'':102,118 ''say'':61,69 ''seem'':55 ''sens'':86 ''show'':40 ''someth'':98 ''subject'':30 ''vest'':46 ''wit'':32 ''word'':52 ''worthi'':120 ''would'':60,70', NULL, '556');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('787', '2', '787', NULL, 'Among those delivered by Johanan from Ishmael had been Jeremiah and Baruch Jeremiah 43:6; and to them now all, without exception, come for counsel.Jezaniah - He is called Azariah in Jeremiah 43:2. The Septuagint, in both places, call him Azariah. Since there is little reason for identifying him with Jezaniah the Maachathite Jeremiah 40:8, it is probable that the Septuagint is right in calling him in both places Azariah, and that the reading Jezaniah arose from some scribe assuming that his name must be found in the earlier list.', NULL, NULL, '''2'':33 ''40'':55 ''43'':14,32 ''6'':15 ''8'':56 ''among'':1 ''aros'':77 ''assum'':81 ''azariah'':29,41,71 ''baruch'':12 ''call'':28,39,66 ''come'':23 ''counsel.jezaniah'':25 ''deliv'':3 ''earlier'':90 ''except'':22 ''found'':87 ''identifi'':48 ''ishmael'':7 ''jeremiah'':10,13,31,54 ''jezaniah'':51,76 ''johanan'':5 ''list'':91 ''littl'':45 ''maachathit'':53 ''must'':85 ''name'':84 ''place'':38,70 ''probabl'':59 ''read'':75 ''reason'':46 ''right'':64 ''scribe'':80 ''septuagint'':35,62 ''sinc'':42 ''without'':21', NULL, '787');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('788', '2', '788', NULL, 'These captains belonged to the party who had all along resisted Jeremiah''s counsels, and had led Zedekiah astray. Now however that events had proved that the prophet''s counsels had been wise and true, they cannot for shame find fault with him, but they affirm that he is under the influence of Baruch, a traitor who has sold himself to the Chaldaeans, and seeks only the hurt of the people.These captains belonged to the party who had all along resisted Jeremiah''s counsels, and had led Zedekiah astray. Now however that events had proved that the prophet''s counsels had been wise and true, they cannot for shame find fault with him, but they affirm that he is under the influence of Baruch, a traitor who has sold himself to the Chaldaeans, and seeks only the hurt of the people.', NULL, NULL, '''affirm'':46,116 ''along'':10,80 ''astray'':19,89 ''baruch'':54,124 ''belong'':3,73 ''cannot'':37,107 ''captain'':2,72 ''chaldaean'':63,133 ''counsel'':14,30,84,100 ''event'':23,93 ''fault'':41,111 ''find'':40,110 ''howev'':21,91 ''hurt'':68,138 ''influenc'':52,122 ''jeremiah'':12,82 ''led'':17,87 ''parti'':6,76 ''peopl'':141 ''people.these'':71 ''prophet'':28,98 ''prove'':25,95 ''resist'':11,81 ''seek'':65,135 ''shame'':39,109 ''sold'':59,129 ''traitor'':56,126 ''true'':35,105 ''wise'':33,103 ''zedekiah'':18,88', NULL, '788');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('789', '2', '789', NULL, 'In that they went to burn incense, and to serve - Or, by going to burn incense to serve thereby other gods.', NULL, NULL, '''burn'':6,15 ''go'':13 ''god'':21 ''incens'':7,16 ''serv'':10,18 ''therebi'':19 ''went'':4', NULL, '789');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('790', '2', '790', NULL, 'Grief to my sorrow - Baruch''s sorrow is caused by the sinfulness of the Jewish nation, to which God adds grief by showing how severely it will be punished.I fainted in - Or, "am weary with" Psalm 6:6.', NULL, NULL, '''6'':37,38 ''add'':20 ''baruch'':5 ''caus'':9 ''faint'':30 ''god'':19 ''grief'':1,21 ''jewish'':15 ''nation'':16 ''psalm'':36 ''punished.i'':29 ''sever'':25 ''show'':23 ''sin'':12 ''sorrow'':4,7 ''weari'':34', NULL, '790');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('791', '2', '791', NULL, 'Against ... - i. e., relating to, concerning. So Jeremiah 48:1; Jeremiah 49:1; see the note at Jeremiah 46:13.Pharaoh-necho - See 2 Kings 23:29 note.In - (at) Carchemish - (The Gargamis of the inscriptions, now Jerabis, on the Euphrates, about 16 miles south of Birejik.)', NULL, NULL, '''1'':10,13 ''13.pharaoh'':20 ''16'':41 ''2'':23 ''23'':25 ''29'':26 ''46'':19 ''48'':9 ''49'':12 ''birejik'':45 ''carchemish'':29 ''concern'':6 ''e'':3 ''euphrat'':39 ''gargami'':31 ''inscript'':34 ''jerabi'':36 ''jeremiah'':8,11,18 ''king'':24 ''mile'':42 ''necho'':21 ''note'':16 ''note.in'':27 ''relat'':4 ''see'':14,22 ''south'':43', NULL, '791');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('792', '2', '792', NULL, 'that Pharaoh - Pharaoh-Necho though defeated at Carchemish, was probably able to seize Gaza upon his retreat, when obviously the possession of so strong a fortress would be most useful to him to prevent the entrance of the victorious Chaldaeans into Egypt.', NULL, NULL, '''abl'':12 ''carchemish'':9 ''chaldaean'':41 ''defeat'':7 ''egypt'':43 ''entranc'':37 ''fortress'':27 ''gaza'':15 ''necho'':5 ''obvious'':20 ''pharaoh'':2,4 ''pharaoh-necho'':3 ''possess'':22 ''prevent'':35 ''probabl'':11 ''retreat'':18 ''seiz'':14 ''strong'':25 ''though'':6 ''upon'':16 ''use'':31 ''victori'':40 ''would'':28', NULL, '792');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('793', '2', '793', NULL, 'Against Moab - Concerning Moab.Is confounded - Is brought to shame.Misgab - The high fort; some special fortress, probably Kir-haraseth 2 Kings 3:25.', NULL, NULL, '''2'':20 ''25'':23 ''3'':22 ''brought'':7 ''concern'':3 ''confound'':5 ''fort'':12 ''fortress'':15 ''haraseth'':19 ''high'':11 ''king'':21 ''kir'':18 ''kir-haraseth'':17 ''moab'':2 ''moab.is'':4 ''probabl'':16 ''shame.misgab'':9 ''special'':14', NULL, '793');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('794', '2', '794', NULL, 'Hath Israel no sons? - i. e., the Ammonites in seizing Gilead have acted as if the country had no rightful owner. The sons of Israel were to return from captivity, and the land was their hereditary property.Their king - Milcom (and in Jeremiah 49:3), see the margin. The Ammonite god stands for the Ammonites just as Chemosh Jeremiah 48:7 is the equivalent of the Moabites.Inherit - i. e., take possession of.', NULL, NULL, '''3'':44 ''48'':59 ''49'':43 ''7'':60 ''act'':13 ''ammonit'':8,49,54 ''captiv'':30 ''chemosh'':57 ''countri'':17 ''e'':6,68 ''equival'':63 ''gilead'':11 ''god'':50 ''hath'':1 ''hereditari'':36 ''israel'':2,25 ''jeremiah'':42,58 ''king'':38 ''land'':33 ''margin'':47 ''milcom'':39 ''moabites.inherit'':66 ''owner'':21 ''possess'':70 ''property.their'':37 ''return'':28 ''right'':20 ''see'':45 ''seiz'':10 ''son'':4,23 ''stand'':51 ''take'':69', NULL, '794');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('795', '2', '795', NULL, 'Confounded ... confounded - ashamed ... ashamed.Merodach - This deity, in the inscriptions Marduk, was the tutelary god of Babylon, and Nebuchadnezzar, who called his son Evil-Merodach, appears to have been especially devoted to his service. He was really identical with Bel, and his equivalent among the planets was Jupiter: and as such he was styled "King of heaven and earth."', NULL, NULL, '''among'':44 ''appear'':26 ''asham'':3 ''ashamed.merodach'':4 ''babylon'':16 ''bel'':40 ''call'':20 ''confound'':1,2 ''deiti'':6 ''devot'':31 ''earth'':59 ''equival'':43 ''especi'':30 ''evil'':24 ''evil-merodach'':23 ''god'':14 ''heaven'':57 ''ident'':38 ''inscript'':9 ''jupit'':48 ''king'':55 ''marduk'':10 ''merodach'':25 ''nebuchadnezzar'':18 ''planet'':46 ''realli'':37 ''servic'':34 ''son'':22 ''style'':54 ''tutelari'':13', NULL, '795');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('796', '2', '796', NULL, 'In the midst of them that rise up against me - Or, in Leb-kamai, the cipher for Kasdim, i. e., Chaldaea. This cipher was not necessarily invented by Jeremiah, or used for concealment. It was probaby first devised either for political purposes or for trade, and was in time largely employed in the correspondence between the exiles at Babylon and their friends at home. Thus, words in common use like Sheshach Jeremiah 25:26 and Leb-kamai, would be known to everybody.', NULL, NULL, '''25'':74 ''26'':75 ''babylon'':60 ''chaldaea'':22 ''cipher'':17,24 ''common'':69 ''conceal'':34 ''correspond'':55 ''devis'':39 ''e'':21 ''either'':40 ''employ'':52 ''everybodi'':84 ''exil'':58 ''first'':38 ''friend'':63 ''home'':65 ''invent'':28 ''jeremiah'':30,73 ''kamai'':15,79 ''kasdim'':19 ''known'':82 ''larg'':51 ''leb'':14,78 ''leb-kamai'':13,77 ''like'':71 ''midst'':3 ''necessarili'':27 ''polit'':42 ''probabi'':37 ''purpos'':43 ''rise'':7 ''sheshach'':72 ''thus'':66 ''time'':50 ''trade'':46 ''use'':32,70 ''word'':67 ''would'':80', NULL, '796');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('797', '2', '797', NULL, 'Jeremiah 52 is an historical appendix to the Book of Jeremiah, giving details of the capture of Babylon additional to those contained in Jeremiah 39:The last words of the foregoing chapter affirm that Jeremiah was not the author, and the view adopted by most commentators is, that this chapter is taken from the 2nd Book of Kings, but that the person who added it here had access to other valuable documents, and made several modifications in it, the principal being the substituation of the account of those led captive by Nebuchadnezzar Jeremiah 52:28-30, for the narrative given in 2 Kings 25:22-26, where see the notes.', NULL, NULL, '''-26'':106 ''-30'':96 ''2'':102 ''22'':105 ''25'':104 ''28'':95 ''2nd'':55 ''39'':25 ''52'':2,94 ''access'':68 ''account'':86 ''add'':64 ''addit'':19 ''adopt'':43 ''affirm'':33 ''appendix'':6 ''author'':39 ''babylon'':18 ''book'':9,56 ''captiv'':90 ''captur'':16 ''chapter'':32,50 ''comment'':46 ''contain'':22 ''detail'':13 ''document'':72 ''forego'':31 ''give'':12 ''given'':100 ''histor'':5 ''jeremiah'':1,11,24,35,93 ''king'':58,103 ''last'':27 ''led'':89 ''made'':74 ''modif'':76 ''narrat'':99 ''nebuchadnezzar'':92 ''note'':110 ''person'':62 ''princip'':80 ''see'':108 ''sever'':75 ''substitu'':83 ''taken'':52 ''valuabl'':71 ''view'':42 ''word'':28', NULL, '797');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('798', '2', '798', NULL, 'In these two verses is the same sad image as appears in the well-known medal of Titus, struck to celebrate his triumph over Jerusalem. A woman sits weeping beneath a palm-tree, and below is the legend "Judaea capta."Translate Lamentations 1:1 :How sitteth solitary the city that was full of people:She is become as a widow that was great among the nations:A princess among provinces she is become a vassal.Tributary - In the sense of personal labor Joshua 16:10.', NULL, NULL, '''1'':45,46 ''10'':86 ''16'':85 ''among'':66,71 ''appear'':11 ''becom'':59,75 ''beneath'':31 ''capta'':42 ''celebr'':22 ''citi'':51 ''full'':54 ''great'':65 ''imag'':9 ''jerusalem'':26 ''joshua'':84 ''judaea'':41 ''known'':16 ''labor'':83 ''lament'':44 ''legend'':40 ''medal'':17 ''nation'':68 ''palm'':34 ''palm-tre'':33 ''peopl'':56 ''person'':82 ''princess'':70 ''provinc'':72 ''sad'':8 ''sens'':80 ''sit'':29 ''sitteth'':48 ''solitari'':49 ''struck'':20 ''titus'':19 ''translat'':43 ''tree'':35 ''triumph'':24 ''two'':3 ''vassal.tributary'':77 ''vers'':4 ''weep'':30 ''well'':15 ''well-known'':14 ''widow'':62 ''woman'':28', NULL, '798');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('621', '2', '621', NULL, 'Hear my prayer, O Lord, give ear ... - See Psalm 4:1, note; Psalm 5:1, note.In thy faithfulness answer me - That is, Show thy faithfulness to thy promises. God had made gracious promises to David (compare Psalm 89:19-37), and he now pleads that he would remember those promises, and accomplish in his behalf what he had said he would. God has also made gracious promises to his people, and they may always plead those promises as a reason why they should be heard, and why their prayers should be answered.And in thy righteousness - Compare Psalm 31:1. In thy disposition to do right; to vindicate a righteous cause; to interpose when wrong is done. We, though sinners before God, may feel that our cause is a just one as toward our fellowmen, and, when wronged, we may ask God to interpose, as a righteous God, in our behalf. We cannot, however, ask him to save us on the ground of our righteousness toward him, for we have no such righteousness. See Psalm 143:2.', NULL, NULL, '''-37'':40 ''1'':11,15,99 ''143'':175 ''19'':39 ''2'':176 ''31'':98 ''4'':10 ''5'':14 ''89'':38 ''accomplish'':52 ''also'':64 ''alway'':74 ''answer'':19 ''answered.and'':92 ''ask'':140,154 ''behalf'':55,150 ''cannot'':152 ''caus'':110,126 ''compar'':36,96 ''david'':35 ''disposit'':102 ''done'':116 ''ear'':7 ''faith'':18,25 ''feel'':123 ''fellowmen'':134 ''give'':6 ''god'':29,62,121,141,147 ''gracious'':32,66 ''ground'':161 ''hear'':1 ''heard'':85 ''howev'':153 ''interpos'':112,143 ''lord'':5 ''made'':31,65 ''may'':73,122,139 ''note'':12 ''note.in'':16 ''o'':4 ''one'':130 ''peopl'':70 ''plead'':44,75 ''prayer'':3,89 ''promis'':28,33,50,67,77 ''psalm'':9,13,37,97,174 ''reason'':80 ''rememb'':48 ''right'':105 ''righteous'':95,109,146,164,172 ''said'':59 ''save'':157 ''see'':8,173 ''show'':23 ''sinner'':119 ''thi'':17,24,27,94,101 ''though'':118 ''toward'':132,165 ''us'':158 ''vindic'':107 ''would'':47,61 ''wrong'':114,137', NULL, '621');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('622', '2', '622', NULL, 'Blessed be the Lord my strength - Margin, as in Hebrew, "my rock." See the notes at Psalm 18:46, where the same expression occurs in the Hebrew.Which teacheth my hands to war - Hebrew, "To the war." See the notes at Psalm 18:34. The Hebrew is not precisely alike, but the sense is the same.And my fingers to fight - Hebrew, my fingers to the fight. That is, he teaches my fingers so that I can skillfully use them in battle. Probably the immediate reference here is to the use of the bow - placing the arrow, and drawing the string.', NULL, NULL, '''18'':18,42 ''34'':43 ''46'':19 ''alik'':49 ''arrow'':95 ''battl'':80 ''bless'':1 ''bow'':92 ''draw'':97 ''express'':23 ''fight'':59,65 ''finger'':57,62,71 ''hand'':30 ''hebrew'':10,33,45,60 ''hebrew.which'':27 ''immedi'':83 ''lord'':4 ''margin'':7 ''note'':15,39 ''occur'':24 ''place'':93 ''precis'':48 ''probabl'':81 ''psalm'':17,41 ''refer'':84 ''rock'':12 ''same.and'':55 ''see'':13,37 ''sens'':52 ''skill'':76 ''strength'':6 ''string'':99 ''teach'':69 ''teacheth'':28 ''use'':77,89 ''war'':32,36', NULL, '622');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('623', '2', '623', NULL, 'I will extol thee ... - I will lift thee up; I will lift up thy name and praise, so that it may be heard afar.And I will bless thy name forever and ever - I will bless or praise thee. I will do it now; I will do it in all the future. I will do it in time; I will do it in eternity. See the notes at Psalm 30:1.', NULL, NULL, '''1'':70 ''30'':69 ''afar.and'':24 ''bless'':27,35 ''etern'':63 ''ever'':32 ''extol'':3 ''forev'':30 ''futur'':51 ''heard'':23 ''lift'':7,12 ''may'':21 ''name'':15,29 ''note'':66 ''prais'':17,37 ''psalm'':68 ''see'':64 ''thee'':4,8,38 ''thi'':14,28 ''time'':57', NULL, '623');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('624', '2', '624', NULL, 'Praise ye the Lord - "Ye" - all people. Margin, Hallelujah. See Psalm 104:35; Psalm 106:1.Praise the Lord, O my soul - See Psalm 103:1, note; Psalm 104:1, note.', NULL, NULL, '''1'':25,29 ''1.praise'':16 ''103'':24 ''104'':12,28 ''106'':15 ''35'':13 ''hallelujah'':9 ''lord'':4,18 ''margin'':8 ''note'':26,30 ''o'':19 ''peopl'':7 ''prais'':1 ''psalm'':11,14,23,27 ''see'':10,22 ''soul'':21 ''ye'':2,5', NULL, '624');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('557', '2', '557', NULL, 'O God, the heathen are come into thine inheritance - The nations; a foreign people. See Psalm 2:1, note; Psalm 2:8; note; Psalm 78:55, note. The term is one that would be applicable to the Chaldeans, or Babylonians, and the probable allusion here is to their invasion of the holy land under Nebuchadnezzar. 2 Chronicles 36:17-21.Thy holy temple have they defiled - They have polluted it. By entering it; by removing the sacred furniture; by cutting down the carved work; by making it desolate. See 2 Chronicles 36:17-18. Compare the notes at Psalm 74:5-7.They have laid Jerusalem on heaps - See 2 Chronicles 36:19 : "And they burnt the house of God, and brake down the wall of Jerusalem, and burnt all the palaces thereof with fire, and destroyed all the goodly vessels thereof."', NULL, NULL, '''-18'':92 ''1'':18 ''17'':91 ''17-21.thy'':59 ''19'':109 ''2'':17,21,56,88,106 ''36'':58,90,108 ''5-7.they'':99 ''55'':26 ''74'':98 ''78'':25 ''8'':22 ''allus'':44 ''applic'':35 ''babylonian'':40 ''brake'':118 ''burnt'':112,125 ''carv'':81 ''chaldean'':38 ''chronicl'':57,89,107 ''come'':6 ''compar'':93 ''cut'':78 ''defil'':64 ''desol'':86 ''destroy'':133 ''enter'':70 ''fire'':131 ''foreign'':13 ''furnitur'':76 ''god'':2,116 ''good'':136 ''heap'':104 ''heathen'':4 ''holi'':52,60 ''hous'':114 ''inherit'':9 ''invas'':49 ''jerusalem'':102,123 ''laid'':101 ''land'':53 ''make'':84 ''nation'':11 ''nebuchadnezzar'':55 ''note'':19,23,27,95 ''o'':1 ''one'':31 ''palac'':128 ''peopl'':14 ''pollut'':67 ''probabl'':43 ''psalm'':16,20,24,97 ''remov'':73 ''sacr'':75 ''see'':15,87,105 ''templ'':61 ''term'':29 ''thereof'':129,138 ''thine'':8 ''vessel'':137 ''wall'':121 ''work'':82 ''would'':33', NULL, '557');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('558', '2', '558', NULL, 'Give ear - Incline the ear; as if the ear of God was then turned away, or as if he was inattentive to what was occurring. See the notes at Psalm 5:1. O Shepherd of Israel. See the notes at Psalm 23:1.Thou that leadest Joseph like a flock - Joseph, the father of Ephraim and Manasseh. See the notes at Psalm 78:67. The name Joseph seems here to be used poetically to represent the whole people of Israel, as he was a man so prominent in their history, and especially as Egypt is mentioned as the country from which the vine had been transplanted - a country where Joseph had acted so important a part, and in connection with which his name would be so naturally associated. The meaning is, that God had led the tribes of the Hebrew people as a shepherd leads or conducts his flock.Thou that dwellest between the cherubims - See the notes at Psalm 18:10. The allusion here is to God as dwelling, by a visible symbol - the Shechinah - on the mercy-seat, between the cherubims. Exodus 25:18, Exodus 25:22; Exodus 37:7; 1 Samuel 4:4; 1 Kings 6:25. See the notes at Isaiah 37:16; and notes at Hebrews 9:5. "Shine, forth." Manifest thyself. Let light come from thy presence in the midst of our darkness and calamity.', NULL, NULL, '''1'':32,192,196 ''1.thou'':43 ''10'':160 ''16'':206 ''18'':159,185 ''22'':188 ''23'':42 ''25'':184,187,199 ''37'':190,205 ''4'':194,195 ''5'':31,212 ''6'':198 ''67'':63 ''7'':191 ''78'':62 ''9'':211 ''act'':111 ''allus'':162 ''associ'':127 ''away'':15 ''calam'':230 ''cherubim'':153,182 ''come'':219 ''conduct'':146 ''connect'':118 ''countri'':98,107 ''dark'':228 ''dwell'':168 ''dwellest'':150 ''ear'':2,5,9 ''egypt'':93 ''ephraim'':54 ''especi'':91 ''exodus'':183,186,189 ''father'':52 ''flock'':49 ''flock.thou'':148 ''forth'':214 ''give'':1 ''god'':11,132,166 ''hebrew'':139,210 ''histori'':89 ''import'':113 ''inattent'':21 ''inclin'':3 ''isaiah'':204 ''israel'':36,79 ''joseph'':46,50,66,109 ''king'':197 ''lead'':144 ''leadest'':45 ''led'':134 ''let'':217 ''light'':218 ''like'':47 ''man'':84 ''manasseh'':56 ''manifest'':215 ''mean'':129 ''mention'':95 ''merci'':178 ''mercy-seat'':177 ''midst'':225 ''name'':65,122 ''natur'':126 ''note'':28,39,59,156,202,208 ''o'':33 ''occur'':25 ''part'':115 ''peopl'':77,140 ''poetic'':72 ''presenc'':222 ''promin'':86 ''psalm'':30,41,61,158 ''repres'':74 ''samuel'':193 ''seat'':179 ''see'':26,37,57,154,200 ''seem'':67 ''shechinah'':174 ''shepherd'':34,143 ''shine'':213 ''symbol'':172 ''thi'':221 ''thyself'':216 ''transplant'':105 ''tribe'':136 ''turn'':14 ''use'':71 ''vine'':102 ''visibl'':171 ''whole'':76 ''would'':123', NULL, '558');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('559', '2', '559', NULL, 'Sing aloud unto God our strength - The strength and support of the nation; he from whom the nation has derived all its power. The word rendered sing aloud means to rejoice; and then, to make or cause to rejoice. It would be appropriate to a high festal occasion, where music constituted an important part of the public service. And it would be a proper word to employ in reference to any of the great feasts of the Hebrews.Make a joyful noise - A noise indicating joy, as distinguished from a noise of mourning or lamentation.Unto the God of Jacob - Not here particularly the God of the patriarch himself, but of the people who bore his name - his descendants.', NULL, NULL, '''aloud'':2,28 ''appropri'':43 ''bore'':113 ''caus'':37 ''constitut'':51 ''deriv'':20 ''descend'':117 ''distinguish'':87 ''employ'':67 ''feast'':75 ''festal'':47 ''god'':4,96,103 ''great'':74 ''hebrews.make'':78 ''high'':46 ''import'':53 ''indic'':84 ''jacob'':98 ''joy'':80,85 ''lamentation.unto'':94 ''make'':35 ''mean'':29 ''mourn'':92 ''music'':50 ''name'':115 ''nation'':13,18 ''nois'':81,83,90 ''occas'':48 ''part'':54 ''particular'':101 ''patriarch'':106 ''peopl'':111 ''power'':23 ''proper'':64 ''public'':57 ''refer'':69 ''rejoic'':31,39 ''render'':26 ''servic'':58 ''sing'':1,27 ''strength'':6,8 ''support'':10 ''unto'':3 ''word'':25,65 ''would'':41,61', NULL, '559');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('560', '2', '560', NULL, 'God standeth in the congregation of the mighty - In the assembly of the rulers and judges; among those of most exalted rank and station. He is there to observe them; to give them law; to direct their decisions; to judge them. He is supreme over them; and he holds them responsible to himself The word rendered congregation is that which is commonly applied to the assembly of the people of Israel, considered as an organized body, or as a body politic. It here, however, refers to magistrates considered as a body or class of people; as those who have assemblages or meetings, with special reference to their duties as magistrates. The word rendered "mighty" -   ''El - is in the singular number, and is one of the names which are given to God; hence, the literal rendering is, "God standeth in the assembly of God." The Septuagint renders it, In the synagogue of the gods. So also the Latin Vulgate. The reference, however, is undoubtedly to magistrates, and the idea is, that they were to be regarded as representatives of God; as acting in his name; and as those, therefore, to whom, in a subordinate sense, the name gods might be given. Compare Psalm 82:6. In Exodus 21:6; Exodus 22:8-9, Exodus 22:28, also, the same word in the plural is applied to magistrates, and is properly translated judges in our common version. Compare the notes at John 10:34-35. The idea is, that they were the representatives of the divine sovereignty in the administration of justice. Compare Romans 13:1-2, Romans 13:6. They were, in a sense, gods to other people; but they were not to forget that God stood among them as their God; that if they were exalted to a high rank in respect to their fellowmen, they were, nevertheless, subject to One to whom the name of God belonged in the highest sense.He judgeth among the gods - As they to whom the name gods is thus given as the representatives of the divine sovereignty judged among people, so God would judge among them. If they were, in some sense (in consequence of their representing the divine majesty, and deriving their power and appointment from God), independent of people, they were in no sense independent of God himself.', NULL, NULL, '''-2'':265 ''-35'':243 ''-9'':212 ''1'':264 ''10'':241 ''13'':263,267 ''21'':207 ''22'':210,214 ''28'':215 ''34'':242 ''6'':204,208,268 ''8'':211 ''82'':203 ''act'':181 ''administr'':258 ''also'':155,216 ''among'':17,287,324,345,351 ''appli'':63,224 ''appoint'':372 ''assembl'':11,66,141 ''assemblag'':100 ''belong'':318 ''bodi'':76,80,91 ''class'':93 ''common'':62,234 ''compar'':201,236,261 ''congreg'':5,57 ''consequ'':360 ''consid'':72,88 ''decis'':38 ''deriv'':368 ''direct'':36 ''divin'':254,342,365 ''duti'':108 ''el'':115 ''exalt'':21,296 ''exodus'':206,209,213 ''fellowmen'':305 ''forget'':283 ''give'':32 ''given'':129,200,336 ''god'':1,131,137,143,153,179,197,274,285,291,317,326,333,348,374,385 ''henc'':132 ''high'':299 ''highest'':321 ''hold'':49 ''howev'':84,161 ''idea'':168,245 ''independ'':375,383 ''israel'':71 ''john'':240 ''judg'':16,40,231,344,350 ''judgeth'':323 ''justic'':260 ''latin'':157 ''law'':34 ''liter'':134 ''magistr'':87,110,165,226 ''majesti'':366 ''meet'':102 ''might'':198 ''mighti'':8,114 ''name'':126,184,196,315,332 ''nevertheless'':308 ''note'':238 ''number'':120 ''observ'':29 ''one'':123,311 ''organ'':75 ''peopl'':69,95,277,346,377 ''plural'':222 ''polit'':81 ''power'':370 ''proper'':229 ''psalm'':202 ''rank'':22,300 ''refer'':85,105,160 ''regard'':175 ''render'':56,113,135,146 ''repres'':177,251,339,363 ''respect'':302 ''respons'':51 ''roman'':262,266 ''ruler'':14 ''sens'':194,273,358,382 ''sense.he'':322 ''septuagint'':145 ''singular'':119 ''sovereignti'':255,343 ''special'':104 ''standeth'':2,138 ''station'':24 ''stood'':286 ''subject'':309 ''subordin'':193 ''suprem'':44 ''synagogu'':150 ''therefor'':188 ''thus'':335 ''translat'':230 ''undoubt'':163 ''version'':235 ''vulgat'':158 ''word'':55,112,219 ''would'':349', NULL, '560');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('849', '2', '849', NULL, 'The vision of the waters; or, the blessings which flow from this source to animate and refresh all the inhabitants of the earth. Compare Isaiah 44:8...; Joel 3:18. Ezekiel''s description is adopted and modifled by Zechariah and in Rev. (compare the marginal references) Hebrew tradition speaks of a spring of water, named Etham, said to be identical with the well-waters of Nephtoah Joshua 18:15, on the west of the temple, whose waters were conducted by pipes into the temple-courts for the uses needed in the ministration of the priests. The waters of Shiloah Psalm 46:4; Isaiah 8:6 flowed from the rocks beneath the temple-hill. It is quite in the manner of Ezekiel''s vision to start from an existing feature and thence proceed to an ideal picture from where to draw a spiritual lesson. The deepening of the waters in their course shows the continual deepening of spiritual life and multiplication of spiritual blessings in the growth of the kingdom of God. So long as the stream is confined to the temple-courts, it is merely a small rill, for the most part unseen, but when it issues from the courts it begins at once to deepen and to widen. So on the day of Pentecost, the Holy Spirit descended upon the company of believers, little then but presently to develop into the infant Church in Jerusalem.', NULL, NULL, '''15'':70 ''18'':30,69 ''3'':29 ''4'':104 ''44'':26 ''46'':103 ''6'':107 ''8'':27,106 ''adopt'':35 ''anim'':15 ''begin'':206 ''believ'':228 ''beneath'':112 ''bless'':8,166 ''church'':238 ''compani'':226 ''compar'':24,43 ''conduct'':80 ''confin'':181 ''continu'':157 ''cours'':154 ''court'':87,186,204 ''day'':217 ''deepen'':148,158,210 ''descend'':223 ''descript'':33 ''develop'':234 ''draw'':143 ''earth'':23 ''etham'':56 ''exist'':131 ''ezekiel'':31,124 ''featur'':132 ''flow'':10,108 ''god'':174 ''growth'':169 ''hebrew'':47 ''hill'':116 ''holi'':221 ''ideal'':138 ''ident'':60 ''infant'':237 ''inhabit'':20 ''isaiah'':25,105 ''issu'':201 ''jerusalem'':240 ''joel'':28 ''joshua'':68 ''kingdom'':172 ''lesson'':146 ''life'':161 ''littl'':229 ''long'':176 ''manner'':122 ''margin'':45 ''mere'':189 ''ministr'':94 ''modifl'':37 ''multipl'':163 ''name'':55 ''need'':91 ''nephtoah'':67 ''part'':196 ''pentecost'':219 ''pictur'':139 ''pipe'':82 ''present'':232 ''priest'':97 ''proceed'':135 ''psalm'':102 ''quit'':119 ''refer'':46 ''refresh'':17 ''rev'':42 ''rill'':192 ''rock'':111 ''said'':57 ''shiloah'':101 ''show'':155 ''small'':191 ''sourc'':13 ''speak'':49 ''spirit'':222 ''spiritu'':145,160,165 ''spring'':52 ''start'':128 ''stream'':179 ''templ'':76,86,115,185 ''temple-court'':85,184 ''temple-hil'':114 ''thenc'':134 ''tradit'':48 ''unseen'':197 ''upon'':224 ''use'':90 ''vision'':2,126 ''water'':5,54,65,78,99,151 ''well'':64 ''well-wat'':63 ''west'':73 ''whose'':77 ''widen'':213 ''zechariah'':39', NULL, '849');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1017', '2', '1017', NULL, 'For God commanded ... - That is, in the fifth commandment Exodus 20:12, and in Exodus 21:17. To "honor" is to obey, to reverence, to speak kindly to, to speak and think well of. To "curse" is to disobey, to treat with irreverence, to swear at, to speak ill of, to think evil of in the heart, to meditate or do any evil to a parent. All this is included in the original word.Let him die the death - This is a Hebrew phrase, the same as saying, "let him surely die." The Jewish law punished this crime with death. This duty of honoring and obeying a parent was what Christ said they had violated by their traditions. He proceeds to state the way in which it was done.', NULL, NULL, '''12'':12 ''17'':17 ''20'':11 ''21'':16 ''christ'':110 ''command'':3,9 ''crime'':97 ''curs'':36 ''death'':78,99 ''die'':76,91 ''disobey'':39 ''done'':128 ''duti'':101 ''evil'':53,63 ''exodus'':10,15 ''fifth'':8 ''god'':2 ''heart'':57 ''hebrew'':82 ''honor'':19,103 ''ill'':49 ''includ'':70 ''irrever'':43 ''jewish'':93 ''kind'':27 ''law'':94 ''let'':88 ''medit'':59 ''obey'':22,105 ''origin'':73 ''parent'':66,107 ''phrase'':83 ''proceed'':119 ''punish'':95 ''rever'':24 ''said'':111 ''say'':87 ''speak'':26,30,48 ''state'':121 ''sure'':90 ''swear'':45 ''think'':32,52 ''tradit'':117 ''treat'':41 ''violat'':114 ''way'':123 ''well'':33 ''word.let'':74', NULL, '944');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1018', '2', '1018', NULL, 'See also Mark 8:11-12.The Pharisees also, and the Sadducees - See the notes at Matthew 3:7.Tempting - That is, trying him - feigning a desire to see evidence that he was the Messiah, but with a real desire to see him make the attempt to work a miracle and fail, so that they might betray him and ruin him.A sign from heaven - Some miraculous appearance in the sky. Such appearances had been given by the prophets; and they supposed, if he was the Messiah, that his miracles would not all be confined to the earth, but that he was able to give some signal miracle from heaven. Samuel had caused it to thunder 1 Samuel 12:16-18; Isaiah had caused the shadow to go back ten degrees on the dial of Ahaz Isaiah 38:8; and Moses had sent manna from heaven, Exodus 16:4; John 6:31. It is proper to say, that though Christ did not choose then to show such wonders, yet far more stupendous signs from heaven than these were exhibited at his death.', NULL, NULL, '''-18'':117 ''1'':113 ''11-12.the'':5 ''12'':115 ''16'':116,144 ''3'':16 ''31'':148 ''38'':134 ''4'':145 ''6'':147 ''7.tempting'':17 ''8'':4,135 ''abl'':99 ''ahaz'':132 ''also'':2,7 ''appear'':64,69 ''attempt'':43 ''back'':125 ''betray'':54 ''caus'':109,120 ''choos'':159 ''christ'':156 ''confin'':91 ''death'':178 ''degre'':127 ''desir'':24,37 ''dial'':130 ''earth'':94 ''evid'':27 ''exhibit'':175 ''exodus'':143 ''fail'':49 ''far'':166 ''feign'':22 ''give'':101 ''given'':72 ''go'':124 ''heaven'':61,106,142,171 ''him.a'':58 ''isaiah'':118,133 ''john'':146 ''make'':41 ''manna'':140 ''mark'':3 ''matthew'':15 ''messiah'':32,83 ''might'':53 ''miracl'':47,86,104 ''miracul'':63 ''mose'':137 ''note'':13 ''pharise'':6 ''proper'':151 ''prophet'':75 ''real'':36 ''ruin'':57 ''sadduce'':10 ''samuel'':107,114 ''say'':153 ''see'':1,11,26,39 ''sent'':139 ''shadow'':122 ''show'':162 ''sign'':59,169 ''signal'':103 ''sky'':67 ''stupend'':168 ''suppos'':78 ''ten'':126 ''though'':155 ''thunder'':112 ''tri'':20 ''wonder'':164 ''work'':45 ''would'':87 ''yet'':165', NULL, '945');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1019', '2', '1019', NULL, 'Matthew 17:1-9. See also Mark 9:2-10; Luke 9:28-36.And after six days - That is, six days from the conversation recorded in the last chapter.Luke Luk 9:28 says, about an eight days after. Matthew mentions the six days that intervened between the day of the conversation and the transfiguration. Luke includes both those days, and thus reckons eight. Besides, Luke does not pretend to fix the precise time. He says, "about an eight days after."Taketh Peter, and James, and John - These three disciples were with him, also, in the garden of Gethsemane, Mark 14:33. He designed to prepare them in an eminent degree for the work of the gospel ministry by the previous manifestations of his glory, and of his patience in suffering.Into a high mountain apart - That is, apart from the other disciples. It is commonly supposed that this was Mount Tabor, a high mountain in Galilee. The name of the mountain is not, however, mentioned in the New Testament. Luke adds Luke 9:28 that he went up there to pray. Our Saviour prayed much. When he did it he chose to be alone. For this purpose he often ascended mountains or went into the deserts. There is something in the solitude and deep and awful stillness of a lofty mountain favorable to devotion.', NULL, NULL, '''-10'':10 ''-9'':4 ''1'':3 ''14'':99 ''17'':2 ''2'':9 ''28'':31,172 ''28-36.and'':13 ''33'':100 ''9'':8,12,30,171 ''add'':169 ''alon'':192 ''also'':6,92 ''apart'':133,136 ''ascend'':198 ''aw'':214 ''besid'':63 ''chapter.luke'':28 ''chose'':189 ''common'':143 ''convers'':23,50 ''day'':16,20,36,42,47,58,78 ''deep'':212 ''degre'':109 ''desert'':204 ''design'':102 ''devot'':222 ''discipl'':88,140 ''eight'':35,62,77 ''emin'':108 ''favor'':220 ''fix'':69 ''galile'':154 ''garden'':95 ''gethseman'':97 ''glori'':123 ''gospel'':115 ''high'':131,151 ''howev'':162 ''includ'':55 ''interven'':44 ''jame'':83 ''john'':85 ''last'':27 ''lofti'':218 ''luk'':29 ''luke'':11,54,64,168,170 ''manifest'':120 ''mark'':7,98 ''matthew'':1,38 ''mention'':39,163 ''ministri'':116 ''mount'':148 ''mountain'':132,152,159,199,219 ''much'':183 ''name'':156 ''new'':166 ''often'':197 ''patienc'':127 ''peter'':81 ''pray'':179,182 ''precis'':71 ''prepar'':104 ''pretend'':67 ''previous'':119 ''purpos'':195 ''reckon'':61 ''record'':24 ''saviour'':181 ''say'':32,74 ''see'':5 ''six'':15,19,41 ''solitud'':210 ''someth'':207 ''still'':215 ''suffering.into'':129 ''suppos'':144 ''tabor'':149 ''taketh'':80 ''testament'':167 ''three'':87 ''thus'':60 ''time'':72 ''transfigur'':53 ''went'':175,201 ''work'':112', NULL, '946');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1024', '2', '1024', NULL, 'And Jesus answered and spake unto them again in parables - See the notes at Matthew 13:3. That is, he answered or made reply to the Pharisees, who had been enraged at him for what he had already spoken to them, Matthew 21:45-46. He made a still further statement, to show how the gospel would be received and treated by them. The real answer here, as is frequently the case in the New Testament, refers to what was passing in the mind, or to the conduct of those who were addressed, not to what they said.', NULL, NULL, '''-46'':45 ''13'':16 ''21'':43 ''3'':17 ''45'':44 ''address'':93 ''alreadi'':38 ''answer'':3,21,66 ''case'':72 ''conduct'':88 ''enrag'':31 ''frequent'':70 ''gospel'':56 ''jesus'':2 ''made'':23,47 ''matthew'':15,42 ''mind'':84 ''new'':75 ''note'':13 ''parabl'':10 ''pass'':81 ''pharise'':27 ''real'':65 ''receiv'':59 ''refer'':77 ''repli'':24 ''said'':98 ''see'':11 ''show'':53 ''spake'':5 ''spoken'':39 ''statement'':51 ''still'':49 ''testament'':76 ''treat'':61 ''unto'':6 ''would'':57', NULL, '951');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1025', '2', '1025', NULL, 'Ye serpents - This name is given to them on account of their pretending to be pious, and very much devoted to God, but being secretly evil, At the heart, with all their pretensions, they were filled with evil designs, as the serpent was, Genesis 3:1-5Generation of vipers - See the notes at Matthew 12:34.Damnation of hell - This refers, beyond all question, to future punishment. So great was their wickedness and hypocrisy, that, if they persevered in this course, it was impossible to escape the damnation that should come on the guilty. This is the sternest language that Jesus ever used to wicked people. But it by no means authorizes ministers to use such language to sinners now. Christ knew that this was true of them. He had an authority which none now have. It is not the province of ministers to denounce judgment, or to use severe names, least of all to do it on pretence of imitating Christ. He knew the hearts of people. We know them not. He had authority to declare certainly that those whom he addressed would be lost. We have no such authority. He addressed persons; we address characters.', NULL, NULL, '''-5'':47 ''1'':46 ''12'':56 ''3'':45 ''34.damnation'':57 ''account'':10 ''address'':183,193,196 ''author'':112,132,175,191 ''beyond'':62 ''certain'':178 ''charact'':197 ''christ'':121,162 ''come'':91 ''cours'':81 ''damnat'':88 ''declar'':177 ''denounc'':145 ''design'':39 ''devot'':20 ''escap'':86 ''ever'':102 ''evil'':26,38 ''fill'':36 ''futur'':66 ''generat'':48 ''genesi'':44 ''given'':6 ''god'':22 ''great'':69 ''guilti'':94 ''heart'':29,166 ''hell'':59 ''hypocrisi'':74 ''imit'':161 ''imposs'':84 ''jesus'':101 ''judgment'':146 ''knew'':122,164 ''know'':170 ''languag'':99,117 ''least'':152 ''lost'':186 ''matthew'':55 ''mean'':111 ''minist'':113,143 ''much'':19 ''name'':4,151 ''none'':134 ''note'':53 ''peopl'':106,168 ''persev'':78 ''person'':194 ''pious'':16 ''pretenc'':159 ''pretend'':13 ''pretens'':33 ''provinc'':141 ''punish'':67 ''question'':64 ''refer'':61 ''secret'':25 ''see'':51 ''serpent'':2,42 ''sever'':150 ''sinner'':119 ''sternest'':98 ''true'':126 ''use'':103,115,149 ''viper'':50 ''wick'':105 ''wicked'':72 ''would'':184 ''ye'':1', NULL, '952');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('561', '2', '561', NULL, 'The tabernacles of Edom - The tents of Edom; meaning here, the dwellers in those tents, that is, the Edomites. The word tabernacles or tents does not necessarily imply that the nation then led a wandering life, for the word came to signify in process of time a dwelling-place, or a habitation. The Edomites were not, in fact, a roving and wandering people, but a people of fixed boundaries. In early periods, however, like most ancient people, they doubtless dwelt in tents. Edom, or Idumea, was south of Palestine. See the notes at Isaiah 11:14.And the Ishmaelites - The descendants of Ishmael. They dwelt in Arabia Deserta.Of Moab - On the situation of Moab, see the notes at Isaiah 15:1-9. It was on the southeast of Palestine.And the Hagarenes - The Hagarenes were properly Arabs, so called from Hagar, the handmaid of Abraham, the mother of Ishmael. Genesis 16:1; Genesis 25:12. As connected with the Ishmaelites they would naturally join in this alliance.', NULL, NULL, '''-9'':122 ''1'':121,151 ''11'':96 ''12'':154 ''14.and'':97 ''15'':120 ''16'':150 ''25'':153 ''abraham'':144 ''allianc'':166 ''ancient'':77 ''arab'':136 ''arabia'':107 ''boundari'':70 ''call'':138 ''came'':40 ''connect'':156 ''descend'':101 ''deserta.of'':108 ''doubtless'':80 ''dwell'':49 ''dweller'':12 ''dwelling-plac'':48 ''dwelt'':81,105 ''earli'':72 ''edom'':4,8,84 ''edomit'':19,55 ''fact'':59 ''fix'':69 ''genesi'':149,152 ''habit'':53 ''hagar'':140 ''hagaren'':131,133 ''handmaid'':142 ''howev'':74 ''idumea'':86 ''impli'':28 ''isaiah'':95,119 ''ishmael'':103,148 ''ishmaelit'':99,159 ''join'':163 ''led'':33 ''life'':36 ''like'':75 ''mean'':9 ''moab'':109,114 ''mother'':146 ''nation'':31 ''natur'':162 ''necessarili'':27 ''note'':93,117 ''palestin'':90 ''palestine.and'':129 ''peopl'':64,67,78 ''period'':73 ''place'':50 ''process'':44 ''proper'':135 ''rove'':61 ''see'':91,115 ''signifi'':42 ''situat'':112 ''south'':88 ''southeast'':127 ''tabernacl'':2,22 ''tent'':6,15,24,83 ''time'':46 ''wander'':35,63 ''word'':21,39 ''would'':161', NULL, '561');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('268', '2', '268', NULL, 'Now it came to pass ... - There is no break whatever between the two books of Samuel, the division being purely artificial.', NULL, NULL, '''artifici'':21 ''book'':14 ''break'':9 ''came'':3 ''divis'':18 ''pass'':5 ''pure'':20 ''samuel'':16 ''two'':13 ''whatev'':10', NULL, '268');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('269', '2', '269', NULL, 'Enquired of the Lord - Through Abiathar, the high priest. The death of Saul and Jonathan had entirely changed David''s position, and therefore he needed divine guidance how to act under the new circumstances in which he was placed. Compare the marginal references.Hebron was well suited for the temporary capital of David''s kingdom, being situated in a strong position in the mountains of Judah, amidst David''s friends, and withal having especially sacred associations (see the marginal references note). It appears to have also been the center of a district 2 Samuel 2:3.', NULL, NULL, '''2'':92,94 ''3'':95 ''abiathar'':6 ''act'':30 ''also'':85 ''amidst'':66 ''appear'':82 ''associ'':75 ''capit'':50 ''center'':88 ''chang'':18 ''circumst'':34 ''compar'':40 ''david'':19,52,67 ''death'':11 ''district'':91 ''divin'':26 ''enquir'':1 ''entir'':17 ''especi'':73 ''friend'':69 ''guidanc'':27 ''high'':8 ''jonathan'':15 ''judah'':65 ''kingdom'':54 ''lord'':4 ''margin'':42,78 ''mountain'':63 ''need'':25 ''new'':33 ''note'':80 ''place'':39 ''posit'':21,60 ''priest'':9 ''refer'':79 ''references.hebron'':43 ''sacr'':74 ''samuel'':93 ''saul'':13 ''see'':76 ''situat'':56 ''strong'':59 ''suit'':46 ''temporari'':49 ''therefor'':23 ''well'':45 ''withal'':71', NULL, '269');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('270', '2', '270', NULL, 'Chileab - In the duplicate passage (see the margin.) David''s second son is called Daniel (God is my judge), a name given to him in commemoration of the death of Nabal 1 Samuel 25:39. Chileab seems to be made up of the three first letters of the following Hebrew word, through an error of the transcriber, and intended to be erased.Talmai king of Geshur - Talmai was the name of one of the sons of Anak at Hebron Numbers 13:22; this Talmai was perhaps of the same race.Geshur - Where he reigned was in Bashan, and we know from Deuteronomy 3:11, that Og, king of Bashan, was of the "remnant of the giants." See 1 Samuel 27:8 note.', NULL, NULL, '''1'':32,116 ''11'':102 ''13'':80 ''22'':81 ''25'':34 ''27'':118 ''3'':101 ''39'':35 ''8'':119 ''anak'':76 ''bashan'':95,107 ''call'':14 ''chileab'':1,36 ''commemor'':26 ''daniel'':15 ''david'':9 ''death'':29 ''deuteronomi'':100 ''duplic'':4 ''erased.talmai'':62 ''error'':54 ''first'':45 ''follow'':49 ''geshur'':65 ''giant'':114 ''given'':22 ''god'':16 ''hebrew'':50 ''hebron'':78 ''intend'':59 ''judg'':19 ''king'':63,105 ''know'':98 ''letter'':46 ''made'':40 ''margin'':8 ''nabal'':31 ''name'':21,69 ''note'':120 ''number'':79 ''og'':104 ''one'':71 ''passag'':5 ''perhap'':85 ''race.geshur'':89 ''reign'':92 ''remnant'':111 ''samuel'':33,117 ''second'':11 ''see'':6,115 ''seem'':37 ''son'':12,74 ''talmai'':66,83 ''three'':44 ''transcrib'':57 ''word'':51', NULL, '270');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('271', '2', '271', NULL, 'Beeroth - See the marginal reference. From Joshua 9:17, it might have been expected that the population of Beeroth would be Canaanite. But from some unknown cause the Canaanite inhabitants of Beeroth had fled to Gittaim - perhaps the same as Gath - and continued there as sojourners. If this flight of the Beerothites took place at the time of Saul''s cruel attack upon the Gibeonites 2 Samuel 21:1-2, Baanah and Reehab may have been native Beerothites, and have been instigated to murder the son of Saul by a desire to avenge the blood of their countrymen. The fact of their being reckoned as Benjamites is quite compatible with their being Canaanites by blood.', NULL, NULL, '''-2'':70 ''1'':69 ''17'':9 ''2'':66 ''21'':68 ''9'':8 ''attack'':62 ''aveng'':93 ''baanah'':71 ''beeroth'':1,19,32 ''beerothit'':52,78 ''benjamit'':106 ''blood'':95,115 ''canaanit'':22,29,113 ''caus'':27 ''compat'':109 ''continu'':43 ''countrymen'':98 ''cruel'':61 ''desir'':91 ''expect'':14 ''fact'':100 ''fled'':34 ''flight'':49 ''gath'':41 ''gibeonit'':65 ''gittaim'':36 ''inhabit'':30 ''instig'':82 ''joshua'':7 ''margin'':4 ''may'':74 ''might'':11 ''murder'':84 ''nativ'':77 ''perhap'':37 ''place'':54 ''popul'':17 ''quit'':108 ''reckon'':104 ''reehab'':73 ''refer'':5 ''samuel'':67 ''saul'':59,88 ''see'':2 ''sojourn'':46 ''son'':86 ''time'':57 ''took'':53 ''unknown'':26 ''upon'':63 ''would'':20', NULL, '271');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('272', '2', '272', NULL, 'Compare the marginal reference. The chronicler adds some interesting details 2 Samuel 12:23-40 of the manner in which the various tribes from both sides of the Jordan came to Hebron to make David king, and of the joyful festivities on the occasion. The consummation to which events in God''s Providence had been leading had now come. Saul and Jonathan, Abner and Ish-bosheth, were dead; David was already head of a very large portion of Israel; the Philistines, and perhaps the remnant of the Canaanites, were restless and threatening; and it was obviously the interest of the Israelite nation to unite themselves under the sovereignty of the valiant and virtuous son of Jesse, their former deliverer, and the man designated by the word of God as their Captain and Shepherd. Accordingly he was at once anointed king over all Israel (compare 2 Samuel 2:4 note).', NULL, NULL, '''-40'':15 ''12'':13 ''2'':11,146,148 ''23'':14 ''4'':149 ''abner'':63 ''accord'':135 ''add'':7 ''alreadi'':72 ''anoint'':140 ''bosheth'':67 ''came'':30 ''canaanit'':89 ''captain'':132 ''chronicl'':6 ''come'':59 ''compar'':1,145 ''consumm'':46 ''david'':35,70 ''dead'':69 ''deliver'':120 ''design'':124 ''detail'':10 ''event'':49 ''festiv'':41 ''former'':119 ''god'':51,129 ''head'':73 ''hebron'':32 ''interest'':9,99 ''ish'':66 ''ish-bosheth'':65 ''israel'':80,144 ''israelit'':102 ''jess'':117 ''jonathan'':62 ''jordan'':29 ''joy'':40 ''king'':36,141 ''larg'':77 ''lead'':56 ''make'':34 ''man'':123 ''manner'':18 ''margin'':3 ''nation'':103 ''note'':150 ''obvious'':97 ''occas'':44 ''perhap'':84 ''philistin'':82 ''portion'':78 ''provid'':53 ''refer'':4 ''remnant'':86 ''restless'':91 ''samuel'':12,147 ''saul'':60 ''shepherd'':134 ''side'':26 ''son'':115 ''sovereignti'':109 ''threaten'':93 ''tribe'':23 ''unit'':105 ''valiant'':112 ''various'':22 ''virtuous'':114 ''word'':127', NULL, '272');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('273', '2', '273', NULL, 'Again - It should be, "and David again gathered," etc., i. e. after the previous gathering, either for his election to the kingdom 2 Samuel 5:1-3 or for the Philistine war 2 Samuel 5:17-25, he assembled them again for the peaceful purpose of bringing up the ark to Mount Zion (see marginal reference). The whole narrative indicates the progressive consolidation of David''s power, and the settlement of his monarchy on strong foundations.', NULL, NULL, '''-25'':37 ''-3'':27 ''1'':26 ''17'':36 ''2'':23,33 ''5'':25,35 ''ark'':50 ''assembl'':39 ''bring'':47 ''consolid'':63 ''david'':6,65 ''e'':11 ''either'':16 ''elect'':19 ''etc'':9 ''foundat'':76 ''gather'':8,15 ''indic'':60 ''kingdom'':22 ''margin'':55 ''monarchi'':73 ''mount'':52 ''narrat'':59 ''peac'':44 ''philistin'':31 ''power'':67 ''previous'':14 ''progress'':62 ''purpos'':45 ''refer'':56 ''samuel'':24,34 ''see'':54 ''settlement'':70 ''strong'':75 ''war'':32 ''whole'':58 ''zion'':53', NULL, '273');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('274', '2', '274', NULL, 'There is no indication how soon after the bringing up of the ark these things occurred, but it was probably at no long interval.', NULL, NULL, '''ark'':13 ''bring'':9 ''indic'':4 ''interv'':24 ''long'':23 ''occur'':16 ''probabl'':20 ''soon'':6 ''thing'':15', NULL, '274');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('275', '2', '275', NULL, 'Metheg-ammah must be the name of some stronghold which commanded Gath, and the taking of which made David master of Gath and her towns.', NULL, NULL, '''ammah'':3 ''command'':12 ''david'':20 ''gath'':13,23 ''made'':19 ''master'':21 ''metheg'':2 ''metheg-ammah'':1 ''must'':4 ''name'':7 ''stronghold'':10 ''take'':16 ''town'':26', NULL, '275');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('276', '2', '276', NULL, 'David reaped the fruit of his kindness to Mephibosheth, for, when he fled from Absalom, Machir, the son of Ammiel, was one of those who were most liberal in providing him and his army with necessaries (marginal reference). According to 1 Chronicles 3:5, Ammiel (called inversely Eliam, 2 Samuel 11:3) was the father of Bath-sheba. If this be the same Ammiel, Machir would be Bath-sheba''s brother. However, the name is not a very uncommon one (Numbers 13:12; 1 Chronicles 26:5, etc.).Lo-debar - Evidently on the east of Jordan River, and in the neighborhood of Ish-bosheth''s capital, Mahanaim 2 Samuel 17:27, but not identified by any modern traveler. Thought by some, not improbably, to be the same as Debir Joshua 13:26.', NULL, NULL, '''1'':41,86 ''11'':51 ''12'':85 ''13'':84,135 ''17'':114 ''2'':49,112 ''26'':88,136 ''27'':115 ''3'':43,52 ''5'':44,89 ''absalom'':15 ''accord'':39 ''ammiel'':20,45,65 ''armi'':34 ''bath'':58,70 ''bath-sheba'':57,69 ''bosheth'':108 ''brother'':73 ''call'':46 ''capit'':110 ''chronicl'':42,87 ''david'':1 ''debar'':93 ''debir'':133 ''east'':97 ''eliam'':48 ''etc'':90 ''evid'':94 ''father'':55 ''fled'':13 ''fruit'':4 ''howev'':74 ''identifi'':118 ''improb'':127 ''invers'':47 ''ish'':107 ''ish-bosheth'':106 ''jordan'':99 ''joshua'':134 ''kind'':7 ''liber'':28 ''lo'':92 ''lo-debar'':91 ''machir'':16,66 ''mahanaim'':111 ''margin'':37 ''mephibosheth'':9 ''modern'':121 ''name'':76 ''necessari'':36 ''neighborhood'':104 ''number'':83 ''one'':22,82 ''provid'':30 ''reap'':2 ''refer'':38 ''river'':100 ''samuel'':50,113 ''sheba'':59,71 ''son'':18 ''thought'':123 ''travel'':122 ''uncommon'':81 ''would'':67', NULL, '276');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('277', '2', '277', NULL, 'The king - In marginal reference. Nahash, king, etc. The interval between the two events, not less than 50 years, and possibly more, is against his being the same as the Nahash of 1 Samuel 11:1-15.The Ammonites are almost always spoken of as the children of Ammon, from the name of their first ancestor Ben-ammi Genesis 19:38.Hanun - The equivalent of the Carthaginian Hanno, from the same root as the Hebrew, Hananiah, Johanan, Hannah, etc. The same name appears in composition with Baal in Baal-Hanan, an Aramean king Genesis 36:38-39.', NULL, NULL, '''-39'':96 ''1'':33 ''1-15.the'':36 ''11'':35 ''19'':59 ''36'':94 ''38'':95 ''38.hanun'':60 ''50'':18 ''almost'':39 ''alway'':40 ''ammi'':57 ''ammon'':47 ''ammonit'':37 ''ancestor'':54 ''appear'':81 ''aramean'':91 ''baal'':85,88 ''baal-hanan'':87 ''ben'':56 ''ben-ammi'':55 ''carthaginian'':65 ''children'':45 ''composit'':83 ''equival'':62 ''etc'':8,77 ''event'':14 ''first'':53 ''genesi'':58,93 ''hanan'':89 ''hananiah'':74 ''hannah'':76 ''hanno'':66 ''hebrew'':73 ''interv'':10 ''johanan'':75 ''king'':2,7,92 ''less'':16 ''margin'':4 ''nahash'':6,31 ''name'':50,80 ''possibl'':21 ''refer'':5 ''root'':70 ''samuel'':34 ''spoken'':41 ''two'':13 ''year'':19', NULL, '277');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('278', '2', '278', NULL, 'After the year was expired - The next spring after the escape of the Ammonites into their city 2 Samuel 10:14.The children of Ammon - The marginal reference supplies the word "the land of," which is obviously the right reading.David tarried at Jerusalem - The Syrians being subdued, the war with Ammon was not of sufficient moment to require David''s personal presence. The whole section relating to David''s adultery and Uriah''s death, from this verse to 2 Samuel 12:26, is omitted in the Book of Chronicles.', NULL, NULL, '''10'':20 ''12'':80 ''14.the'':21 ''2'':18,78 ''26'':81 ''adulteri'':69 ''ammon'':24,50 ''ammonit'':14 ''book'':86 ''children'':22 ''chronicl'':88 ''citi'':17 ''david'':58,67 ''death'':73 ''escap'':11 ''expir'':5 ''jerusalem'':42 ''land'':32 ''margin'':26 ''moment'':55 ''next'':7 ''obvious'':36 ''omit'':83 ''person'':60 ''presenc'':61 ''reading.david'':39 ''refer'':27 ''relat'':65 ''requir'':57 ''right'':38 ''samuel'':19,79 ''section'':64 ''spring'':8 ''subdu'':46 ''suffici'':54 ''suppli'':28 ''syrian'':44 ''tarri'':40 ''uriah'':71 ''vers'':76 ''war'':48 ''whole'':63 ''word'':30 ''year'':3', NULL, '278');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('279', '2', '279', NULL, 'Nathan came to David as if to ask his judicial decision on the case about to be submitted to him (compare 2 Samuel 14:2-11; 1 Kings 20:35-41). The circumstances of the story are exquisitely contrived to heighten the pity of David for the oppressed, and his indignation against the oppressor 1 Samuel 25:13, 1 Samuel 25:22.', NULL, NULL, '''-11'':26 ''-41'':31 ''1'':27,55,59 ''13'':58 ''14'':24 ''2'':22,25 ''20'':29 ''22'':62 ''25'':57,61 ''35'':30 ''ask'':8 ''came'':2 ''case'':14 ''circumst'':33 ''compar'':21 ''contriv'':39 ''david'':4,45 ''decis'':11 ''exquisit'':38 ''heighten'':41 ''indign'':51 ''judici'':10 ''king'':28 ''nathan'':1 ''oppress'':48 ''oppressor'':54 ''piti'':43 ''samuel'':23,56,60 ''stori'':36 ''submit'':18', NULL, '279');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('280', '2', '280', NULL, 'The history here, down to the end of 2 Samuel 23 (excepting a few particulars), is omitted in the Book of Chronicles.', NULL, NULL, '''2'':9 ''23'':11 ''book'':20 ''chronicl'':22 ''end'':7 ''except'':12 ''histori'':2 ''omit'':17 ''particular'':15 ''samuel'':10', NULL, '280');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('281', '2', '281', NULL, 'Tekoah - In the south of Judah, six miles from Bethlehem, the modern Tekua. The rough, wild district was well suited for the lawless profession of the wise woman; it abounds in caves, as does the country near Endor.', NULL, NULL, '''abound'':30 ''bethlehem'':10 ''cave'':32 ''countri'':36 ''district'':17 ''endor'':38 ''judah'':6 ''lawless'':23 ''mile'':8 ''modern'':12 ''near'':37 ''profess'':24 ''rough'':15 ''six'':7 ''south'':4 ''suit'':20 ''tekoah'':1 ''tekua'':13 ''well'':19 ''wild'':16 ''wise'':27 ''woman'':28', NULL, '281');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('282', '2', '282', NULL, 'And it came to pass ... - The working out of Nathan''s prophecy (marginal reference) is the clue to the course of the narrative. How long after Absalom''s return these events occurred we are not told.', NULL, NULL, '''absalom'':27 ''came'':3 ''clue'':17 ''cours'':20 ''event'':31 ''long'':25 ''margin'':13 ''narrat'':23 ''nathan'':10 ''occur'':32 ''pass'':5 ''propheci'':12 ''refer'':14 ''return'':29 ''told'':36 ''work'':7', NULL, '282');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('284', '2', '284', NULL, 'This night - The night of the day on which David fled, and Absalom entered into Jerusalem. Ahithophel''s idea was to fall upon David by surprise, and in the first confusion of the surprised army to seize and kill David only.', NULL, NULL, '''absalom'':13 ''ahithophel'':17 ''armi'':35 ''confus'':31 ''david'':10,24,40 ''day'':7 ''enter'':14 ''fall'':22 ''first'':30 ''fled'':11 ''idea'':19 ''jerusalem'':16 ''kill'':39 ''night'':2,4 ''seiz'':37 ''surpris'':26,34 ''upon'':23', NULL, '284');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('285', '2', '285', NULL, 'A third part - This seems to have been a favorite division with the Hebrew commanders (see Judges 7:16; Judges 9:43; 1 Samuel 11:11; 2 Kings 11:5-6) and with the Philistines also 1 Samuel 13:17.', NULL, NULL, '''-6'':31 ''1'':23,37 ''11'':25,26,29 ''13'':39 ''16'':19 ''17'':40 ''2'':27 ''43'':22 ''5'':30 ''7'':18 ''9'':21 ''also'':36 ''command'':15 ''divis'':11 ''favorit'':10 ''hebrew'':14 ''judg'':17,20 ''king'':28 ''part'':3 ''philistin'':35 ''samuel'':24,38 ''see'':16 ''seem'':5 ''third'':2', NULL, '285');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('286', '2', '286', NULL, 'Had Absalom gained the victory, it is likely that, according to the manner of Oriental despots, he would have sought to secure his throne by killing all possible competitors Judges 9:5; 1 Kings 15:29.', NULL, NULL, '''1'':33 ''15'':35 ''29'':36 ''5'':32 ''9'':31 ''absalom'':2 ''accord'':10 ''competitor'':29 ''despot'':16 ''gain'':3 ''judg'':30 ''kill'':26 ''king'':34 ''like'':8 ''manner'':13 ''orient'':15 ''possibl'':28 ''secur'':22 ''sought'':20 ''throne'':24 ''victori'':5 ''would'':18', NULL, '286');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('2', '2', '2', NULL, '- The Seventh Day1.   tsaba'' "a host in marching order," a company of persons or things in the order of their nature and the progressive discharge of their functions. Hence, it is applied to the starry host Deuteronomy 4:19, to the angelic host 1 Kings 22:19, to the host of Israel Exodus 12:41, and to the ministering Levites Numbers 4:23. &#x3ba;&#x3bf;&#x3c3;&#x3bc;&#x3bf;&#x3c2;  kosmos.2.   chashebyy. Here   hashshy is read by the Samaritan Pentateuch, the Septuagint, the Syriac, and Josephus. The Masoretic reading, however, is preferable, as the sixth day was completed in the preceding paragraph: to finish a work on the seventh day is, in Hebrew phrase, not to do any part of it on that day, but to cease from it as a thing already finished; and "resting," in the subsequent part of the verse, is distinct from "finishing," being the positive of which the latter is the negative.  shabat "rest."   yashab "sit."3.   qadsh "be separate, clean, holy, set apart for a sacred use."In this section we have the institution of the day of rest, the Sabbath   shabat, on the cessation of God from his creative activity.Genesis 2:1And all the host of them. - All the array of luminaries, plants, and animals by which the darkness, waste, and solitude of sky and land were removed, has now been called into unhindered action or new existence. The whole is now finished; that is, perfectly suited at length for the convenience of man, the high-born inhabitant of this fair scene. Since the absolute beginning of things the earth may have undergone many changes of climate and surface before it was adapted for the residence of man. But it has received the finishing touch in these last six days. These days accordingly are to man the only period of creation, since the beginning of time, of special or personal interest. The preceding interval of progressive development and periodical creation is, in regard to him, condensed into a point of time. The creative work of the six days is accordingly called the "making," or fitting up for man of "the skies and the land and the sea, and all that in them is" (Exodus 20:10 (Exodus 20:11)).', NULL, NULL, '''1'':44 ''10'':367 ''11'':370 ''12'':54 ''19'':39,47 ''1and'':192 ''2'':191 ''20'':366,369 ''22'':46 ''23'':63 ''3'':155 ''4'':38,62 ''41'':55 ''absolut'':256 ''accord'':294,341 ''action'':225 ''activity.genesis'':190 ''adapt'':274 ''alreadi'':126 ''angel'':42 ''anim'':205 ''apart'':162 ''appli'':32 ''array'':200 ''begin'':257,305 ''born'':248 ''call'':222,342 ''ceas'':120 ''cessat'':184 ''chang'':266 ''chashebyy'':65 ''clean'':159 ''climat'':268 ''compani'':11 ''complet'':91 ''condens'':327 ''conveni'':242 ''creation'':302,321 ''creativ'':189,334 ''dark'':209 ''day'':89,103,117,176,291,293,339 ''day1'':3 ''deuteronomi'':37 ''develop'':318 ''discharg'':25 ''distinct'':138 ''earth'':261 ''exist'':228 ''exodus'':53,365,368 ''fair'':252 ''finish'':97,127,140,233,285 ''fit'':346 ''function'':28 ''god'':186 ''hashshi'':67 ''hebrew'':106 ''henc'':29 ''high'':247 ''high-born'':246 ''holi'':160 ''host'':6,36,43,50,195 ''howev'':83 ''inhabit'':249 ''institut'':173 ''interest'':312 ''interv'':315 ''israel'':52 ''josephus'':79 ''king'':45 ''kosmos.2'':64 ''land'':216,355 ''last'':289 ''latter'':147 ''length'':239 ''levit'':60 ''luminari'':202 ''make'':344 ''man'':244,279,297,349 ''mani'':265 ''march'':8 ''masoret'':81 ''may'':262 ''minist'':59 ''natur'':21 ''negat'':150 ''new'':227 ''number'':61 ''order'':9,18 ''paragraph'':95 ''part'':112,133 ''pentateuch'':73 ''perfect'':236 ''period'':300,320 ''person'':13,311 ''phrase'':107 ''plant'':203 ''point'':330 ''posit'':143 ''preced'':94,314 ''prefer'':85 ''progress'':24,317 ''qadsh'':156 ''read'':69,82 ''receiv'':283 ''regard'':324 ''remov'':218 ''resid'':277 ''rest'':129,152,178 ''sabbath'':180 ''sacr'':165 ''samaritan'':72 ''scene'':253 ''sea'':358 ''section'':169 ''separ'':158 ''septuagint'':75 ''set'':161 ''seventh'':2,102 ''shabat'':151,181 ''sinc'':254,303 ''sit'':154 ''six'':290,338 ''sixth'':88 ''sky'':214,352 ''solitud'':212 ''special'':309 ''starri'':35 ''subsequ'':132 ''suit'':237 ''surfac'':270 ''syriac'':77 ''thing'':15,125,259 ''time'':307,332 ''touch'':286 ''tsaba'':4 ''undergon'':264 ''unhind'':224 ''use'':166 ''vers'':136 ''wast'':210 ''whole'':230 ''work'':99,335 ''yashab'':153', NULL, '2');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('287', '2', '287', NULL, 'The son of Bichri ... - Rather, "a Bichrite," formed like the names "Ahohite," "Hachmonite," etc. 2 Samuel 23:8-9, and so called from Becher, the son of Benjamin Genesis 46:21; 1 Chronicles 7:6-8 Saul was also of this family. It is evident that the transfer of the royalty from their tribe to that of Judah still rankled in the hearts of many Benjamites (2 Samuel 16:8 note).', NULL, NULL, '''-8'':36 ''-9'':19 ''1'':32 ''16'':69 ''2'':15,67 ''21'':31 ''23'':17 ''46'':30 ''6'':35 ''7'':34 ''8'':18,70 ''ahohit'':12 ''also'':39 ''becher'':24 ''benjamin'':28 ''benjamit'':66 ''bichri'':4 ''bichrit'':7 ''call'':22 ''chronicl'':33 ''etc'':14 ''evid'':45 ''famili'':42 ''form'':8 ''genesi'':29 ''hachmonit'':13 ''heart'':63 ''judah'':58 ''like'':9 ''mani'':65 ''name'':11 ''note'':71 ''rankl'':60 ''rather'':5 ''royalti'':51 ''samuel'':16,68 ''saul'':37 ''son'':2,26 ''still'':59 ''transfer'':48 ''tribe'':54', NULL, '287');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('288', '2', '288', NULL, 'There is no note of time whatever, nor any clue as to what part of David''s reign the events of this chapter ought to be assigned.Enquired of the Lord - Hebrew "sought the face of the Lord," quite a different phrase from that so often used in Judges (e. g. Judges 1:1) and the Books of Samuel, and probably indicating that this chapter is from a different source; an inference agreeing with the indefinite "in the days of David," and with the allusion to the slaughter of the Gibeonites, which has not anywhere been narrated.And for his bloody house - literally, "the house of blood," i. e., the house or family upon which rests the guilt of shedding innocent blood.', NULL, NULL, '''1'':52,53 ''agre'':72 ''allus'':84 ''anywher'':94 ''assigned.enquired'':27 ''blood'':105,120 ''bloodi'':99 ''book'':56 ''chapter'':23,64 ''clue'':10 ''david'':16,80 ''day'':78 ''differ'':40,68 ''e'':49,107 ''event'':20 ''face'':34 ''famili'':111 ''g'':50 ''gibeonit'':90 ''guilt'':116 ''hebrew'':31 ''hous'':100,103,109 ''indefinit'':75 ''indic'':61 ''infer'':71 ''innoc'':119 ''judg'':48,51 ''liter'':101 ''lord'':30,37 ''narrated.and'':96 ''note'':4 ''often'':45 ''ought'':24 ''part'':14 ''phrase'':41 ''probabl'':60 ''quit'':38 ''reign'':18 ''rest'':114 ''samuel'':58 ''shed'':118 ''slaughter'':87 ''sought'':32 ''sourc'':69 ''time'':6 ''upon'':112 ''use'':46 ''whatev'':7', NULL, '288');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('289', '2', '289', NULL, 'This song, which is found with scarcely any material variation as Psalm 18, and with the words of this first verse for its title, belongs to the early part of David''s reign when he was recently established upon the throne of all Israel, and when his final triumph over the house of Saul, and over the pagan nations 2 Samuel 22:44-46, Philistines, Moabites, Syrians, Ammonites, and Edomites, was still fresh 2 Samuel 21. For a commentary on the separate verses the reader is referred to the commentary on Psalm 18. The last words of David - i. e., his last Psalm, his last "words of song" 2 Samuel 22:1. The insertion of this Psalm, which is not in the Book of Psalms, was probably suggested by the insertion of the long Psalm in 2 Samuel 22.David the son of Jesse said ... - The original word for "said" is used between 200 and 300 times in the phrase, "saith the Lord," designating the word of God in the mouth of the prophet. It is only applied to the words of a man here, and in the strikingly similar passage Numbers 24:3-4, Numbers 24:15-16, and in Proverbs 30:1; and in all these places the words spoken are inspired words. The description of David is divided into four clauses, which correspond to and balance each other.', NULL, NULL, '''-16'':198 ''-4'':194 ''-46'':64 ''1'':112,203 ''15'':197 ''18'':13,93 ''2'':60,74,109,137 ''200'':153 ''21'':76 ''22'':62,111 ''22.david'':139 ''24'':192,196 ''3'':193 ''30'':202 ''300'':155 ''44'':63 ''ammonit'':68 ''appli'':177 ''balanc'':228 ''belong'':25 ''book'':123 ''claus'':223 ''commentari'':79,90 ''correspond'':225 ''david'':31,98,218 ''descript'':216 ''design'':163 ''divid'':220 ''e'':100 ''earli'':28 ''edomit'':70 ''establish'':38 ''final'':48 ''first'':20 ''found'':5 ''four'':222 ''fresh'':73 ''god'':167 ''hous'':52 ''insert'':114,131 ''inspir'':213 ''israel'':44 ''jess'':143 ''last'':95,102,105 ''long'':134 ''lord'':162 ''man'':183 ''materi'':9 ''moabit'':66 ''mouth'':170 ''nation'':59 ''number'':191,195 ''origin'':146 ''pagan'':58 ''part'':29 ''passag'':190 ''philistin'':65 ''phrase'':159 ''place'':208 ''probabl'':127 ''prophet'':173 ''proverb'':201 ''psalm'':12,92,103,117,125,135 ''reader'':85 ''recent'':37 ''refer'':87 ''reign'':33 ''said'':144,149 ''saith'':160 ''samuel'':61,75,110,138 ''saul'':54 ''scarc'':7 ''separ'':82 ''similar'':189 ''son'':141 ''song'':2,108 ''spoken'':211 ''still'':72 ''strike'':188 ''suggest'':128 ''syrian'':67 ''throne'':41 ''time'':156 ''titl'':24 ''triumph'':49 ''upon'':39 ''use'':151 ''variat'':10 ''vers'':21,83 ''word'':17,96,106,147,165,180,210,214', NULL, '289');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('504', '2', '504', NULL, 'Judge me, O Lord - That is, determine in regard to my case whether I am truly thy friend, or whether the evidences of my piety are genuine. The psalmist asks an examination of his own case; he brings the matter before God for Him to decide; he submits the facts in regard to himself to God, so that He may pronounce upon them whether they constitute evidence of real piety.For I have walked in mine integrity - On the word "walk," see the notes at Psalm 1:1. The word "integrity" here is the same which is elsewhere rendered "perfection." See the notes at Job 1:1. Compare Psalm 37:37. See also Psalm 7:8; Psalm 25:21; where the word is rendered, as here, "integrity." It means here "uprightness, sincerity." This is the first thing which he brings before God for him to examine - the consciousness that he had endeavored to live an upright life; and yet it is referred to as if he was sensible that he "might" have deceived himself, and therefore, he prays that God would determine whether his life had been really upright.I have trusted also in the Lord - Of this, likewise, he felt conscious; but this too he desired to submit to God. Trust in Yahweh, and an upright life, constituted the evidence of piety, or were the constituents of true religion according to the views of the Hebrews, as they are the constituents of true religion everywhere; and the purpose of the psalmist was to ascertain whether his piety was really of that character.Therefore I shall not slide - If these are really traits of my character, if I really possess these, I shall not be moved. My feet will be firm, and I shall be secure. Or this may be regarded as a further declaration in regard to himself, as indicating firm confidence in God, and as meaning that he was conscious that he would not be moved, or would not swerve in this purpose of life. And yet the next verse shows that, with all this confidence as to his own character, he felt that there was a "possibility" of his having deceived himself; and, therefore, he pleaded that God would search and test him.', NULL, NULL, '''1'':86,87,105,106 ''21'':118 ''25'':117 ''37'':109,110 ''7'':114 ''8'':115 ''accord'':229 ''also'':112,191 ''ascertain'':253 ''ask'':30 ''bring'':38,139 ''case'':12,36 ''charact'':273,350 ''character.therefore'':261 ''compar'':107 ''confid'':310,345 ''conscious'':147,200,319 ''constitu'':225,240 ''constitut'':66,217 ''deceiv'':172,361 ''decid'':46 ''declar'':302 ''desir'':205 ''determin'':7,181 ''elsewher'':97 ''endeavor'':151 ''everywher'':244 ''evid'':22,67,219 ''examin'':32,145 ''fact'':50 ''feet'':285 ''felt'':199,352 ''firm'':288,309 ''first'':135 ''friend'':18 ''genuin'':27 ''god'':42,56,141,179,209,312,368 ''hebrew'':235 ''indic'':308 ''integr'':76,90,126 ''job'':104 ''judg'':1 ''life'':156,184,216,334 ''likewis'':197 ''live'':153 ''lord'':4,194 ''matter'':40 ''may'':60,296 ''mean'':128,315 ''might'':170 ''mine'':75 ''move'':283,325 ''next'':338 ''note'':83,102 ''o'':3 ''perfect'':99 ''pieti'':25,221,256 ''piety.for'':70 ''plead'':366 ''possess'':277 ''possibl'':357 ''pray'':177 ''pronounc'':61 ''psalm'':85,108,113,116 ''psalmist'':29,250 ''purpos'':247,332 ''real'':69 ''realli'':187,258,269,276 ''refer'':161 ''regard'':9,52,298,304 ''religion'':228,243 ''render'':98,123 ''search'':370 ''secur'':293 ''see'':81,100,111 ''sensibl'':167 ''shall'':263,280,291 ''show'':340 ''sincer'':131 ''slide'':265 ''submit'':48,207 ''swerv'':329 ''test'':372 ''therefor'':175,364 ''thi'':17 ''thing'':136 ''trait'':270 ''true'':227,242 ''truli'':16 ''trust'':190,210 ''upon'':62 ''upright'':130,155,215 ''upright.i'':188 ''vers'':339 ''view'':232 ''walk'':73,80 ''whether'':13,20,64,182,254 ''word'':79,89,121 ''would'':180,322,327,369 ''yahweh'':212 ''yet'':158,336', NULL, '504');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('290', '2', '290', NULL, 'Although my house ... - The sense of this clause (according to the the King James Version) will be that David comparing the actual state of his family and kingdom during the later years of trouble and disaster with the prophetic description of the prosperity of the righteous king, and seeing how far it falls short, comforts himself by the terms of God''s covenant 2 Samuel 7:12-16 and looks forward to Messiah''s kingdom. The latter clause, "although he make it not to grow," must then mean that, although at the present time the glory of his house was not made to grow, yet all his salvation and all his desire was made sure in the covenant which would be fulfilled in due time. But most modern commentators understand both clauses as follows: "Is not my house so with God that He has made with me an everlasting covenant," etc.? "For all my salvation and all my desire, will He not cause it to spring up?" namely, in the kingdom of Solomon, and still more fully in the kingdom of Christ.', NULL, NULL, '''-16'':68 ''12'':67 ''2'':64 ''7'':66 ''accord'':9 ''actual'':22 ''although'':1,79,90 ''caus'':163 ''christ'':182 ''claus'':8,78,132 ''comfort'':55 ''comment'':129 ''compar'':20 ''coven'':63,118,150 ''david'':19 ''descript'':40 ''desir'':112,159 ''disast'':36 ''due'':124 ''etc'':151 ''everlast'':149 ''fall'':53 ''famili'':26 ''far'':51 ''follow'':134 ''forward'':71 ''fulfil'':122 ''fulli'':177 ''glori'':96 ''god'':61,141 ''grow'':85,104 ''hous'':3,99,138 ''jame'':14 ''king'':13,47 ''kingdom'':28,75,171,180 ''later'':31 ''latter'':77 ''look'':70 ''made'':102,114,145 ''make'':81 ''mean'':88 ''messiah'':73 ''modern'':128 ''must'':86 ''name'':168 ''present'':93 ''prophet'':39 ''prosper'':43 ''righteous'':46 ''salvat'':108,155 ''samuel'':65 ''see'':49 ''sens'':5 ''short'':54 ''solomon'':173 ''spring'':166 ''state'':23 ''still'':175 ''sure'':115 ''term'':59 ''time'':94,125 ''troubl'':34 ''understand'':130 ''version'':15 ''would'':120 ''year'':32 ''yet'':105', NULL, '290');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('291', '2', '291', NULL, 'And again the anger of the Lord was kindled against Israel - This sentence is the heading of the whole chapter, which goes on to describe the sin which kindled this anger, namely, the numbering of the people 1 Chronicles 21:7-8; 1 Chronicles 27:24. There is no note of time, except that the word "again" shows that these events happened "after" those of 2 Samuel 21. (Compare also 2 Samuel 24:25; 2 Samuel 21:14.)And he moved David - In 1 Chronicles 21:1 the statement is, "and an adversary" (not "Satan," as the King James Version, since there is no article prefixed, as in Job 1:6; Job 2:1, etc.) "stood up against Israel and moved David," just as 1 Kings 11:14, 1 Kings 11:23, 1 Kings 11:25 first Hadad, and then Rezon, is said to have been "an adversary" (Satan) to Solomon and to Israel. Hence, our text should be rendered, "For one moved David against them." We are not told whose advice it was, but some one, who proved himself an enemy to the best interests of David and Israel, urged the king to number the people.', NULL, NULL, '''-8'':42 ''1'':38,43,84,87,110,114,125,129,133 ''11'':127,131,135 ''14'':78,128 ''2'':66,71,75,113 ''21'':40,68,77,86 ''23'':132 ''24'':46,73 ''25'':74,136 ''27'':45 ''6'':111 ''7'':41 ''adversari'':93,148 ''advic'':172 ''also'':70 ''anger'':4,31 ''articl'':105 ''best'':185 ''chapter'':20 ''chronicl'':39,44,85 ''compar'':69 ''david'':82,122,164,188 ''describ'':25 ''enemi'':182 ''etc'':115 ''event'':61 ''except'':53 ''first'':137 ''goe'':22 ''hadad'':138 ''happen'':62 ''head'':16 ''henc'':155 ''interest'':186 ''israel'':11,119,154,190 ''jame'':99 ''job'':109,112 ''kindl'':9,29 ''king'':98,126,130,134,193 ''lord'':7 ''move'':81,121,163 ''name'':32 ''note'':50 ''number'':34,195 ''one'':162,177 ''peopl'':37,197 ''prefix'':106 ''prove'':179 ''render'':160 ''rezon'':141 ''said'':143 ''samuel''