INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('7', '2', '7', NULL, '- The Ark Was Entered2.   tahor "clean, fit for food or sacrifice."4.   yequm "standing thing; what grows up, whether animal or plant." Compare   qamah "stalk, or standing corn."Genesis 7:1-4Here is found the command to enter the ark. The general direction in the preceding chapter was given many years ago, before the ark was commenced. Now, when it is completed, a more specific command is issued. "For thee have I seen righteous before me." Noah has accepted the mercy of God, is therefore set right in point of law, and walks aright in point of practice. The Lord recognizes this indication of an adopted and renewed son. "In this age" he and his were the solitary family so characterized.', NULL, NULL, '''-4'':32 ''1'':31 ''4'':12 ''7'':30 ''accept'':80 ''adopt'':107 ''age'':113 ''ago'':53 ''anim'':20 ''aright'':95 ''ark'':2,41,56 ''chapter'':48 ''character'':122 ''clean'':6 ''command'':37,67 ''commenc'':58 ''compar'':23 ''complet'':63 ''corn'':28 ''direct'':44 ''enter'':39 ''entered2'':4 ''famili'':120 ''fit'':7 ''food'':9 ''found'':35 ''general'':43 ''genesi'':29 ''given'':50 ''god'':84 ''grow'':17 ''indic'':104 ''issu'':69 ''law'':92 ''lord'':101 ''mani'':51 ''merci'':82 ''noah'':78 ''plant'':22 ''point'':90,97 ''practic'':99 ''preced'':47 ''qamah'':24 ''recogn'':102 ''renew'':109 ''right'':88 ''righteous'':75 ''sacrific'':11 ''seen'':74 ''set'':87 ''solitari'':119 ''son'':110 ''specif'':66 ''stalk'':25 ''stand'':14,27 ''tahor'':5 ''thee'':71 ''therefor'':86 ''thing'':15 ''walk'':94 ''whether'':19 ''year'':52 ''yequm'':13', NULL, '7');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('8', '2', '8', NULL, '- The Land Was Dried1.   shakak "stoop, assuage."3.   chasar "want, fail, be abated."4.   ''ararat, "Ararat," a land forming part of Armenia. It is mentioned in 2 Kings 19:37, and Isaiah 37:38, as the retreat of Adrammelek and Sharezer after the murder of their father; and in Jeremiah 51:27 as a kingdom.8.   qalal, "be light, lightened, lightly esteemed, swift."10.   chul, "twist, turn, dance, writhe, tremble, be strong, wait."   yachal "remain, wait, hope."13.   chareb, "be drained, desolated, amazed."Genesis 8:1-3The waters commence their retreat. "And God remembered Noah." He is said to remember him when he takes any step to deliver him from the waters. The several steps to this end are enumerated.A wind. - This would promote evaporation, and otherwise aid the retreat of the waters. "The fountains of the deep and the windows of the skies were shut." The incessant and violent showers had continued for six weeks. It is probable the weather remained turbid and moist for some time longer. In the sixth month, however, the rain probably ceased altogether. Some time before this, the depressing of the ground had reached its lowest point, and the upheaving had set in. This is the main cause of the reflux of the waters. All this is described, as we perceive, according to appearance. It is probable that the former configuration of the surface was not exactly restored. At all events it is not necessary, as the ark may have drifted a considerable space in a hundred and fifty days. Some of the old ground on which primeval man had trodden may have become a permanent water bed, and a like amount of new land may have risen to the light in another place. Hence, it is vain to seek for a spot retaining the precise conditions of the primitive Eden. The Euphrates and Tigris may substantially remain, but the Pishon and Gihon may have considerably changed. The Black Sea, the Caspian, the lakes Van and Urumiah may cover portions of the Adamic land. At the end of the hundred and fifty days the prevalence of the waters begins to turn into a positive retreat.', NULL, NULL, '''-3'':86 ''1'':85 ''10'':63 ''13'':77 ''19'':29 ''2'':27 ''27'':52 ''3'':8 ''37'':30,33 ''38'':34 ''4'':14 ''51'':51 ''8'':84 ''abat'':13 ''accord'':218 ''adam'':339 ''adrammelek'':39 ''aid'':128 ''altogeth'':179 ''amaz'':82 ''amount'':278 ''anoth'':289 ''appear'':220 ''ararat'':15,16 ''ark'':244 ''armenia'':22 ''assuag'':7 ''becom'':270 ''bed'':274 ''begin'':355 ''black'':325 ''caspian'':328 ''caus'':204 ''ceas'':178 ''chang'':323 ''chareb'':78 ''chasar'':9 ''chul'':64 ''commenc'':89 ''condit'':303 ''configur'':227 ''consider'':249,322 ''continu'':153 ''cover'':335 ''danc'':67 ''day'':256,349 ''deep'':138 ''deliv'':108 ''depress'':185 ''describ'':214 ''desol'':81 ''drain'':80 ''dried1'':4 ''drift'':247 ''eden'':307 ''end'':118,343 ''enumerated.a'':120 ''esteem'':61 ''euphrat'':309 ''evapor'':125 ''event'':237 ''exact'':233 ''fail'':11 ''father'':47 ''fifti'':255,348 ''form'':19 ''former'':226 ''fountain'':135 ''genesi'':83 ''gihon'':319 ''god'':93 ''ground'':188,261 ''henc'':291 ''hope'':76 ''howev'':174 ''hundr'':253,346 ''incess'':148 ''isaiah'':32 ''jeremiah'':50 ''king'':28 ''kingdom.8'':55 ''lake'':330 ''land'':2,18,281,340 ''light'':58,60,287 ''lighten'':59 ''like'':277 ''longer'':169 ''lowest'':192 ''main'':203 ''man'':265 ''may'':245,268,282,312,320,334 ''mention'':25 ''moist'':165 ''month'':173 ''murder'':44 ''necessari'':241 ''new'':280 ''noah'':95 ''old'':260 ''otherwis'':127 ''part'':20 ''perceiv'':217 ''perman'':272 ''pishon'':317 ''place'':290 ''point'':193 ''portion'':336 ''posit'':360 ''precis'':302 ''preval'':351 ''primev'':264 ''primit'':306 ''probabl'':159,177,223 ''promot'':124 ''qalal'':56 ''rain'':176 ''reach'':190 ''reflux'':207 ''remain'':74,162,314 ''rememb'':94,100 ''restor'':234 ''retain'':300 ''re