INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('9', '2', '9', NULL, '- The Blessing of Noah2.   mora'', "fear, reverence, awful deed."   chat, "dread, breaking of the courage."Noah is saved from the deluge. His life is twice given to him by God. He had found grace in the sight of the Lord, and now he and his family have been graciously accepted when they approached the Lord with burnt-offerings. In him, therefore, the race of man is to be begun anew. Accordingly, as at the beginning, the Lord proceeds to bless him. First. The grant of increase is the same as at first, but expressed in ampler terms. Second. Dominion over the other animals is renewed. But some reluctance on their part to yield obedience is intimated. "The fear and dread of you." These terms give token of a master whose power is dreaded, rather than of a superior whose friendly protection is sought. "Into your hand are they given." They are placed entirely at the disposal of man.', NULL, NULL, '''accept'':50 ''accord'':72 ''ampler'':97 ''anew'':71 ''anim'':104 ''approach'':53 ''aw'':8 ''begin'':76 ''begun'':70 ''bless'':2,81 ''break'':12 ''burnt'':58 ''burnt-off'':57 ''chat'':10 ''courag'':15 ''deed'':9 ''delug'':21 ''dispos'':157 ''dominion'':100 ''dread'':11,121,134 ''entir'':154 ''express'':95 ''famili'':46 ''fear'':6,119 ''first'':83,93 ''found'':33 ''friend'':141 ''give'':126 ''given'':26,150 ''god'':30 ''grace'':34 ''gracious'':49 ''grant'':85 ''hand'':147 ''increas'':87 ''intim'':117 ''life'':23 ''lord'':40,55,78 ''man'':66,159 ''master'':130 ''mora'':5 ''noah'':16 ''noah2'':4 ''obedi'':115 ''offer'':59 ''part'':112 ''place'':153 ''power'':132 ''proceed'':79 ''protect'':142 ''race'':64 ''rather'':135 ''reluct'':109 ''renew'':106 ''rever'':7 ''save'':18 ''second'':99 ''sight'':37 ''sought'':144 ''superior'':139 ''term'':98,125 ''therefor'':62 ''token'':127 ''twice'':25 ''whose'':131,140 ''yield'':114', NULL, 