INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('29', '2', '29', NULL, 'Jacob arrives at the well of Haran. "The land of the sons of the east." The points of the heavens were defined by the usage of practical life, and not by the standard of a science yet unknown. Hence, the east means any quarter toward the sunrising. Haran was about four degrees east of Beer-sheba, and five and a half degrees north. The distance was about four hundred and fifty miles, and therefore it would take Jacob fifteen days to perform the journey at thirty miles a day. If he reached Bethel the first night, he must have travelled about fifty miles the first day. After this he proceeds on his journey without any memorable incident. In the neighborhood of Haran he comes upon a well, by which lay three flocks. This is not the well near Haran where Abraham''s servant met Rebekah. It is in the pasture grounds at some distance from the town. On its mouth was a large stone, indicating that water was precious, and that the well was the common property of the surrounding natives. The custom was to gather the flocks, roll away the stone, which was too great to be moved by a boy or a female, water the flocks, and replace the stone. Jacob, on making inquiry, learns that Haran is at hand, that Laban is well, and that Rachel is drawing nigh with her father''s flocks. Laban is called by Jacob the son of Nahor, that is, his grandson, with the usual latitude of relative names in Scripture Genesis 28:13. "The day is great." A great part of it yet remains. It is not yet the time to shut up the cattle for the night; "water the sheep and go feed them." Jacob may have wished to meet with Rachel without presence of the shepherds. "We cannot." There was a rule or custom that the flocks must be all assembled before the stone was rolled away for the purpose of watering the cattle. This may have been required to insure a fair distribution of the water to all parties, and especially to those who were too weak to roll away the stone.', NULL, NULL, '''13'':263 ''28'':262 ''abraham'':142 ''arriv'':2 ''assembl'':323 ''away'':191,329,363 ''beer'':56 ''beer-sheba'':55 ''bethel'':94 ''boy'':203 ''call'':241 ''cannot'':310 ''cattl'':285,336 ''come'':125 ''common'':177 ''custom'':184,316 ''day'':81,90,107,265 ''defin'':22 ''degre'':52,63 ''distanc'':66,155 ''distribut'':346 ''draw'':232 ''east'':15,41,53 ''especi'':354 ''fair'':345 ''father'':236 ''feed'':294 ''femal'':206 ''fifteen'':80 ''fifti'':72,103 ''first'':96,106 ''five'':59 ''flock'':133,189,209,238,319 ''four'':51,69 ''gather'':187 ''genesi'':261 ''go'':293 ''grandson'':251 ''great'':197,267,269 ''ground'':152 ''half'':62 ''hand'':223 ''haran'':7,48,123,140,220 ''heaven'':20 ''henc'':39 ''hundr'':70 ''incid'':118 ''indic'':166 ''inquiri'':217 ''insur'':343 ''jacob'':1,79,214,243,296 ''journey'':85,114 ''laban'':225,239 ''land'':9 ''larg'':164 ''latitud'':255 ''lay'':131 ''learn'':218 ''life'':28 ''make'':216 ''may'':297,338 ''mean'':42 ''meet'':301 ''memor'':117 ''met'':145 ''mile'':73,88,104 ''mouth'':161 ''move'':200 ''must'':99,320 ''nahor'':247 ''name'':258 ''nativ'':182 ''near'':139 ''neighborhood'':121 ''nigh'':233 ''night'':97,288 ''north'':64 ''part'':270 ''parti'':352 ''pastur'':151 ''perform'':83 ''point'':17 ''practic'':27 ''precious'':170 ''presenc'':305 ''proceed'':111 ''properti'':178 ''purpos'':332 ''quarter'':44 ''rachel'':230,303 ''reach'':93 ''rebekah'':146 ''relat'':257 ''remain'':274 ''replac'':211 ''requir'':341 ''roll'':190,328,362 ''rule'':314 ''scienc'':36 ''scriptur'':260 ''servant'':144 ''sheba'':57 ''sheep'':291 ''shepherd'':308 ''shut'':282 ''son'':12,245 ''standard'':33 ''stone'':165,193,213,326,365 ''sunris'':47 ''surround'':181 ''take'':78 ''therefor'':75 ''thirti'':87 ''three'':132 ''time'':280 ''toward'':45 ''town'':158 ''travel'':101 ''unknown'':38 ''upon'':126 ''usag'':25 ''usual'':254 ''water'':168,207,289,