INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('30', '2', '30', NULL, 'Bilhah, Rachel''s maid, bears two sons. Rachel becomes impatient of her barrenness and jealous of her sister, and unjustly reproaches her husband, who indignantly rebukes her. God, not he, has withheld children from her. She does what Sarah had done before her Genesis 16:2-3, gives her handmaid to her husband. No express law yet forbade this course, though nature and Scripture by implication did Genesis 2:23-25. "Dan." "God hath judged me." In this passage Jacob and Rachel use the common noun, God, the Everlasting, and therefore Almighty, who rules in the physical relations of things - a name suitable to the occasion. He had judged her, dealt with her according to his sovereign justice in withholding the fruit of the womb, when she was self-complacent and forgetful of her dependence on a higher power; and also in hearing her voice when she approached him in humble supplication. "Naphtali." "Wrestlings of God," with God, in prayer, on the part of both sisters, so that they wrestled with one another in the self-same act. Rachel, though looking first to Jacob and then to her maid, had at length learned to look to her God, and then had prevailed.', NULL, NULL, '''-25'':71 ''-3'':47 ''16'':45 ''2'':46,69 ''23'':70 ''accord'':114 ''act'':180 ''almighti'':92 ''also'':142 ''anoth'':174 ''approach'':149 ''barren'':13 ''bear'':5 ''becom'':9 ''bilhah'':1 ''children'':33 ''common'':85 ''complac'':131 ''cours'':60 ''dan'':72 ''dealt'':111 ''depend'':136 ''done'':41 ''everlast'':89 ''express'':55 ''first'':184 ''forbad'':58 ''forget'':133 ''fruit'':122 ''genesi'':44,68 ''give'':48 ''god'':28,73,87,157,159,200 ''handmaid'':50 ''hath'':74 ''hear'':144 ''higher'':139 ''humbl'':152 ''husband'':23,53 ''impati'':10 ''implic'':66 ''indign'':25 ''jacob'':80,186 ''jealous'':15 ''judg'':75,109 ''justic'':118 ''law'':56 ''learn'':195