INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('481', '2', '481', NULL, 'A Psalm of David - literally, belonging to David; that is, belonging to him as the author. This is marked in the Hebrew as the first verse, and so in the Syriac version, the Latin Vulgate, and the Septuagint, making in the Hebrew, and in each of these versions, nine verses in the psalm instead of eight, as in our translation. This may have been prefixed to the psalm by the author himself, for it was not uncommon in ancient times for an author to prefix his name to his own composition, as is commonly done by the apostle Paul in his epistles. It is not absolutely certain, however, that this was done in the Psalms by the authors themselves, but it may have been done by him who collected and arranged the Psalms, indicating the prevalent belief in regard to the authorship, and under the Spirit of inspiration.When he fled - On the occasion of his fleeing. That is, it was composed at that time, or was subsequently composed in remembrance of it. See Introduction, Section 2.From Absalom his son - See the introduction, Section 2.Lord, how are they increased - How are they multiplied; or, how numerous they are. Perhaps the idea is, that at first they seemed to be comparatively few in number, but had now so multiplied as to endanger his crown and life. This is an appropriate expression on the supposition that it refers to Absalom. At first the number of those who adhered to Absalom was not so great as to excite much alarm; but by the arts of a demagogue, by complaining of the government, by saying that if he were made a judge in tim land, every man would have justice done him 2 Samuel 15:4-5, he won the hearts of the people, and gathered so many under his standard as to make it necessary that the king should flee from Jerusalem to a place of safety.That trouble me - literally, my enemies. The allusion is to those who were now enlisted under Absalom, and who were engaged in endeavoring to overthrow the government.Many are they that rise up against me - That is, that have become my enemies.', NULL, NULL, '''-5'':292 ''15'':290 ''2'':288 ''2.from'':176 ''2.lord'':184 ''4'':291 ''absalom'':177,237,247,339 ''absolut'':106 ''adher'':245 ''alarm'':256 ''allus'':330 ''ancient'':79 ''apostl'':98 ''appropri'':228 ''arrang'':131 ''art'':260 ''author'':16,71,83,118 ''authorship'':142 ''becom'':361 ''belief'':137 ''belong'':6,11 ''certain'':107 ''collect'':129 ''common'':94 ''compar'':209 ''complain'':265 ''compos'':161,168 ''composit'':91 ''crown'':222 ''david'':4,8 ''demagogu'':263 ''done'':95,112,125,286 ''eight'':56 ''endang'':220 ''endeavor'':345 ''enemi'':328,363 ''engag'':343 ''enlist'':337 ''epistl'':102 ''everi'':281 ''excit'':254 ''express'':229 ''first'':25,204,239 ''fled'':150 ''flee'':156,316 ''gather'':301 ''govern'':268 ''government.many'':349 ''great'':251 ''heart'':296 ''hebrew'':22,42 ''howev'':108 ''idea'':200 ''increas'':188 ''indic'':134 ''inspiration.when'':148 ''instead'':54 ''introduct'':174,182 ''jerusalem'':318 ''judg'':277 ''justic'':285 ''king'':314 ''land'':280 ''latin'':34 ''life'':224 ''liter'':5,326 ''made'':275 ''make'':39,309 ''man'':282 ''mani'':303 ''mark'':19 ''may'':62,122 ''much'':255 ''multipli'':192,217 ''name'':87 ''necessari'':311 ''nine'':49 ''number'':212,241 ''numer'':195 ''occas'':153 ''overthrow'':347 ''paul'':99 ''peopl'':299 ''perhap'':198 ''place'':321 ''prefix'':65,85 ''preval'':136 ''psalm'':2,53,68,115,133 ''refer'':235 ''regard'':139 ''remembr'':170 ''rise'':353 ''safety.that'':323 ''samuel'':289 ''say'':270 ''section'':175,183 ''see'':173,180 ''seem'':206 ''septuagint'':38 ''son'':179 ''spirit'':146 ''standard'':306 ''subsequ'':167 ''supposit'':232 ''syriac'':31 ''tim'':279 ''time'':80,164 ''translat'':60 ''troubl'':324 ''uncommon'':77 ''vers'':26,50 ''version'':32,48 ''vulgat'':35 ''won'':294 ''would'':283', NULL, '481');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('482', '2', '482', NULL, 'Hear me when I call - When I pray. The word "hear" in such cases is always used in the sense of "listen to," "hear favorably," or "attend to;" hence, in the literal sense it is always true that God "hears" all that is said. The meaning is, "hear and answer me," or grant me what Iask.O God of my righteousness - That is, O my righteous God. This is a common mode of expression in Hebrew. Thus, in Psalm 2:6, "hill of my holiness," meaning "my holy hill;" Psalm 3:4, "his hill of holiness," meaning "his holy hill." The psalmist here appeals to God as "his" God - the God in whom he trusted; and as a "righteous" God - a God who would do that which was right, and on whom, therefore, he might rely as one who would protect his own people. The appeal to God as a righteous God implies a conviction in the mind of the psalmist of the justice of his cause; and he asks God merely to do "right" in the case. It is not on the ground of his own claim as a righteous man, but it is that, in this particular case, he was wrongfully persecuted; and he asks God to interpose, and to cause justice to be done. This is always a proper ground of appeal to God. A man may be sensible that in a particular case he has justice on his side, though he has a general conviction that he himself is a sinner; and he may pray to God to cause his enemies to do right, or to lead those whose office it is to decide the case, to do what ought to be done to vindicate his name, or to save him from wrong.Thou hast enlarged me when I was in distress - That is, on some former occasion. When he was "pressed" or "confined," and knew not how to escape, God had interposed and had given him room, so that he felt free. He now implores the same mercy again. He feels that the God who had done it in former troubles could do it again; and he asks him to repeat his mercy. The prayer indicates confidence in the power and the unchangeableness of God, and proves that it is right in our prayers to recall the former instances of the divine interposition, as an argument, or as a ground of hope that God would again interpose.Have mercy upon me - In my present troubles. That is, Pity me, and have compassion on me, as thou hast done in former times. Who that has felt the assurance that God has heard his prayer in former times, and has delivered him from trouble, will not go to him with the more confident assurance that he will hear him again?', NULL, NULL, '''2'':79 ''3'':90 ''4'':91 ''6'':80 ''alway'':16,36,219 ''answer'':50 ''appeal'':103,145,224 ''argument'':399 ''ask'':169,206,361 ''assur'':439,464 ''attend'':27 ''call'':5 ''case'':14,177,199,236,279 ''caus'':166,212,262 ''claim'':187 ''common'':70 ''compass'':424 ''confid'':370,463 ''confin'':316 ''convict'':154,248 ''could'':355 ''decid'':277 ''deliv'':451 ''distress'':304 ''divin'':395 ''done'':216,286,350,430 ''enemi'':264 ''enlarg'':298 ''escap'':322 ''express'':73 ''favor'':25 ''feel'':344 ''felt'':334,437 ''former'':309,353,391,432,447 ''free'':335 ''general'':247 ''given'':328 ''go'':457 ''god'':39,57,66,105,108,110,119,121,147,151,170,207,226,260,323,347,378,407,441 ''grant'':53 ''ground'':183,222,403 ''hast'':297,429 ''hear'':1,11,24,40,48,468 ''heard'':443 ''hebrew'':75 ''henc'':29 ''hill'':81,88,93,99 ''holi'':84,87,95,98 ''hope'':405 ''iask.o'':56 ''impli'':152 ''implor'':338 ''indic'':369 ''instanc'':392 ''interpos'':209,325 ''interpose.have'':410 ''interposit'':396 ''justic'':163,213,239 ''knew'':318 ''lead'':270 ''listen'':22 ''liter'':32 ''man'':191,228 ''may'':229,257 ''mean'':46,85,96 ''merci'':341,366,411 ''mere'':171 ''might'':134 ''mind'':157 ''mode'':71 ''name'':290 ''o'':63 ''occas'':310 ''offic'':273 ''one'':137 ''ought'':283 ''particular'':198,235 ''peopl'':143 ''persecut'':203 ''piti'':420 ''power'':373 ''pray'':8,258 ''prayer'':368,387,445 ''present'':416 ''press'':314 ''proper'':221 ''protect'':140 ''prove'':380 ''psalm'':78,89 ''psalmist'':101,160 ''recal'':389 ''reli'':135 ''repeat'':364 ''right'':128,174,267,384 ''righteous'':60,65,118,150,190 ''room'':330 ''said'':44 ''save'':293 ''sens'':20,33 ''sensibl'':231 ''side'':242 ''sinner'':254 ''therefor'':132 ''thou'':428 ''though'':243 ''thus'':76 ''time'':433,448 ''troubl'':354,417,454 ''true'':37 ''trust'':114 ''unchang'':376 ''upon'':412 ''use'':17 ''vindic'':288 ''whose'':272 ''word'':10 ''would'':123,139,408 ''wrong'':202 ''wrong.thou'':296', NULL, '482');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('483', '2', '483', NULL, 'Upon Nehiloth - The title of Psalm 4:1-8 is, "upon Neginoth." As that refers to a musical instrument, so it is probable that this does, and that the idea here is that this psalm was intended particularly for the music-master that had special charge of this instrument, or who presided over those that played on it. Perhaps the idea is that this psalm was specially designed to be accompanied with this instrument. The word here, Nehiloth -   nechyloth, plural.   nechylah, singular - is supposed by Gesenius, Lexicon, to denote a flute, or pipe, as being "perforated," from   chalal, to bore." The word occurs only in this place. Very various opinions have been entertained of its meaning. See Hengstenberg, "Com." The Latin Vulgate and the Septuagint understand it as meaning "inheritance" - the same as   nachalah, and as being somehow designed to refer to the people of God "as" a heritage. Latin Vulgate: In finem pro ca, quae hereditatem consequitur, psalmus David. So the Septuagint - &#x3c5;&#x3c0;&#x3b5;&#x3c1; &#x3c4;&#x3b7;&#x3c2; &#x3ba;&#x3bb;&#x3b7;&#x3c1;&#x3bf;&#x3bd;&#x3bf;&#x3bc;&#x3bf;&#x3c5;&#x3c3;&#x3b7;&#x3c2;  huper tes kleronomouses. So Luther, Fur das Erbe. What was the precise idea affixed to this it is not very easy to determine. Luther explains it, "according to the title, this is the general idea of the psalm, that the author prays for the inheritance or heritage of God, desiring that the people of God may be faithful to him, and may always adhere to him." The true interpretation, however, is evidently to regard this as an instrument of music, and to consider the psalm as adapted to be sung with the instrument of music specified. Why it was adapted particularly to "that" instrument of music cannot now be determined. Horsley renders it "upon the flutes." Compare Ugolin. Thesau. Ant. Sac.; tom. xxxii. pp. 158-170.A Psalm of David - See introduction to Psalm 3:1-8. Give ear to my words, O Lord - We naturally incline the ear toward anyone when we wish to hear distinctly what he says, and we turn away the ear when we do not. The meaning here is, David prayed that God would be attentive to or would regard his prayer. This form of the petition is, that he would attend to his "words" - to what he was about to "express" as his desire. He intended to express only what he wished to be granted.Consider my meditation - Understand; perceive, for so the word rendered "consider" properly means. He desired that he would regard the real import of what is here called his "meditation;" that is, he wished him not merely to attend to his "words," but to the secret and unexpressed desires of the soul. The idea seems to be that while his words would be sincere and truthful, yet they could not express "all" his meaning. There were desires of the soul which no language could convey - deep, unuttered "groanings" (compare Romans 8:26-27), which could not be uttered in language. There is a difference, however, in rendering the word translated "meditation." Most interpreters regard it as derived from   hagah, to meditate (see the notes at Psalm 1:2) - and as thus denoting "thought," or "meditation." Gesenius and some others regard it as derived from   hagag, obsolete root - meaning to set on fire, to kindle; and hence, that it means here "heat," fervour of the mind; and then, fervent cry, or prayer. See "Rosenmuiller" also in "loc." DeWette concurs with Gesenius, and supposes that it should be rendered "sigh" or complaint. Prof. Alexander renders it "thought." Horsley renders it, "my sighing," but says he is in doubt whether it refers to an "internal desire of the mind," in opposition to "words" in the former part of the verse, or to a "prayer uttered sotto voce, like the private prayer usually said by every person before he takes his seat in the church" - the "internal motion of the mind toward God." It is not easy to determine the true meaning, but the probability is that it refers to an internal emotion - a fervent, ardent feeling - perhaps finding partial expression in sighs Romans 8:26, but which does not find expression in words, and which words could not convey. He prayed that God would attend to the "whole" desires of the soul - whether expressed or unexpressed.', NULL, NULL, '''-170'':290 ''-27'':476 ''-8'':9,301 ''1'':8,300,510 ''158'':289 ''2'':511 ''26'':475,675 ''3'':299 ''4'':7 ''8'':474,674 ''accompani'':72 ''accord'':191 ''adapt'':251,264 ''adher'':228 ''affix'':178 ''alexand'':575 ''also'':557 ''alway'':227 ''ant'':284 ''anyon'':315 ''ardent'':665 ''attend'':361,422,695 ''attent'':345 ''author'':205 ''away'':328 ''bore'':101 ''ca'':156 ''call'':411 ''cannot'':271 ''chalal'':99 ''charg'':47 ''church'':634 ''com'':120 ''compar'':281,472 ''complaint'':573 ''concur'':561 ''consequitur'':159 ''consid'':247,395 ''convey'':468,689 ''could'':452,467,478,687 ''cri'':552 ''das'':171 ''david'':161,294,339 ''deep'':469 ''denot'':90,515 ''deriv'':500,526 ''design'':69,140 ''desir'':214,374,399,432,460,596,699 ''determin'':187,274,648 ''dewett'':560 ''differ'':487 ''distinct'':321 ''doubt'':589 ''ear'':303,313,330 ''easi'':185,646 ''emot'':662 ''entertain'':114 ''erb'':172 ''everi'':625 ''evid'':236 ''explain'':189 ''express'':371,378,454,670,681,704 ''faith'':222 ''feel'':666 ''fervent'':551,664 ''fervour'':545 ''find'':668,680 ''finem'':154 ''fire'':535 ''flute'':92,280 ''form'':353 ''former'':606 ''fur'':170 ''general'':198 ''gesenius'':87,519,563 ''give'':302 ''god'':147,213,219,342,642,693 ''granted.consider'':385 ''groan'':471 ''hagag'':528 ''hagah'':502 ''hear'':320 ''heat'':544 ''henc'':539 ''hengstenberg'':119 ''hereditatem'':158 ''heritag'':150,211 ''horsley'':275,579 ''howev'':234,488 ''huper'':165 ''idea'':30,62,177,199,437 ''import'':406 ''inclin'':311 ''inherit'':131,209 ''instrument'':19,50,75,242,257,268 ''intend'':37,376 ''in