INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('484', '2', '484', NULL, 'O Lord, rebuke me not in thine anger - As if God was rebuking him by the affliction which he was bringing upon him. This is the point on which the attention of the psalmist is now fixed. He had been apparently contemplating his afflictions, and inquiring into their cause, and he was led to the conclusion that it might be for his sins, and that his trials were to be interpreted as proof that God was angry with him. He speaks, therefore, of God as visiting him in his "anger," and in his "hot displeasure," and pleads with him that he would "not" thus rebuke and chasten him. The word "rebuke" here, like the word rendered "chasten," properly refers to the reproof of an offender "by words," but may also be used to denote the reproof which God administers by his providential dealings when he brings judgment upon anyone for his sins. This is the meaning here. The psalmist did not apprehend that God would openly "reprove" him for his sins; but he regarded his dealings with him as such a reproof, and he pleads that the tokens of the reproof might be taken away. The whole language is that which indicates a connection between suffering and sin; the feeling which we have when we are afflicted that it must be on account of our sins.Neither chasten me - A word denoting substantially the same thing; used here in the sense of "punishing."In thy hot displeasure - literally, "in thy heat." We speak of anger or wrath as "burning," or "consuming." Compare Genesis 39:19; Numbers 11:33; Deuteronomy 11:17; Psalm 106:40; Job 19:11; Job 32:2-3; Psalm 2:12.', NULL, NULL, '''-3'':280 ''106'':272 ''11'':266,269,276 ''12'':283 ''17'':270 ''19'':264,275 ''2'':279,282 ''32'':278 ''33'':267 ''39'':263 ''40'':273 ''account'':223 ''administ'':139 ''afflict'':17,44,217 ''also'':130 ''anger'':8,90,254 ''angri'':77 ''anyon'':149 ''appar'':41 ''apprehend'':162 ''attent'':31 ''away'':195 ''bring'':21,146 ''burn'':258 ''caus'':49 ''chasten'':107,117,227 ''compar'':261 ''conclus'':56 ''connect'':204 ''consum'':260 ''contempl'':42 ''deal'':143,176 ''denot'':134,231 ''deuteronomi'':268 ''displeasur'':95,246 ''feel'':210 ''fix'':37 ''genesi'':262 ''god'':11,75,84,138,164 ''heat'':250 ''hot'':94,245 ''indic'':202 ''inquir'':46 ''interpret'':71 ''job'':274,277 ''judgment'':147 ''languag'':198 ''led'':53 ''like'':113 ''liter'':247 ''lord'':2 ''may'':129 ''mean'':156 ''might'':59,192 ''must'':220 ''number'':265 ''o'':1 ''offend'':125 ''open'':166 ''plead'':97,185 ''point'':27 ''proof'':73 ''proper'':118 ''providenti'':142 ''psalm'':271,281 ''psalmist'':34,159 ''punish'':242 ''rebuk'':3,13,105,111 ''refer'':119 ''regard'':174 ''render'':116 ''reproof'':122,136,182,191 ''reprov'':167 ''sens'':240 ''sin'':63,152,171,208 ''sins.neither'':226 ''speak'':81,252 ''substanti'':232 ''suffer'':206 ''taken'':194 ''therefor'':82 ''thi'':244,249 ''thine'':7 ''thing'':235 ''thus'':104 ''token'':188 ''trial'':67 ''upon'':22,148 ''use'':132,236 ''visit'':86 ''whole'':197 ''word'':110,115,127,230 ''would'':102,165 ''wrath'':256', NULL, '484');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('485', '2', '485', NULL, 'O Lord my God, in thee do I put my trust - The psalm opens with an expression of strong confidence in God. The psalmist addresses Yahweh as his God, and says that in him he trusts or confides. The word rendered trust -   chasah - means "to flee;" to flee to a place; to take shelter; and is applied to taking shelter under the shadow or protection of one Judges 9:15; Isaiah 30:2; Psalm 57:1; Psalm 61:4. The idea here is, that in his troubles he fled to God as a refuge, and felt safe under his protection.Save me from all them that persecute me - That is, protect my life; rescue me from their power. The word "persecute" here refers to those who sought his life, who endeavored to deprive him of his rights. The language would apply to many occasions in the life of David - to the persecutions which he endured by Saul, by Absalom, etc. In this case the language was suggested by the opposition of Cush the Benjamite; and it was this that David had particularly in view. It is probable, however, that, whoever Cush was, he was not alone, but that others were associated with him in his opposition to David; and it was natural also that, in circumstances like these, David should remember his other persecutors, and pray that he might be delivered from them all. The prayer, therefore, has a general form, and the desire expressed is that which we all naturally have, that we may be delivered from all that troubles us.And deliver me - Rescue me. It would seem from this expression, and from the following verse, that there was more to be apprehended in the case than mere reproachful words, and that his life was actually in danger.', NULL, NULL, '''1'':76 ''15'':70 ''2'':73 ''30'':72 ''4'':79 ''57'':75 ''61'':78 ''9'':69 ''absalom'':158 ''actual'':296 ''address'':25 ''alon'':195 ''also'':212 ''appli'':57,140 ''apprehend'':283 ''associ'':200 ''benjamit'':173 ''case'':162,286 ''chasah'':43 ''circumst'':215 ''confid'':20,38 ''cush'':171,190 ''danger'':298 ''david'':148,179,207,218 ''deliv'':230,256,262 ''depriv'':132 ''desir'':243 ''endeavor'':130 ''endur'':154 ''etc'':159 ''express'':17,244,271 ''felt'':96 ''fled'':89 ''flee'':46,48 ''follow'':275 ''form'':240 ''general'':239 ''god'':4,22,29,91 ''howev'':187 ''idea'':81 ''isaiah'':71 ''judg'':68 ''languag'':138,164 ''life'':112,128,146,294 ''like'':216 ''lord'':2 ''mani'':142 ''may'':254 ''mean'':44 ''mere'':288 ''might'':228 ''natur'':211,250 ''o'':1 ''occas'':143 ''one'':67 ''open'':14 ''opposit'':169,205 ''other'':198 ''particular'':181 ''persecut'':106,120,151 ''persecutor'':223 ''place'':51 ''power'':117 ''pray'':225 ''prayer'':235 ''probabl'':186 ''protect'':65,110 ''protection.save'':100 ''psalm'':13,74,77 ''psalmist'':24 ''put'':9 ''refer'':122 ''refug'':94 ''rememb'':220 ''render'':41 ''reproach'':289 ''rescu'':113,264 ''right'':136 ''safe'':97 ''saul'':156 ''say'':31 ''seem'':268 ''shadow'':63 ''shelter'':54,60 ''sought'':126 ''strong'':19 ''suggest'':166 ''take'':53,59 ''thee'':6 ''therefor'':236 ''troubl'':87,260 ''trust'':11,36,42 ''us.and'':261 ''vers'':276 ''view'':183 ''whoever'':189 ''word'':40,119,290 ''would'':139,267 ''yahweh'':26', NULL, '485');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('486', '2', '486', NULL, 'O Lord - Hebrew,   Yahweh. It is an address to God by his chosen and special title, Exodus 3:14. Compare the notes at Isaiah 1:2.Our Lord - The word used here -   ''adonay - means properly master, lord, ruler, owner, and is such a title as is given to an owner of land or of slaves, to kings, or to rulers, and is applied to God as being the ruler or governor of the universe. The meaning here is, that the psalmist acknowledged Yahweh to be the rightful ruler, king, or master of himself and of all others. He comes before him with the feeling that Yahweh is the universal ruler - the king and proprietor of all things.How excellent is thy name - How excellent or exalted art thou - the name being often used to denote the person. The idea is," How glorious art thou in thy manifested excellence or character."In all the earth - In all parts of the world. That is, the manifestation of his perfect character was not confined to any one country, but was seen in all lands, and among all people. In every place his true character was made known through His works; in every land there were evidences of his wisdom, his greatness, his goodness, his condescension.Who hast set thy glory above the heavens - The word used here, and rendered "hast set," is in the imperative mood -   tenah - give; and it should probably have been so rendered here, "which thy glory give thou;" that is, "which glory of thine, or implied in thy name, give or place above the heavens." In other words, let it he exalted in the highest degree, and to the highest place, even above the heavens on which he was gazing, and which were in themselves so grand, Psalm 8:3. It expresses the wish or prayer of the writer that the name or praise of God, so manifest in the earth, might be exalted in the highest possible degree - be more elevated than the moon and the stars - exalted and adored in all worlds. In His name there was such intrinsic grandeur that he desired that it might be regarded as the highest object in the universe, and might blaze forth above all worlds. On the grammatical construction of this word -   tenah - see an article by Prof. Stuart, in the Bibliotheca Sacra, vol. ix. pp. 73-77. Prof. Stuart supposes that the word is not formed from   nathan - to give, as is the common explanation, but from   tanah - to give presents, to distribute gifts, Hosea 8:9-10, and that it should be rendered, Thou who diffusest abroad thy glory over the heavens.', NULL, NULL, '''-10'':426 ''-77'':395 ''1'':25 ''14'':19 ''2.our'':26 ''3'':18,298 ''73'':394 ''8'':297,424 ''9'':425 ''abroad'':436 ''acknowledg'':81 ''address'':8 ''adonay'':32 ''ador'':339 ''among'':181 ''appli'':62 ''art'':125,141 ''articl'':383 ''bibliotheca'':389 ''blaze'':368 ''charact'':148,166,189 ''chosen'':13 ''come'':98 ''common'':412 ''compar'':20 ''condescension.who'':210 ''confin'':169 ''construct'':376 ''countri'':173 ''degre'':274,327 ''denot'':133 ''desir'':353 ''diffusest'':435 ''distribut'':421 ''earth'':152,319 ''elev'':330 ''even'':280 ''everi'':185,197 ''evid'':201 ''exalt'':124,270,322,337 ''excel'':117,122,146 ''exodus'':17 ''explan'':413 ''express'':300 ''feel'':103 ''form'':404 ''forth'':369 ''gaze'':288 ''gift'':422 ''give'':232,245,258,408,418 ''given'':46 ''glori'':214,244,250,438 ''glorious'':140 ''god'':10,64,314 ''good'':208 ''governor'':70 ''grammat'':375 ''grand'':295 ''grandeur'':350 ''great'':206 ''hast'':211,224 ''heaven'':217,263,283,441 ''hebrew'':3 ''highest'':273,278,325,361 ''hosea'':423 ''idea'':137 ''imper'':229 ''impli'':254 ''intrins'':349 ''isaiah'':24 ''ix'':392 ''king'':56,88,111 ''known'':192 ''land'':51,179,198 ''let'':267 ''lord'':2,27,36 ''made'':191 ''manifest'':145,162,316 ''master'':35,90 ''mean'':33,75 ''might'':320,356,367 ''mood'':230 ''moon'':333 ''name'':120,128,257,310,345 ''nathan'':406 ''note'':22 ''o'':1 ''object'':362 ''often'':130 ''one'':172 ''other'':96 ''owner'':38,49 ''part'':155 ''peopl'':183 ''perfect'':165 ''person'':135 ''place'':186,260,279 ''possibl'':326 ''pp'':393 ''prais'':312 ''prayer'':304 ''present'':419 ''probabl'':236 ''prof'':385,396 ''proper'':34 ''proprietor'':113 ''psalm'':296 ''psalmist'':80 ''regard'':358 ''render'':223,240,432 ''right'':86 ''ruler'':37,59,68,87,109 ''sacra'':390 ''see'':381 ''seen'':176 ''set'':212,225 ''slave'':54 ''special'':15 ''star'':336 ''stuart'':386,397 ''suppos'':398 ''tanah'':416 ''tenah'':231,380 ''thi'':119,144,213,243,256,437 ''thine'':252 ''things.how'':116 ''thou'':126,142,246,433 ''titl'':16,43 ''true'':188 ''univers'':73,108,365 ''use'':30,131,220 ''vol'':391 ''wisdom'':204 ''wish'':302 ''word'':29,219,266,379,401 ''work'':195 ''world'':158,342,372 ''writer'':307 ''yahweh'':4,82,105', NULL, '486');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('487', '2', '487', NULL, 'I will praise thee, O Lord - That is, in view of the merciful interpositions referred to in the psalm Psa 9:3-5, and in view of the attributes of God''s character which had been displayed on that occasion Psalm 9:7-12.With my whole heart - Not with divided affection, or with partial gratitude. He meant that all his powers should be employed in this service; that he would give utterance to his feelings of gratitude and adoration in the loftiest and purest manner possible.I will show forth - I will recount or narrate - to wit, in this song of praise.All thy marvelous works - All his works or doings fitted to excite admiration or wonder. The reference here is particularly to what God had done which had given occasion to this psalm, but still the psalmist designs undoubtedly to connect with this the purpose to give a general expression of praise in view of all that God had done that was fitted to excite such feelings.', NULL, NULL, '''-5'':23 ''3'':22 ''7-12.with'':43 ''9'':21,42 ''admir'':112 ''ador'':78 ''affect'':50 ''attribut'':29 ''charact'':33 ''connect'':139 ''design'':136 ''display'':37 ''divid'':49 ''do'':108 ''done'':124,158 ''employ'':63 ''excit'':111,163 ''express'':148 ''feel'':74,165 ''fit'':109,161 ''forth'':88 ''general'':147 ''give'':70,145 ''given'':127 ''god'':31,122,156 ''gratitud'':54,76 ''heart'':46 ''interposit'':14 ''loftiest'':81 ''lord'':6 ''manner'':84 ''marvel'':102 ''meant'':56 ''merci'':13 ''narrat'':93 ''o'':5 ''occas'':40,128 ''partial'':53 ''particular'':119 ''possible.i'':85 ''power'':60 ''prais'':3,150 ''praise.all'':100 ''psa'':20 ''psalm'':19,41,131 ''psalmist'':135 ''purest'':83 ''purpos'':143 ''recount'':91 ''refer'':15,116 ''servic'':66 ''show'':87 ''song'':98 ''still'':133 ''thee'':4 ''thi'':101 ''undoubt'':137 ''utter'':71 ''view'':10,26,152 ''whole'':45 ''wit'':95 ''wo