INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('509', '2', '509', NULL, 'In thee, O Lord, do I put my trust - This is the ground of the petitions which follow; or the reason why the psalmist thus appeals to God. It was his firm confidence in Him; in His character; in His promises; in His ability to deliver Him in the time of danger. Compare the notes at Psalm 7:1.Let me never be ashamed - That is, let me never have occasion to be ashamed for having put this confidence in Thee. Let Thy dealings toward me be such as to show that my confidence was well founded. The word is not used here in the sense of being unwilling to confess his faith in God, or his love for Him, as it is often now (compare Romans 1:16; Romans 5:5; 2 Timothy 1:12), but in the sense of being so "disappointed" as to make one ashamed that he had thus relied on that which was unworthy of confidence. See the notes at Job 6:20; compare also Isaiah 30:5; Jeremiah 2:26; Jeremiah 14:3-4. The psalmist prays that God would interpose in his behalf in answer to his prayers, and that he would show that He was worthy of the confidence which he had reposed in him, or that He was a God who might be trusted in the time of trial; in other words, that he might not be subjected to the reproach of the wicked for having in his troubles relied upon such a God.Deliver me in thy righteousness - In the manifestation of Thy righteous character; in the exhibition of that character as righteous; as doing justice between man and man; as pronouncing a just sentence between me and my enemies.', NULL, NULL, '''-4'':179 ''1'':127,134 ''1.let'':59 ''12'':135 ''14'':177 ''16'':128 ''2'':132,174 ''20'':167 ''26'':175 ''3'':178 ''30'':171 ''5'':130,131,172 ''6'':166 ''7'':58 ''abil'':44 ''also'':169 ''answer'':191 ''appeal'':26 ''asham'':63,73,148 ''behalf'':189 ''charact'':38,263,269 ''compar'':53,125,168 ''confess'':110 ''confid'':33,78,93,160,206