INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1047', '2', '1047', NULL, 'Called Praetorium - The hall of the "praetor," or Roman governor, where he sat to administer justice.Whole band - See the notes at Matthew 27:27.', NULL, NULL, '''27'':23,24 ''administ'':15 ''band'':17 ''call'':1 ''governor'':10 ''hall'':4 ''justice.whole'':16 ''matthew'':22 ''note'':20 ''praetor'':7 ''praetorium'':2 ''roman'':9 ''sat'':13 ''see'':18', NULL, '972');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('817', '2', '817', NULL, 'The vine ... - The image is grounded on a well-known figure Psalm 80:8; Isaiah 5. The comparison is not between the vine and other trees, but between the wood of the vine and the wood of other trees.', NULL, NULL, '''5'':17 ''8'':15 ''80'':14 ''comparison'':19 ''figur'':12 ''ground'':6 ''imag'':4 ''isaiah'':16 ''known'':11 ''psalm'':13 ''tree'':27,40 ''vine'':2,24,34 ''well'':10 ''well-known'':9 ''wood'':31,37', NULL, '817');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('957', '2', '957', NULL, 'en a person is struck, he happens to have his hand extended, he is unable to draw it back; if not extended, he is unable to stretch it out. It gradually becomes diminished in size, and dried up in app', NULL, NULL, '''app'':40 ''back'':19 ''becom'':32 ''diminish'':33 ''draw'':17 ''dri'':37 ''en'':1 ''extend'':12,22 ''gradual'':31 ''hand'':11 ''happen'':7 ''person'':3 ''size'':35 ''stretch'':27 ''struck'':5 ''unabl'':15,25', NULL, '933');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('531', '2', '531', NULL, 'The fool hath said in his heart ... - For the meaning of this verse, see the notes at Psalm 14:1. The only change in this verse - a change which does not affect the sense - is the substitution of the word "iniquity," in Psalm 53:1-6, for "works," in Psalm 14:1-7.', NULL, NULL, '''-6'':46 ''-7'':53 ''1'':20,45,52 ''14'':19,51 ''53'':44 ''affect'':32 ''chang'':23,28 ''fool'':2 ''hath'':3 ''heart'':7 ''iniqu'':41 ''mean'':10 ''note'':16 ''psalm'':18,43,50 ''said'':4 ''see'':14 ''sens'':34 ''substitut'':37 ''vers'':13,26 ''word'':40 ''work'':48', NULL, '531');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('538', '2', '538', NULL, 'O God, thou hast cast us off - The word used here means properly to be foul, rancid, offensive; and then, to treat anything as if it were foul or rancid; to repel, to spurn, to cast away. See the notes at Psalm 43:2. It is strong language, meaning that God had seemed to treat them as if they were loathsome or offensive to him. The allusion, according to the view taken in the introduction to the psalm, is to some defeat or disaster which had occurred after the conquests in the East, or during the absence of the armies of David in the East 2 Samuel 8; 1 Chronicles 18; probably to the fact that the Edomites had taken occasion to invade the southern part of Palestine, and that the forces employed to expel them had been unsuccessful.Thou hast scattered us - Margin, broken. So the Hebrew. The word is applied to the forces of war which are broken and scattered by defeat, 2 Samuel 5:20.Thou hast been displeased - The word used here means "to breathe"; to breathe hard; and then, to be angry. See the notes at Psalm 2:12. God had treated them as if he was displeased or angry. He had suffered them to be defeated.O turn thyself to us again - Return to our armies, and give us success. This might be rendered, "Thou wilt turn to us;" that is, thou wilt favor us - expressing a confident belief that God would do this, as in Psalm 60:12. It is more in accordance, however, with the usual structure of the Psalms to regard this as a prayer. Many of the psalms begin with a prayer, and end with the expression of a confident assurance that the prayer has been, or would certainly be heard.', NULL, NULL, '''1'':109 ''12'':192,252 ''18'':111 ''2'':44,106,164,191 ''20.thou'':167 ''43'':43 ''5'':166 ''60'':251 ''8'':108 ''absenc'':97 ''accord'':68,257 ''allus'':67 ''angri'':185,203 ''anyth'':23 ''appli'':151 ''armi'':100,219 ''assur'':288 ''away'':37 ''begin'':276 ''belief'':242 ''breath'':177,179 ''broken'':144,159 ''cast'':5,36 ''certain'':296 ''chronicl'':110 ''confid'':241,287 ''conquest'':90 ''david'':102 ''defeat'':82,163 ''defeated.o'':210 ''disast'':84 ''displeas'':170,201 ''east'':93,105 ''edomit'':118 ''employ'':133 ''end'':281 ''expel'':135 ''express'':239,284 ''fact'':115 ''favor'':237 ''forc'':132,154 ''foul'':16,28 ''give'':221 ''god'':2,51,193,244 ''hard'':180 ''hast'':4,140,168 ''heard'':298 ''hebrew'':147 ''howev'':258 ''introduct'':75 ''invad'':123 ''languag'':48 ''loathsom'':61 ''mani'':272 ''margin'':143 ''mean'':12,49,175 ''might'':225 ''note'':40,188 ''o'':1 ''occas'':121 ''occur'':87 ''offens'':18,63 ''palestin'':128 ''part'':126 ''prayer'':271,279,291 ''probabl'':112 ''proper'':13 ''psalm'':42,78,190,250,265,275 ''rancid'':17,30 ''regard'':267 ''render'':227 ''repel'':32 ''return'':216 ''samuel'':107,165 ''scatter'':141,161 ''see'':38,186 ''seem'':53 ''southern'':125 ''spurn'':34 ''strong'':47 ''structur'':262 ''success'':223 ''suffer'':206 ''taken'':72,120 ''thou'':3,228,235 ''thyself'':212 ''treat'':22,55,195 ''turn'':211,230 ''unsuccessful.thou'':139 ''us'':6,142,214,222,232,238 ''use'':10,173 ''usual'':261 ''view'':71 ''war'':156 ''wilt'':229,236 ''word'':9,149,172 ''would'':245,295', NULL, '538');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('499', '2', '499', NULL, 'The king shall joy in thy strength - King David, who had achieved the victory which he had desired and prayed for, Psalm 20:1-9. This is in the third person, but the reference is doubtless to David himself, and is to be understood as his own language. If it be understood, however, as the language of "the people," it is still an ascription of praise to God for his favor to their king. It seems better, however, to regard it as the language of David himself. The word ""strength"" here implies that all the success referred to was to be traced to God. It was not by the prowess of a human arm; it was not by the valor or skill of the king himself; it was by the power of God alone.And in thy salvation - In the salvation or deliverance from foes which thou hast granted, and in all that thou doest to save. The language would embrace all that God does to save his people.How greatly shall he rejoice! - Not only does he rejoice now, but he ever will rejoice. It will be to him a constant joy. Salvation, now to us a source of comfort, will always be such; and when we once have evidence that God has interposed to save us, it is accompanied with the confident anticipation that this will continue to be the source of our highest joy forever.', NULL, NULL, '''-9'':25 ''1'':24 ''20'':23 ''accompani'':219 ''achiev'':12 ''alone.and'':134 ''alway'':201 ''anticip'':223 ''arm'':114 ''ascript'':64 ''better'':77 ''comfort'':199 ''confid'':222 ''constant'':190 ''continu'':227 ''david'':9,38,86 ''deliver'':142 ''desir'':18 ''doest'':154 ''doubtless'':36 ''embrac'':160 ''ever'':181 ''evid'':209 ''favor'':71 ''foe'':144 ''forev'':236 ''god'':68,104,133,163,211 ''grant'':148 ''great'':169 ''hast'':147 ''highest'':234 ''howev'':53,78 ''human'':113 ''impli'':92 ''interpos'':213 ''joy'':4,191,235 ''king'':2,8,74,125 ''languag'':48,56,84,158 ''peopl'':59 ''people.how'':168 ''person'':31 ''power'':131 ''prais'':66 ''pray'':20 ''prowess'':110 ''psalm'':22 ''refer'':34,97 ''regard'':80 ''rejoic'':172,177,183 ''salvat'':137,140,192 ''save'':156,166,215 ''seem'':76 ''shall'':3,170 ''skill'':122 ''sourc'':197,231 ''still'':62 ''strength'':7,90 ''success'':96 ''thi'':6,136 ''third'':30 ''thou'':146,153 ''trace'':102 ''understood'':44,52 ''us'':195,216 ''valor'':120 ''victori'':14 ''word'':89 ''would'':159', NULL, '499');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('501', '2', '501', NULL, 'The Lord is my shepherd - Compare Genesis 49:24, "From thence is the shepherd, the stone of Israel;" Psalm 80:1, "Give ear, O Shepherd of Israel." See also the notes at John 10:1-14. The comparison of the care which God extends over his people to that of a shepherd for his flock is one that would naturally occur to those who were accustomed to pastoral life. It would be natural that it should suggest itself to Jacob Genesis 49:24, and to David, for both of them had been shepherds. David, in advanced years, would naturally remember the occupations of his early life; and the remembrance of the care of God over him would naturally recall the care which he had, in earlier years, extended over his flocks. The idea which the language suggests is that of tender care; protection; particular attention to the young and the feeble (compare Isaiah 40:11); and providing for their wants. All these things are found eminently in God in reference to his people.I shall not want - This is the main idea in the psalm, and this idea is derived from the fact that God is a shepherd. The meaning is, that, as a shepherd, he would make all needful provision for his flock, and evince all proper care for it. The words shall not want, as applied to the psalmist, would embrace everything that could be a proper object of desire, whether temporal or spiritual; whether pertaining to the body or the soul; whether having reference to time or to eternity. There is no reason for supposing that David limited this to his temporal necessities, or to the present life, but the idea manifestly is that God would provide all that was needful for him always. Compare Psalm 34:9, "There is no want to them that fear him." This idea enters essentially into the conception of God as the shepherd of his people, that all their real wants shall be supplied.', NULL, NULL, '''-14'':36 ''1'':21,35 ''10'':34 ''11'':155 ''24'':9,83 ''34'':299 ''40'':154 ''49'':8,82 ''80'':20 ''9'':300 ''accustom'':66 ''advanc'':96 ''also'':29 ''alway'':296 ''appli'':227 ''attent'':145 ''bodi'':250 ''care'':41,112,121,142,218 ''compar'':6,152,297 ''comparison'':38 ''concept'':316 ''could'':235 ''david'':86,94,269 ''deriv'':189 ''desir'':241 ''ear'':23 ''earli'':105 ''earlier'':126 ''embrac'':232 ''emin'':166 ''enter'':312 ''essenti'':313 ''etern'':261 ''everyth'':233 ''evinc'':215 ''extend'':44,128 ''fact'':192 ''fear'':308 ''feebl'':151 ''flock'':55,131,213 ''found'':165 ''genesi'':7,81 ''give'':22 ''god'':43,114,168,194,287,318 ''idea'':133,181,187,283,311 ''isaiah'':153 ''israel'':18,27 ''jacob'':80 ''john'':33 ''languag'':136 ''life'':69,106,280 ''limit'':270 ''lord'':2 ''main'':180 ''make'':207 ''manifest'':284 ''mean'':199 ''natur'':60,73,99,118 ''necess'':275 ''need'':209,293 ''note'':31 ''o'':24 ''object'':239 ''occup'':102 ''occur'':61 ''one'':57 ''particular'':144 ''pastor'':68 ''peopl'':47,324 ''people.i'':173 ''pertain'':247 ''present'':279 ''proper'':217,238 ''protect'':143 ''provid'':157,289 ''provis'':210 ''psalm'':19,184,298 ''psalmist'':230 ''real'':328 ''reason'':265 ''recal'':119 ''refer'':170,256 ''rememb'':100 ''remembr'':109 ''see'':28 ''shall'':174,223,330 ''shepherd'':5,14,25,52,93,197,204,321 ''soul'':253 ''spiritu'':245 ''stone'':16 ''suggest'':77,137 ''suppli'':332 ''suppos'':267 ''tempor'':243,274 ''tender'':141 ''thenc'':11 ''thing'':163 ''time'':258 ''want'':160,176,225,304,329 ''whether'':242,246,254 ''word'':222 ''would'':59,71,98,117,206,231,288 ''year'':97,127 ''young'':148', NULL, '501');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('502', '2', '502', NULL, 'The earth is the Lord''s - The whole world belongs to God. He is the Creator of the earth, and therefore, its Proprietor; or, in other words, "the property vests in him." It belongs to Him in a sense somewhat similar to our right of property in anything that is the production of our hands, or of our labor or skill. We claim that as our own. We feel that we have a right to use it, or to dispose of it, as we choose. No other person has a right to take it from us, or to dictate to us how we shall employ it. Thus, God, in the highest possible sense, has a right to the earth, and to all which it produces, as being all of it the creation of His hands, and the fruit of His culture and skill. He has a right to dispose of it as He pleases; by fire, or flood, or tempest; and He has an equal right to direct man in what way He shall employ that portion of the productions of the earth which may be entrusted to Him. All the right which any person has to any portion of the earth''s surface, or to what is treasured up in the earth, or to what it is made to produce, is subordinate to the claims of God, and all should be yielded up at His bidding, whether He comes and claims it to be employed in His service, or whether He comes and sweeps it away by fire or flood; by the locust, or by the palmer-worm.And the fulness thereof - All which it contains; everything which goes to "fill up" the world: animals, minerals, vegetables, people. All belong to God, and He has a right to claim them for His service, and to dispose of them as He pleases. This very language, so noble, so true, and so suitable to be made conspicuous in the eyes of human beings, I saw inscribed in a place where it seemed to be most appropriate, and most adapted to arrest and direct the thoughts of men - on the front of the Royal Exchange in London. It was well to remind the great merchants of the largest commercial city in the world of the truth which it contains; it does much to describe the character of the British nation that it should be inscribed in a place so conspicuous, and, as it were, on the wealth of that great capital.The world - The word used here -   tebel - is a poetic word, referring to the earth considered as fertile and inhabited - the "habitable" globe; the same as the Greek, &#x3bf;&#x3b9;&#x3ba;&#x3bf;&#x3c5;&#x3bc;&#x3b5;&#x3bd;&#x3b7;  oikoumene.And they that dwell therein - All the inhabitants of the earth, embracing men and animals of all kinds. Compare Psalm 50:10-11. God has a claim on people - upon their services, upon their talents, upon all that they can acquire by labor and skill; He has a right to all that fly in the air, or that walk the earth, or that swim in the sea. On the occasion on which it is supposed that this psalm was written, in bringing up the ark of God, and placing it in the tabernacle provided for it in the capital of the nation, no sentiment could be more appropriate than that which would recognize the universal supremacy of God.', NULL, NULL, '''-11'':467 ''10'':466 ''50'':465 ''acquir'':485 ''adapt'':346 ''air'':500 ''anim'':284,459 ''anyth'':48 ''appropri'':343,552 ''ark'':529 ''arrest'':348 ''away'':257 ''be'':330 ''belong'':10,34,289 ''bid'':237 ''bring'':526 ''british'':395 ''capit'':543 ''capital.the'':417 ''charact'':392 ''choos'':85 ''citi'':376 ''claim'':63,226,242,298,471 ''come'':240,253 ''commerci'':375 ''compar'':463 ''consid'':432 ''conspicu'':324,406 ''contain'':275,385 ''could'':549 ''creation'':132 ''creator'':16 ''cultur'':141 ''describ'':390 ''dictat'':99 ''direct'':168,350 ''dispos'':80,149,305 ''dwell'':448 ''earth'':2,19,119,183,202,213,431,455,505 ''embrac'':456 ''employ'':105,175,246 ''entrust'':187 ''equal'':165 ''everyth'':276 ''exchang'':361 ''eye'':327 ''feel'':69 ''fertil'':434 ''fill'':280 ''fire'':156,259 ''fli'':497 ''flood'':158,261 ''front'