INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('591', '2', '591', NULL, 'Praise ye the Lord - Margin, as in Hebrew, "Hallelujah." See the notes at Psalm 106:1.Praise, O ye servants of the Lord - You who profess to serve and obey him; who acknowledge him as your God. In the original this is also the word "Hallelu,"   halelu.Praise the name of the Lord - Still the same word "Hallelu." The name of the Lord is put here, as it is often, for the Lord himself.', NULL, NULL, '''1.praise'':16 ''106'':15 ''acknowledg'':32 ''also'':42 ''god'':36 ''halelu.praise'':46 ''hallelu'':45,56 ''hallelujah'':9 ''hebrew'':8 ''lord'':4,22,51,61,71 ''margin'':5 ''name'':48,58 ''note'':12 ''o'':17 ''obey'':29 ''often'':68 ''origin'':39 ''prais'':1 ''profess'':25 ''psalm'':14 ''put'':63 ''see'':10 ''serv'':27 ''servant'':19 ''still'':52 ''word'':44,55 ''ye'':2,18', NULL, '591');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('526', '2', '526', NULL, 'Great is the Lord - That is, he is high and exalted; he is a Being of great power and glory. He is not weak and feeble, like the idols worshipped by other nations. He is able to defend his people; he has shown his great power in overthrowing the mighty forces that were gathered together against the city where he dwells.And greatly to be praised - Worthy to be praised. In his own nature, he is worthy of adoration; in interposing to save the city from its foes, he has shown that he is worthy of exalted praise.In the city of our God - Jerusalem. In the city which he has chosen for his abode, and where his worship is celebrated. See the notes at Psalm 46:4. This praise was especially appropriate there:(a) because it was a place set apart for his worship;(b) because he had now interposed to save it from threatened ruin.In the mountain of his holiness - His holy mountain; either Mount Zion, if the psalm was composed before the building of the temple - or more probably here Mount Moriah, on which the temple was reared. The names Zion, and Mount Zion, however, were sometimes given to the entire city. Compare the notes at Isaiah 2:2-3.', NULL, NULL, '''-3'':211 ''2'':209,210 ''4'':126 ''46'':125 ''abl'':36 ''abod'':113 ''ador'':78 ''apart'':140 ''appropri'':131 ''b'':144 ''build'':174 ''celebr'':119 ''chosen'':110 ''citi'':58,84,99,106,203 ''compar'':204 ''compos'':171 ''defend'':38 ''dwells.and'':61 ''either'':164 ''entir'':202 ''especi'':130 ''exalt'':11,96 ''feebl'':26 ''foe'':87 ''forc'':51 ''gather'':54 ''given'':199 ''glori'':20 ''god'':102 ''great'':1,17,45,62 ''high'':9 ''holi'':160,162 ''howev'':196 ''idol'':29 ''interpos'':80,149 ''isaiah'':208 ''jerusalem'':103 ''like'':27 ''lord'':4 ''mighti'':50 ''moriah'':183 ''mount'':165,182,194 ''mountain'':157,163 ''name'':191 ''nation'':33 ''natur'':73 ''note'':122,206 ''overthrow'':48 ''peopl'':40 ''place'':138 ''power'':18,46 ''prais'':65,69,128 ''praise.in'':97 ''probabl'':180 ''psalm'':124,169 ''rear'':189 ''ruin.in'':155 ''save'':82,151 ''see'':120 ''set'':139 ''shown'':43,90 ''sometim'':198 ''templ'':177,187 ''threaten'':154 ''togeth'':55 ''weak'':24 ''worship'':30,117,143 ''worthi'':66,76,94 ''zion'':166,192,195', NULL, '526');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('527', '2', '527', NULL, 'Hear this, all ye people - That is, What I am about; to utter is worthy of universal attention; it pertains equally to all mankind. The psalmist; therefore calls on all the nations to attend to what he is about to say. Compare the notes at Isaiah 1:2.Give ear - Incline your ear; attend. Compare the notes at Psalm 17:6. See also Isaiah 37:17; Isaiah 55:3; Daniel 9:18; Proverbs 2:2.All ye inhabitants of the world - The truth to be declared does not pertain exclusively to any one nation, or any one class of people. All are interested in it. The term here rendered "world" -   cheled, - means properly "duration of life, lifetime;" then, "life, time, age;" and then it comes to denote the world, considered as made up of the living, or the passing generations.', NULL, NULL, '''1'':47 ''17'':59,65 ''18'':71 ''2'':73 ''2.all'':74 ''2.give'':48 ''3'':68 ''37'':64 ''55'':67 ''6'':60 ''9'':70 ''age'':119 ''also'':62 ''attend'':34,53 ''attent'':18 ''call'':28 ''chele'':109 ''class'':96 ''come'':123 ''compar'':42,54 ''consid'':128 ''daniel'':69 ''declar'':84 ''denot'':125 ''durat'':112 ''ear'':49,52 ''equal'':21 ''exclus'':88 ''generat'':138 ''hear'':1 ''inclin'':50 ''inhabit'':76 ''interest'':101 ''isaiah'':46,63,66 ''life'':114,117 ''lifetim'':115 ''live'':134 ''made'':130 ''mankind'':24 ''mean'':110 ''nation'':32,92 ''note'':44,56 ''one'':91,95 ''pass'':137 ''peopl'':5,98 ''pertain'':20,87 ''proper'':111 ''proverb'':72 ''psalm'':58 ''psalmist'':26 ''render'':107 ''say'':41 ''see'':61 ''term'':105 ''therefor'':27 ''time'':118 ''truth'':81 ''univers'':17 ''utter'':13 ''world'':79,108,127 ''worthi'':15 ''ye'':4,75', NULL, '527');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('528', '2', '528', NULL, 'The mighty God, even the Lord - Even "Yahweh," for this is the original word. The Septuagint and Vulgate render this "The God of gods, the Lord." DeWette renders it, "God, God Jehovah, speaks." Prof. Alexander, "The Almighty, God, Jehovah, speaks;" and remarks that the word "mighty" is not an adjective agreeing with the next word ("the mighty God"), but a substantive in apposition with it. The idea is, that he who speaks is the true God; the Supreme Ruler of the universe. It is "that" God who has a right to call the world to judgment, and who has power to execute his will.Hath spoken - Or rather, "speaks." That is, the psalmist represents him as now speaking, and as calling the world to judgment.And called the earth - Addressed all the inhabitants of the world; all dwellers on the earth.From the rising of the sun unto the going down thereof - From the place where the sun seems to rise, to the place where it seems to set; that is, all the world. Compare the notes at Isaiah 59:19. See also Malachi 1:11; Psalm 113:3. The call is made to all the earth; to all the human race. The scene is imaginary as represented by the psalmist, but it is founded on a true representation of what will occur - of the universal judgment, when all nations shall be summoned to appear before the final Judge. See Matthew 25:32; Revelation 20:11-14.', NULL, NULL, '''-14'':244 ''1'':182 ''11'':183,243 ''113'':185 ''19'':178 ''20'':242 ''25'':239 ''3'':186 ''32'':240 ''59'':177 ''address'':128 ''adject'':50 ''agre'':51 ''alexand'':35 ''almighti'':37 ''also'':180 ''appear'':232 ''apposit'':63 ''call'':92,120,125,188 ''compar'':172 ''dewett'':27 ''dweller'':136 ''earth'':127,194 ''earth.from'':139 ''even'':4,7 ''execut'':102 ''final'':235 ''found'':212 ''go'':147 ''god'':3,22,24,30,31,38,58,76,86 ''human'':198 ''idea'':67 ''imaginari'':203 ''inhabit'':131 ''isaiah'':176 ''jehovah'':32,39 ''judg'':236 ''judgment'':96,224 ''judgment.and'':124 ''lord'':6,26 ''made'':190 ''malachi'':181 ''matthew'':238 ''mighti'':2,46,57 ''nation'':227 ''next'':54 ''note'':174 ''occur'':220 ''origin'':13 ''place'':152,161 ''power'':100 ''prof'':34 ''psalm'':184 ''psalmist'':112,208 ''race'':199 ''rather'':107 ''remark'':42 ''render'':19,28 ''repres'':113,205 ''represent'':216 ''revel'':241 ''right'':90 ''rise'':141,158 ''ruler'':79 ''scene'':201 ''see'':179,237 ''seem'':156,164 ''septuagint'':16 ''set'':166 ''shall'':228 ''speak'':33,40,72,108,117 ''spoken'':105 ''substant'':61 ''summon'':230 ''sun'':144,155 ''suprem'':78 ''thereof'':149 ''true'':75,215 ''univers'':82,223 ''unto'':145 ''vulgat'':18 ''will.hath'':104 ''word'':14,45,55 ''world'':94,122,134,171 ''yahweh'':8', NULL, '528');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('529', '2', '529', NULL, 'Have mercy opon me, O God - This is the utterance of a full heart; a heart crushed and broken by the consciousness of sin. The psalmist had been made to see his great guilt; and his first act is to cry out for mercy. There is no attempt to excuse his sin, or to apologise for it; there is no effort to vindicate his conduct; there is no complaint of the righteousness of that holy law which condemned him. It was "guilt" that was before his mind; guilt only; deep and dreadful guilt. The appeal properly expresses the state of a mind that is overwhelmed at the remembrance of crime, and that comes with earnestness to God to plead for pardon. The only hope of a sinner when crushed with the consciousness of sin is the mercy of God; and the plea for that mercy will be urged in the most earnest and impassioned language that the mind can employ. "Accordingly to thy Iovingkindness." On the meaning of the word used here, see the notes at Psalm 36:7.(a) The "ground" of his hope was the compassion of God:(b) the "measure" of that hope was His boundless beneficence; or, in other words, he felt that there was need of "all" the compassion of a God.His sin was so great, his offence was so aggravated, that he could have no hope but in a Being of infinite compassion, and he felt that the need of mercy in his case could be measured and covered "only" by that infinite compassion.According unto the multitude of thy tender mercies - The same idea occurs here also. The psalmist fixed his eye on the "vastness" of the divine mercy; on the numberless "acts" of that mercy toward the guilty; here he found his hope, and here alone. Every instance of extraordinary mercy which had occurred in the world furnished him now with an argument in his appeal to God; was an encouragement to him "in" that appeal; was a ground of hope that his appeal would not be rejected. So to us: every instance in which a great sinner has been forgiven is evidence that we may be forgiven also, and is an encouragement to us to come to God for pardon. See the notes at 1 Timothy 1:16.Blot out my transgressions - In allusion to an account that is kept, or a charge made, when such an account is wiped away, erased, or blotted out. Compare Exodus 32:32-33; see the notes at Isaiah 43:25; notes at Isaiah 44:22; notes at Colossians 2:14. Never was a more earnest appeal made by a sinner than that which is made in this verse; never was there a more sincere cry for mercy. It shows us where we should "begin" in our prayers when we are pressed down with the consciousness of sin - with a cry for "mercy," and not an appeal to "justice;" it shows us what is to be the "ground" and the "measure" of our hope - the mere compassion of an infinitely benevolent God; it shows us the place which we must take, and the argument on which we must rely - a place among sinners, and an argument that God has been merciful to great sinners, and that therefore he may be merciful to us.', NULL, NULL, '''-33'':417 ''1'':383,385 ''14'':434 ''16.blot'':386 ''2'':433 ''22'':429 ''25'':424 ''32'':415,416 ''36'':178 ''43'':423 ''44'':428 ''7'':179 ''accord'':161 ''account'':394,405 ''act'':38,289 ''aggrav'':226 ''allus'':391 ''alon'':303 ''also'':273,366 ''among'':535 ''apologis'':55 ''appeal'':95,323,333,341,440,490 ''argument'':320,527,539 ''attempt'':48 ''away'':408 ''b'':191 ''begin'':468 ''benefic'':200 ''benevol'':514 ''blot'':411 ''boundless'':199 ''broken'':19 ''case'':250 ''charg'':400 ''colossian'':432 ''come'':113,374 ''compar'':413 ''compass'':188,214,239,510 ''compassion.according'':260 ''complaint'':69 ''condemn'':78 ''conduct'':65 ''conscious'':22,132,479 ''could'':229,251 ''cover'':255 ''cri'':41,459,484 ''crime'':110 ''crush'':17,129 ''deep'':90 ''divin'':284 ''dread'':92 ''earnest'':115,152,439 ''effort'':61 ''employ'':160 ''encourag'':328,370 ''eras''