INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('530', '2', '530', NULL, 'Why boastest thou thyself in Mischief? - Why dost thou "exult" in that which is wrong? Why dost thou find pleasure in evil rather than in good? Why dost thou seek to triumph in the injury done to others? The reference is to one who prided himself on schemes and projects which tended to injure others; or who congratulated himself on the success which attended his efforts to wrong other people.O mighty man - DeWette and Luther render this, "tyrant." The original word would be properly applied to one of rank or distinction; a man of "power" - power derived either from office, from talent, or from wealth. It is a word which is often applied to a hero or warrior: Isaiah 3:2; Ezekiel 39:20; 2 Samuel 17:10; Psalm 33:16; Psalm 120:4; Psalm 127:4; Daniel 11:3; Genesis 6:4; Jeremiah 51:30. So far as the "word" is concerned, it might be applied either to Saul or to any other warrior or man of rank; and Professor Alexander supposes that it refers to Saul himself. The connection, however, seems to require us to understand it of Doeg, and not of Saul, This appears to be clear(a) from the general character here given to the person referred to, a character not particularly applicable to Saul, but applicable to an informer like Doeg Psalm 52:2-4; and(b) from the fact that he derived his power, not from his rank and office, as Saul did, but mainly from his wealth Psalm 52:7. This would seem to imply that some other was referred to than Saul.The goodness of God endureth continually - literally, "all the day." That is, the wicked man could not hope to prevent the exercise of the divine goodness toward him whom he persecuted, and whom he sought to injure. David means to say that the goodness of God was so great and so constant, that he would protect his true friends from such machinations; or that it, was so unceasing and watchful, that the informer and accuser could not hope to find an interval of time when God would intermit his care, and when, therefore, he might hope for success. Against the goodness of God, the devices of a wicked man to injure the righteous could not ultimately prevail.', NULL, NULL, '''-4'':230 ''10'':128 ''11'':139 ''120'':133 ''127'':136 ''16'':131 ''17'':127 ''2'':121,125,229 ''20'':124 ''3'':120,140 ''30'':146 ''33'':130 ''39'':123 ''4'':134,137,143 ''51'':145 ''52'':228,256 ''6'':142 ''7'':257 ''accus'':344 ''alexand'':172 ''appear'':197 ''appli'':85,113,157 ''applic'':217,221 ''attend'':64 ''b'':232 ''boastest'':2 ''care'':359 ''charact'':205,214 ''clear'':200 ''concern'':153 ''congratul'':58 ''connect'':181 ''constant'':321 ''continu'':275 ''could'':285,345,383 ''daniel'':138 ''david'':307 ''day'':279 ''deriv'':97,238 ''devic'':374 ''dewett'':73 ''distinct'':91 ''divin'':294 ''doeg'':191,226 ''done'':36 ''dost'':8,17,28 ''effort'':66 ''either'':98,158 ''endureth'':274 ''evil'':22 ''exercis'':291 ''exult'':10 ''ezekiel'':122 ''fact'':235 ''far'':148 ''find'':19,349 ''friend'':328 ''general'':204 ''genesi'':141 ''given'':207 ''god'':273,315,355,372 ''good'':26,271,295,313,370 ''great'':318 ''hero'':116 ''hope'':287,347,365 ''howev'':182 ''impli'':262 ''inform'':224,342 ''injur'':54,306,380 ''injuri'':35 ''intermit'':357 ''interv'':351 ''isaiah'':119 ''jeremiah'':144 ''like'':225 ''liter'':276 ''luther'':75 ''machin'':331 ''main'':251 ''man'':72,93,167,284,378 ''mean'':308 ''might'':155,364 ''mighti'':71 ''mischief'':6 ''offic'':100,246 ''often'':112 ''one'':43,87 ''origin'':80 ''other'':38,55 ''particular'':216 ''people.o'':70 ''persecut'':300 ''person'':210 ''pleasur'':20 ''power'':95,96,240 ''prevail'':386 ''prevent'':289 ''pride'':45 ''professor'':171 ''project'':50 ''proper'':84 ''protect'':325 ''psalm'':129,132,135,227,255 ''rank'':89,169,244 ''rather'':23 ''refer'':40,176,211,267 ''render'':76 ''requir'':185 ''righteous'':382 ''samuel'':126 ''saul'':160,178,195,219,248 ''saul.the'':270 ''say'':310 ''scheme'':48 ''seek'':30 ''seem'':183,260 ''sought'':304 ''success'':62,367 ''suppos'':173 ''talent'':102 ''tend'':52 ''therefor'':362 ''thou'':3,9,18,29 ''thyself'':4 ''time'':353 ''toward'':296 ''triumph'':32 ''true'':327 ''tyrant'':78 ''ultim'':385 ''unceas'':337 ''understand'':188 ''us'':186 ''warrior'':118,165 ''watch'':339 ''wealth'':105,254 ''wick'':283,377 ''word'':81,109,151 ''would'':82,259,324,356 ''wrong'':15,68', NULL, '530');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('532', '2', '532', NULL, 'Save me, O God, by thy name - The word "name" here may include the perfections or attributes properly implied in the name. It is a calling on God as God, or in view of all that is implied in his name, or that constitutes the idea of "God." That name would imply all of power and benevolence that was necessary to secure his salvation or safety. The particular object of the prayer here is that God would save him from the design of the Ziphims to betray him to Saul. In some way David seems to have been apprised of the information which they had given to Saul, or at least to have suspected it so strongly that he felt it was necessary for him to move from place to place in order to find safety.And judqe me by thy strength - The word "judge" here is used in the sense of declaring a judgment in his favor, or of vindicating him. See the notes at Psalm 7:8. Compare Psalm 18:20; Psalm 26:1; Psalm 43:1. The idea is, Vindicate or save me by thy power.', NULL, NULL, '''1'':175,178 ''18'':171 ''20'':172 ''26'':174 ''43'':177 ''7'':167 ''8'':168 ''appris'':99 ''attribut'':17 ''benevol'':57 ''betray'':87 ''call'':26 ''compar'':169 ''constitut'':44 ''david'':94 ''declar'':152 ''design'':82 ''favor'':157 ''felt'':120 ''find'':135 ''given'':106 ''god'':4,28,30,48,76 ''idea'':46,180 ''impli'':19,38,52 ''includ'':13 ''inform'':102 ''judg'':144 ''judgment'':154 ''judq'':137 ''least'':111 ''may'':12 ''move'':127 ''name'':7,10,22,41,50 ''necessari'':60,123 ''note'':164 ''o'':3 ''object'':69 ''order'':133 ''particular'':68 ''perfect'':15 ''place'':129,131 ''power'':55,188 ''prayer'':72 ''proper'':18 ''psalm'':166,170,173,176 ''safeti'':66 ''safety.and'':136 ''salvat'':64 ''saul'':90,108 ''save'':1,78,184 ''secur'':62 ''see'':162 ''seem'':95 ''sens'':150 ''strength'':141 ''strong'':117 ''suspect'':114 ''thi'':6,140,187 ''use'':147 ''view'':33 ''vindic'':160,182 ''way'':93 ''word'':9,143 ''would'':51,77 ''ziphim'':85', NULL, '532');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('533', '2', '533', NULL, 'Give ear to my prayer - See the notes at Psalm 5:1; Psalm 17:6. This is the language of earnestness. The psalmist was in deep affliction, and he pleaded, therefore, that God would not turn away from him in his troubles.And hide not thyself from my supplication - That is, Do not withdraw thyself, or render thyself inaccessible to my prayer. Do not so conceal thyself that I may not have the privilege of approaching thee. Compare the notes at Isaiah 1:15. See also Ezekiel 22:26; Proverbs 28:27; Leviticus 20:4; 1 Samuel 12:3. The same word is used in all these places, and the general meaning is that of "shutting the eyes upon," as implying neglect. So also in Lamentations 3:56, the phrase "to hide the ear" means to turn away so as not to hear. The earnest prayer of the psalmist here is, that God would not, as it were, withdraw or conceal himself, but would give free access to himself in prayer. The language is, of course, figurative, but it illustrates what often occurs when God seems to withdraw himself; when our prayers do not appear to be heard; when God is apparently unwilling to attend to us.', NULL, NULL, '''1'':12,82,95 ''12'':97 ''15'':83 ''17'':14 ''20'':93 ''22'':87 ''26'':88 ''27'':91 ''28'':90 ''3'':98,126 ''4'':94 ''5'':11 ''56'':127 ''6'':15 ''access'':166 ''afflict'':27 ''also'':85,123 ''appar'':201 ''appear'':194 ''approach'':75 ''attend'':204 ''away'':37,137 ''compar'':77 ''conceal'':65,160 ''cours'':175 ''deep'':26 ''ear'':2,133 ''earnest'':21,144 ''eye'':117 ''ezekiel'':86 ''figur'':176 ''free'':165 ''general'':110 ''give'':1,164 ''god'':33,152,184,199 ''hear'':142 ''heard'':197 ''hide'':43,131 ''illustr'':179 ''impli'':120 ''inaccess'':58 ''isaiah'':81 ''lament'':125 ''languag'':19,172 ''leviticus'':92 ''may'':69 ''mean'':111,134 ''neglect'':121 ''note'':8,79 ''occur'':182 ''often'':181 ''phrase'':129 ''place'':107 ''plead'':30 ''prayer'':5,61,145,170,191 ''privileg'':73 ''proverb'':89 ''psalm'':10,13 ''psalmist'':23,148 ''render'':56 ''samuel'':96 ''see'':6,84 ''seem'':185 ''shut'':115 ''supplic'':48 ''thee'':76 ''therefor'':31 ''thyself'':45,54,57,66 ''troubles.and'':42 ''turn'':36,136 ''unwil'':202 ''upon'':118 ''us'':206 ''use'':103 ''withdraw'':53,158,187 ''word'':101 ''would'':34,153,163', NULL, '533');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('534', '2', '534', NULL, 'Be merciful unto me, O God - See the notes at Psalm 51:1.For man would swallow me up - The word used here means properly to breathe hard; to pant; to blow hard; and then, to pant after, to yawn after with open mouth. The idea is, that people came upon him everywhere with open mouth, as if they would swallow him down whole. He found no friend in man - in any man. Everywhere his life was sought. There was no "man," wherever he might go, on whom he could rely, or whom he could trust; and his only refuge, therefore, was in God.He fighting daily - Constantly; without intermission. That is, all people seemed to be at war with him, and to pursue him always.Oppresseth me - Presses hard upon me; so presses on me as always to endanger my life, and so that I feel no security anywhere.', NULL, NULL, '''1.for'':13 ''51'':12 ''alway'':135 ''always.oppresseth'':124 ''anywher'':147 ''blow'':31 ''breath'':26 ''came'':49 ''constant'':106 ''could'':89,94 ''daili'':105 ''endang'':137 ''everywher'':52,73 ''feel'':144 ''fight'':104 ''found'':65 ''friend'':67 ''go'':85 ''god'':6 ''god.he'':103 ''hard'':27,32,127 ''idea'':45 ''intermiss'':108 ''life'':75,139 ''man'':14,69,72,81 ''mean'':23 ''merci'':2 ''might'':84 ''mouth'':43,55 ''note'':9 ''o'':5 ''open'':42,54 ''pant'':29,36 ''peopl'':48,112 ''press'':126,131 ''proper'':24 ''psalm'':11 ''pursu'':122 ''refug'':99 ''reli'':90 ''secur'':146 ''see'':7 ''seem'':113 ''sought'':77 ''swallow'':16,60 ''therefor'':100 ''trust'':95 ''unto'':3 ''upon'':50,128 ''use'':21 ''war'':117 ''wherev'':82 ''whole'':63 ''without'':107 ''word'':20 ''would'':15,59 ''yawn'':39', NULL, '534');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('535', '2', '535', NULL, 'Be merciful unto me, O God - The same beginning as the former psalm - a cry for mercy; an overwhelming sense of trouble and danger leading him to come at once to the throne of God for help. See the notes at Psalm 56:1.For my soul trusteth in thee - See the notes at Psalm 56:3. He had nowhere else to go; there was no one on whom he could rely but God.Yea, in the shadow of thy wings will I make my refuge - Under the protection or covering of his wings - as young birds seek protection under the wings of the parent bird. See the notes at Psalm 17:8. Compare Psalm 36:7.Until these calamities be overpast - Compare Job 14:13, note; Psalm 27:13, note; also at Isaiah 26:20, note. He believed that these calamities "would" pass away, or would cease; that a time would come when he would not thus be driven from place to place. At present he knew that he was in danger, and he desired the divine protection, for under "that" protection he would be safe.', NULL, NULL, '''1.for'':44 ''13'':123,127 ''14'':122 ''17'':110 ''20'':133 ''26'':132 ''27'':126 ''3'':56 ''36'':114 ''56'':43,55 ''7.until'':115 ''8'':111 ''also'':129 ''away'':142 ''begin'':9 ''believ'':136 ''bird'':95,104 ''calam'':117,139 ''ceas'':145 ''come'':28,150 ''compar'':112,120 ''could'':70 ''cover'':89 ''cri'':15 ''danger'':24,170 ''desir'':173 ''divin'':175 ''driven'':157 ''els'':60 ''former'':12 ''go'':62 ''god'':6,35 ''god.yea'':73 ''help'':37 ''isaiah'':131 ''job'':121 ''knew'':165 ''lead'':25 ''make'':82 ''merci'':2,17 ''note'':40,52,107,124,128,134 ''nowher'':59 ''o'':5 ''one'':66 ''overpast'':119 ''overwhelm'':19 ''parent'':103 ''pass'':141 ''place'':159,161 ''present'':163 ''protect'':87,97,176,180 ''psalm'':13,42,54,109,113,125 ''refug'':84 ''reli'':71 ''safe'':184 ''see'':38,50,105 ''seek'':96 ''sens'':20 ''shadow'':76 ''soul'':46 ''thee'':49 ''thi'':78 ''throne'':33 ''thus'':155 ''time'':148 ''troubl'':22 ''trusteth'':47 ''unto'':3 ''wing'':79,92,100 ''would'':140,144,149,153,182 ''young'':94', NULL, '535');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('537', '2', '537', NULL, 'Deliver me from mine enemies, O my God - See the notes at Psalm 18:48. This prayer was offered when the spies sent by Saul surrounded the house of David. They had come to apprehend him, and it is to be presumed that they had come in sufficient numbers, and with sufficient power, to effect their object. Their purpose was not to break in upon him in the night, but to watch their opportunity, when he went forth in the morning, to slay him 1 Samuel 19:11, and there seemed no way for him to escape. Of their coming, and of their design, Michal, the daughter of Saul, and the wife of David, seems to have been apprised - perhaps by someone of her father''s family. She informed David of the arrangement, and assured him that unless he should escape in the night, he would be put to death in the morning. She, therefore, let him down through a window, and he escaped, 1 Samuel 19:12. It was in this way that he was in fact delivered; in this way that his prayer was answered. A faithful wife saved him.Defend me from them that rise up against me - Margin, as in Hebrew, "Set me on high." The idea is that of placing him, as it were, on a tower, or on an eminence which would be inaccessible. These were common places of refuge or defense. See the notes at Psalm 18:2.', NULL, NULL, '''1'':85,165 ''11'':88 ''12'':168 ''18'':14,243 ''19'':87,167 ''2'':244 ''48'':15 ''answer'':187 ''apprehend'':35 ''appris'':119 ''arrang'':133 ''assur'':135 ''break'':63 ''come'':33,46,100 ''common'':232 ''daughter'':107 ''david'':30,114,130 ''death'':150 ''defens'':237 ''deliv'':1,179 ''design'':104 ''effect'':55 ''emin'':225 ''enemi'':5 ''escap'':97,141,164 ''fact'':178 ''faith'':189 ''famili'':127 ''father'':125 ''forth'':78 ''god'':8 ''hebrew'':204 ''high'':208 ''him.defend'':192 ''hous'':28 ''idea'':210 ''inaccess'':229 ''inform'':129 ''let'':156 ''margin'':201 ''michal'':105 ''mine'':4 ''morn'':81,153 ''night'':69,144 ''note'':11,240 ''number'':49 ''o'':6 ''object'':57 ''offer'':19 ''opportun'':74 ''perhap'':120 ''place'':214,233 ''power'':53 ''prayer'':17,185 ''presum'':42 ''psalm'':13,242 ''purpos'':59 ''put'':148 ''refug'':235 ''rise'':197 ''samuel'':86,166 ''saul'':25,109 ''save'':191 ''see'':9,238 ''seem'':91,115 ''sent'':23 ''set'':205 ''slay'':83 ''someon'':122 ''spi'':22 ''suffici'':48,52 ''surround'':26 ''therefor'':155 ''tower'':221 ''unless'':138 ''upon'':65 ''watch'':72 ''way'':93,173,182 ''went'':77 ''wife'':112,190 ''window'':161 ''would'':146,227', NULL, '537');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('551', '2', '551', NULL, 'Truly God is good to Israel - That is, to his people; to the righteous; to those who serve him. That is, God is the "real" friend of the righteous. He has not forgotten them. He does not abandon them. He is not indifferent to them. He is not the friend of wicked people; and the administration of his government is not in favor of wickedness. After all that seems to indicate this, after all that troubles the mind in regard to his dealings, it is a truth that God is the friend of righteousness, and not of wickedness, and that there is advantage in his service. To see the force of what is said here by the psalmist we must realize that the train of thought in the psalm had passed through his mind, and that his perplexities had been relieved in the manner specified in the psalm. The margin here is "yet;" "yet God is good to Israel." This word "yet" would, in this place, be a happy translation. The psalmist then would be represented as having been engaged in meditating on the subject and in looking at all its perplexities, and then he says, "Yet God is good; notwithstanding all the difficulties in the case, it is nevertheless true that he is the friend of his people - the friend of righteousness."Even to such as are of a clean heart - Margin, as in Hebrew, "clean of heart." See Psalm 73:13. The reference is to those who are truly righteous, for all true righteousness has its seat in the heart. See Psalm 51:10.', NULL, NULL, '''10'':266 ''13'':243 ''51'':265 ''73'':242 ''abandon'':38 ''administr'':56 ''advantag'':103 ''case'':207 ''clean'':231,237 ''deal'':83 ''difficulti'':204 ''engag'':180 ''even'':224 ''favor'':63 ''forc'':110 ''forgotten'':33 ''friend'':26,50,92,216,221 ''god'':2,22,89,155,198 ''good'':4,157,200 ''govern'':59 ''happi'':169 ''heart'':232,239,262 ''hebrew'':236 ''indic'':71 ''indiffer'':43 ''israel'':6,159 ''look'':188 ''manner'':144 ''margin'':150,233 ''medit'':182 ''mind'':78,134 ''must'':120 ''nevertheless'':210 ''notwithstand'':201 ''pass'':131 ''peopl'':11,53,219 ''perplex'':138,192 ''place'':166 ''psalm'':129,148,241,264 ''psalmist'':118,172 ''real'':25 ''realiz'':121 ''refer'':245 ''regard'':80 ''reliev'':141 ''repres'':176 ''righteous'':14,29,94,223,252,256 ''said'':114 ''say'':196 ''seat'':259 ''see'':108,240,263 ''seem'':69 ''serv'':18 ''servic'':106 ''specifi'':145 ''subject'':185 ''thought'':126 ''train'':124 ''translat'':170 ''troubl'':76 ''true'':211,255 ''truli'':1,251 ''truth'':87 ''wick'':52 ''wicked'':65,98 ''word'':161 ''would'':163,174 ''yet'':153,154,162,197', NULL, '551');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('552', '2', '552', NULL, 'Thine enemies roar - This refers to the shout and tumult of war. They raised up the war-cry even in the very place where the congregations had been assembled; where God had been worshipped. The word rendered "roar" properly has reference to wild beasts; and the meaning is, that their war-cry resembled the howling of beasts of prey.In the midst of thy congregations - literally, "in the midst of thine assembly." This is a different word from that which is rendered "congregation" in Psalm 74:2. This word -   moed - means a meeting together by mutual appointment, and is often applied to the meeting of God with his people at the tabernacle, which was therefore called "the tent of the congregation," or, more properly, "the tent of meeting," as the place where God met with his people, Exodus 29:10, Exodus 29:44; Exodus 33:7; Leviticus 3:8, Leviticus 3:13; Leviticus 10:7, Leviticus 10:9; "et saepe." The meaning here is, that they roared like wild beasts in the very place which God had appointed as the place where he would meet with his people.They set up their ensigns for signs - That is, they set up "their" banners or standards, as "the" standards of the place; as that which indicated sovereignty over the place. They proclaimed thus that it was a conquered place, and they set up their own standards as denoting their title to it, or as declaring that they ruled there. It was no longer a place sacred to God; it was publicly seen to belong to a foreign power.', NULL, NULL, '''10'':141,155,158 ''13'':153 ''2'':88 ''29'':140,143 ''3'':149,152 ''33'':146 ''44'':144 ''7'':147,156 ''74'':87 ''8'':150 ''9'':159 ''appli'':102 ''appoint'':98,179 ''assembl'':30,73 ''banner'':202 ''beast'':45,59,171 ''belong'':262 ''call'':117 ''congreg'':27,66,84,122 ''conquer'':226 ''cri'':19,54 ''declar'':243 ''denot'':236 ''differ'':77 ''enemi'':2 ''ensign'':193 ''et'':160 ''even'':20 ''exodus'':139,142,145 ''foreign'':265 ''god'':32,107,134,177,256 ''howl'':57 ''indic'':214 ''leviticus'':148,151,154,157 ''like'':169 ''liter'':67 ''longer'':251 ''mean'':48,92,163 ''meet'':94,105,129,186 ''met'':135 ''midst'':63,70 ''mo'':91 ''mutual'':97 ''often'':101 ''peopl'':110,138 ''people.they'':189 ''place'':24,132,175,182,210,218,227,253 ''power'':266 ''prey.in'':61 ''proclaim'':220 ''proper'':40,125 ''psalm'':86 ''public'':259 ''rais'':14 ''refer'':5,42 ''render'':38,83 ''resembl'':55 ''roar'':3,39,168 ''rule'':246 ''sacr'':254 ''saep'':161 ''seen'':260 ''set'':190,199,230 ''shout'':8 ''sign'':195 ''sovereignti'':215 ''standard'':204,207,234 ''tabernacl'':113 ''tent'':119,127 ''therefor'':116 ''thi'':65 ''thine'':1,72 ''thus'':221 ''titl'':238 ''togeth'':95 ''tumult'':10 ''war'':12,18,53 ''war-cri'':17,52 ''wild'':44,170 ''word'':37,78,90 ''worship'':35 ''would'':185', NULL, '552');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('553', '2', '553', NULL, 'Unto thee, O God, do we give thanks - We, the people; language which would be appropriate to public thanksgiving - showing that the psalm was designed for public use. The reasons for this public thanksgiving are stated in the subsequent part of the psalm.Do we give thanks - The repetition is emphatic. The idea is, that the occasion was one for special thanksgiving.For that thy name is near - literally, "and near is thy name." The word name is often used to designate the person himself; and the idea here is, that God was near; that he had manifested himself to them in some special manner, and that for this there was occasion of praise. Compare Jeremiah 23:23.Thy wondrous works declare - Or, "They declare thy wondrous works." The Septuagint renders it, "I will declare all thy wondrous works." The Latin Vulgate, "We will declare thy wonders." Luther, "We will declare thy wonders, that thy name is so near." Prof. Alexander, "They recount thy wonders." The meaning seems to be, "They," that is, the people, "declare thy wondrous works." Thy marvelous doings constitute the foundation for praise - for the praise now offered.', NULL, NULL, '''23'':115 ''23.thy'':116 ''alexand'':158 ''appropri'':16 ''compar'':113 ''constitut'':180 ''declar'':119,122,132,142,148,173 ''design'':25,80 ''do'':179 ''emphat'':50 ''foundat'':182 ''give'':7,45 ''god'':4,90 ''idea'':52,86 ''jeremiah'':114 ''languag'':12 ''latin'':138 ''liter'':67 ''luther'':145 ''manifest'':96 ''manner'':103 ''marvel'':178 ''mean'':164 ''name'':64,72,75,153 ''near'':66,69,92,156 ''o'':3 ''occas'':56,110 ''offer'':189 ''often'':77 ''one'':58 ''part'':40 ''peopl'':11,172 ''person'':82 ''prais'':112,184,187 ''prof'':157 ''psalm'':23 ''psalm.do'':43 ''public'':18,27,33 ''reason'':30 ''recount'':160 ''render'':128 ''repetit'':48 ''seem'':165 ''septuagint'':127 ''show'':20 ''special'':60,102 ''state'':36 ''subsequ'':39 ''thank'':8,46 ''thanksgiv'':19,34 ''thanksgiving.for'':61 ''thee'':2 ''thi'':63,71,123,134,143,149,152,161,174,177 ''unto'':1 ''use'':28,78 ''vulgat'':139 ''wonder'':144,150,162 ''wondrous'':117,124,135,175 ''word'':74 ''work'':118,125,136,176 ''would'':14', NULL, '553');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('554', '2', '554', NULL, 'In Judah is God known - That is, he has made himself known there in a special manner; he has evinced his watchful care over the city so as to demand a proper acknowledgment; he has manifested himself there as he has not elsewhere. It is true that God is known, or makes himself known everywhere; but it is also true that he does this in some places, and at some times, in a more marked and striking manner than he does in other places and at other times. The most clear and impressive displays of his character are among his own people - in the church. "His name is great in Israel." Among the people of Israel; or, among his own people. The meaning here is, that, by some act referred to in the psalm, he had so displayed his power and his mercy in favor of that people, as to make it proper that his name should be exalted or praised.', NULL, NULL, '''acknowledg'':33 ''act'':129 ''also'':59 ''among'':99,112,118 ''care'':23 ''charact'':97 ''church'':105 ''citi'':26 ''clear'':91 ''demand'':30 ''display'':94,138 ''elsewher'':43 ''everywher'':55 ''evinc'':20 ''exalt'':159 ''favor'':145 ''god'':4,48 ''great'':109 ''impress'':93 ''israel'':111,116 ''judah'':2 ''known'':5,12,50,54 ''made'':10 ''make'':52,151 ''manifest'':36 ''manner'':17,78 ''mark'':75 ''mean'':123 ''merci'':143 ''name'':107,156 ''peopl'':102,114,121,148 ''place'':67,84 ''power'':140 ''prais'':161 ''proper'':32,153 ''psalm'':134 ''refer'':130 ''special'':16 ''strike'':77 ''time'':71,88 ''true'':46,60 ''watch'':22', NULL, '554');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('555', '2', '555', NULL, 'I cried unto God with my voice - That is, he cried or prayed audibly. It was not mere mental prayer. See the notes at Psalm 3:4.Even unto God with my voice - The repetition here is emphatic. The idea is that it was an earnest or fervent cry. Compare the notes at 2 Corinthians 12:8.And he gave ear unto me - See Psalm 5:1, note; Psalm 17:6, note.', NULL, NULL, '''1'':65 ''12'':55 ''17'':68 ''2'':53 ''3'':26 ''4.even'':27 ''5'':64 ''6'':69 ''8.and'':56 ''audibl'':14 ''compar'':49 ''corinthian'':54 ''cri'':2,11,48 ''ear'':59 ''earnest'':45 ''emphat'':37 ''fervent'':47 ''gave'':58 ''god'':4,29 ''idea'':39 ''mental'':19 ''mere'':18 ''note'':23,51,66,70 ''pray'':13 ''prayer'':20 ''psalm'':25,63,67 ''repetit'':34 ''see'':21,62 ''unto'':3,28,60 ''voic'':7,32', NULL, '555');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('832', '2', '832', NULL, 'Third prophecy Ezekiel 30:1-19 against Egypt, probably to be connected with the previous verses (compare Ezekiel 30:10 with the Ezekiel 29:17-21 note). Some consider it to belong to the earlier part of Ezekiel 29 (compare Ezekiel 29:10, Ezekiel 29:12 with Ezekiel 30:5-6).', NULL, NULL, '''-19'':6 ''-21'':26 ''-6'':51 ''1'':5 ''10'':20,43 ''12'':46 ''17'':25 ''29'':24,39,42,45 ''30'':4,19,49 ''5'':50 ''belong'':32 ''compar'':17,40 ''connect'':12 ''consid'':29 ''earlier'':35 ''egypt'':8 ''ezekiel'':3,18,23,38,41,44,48 ''note'':27 ''part'':36 ''previous'':15 ''probabl'':9 ''propheci'':2 ''third'':1 ''vers'':16', NULL, '832');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('564', '2', '564', NULL, 'Bow down thine ear, O Lord, hear me - See the notes at Psalm 5:1.For I am poor and needy - This is the reason here assigned why God should hear him. It is not a plea of merit. It is not that there was any claim on God in the fact that he was a poor and needy man - a sinner helpless and dependent, or that it would be any injustice if God should not hear, for a sinner has no claim to favor; but it is that this was a condition in which the aid of God was needed, and in which it was proper or appropriate for God to hear prayer, and to render help. We may always make our helplessness, our weakness, our poverty, our need, a ground of appeal to God; not as a claim of justice, but as a case in which he will glorify himself by a gracious interposition. It is also to be remarked that it is a matter of unspeakable thankfulness that the "poor and needy" may call upon God; that they will be as welcome as any class of people; that there is no condition of poverty and want so low that we are debarred from the privilege of approaching One who has infinite resources, and who is as willing to help as he is able.', NULL, NULL, '''1.for'':15 ''5'':14 ''abl'':225 ''aid'':96 ''also'':158 ''alway'':120 ''appeal'':133 ''approach'':209 ''appropri'':108 ''assign'':26 ''bow'':1 ''call'':176 ''case'':145 ''claim'':46,82,139 ''class'':187 ''condit'':92,194 ''debar'':204 ''depend'':64 ''ear'':4 ''fact'':51 ''favor'':84 ''glorifi'':150 ''god'':28,48,73,98,110,135,178 ''gracious'':154 ''ground'':131 ''hear'':7,30,76,112 ''help'':117,221 ''helpless'':62,123 ''infinit'':213 ''injustic'':71 ''interposit'':155 ''justic'':141 ''lord'':6 ''low'':200 ''make'':121 ''man'':59 ''matter'':166 ''may'':119,175 ''merit'':38 ''need'':100,129 ''needi'':20,58,174 ''note'':11 ''o'':5 ''one'':210 ''peopl'':189 ''plea'':36 ''poor'':18,56,172 ''poverti'':127,196 ''prayer'':113 ''privileg'':207 ''proper'':106 ''psalm'':13 ''reason'':24 ''remark'':161 ''render'':116 ''resourc'':214 ''see'':9 ''sinner'':61,79 ''thank'':169 ''thine'':3 ''unspeak'':168 ''upon'':177 ''want'':198 ''weak'':125 ''welcom'':184 ''will'':219 ''would'':68', NULL, '564');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('565', '2', '565', NULL, 'His foundation - This is an abrupt commencement of the psalm. The adjective "his" has been supposed by some to refer to the psalm itself, and this expression has been considered to be a part of the title to the psalm, meaning that the foundation of the psalm is the holy mountain where the praises of God were celebrated; that is Zion. This, however, is a forced and unnatural interpretation. The most obvious explanation is to refer it to God, and the meaning is, that his "foundation," or that which he had founded and established, to wit, the place for his worship, or for the institutions of religion, was in the holy mountains of Jerusalem. It would seem that the psalmist was contemplating the city - looking on its walls, and its palaces, and especially on the place which had been reared for the worship of God, and that he breaks out in this abrupt manner, by saying that this was what God had founded; that here he had established his home; that here was the place where he was worshipped, and where he dwelt; that this was the place which he loved more than all the other places where the descendants of Jacob dwelt.Is in the holy mountains - The mountains of Jerusalem. Jerusalem is surrounded by hills, and within the city itself there were the hills of Zion, Moriah, Acra, and Bezethah; See the notes at Matthew 2:1. These sacred hills God had selected as the place of his solemn worship - of his own abode. Compare the notes at Psalm 48:1-2.', NULL, NULL, '''-2'':263 ''1'':238,262 ''2'':237 ''48'':261 ''abod'':255 ''abrupt'':6,153 ''acra'':229 ''adject'':12 ''bezethah'':231 ''break'':149 ''celebr'':58 ''citi'':124,220 ''commenc'':7 ''compar'':256 ''consid'':30 ''contempl'':122 ''descend'':200 ''dwelt'':183 ''dwelt.is'':203 ''especi'':133 ''establish'':94,168 ''explan'':73 ''express'':27 ''forc'':66 ''found'':92,163 ''foundat'':2,44,86 ''god'':56,79,145,161,242 ''hill'':216,225,241 ''holi'':50,111,206 ''home'':170 ''howev'':63 ''institut'':105 ''interpret'':69 ''jacob'':202 ''jerusalem'':114,211,212 ''look'':125 ''love'':191 ''manner'':154 ''matthew'':236 ''mean'':41,82 ''moriah'':228 ''mountain'':51,112,207,209 ''note'':234,258 ''obvious'':72 ''palac'':131 ''part'':34 ''place'':98,136,175,188,197,247 ''prais'':54 ''psalm'':10,23,40,47,260 ''psalmist'':120 ''rear'':140 ''refer'':20,76 ''religion'':107 ''sacr'':240 ''say'':156 ''see'':232 ''seem'':117 ''select'':244 ''solemn'':250 ''suppos'':16 ''surround'':214 ''titl'':37 ''unnatur'':68 ''wall'':128 ''wit'':96 ''within'':218 ''worship'':101,143,179,251 ''would'':116 ''zion'':61,227', NULL, '565');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('566', '2', '566', NULL, 'O Lord God of my salvation - On whom I depend for salvation; who alone canst save me. Luther renders this, "O God, my Saviour."I have cried day and night before thee - literally, "By day I cried; by night before thee;" that is, my prayer is constantly before thee. The meaning is, that there was no intermission to his prayers; he prayed all the while. This does not refer to the general habit of his life, but to the time of his sickness. He had prayed most earnestly and constantly that he might be delivered from sickness and from the dangers of death. He had, as yet, obtained no answer, and he now pours out, and records, a more earnest petition to God.', NULL, NULL, '''alon'':14 ''answer'':110 ''canst'':15 ''constant'':47,90 ''cri'':27,37 ''danger'':101 ''day'':28,35 ''death'':103 ''deliv'':95 ''depend'':10 ''earnest'':88,120 ''general'':72 ''god'':3,22,123 ''habit'':73 ''intermiss'':57 ''life'':76 ''liter'':33 ''lord'':2 ''luther'':18 ''mean'':51 ''might'':93 ''night'':30,39 ''o'':1,21 ''obtain'':108 ''petit'':121 ''pour'':114 ''pray'':62,86 ''prayer'':45,60 ''record'':117 ''refer'':69 ''render'':19 ''salvat'':6,12 ''save'':16 ''saviour'':24 ''sick'':83,97 ''thee'':32,41,49 ''time'':80 ''yet'':107', NULL, '566');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('567', '2', '567', NULL, 'The days of his youth hast thou shortened - This does not mean that he had shortened his life, but that he had abbreviated the period of his vigor, his hope, and his prosperity; instead of lengthening out these, and prolonging them into advancing years, he had by calamities, disappointments, reverses, and troubles, as it were, abridged them. No such youthful vigor, no such youthful hope now remained. The feelings of age - the cutting off from the world - had come suddenly upon him, even before he had reached the season when this might be expected to occur. Though at a time of life and in circumstances when he might have hoped for a longer continuance of that youthful vigor, he had suddenly been brought into the sad condition of an old man.Thou hast covered him with shame - Hast clothed him with shame or disgrace. Everything in his circumstances and in his appearance indicates shame and disgrace, and the divine displeasure.', NULL, NULL, '''abbrevi'':23 ''abridg'':56 ''advanc'':43 ''age'':71 ''appear'':151 ''brought'':123 ''calam'':48 ''circumst'':105,147 ''cloth'':138 ''come'':79 ''condit'':127 ''continu'':114 ''cover'':133 ''cut'':73 ''day'':2 ''disappoint'':49 ''disgrac'':143,155 ''displeasur'':159 ''divin'':158 ''even'':83 ''everyth'':144 ''expect'':94 ''feel'':69 ''hast'':6,132,137 ''hope'':30,65,110 ''indic'':152 ''instead'':34 ''lengthen'':36 ''life'':18,102 ''longer'':113 ''man.thou'':131 ''mean'':12 ''might'':92,108 ''occur'':96 ''old'':130 ''period'':25 ''prolong'':40 ''prosper'':33 ''reach'':87 ''remain'':67 ''revers'':50 ''sad'':126 ''season'':89 ''shame'':136,141,153 ''shorten'':8,16 ''sudden'':80,121 ''thou'':7 ''though'':97 ''time'':100 ''troubl'':52 ''upon'':81 ''vigor'':28,61,118 ''world'':77 ''year'':44 ''youth'':5,60,64,117', NULL, '567');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('568', '2', '568', NULL, 'Lord - Not   Yahweh here, but   ''Adonay. The word is properly rendered "Lord," but it is a term which is often applied to God. It indicates, however, nothing in regard to his character or attributes except that he is a "Ruler or Governor."Thou hast been our dwelling-place - The Septuagint renders this, "refuge" - &#x3ba;&#x3b1;&#x3c4;&#x3b1;&#x3c6;&#x3c5;&#x3b3;&#x3b7;  kataphuge. So the Latin Vulgate, "refugium;" and Luther, "Zuflucht." The Hebrew word -   maon - means properly a habitation, a dwelling, as of God in his temple, Psalm 26:8; heaven, Psalm 68:5; Deuteronomy 26:15. It also means a den or lair for wild beasts, Nahum 2:12; Jeremiah 9:11. But here the idea seems to be, as in the Septuagint, Vulgate, and Luther, "a refuge"; a place to which one may come as to his home, as one does from a journey; from wandering; from toil; from danger: a place to which such a one naturally resorts, which he loves, and where he feels that he may rest secure. The idea is, that a friend of God has that feeling in respect to Him, which one has toward his own home - his abode - the place which he loves and calls his own.In all generations - Margin, "generation and generation." That is, A succeeding generation has found him to be the same as the previous generation had. He was unchanged, though the successive generations of men passed away.', NULL, NULL, '''11'':105 ''12'':102 ''15'':89 ''2'':101 ''26'':81,88 ''5'':86 ''68'':85 ''8'':82 ''9'':104 ''abod'':189 ''adonay'':6 ''also'':91 ''appli'':21 ''attribut'':34 ''away'':232 ''beast'':99 ''call'':196 ''charact'':32 ''come'':128 ''danger'':144 ''den'':94 ''deuteronomi'':87 ''dwell'':48,73 ''dwelling-plac'':47 ''except'':35 ''feel'':160,176 ''found'':211 ''friend'':171 ''generat'':200,202,204,209,220,228 ''god'':23,76,173 ''governor'':42 ''habit'':71 ''hast'':44 ''heaven'':83 ''hebrew'':65 ''home'':132,187 ''howev'':26 ''idea'':109,167 ''indic'':25 ''jeremiah'':103 ''journey'':138 ''kataphug'':55 ''lair'':96 ''latin'':58 ''lord'':1,12 ''love'':156,194 ''luther'':62,119 ''maon'':67 ''margin'':201 ''may'':127,163 ''mean'':68,92 ''men'':230 ''nahum'':100 ''natur'':152 ''noth'':27 ''often'':20 ''one'':126,134,151,182 ''own.in'':198 ''pass'':231 ''place'':49,123,146,191 ''previous'':219 ''proper'':10,69 ''psalm'':80,84 ''refug'':54,121 ''refugium'':60 ''regard'':29 ''render'':11,52 ''resort'':153 ''respect'':178 ''rest'':164 ''ruler'':40 ''secur'':165 ''seem'':110 ''septuagint'':51,116 ''succeed'':208 ''success'':227 ''templ'':79 ''term'':17 ''thou'':43 ''though'':225 ''toil'':142 ''toward'':184 ''unchang'':224 ''vulgat'':59,117 ''wander'':140 ''wild'':98 ''word'':8,66 ''yahweh'':3 ''zuflucht'':63', NULL, '568');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('97', '2', '97', NULL, 'See Leviticus 5:14 note. In Leviticus 7:2 "sprinkle" should rather be cast Leviticus 1:5. All the details regarding the parts put on the altar are repeated for each kind of sacrifice, because the matter was one of paramount importance.', NULL, NULL, '''1'':16 ''14'':4 ''2'':9 ''5'':3,17 ''7'':8 ''altar'':27 ''cast'':14 ''detail'':20 ''import'':42 ''kind'':32 ''leviticus'':2,7,15 ''matter'':37 ''note'':5 ''one'':39 ''paramount'':41 ''part'':23 ''put'':24 ''rather'':12 ''regard'':21 ''repeat'':29 ''sacrific'':34 ''see'':1 ''sprinkl'':10', NULL, '97');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('572', '2', '572', NULL, 'O Lord God, to whom vengeance belongeth ... - Margin, God of revenges The idea is, that it pertains to God to take vengeance, or to punish for crimes. See the notes at Romans 12:19. The appeal here is made to God in view of the crimes committed by others, and which are referred to in the subsequent part of the psalm. God is addressed as having the right to restrain and punish wicked people, and he is asked to interpose and assert that right in a case which clearly demanded it. The appeal is repeated to make it emphatic, or to denote "earnestness" in the petition.Show thyself - Margin, as in Hebrew, "shine forth." The meaning is, Manifest thyself; come forth as such a God; prove thy right; display thy power, and show that thou art a God opposed to crime and wrong. The same Hebrew word is used here which is found in Psalm 80:1, and which is there rendered "shine forth." See the notes at that passage.', NULL, NULL, '''1'':156 ''12'':33 ''19'':34 ''80'':155 ''address'':64 ''appeal'':36,93 ''art'':135 ''ask'':78 ''assert'':82 ''belongeth'':7 ''case'':87 ''clear'':89 ''come'':119 ''commit'':47 ''crime'':27,46,140 ''demand'':90 ''denot'':102 ''display'':128 ''earnest'':103 ''emphat'':99 ''forth'':113,120,163 ''found'':152 ''god'':3,9,19,41,62,124,137 ''hebrew'':111,145 ''idea'':13 ''interpos'':80 ''lord'':2 ''made'':39 ''make'':97 ''manifest'':117 ''margin'':8,108 ''mean'':115 ''note'':30,166 ''o'':1 ''oppos'':138 ''other'':49 ''part'':58 ''passag'':169 ''peopl'':74 ''pertain'':17 ''petition.show'':106 ''power'':130 ''prove'':125 ''psalm'':61,154 ''punish'':25,72 ''refer'':53 ''render'':161 ''repeat'':95 ''restrain'':70 ''reveng'':11 ''right'':68,84,127 ''roman'':32 ''see'':28,164 ''shine'':112,162 ''show'':132 ''subsequ'':57 ''take'':21 ''thi'':126,129 ''thou'':134 ''thyself'':107,118 ''use'':148 ''vengeanc'':6,22 ''view'':43 ''wick'':73 ''word'':146 ''wrong'':142', NULL, '572');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('573', '2', '573', NULL, 'O come, let us sing unto the Lord - The word here rendered come, means properly "go;" but it is used here, as it often is, as a formula of invitation, in calling on others to share in what is done by the speaker. It is here to be understood as used by one portion of an assembly convened for worship addressing the other portion, and calling on them to unite in the praise of God.Let us make a joyful noise - The word used here means commonly to make a loud noise, to shout, Job 30:5. It is especially used(a) of warlike shouts, Joshua 6:16; 1 Samuel 17:20;(b) of the shout of triumph, Judges 15:14;(c) of the sound or clangor of a trumpet, Numbers 10:9; Joel 2:1.It may thus be used to denote any shout of joy or praise. In public worship it would denote praise of the most animated kind.To the Rock of our salvation - The strong ground of our confidence; the basis of our hope; our security. See the notes at Psalm 18:2.', NULL, NULL, '''1'':108 ''1.it'':135 ''10'':131 ''14'':120 ''15'':119 ''16'':107 ''17'':110 ''18'':183 ''2'':134,184 ''20'':111 ''30'':95 ''5'':96 ''6'':106 ''9'':132 ''address'':61 ''anim'':158 ''assembl'':57 ''b'':112 ''basi'':172 ''c'':121 ''call'':32,66 ''clangor'':126 ''come'':2,13 ''common'':86 ''confid'':170 ''conven'':58 ''denot'':141,153 ''done'':40 ''especi'':99 ''formula'':28 ''go'':16 ''god.let'':75 ''ground'':167 ''hope'':175 ''invit'':30 ''job'':94 ''joel'':133 ''joshua'':105 ''joy'':79,145 ''judg'':118 ''kind.to'':159 ''let'':3 ''lord'':8 ''loud'':90 ''make'':77,88 ''may'':136 ''mean'':14,85 ''nois'':80,91 ''note'':180 ''number'':130 ''o'':1 ''often'':24 ''one'':53 ''other'':34 ''portion'':54,64 ''prais'':73,147,154 ''proper'':15 ''psalm'':182 ''public'':149 ''render'':12 ''rock'':161 ''salvat'':164 ''samuel'':109 ''secur'':177 ''see'':178 ''share'':36 ''shout'':93,104,115,143 ''sing'':5 ''sound'':124 ''speaker'':43 ''strong'':166 ''thus'':137 ''triumph'':117 ''trumpet'':129 ''understood'':49 ''unit'':70 ''unto'':6 ''us'':4,76 ''use'':20,51,83,100,139 ''warlik'':103 ''word'':10,82 ''worship'':60,150 ''would'':152', NULL, '573');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('574', '2', '574', NULL, 'O worship the Lord in the beauty of holiness - This verse is literally taken from 1 Chronicles 16:29-30. The margin here is, "in the glorious sanctuary." The Septuagint, &#x3b5;&#x3bd; &#x3b1;&#x3c5;&#x3bb;&#x3b7; &#x3b1;&#x3b3;&#x3b9;&#x3b1;  en aule hagia - "in his holy court." So the Latin Vulgate. On the meanings of the expression, see the notes at Psalm 29:2.Fear before him, all the earth - All lands; all people. The word rendered "fear" means properly to writhe, to twist, to be in pain; and then, to tremble, to quake, to be afraid. The word "tremble" would perhaps best express the idea here. It is that solemn awe produced by the sense of the divine presence and majesty which causes trembling. It denotes profound reverence for God.', NULL, NULL, '''-30'':20 ''1'':16 ''16'':18 ''2.fear'':54 ''29'':19,53 ''afraid'':86 ''aul'':32 ''awe'':101 ''beauti'':7 ''best'':92 ''caus'':113 ''chronicl'':17 ''court'':37 ''denot'':116 ''divin'':108 ''earth'':59 ''en'':31 ''express'':47,93 ''fear'':67 ''glorious'':27 ''god'':120 ''hagia'':33 ''holi'':9,36 ''idea'':95 ''land'':61 ''latin'':40 ''liter'':13 ''lord'':4 ''majesti'':111 ''margin'':22 ''mean'':44,68 ''note'':50 ''o'':1 ''pain'':77 ''peopl'':63 ''perhap'':91 ''presenc'':109 ''produc'':102 ''profound'':117 ''proper'':69 ''psalm'':52 ''quak'':83 ''render'':66 ''rever'':118 ''sanctuari'':28 ''see'':48 ''sens'':105 ''septuagint'':30 ''solemn'':100 ''taken'':14 ''trembl'':81,89,114 ''twist'':73 ''vers'':11 ''vulgat'':41 ''word'':65,88 ''worship'':2 ''would'':90 ''writh'':71', NULL, '574');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('575', '2', '575', NULL, 'The Lord reigneth - See the notes at Psalm 93:1. This is the general fact to be dwelt upon; this is the foundation of joy and praise. The universe is not without a sovereign. It is not the abode of anarchy. It is not the production of chance. It is not subject to mere physical laws. It is not under the control of evil. It is under the government of a God: a wise, holy, intelligent, just, benevolent Being, who rules it well, and who presides over all its affairs. If there is anything for which we should rejoice, it is that there is One Mind, everlasting and most glorious, who presides over the universe, and conducts all things according to his own wise and eternal plan.Let the earth rejoice - The earth itself; all parts of it; all that dwell upon it. As the earth everywhere derives whatever it has of fertility, beauty, grandeur, or stability, from God - as order, beauty, productiveness are diffused everywhere over it - as it has received so many proofs of the divine beneficence toward it, it has occasion for universal joy.Let the multitude of isles be glad thereof - Margin, "Many, or great isles." The Hebrew is many. So the Septuagint, the Latin Vulgate, the Chaldee, and the Syriac. The eye of the psalmist is evidently on the many islands which are scattered over the sea. Not merely the continents - the extended countries where nations dwell - have occasion for joy, but the beautiful islands - the spots of earth which have risen from the deep, and which are covered with fruits and flowers - these, too, have occasion to rejoice: to rejoice that God has raised them from the waters; that he keeps them from being overflowed or washed away; that he clothes them with beauty; that he makes them the abode of happy life; that he places them in the wastes of the ocean as he does the stars in the wastes of the sky, to beautify the universe. The idea in the verse is, that all the earth has cause to rejoice that Yahweh reigns.', NULL, NULL, '''1'':10 ''93'':9 ''abod'':39,304 ''accord'':120 ''affair'':90 ''anarchi'':41 ''anyth'':94 ''away'':292 ''beauti'':153,161,247,298 ''beautifi'':330 ''benefic'':178 ''benevol'':78 ''caus'':344 ''chalde'':210 ''chanc'':48 ''cloth'':295 ''conduct'':117 ''contin'':234 ''control'':62 ''countri'':237 ''cover'':262 ''deep'':258 ''deriv'':147 ''diffus'':164 ''divin'':177 ''dwell'':140,240 ''dwelt'':18 ''earth'':129,132,145,252,342 ''etern'':126 ''everlast'':107 ''everywher'':146,165 ''evid'':220 ''evil'':64 ''extend'':236 ''eye'':215 ''fact'':15 ''fertil'':152 ''flower'':266 ''foundat'':23 ''fruit'':264 ''general'':14 ''glad'':192 ''glorious'':110 ''god'':72,158,276 ''govern'':69 ''grandeur'':154 ''great'':197 ''happi'':306 ''hebrew'':200 ''holi'':75 ''idea'':334 ''intellig'':76 ''isl'':190,198 ''island'':224,248 ''joy'':25,244 ''joy.let'':186 ''keep'':285 ''latin'':207 ''law'':56 ''life'':307 ''lord'':2 ''make'':301 ''mani'':173,195,202,223 ''margin'':194 ''mere'':54,232 ''mind'':106 ''multitud'':188 ''nation'':239 ''note'':6 ''occas'':183,242,270 ''ocean'':317 ''one'':105 ''order'':160 ''overflow'':289 ''part'':135 ''physic'':55 ''place'':310 ''plan.let'':127 ''prais'':27 ''presid'':86,112 ''product'':46,162 ''proof'':174 ''psalm'':8 ''psalmist'':218 ''rais'':278 ''receiv'':171 ''reign'':349 ''reigneth'':3 ''rejoic'':99,130,272,274,346 ''risen'':255 ''rule'':81 ''scatter'':227 ''sea'':230 ''see'':4 ''septuagint'':205 ''sky'':328 ''sovereign'':34 ''spot'':250 ''stabil'':156 ''star'':322 ''subject'':52 ''syriac'':213 ''thereof'':193 ''thing'':119 ''toward'':179 ''univers'':29,115,185,332 ''upon'':19,141 ''vers'':337 ''vulgat'':208 ''wash'':291 ''wast'':314,325 ''water'':282 ''well'':83 ''whatev'':148 ''wise'':74,124 ''without'':32 ''yahweh'':348', NULL, '575');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('576', '2', '576', NULL, 'O sing unto the Lord a new song - Compare Psalm 33:3; Psalm 96:1. "For he hath done marvelous things." Things suited to excite wonder, or to fill the mind with astonishment. See Psalm 77:14; Psalm 86:10.His right hand - The instrument by which we execute any purpose. Compare Isaiah 59:16; Isaiah 63:5.And his holy arm - The arm of his holiness; that is, his arm put forth in a righteous cause, or vindicating that which is right.Hath gotten him the victory - literally, "has worked salvation for him:" for himself, or in his own cause. The victory - the salvation - was really in defense of his own government; in maintaining his own authority against those who set themselves in opposition to it. What is here said may be applied to all that God does. It is really in his own cause, in order to maintain the principles of his own administration.', NULL, NULL, '''1'':15 ''10.his'':40 ''14'':37 ''16'':54 ''3'':12 ''33'':11 ''5.and'':57 ''59'':53 ''63'':56 ''77'':36 ''86'':39 ''96'':14 ''administr'':153 ''appli'':131 ''arm'':60,62,69 ''astonish'':33 ''author'':115 ''caus'':75,98,143 ''compar'':9,51 ''defens'':106 ''done'':19 ''excit'':25 ''execut'':48 ''fill'':29 ''forth'':71 ''god'':135 ''gotten'':82 ''govern'':110 ''hand'':42 ''hath'':18 ''holi'':59,65 ''instrument'':44 ''isaiah'':52,55 ''liter'':86 ''lord'':5 ''maintain'':112,147 ''marvel'':20 ''may'':129 ''mind'':31 ''new'':7 ''o'':1 ''opposit'':122 ''order'':145 ''principl'':149 ''psalm'':10,13,35,38 ''purpos'':50 ''put'':70 ''realli'':104,139 ''right'':41 ''right.hath'':81 ''righteous'':74 ''said'':128 ''salvat'':89,102 ''see'':34 ''set'':119 ''sing'':2 ''song'':8 ''suit'':23 ''thing'':21,22 ''unto'':3 ''victori'':85,100 ''vindic'':77 ''wonder'':26 ''work'':88', NULL, '576');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('586', '2', '586', NULL, 'O God, my heart is fixed - Prepared, suited, ready. See the notes at Psalm 57:7. In Psalm 57:7, this is repeated: "My heart is fixed; O God, my heart is fixed:" indicating that there "might" have been some doubt or vacillation caused by the circumstances then existing, and the repetition would have respect to that, as if the psalmist had been unsettled and wavering for a time, but was at last firm. In such circumstances it would not be unnatural to "repeat" the assertion, as if there were no longer any doubt. In the beginning of a psalm, however, where there had been no previous expression or feeling of doubt so far as appears, there would be no propriety in repeating the assertion.I will sing and give praise - See the notes at Psalm 57:7.Even with my glory - This is not in Psalm 57:1-11. It is literally here, "truly my glory." In Psalm 57:8, however, the expression, "Awake up, my glory," occurs, and this seems to correspond with that language. It means here that it was his glory - his honor - thus to be employed in giving praise to God. It was worthy of all that there was elevated in his nature; of all that constituted his glory; of his highest powers. At no time is man employed in a more noble and lofty work than praise.', NULL, NULL, '''-11'':148 ''1'':147 ''57'':15,19,136,146,158 ''7'':16,20 ''7.even'':137 ''8'':159 ''appear'':116 ''assert'':86 ''assertion.i'':125 ''awak'':163 ''begin'':97 ''caus'':44 ''circumst'':47,77 ''constitut'':210 ''correspond'':172 ''doubt'':41,94,112 ''elev'':203 ''employ'':189,222 ''exist'':49 ''express'':108,162 ''far'':114 ''feel'':110 ''firm'':74 ''fix'':6,27,33 ''give'':129,191 ''glori'':140,155,166,183,212 ''god'':2,29,194 ''heart'':4,25,31 ''highest'':215 ''honor'':185 ''howev'':101,160 ''indic'':34 ''languag'':175 ''last'':73 ''liter'':151 ''lofti'':228 ''longer'':92 ''man'':221 ''mean'':177 ''might'':37 ''natur'':206 ''nobl'':226 ''note'':12,133 ''o'':1,28 ''occur'':167 ''power'':216 ''prais'':130,192,231 ''prepar'':7 ''previous'':107 ''proprieti'':121 ''psalm'':14,18,100,135,145,157 ''psalmist'':61 ''readi'':9 ''repeat'':23,84,123 ''repetit'':52 ''respect'':55 ''see'':10,131 ''seem'':170 ''sing'':127 ''suit'':8 ''thus'':186 ''time'':69,219 ''truli'':153 ''unnatur'':82 ''unsettl'':64 ''vacil'':43 ''waver'':66 ''work'':229 ''worthi'':197 ''would'':53,79,118', NULL, '586');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('587', '2', '587', NULL, 'Hold not thy peace - That is, Speak for my defense - as if God had looked with unconcern on the wrongs which were done to him. See the notes at Psalm 83:1.O God of my praise - The God whom I praise; whom I worship and adore. It implies that he was accustomed to praise him, and desired still to praise him. He sought that God would interpose now that he might have new occasion for praise.', NULL, NULL, '''1'':32 ''83'':31 ''accustom'':53 ''ador'':47 ''defens'':10 ''desir'':58 ''done'':23 ''god'':13,34,39,66 ''hold'':1 ''impli'':49 ''interpos'':68 ''look'':15 ''might'':72 ''new'':74 ''note'':28 ''o'':33 ''occas'':75 ''peac'':4 ''prais'':37,42,55,61,77 ''psalm'':30 ''see'':26 ''sought'':64 ''speak'':7 ''still'':59 ''thi'':3 ''unconcern'':17 ''worship'':45 ''would'':67 ''wrong'':20', NULL, '587');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('588', '2', '588', NULL, 'The Lord said unto my Lord - In the Hebrew, "Spake Jehovah to my Lord." The word   Yahweh is the incommunicable name of God. It is never given to a created being. The other word translated "Lord -   ''Adonay - means one who has rule or authority; one of high rank; one who has dominion; one who is the owner or possessor, etc. This word is applied frequently to a creature. It is applied to kings, princes, rulers, masters. The phrase "my Lord" refers to someone who was superior in rank to the author of the psalm; one whom he could address as his superior. The psalm, therefore, cannot refer to David himself, as if Yahweh had said to him, "Sit thou at my right hand." Nor was there anyone on earth in the time of David to whom it could be applicable; anyone whom he would call his "Lord" or superior. If, therefore, the psalm was written by David, it must have reference to the Messiah - to one whom he owned as his superior - his Lord - his Sovereign. It cannot refer to God as if he were to have this rule over David, since God himself is referred to as "speaking" to him whom David called his Lord: "Jehovah said unto my Lord." The reasoning of the Saviour, therefore, in Matthew 22:43-45, was founded on a fair and just interpretation of the psalm, and was so plain and conclusive that the Pharisees did not attempt to reply to it. Matthew 22:46. See the notes at that passage. No other interpretation "can" be given to it, consistently with the proper rules of expounding language, unless it be shown that the psalm was not composed by David, and might, therefore, be applied to someone whom the author would acknowledge as his "Lord." But there is no evidence of this, and there is no one in the Old Testament history to whom the psalm would be applicable.Sit thou at my right hand - The position of honor and of rank. Compare the notes at Psalm 16:8. See also Psalm 45:9; Mark 14:62; Luke 22:69; Acts 7:55; Hebrews 1:3; Hebrews 8:1. The phrase is properly applicable to the Messiah as exalted to the highest place in the universe - the right hand of God.Until I make thine enemies thy footstool - Until they are entirely subdued under time. See the notes at Matthew 22:44. The enemies here referred to are the enemies of the Messiah considered as King (see Psalm 2:1-12); and the promise here is, that "he must reign until he shall have put all enemies under his feet." See the notes at 1 Corinthians 15:25.', NULL, NULL, '''-12'':425 ''-45'':222 ''1'':360,364,424,449 ''14'':351 ''15'':451 ''16'':343 ''2'':423 ''22'':220,251,354,405 ''25'':452 ''3'':361 ''43'':221 ''44'':406 ''45'':348 ''46'':252 ''55'':358 ''62'':352 ''69'':355 ''7'':357 ''8'':344,363 ''9'':349 ''acknowledg'':298 ''act'':356 ''address'':99 ''adonay'':37 ''also'':346 ''anyon'':127,141 ''appli'':64,71,291 ''applic'':140,369 ''applicable.sit'':325 ''attempt'':245 ''author'':44,91,296 ''call'':145,204 ''cannot'':106,178 ''compar'':338 ''compos'':284 ''conclus'':239 ''consid'':418 ''consist'':267 ''corinthian'':450 ''could'':98,138 ''creat'':30 ''creatur'':68 ''david'':109,134,157,191,203,286 ''dominion'':52 ''earth'':129 ''enemi'':390,408,414,441 ''entir'':396 ''etc'':60 ''evid'':306 ''exalt'':374 ''expound'':273 ''fair'':227 ''feet'':444 ''footstool'':392 ''found'':224 ''frequent'':65 ''given'':27,264 ''god'':23,181,193 ''god.until'':386 ''hand'':123,330,384 ''hebrew'':9,359,362 ''high'':47 ''highest'':377 ''histori'':318 ''honor'':334 ''incommunic'':20 ''interpret'':230,261 ''jehovah'':11,207 ''king'':73,420 ''languag'':274 ''lord'':2,6,14,36,80,147,174,206,211,301 ''luke'':353 ''make'':388 ''mark'':350 ''master'':76 ''matthew'':219,250,404 ''mean'':38 ''messiah'':164,372,417 ''might'':288 ''must'':159,433 ''name'':21 ''never'':26 ''note'':255,340,402,447 ''old'':316 ''one'':39,45,49,53,95,166,313 ''own'':169 ''owner'':57 ''passag'':258 ''pharise'':242 ''phrase'':78,366 ''place'':378 ''plain'':237 ''posit'':332 ''possessor'':59 ''princ'':74 ''promis'':428 ''proper'':270,368 ''psalm'':94,104,153,233,281,322,342,347,422 ''put'':439 ''rank'':48,88,337 ''reason'':213 ''refer'':81,107,161,179,196,410 ''reign'':434 ''repli'':247 ''right'':122,329,383 ''rule'':42,189,271 ''ruler'':75 ''said'':3,115,208 ''saviour'':216 ''see'':253,345,400,421,445 ''shall'':437 ''shown'':278 ''sinc'':192 ''sit'':118 ''someon'':83,293 ''sovereign'':176 ''spake'':10 ''speak'':199 ''subdu'':397 ''superior'':86,102,149,172 ''testament'':317 ''therefor'':105,151,217,289 ''thi'':391 ''thine'':389 ''thou'':119,326 ''time'':132,399 ''translat'':35 ''univers'':381 ''unless'':275 ''unto'':4,209 ''word'':16,34,62 ''would'':144,297,323 ''written'':155 ''yahweh'':17,113', NULL, '588');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('589', '2', '589', NULL, 'Praise ye the Lord - Margin, "Hallelujah." See Psalm 106:1.I will praise the Lord with my whole heart - With undivided affections; holding back nothing. I will allow nothing to be in my heart that would interfere with the fullness of praise; no coldness or dividedness of affection; no love for other things that would deaden my love for God; no suspicion respecting him that would chill my ardor; no unbelief that would drag me down to earth, while the language of my lips ascended to God. See the notes at Psalm 86:12.In the assembly of the upright - With the righteous when they are gathered together for public worship.And in the congregation - See Psalm 22:22, Psalm 22:25; Psalm 66:13; Psalm 89:5.', NULL, NULL, '''1'':10 ''106'':9 ''12.in'':94 ''13'':123 ''22'':116,117,119 ''25'':120 ''5'':126 ''66'':122 ''86'':93 ''89'':125 ''affect'':22,48 ''allow'':28 ''ardor'':69 ''ascend'':85 ''assembl'':96 ''back'':24 ''chill'':67 ''cold'':44 ''congreg'':113 ''deaden'':56 ''divided'':46 ''drag'':74 ''earth'':78 ''full'':40 ''gather'':106 ''god'':60,87 ''hallelujah'':6 ''heart'':19,34 ''hold'':23 ''interfer'':37 ''languag'':81 ''lip'':84 ''lord'':4,15 ''love'':50,58 ''margin'':5 ''note'':90 ''noth'':25,29 ''prais'':1,13,42 ''psalm'':8,92,115,118,121,124 ''public'':109 ''respect'':63 ''righteous'':102 ''see'':7,88,114 ''suspicion'':62 ''thing'':53 ''togeth'':107 ''unbelief'':71 ''undivid'':21 ''upright'':99 ''whole'':18 ''worship.and'':110 ''would'':36,55,66,73 ''ye'':2', NULL, '589');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('590', '2', '590', NULL, 'Praise ye the Lord - Margin, as in Hebrew, "Hallelujah." See the notes at Psalm 106:1.Blessed is the man - Hebrew, "The blessings of the man." See the notes at Psalm 1:1. That is, Blessed, or happy, is such a one.That feareth the Lord - In Psalm 111:10, the psalmist had referred to "the fear of the Lord" as "the beginning of wisdom," and had "alluded" to the success, prosperity, or happiness which attends the fear of the Lord, or true religion. This psalm is designed more fully "to illustrate" that thought.That delighteth greatly in his commandments - See the notes at Psalm 1:2. It is a characteristic of true piety to find pleasure in the commands of God; in the commandments themselves, and in obedience to them.', NULL, NULL, '''1'':31,32,103 ''1.blessed'':16 ''10'':48 ''106'':15 ''111'':47 ''2'':104 ''allud'':66 ''attend'':74 ''begin'':61 ''bless'':22,35 ''characterist'':108 ''command'':97,117,122 ''delighteth'':93 ''design'':86 ''fear'':55,76 ''feareth'':42 ''find'':113 ''fulli'':88 ''god'':119 ''great'':94 ''hallelujah'':9 ''happi'':37,72 ''hebrew'':8,20 ''illustr'':90 ''lord'':4,44,58,79 ''man'':19,25 ''margin'':5 ''note'':12,28,100 ''obedi'':126 ''one.that'':41 ''pieti'':111 ''pleasur'':114 ''prais'':1 ''prosper'':70 ''psalm'':14,30,46,84,102 ''psalmist'':50 ''refer'':52 ''religion'':82 ''see'':10,26,98 ''success'':69 ''thought.that'':92 ''true'':81,110 ''wisdom'':63 ''ye'':2', NULL, '590');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('220', '2', '220', NULL, 'We are not told how soon after the death of Gideon these events happened. There must have been time for the apostacy and establishment of Baal-worship, and for the development of ill-will between Abimelech and his brethren.', NULL, NULL, '''abimelech'':38 ''apostaci'':22 ''baal'':27 ''baal-worship'':26 ''brethren'':41 ''death'':9 ''develop'':32 ''establish'':24 ''event'':13 ''gideon'':11 ''happen'':14 ''ill'':35 ''ill-wil'':34 ''must'':16 ''soon'':6 ''time'':19 ''told'':4 ''worship'':28', NULL, '220');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('593', '2', '593', NULL, 'Not unto us, O Lord, not unto us, but unto thy name give glory - This apparently abrupt commencement of the psalm was undoubtedly in reference to some circumstances which would be well understood at the time when the psalm was composed, but which cannot be definitely ascertained now. It seems to have been in view of some existing troubles, and the language at the same time expresses a hope of the divine interposition, and a feeling that the praise of such interposition would belong wholly to God. The phrase "give glory" means, give all the honor and praise. See the notes at Psalm 29:1-2.For thy mercy - The mercy or the favor which we seek and look for - thy gracious help in the time of trouble.And for thy truth''s sake - Thy faithfulness to thy promises; thy faithfulness to thy people. The psalmist anticipated this manifestation of faithfulness with confidence; he felt that all the praise for such an anticipated interposition would belong to God.', NULL, NULL, '''1-2.for'':105 ''29'':104 ''abrupt'':17 ''anticip'':144,160 ''appar'':16 ''ascertain'':47 ''belong'':84,163 ''cannot'':44 ''circumst'':28 ''commenc'':18 ''compos'':41 ''confid'':150 ''definit'':46 ''divin'':72 ''exist'':58 ''express'':67 ''faith'':133,138,148 ''favor'':112 ''feel'':76 ''felt'':152 ''give'':13,90,93 ''glori'':14,91 ''god'':87,165 ''gracious'':120 ''help'':121 ''honor'':96 ''hope'':69 ''interposit'':73,82,161 ''languag'':62 ''look'':117 ''lord'':5 ''manifest'':146 ''mean'':92 ''merci'':107,109 ''name'':12 ''note'':101 ''o'':4 ''peopl'':141 ''phrase'':89 ''prais'':79,98,156 ''promis'':136 ''psalm'':21,39,103 ''psalmist'':143 ''refer'':25 ''sake'':131 ''see'':99 ''seek'':115 ''seem'':50 ''thi'':11,106,119,128,132,135,137,140 ''time'':36,66,124 ''troubl'':59 ''trouble.and'':126 ''truth'':129 ''understood'':33 ''undoubt'':23 ''unto'':2,7,10 ''us'':3,8 ''view'':55 ''well'':32 ''wholli'':85 ''would'':30,83,162', NULL, '593');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('594', '2', '594', NULL, 'I love the Lord - The Hebrew rather means, "I love, because the Lord hath heard," etc. That is, the psalmist was conscious of love; he felt it glowing in his soul; his heart was full of that special joy, tenderness, kindness, peace, which love produces; and the source or reason of this, he says, was that the Lord had heard him in his prayers.Because he hath heard ... - That is, This fact was a reason for loving him. The psalmist does not say that this was the only reason, or the main reason for loving him, but that it was the reason for that special joy of love which he then felt in his soul. The main reason for loving God is his own excellency of nature; but still there are other reasons for doing it, and among them are the benefits which he has conferred on us, and which awaken the love of gratitude. Compare the notes at 1 John 4:19.', NULL, NULL, '''1'':159 ''19'':162 ''4'':161 ''among'':137 ''awaken'':150 ''benefit'':141 ''compar'':155 ''confer'':145 ''conscious'':22 ''etc'':16 ''excel'':124 ''fact'':71 ''felt'':26,111 ''full'':35 ''glow'':28 ''god'':120 ''gratitud'':154 ''hath'':14,66 ''heard'':15,60,67 ''heart'':33 ''hebrew'':6 ''john'':160 ''joy'':39,105 ''kind'':41 ''lord'':4,13,58 ''love'':2,10,24,44,76,94,107,119,152 ''main'':91,116 ''mean'':8 ''natur'':126 ''note'':157 ''peac'':42 ''prayers.because'':64 ''produc'':45 ''psalmist'':20,79 ''rather'':7 ''reason'':50,74,88,92,101,117,132 ''say'':54,82 ''soul'':31,114 ''sourc'':48 ''special'':38,104 ''still'':128 ''tender'':40 ''us'':147', NULL, '594');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('595', '2', '595', NULL, 'O praise the Lord, all ye nations - The idea is that God has a claim to universal worship, and that all the nations of the earth are under obligations to adore him as the true God. He is not the God of the Hebrew people only, but of all people; his praise should be celebrated not merely by one nation, but by all. This is one of the passages in the Old Testament, anticipating what is more fully disclosed in the New Testament, in which the sacred writer extends his vision beyond the narrow boundaries of Judea, and looks to the world, the whole world, as the theater on which the true religion was to be displayed, and for which it was designed. It is language such as would be indited by the Spirit of inspiration on the supposition that the time would come when the barrier between Jews and Gentiles would be broken down, and when all the nations of the earth would be in the possession of the true religion, and would unite in the worship of the same God. This doctrine, however, was not fully made known until the coming of the Redeemer. The announcement of this was made by the Redeemer himself (compare Matthew 8:11; Matthew 12:21; Matthew 28:19); it was the occasion of no small part of the trouble which the Apostle Paul had with his countrymen (compare Acts 13:46; Acts 18:6; Acts 21:21; Acts 22:21; Acts 26:20, Acts 26:23); it was one of the doctrines which Paul especially endeavored to establish, as a great truth of Christianity, that all the barriers between the nations were to be broken down, and the Gospel proclaimed to all people alike, Romans 3:29; Romans 9:24, Romans 9:30; Romans 11:11; Romans 15:9-11, Romans 15:16, Romans 15:18; Galatians 2:2; Ephesians 2:11-18; Ephesians 3:1-9. It is under the gospel that this language becomes especially appropriate.Praise him, all ye people - People of all lands. The word here rendered "praise" -   shabach - means properly to soothe, to still, to restrain - as, for example, billows Psalm 89:9; and then, to praise, as if to soothe with praises - mulcere laudibus, Pacuv. The idea of soothing or mitigating, however, is not necessarily in the word, but it may be understood in the general sense of praise. We may in fact often soothe or appease people - angry, jealous, suspicious people - by skillful flattery or praise - for there are few, even when under the influence of anger or hatred, who may not thus be approached, or who do not value praise and commendation more than they do the indulgence of passion; but we cannot hope thus to appease the anger of God. We approach him to utter our deep sense of his goodness, and our veneration for his character; we do not expect to turn him from anger to love - to make him forget his justice or our sins - by soothing flattery.', NULL, NULL, '''-11'':308 ''-18'':321 ''-9'':325 ''1'':324 ''11'':210,303,304,320 ''12'':212 ''13'':238 ''15'':306,310,313 ''16'':311 ''18'':241,314 ''19'':216 ''2'':316,317,319 ''20'':251 ''21'':213,244,245,248 ''22'':247 ''23'':254 ''24'':298 ''26'':250,253 ''28'':215 ''29'':295 ''3'':294,323 ''30'':301 ''46'':239 ''6'':242 ''8'':209 ''89'':364 ''9'':297,300,307,365 ''act'':237,240,243,246,249,252 ''ador'':31 ''alik'':292 ''anger'':431,464,492 ''angri'':412 ''announc'':198 ''anticip'':74 ''apostl'':230 ''appeas'':410,462 ''approach'':439,468 ''appropriate.praise'':336 ''barrier'':147,276 ''becom'':334 ''beyond'':92 ''billow'':362 ''boundari'':95 ''broken'':154,283 ''cannot'':458 ''celebr'':55 ''charact'':483 ''christian'':272 ''claim'':15 ''come'':144,193 ''commend'':447 ''compar'':207,236 ''countrymen'':235 ''deep'':473 ''design'':123 ''disclos'':79 ''display'':117 ''doctrin'':184,260 ''earth'':26,163 ''endeavor'':264 ''ephesian'':318,322 ''especi'':263,335 ''establish'':266 ''even'':425 ''exampl'':361 ''expect'':487 ''extend'':89 ''fact'':406 ''flatteri'':418,506 ''forget'':498 ''fulli'':78,188 ''galatian'':315 ''general'':399 ''gentil'':151 ''god'':12,36,41,182,466 ''good'':477 ''gospel'':287,330 ''great'':269 ''hatr'':433 ''hebrew'':44 ''hope'':459 ''howev'':185,385 ''idea'':9,380 ''indit'':131 ''indulg'':453 ''influenc'':429 ''inspir'':136 ''jealous'':413 ''jew'':149 ''judea'':97 ''justic'':500 ''known'':190 ''land'':344 ''languag'':126,333 ''laudibus'':377 ''look'':99 ''lord'':4 ''love'':494 ''made'':189,202 ''make'':496 ''matthew'':208,211,214 ''may'':394,404,435 ''mean'':351 ''mere'':57 ''mitig'':384 ''mulcer'':376 ''narrow'':94 ''nation'':7,23,60,160,279 ''necessarili'':388 ''new'':82 ''o'':1 ''oblig'':29 ''occas'':220 ''often'':407 ''old'':72 ''one'':59,66,257 ''pacuv'':378 ''part'':224 ''passag'':69 ''passion'':455 ''paul'':231,262 ''peopl'':45,50,291,340,341,411,415 ''possess'':168 ''prais'':2,52,349,369,375,402,420,445 ''proclaim'':288 ''proper'':352 ''psalm'':363 ''redeem'':196,205 ''religion'':113,172 ''render'':348 ''restrain'':358 ''roman'':293,296,299,302,305,309,312 ''sacr'':87 ''sens'':400,474 ''shabach'':350 ''sin'':503 ''skill'':417 ''small'':223 ''sooth'':354,373,382,408,505 ''spirit'':134 ''still'':356 ''supposit'':139 ''suspici'':414 ''testament'':73,83 ''theater'':108 ''thus'':437,460 ''time'':142 ''troubl'':227 ''true'':35,112,171 ''truth'':270 ''turn'':489 ''understood'':396 ''unit'':175 ''univers'':17 ''utter'':471 ''valu'':444 ''vener'':480 ''vision'':91 ''whole'':104 ''word'':346,391 ''world'':102,105 ''worship'':18,178 ''would'':129,143,152,164,174 ''writer'':88 ''ye'':6,339', NULL, '595');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('596', '2', '596', NULL, 'O give thanks unto the Lord ... - Let others unite with me in giving thanks to the Lord; let them see, from what has occurred in my case, what occasion there is for praise. Every instance of a particular favor shown to anyone is to others an occasion for praise, inasmuch as it is an illustration of the general character of God. On this verse compare the notes at Psalm 106:1. The language is nearly the same.', NULL, NULL, '''1'':71 ''106'':70 ''anyon'':42 ''case'':27 ''charact'':59 ''compar'':65 ''everi'':34 ''favor'':39 ''general'':58 ''give'':2,13 ''god'':61 ''illustr'':55 ''inasmuch'':50 ''instanc'':35 ''languag'':73 ''let'':7,18 ''lord'':6,17 ''near'':75 ''note'':67 ''o'':1 ''occas'':29,47 ''occur'':24 ''other'':8,45 ''particular'':38 ''prais'':33,49 ''psalm'':69 ''see'':20 ''shown'':40 ''thank'':3,14 ''unit'':9 ''unto'':4 ''vers'':64', NULL, '596');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('602', '2', '602', NULL, 'If it had not been the Lord who was on our side - Unless it was Yahweh who was with us. The idea is, that someone had been with them, and had delivered them, and that such was the nature of the interposition that it could be ascribed to no one but Yahweh. It bore unmistakeable evidence that it was his work. The deliverance was of such a kind that it could have been accomplished by him only. Such things often occur in life, when the intervention in our behalf is so remarkable that we can ascribe it to no one else but God.Now may Israel say - May well and truly say. The danger was so great, their helplessness was so manifest, and the deliverance was so clearly the work of God, that it was proper to say that if this had not occurred, ruin would have been inevitable and entire.', NULL, NULL, '''accomplish'':74 ''ascrib'':47,96 ''behalf'':89 ''bore'':54 ''clear'':127 ''could'':45,71 ''danger'':113 ''deliv'':32 ''deliver'':63,124 ''els'':101 ''entir'':150 ''evid'':56 ''god'':131 ''god.now'':103 ''great'':116 ''helpless'':118 ''idea'':22 ''inevit'':148 ''interposit'':42 ''intervent'':86 ''israel'':105 ''kind'':68 ''life'':83 ''lord'':7 ''manifest'':121 ''may'':104,107 ''natur'':39 ''occur'':81,143 ''often'':80 ''one'':50,100 ''proper'':135 ''remark'':92 ''ruin'':144 ''say'':106,111,137 ''side'':12 ''someon'':25 ''thing'':79 ''truli'':110 ''unless'':13 ''unmistak'':55 ''us'':20 ''well'':108 ''work'':61,129 ''would'':145 ''yahweh'':16,52', NULL, '602');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('597', '2', '597', NULL, 'Blessed are the undefiled in the way - In the way or journey of life; in the path of religion; in the road which leads to heaven. As life - the religious life - is represented under the image of a journey, the expression here is equivalent to saying, "Blessed are those who in the journey of life - in their religious course - are pure, Sincere, uncontaminated." On the word way, see the notes at Psalm 1:6. The margin here on the word undefiled, is perfect, or sincere. So the Hebrew. The word is the same as in Job 1:1, where it is rendered "perfect." See the notes at that passage. The Greek translation is undefiled - &#x3b1;&#x3bc;&#x3c9;&#x3bc;&#x3bf;&#x3b9;  amomoi. So the Latin, "immaculati." Luther renders it, "Who live without blemish" or stain. The idea is, "Blessed are they who are upright, sincere, perfect, in their course." The whole psalm is designed to illustrate this thought, by showing what the influence of a sincere and conscientious attachment to the principles of the law or word of God in the various circumstances of life must be.Who walk in the law of the Lord - Who habitually obey his law. This constitutes sincerity, uprightness, perfection in a man''s life, for the law of the Lord is the only just rule of human conduct.', NULL, NULL, '''1'':73,97,98 ''6'':74 ''amomoi'':115 ''attach'':162 ''be.who'':180 ''blemish'':126 ''bless'':1,47,132 ''circumst'':176 ''conduct'':216 ''conscienti'':161 ''constitut'':194 ''cours'':59,142 ''design'':147 ''equival'':44 ''express'':41 ''god'':172 ''greek'':111 ''habitu'':189 ''heaven'':26 ''hebrew'':88 ''human'':215 ''idea'':130 ''illustr'':149 ''imag'':36 ''immaculati'':119 ''influenc'':156 ''job'':96 ''journey'':12,39,53 ''latin'':118 ''law'':168,184,192,205 ''lead'':24 ''life'':14,28,31,55,178,202 ''live'':124 ''lord'':187,208 ''luther'':120 ''man'':200 ''margin'':76 ''must'':179 ''note'':70,106 ''obey'':190 ''passag'':109 ''path'':17 ''perfect'':83,103,139,197 ''principl'':165 ''psalm'':72,145 ''pure'':61 ''religi'':30,58 ''religion'':19 ''render'':102,121 ''repres'':33 ''road'':22 ''rule'':213 ''say'':46 ''see'':68,104 ''show'':153 ''sincer'':62,85,138,159,195 ''stain'':128 ''thought'':151 ''translat'':112 ''uncontamin'':63 ''undefil'':4,81,114 ''upright'':137,196 ''various'':175 ''walk'':181 ''way'':7,10,67 ''whole'':144 ''without'':125 ''word'':66,80,90,170', NULL, '597');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('598', '2', '598', NULL, 'In my distress - In my suffering, as arising from slander, Psalm 120:2-3. There are few forms of suffering more keen than those caused by slander:"Whose edge is sharper than the sword; whose tongueOutvenoms all the worms of Nile; whose breathRides on the posting winds, and doth belieAll corners of the world: kings, queens, and states,Maids, matrons, nay, the secrets of the graveThis viperous slander enters."Cymbeline, iii.4.It is one of those things which a man cannot guard against; which he cannot repel by force; whose origin he cannot always trace; which will go where a vindication will not follow; whose effects will live long after the slander is refuted; which will adhere to a man, or leave a trait of suspicion, even after the most successful vindication, for the effect will be to make a second slander more easily credited than the first was.I cried unto the Lord, and he heard me - I had no other resource. I could not meet the slander. I could not refute it. I could not prevent its effects on my reputation, and all that I could do was to commit the case to the Lord. See the notes at Psalm 37:5-6.', NULL, NULL, '''-3'':14 ''-6'':203 ''120'':12 ''2'':13 ''37'':201 ''5'':202 ''adher'':116 ''alway'':93 ''aris'':8 ''belieal'':50 ''breathrid'':43 ''cannot'':80,85,92 ''case'':192 ''caus'':25 ''commit'':190 ''corner'':51 ''could'':163,169,174,186 ''credit'':144 ''cri'':149 ''cymbelin'':70 ''distress'':3 ''doth'':49 ''easili'':143 ''edg'':29 ''effect'':105,134,178 ''enter'':69 ''even'':126 ''first'':147 ''follow'':103 ''forc'':88 ''form'':18 ''go'':97 ''gravethi'':66 ''guard'':81 ''heard'':155 ''iii.4.it'':71 ''keen'':22 ''king'':55 ''leav'':121 ''live'':107 ''long'':108 ''lord'':152,195 ''maid'':59 ''make'':138 ''man'':79,119 ''matron'':60 ''meet'':165 ''nay'':61 ''nile'':41 ''note'':198 ''one'':73 ''origin'':90 ''post'':46 ''prevent'':176 ''psalm'':11,200 ''queen'':56 ''refut'':113,171 ''repel'':86 ''reput'':181 ''resourc'':161 ''second'':140 ''secret'':63 ''see'':196 ''sharper'':31 ''slander'':10,27,68,111,141,167 ''state'':58 ''success'':130 ''suffer'':6,20 ''suspicion'':125 ''sword'':34 ''thing'':76 ''tongueoutvenom'':36 ''trace'':94 ''trait'':123 ''unto'':150 ''vindic'':100,131 ''viper'':67 ''was.i'':148 ''whose'':28,35,42,89,104 ''wind'':47 ''world'':54 ''worm'':39', NULL, '598');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('599', '2', '599', NULL, 'I will lift up mine eyes - Margin, "Shall I lift up mine eyes to the hills? Whence should my help come?" The expression would properly denote a condition where there was danger; when no help or aid was visible; and when the eyes were turned to the quarter from which help might be expected to come. What the danger was cannot now be ascertained.Unto the hills - Hebrew, the mountains. To the quarter from where I look for assistance. This (as has been shown in the Introduction) may refer(1) to the mountains from where one in danger expected help; or(2) to heaven, considered as high, and as the abode of God; or(3) to the hills on which Jerusalem was built, as the place where God dwelt, and from where aid was expected.The third of these is the most probable. The first would be applicable to a state of war only, and the second is forced and unnatural. Adopting the third interpretation, the language is natural, and makes it proper to be used at all times, since it indicates a proper looking to God as he manifests himself to people, particularly in the church.From whence cometh my help - A more literal rendering would be, "Whence cometh my help?" This accords best with the usage of the Hebrew word, and agrees well with the connection. It indicates a troubled and anxious state of mind - a mind that asks, Where shall I look for help? The answer is found in the following verse.', NULL, NULL, '''1'':89 ''2'':101 ''3'':114 ''abod'':110 ''accord'':211 ''adopt'':160 ''agre'':221 ''aid'':37,132 ''answer'':246 ''anxious'':231 ''applic'':146 ''ascertained.unto'':64 ''ask'':238 ''assist'':78 ''best'':212 ''built'':122 ''cannot'':61 ''church.from'':195 ''come'':21,56 ''cometh'':197,207 ''condit'':28 ''connect'':225 ''consid'':104 ''danger'':32,59,97 ''denot'':26 ''dwelt'':128 ''expect'':54,98 ''expected.the'':134 ''express'':23 ''eye'':6,13,43 ''first'':143 ''follow'':251 ''forc'':157 ''found'':248 ''god'':112,127,185 ''heaven'':103 ''hebrew'':67,218 ''help'':20,35,51,99,199,209,244 ''high'':106 ''hill'':16,66,117 ''indic'':180,227 ''interpret'':163 ''introduct'':86 ''jerusalem'':120 ''languag'':165 ''lift'':3,10 ''liter'':202 ''look'':76,183,242 ''make'':169 ''manifest'':188 ''margin'':7 ''may'':87 ''might'':52 ''mind'':234,236 ''mine'':5,12 ''mountain'':69,92 ''natur'':167 ''one'':95 ''particular'':192 ''peopl'':191 ''place'':125 ''probabl'':141 ''proper'':25,171,182 ''quarter'':48,72 ''refer'':88 ''render'':203 ''second'':155 ''shall'':8,240 ''shown'':83 ''sinc'':178 ''state'':149,232 ''third'':135,162 ''time'':177 ''troubl'':229 ''turn'':45 ''unnatur'':159 ''usag'':215 ''use'':174 ''vers'':252 ''visibl'':39 ''war'':151 ''well'':222 ''whenc'':17,196,206 ''word'':219 ''would'':24,144,204', NULL, '599');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('600', '2', '600', NULL, 'I was glad - It was a subject; of joy to me. The return of the happy season when we were to go up to worship filled me with joy. The language is expressive of the, happiness which is felt by those who love God and his sanctuary, when the stated season of worship returns. The heart is drawn to the house of prayer; the soul is filled with peace at the prospect of being again permitted to worship God. Who the speaker here is, is not known. It may have been David himself; more probably, however, it was designed by him to be used by those who should go up to worship, as expressive of their individual joy.When they said unto me - When it was said unto me. When the time arrived. When I was invited by others to go. The announcement was joyful; the invitation was welcome. It met the desires of my heart, and I embraced the invitation cheerfully and joyfully.Let us go into the house of the Lord - Up to the place where God dwells; the house which he has made his abode. If the psalm was composed in the time of David, this would refer to the tabernacle as fixed by him on Mount Zion; if at a later period, to the temple. The language will admit of either interpretation. Compare the notes at Isaiah 2:3.', NULL, NULL, '''2'':230 ''3'':231 ''abod'':186 ''admit'':221 ''announc'':142 ''arriv'':132 ''cheer'':161 ''compar'':225 ''compos'':191 ''david'':92,196 ''design'':99 ''desir'':152 ''drawn'':58 ''dwell'':178 ''either'':223 ''embrac'':158 ''express'':33,114 ''felt'':39 ''fill'':26,67 ''fix'':204 ''glad'':3 ''go'':22,109,140,165 ''god'':44,79,177 ''happi'':16,36 ''heart'':56,155 ''hous'':61,168,180 ''howev'':96 ''individu'':117 ''interpret'':224 ''invit'':136,146,160 ''isaiah'':229 ''joy'':9,29,144 ''joy.when'':118 ''joyfully.let'':163 ''known'':87 ''languag'':31,219 ''later'':213 ''lord'':171 ''love'':43 ''made'':184 ''may'':89 ''met'':150 ''mount'':208 ''note'':227 ''other'':138 ''peac'':69 ''period'':214 ''permit'':76 ''place'':175 ''prayer'':63 ''probabl'':95 ''prospect'':72 ''psalm'':189 ''refer'':199 ''return'':13,54 ''said'':120,126 ''sanctuari'':47 ''season'':17,51 ''soul'':65 ''speaker'':82 ''state'':50 ''subject'':7 ''tabernacl'':202 ''templ'':217 ''time'':131,194 ''unto'':121,127 ''us'':164 ''use'':104 ''welcom'':148 ''worship'':25,53,78,112 ''would'':198 ''zion'':209', NULL, '600');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('601', '2', '601', NULL, 'Unto thee - To God.Lift I up mine eyes - In supplication and prayer. Nature prompts us to look up when we address God, as if he dwelt above us. It is the natural prompting of the heart that he must be the most exalted of all beings, dwelling above all. See Psalm 121:1.O thou that dwellest in the heavens - Whose home - whose special home - is in heaven - above the sky. This is in accordance with the common feelings of people, and the common description of God in the Bible, though it is true also that God is everywhere. Compare Psalm 2:4; Psalm 11:4.', NULL, NULL, '''1'':53 ''11'':105 ''121'':52 ''2'':102 ''4'':103,106 ''accord'':75 ''address'':21 ''also'':95 ''be'':46 ''bibl'':90 ''common'':78,84 ''compar'':100 ''descript'':85 ''dwell'':47 ''dwellest'':57 ''dwelt'':26 ''everywher'':99 ''exalt'':43 ''eye'':8 ''feel'':79 ''god'':22,87,97 ''god.lift'':4 ''heart'':36 ''heaven'':60,68 ''home'':62,65 ''look'':17 ''mine'':7 ''must'':39 ''natur'':13,32 ''o'':54 ''peopl'':81 ''prayer'':12 ''prompt'':14,33 ''psalm'':51,101,104 ''see'':50 ''sky'':71 ''special'':64 ''supplic'':10 ''thee'':2 ''thou'':55 ''though'':91 ''true'':94 ''unto'':1 ''us'':15,28 ''whose'':61,63', NULL, '601');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('769', '2', '769', NULL, 'Omit "were." "Set before," i. e put in the appointed place for offerings of firstfruits in the forecourt of the temple.Carpenters - "Craftsmen" (see the marginal reference).', NULL, NULL, '''appoint'':10 ''craftsmen'':22 ''e'':6 ''firstfruit'':15 ''forecourt'':18 ''margin'':25 ''offer'':13 ''omit'':1 ''place'':11 ''put'':7 ''refer'':26 ''see'':23 ''set'':3 ''temple.carpenters'':21', NULL, '769');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('61', '2', '61', NULL, 'The Lord said - Or "the Lord had said." The first three verses of this chapter are parenthetical. Before Moses relates the last warning given to Pharaoh, he feels it right to recall to his readers'' minds the revelation and command which had been previously given to him by the Lord.When he shall let you go ... - When at last he lets you depart with children, flocks, herds, and all your possessions, he will compel you to depart in haste. Moses was already aware that the last plague would be followed by an immediate departure, and, therefore, measures had probably been taken to prepare the Israelites for the journey. In fact, on each occasion when Pharaoh relented for a season, immediate orders would of course be issued by Moses to the heads of the people, who were thus repeatedly brought into a state of more or less complete organization for the final movement.', NULL, NULL, '''alreadi'':81 ''awar'':82 ''brought'':138 ''chapter'':15 ''children'':64 ''command'':40 ''compel'':73 ''complet'':146 ''cours'':123 ''depart'':62,76 ''departur'':93 ''fact'':109 ''feel'':28 ''final'':150 ''first'':10 ''flock'':65 ''follow'':89 ''given'':24,45 ''go'':55 ''hast'':78 ''head'':130 ''herd'':66 ''immedi'':92,119 ''israelit'':104 ''issu'':125 ''journey'':107 ''last'':22,58,85 ''less'':145 ''let'':53,60 ''lord'':2,6 ''lord.when'':50 ''measur'':96 ''mind'':36 ''mose'':19,79,127 ''movement'':151 ''occas'':112 ''order'':120 ''organ'':147 ''parenthet'':17 ''peopl'':133 ''pharaoh'':26,114 ''plagu'':86 ''possess'':70 ''prepar'':102 ''previous'':44 ''probabl'':98 ''reader'':35 ''recal'':32 ''relat'':20 ''relent'':115 ''repeat'':137 ''revel'':38 ''right'':30 ''said'':3,8 ''season'':118 ''shall'':52 ''state'':141 ''taken'':100 ''therefor'':95 ''three'':11 ''thus'':136 ''vers'':12 ''warn'':23 ''would'':87,121', NULL, '61');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('62', '2', '62', NULL, 'This chapter was written some time after the Exodus, probably when Moses put together the portions of the book toward the end of his life. The statements that these instructions were given in the land of Egypt, and that they were given to Moses and Aaron, are important: the one marks the special dignity of this ordinance, which was established before the Sinaitic code; the other marks the distinction between Moses and Aaron and all other prophets. They alone were prophets of the law, i. e. no law was promulgated by any other prophets.', NULL, NULL, '''aaron'':46,73 ''alon'':79 ''book'':19 ''chapter'':2 ''code'':64 ''digniti'':54 ''distinct'':69 ''e'':86 ''egypt'':37 ''end'':22 ''establish'':60 ''exodus'':9 ''given'':32,42 ''import'':48 ''instruct'':30 ''land'':35 ''law'':84,88 ''life'':25 ''mark'':51,67 ''mose'':12,44,71 ''one'':50 ''ordin'':57 ''portion'':16 ''probabl'':10 ''promulg'':90 ''prophet'':77,81,94 ''put'':13 ''sinait'':63 ''special'':53 ''statement'':27 ''time'':6 ''togeth'':14 ''toward'':20 ''written'':4', NULL, '62');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('63', '2', '63', NULL, 'Sanctify unto me - The command is addressed to Moses. It was to declare the will of God that all firstborn were to be consecrated to Him, set apart from all other creatures. The command is expressly based upon the Passover. The firstborn exempt from the destruction became in a new and special sense the exclusive property of the Lord: the firstborn of man as His ministers, the firstborn of cattle as victims. In lieu of the firstborn of men the Levites were devoted to the temple services.', NULL, NULL, '''address'':7 ''apart'':28 ''base'':37 ''becam'':47 ''cattl'':70 ''command'':5,34 ''consecr'':24 ''creatur'':32 ''declar'':13 ''destruct'':46 ''devot'':83 ''exclus'':55 ''exempt'':43 ''expressli'':36 ''firstborn'':20,42,61,68,77 ''god'':17 ''levit'':81 ''lieu'':74 ''lord'':59 ''man'':63 ''men'':79 ''minist'':66 ''mose'':9 ''new'':50 ''passov'':40 ''properti'':56 ''sanctifi'':1 ''sens'':53 ''servic'':87 ''set'':27 ''special'':52 ''templ'':86 ''unto'':2 ''upon'':38 ''victim'':72', NULL, '63');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('64', '2', '64', NULL, 'That they turn - i. e. away from the wilderness, and go southwards, to the west of the Bitter Lakes, which completely separated them from the desert.Pi-hahiroth - The place is generally identified with Ajrud, a fortress with a very large well of good water, situated at the foot of an elevation commanding the plain which extends to Suez, at a distance of four leagues. The journey from Etham might occupy two, or even three days.Migdol - A tower, or fort, the "Maktal" of Egyptian monuments; it is probably to be identified with Bir Suweis, about two miles from Suez.Baal-zephon - The name under which the Phoenicians, who had a settlement in Lower Egypt at a very ancient period, worshipped their chief Deity. There can be no doubt it was near Kolsum, or Suez. From the text it is clear that the encampment of the Israelites extended over the plain from Pi-hahiroth: their headquarters being between Bir Suweis and the sea opposite to Baal-Zephon. At Ajrud the road branches off in two directions, one leading to the wilderness by a tract, now dry, but in the time of Moses probably impassable (see next note); the other leading to Suez, which was doubtless followed by the Israelites.', NULL, NULL, '''ajrud'':34,168 ''ancient'':116 ''away'':6 ''baal'':165 ''baal-zephon'':164 ''bir'':92,157 ''bitter'':18 ''branch'':171 ''chief'':120 ''clear'':138 ''command'':52 ''complet'':21 ''days.migdol'':75 ''deiti'':121 ''desert.pi'':26 ''direct'':175 ''distanc'':61 ''doubt'':126 ''doubtless'':204 ''dri'':185 ''e'':5 ''egypt'':112 ''egyptian'':83 ''elev'':51 ''encamp'':141 ''etham'':68 ''even'':73 ''extend'':56,145 ''follow'':205 ''foot'':48 ''fort'':79 ''fortress'':36 ''four'':63 ''general'':31 ''go'':11 ''good'':43 ''hahiroth'':27,152 ''headquart'':154 ''identifi'':32,90 ''impass'':193 ''israelit'':144,208 ''journey'':66 ''kolsum'':130 ''lake'':19 ''larg'':40 ''lead'':177,199 ''leagu'':64 ''lower'':111 ''maktal'':81 ''might'':69 ''mile'':96 ''monument'':84 ''mose'':191 ''name'':101 ''near'':129 ''next'':195 ''note'':196 ''occupi'':70 ''one'':176 ''opposit'':162 ''period'':117 ''phoenician'':105 ''pi'':151 ''pi-hahiroth'':150 ''place'':29 ''plain'':54,148 ''probabl'':87,192 ''road'':170 ''sea'':161 ''see'':194 ''separ'':22 ''settlement'':109 ''situat'':45 ''southward'':12 ''suez'':58,132,201 ''suez.baal'':98 ''suwei'':93,158 ''text'':135 ''three'':74 ''time'':189 ''tower'':77 ''tract'':183 ''turn'':3 ''two'':71,95,174 ''water'':44 ''well'':41 ''west'':15 ''wilder'':9,180 ''worship'':118 ''zephon'':99,166', NULL, '64');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('65', '2', '65', NULL, 'With the deliverance of Israel is associated the development of the national poetry, which finds its first and perfect expression in this magnificent hymn. It was sung by Moses and the people, an expression which evidently points to him as the author. That it was written at the time is an assertion expressly made in the text, and it is supported by the strongest internal evidence. In every age this song gave the tone to the poetry of Israel; especially at great critical epochs of deliverance: and in the book of Revelation Exo 15:3 it is associated with the final triumph of the Church.The division of the song into three parts is distinctly marked: Exodus 15:1-5; Exodus 15:6-10; Exodus 15:11-18 : each begins with an ascription of praise to God; each increases in length and varied imagery unto the triumphant close.Exodus 15:1He hath triumphed gloriously - Literally, He is gloriously glorious.The horse and his rider - The word "rider" may include horseman, but applies properly to the charioteer.', NULL, NULL, '''-10'':123 ''-18'':127 ''-5'':119 ''1'':118 ''11'':126 ''15'':94,117,121,125,148 ''1he'':149 ''3'':95 ''6'':122 ''age'':69 ''appli'':169 ''ascript'':132 ''assert'':52 ''associ'':7,98 ''author'':42 ''begin'':129 ''book'':90 ''chariot'':173 ''church.the'':105 ''close.exodus'':147 ''critic'':83 ''deliver'':3,86 ''develop'':9 ''distinct'':114 ''divis'':106 ''epoch'':84 ''especi'':80 ''everi'':68 ''evid'':36,66 ''exo'':93 ''exodus'':116,120,124 ''express'':20,34 ''expressli'':53 ''final'':101 ''find'':15 ''first'':17 ''gave'':72 ''glorious'':152,156 ''glorious.the'':157 ''god'':136 ''great'':82 ''hath'':150 ''hors'':158 ''horseman'':167 ''hymn'':24 ''imageri'':143 ''includ'':166 ''increas'':138 ''intern'':65 ''israel'':5,79 ''length'':140 ''liter'':153 ''made'':54 ''magnific'':23 ''mark'':115 ''may'':165 ''mose'':29 ''nation'':12 ''part'':112 ''peopl'':32 ''perfect'':19 ''poetri'':13,77 ''point'':37 ''prais'':134 ''proper'':170 ''revel'':92 ''rider'':161,164 ''song'':71,109 ''strongest'':64 ''sung'':27 ''support'':61 ''text'':57 ''three'':111 ''time'':49 ''tone'':74 ''triumph'':102,151 ''triumphant'':146 ''unto'':144 ''vari'':142 ''word'':163 ''written'':46', NULL, '65');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('66', '2', '66', NULL, 'The the wilderness of Sin - The desert tract, called Debbet er Ramleh, extend nearly across the peninsula from the Wady Nasb in a south-easterly direction, between the limestone district of Et Tih and the granite of Sinai. The journey from the station at Elim, or even from that on the Red Sea, could be performed in a day: at that time the route was kept in good condition by the Egyptians.', NULL, NULL, '''across'':15 ''call'':9 ''condit'':70 ''could'':55 ''day'':60 ''debbet'':10 ''desert'':7 ''direct'':27 ''district'':31 ''easter'':26 ''egyptian'':73 ''elim'':46 ''er'':11 ''et'':33 ''even'':48 ''extend'':13 ''good'':69 ''granit'':37 ''journey'':41 ''kept'':67 ''limeston'':30 ''nasb'':21 ''near'':14 ''peninsula'':17 ''perform'':57 ''ramleh'':12 ''red'':53 ''rout'':65 ''sea'':54 ''sin'':5 ''sinai'':39 ''south'':25 ''south-east'':24 ''station'':44 ''tih'':34 ''time'':63 ''tract'':8 ''wadi'':20 ''wilder'':3', NULL, '66');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('770', '2', '770', NULL, 'The fourth year - See Daniel 1:1 note. This invasion of Judaea, in which Daniel was carried captive to Babylon, was according to the date of the years the fourth, but according to the actual time the third, year of the Jewish king. Nebuchadnezzar was not yet fully king, but associated with his father Nabopalassar.', NULL, NULL, '''1'':6,7 ''accord'':22,32 ''actual'':35 ''associ'':51 ''babylon'':20 ''captiv'':18 ''carri'':17 ''daniel'':5,15 ''date'':25 ''father'':54 ''fourth'':2,30 ''fulli'':48 ''invas'':10 ''jewish'':42 ''judaea'':12 ''king'':43,49 ''nabopalassar'':55 ''nebuchadnezzar'':44 ''note'':8 ''see'':4 ''third'':38 ''time'':36 ''year'':3,28,39 ''yet'':47', NULL, '770');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('70', '2', '70', NULL, 'The Hebrew name which is rendered in our King James Version as the ten commandments occurs in Exodus 34:28; Deuteronomy 4:13; Deuteronomy 10:4. It literally means "the Ten Words." The Ten Commandments are also called the law, even the commandment Exodus 24:12, the words of the covenant Exodus 34:28, the tables of the covenant Deuteronomy 9:9, the covenant Deuteronomy 4:13, the two tables Deuteronomy 9:10, Deuteronomy 9:17, and, most frequently, the testimony (e. g. Exodus 16:34; Exodus 25:16), or the two tables of the testimony (e. g. Exodus 31:18). In the New Testament they are called simply the commandments (e. g. Matthew 19:17). The name decalogue is found first in Clement of Alexandria, and was commonly used by the Fathers who followed him.Thus we know that the tables were two, and that the commandments were ten, in number. But the Scriptures do not, by any direct statements, enable us to determine with precision how the Ten Commandments are severally to be made out, nor how they are to be allotted to the Two tables. On each of these points various opinions have been held (see Exodus 20:12).Of the Words of Yahweh engraven on the tables of Stone, we have two distinct statements, one in Exodus Exo. 20:1-17 and one in Deuteronomy Deu 5:7-21, apparently of equal authority, but differing principally from each other in the fourth, the fifth, and the tenth commandments.It has been supposed that the original commandments were all in the same terse and simple form of expression as appears (both in Exodus and Deuteronomy) in the first, sixth, seventh, eighth, and ninth, such as would be most suitable for recollection, and that the passages in each copy in which the most important variations are found were comments added when the books were written.The account of the delivery of them in Exodus 19 and in Exodus 20:18-21 is in accordance with their importance as the recognized basis of the covenant between Yahweh and His ancient people (Exodus 34:27-28; Deuteronomy 4:13; 1 Kings 8:21, etc.), and as the divine testimony against the sinful tendencies in man for all ages. While it is here said that "God spake all these words," and in Deuteronomy 5:4, that He "talked face to face," in the New Testament the giving of the law is spoken of as having been through the ministration of Angels Acts 7:53; Galatians 3:19; Hebrews 2:2. We can reconcile these contrasts of language by keeping in mind that God is a Spirit, and that He is essentially present in the agents who are performing His will.', NULL, NULL, '''-17'':224 ''-21'':232,330 ''-28'':353 ''1'':223,357 ''10'':25,73 ''12'':46,201 ''13'':23,67,356 ''16'':85,89 ''17'':76,116 ''18'':101,329 ''19'':115,324,423 ''2'':425,426 ''20'':200,222,328 ''21'':360 ''24'':45 ''25'':88 ''27'':352 ''28'':20,54 ''3'':422 ''31'':100 ''34'':19,53,86,351 ''4'':22,26,66,355,391 ''5'':230,390 ''53'':420 ''7'':231,419 ''8'':359 ''9'':61,62,72,75 ''accord'':333 ''account'':316 ''act'':418 ''add'':310 ''age'':375 ''agent'':451 ''alexandria'':126 ''allot'':183 ''also'':37 ''ancient'':348 ''angel'':417 ''appar'':233 ''appear'':271 ''author'':236 ''basi'':340 ''book'':313 ''call'':38,108 ''clement'':124 ''command'':15,35,43,111,147,170,258 ''commandments.it'':251 ''comment'':309 ''common'':129 ''contrast'':431 ''copi'':299 ''coven'':51,59,64,343 ''decalogu'':119 ''deliveri'':319 ''determin'':164 ''deu'':229 ''deuteronomi'':21,24,60,65,71,74,228,276,354,389 ''differ'':238 ''direct'':159 ''distinct'':216 ''divin'':365 ''e'':82,97,112 ''eighth'':282 ''enabl'':161 ''engraven'':207 ''equal'':235 ''essenti'':447 ''etc'':361 ''even'':41 ''exo'':221 ''exodus'':18,44,52,84,87,99,199,220,274,323,327,350 ''express'':269 ''face'':395,397 ''father'':133 ''fifth'':247 ''first'':122,279 ''follow'':135 ''form'':267 ''found'':121,307 ''fourth'':245 ''frequent'':79 ''g'':83,98,113 ''galatian'':421 ''give'':403 ''god'':382,439 ''hebrew'':2,424 ''held'':197 ''him.thus'':136 ''import'':304,336 ''jame'':10 ''keep'':435 ''king'':9,358 ''know'':138 ''languag'':433 ''law'':40,406 ''liter'':28 ''made'':175 ''man'':372 ''matthew'':114 ''mean'':29 ''mind'':437 ''ministr'':415 ''name'':3,118 ''new'':104,400 ''ninth'':284 ''number'':151 ''occur'':16 ''one'':218,226 ''opinion'':194 ''origin'':257 ''passag'':296 ''peopl'':349 ''perform'':454 ''point'':192 ''precis'':166 ''present'':448 ''princip'':239 ''recogn'':339 ''recollect'':292 ''reconcil'':429 ''render'':6 ''said'':380 ''scriptur'':154 ''see'':198 ''seventh'':281 ''sever'':172 ''simpl'':266 ''simpli'':109 ''sin'':369 ''sixth'':280 ''spake'':383 ''spirit'':442 ''spoken'':408 ''statement'':160,217 ''stone'':212 ''suitabl'':290 ''suppos'':254 ''tabl'':56,70,93,141,187,210 ''talk'':394 ''ten'':14,31,34,149,169 ''tendenc'':370 ''tenth'':250 ''ters'':264 ''testament'':105,401 ''testimoni'':81,96,366 ''two'':69,92,143,186,215 ''us'':162 ''use'':130 ''variat'':305 ''various'':193 ''version'':11 ''word'':32,48,204,386 ''would'':287 ''written.the'':315 ''yahweh'':206,345', NULL, '70');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('71', '2', '71', NULL, 'A Hebrew might be sold as a bondman in consequence either of debt Leviticus 25:39 or of the commission of theft Exodus 22:3. But his servitude could not be enforced for more than six full years. Compare the marginal references.', NULL, NULL, '''22'':24 ''25'':15 ''3'':25 ''39'':16 ''bondman'':8 ''commiss'':20 ''compar'':39 ''consequ'':10 ''could'':29 ''debt'':13 ''either'':11 ''enforc'':32 ''exodus'':23 ''full'':37 ''hebrew'':2 ''leviticus'':14 ''margin'':41 ''might'':3 ''refer'':42 ''servitud'':28 ''six'':36 ''sold'':5 ''theft'':22 ''year'':38', NULL, '71');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('72', '2', '72', NULL, 'The theft of an ox appears to have been regarded as a greater crime than the theft of a sheep, because it showed a stronger purpose in wickedness to take the larger and more powerful animal. It may have been on similar moral ground that the thief, when he had proved his persistency in crime by adding to his theft the slaughter, or sale, of the animal, was to restore four times its value in the case of a sheep (compare the marginal references), and five times its value in the case of an ox; but if the animal was still in his possession alive (see Exodus 22:4) he had to make only twofold restitution.', NULL, NULL, '''22'':108 ''4'':109 ''add'':57 ''aliv'':105 ''anim'':36,67,99 ''appear'':6 ''case'':77,92 ''compar'':81 ''crime'':14,55 ''exodus'':107 ''five'':86 ''four'':71 ''greater'':13 ''ground'':44 ''larger'':32 ''make'':113 ''margin'':83 ''may'':38 ''moral'':43 ''ox'':5,95 ''persist'':53 ''possess'':104 ''power'':35 ''prove'':51 ''purpos'':26 ''refer'':84 ''regard'':10 ''restitut'':116 ''restor'':70 ''sale'':64 ''see'':106 ''sheep'':20,80 ''show'':23 ''similar'':42 ''slaughter'':62 ''still'':101 ''stronger'':25 ''take'':30 ''theft'':2,17,60 ''thief'':47 ''time'':72,87 ''twofold'':115 ''valu'':74,89 ''wicked'':28', NULL, '72');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('73', '2', '73', NULL, 'These four commands, addressed to the conscience, are illustrations of the ninth commandment, mainly in reference to the giving of evidence in legal causes. Compare 1 Kings 21:10; Acts 6:11.', NULL, NULL, '''1'':26 ''10'':29 ''11'':32 ''21'':28 ''6'':31 ''act'':30 ''address'':4 ''caus'':24 ''command'':3,13 ''compar'':25 ''conscienc'':7 ''evid'':21 ''four'':2 ''give'':19 ''illustr'':9 ''king'':27 ''legal'':23 ''main'':14 ''ninth'':12 ''refer'':16', NULL, '73');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('74', '2', '74', NULL, 'Twelve pillars - As the altar was a symbol of the presence of Yahweh, so these twelve pillars represented the presence of the Twelve tribes with whom He was making the covenant.', NULL, NULL, '''altar'':5 ''coven'':31 ''make'':29 ''pillar'':2,17 ''presenc'':11,20 ''repres'':18 ''symbol'':8 ''tribe'':24 ''twelv'':1,16,23 ''yahweh'':13', NULL, '74');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('75', '2', '75', NULL, 'Yahweh had redeemed the Israelites from bondage. He had made a covenant with them and had given them laws. He had promised, on condition of their obedience, to accept them as His own "peculiar treasure," as "a kingdom of priests and an holy nation" Exodus 19:5-6. And now He was ready visibly to testify that He made his abode with them. He claimed to have a dwelling for Himself, which was to be in external form a tent of goats'' hair Exodus 19:4, to take its place among their own tents, and formed out of the same material (see Exodus 26:7 note). The special mark of His presence within the tent was to be the ark or chest containing the Ten Commandments on two tables of stone Exodus 31:18, symbolizing the divine law of holiness, and covered by the mercy-seat, the type of reconciliation. Moses was divinely taught regarding the construction and arrangement of every part of the sanctuary. The directions which were given him are comprised in Exodus 25:1-31:11. The account of the performance of the work, expressed generally in the same terms, is given Exodus 35:21-40:33.Moses is commanded to invite the people to bring their gifts for the construction and service of the sanctuary and for the dresses of the priests.', NULL, NULL, '''-31'':179 ''-40'':200 ''-6'':48 ''1'':178 ''11'':180 ''18'':134 ''19'':46,85 ''21'':199 ''25'':177 ''26'':104 ''31'':133 ''33.moses'':201 ''35'':198 ''4'':86 ''5'':47 ''7'':105 ''abod'':61 ''accept'':29 ''account'':182 ''among'':91 ''ark'':120 ''arrang'':160 ''bondag'':7 ''bring'':209 ''chest'':122 ''claim'':65 ''command'':126,203 ''compris'':174 ''condit'':24 ''construct'':158,214 ''contain'':123 ''coven'':12 ''cover'':142 ''direct'':168 ''divin'':137,154 ''dress'':223 ''dwell'':69 ''everi'':162 ''exodus'':45,84,103,132,176,197 ''express'':189 ''extern'':77 ''form'':78,96 ''general'':190 ''gift'':211 ''given'':17,171,196 ''goat'':82 ''hair'':83 ''holi'':43,140 ''invit'':205 ''israelit'':5 ''kingdom'':38 ''law'':19,138 ''made'':10,59 ''mark'':109 ''materi'':101 ''merci'':146 ''mercy-seat'':145 ''mose'':152 ''nation'':44 ''note'':106 ''obedi'':27 ''part'':163 ''peculiar'':34 ''peopl'':207 ''perform'':185 ''place'':90 ''presenc'':112 ''priest'':40,226 ''promis'':22 ''readi'':53 ''reconcili'':151 ''redeem'':3 ''regard'':156 ''sanctuari'':166,219 ''seat'':147 ''see'':102 ''servic'':216 ''special'':108 ''stone'':131 ''symbol'':135 ''tabl'':129 ''take'':88 ''taught'':155 ''ten'':125 ''tent'':80,94,115 ''term'':194 ''testifi'':56 ''treasur'':35 ''two'':128 ''type'':149 ''visibl'':54 ''within'':113 ''work'':188 ''yahweh'':1', NULL, '75');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('76', '2', '76', NULL, '(Compare Exodus 36:8-33.) The tabernacle was to comprise three main parts, the tabernacle Exodus 26:1-6, more strictly so-called, its tent Exodus 26:7-13, and its covering Exodus 26:14 (Compare Exodus 35:11; Exodus 39:33-34; Exodus 40:19, Exodus 40:34; Numbers 3:25, etc.). These parts are very clearly distinguished in the Hebrew, but they are confounded in many places of the English Version (see Exodus 26:7, Exodus 26:9, etc.). The tabernacle itself was to consist of curtains of fine linen woven with colored figures of cherubim, and a structure of boards which was to contain the holy place and the most holy place; the tent was to be a true tent of goats'' hair cloth to contain and shelter the tabernacle: the covering was to be of red rams'' skins and "tachash" skins Exodus 25:5, and was spread over the goats'' hair tent as an additional protection against the weather. On the external form of the tabernacle and the arrangement of its parts, see cuts at the end of the chapter.Exodus 26:1The tabernacle - The   mshkan, i. e. the dwelling-place; the definite article regularly accompanies the Hebrew word when the dwelling-place of Yahweh is denoted. But in this place the word is not used in its full sense as denoting the dwelling-place of Yahweh: it denotes only the tabernacle-cloth Exodus 26:6. The word is, in fact, employed with three distinct ranges of meaning,(1) in its strict sense, comprising the cloth of the tabernacle with its woodwork (Exodus 25:9; Exodus 26:30; Exodus 36:13; Exodus 40:18, etc.);(2) in a narrower sense, for the tabernacle-cloth only (Exodus 26:1, Exodus 26:6; Exodus 35:11; Exodus 39:33-34, etc.);(3) in a wider sense, for the tabernacle with its tent and covering (Exodus 27:19; Exodus 35:18, etc.).With ten curtains - Rather, of ten breadths. Five of these breadths were united so as to form what, in common usage, we should call a large curtain Exodus 26:3. The two curtains thus formed were coupled together by the loops and taches to make the entire tabernacle-cloth Exodus 26:6.Of cunning work - More properly, of the work of the skilled weaver. The colored figures of cherubim (see Exodus 25:4, Exodus 25:18) were to be worked in the loom, as in the manufacture of tapestry and carpets (see Exodus 26:36 note). On the different kinds of workmen employed on the textile fabrics, see Exodus 35:35.', NULL, NULL, '''-13'':30 ''-33'':5 ''-34'':44,307 ''-6'':19 ''1'':18,257,297 ''11'':40,303 ''13'':279 ''14'':36 ''18'':282,327,404 ''19'':47,324 ''1the'':187 ''2'':284 ''25'':53,148,272,400,403 ''26'':17,28,35,77,80,186,243,275,296,299,357,380,422 ''27'':323 ''3'':52,309,358 ''30'':276 ''33'':43,306 ''34'':50 ''35'':39,302,326,438,439 ''36'':3,278,423 ''39'':42,305 ''4'':401 ''40'':46,49,281 ''5'':149 ''6'':244,300 ''6.of'':381 ''7'':29,78 ''8'':4 ''9'':81,273 ''accompani'':201 ''addit'':160 ''arrang'':174 ''articl'':199 ''board'':104 ''breadth'':335,339 ''call'':24,352 ''carpet'':419 ''chapter.exodus'':185 ''cherubim'':99,397 ''clear'':59 ''cloth'':128,241,264,293,378 ''color'':96,394 ''common'':348 ''compar'':1,37 ''compris'':10,262 ''confound'':67 ''consist'':88 ''contain'':108,130 ''coupl'':365 ''cover'':33,136,321 ''cun'':382 ''curtain'':90,331,355,361 ''cut'':179 ''definit'':198 ''denot'':213,228,236 ''differ'':427 ''distinct'':253 ''distinguish'':60 ''dwell'':195,208,231 ''dwelling-plac'':194,207,230 ''e'':192 ''employ'':250,431 ''end'':182 ''english'':73 ''entir'':375 ''etc'':54,82,283,308,328 ''exodus'':2,16,27,34,38,41,45,48,76,79,147,242,271,274,277,280,295,298,301,304,322,325,356,379,399,402,421,437 ''extern'':167 ''fabric'':435 ''fact'':249 ''figur'':97,395 ''fine'':92 ''five'':336 ''form'':168,345,363 ''full'':225 ''goat'':126,155 ''hair'':127,156 ''hebrew'':63,203 ''holi'':110,115 ''kind'':428 ''larg'':354 ''linen'':93 ''loom'':411 ''loop'':369 ''main'':12 ''make'':373 ''mani'':69 ''manufactur'':415 ''mean'':256 ''mshkan'':190 ''narrow'':287 ''note'':424 ''number'':51 ''part'':13,56,177 ''place'':70,111,116,196,209,217,232 ''proper'':385 ''protect'':161 ''ram'':142 ''rang'':254 ''rather'':332 ''red'':141 ''regular'':200 ''see'':75,178,398,420,436 ''sens'':226,261,288,313 ''shelter'':132 ''skill'':391 ''skin'':143,146 ''so-cal'':22 ''spread'':152 ''strict'':21,260 ''structur'':102 ''tabernacl'':7,15,84,134,171,188,240,267,292,316,377 ''tabernacle-cloth'':239,291,376 ''tach'':371 ''tachash'':145 ''tapestri'':417 ''ten'':330,334 ''tent'':26,118,124,157,319 ''textil'':434 ''three'':11,252 ''thus'':362 ''togeth'':366 ''true'':123 ''two'':360 ''unit'':341 ''usag'':349 ''use'':222 ''version'':74 ''weather'':164 ''weaver'':392 ''wider'':312 ''woodwork'':270 ''word'':204,219,246 ''work'':383,388,408 ''workmen'':430 ''woven'':94 ''yahweh'':211,234', NULL, '76');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('771', '2', '771', NULL, 'Jeremiah 26 is a narrative of the danger to which Jeremiah was exposed by reason of the prophecy contained in Jeremiah 7 and should be read in connection with it. Jeremiah 26:4-6 contain a summary of the prediction contained in Jeremiah 7, and that again is but an outline of what was a long address.', NULL, NULL, '''-6'':34 ''26'':2,32 ''4'':33 ''7'':22,44 ''address'':57 ''connect'':28 ''contain'':19,35,41 ''danger'':8 ''expos'':13 ''jeremiah'':1,11,21,31,43 ''long'':56 ''narrat'':5 ''outlin'':51 ''predict'':40 ''propheci'':18 ''read'':26 ''reason'':15 ''summari'':37', NULL, '771');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('82', '2', '82', NULL, 'In all probability these three chapters originally formed a distinct composition. The main incidents recorded in them follow in the order of time, and are therefore in their proper place as regards historical sequence.The golden calf - The people had, to a great extent, lost the patriarchal faith, and were but imperfectly instructed in the reality of a personal unseen God. Being disappointed at the long absence of Moses, they seem to have imagined that he had deluded them, and had probably been destroyed amidst the thunders of the mountain Exodus 24:15-18. Accordingly, they gave way to their superstitious fears and fell back upon that form of idolatry which was most familiar to them (see Exodus 32:4 note). The narrative of the circumstances is more briefly given by Moses at a later period in one of his addresses to the people Deuteronomy 9:8-21, Deuteronomy 9:25-29; Deuteronomy 10:1-5, Deuteronomy 10:8-11. It is worthy of remark, that Josephus, in his very characteristic chapter on the giving of the law, says nothing whatever of this act of apostacy, though he relates that Moses twice ascended the mountain.Exodus 32:1Unto Aaron - The chief authority during the absence of Moses was committed to Aaron and Hur Exodus 24:14.Make us gods - The substantive   ''elohym is plural in form and may denote gods. But according to the Hebrew idiom, the meaning need not be plural, and hence, the word is used as the common designation of the true God (Genesis 1:1, etc. See Exodus 21:6 note). It here denotes a god, and should be so rendered.', NULL, NULL, '''-11'':159 ''-18'':93 ''-21'':147 ''-29'':151 ''-5'':155 ''1'':154,255,256 ''10'':153,157 ''14.make'':214 ''15'':92 ''1unto'':196 ''21'':260 ''24'':91,213 ''25'':150 ''32'':118,195 ''4'':119 ''6'':261 ''8'':146,158 ''9'':145,149 ''aaron'':197,209 ''absenc'':66,203 ''accord'