INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('83', '2', '83', NULL, 'See Exodus 3:8.For I will not go up in the midst of thee - The covenant on which the original promise Exodus 23:20-23 was based had been broken by the people. Yahweh now therefore declared that though His Angel should go before Moses, He would withhold His own favoring presence. The nation should be put on a level with other nations, to lose its character as the people in special covenant with Yahweh (see the note at Exodus 33:16). Thus were the people forcibly warned that His presence could prove a blessing to them only on condition of their keeping their part of the covenant Exodus 33:3. If they failed in this, His presence would be to them "a consuming fire" (Deuteronomy 4:24; compare Exodus 32:10).', NULL, NULL, '''-23'':25 ''10'':132 ''16'':82 ''20'':24 ''23'':23 ''24'':128 ''3'':3,111 ''32'':131 ''33'':81,110 ''4'':127 ''8.for'':4 ''angel'':41 ''base'':27 ''bless'':95 ''broken'':30 ''charact'':67 ''compar'':129 ''condit'':100 ''consum'':124 ''could'':92 ''coven'':16,73,108 ''declar'':37 ''deuteronomi'':126 ''exodus'':2,22,80,109,130 ''fail'':114 ''favor'':51 ''fire'':125 ''forcibl'':87 ''go'':8,43 ''keep'':103 ''level'':60 ''lose'':65 ''midst'':12 ''mose'':45 ''nation'':54,63 ''note'':78 ''origin'':20 ''part'':105 ''peopl'':33,70,86 ''presenc'':52,91,118 ''promis'':21 ''prove'':93 ''put'':57 ''see'':1,76 ''special'':72 ''thee'':14 ''therefor'':36 ''though'':39 ''thus'':83 ''warn'':88 ''withhold'':48 ''would'':47,119 ''yahweh'':34,75', NULL, '83');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('84', '2', '84', NULL, 'Hew thee - The former tables are called "the work of God;" compare Exodus 32:16.The words - See Exodus 34:28.', NULL, NULL, '''16.the'':15 ''28'':20 ''32'':14 ''34'':19 ''call'':7 ''compar'':12 ''exodus'':13,18 ''former'':4 ''god'':11 ''hew'':1 ''see'':17 ''tabl'':5 ''thee'':2 ''word'':16 ''work'':9', NULL, '84');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('85', '2', '85', NULL, 'The narrative of what relates to the construction of the sanctuary is now resumed from Exodus 31:18.', NULL, NULL, '''18'':18 ''31'':17 ''construct'':8 ''exodus'':16 ''narrat'':2 ''relat'':5 ''resum'':14 ''sanctuari'':11', NULL, '85');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('86', '2', '86', NULL, 'See the notes to Exodus 26. See the notes to Exodus 25. For Exodus 38:1-7 and Exodus 38:9-20 see the notes to Exodus 27.', NULL, NULL, '''-20'':22 ''-7'':17 ''1'':16 ''25'':12 ''26'':6 ''27'':28 ''38'':15,20 ''9'':21 ''exodus'':5,11,14,19,27 ''note'':3,9,25 ''see'':1,7,23', NULL, '86');
