INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('88', '2', '88', NULL, 'See the marginal reference. The women who assembled at the entrance of the tent of meeting were most probably devout women who loved the public service of religion. The giving up of their mirrors for the use of the sanctuary was a fit sacrifice for such women to make (compare Exodus 35:22 note).', NULL, NULL, '''22'':53 ''35'':52 ''assembl'':8 ''compar'':50 ''devout'':20 ''entranc'':11 ''exodus'':51 ''fit'':43 ''give'':30 ''love'':23 ''make'':49 ''margin'':3 ''meet'':16 ''mirror'':34 ''note'':54 ''probabl'':19 ''public'':25 ''refer'':4 ''religion'':28 ''sacrific'':44 ''sanctuari'':40 ''see'':1 ''servic'':26 ''tent'':14 ''use'':37 ''women'':6,21,47', NULL, '88');
