INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('90', '2', '90', NULL, 'The directions given in Leviticus 24:5-9 are here presupposed, and must have been issued before this chapter was written.', NULL, NULL, '''-9'':8 ''24'':6 ''5'':7 ''chapter'':19 ''direct'':2 ''given'':3 ''issu'':16 ''leviticus'':5 ''must'':13 ''presuppos'':11 ''written'':21', NULL, '90');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('660', '2', '660', NULL, 'Preacher - literally, Convener. No one English word represents the Hebrew   qoheleth adequately. Though capable, according to Hebrew usage, of being applied to men in office, it is strictly a feminine participle, and describes a person in the act of calling together an assembly of people as if with the intention of addressing them. The word thus understood refers us to the action of Wisdom personified Proverbs 1:20; Proverbs 8:8. In Proverbs and here, Solomon seems to support two characters, speaking sometimes in the third person as Wisdom instructing the assembled people, at other times in the first person. So our Lord speaks of Himself (compare Luke 11:49 with Matthew 23:34) as Wisdom, and as desiring Luke 13:34 to gather the people together for instruction; It is unfortunate that the word "Preacher" does not bring this personification before English minds, but a different idea.', NULL, NULL, '''1'':67 ''11'':109 ''13'':121 ''20'':68 ''23'':113 ''34'':114,122 ''49'':110 ''8'':70,71 ''accord'':15 ''act'':38 ''action'':62 ''address'':52 ''adequ'':12 ''appli'':21 ''assembl'':43,92 ''bring'':139 ''call'':40 ''capabl'':14 ''charact'':81 ''compar'':107 ''conven'':3 ''describ'':33 ''desir'':119 ''differ'':147 ''english'':6,143 ''feminin'':30 ''first'':99 ''gather'':124 ''hebrew'':10,17 ''idea'':148 ''instruct'':90,129 ''intent'':50 ''liter'':2 ''lord'':103 ''luke'':108,120 ''matthew'':112 ''men'':23 ''mind'':144 ''offic'':25 ''one'':5 ''participl'':31 ''peopl'':45,93,126 ''person'':35,87,100 ''personif'':141 ''personifi'':65 ''preacher'':1,136 ''proverb'':66,69,73 ''qoheleth'':11 ''refer'':58 ''repres'':8 ''seem'':77 ''solomon'':76 ''sometim'':83 ''speak'':82,104 ''strict'':28 ''support'':79 ''third'':86 ''though'':13 ''thus'':56 ''time'':96 ''togeth'':41,127 ''two'':80 ''understood'':57 ''unfortun'':132 ''us'':59 ''usag'':18 ''wisdom'':64,89,116 ''word'':7,55,135', NULL, '660');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('661', '2', '661', NULL, 'Solomon''s trial of God''s second gift, namely, riches, and the enjoyment which riches supply; this brought him to the sane result (compare Ecclesiastes 1:12).Comparing Solomon''s action with Luke 12:16-21, it must be remembered that Solomon''s object was the acquisition of wisdom, not self-indulgence, and that he did not fail to look forward to the certainty of death overtaking him.', NULL, NULL, '''-21'':36 ''1'':26 ''12'':27,34 ''16'':35 ''acquisit'':47 ''action'':31 ''brought'':18 ''certainti'':65 ''compar'':24,28 ''death'':67 ''ecclesiast'':25 ''enjoy'':13 ''fail'':59 ''forward'':62 ''gift'':8 ''god'':5 ''indulg'':53 ''look'':61 ''luke'':33 ''must'':38 ''name'':9 ''object'':44 ''overtak'':68 ''rememb'':40 ''result'':23 ''rich'':10,15 ''sane'':22 ''second'':7 ''self'':52 ''self-indulg'':51 ''solomon'':1,29,42 ''suppli'':16 ''trial'':3 ''wisdom'':49', NULL, '661');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('662', '2', '662', NULL, 'Everything - More particularly, the actions of people (e. g. his own, Ecclesiastes 2:1-8) and events which happen to people, the world of Providence rather than the world of creation. It would seem that most of his own works described in Ecclesiastes 2:1-8 were present to his mind. The rare word translated "season" means emphatically "fitting time" (compare Nehemiah 2:6; Esther 9:27, Esther 9:31).', NULL, NULL, '''-8'':15,46 ''1'':14,45 ''2'':13,44,63 ''27'':67 ''31'':70 ''6'':64 ''9'':66,69 ''action'':5 ''compar'':61 ''creation'':31 ''describ'':41 ''e'':8 ''ecclesiast'':12,43 ''emphat'':58 ''esther'':65,68 ''event'':17 ''everyth'':1 ''fit'':59 ''g'':9 ''happen'':19 ''mean'':57 ''mind'':51 ''nehemiah'':62 ''particular'':3 ''peopl'':7,21 ''present'':48 ''provid'':25 ''rare'':53 ''rather'':26 ''season'':56 ''seem'':34 ''time'':60 ''translat'':55 ''word'':54 ''work'':40 ''world'':23,29 ''would'':33', NULL, '662');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('663', '2', '663', NULL, 'So I returned, and considered - Rather, And I returned and saw. He turns to look upon other phenomena, and to test his previous conclusion by them.Oppressed - See the introduction to Ecclesiastes.', NULL, NULL, '''conclus'':24 ''consid'':5 ''ecclesiast'':31 ''introduct'':29 ''look'':15 ''phenomena'':18 ''previous'':23 ''rather'':6 ''return'':3,9 ''saw'':11 ''see'':27 ''test'':21 ''them.oppressed'':26 ''turn'':13 ''upon'':16', NULL, '663');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('664', '2', '664', NULL, 'Keep thy foot - i. e., Give thy mind to what thou art going to do.The house of God - It has been said that here an ordinary devout Hebrew writer might have been expected to call it "the house of Yahweh;" but to those who accept this book as the work of Solomon after his fall into idolatry, it will appear a natural sign of the writer''s self-humiliation, an acknowledgment of his unworthiness of the privileges of a son of the covenant, that he avoids the name of the Lord of the covenant (see Ecclesiastes 1:13 note).Be more ready to hear - Perhaps in the sense that, "to draw near for the purpose of hearing (and obeying) is better than etc."', NULL, NULL, '''1'':98 ''13'':99 ''accept'':45 ''acknowledg'':72 ''appear'':60 ''art'':12 ''avoid'':87 ''better'':122 ''book'':47 ''call'':35 ''coven'':84,95 ''devout'':27 ''do.the'':15 ''draw'':112 ''e'':5 ''ecclesiast'':97 ''etc'':124 ''expect'':33 ''fall'':55 ''foot'':3 ''give'':6 ''go'':13 ''god'':18 ''hear'':105,118 ''hebrew'':28 ''hous'':16,38 ''humili'':70 ''idolatri'':57 ''keep'':1 ''lord'':92 ''might'':30 ''mind'':8 ''name'':89 ''natur'':62 ''near'':113 ''note'':100 ''obey'':120 ''ordinari'':26 ''perhap'':106 ''privileg'':78 ''purpos'':116 ''readi'':103 ''said'':22 ''see'':96 ''self'':69 ''self-humili'':68 ''sens'':109 ''sign'':63 ''solomon'':52 ''son'':81 ''thi'':2,7 ''thou'':11 ''unworthi'':75 ''work'':50 ''writer'':29,66 ''yahweh'':40', NULL, '664');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('665', '2', '665', NULL, 'No burial - For a corpse to lie unburied was a circumstance in itself of special ignominy and dishonor (compare the marginal references).', NULL, NULL, '''burial'':2 ''circumst'':11 ''compar'':19 ''corps'':5 ''dishonor'':18 ''ignomini'':16 ''lie'':7 ''margin'':21 ''refer'':22 ''special'':15 ''unburi'':8', NULL, '665');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('666', '2', '666', NULL, 'Name ... ointment - The likeness between reputation and odor supplies a common metaphor: the contrast is between reputation, as an honorable attainment which only wise people win, and fragrant odor, as a gratification of the senses which all people enjoy.The connection of this verse with the preceding verses is this: the man, who wants to know what is profitable for man and good in this life, is here told to act in such a way as ordinarily secures a good reputation (i. e., to act like a wise man), and to teach himself this hard lesson - to regard the day of death as preferable to the day of birth. Though Solomon seems in some places to feel strongly (Ecclesiastes 2:16; Ecclesiastes 3:19-20 ff) that natural fear of death which is, in a great measure, mistrust founded on the ignorance which Christ dispelled; yet he states the advantage of death over life in respect of its freedom from toil, oppression, restlessness Ecclesiastes 2:17; Ecclesiastes 4:2; Ecclesiastes 6:5, and in respect of its implying an immediate and a nearer approach to God Ecclesiastes 3:21; Ecclesiastes 12:7. While Solomon preferred the day of death, he might still (with Luther here) have regarded birth as a good thing, and as having its place in the creation of God.', NULL, NULL, '''-20'':124 ''12'':190 ''16'':120 ''17'':165 ''19'':123 ''2'':119,164,168 ''21'':188 ''3'':122,187 ''4'':167 ''5'':171 ''6'':170 ''7'':191 ''act'':70,84 ''advantag'':149 ''approach'':183 ''attain'':21 ''birth'':108,207 ''christ'':143 ''common'':11 ''connect'':40 ''contrast'':14 ''creation'':219 ''day'':99,106,196 ''death'':101,130,151,198 ''dispel'':144 ''e'':82 ''ecclesiast'':118,121,163,166,169,186,189 ''enjoy.the'':39 ''fear'':128 ''feel'':116 ''ff'':125 ''found'':138 ''fragrant'':28 ''freedom'':158 ''god'':185,221 ''good'':62,79,210 ''gratif'':32 ''great'':135 ''hard'':94 ''honor'':20 ''ignor'':141 ''immedi'':179 ''impli'':177 ''know'':55 ''lesson'':95 ''life'':65,153 ''like'':4,85 ''luther'':203 ''man'':51,60,88 ''measur'':136 ''metaphor'':12 ''might'':200 ''mistrust'':137 ''name'':1 ''natur'':127 ''nearer'':182 ''odor'':8,29 ''ointment'':2 ''oppress'':161 ''ordinarili'':76 ''peopl'':25,38 ''place'':114,216 ''preced'':46 ''prefer'':103,194 ''profit'':58 ''regard'':97,206 ''reput'':6,17,80 ''respect'':155,174 ''restless'':162 ''secur'':77 ''seem'':111 ''sens'':35 ''solomon'':110,193 ''state'':147 ''still'':201 ''strong'':117 ''suppli'':9 ''teach'':91 ''thing'':211 ''though'':109 ''toil'':160 ''told'':68 ''vers'':43,47 ''want'':53 ''way'':74 ''win'':26 ''wise'':24,87 ''yet'':145', NULL, '666');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('772', '2', '772', NULL, 'Of Jehoiakim - Really, of Zedekiah, as the Syriac reads (see Jeremiah 27:3). In the Septuagint the verse is missing. Some scribe has confused the title of this chapter with that of Jeremiah 26.', NULL, NULL, '''26'':34 ''27'':12 ''3'':13 ''chapter'':29 ''confus'':24 ''jehoiakim'':2 ''jeremiah'':11,33 ''miss'':20 ''read'':9 ''realli'':3 ''scribe'':22 ''see'':10 ''septuagint'':16 ''syriac'':8 ''titl'':26 ''vers'':18 ''zedekiah'':5', NULL, '772');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('676', '2', '676', NULL, 'My honeycomb - literally, "my reed" or "my wood," i. e., the substance itself, or portions of it in which the comb is formed. The bees in Palestine form their combs not only in the hollows of trees and rocks, but also in reeds by the river-banks. The king''s meaning appears to be: "All pleases me in thee, there is nothing to despise or cast away."Eat, O friends - A salutation from the king to his assembled guests, or to the chorus of young men his companions, bidding them in the gladness of his heart Sol 3:11 partake of the banquet. So ends this day of outward festivity and supreme heart-joy. The first half of the Song of Songs is fitly closed. The second half of the poem commences Sol 5:2 with a change of tone and reaction of feeling similar to that of Sol 3:1. It terminates with the sealing Sol 8:6-7 of yet deeper love.', NULL, NULL, '''-7'':162 ''1'':153 ''11'':100 ''2'':137 ''3'':99,152 ''5'':136 ''6'':161 ''8'':160 ''also'':41 ''appear'':53 ''assembl'':79 ''away'':68 ''bank'':48 ''banquet'':104 ''bee'':25 ''bid'':90 ''cast'':67 ''chang'':140 ''chorus'':84 ''close'':127 ''comb'':21,30 ''commenc'':134 ''companion'':89 ''day'':108 ''deeper'':165 ''despis'':65 ''e'':10 ''eat'':69 ''end'':106 ''feel'':146 ''festiv'':111 ''first'':118 ''fit'':126 ''form'':23,28 ''friend'':71 ''glad'':94 ''guest'':80 ''half'':119,130 ''heart'':97,115 ''heart-joy'':114 ''hollow'':35 ''honeycomb'':2 ''joy'':116 ''king'':50,76 ''liter'':3 ''love'':166 ''mean'':52 ''men'':87 ''noth'':63 ''o'':70 ''outward'':110 ''palestin'':27 ''partak'':101 ''pleas'':57 ''poem'':133 ''portion'':15 ''reaction'':144 ''reed'':5,43 ''river'':47 ''river-bank'':46 ''rock'':39 ''salut'':73 ''seal'':158 ''second'':129 ''similar'':147 ''sol'':98,135,151,159 ''song'':122,124 ''substanc'':12 ''suprem'':113 ''termin'':155 ''thee'':60 ''tone'':142 ''tree'':37 ''wood'':8 ''yet'':164 ''young'':86', NULL, '676');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('677', '2', '677', NULL, 'The question put by the chorus, and the answer it receives from the bride, show that the loss and seeking are not to be taken too seriously.', NULL, NULL, '''answer'':9 ''bride'':14 ''chorus'':6 ''loss'':18 ''put'':3 ''question'':2 ''receiv'':11 ''seek'':20 ''serious'':27 ''show'':15 ''taken'':25', NULL, '677');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('678', '2', '678', NULL, 'Thy feet with shoes - Or, thy steps in the sandals: the bride''s feet are seen in motion in the dance. "Joints" might be rendered circling movements.Prince''s daughter - Or, daughter of a noble; the bride is of honorable though not of kingly birth.Like jewels - The image suggested is that of large well-formed pearls or other jewels skillfully strung or linked together.', NULL, NULL, '''birth.like'':44 ''bride'':12,36 ''circl'':26 ''danc'':21 ''daughter'':29,31 ''feet'':2,14 ''form'':55 ''honor'':39 ''imag'':47 ''jewel'':45,59 ''joint'':22 ''king'':43 ''larg'':52 ''link'':63 ''might'':23 ''motion'':18 ''movements.prince'':27 ''nobl'':34 ''pearl'':56 ''render'':25 ''sandal'':10 ''seen'':16 ''shoe'':4 ''skill'':60 ''step'':7 ''strung'':61 ''suggest'':48 ''thi'':1,6 ''though'':40 ''togeth'':64 ''well'':54 ''well-form'':53', NULL, '678');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('679', '2', '679', NULL, 'Royal rank and splendor are grown wearisome. The king once called her "sister" and "sister-bride." Would he were indeed as a "brother," her mother''s own child whom she might meet, embrace, and welcome everywhere without restraint or shame. Her love for him is simple, sacred, pure, free from the unrest and the stains of mere earthly passion.', NULL, NULL, '''bride'':17 ''brother'':24 ''call'':11 ''child'':29 ''earth'':59 ''embrac'':34 ''everywher'':37 ''free'':50 ''grown'':6 ''inde'':21 ''king'':9 ''love'':43 ''meet'':33 ''mere'':58 ''might'':32 ''mother'':26 ''passion'':60 ''pure'':49 ''rank'':2 ''restraint'':39 ''royal'':1 ''sacr'':48 ''shame'':41 ''simpl'':47 ''sister'':13,16 ''sister-brid'':15 ''splendor'':4 ''stain'':56 ''unrest'':53 ''wearisom'':7 ''welcom'':36 ''without'':38 ''would'':18', NULL, '679');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('681', '2', '681', NULL, 'The word - This indicates that this is the commencement of a new prophecy. It has no immediate connection with the preceding. It was delivered doubtless at a different time, and with reference to a different class of events. In the previous chapter the term "vision" is used Isaiah 2:1, but the meaning is substantially the same. The term "word"   dabar, denotes a "command, a promise, a doctrine, an oracle, a revelation, a message, a thing," etc. It means here, that Isaiah foresaw certain "future events" or "things" that would happen in regard to Judah and Jerusalem.Judah ... - see the notes at Isaiah 1:1.', NULL, NULL, '''1'':50,103,104 ''2'':49 ''certain'':84 ''chapter'':42 ''class'':36 ''command'':64 ''commenc'':9 ''connect'':18 ''dabar'':61 ''deliv'':24 ''denot'':62 ''differ'':28,35 ''doctrin'':68 ''doubtless'':25 ''etc'':77 ''event'':38,86 ''foresaw'':83 ''futur'':85 ''happen'':91 ''immedi'':17 ''indic'':4 ''isaiah'':48,82,102 ''jerusalem.judah'':97 ''judah'':95 ''mean'':53,79 ''messag'':74 ''new'':12 ''note'':100 ''oracl'':70 ''preced'':21 ''previous'':41 ''promis'':66 ''propheci'':13 ''refer'':32 ''regard'':93 ''revel'':72 ''see'':98 ''substanti'':55 ''term'':44,59 ''thing'':76,88 ''time'':29 ''use'':47 ''vision'':45 ''word'':2,60 ''would'':90', NULL, '681');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('682', '2', '682', NULL, 'For - This is a continuation of the previous chapter. The same prophecy is continued, and the force of the argument of the prophet will not be seen unless the chapters are read together; see the Analysis prefixed to Isaiah 2. In the close of the second chapter Isaiah 2:22, the prophet had cautioned his countrymen against confiding in man. In this chapter, a reason is given here why they should cease to do it - to wit, that God would soon take away their kings and princes.The Lord -   ha''adon; see the note at Isaiah 1:24.The Lord of hosts - see the note at Isaiah 1:9. The prophet calls the attention of the Jews particularly to the fact that this was about to be done by Yahweh "of hosts" - a title which he gives to God when he designs to indicate that that which is to be done implies special strength, power, and majesty. As the work which was now to be done was the removal of the mighty men on which the nation was depending, it is implied that it was a work of power which belonged especially to the God of armies - the Almighty.Doth take away - Is about to remove. In the Hebrew, the word here is a "participle," and does not mark the precise time. It has reference here, however, to the future.From Jerusalem ... - Note Isaiah 1:1.The stay - In the Hebrew, the words translated "stay" and "staff" are the same, with the exception that the former is in the masculine, and the latter in the feminine gender. The meaning is, that God would remove "all kinds of support," or "everything" on which they relied. The reference is undoubtedly to the princes and mighty men on whose counsels and aid the nation was resting for defense; see Isaiah 3:2-3.The whole stay of bread - We use a similar expression when we say that "bread is the staff of life." The Hebrews often expressed the same idea, representing the "heart" in man as being "supported or upheld" by bread, Genesis 18:5 (margin); Judges 19:5 (margin); Leviticus 26:26; Psalm 105:16.Stay of water - He would reduce them from their luxuries introduced by commerce Isaiah 2 to absolute want. This often occurred in the sieges and wars of the nation; and in the famines which were the consequence of the wars. The reference here is probably to the invasion of the land by Nebuchadnezzar. The famine consequent on that invasion is described in Jeremiah 38:21; Jeremiah 38:9; Lamentations 4:4 : "The tongue of the sucking child cleaveth to the roof of his month for thirst; the young children ask bread, and no man breaketh it unto them."', NULL, NULL, '''1'':96,106,231 ''1.the'':232 ''105'':355 ''16.stay'':356 ''18'':344 ''19'':348 ''2'':40,49,370 ''2-3.the'':304 ''21'':420 ''22'':50 ''24.the'':97 ''26'':352,353 ''3'':303 ''38'':419,422 ''4'':425,426 ''5'':345,349 ''9'':107,423 ''absolut'':372 ''adon'':90 ''aid'':294 ''almighty.doth'':197 ''analysi'':36 ''argument'':20 ''armi'':195 ''ask'':445 ''attent'':112 ''away'':83,199 ''belong'':189 ''bread'':308,318,342,446 ''breaketh'':450 ''call'':110 ''caution'':54 ''ceas'':72 ''chapter'':9,30,47,63 ''child'':432 ''children'':444 ''cleaveth'':433 ''close'':43 ''commerc'':368 ''confid'':58 ''consequ'':392,411 ''continu'':5,14 ''counsel'':292 ''countrymen'':56 ''defens'':300 ''depend'':177 ''describ'':416 ''design'':140 ''done'':126,149,164 ''especi'':190 ''everyth'':275 ''except'':248 ''express'':313,327 ''fact'':119 ''famin'':388,410 ''feminin'':261 ''forc'':17 ''former'':251 ''future.from'':227 ''gender'':262 ''genesi'':343 ''give'':135 ''given'':67 ''god'':79,137,193,267 ''ha'':89 ''heart'':333 ''hebrew'':206,236,325 ''host'':100,130 ''howev'':224 ''idea'':330 ''impli'':150,180 ''indic'':142 ''introduc'':366 ''invas'':403,414 ''isaiah'':39,48,95,105,230,302,369 ''jeremiah'':418,421 ''jerusalem'':228 ''jew'':115 ''judg'':347 ''kind'':271 ''king'':85 ''lament'':424 ''land'':406 ''latter'':258 ''leviticus'':351 ''life'':323 ''lord'':88,98 ''luxuri'':365 ''majesti'':155 ''man'':60,335,449 ''margin'':346,350 ''mark'':216 ''masculin'':255 ''mean'':264 ''men'':171,289 ''mighti'':170,288 ''month'':439 ''nation'':175,296,384 ''nebuchadnezzar'':408 ''note'':93,103,229 ''occur'':376 ''often'':326,375 ''participl'':212 ''particular'':116 ''power'':153,187 ''precis'':218 ''prefix'':37 ''previous'':8 ''princ'':286 ''princes.the'':87 ''probabl'':400 ''propheci'':12 ''prophet'':23,52,109 ''psalm'':354 ''read'':32 ''reason'':65 ''reduc'':361 ''refer'':222,281,397 ''reli'':279 ''remov'':167,203,269 ''repres'':331 ''rest'':298 ''roof'':436 ''say'':316 ''second'':46 ''see'':34,91,101,301 ''seen'':27 ''sieg'':379 ''similar'':312 ''soon'':81 ''special'':151 ''staff'':242,321 ''stay'':233,240,306 ''strength'':152 ''suck'':431 ''support'':273,338 ''take'':82,198 ''thirst'':441 ''time'':219 ''titl'':132 ''togeth'':33 ''tongu'':428 ''translat'':239 ''undoubt'':283 ''unless'':28 ''unto'':452 ''upheld'':340 ''use'':310 ''want'':373 ''war'':381,395 ''water'':358 ''whole'':305 ''whose'':291 ''wit'':77 ''word'':208,238 ''work'':158,185 ''would'':80,268,360 ''yahweh'':128 ''young'':443', NULL, '682');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('833', '2', '833', NULL, 'Fifth prophecy against Egypt: a warning to Pharaoh from the fate of the Assyrians. The Assyrian empire, after having been supreme in Asia for four centuries, had been overthrown by the united forces of the Babylonians and Medes, in the year of the battle of Carchemish (605 b.c.), which had broken the power of Egypt. This gives force to the warning to Egypt from Assyria''s fall.', NULL, NULL, '''605'':47 ''asia'':23 ''assyria'':65 ''assyrian'':14,16 ''b.c'':48 ''babylonian'':36 ''battl'':44 ''broken'':51 ''carchemish'':46 ''centuri'':26 ''egypt'':4,55,63 ''empir'':17 ''fall'':67 ''fate'':11 ''fifth'':1 ''forc'':33,58 ''four'':25 ''give'':57 ''mede'':38 ''overthrown'':29 ''pharaoh'':8 ''power'':53 ''propheci'':2 ''suprem'':21 ''unit'':32 ''warn'':6,61 ''year'':41', NULL, '833');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('683', '2', '683', NULL, 'In that day - The time of calamity referred to in the close of the previous chapter. This is a continuation of that prophecy, and there was no reason why these six verses should have been made a separate chapter. That the passage refers to the Messiah, is apparent from what has been stated in the note at the commencement of the prophecy Isaiah 2:1-4, and from the expressions which occur in the chapter itself; see the notes at Isaiah 4:2, Isaiah 4:5-6.Seven women - The number "seven" is used often to denote a "large" though "indefinite" number; Leviticus 26:28; Proverbs 24:16; Zechariah 3:9. It means that so great should be the calamity, so many "men" would fall in battle, that many women would, contrary to their natural modesty, become suitors to a single man, to obtain him as a husband and protector.Shall take hold - Shall apply to. The expression, ''shall take hold,'' denotes the "earnestness" of their application.We will eat our own bread ... - We do not ask this in order to be maintained. We will forego that which the law Exodus 21:10 enjoins as the duty of the husband in case he has more than one wife.Only let us be called by thy name - Let us be regarded as "thy wives." The wife then, as now, assumed the name of the husband. A remarkably similar expression occurs in Lucan (B. ii. 342). Marcia there presents a similar request to Cato:Da tantum nomen inaneConnubii; liceat tumulo scripsisse, Catonis Marcia.''Indulge me only with the empty title of wife.Let there only be inscribed on my tomb, "Marcia, wife of Cato."''To take away my reproach - The reproach of being unmarried; compare Genesis 30:23; 1 Samuel 1:6.', NULL, NULL, '''-4'':66 ''1'':65,291,293 ''10'':189 ''16'':106 ''2'':64,83 ''21'':188 ''23'':290 ''24'':105 ''26'':102 ''28'':103 ''3'':108 ''30'':289 ''342'':239 ''4'':82,85 ''5-6.seven'':86 ''6'':294 ''9'':109 ''appar'':48 ''appli'':152 ''application.we'':164 ''ask'':173 ''assum'':224 ''away'':279 ''b'':237 ''battl'':125 ''becom'':135 ''bread'':169 ''calam'':7,118 ''call'':208 ''case'':198 ''cato'':247,276 ''catoni'':255 ''chapter'':16,39,75 ''close'':12 ''commenc'':59 ''compar'':287 ''continu'':20 ''contrari'':130 ''da'':248 ''day'':3 ''denot'':95,159 ''duti'':193 ''earnest'':161 ''eat'':166 ''empti'':262 ''enjoin'':190 ''exodus'':187 ''express'':70,155,233 ''fall'':123 ''forego'':182 ''genesi'':288 ''great'':114 ''hold'':150,158 ''husband'':146,196,229 ''ii'':238 ''inaneconnubii'':251 ''indefinit'':99 ''indulg'':257 ''inscrib'':269 ''isaiah'':63,81,84 ''larg'':97 ''law'':186 ''let'':205,212 ''leviticus'':101 ''liceat'':252 ''lucan'':236 ''made'':36 ''maintain'':179 ''man'':140 ''mani'':120,127 ''marcia'':240,256,273 ''mean'':111 ''men'':121 ''messiah'':46 ''modesti'':134 ''name'':211,226 ''natur'':133 ''nomen'':250 ''note'':56,79 ''number'':89,100 ''obtain'':142 ''occur'':72,234 ''often'':93 ''one'':203 ''order'':176 ''passag'':42 ''present'':242 ''previous'':15 ''propheci'':23,62 ''protector.shall'':148 ''proverb'':104 ''reason'':28 ''refer'':8,43 ''regard'':215 ''remark'':231 ''reproach'':281,283 ''request'':245 ''samuel'':292 ''scripsiss'':254 ''see'':77 ''separ'':38 ''seven'':90 ''shall'':151,156 ''similar'':232,244 ''singl'':139 ''six'':31 ''state'':53 ''suitor'':136 ''take'':149,157,278 ''tantum'':249 ''thi'':210,217 ''though'':98 ''time'':5 ''titl'':263 ''tomb'':272 ''tumulo'':253 ''unmarri'':286 ''us'':206,213 ''use'':92 ''vers'':32 ''wife'':220,274 ''wife.let'':265 ''wife.only'':204 ''wive'':218 ''women'':87,128 ''would'':122,129 ''zechariah'':107', NULL, '683');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('684', '2', '684', NULL, 'Now will I sing - This is an indication that what follows is poetic, or is adapted to be sung or chanted.To my well-beloved - The word used here -   yedyd - is a term of endearment. It properly denotes a friend; a favorite; one greatly beloved. It is applied to saints as being the beloved, or the favorites of God, in Psalm 127:2; Deuteronomy 33:12. In this place, it is evidently applied to Yahweh, the God of the Jewish people. As there is some reason to believe that the God of the Jews - the manifested Deity who undertook their deliverance from Egypt, and who was revealed as "their" God under the name of ''the Angel of the covenant'' - was the Messiah, so it may be that the prophet here meant to refer to him. It is not, however, to the Messiah "to come." It does not refer to the God incarnate - to Jesus of Nazareth; but to the God of the Jews, in his capacity as their lawgiver and protector in the time of Isaiah; not to him in the capacity of an incarnate Saviour.A Song of my beloved - Lowth, ''A song of loves,'' by a slight change in the Hebrew. The word   dod usually denotes ''an uncle,'' a father''s brother. But it also means one beloved, a friend, a lover; Sol 1:13-14, Sol 1:16; Sol 2:3, Sol 2:8, Sol 2:9; Sol 4:16. Here it refers to Jehovah, and expresses the tender and affectionate attachment which the prophet had for his character and laws.Touching his vineyard - The Jewish people are often represented under the image of a vineyard, planted and cultivated by God; see Psalm 80; Jeremiah 2:21; Jeremiah 12:10. Our Saviour also used this beautiful figure to denote the care and attention which God had bestowed on his people; Matthew 21:33 ff; Mark 12:1, following.My beloved - God.Hath a vineyard in a very fruitful hill - Hebrew ''On a horn of the son of oil.'' The word "horn" used here in the Hebrew, denotes the "brow, apex," or sharp point of a hill. The word is thus used in other languages to denote a hill, as in the Swiss words "shreckhorn, buchorn." Thus "Cornwall," in England, is called in the old British tongue "Kernaw," as lessening by degrees, like a horn, running out into promontories, like so many horns; for the Britons called a horn "corn," and in the plural "kern." The term ''horn'' is not unfrequently applied to hills. Thus, Pococke tells us (vol. ii. p. 67), that there is a low mountain in Galilee which has both its ends raised in such a manner as to look like two mounts, which are called the ''Horns of Hutin.'' Harmer, however, supposes that the term is used here to denote the land of Syria, from its resemblance to the shape ofa horn; Obs. iii. 242. But the idea is, evidently, that the land on which God respresents himself as having planted his vineyard, was like an elevated hill that was adapted eminently to such a culture. It may mean either the "top" of a mountain, or a little mountain, or a "peak" divided from others. The most favorable places for vineyards were on the sides of hills, where they would be exposed to the sun. - Shaw''s "Travels," p. 338. Thus Virgil says: - denique apertosBacchus amat colles.Bacchus loves open hills;'' "Georg." ii. 113. The phrase, "son of oil," is used in accordance with the Jewish custom, where "son" means descendant, relative, etc.; see the note at Matthew 1:1. Here it means that it was so fertile that it might be called the very "son of oil," or fatness, that is, fertility. The image is poetic, and very beautiful; denoting that God had planted his people in circumstances where he had a right to expect great growth in attachment to him. It was not owing to any want of care on his part, that they were not distinguished for piety. The Chaldee renders this verse, ''The prophet said, I will sing now to Israel, who is compared to a vineyard, the seed of Abraham my beloved: a song of my beloved to his vineyard.''', NULL, NULL, '''-14'':227 ''1'':225,229,318,600,601 ''10'':291 ''113'':575 ''12'':66,290,317 ''127'':62 ''13'':226 ''16'':230,242 ''2'':63,232,235,238,287 ''21'':288,313 ''242'':487 ''3'':233 ''33'':65,314 ''338'':562 ''4'':241 ''67'':430 ''8'':236 ''80'':285 ''9'':239 ''abraham'':696 ''accord'':584 ''adapt'':16,513 ''affection'':253 ''also'':216,294 ''amat'':568 ''angel'':116 ''apertosbacchus'':567 ''apex'':349 ''appli'':48,73,420 ''attach'':254,651 ''attent'':304 ''beauti'':297,631 ''believ'':88 ''belov'':25,45,54,190,219,320,698,703 ''bestow'':308 ''british'':384 ''briton'':404 ''brother'':213 ''brow'':348 ''buchorn'':374 ''call'':380,405,457,614 ''capac'':166,182 ''care'':302,662 ''chalde'':674 ''chang'':199 ''chanted.to'':21 ''charact'':261 ''circumst'':640 ''colles.bacchus'':569 ''come'':144 ''compar'':689 ''corn'':408 ''cornwal'':376 ''coven'':119 ''cultiv'':280 ''cultur'':518 ''custom'':588 ''degre'':390 ''deiti'':97 ''deliver'':101 ''deniqu'':566 ''denot'':38,207,300,346,365,472,632 ''descend'':592 ''deuteronomi'':64 ''distinguish'':670 ''divid'':535 ''dod'':205 ''egypt'':103 ''either'':522 ''elev'':509 ''emin'':514 ''end'':443 ''endear'':35 ''england'':378 ''etc'':594 ''evid'':72,492 ''expect'':647 ''expos'':554 ''express'':249 ''fat'':621 ''father'':211 ''favor'':540 ''favorit'':42,57 ''fertil'':609,624 ''ff'':315 ''figur'':298 ''follow'':11 ''following.my'':319 ''friend'':40,221 ''fruit'':327 ''galile'':438 ''georg'':573 ''god'':59,77,91,110,151,160,282,306,498,634 ''god.hath'':321 ''great'':44,648 ''growth'':649 ''harmer'':462 ''hebrew'':202,329,345 ''hill'':328,355,367,422,510,549,572 ''horn'':332,340,393,401,407,416,459,484 ''howev'':139,463 ''hutin'':461 ''idea'':490 ''ii'':428,574 ''iii'':486 ''imag'':274,626 ''incarn'':152,185 ''indic'':8 ''isaiah'':176 ''israel'':686 ''jehovah'':247 ''jeremiah'':286,289 ''jesus'':154 ''jew'':94,163 ''jewish'':80,267,587 ''kern'':413 ''kernaw'':386 ''land'':474,495 ''languag'':363 ''lawgiv'':169 ''laws.touching'':263 ''