INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('698', '2', '698', NULL, 'The burden of Egypt - This is the title to the prophecy. For the meaning of the word "burden," see the note at Isaiah 13:1. The word ''Egypt'' in the original is   mtseraym; and it was so called after Mizraim the second son of Ham, and grandson of Noah. Sometimes it is called Mazor 2 Kings 19:24; Isaiah 19:6; Isaiah 37:25; Micah 7:12; where, however, our English version has rendered the word by "besieged place or fortress." The ancient name of the country among the inhabitants themselves was "Chimi or Chami" (&#x3a7;&#x3b7;&#x3bc;&#x3c5;  Chemu). The Egyptian word signified "black," and the name was probably given from the black deposit made by the slime of the Nile. ''Mizraim, or Misrim, the name given to Egypt in the Scriptures, is in the plural form, and is the Hebrew mede of expressing the "two regions of Egypt" (so commonly met with in the hieroglyphics), or the "two Misr," a name still used by the Arabs, who call all Egypt, as well as Cairo, Musr or Misr.'' (Wilkinson''s "Ancient Egyptians," vol. i. p. 2). The origin of the name ''Egypt'' is unknown. Egyptus is said by some to have been an ancient king of this country.Behold, the Lord - This is a bold introduction. Yahweh is seen advancing to Egypt for the purpose of confounding its idols, and inflicting punishment. The leading idea which the prophet wishes probably to present is, that national calamities - anarchy, commotion, revolution, as well as physical sufferings - are under the government and direction of Yahweh.Rideth upon a swift cloud - Yahweh is often thus represented as riding on a cloud, especially when he comes for purposes of vengeance or punishment:And he rode upon a cherub and did fly,Yea, he did fly upon the wings of the wind.', NULL, NULL, '''1'':25 ''12'':67 ''13'':24 ''19'':57,60 ''2'':55,183 ''24'':58 ''25'':64 ''37'':63 ''6'':61 ''7'':66 ''advanc'':216 ''among'':88 ''anarchi'':243 ''ancient'':83,178,201 ''arab'':164 ''besieg'':78 ''black'':101,110 ''bold'':211 ''burden'':2,18 ''cairo'':172 ''calam'':242 ''call'':38,53,166 ''chami'':95 ''chemu'':96 ''cherub'':288 ''chimi'':93 ''cloud'':262,272 ''come'':276 ''common'':148 ''commot'':244 ''confound'':223 ''countri'':87 ''country.behold'':205 ''deposit'':111 ''direct'':256 ''egypt'':4,28,126,146,168,189,218 ''egyptian'':98,179 ''egyptus'':192 ''english'':71 ''especi'':273 ''express'':141 ''fli'':291,295 ''form'':134 ''fortress'':81 ''given'':107,124 ''govern'':254 ''grandson'':47 ''ham'':45 ''hebrew'':138 ''hieroglyph'':153 ''howev'':69 ''idea'':231 ''idol'':225 ''inflict'':227 ''inhabit'':90 ''introduct'':212 ''isaiah'':23,59,62 ''king'':56,202 ''lead'':230 ''lord'':207 ''made'':112 ''mazor'':54 ''mean'':14 ''mede'':139 ''met'':149 ''micah'':65 ''misr'':157,175 ''misrim'':121 ''mizraim'':40,119 ''mtseraym'':33 ''musr'':173 ''name'':84,104,123,159,188 ''nation'':241 ''nile'':118 ''noah'':49 ''note'':21 ''often'':265 ''origin'':31,185 ''p'':182 ''physic'':249 ''place'':79 ''plural'':133 ''present'':238 ''probabl'':106,236 ''propheci'':11 ''prophet'':234 ''punish'':228,282 ''purpos'':221,278 ''region'':144 ''render'':74 ''repres'':267 ''revolut'':245 ''ride'':269 ''rode'':285 ''said'':194 ''scriptur'':129 ''second'':42 ''see'':19 ''seen'':215 ''signifi'':100 ''slime'':115 ''sometim'':50 ''son'':43 ''still'':160 ''suffer'':250 ''swift'':261 ''thus'':266 ''titl'':8 ''two'':143,156 ''unknown'':191 ''upon'':259,286,296 ''use'':161 ''vengeanc'':280 ''version'':72 ''vol'':180 ''well'':170,247 ''wilkinson'':176 ''wind'':301 ''wing'':298 ''wish'':235 ''word'':17,27,76,99 ''yahweh'':213,263 ''yahweh.rideth'':258 ''yea'':292', NULL, '698');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('703', '2', '703', NULL, 'Maketh the earth empty - That is, will depopulate it, or take away its inhabitants, and its wealth. The word ''earth'' here (  ''arets) is used evidently not to denote the whole world, but the land to which the prophet particularly refers - the land of Judea. It should have been translated the land (see Joel 1:2). It is possible, however, that the word here may be intended to include so much of the nations that surrounded Palestine as were allied with it, or as were connected with it in the desolations under Nebuchadnezzar.And turneth it upside down - Margin, ''Perverteth the face thereof.'' That is, everything is thrown into confusion; the civil and religious institutions are disorganized, and derangement everywhere prevails.And scattereth abroad ... - This was done in the invasion by the Chaldeans by the carrying away of the inhabitants into their long and painful captivity.', NULL, NULL, '''1'':54 ''2'':55 ''abroad'':121 ''alli'':79 ''aret'':22 ''away'':12,134 ''captiv'':143 ''carri'':133 ''chaldean'':130 ''civil'':110 ''confus'':108 ''connect'':85 ''denot'':28 ''depopul'':8 ''derang'':117 ''desol'':90 ''disorgan'':115 ''done'':124 ''earth'':3,20 ''empti'':4 ''everyth'':104 ''everywher'':118 ''evid'':25 ''face'':100 ''howev'':59 ''includ'':68 ''inhabit'':14,137 ''institut'':113 ''intend'':66 ''invas'':127 ''joel'':53 ''judea'':44 ''land'':34,42,51 ''long'':140 ''maketh'':1 ''margin'':97 ''may'':64 ''much'':70 ''nation'':73 ''nebuchadnezzar.and'':92 ''pain'':142 ''palestin'':76 ''particular'':39 ''perverteth'':98 ''possibl'':58 ''prevails.and'':119 ''prophet'':38 ''refer'':40 ''religi'':112 ''scattereth'':120 ''see'':52 ''surround'':75 ''take'':11 ''thereof'':101 ''thrown'':106 ''translat'':49 ''turneth'':93 ''upsid'':95 ''use'':24 ''wealth'':17 ''whole'':30 ''word'':19,62 ''world'':31', NULL, '703');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('704', '2', '704', NULL, 'O Lord, thou art my God - The prophet speaks, not in his own name, but in the name of the people that would be delivered from bondage. The sense is, that Yahweh had manifested himself as their covenant-keeping God; and that in view of his faithfulness in keeping his promises, they now had demonstration that he was their God.I will exalt thee - A form of expression often used to denote praise Psalm 118:28; Psalm 145:1, meaning that the worshipper would exalt God in the view of his own mind, or would regard him as above all other beings and objects.For thou hast done wonderful things - On the meaning of the Hebrew,   pel'' - ''wonderful,'' see the note at Isaiah 9:6.Thy counsels of old - Which were formed and revealed long since. The counsels referred to are those respecting the delivery of his people from bondage, which had been expressed even long before their captivity commenced, and which would be now completely and triumphantly fulfilled.Are faithfulness - Have been brought to pass; do not fail.And truth - Hebrew,   ''omen - whence our word Amen. Septuagint, &#x393;&#x3b5;&#x3bd;&#x3bf;&#x3b9;&#x3c4;&#x3bf;  Genoito - ''Let it be.'' The word denotes that the purposes of God were firm, and would certainly be fulfilled.', NULL, NULL, '''1'':79 ''118'':75 ''145'':78 ''28'':76 ''6.thy'':124 ''9'':123 ''amen'':183 ''art'':4 ''be'':102 ''bondag'':27,148 ''brought'':171 ''captiv'':157 ''certain'':201 ''commenc'':158 ''complet'':164 ''counsel'':125,136 ''coven'':39 ''covenant-keep'':38 ''deliv'':25 ''deliveri'':143 ''demonstr'':56 ''denot'':72,191 ''done'':107 ''even'':153 ''exalt'':63,85 ''express'':68,152 ''fail.and'':176 ''faith'':48,168 ''firm'':198 ''form'':66,130 ''fulfil'':203 ''fulfilled.are'':167 ''genoito'':185 ''god'':6,41,86,196 ''god.i'':61 ''hast'':106 ''hebrew'':115,178 ''isaiah'':122 ''keep'':40,50 ''let'':186 ''long'':133,154 ''lord'':2 ''manifest'':34 ''mean'':80,112 ''mind'':93 ''name'':14,18 ''note'':120 ''o'':1 ''objects.for'':104 ''often'':69 ''old'':127 ''omen'':179 ''pass'':173 ''pel'':116 ''peopl'':21,146 ''prais'':73 ''promis'':52 ''prophet'':8 ''psalm'':74,77 ''purpos'':194 ''refer'':137 ''regard'':96 ''respect'':141 ''reveal'':132 ''see'':118 ''sens'':29 ''septuagint'':184 ''sinc'':134 ''speak'':9 ''thee'':64 ''thing'':109 ''thou'':3,105 ''triumphant'':166 ''truth'':177 ''use'':70 ''view'':45,89 ''whenc'':180 ''wonder'':108,117 ''word'':182,190 ''worshipp'':83 ''would'':23,84,95,161,200 ''yahweh'':32', NULL, '704');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('705', '2', '705', NULL, 'In that day shall this song be sung - By the people of God, on their restoration to their own land.We have a strong city - Jerusalem. This does not mean that it was then strongly fortified, but that God would guard it, and that thus it would be strong. Jerusalem was easily capable of being strongly fortified Psalm 25:2; but the idea here is, that Yahweh would be a protector, and that this would constitute its strength.Salvation will God appoint for walls - That is, he will himself be the defender of his people in the place of walls and bulwarks. A similar expression occurs in Isaiah 60:18 (see also Jeremiah 3:23, and Zechariah 2:5).Bulwarks - This word means properly bastions, or ramparts. The original means properly a pomoerium, or antemural defense; a space without the wall of a city raised up like a small wall. The Syriac renders it, Bar shuro, - ''Son of a wall,'' meaning a small wall. It was usually a breastwork, or heap of earth thrown up around the city, that constituted an additional defense, so that if they were driven from that they could retreat within the walls.', NULL, NULL, '''18'':108 ''2'':59,116 ''23'':113 ''25'':58 ''3'':112 ''5'':117 ''60'':107 ''addit'':180 ''also'':110 ''antemur'':133 ''appoint'':80 ''around'':174 ''bar'':153 ''bastion'':123 ''breastwork'':167 ''bulwark'':100,118 ''capabl'':52 ''citi'':24,142,176 ''constitut'':75,178 ''could'':191 ''day'':3 ''defend'':90 ''defens'':134,181 ''driven'':187 ''earth'':171 ''easili'':51 ''express'':103 ''fortifi'':35,56 ''god'':13,38,79 ''guard'':40 ''heap'':169 ''idea'':62 ''isaiah'':106 ''jeremiah'':111 ''jerusalem'':25,49 ''land.we'':20 ''like'':145 ''mean'':29,121,128,159 ''occur'':104 ''origin'':127 ''peopl'':11,93 ''place'':96 ''pomoerium'':131 ''proper'':122,129 ''protector'':70 ''psalm'':57 ''rais'':143 ''rampart'':125 ''render'':151 ''restor'':16 ''retreat'':192 ''see'':109 ''shall'':4 ''shuro'':154 ''similar'':102 ''small'':147,161 ''son'':155 ''song'':6 ''space'':136 ''strength.salvation'':77 ''strong'':23,34,48,55 ''sung'':8 ''syriac'':150 ''thrown'':172 ''thus'':44 ''usual'':165 ''wall'':82,98,139,148,158,162,195 ''within'':193 ''without'':137 ''word'':120 ''would'':39,46,67,74 ''yahweh'':66 ''zechariah'':115', NULL, '705');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('706', '2', '706', NULL, 'In that day - In that future time when the Jews would be captive in Babylon, and when they would sigh for deliverance (see the note at Isaiah 26:1). This verse might have been connected with the previous chapter, as it refers to the same event, and then this chapter would have more appropriately commenced with the poem or song which begins in Isaiah 27:2.With his sore - Hebrew,   haqashah - ''Hard.'' Septuagint, &#x3a4;&#x3b7;&#x3c2; &#x3b1;&#x3b3;&#x3b9;&#x3b1;&#x3bd;  Ten hagian - ''Holy.'' The Hebrew means a sword that is hard, or well-tempered and trusty.And great, and strong sword - The sword is an emblem of war, and is often used among the Hebrews to denote war (see Genesis 27:40; Leviticus 26:25). It is also an emblem of justice or punishment, as punishment then, as it is now in the Turkish dominions, was often inflicted by the sword Deuteronomy 32:41-42; Psalm 7:12; Hebrews 11:37. Here, if it refers to the overthrow of Babylon and its tyrannical king, it means that God would punish them by the armies of the Medes, employed as his sword or instrument. Thus in Psalm 17:13, David prays, ''Deliver my soul from the wicked, which is thy sword'' (compare the notes at Isaiah 10:5-6).Leviathan -   livyathan. The Septuagint renders this, &#x3a4;&#x3b7;&#x3bd; &#x3b4;&#x3c1;&#x3b1;&#x3ba;&#x3bf;&#x3bd;&#x3c4;&#x3b1;  Ten drakonta - ''The dragon.'' The word ''leviathan'' is probably derived from   lavah in Arabic, to weave, to twist (Gesenius); and literally means, "the twisted animal." The word occurs in six places in the Old Testament, and is translated in Job 3:8, ''mourning,'' Margin, ''leviathan;'' in Job 41:1, ''leviathan'' - in which chapter is an extended description of the animal; in Psalm 74:14, it is rendered ''leviathan,'' and seems to be applied to Pharaoh; and in Psalm 104:26, and in the passage before us, where it is twice also rendered ''leviathan.'' Bochart (Hierez. ii. 5. 16-18) has gone into an extended argument to show that by the leviathan the crocodile is intended; and his argument is in my view conclusive. On this subject, Bochart, Dr. Good (on Job 41), and Robinson''s Calmet, may be consulted.The crocodile is a natural inhabitant of the Nile and of other Asiatic and African rivers; is of enormous voracity and strength, as well as of fleetness in swimming; attacks mankind and all animals with prodigious impetuosity; and is furnished with a coat of mail so scaly and callous that it will resist the force of a musket ball in every part except under the belly. It is, therefore, an appropriate image by which to represent a fierce and cruel tyrant. The sacred writers were accustomed to describe kings and tyrants by an allusion to strong and fierce animals. Thus, in Ezekiel 29:3-5, the dragon, or the crocodile of the Nile, represents Pharaoh; in Ezekiel 22:2, Pharaoh is compared to a young lion, and to a whale in the seas; in Psalm 74:13-14, Pharaoh is compared to the dragon, and to the leviathan. In Daniel 7, the four monarchs that should arise are likened to four great beasts. In Revelation 12, Rome, the new Babylon, is compared to a great red dragon.In the place before us, I suppose that the reference is to Babylon; or to the king and tyrant that ruled there, and that had oppressed the people of God. But among commentators there has been the greatest variety of explanation. As a "specimen" of the various senses which commentators often assign to passages of Scripture, we may notice the following views which have been taken of this passage. The Chaldee Paraphrast regards the leviathans, which are twice mentioned, as referring, the first one to some king like Pharaoh, and the second to a king like Sennacherib. rabbi Moses Haccohen supposes that the word denotes the most select or valiant of the rulers, princes, and commanders that were in the army of the enemy of the people of God. Jarchi supposes that by the first-mentioned leviathan is meant Egypt, by the second Assyria, and by the dragon which is in the sea, he thinks "Tyre" is intended.Aben Ezra supposes that by the dragon in the sea, Egypt is denoted. Kimchi supposes that this will be fulfilled only in the times of the Messiah, and that the sea monsters mentioned here are Gog and Magog - and that these denote the armies of the Greeks, the Saracens, and the inhabitants of India. Abarbanel supposes that the Saracens, the Roman empire, and the other kingdoms of Gentiles, are intended by these sea monsters. Jerome, Sanctius, and some others suppose that "Satan" is denoted by the leviathan. Brentius supposes that this was fulfilled in the day of Pentecost when Satan was overcome by the preaching of the gospel. Other Christian interpreters have supposed, that by the leviathan first mentioned "Mahomet" is intended; by the second, "heretics;" and by the dragon in the sea, "Pagan India." Luther understood it of Assyria and Egypt; Calvin supposes that the description properly applies to the king of Egypt, but that under this image other enemies of the church are embrace', NULL, NULL, '''-14'':492 ''-18'':315 ''-42'':147 ''-5'':459 ''-6'':210 ''1'':29,265 ''10'':208 ''104'':295 ''11'':152 ''12'':150,520 ''13'':190,491 ''14'':280 ''16'':314 ''17'':189 ''2'':473 ''2.with'':66 ''22'':472 ''25'':117 ''26'':28,116,296 ''27'':65,113 ''29'':457 ''3'':257,458 ''32'':145 ''37'':153 ''40'':114 ''41'':146,264,348 ''5'':209,313 ''7'':149,505 ''74'':279,490 ''8'':258 ''abarbanel'':743 ''accustom'':440 ''african'':369 ''allus'':448 ''also'':120,307 ''among'':105,562 ''anim'':241,276,388,453 ''appli'':289,837 ''appropri'':54,425 ''arab'':230 ''argument'':321,334 ''aris'':511 ''armi'':176,651,732 ''asiat'':367 ''assign'':582 ''assyria'':675,828 ''attack'':384 ''babylon'':15,162,524,543 ''ball'':413 ''beast'':517 ''begin'':62 ''belli'':420 ''bochart'':310,343 ''brentius'':776 ''callous'':