INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('773', '2', '773', NULL, 'In the beginning ... Zedekiah - Probably a gloss put into the margin to explain "the same year," from where it has crept into the text.Gibeon - A city of priests Joshua 21:17. Hananiah was probably a priest as well as a prophet. He chose either a Sabbath or a new moon, that he might confront Jeremiah not only in the presence of the priests, but also of all the people. He used Jeremiah 28:2 the solemn formula which claims direct inspiration.', NULL, NULL, '''17'':31 ''2'':74 ''21'':30 ''28'':73 ''also'':65 ''begin'':3 ''chose'':43 ''citi'':26 ''claim'':79 ''confront'':54 ''crept'':21 ''direct'':80 ''either'':44 ''explain'':13 ''formula'':77 ''gloss'':7 ''hananiah'':32 ''inspir'':81 ''jeremiah'':55,72 ''joshua'':29 ''margin'':11 ''might'':53 ''moon'':50 ''new'':49 ''peopl'':69 ''presenc'':60 ''priest'':28,36,63 ''probabl'':5,34 ''prophet'':41 ''put'':8 ''sabbath'':46 ''solemn'':76 ''text.gibeon'':24 ''use'':71 ''well'':38 ''year'':16 ''zedekiah'':4', NULL, '773');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('722', '2', '722', NULL, 'Put me in remembrance - That is, urge all the arguments in your own defense which you can urge. State everything in self-vindication which can be stated. The language here is taken from the practice of courts when a cause is on trial; and God urges them on their side, to urge all in self-vindication which they can urge. On his part, he alleged that the princes and rulers of the nation had sinned Isaiah 43:27; that the whole nation had transgressed Isaiah 43:23-24, and that for this they were justly punished Isaiah 43:28. He here urges them to advance all in self-defense which they could - if they could pretend that He had forgotten anything; that they had merits which he had not considered; or that he had charged them with crime with undue severity.Let us plead together - Hebrew, ''Let us be judged together'' (see the note at Isaiah 41:1).Declare thou, that thou mayest be justified - That you may show that you are just, or righteous; that you may demonstrate that you are unjustly accused of crime, and punished with undue severity.', NULL, NULL, '''-24'':90 ''1'':160 ''23'':89 ''27'':80 ''28'':101 ''41'':159 ''43'':79,88,100 ''accus'':186 ''advanc'':107 ''alleg'':67 ''anyth'':124 ''argument'':10 ''caus'':41 ''charg'':138 ''consid'':133 ''could'':115,118 ''court'':38 ''crime'':141,188 ''declar'':161 ''defens'':14,112 ''demonstr'':181 ''everyth'':20 ''forgotten'':123 ''god'':46 ''hebrew'':148 ''isaiah'':78,87,99,158 ''judg'':152 ''just'':97 ''justifi'':167 ''languag'':30 ''let'':149 ''may'':170,180 ''mayest'':165 ''merit'':128 ''nation'':75,84 ''note'':156 ''part'':65 ''plead'':146 ''practic'':36 ''pretend'':119 ''princ'':70 ''punish'':98,190 ''put'':1 ''remembr'':4 ''righteous'':177 ''ruler'':72 ''see'':154 ''self'':23,57,111 ''self-defens'':110 ''self-vind'':22,56 ''sever'':193 ''severity.let'':144 ''show'':171 ''side'':51 ''sin'':77 ''state'':19,28 ''taken'':33 ''thou'':162,164 ''togeth'':147,153 ''transgress'':86 ''trial'':44 ''undu'':143,192 ''unjust'':185 ''urg'':7,18,47,53,62,104 ''us'':145,150 ''vindic'':24,58 ''whole'':83', NULL, '722');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('723', '2', '723', NULL, 'Yet now hear - This should be read in immediate connection with the previous chapter. ''Notwithstanding you have sinned, yet now hear the gracious promise which is made in regard to your deliverance.''', NULL, NULL, '''chapter'':14 ''connect'':10 ''deliver'':32 ''gracious'':23 ''hear'':3,21 ''immedi'':9 ''made'':27 ''notwithstand'':15 ''previous'':13 ''promis'':24 ''read'':7 ''regard'':29 ''sin'':18 ''yet'':1,19', NULL, '723');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('724', '2', '724', NULL, 'Thus saith the Lord to his anointed - This is a direct apostrophe to Cyrus, though it was uttered not less than one hundred and fifty years before Babylon was taken by him. The word ''anointed'' is that which is usually rendered "Messiah" (  mashyach), and here is rendered by the Septuagint, &#x3a4;&#x3c9; &#x3c7;&#x3c1;&#x3b9;&#x3c3;&#x3c4;&#x3c9; &#x3bc;&#x3bf;&#x3c5; &#x39a;&#x3c5;&#x3c1;&#x3c9;  To christo mou Kuro - ''To Cyrus, my Christ,'' i. e, my anointed. It properly means "the anointed," and was a title which was commonly given to the kings of Israel, because they were set apart to their office by the ceremony of anointing, who hence were called &#x3bf;&#x3b9; &#x3c7;&#x3c1;&#x3c5;&#x3c3;&#x3c4;&#x3bf;&#x3b9; &#x39a;&#x3c5;&#x3c1;&#x3b9;&#x3bf;&#x3c5;  hoi christoi Kuriou - ''The anointed of the Lord'' 1 Samuel 2:10, 1 Samuel 2:35; 1 Samuel 12:3, 1 Samuel 12:5; 1 Samuel 16:6; 1 Samuel 24:7, 1 Samuel 24:11; 1 Samuel 26:9, 1 Samuel 26:11, 1 Samuel 26:23; 2 Samuel 1:14, 2 Samuel 1:16; 2 Samuel 19:22-23. There is no evidence that the Persian kings were inaugurated or consecrated by oil, but this is an appellation which was common among the Jews, and is applied to Cyrus in accordance with their usual mode of designating kings. It means here that God had solemnly set apart Cyrus to perform an important public service in his cause. It does not mean that Cyrus was a man of piety, or a worshipper of the true God, of which there is no certain evidence, but that his appointment as king was owing to the arrangement of God''s providence, and that he was to be employed in accomplishing his purposes. The title does not designate holiness of character, but appointment to an office.Whose right hand I have holden - Margin, ''Strengthened.'' Lowth, ''whom I hold fast by the right hand.'' The idea seems to be, that God had upheld, sustained, strengthened him as we do one who is feeble, by taking his right hand (see the notes at Isaiah 41:13; Isaiah 42:6)To subdue nations before him - For a general account of the conquests of Cyrus, see the notes at Isaiah 41:2. It may be added here, that ''besides his native subjects, the nations which Cyrus subdued, and over which he reigned, were the Cilicians, Syrians, Paphlagonians, Cappadocians, Phrygians, Lydians, Carians, Phenicians, Arabians, Babylonians, Assyrians, Bactrians, Saeae, and Maryandines. Xenophon describes his empire as extending from the Mediterranean and Egypt to the Indian Ocean, and from Ethiopia to the Euxine Sea, and conveys a physical idea of its extent by observing that the extremities were difficult to inhabit, from opposite causes - some from excess of heat, and others from excess of cold; some from a scarcity of water, and others from too great abundance.'' - (Pictorial Bible.)And I will loose the loins of kings - The ancients dressed in a large, loose, flowing robe thrown over an under-garment or tunic, which was shaped to the body. The outer robe was girded with a sash when they toiled, or labored, or went to war, or ran. Hence, ''to gird up the loins'' is indicative of preparation for a journey, for labor, or for war. To unloose the girdle, or the loins, was indicative of a state of rest, repose, or feebleness; and the phrase here means that God would so order it in his providence that the kings would be unprepared to meet him, or so feeble that they would not be able to resist him (compare Job 38:3; Jeremiah 1:17). See also Job 12:21 :He poureth contempt upon princes,And weakeneth the strength of the mighty;Margin, more correctly, ''Looseth the girdle of the strong.'' There was a literal fulfillment of this in regard to Belshazzar, king of Babylon, when the city was taken by Cyrus. When the hand came forth on the walls of his palace, and the mysterious finger wrote his condemnation, it is said, ''Then the king''s countenance was changed, and his thoughts troubled him, so that the joints of his loins were loosed, and his knees smote one against the other'' Daniel 5:6. The Vulgate renders this, ''I will turn the backs of kings.''To open before him the two-leaved gates, and the gates shall not be shut - The folding gates of a city, or a palace. It so happened in the scene of revelry which prevailed in Babylon when Cyrus took it, that the gates within the city which led from the streets to the river were left open. The city was not only enclosed with walls, but there were walls within the city on each side of the river Euphrates with gates, by which the inhabitants had access to the water of the river. Had not these gates been left open on that occasion, contrary to the usual custom, the Persians would have been shut up in the bed of the river, and could all have been destroyed. It also happened in the revelry of that night, that the gates of the palace were left open, so that there was access to every part of the city. Herodotus (i. 191) says, ''If the besieged had been aware of the designs of Cyrus, or had discovered the project before its actual accomplishment, they might', NULL, NULL, '''-23'':158 ''1'':106,110,114,118,122,126,130,134,138,142,148,152,581 ''10'':109 ''11'':133,141 ''12'':116,120,586 ''13'':327 ''14'':149 ''16'':124,153 ''17'':582 ''19'':156 ''191'':853 ''2'':108,112,146,150,154,351 ''21'':587 ''22'':157 ''23'':145 ''24'':128,132 ''26'':136,140,144 ''3'':117,579 ''35'':113 ''38'':578 ''41'':326,350 ''42'':329 ''5'':121,681 ''6'':125,330,682 ''7'':129 ''9'':137 ''abl'':572 ''abund'':453 ''access'':781,844 ''accomplish'':265,874 ''accord'':190 ''account'':339 ''actual'':873 ''add'':355 ''also'':584,823 ''among'':181 ''ancient'':465 ''anoint'':7,35,62,67,93,102 ''apart'':85,206 ''apostroph'':12 ''appel'':177 ''appli'':186 ''appoint'':245,277 ''arabian'':382 ''arrang'':252 ''assyrian'':384 ''awar'':860 ''babylon'':28,622,730 ''babylonian'':383 ''back'':691 ''