INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('735', '2', '735', NULL, 'Thus saith the Lord - That is, in view of the fact that the kingdom of God was to come at no distant period. Yahweh states what was necessary to prepare themselves for it, and what was the character which he demanded of those who were disposed to embrace its offers, and who would be admitted to its privileges.Keep ye judgment - Margin, ''Equity.'' Break off your sins, and be holy. A somewhat similar declaration was made by John the Baptist when he announced the coming of the Messiah: ''Repent ye, for the kingdom of heaven is at hand'' Matthew 3:2. The general idea is, that it was not only appropriate that the prospect of his coming and his near approach should lead them to a holy life, but it was necessary in order that they might escape his indignation.My salvation is near to come - It is to be borne in mind that this was regarded as addressed to the Jews in exile in Babylon, and there is probably a primary reference in the words to the deliverance which they were about to experience from their long and painful captivity. But at the same time the language is appropriate to the coming of the kingdom of God under the Messiah, and the whole scope of the passage requires us to understand it of that event. Language similar to this occurs frequently in the New Testament, where the sacred writers seem to have had this passage in their eye (see Matthew 3:2; Luke 21:31; Romans 13:11; compare Isaiah 62:1-11). It is to be regarded, therefore, as having a reference to the future coming of the Messiah - perhaps as designed to describe the series of deliverances which were to close the painful bondage in Babylon, and to bring the people of God to perfect freedom, and to the full fruition of his favor. Though the actual coming of the Messiah at the time of the exile was at a period comparatively remote, yet the commencement of the great work of their deliverance was near at hand. They were soon to be rescued, and this rescue was to be but the first in the train of deliverances that would result in the entire redemption of the people of God, and was to be the public pledge that all that he had promised of the redemption of the world should be certainly effected.To be revealed - To be made known; to be publicly manifested.', NULL, NULL, '''-11'':262 ''1'':261 ''11'':257 ''13'':256 ''2'':100,251 ''21'':253 ''3'':99,250 ''31'':254 ''62'':260 ''actual'':318 ''address'':157 ''admit'':55 ''announc'':82 ''approach'':120 ''appropri'':110,198 ''babylon'':164,297 ''baptist'':79 ''bondag'':295 ''born'':149 ''break'':63 ''bring'':300 ''captiv'':189 ''certain'':402 ''charact'':38 ''close'':292 ''come'':19,84,116,144,201,276,319 ''commenc'':337 ''compar'':258,333 ''declar'':73 ''deliver'':177,288,344,368 ''demand'':41 ''describ'':284 ''design'':282 ''dispos'':46 ''distant'':22 ''effected.to'':403 ''embrac'':48 ''entir'':374 ''equiti'':62 ''escap'':137 ''event'':224 ''exil'':162,328 ''experi'':183 ''eye'':247 ''fact'':11 ''favor'':315 ''first'':363 ''freedom'':307 ''frequent'':230 ''fruition'':312 ''full'':311 ''futur'':275 ''general'':102 ''god'':16,206,304,380 ''great'':340 ''hand'':97,348 ''heaven'':94 ''holi'':69,126 ''idea'':103 ''indignation.my'':139 ''isaiah'':259 ''jew'':160 ''john'':77 ''judgment'':60 ''kingdom'':14,92,204 ''known'':409 ''languag'':196,225 ''lead'':122 ''life'':127 ''long'':186 ''lord'':4 ''luke'':252 ''made'':75,408 ''manifest'':413 ''margin'':61 ''matthew'':98,249 ''messiah'':87,209,279,322 ''might'':136 ''mind'':151 ''near'':119,142,346 ''necessari'':28,131 ''new'':233 ''occur'':229 ''offer'':50 ''order'':133 ''pain'':188,294 ''passag'':216,244 ''peopl'':302,378 ''perfect'':306 ''perhap'':280 ''period'':23,332 ''pledg'':387 ''prepar'':30 ''primari'':170 ''privileges.keep'':58 ''probabl'':168 ''promis'':393 ''prospect'':113 ''public'':386,412 ''redempt'':375,396 ''refer