INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('738', '2', '738', NULL, 'Behold, the Lord''s hand is not shortened - On the meaning of this phrase, see the notes at Isaiah 50:2.Neither his ear heavy, that it cannot hear - On the meaning of this phrase, see the notes at Isaiah 6:10.', NULL, NULL, '''10'':41 ''2.neither'':21 ''50'':20 ''6'':40 ''behold'':1 ''cannot'':27 ''ear'':23 ''hand'':5 ''hear'':28 ''heavi'':24 ''isaiah'':19,39 ''lord'':3 ''mean'':11,31 ''note'':17,37 ''phrase'':14,34 ''see'':15,35 ''shorten'':8', NULL, '738');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('739', '2', '739', NULL, 'Arise - This is evidently addressed to the church, or to Zion regarded as the seat of the church. It is represented as having been in a state of affliction and calamity (compare the notes at Isaiah 3:26; Isaiah 52:1-2). She is now called on to arise from the dust, and to impart to others the rich privileges which were conferred on her.Shine - (  ''ory). Lowth renders this, ''Be thou enlightened.'' Margin, ''Be enlightened, for thy light cometh.'' Noyes, ''Enjoy light.'' Septuagint &#x3a6;&#x3c9;&#x3c4;&#x3b9;&#x3b6;&#x3bf;&#x3c5; &#x3c6;&#x3c9;&#x3c4;&#x3b9;&#x3b6;&#x3bf;&#x3c5;  Photizou photizou - ''Be enlightened; be enlightened, O Jerusalem.'' Herder renders it, ''Be light.'' Vitringa regards the expression as equivalent to this, ''pass into a state of light. That is, enjoy light thyself, and impart it freely to others, Gesenius renders it, ''Shine, be bright; that is, be surrounded and resplendent with light.'' The idea probably is this, ''rise now from a state of obscurity and darkness. Enter into light; enter into times of prosperity.'' It is not so much a command to impart light to others as it is to be encompassed with light and glory. It is the language of prophecy rather than of command; a call rather to participate in the light that was shining than to impart it to others. The Septuagint and the Chaldee here add the name ''Jerusalem,'' and regard it as addressed directly to her.Thy light is come - On the word ''light,'' see the notes at Isaiah 58:8, Isaiah 58:10. The light here referred to is evidently that of the gospel; and when the prophet says that that light ''is come,'' he throws himself into future times, and sees in vision the Messiah as having already come, and as pouring the light of salvation on a darkened church and world (compare the notes at Isaiah 9:2).And the glory of the Lord - There is refer once here, doubtless, to the Shechinah or visible splendor which usuallv accompanied the manifestations of God to his people (see the notes at Isaiah 4:5). As Yahweh manifested himself in visible glory to the Israelites during their journey to the promised land, so he would manifest himself in the times of the Messiah as the glorious protector and guide of his people. The divine character and perfections would be manifested like the sun rising over a darkened world.Is risen upon thee - As the sun rises. The word used here (  zarach) is commonly applied to the rising of the sun Genesis 32:31; Exodus 22:2; 2 Samuel 23:4; Psalm 104:22. The comparison of the gospel to the sun rising upon a dark world is exceedingly beautiful, and often occurs in the Bible (compare Malachi 4:2; Luke 1:78, margin.)Upon thee - Upon thee, in contradistinction from other nations and people. The gospel shed its first beams of glory on Jerusalem.', NULL, NULL, '''-2'':42 ''1'':41,448 ''10'':241 ''104'':419 ''2'':298,413,414,446 ''22'':412,420 ''23'':416 ''26'':38 ''3'':37 ''31'':410 ''32'':409 ''4'':332,417,445 ''5'':333 ''52'':40 ''58'':237,240 ''78'':449 ''8'':238 ''9'':297 ''accompani'':319 ''add'':213 ''address'':5,221 ''afflict'':29 ''alreadi'':277 ''appli'':401 ''aris'':1,49 ''beam'':467 ''beauti'':436 ''bibl'':442 ''bright'':127 ''calam'':31 ''call'':46,191 ''chalde'':211 ''charact'':373 ''church'':8,18,289 ''come'':227,262,278 ''cometh'':79 ''command'':164,189 ''common'':400 ''compar'':32,292,443 ''comparison'':422 ''confer'':63 ''contradistinct'':456 ''dark'':149,432 ''darken'':288,385 ''direct'':222 ''divin'':372 ''doubtless'':310 ''dust'':52 ''encompass'':175 ''enjoy'':81,113 ''enlighten'':72,75,87,89 ''enter'':150,153 ''equival'':102 ''evid'':4,248 ''exceed'':435 ''exodus'':411 ''express'':100 ''first'':466 ''freeli'':119 ''futur'':267 ''genesi'':408 ''gesenius'':122 ''glori'':179,301,340,469 ''glorious'':364 ''god'':323 ''gospel'':252,425,463 ''guid'':367 ''her.shine'':65 ''her.thy'':224 ''herder'':92 ''idea'':137 ''impart'':55,117,166,203 ''isaiah'':36,39,236,239,296,331 ''israelit'':343 ''jerusalem'':91,216,471 ''journey'':346 ''land'':350 ''languag'':183 ''light'':78,82,96,110,114,135,152,167,177,197,225,231,243,260,283 ''like'':379 ''lord'':304 ''lowth'':67 ''luke'':447 ''malachi'':444 ''manifest'':321,336,354,378 ''margin'':73,450 ''messiah'':274,361 ''much'':162 ''name'':215 ''nation'':459 ''note'':34,234,294,329 ''noy'':80 ''o'':90 ''obscur'':147 ''occur'':439 ''often'':438 ''ori'':66 ''other'':57,121,169,206 ''particip'':194 ''pass'':105 ''peopl'':326,370,461 ''perfect'':375 ''photizou'':84,85 ''pour'':281 ''privileg'':60 ''probabl'':138 ''promis'':349 ''propheci'':185 ''prophet'':256 ''prosper'':157 ''protector'':365 ''psalm'':418 ''rather'':186,192 ''refer'':245,307 ''regard'':12,98,218 ''render'':68,93,123 ''repres'':21 ''resplend'':133 ''rich'':59 ''rise'':141,382,393,404,429 ''risen'':387 ''salvat'':285 ''samuel'':415 ''say'':257 ''seat'':15 ''see'':232,270,327 ''septuagint'':83,208 ''shechinah'':313 ''shed'':464 ''shine'':125,200 ''splendor'':316 ''state'':27,108,145 ''sun'':381,392,407,428 ''surround'':131 ''thee'':389,452,454 ''thi'':77 ''thou'':71 ''throw'':264 ''thyself'':115 ''time'':155,268,358 ''upon'':388,430,451,453 ''use'':396 ''usuallv'':318 ''visibl'':315,339 ''vision'':272 ''vitringa'':97 ''word'':230,395 ''world'':291,433 ''world.is'':386 ''would'':353,376 ''yahweh'':335 ''zarach'':398 ''zion'':11', NULL, '739');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('740', '2', '740', NULL, 'The Spirit of the Lord God - Hebrew, The Spirit of the Lord Yahweh.'' The Chaldee renders this, ''The prophet said, the spirit of prophecy from the presence of Yahweh God is upon me.'' The Syriac, ''The Spirit of the Lord God.'' The Septuagint, &#x3a0;&#x3bd;&#x3b5;&#x3c5;&#x3bc;&#x3b1; &#x39a;&#x3c5;&#x3c1;&#x3b9;&#x3bf;&#x3c5;  Pneuma Kuriou - ''The Spirit of the Lord,'' omitting the word   ''adonay. So Luke quotes it in Luke 4:18. That this refers to the Messiah is abundantly proved by the fact that the Lord Jesus expressly applied it to himself (see Luke 4:21). Rosenmuller, Gesenius, and some others, suppose that it refers to Isaiah himself, and that the idea is, that the prophet proclaims his commission as authorized to administer consolation to the suffering exiles in Babylon. It cannot be denied that the language is such as may be applied in a subordinate sense to the office of the prophet, and that the work of the Redeemer is here described in terms derived from the consolation and deliverance afforded to the long-suffering exiles. But in a much higher sense it refers to the Messiah, and received an entire completion only as applied to him and to his work. Even Grotius, who has been said to ''find Christ nowhere in the Old Testament,'' remarks, ''Isaiah here speaks of himself, as the Chaldee observes; but in him we see not an obscure image of Christ.'' Applied to the Redeemer, it refers to the time when, having been baptized and set apart to the work of the Mediatorial office, he began publicly to preach (see Luke 4:21). The phrase ''the Spirit of Yahweh is upon me,'' refers to the fact; that he had been publicly consecrated to his work by the Holy Spirit descending on him at Iris baptism Matthew 3:16; John 1:32, and that the Spirit of God had been imparted to him ''without measure'' to endow him for his great office (John 3:34; see the notes at Isaiah 11:2).Because the Lord hath anointed me - The word rendered ''hath anointed'' (  mashach), is that from which the word Messiah is derived (see the notes at Isaiah 45:1). prophets and kings were set apart to their high office, by the ceremony of pouring oil on their heads; and the idea here is that God had set apart the Messiah for the office which he was to bear, and had abundantly endowed him with the graces of which the anointing oil was an emblem. The same language is used in reference to the Messiah in Psalm 45:7 (compare Hebrews 1:9).To preach good tidings - On the meaning of the word (  bas''ar) rendered here ''to preach good tidings,'' see the notes at Isaiah 52:7. The Septuagint renders it, &#x395;&#x3c5;&#x3b1;&#x3b3;&#x3b3;&#x3b5;&#x3bb;&#x3b9;&#x3c3;&#x3b1;&#x3c3;&#x3b8;&#x3b1;&#x3b9;  Euangelisasthai - ''To evangelize,'' to preach the gospel.Unto the meek - The word rendered ''meek'' (  anaviym) properly denotes the afflicted, the distressed, the needy. The word ''meek'' means those who are patient in the reception of injuries, and stands opposed to revengeful and irascible. This is by no means the sense of the word here. It refers to those who were borne down by calamity in any form, and would be particularly applicable to those who had been sighing in a long captivity in Babylon. It is not improperly rendered by the Septuagint by the word &#x3c0;&#x3c4;&#x3c9;&#x3c7;&#x3bf;&#x3b9;&#x3c2;  ptochois, ''poor,'' and in like manner by Luke Luk 4:18; and the idea is, that the Redeemer came to bring a joyful message to those who were oppressed and borne down by the evils of poverty and calamity (compare Matthew 11:5).To bind up the broken-hearted - (See the notes at Isaiah 1:6). The broken-hearted are those who are deeply afflicted and distressed on any account. It may be either on account of their sins, or of captivity and oppressionk, or of the loss of relations and friends. The Redeemer came that he might apply the balm of consolation to all such hearts, and give them joy and peace. A similar form of expression occurs in Psalm 147:3 :He healeth the broken in heart,And bindeth up their wounds.To proclaim liberty to the captives - This evidently is language which is taken from the condition of the exiles in their long captivity in Babylon. The Messiah would accomplish a deliverance for those who were held under the captivity of sin similar to that of releasing captives from long and painful servitude. The gospel does not at once, and by a mere exertion of power, open prison doors, and restore captives to liberty. But it accomplishes an effect analogous to this: it releases the mind captive under sin; and it will finally open all prison doors, and by preventing crime will prevent the necessity of prisons, and will remove all the sufferings which are now endured in confinement as the consequence of crime. It may be remarked further, that the word here rendered ''liberty'' (  deror) is a word which is properly applicable to the year of Jubilee, when all were permitred to go free Leviticus 25:10 : ''And ye shall hallow the fiftieth year, and proclaim liberty (  deror) throughout', NULL, NULL, '''1'':298,357,429,609 ''10'':845 ''11'':328,595 ''147'':677 ''16'':296 ''18'':62,564 ''2'':329 ''21'':87,261 ''25'':844 ''3'':295,321,678 ''32'':299 ''34'':322 ''4'':61,86,260,563 ''45'':356,425 ''5'':596 ''52'':454 ''6'':610 ''7'':426,455 ''9'':430 ''abund'':70,399 ''accomplish'':717,764 ''account'':625,631 ''administ'':114 ''adonay'':54 ''afflict'':477,620 ''afford'':163 ''analog'':767 ''anaviym'':473 ''anoint'':334,340,408 ''apart'':245,363,386 ''appli'':80,134,188,230,654 ''applic'':530,830 ''ar'':442 ''author'':112 ''babylon'':121,542,713 ''balm'':656 ''baptism'':293 ''baptiz'':242 ''bas'':441 ''bear'':396 ''began'':254 ''bind'':598 ''bindeth'':686 ''born'':519,584 ''bring'':574 ''broken'':602,613,682 ''broken-heart'':601,612 ''calam'':522,592 ''came'':572,650 ''cannot'':123