INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('868', '2', '868', NULL, 'Come and let us return unto the Lord - These words depend closely on the foregoing. They are words put into their mouth by God Himself, with which or with the like, they should exhort one another to return to God. Before, when God smote them, they had gone to Assyria; now they should turn to Him, owning, not only that He who "tore" has the power and the will to "heal" them, but that He tore, "in order to" heal them; He smote them, "in order to" bind them up. This closeness of connection is expressed in the last words; literally, "smite He and He will bind us up." "He smiteth the putrefaction of the misdeed; He healeth the pain of the wound. Physicians do this; they cut; they smite; they heal; they arm themselves in order to strike; they carry steel, and come to cure."They are not content to return singly or to be saved alone. Each encourageth another to repentance, as before to evil. The dry bones, scattered on the face of the earth, reunite. There is a general movement among those "who sat in darkness and the shadow of death," to return together to Him, who is the source of life.', NULL, NULL, '''alon'':158 ''among'':184 ''anoth'':36,161 ''arm'':134 ''assyria'':50 ''bind'':88,107 ''bone'':170 ''carri'':141 ''close'':12,92 ''come'':1,144 ''connect'':94 ''content'':150 ''cure'':146 ''cut'':128 ''dark'':189 ''death'':194 ''depend'':11 ''dri'':169 ''earth'':177 ''encourageth'':160 ''evil'':167 ''exhort'':34 ''express'':96 ''face'':174 ''forego'':15 ''general'':182 ''god'':24,40,43 ''gone'':48 ''heal'':71,80,132 ''healeth'':118 ''last'':99 ''let'':3 ''life'':205 ''like'':31 ''liter'':101 ''lord'':8 ''misde'':116 ''mouth'':22 ''movement'':183 ''one'':35 ''order'':78,86,137 ''own'':57 ''pain'':120 ''physician'':124 ''power'':66 ''put'':19 ''putrefact'':113 ''repent'':163 ''return'':5,38,152,196 ''reunit'':178 ''sat'':187 ''save'':157 ''scatter'':171 ''shadow'':192 ''singl'':153 ''smite'':102,130 ''smiteth'':111 ''smote'':44,83 ''sourc'':203 ''steel'':142 ''strike'':139 ''togeth'':197 ''tore'':63,76 ''turn'':54 ''unto'':6 ''us'':4,108 ''word'':10,18,100 ''wound'':123', NULL, '868');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('869', '2', '869', NULL, 'When I would have healed Israel - God begins anew by appealing to Israel, that all which He had done to heal them, had but served to make their sin more evident, and "that," from highest to lowest, as to all manners and ways of sin. When the flash of God''s light on the sinner''s conscience enlightens it not, it only discloses its darkness. The name "Israel" includes the whole people; the names, Ephraim and Samaria, probably are meant to designate the chief among them, Ephraim having been their royal tribe, and being the chief tribe among them; Samaria being their royal city. The sins, which Hoses denounces in this chapter, are chiefly the sins of the great, which, from them, had spread among the people. Whatever healing methods God had used, whether through the teaching of the prophets or through His own fatherly chastisements, they "would not hearken nor be amended, but ran on still more obstinately in their evil courses. The disease prevailed against the remedy, and was irritated by it, so that the remedy served only to "lay open" the extent of its malignity, and to shew that there was worse in it, than did at first appear" . Paul says of all human nature. "When the commandment came, sin revived" Romans 7:9.Apart from grace, the knowledge of good only enhances evil. : "So, when God, made Man, present and visible, willed to "heal Israel," then that iniquity of the Jews and wickedness of the Scribes and Pharisees was discovered, whereof this iniquity of Ephraim and wickedness of Samaria was a type. For an evil spirit goaded them to mock, persecute, blaspheme the Teacher of repentance who, together with the word of preaching, did works, such as none other man did. For Christ pleased them not, a Teacher of repentance, persuading to poverty, a Pattern of humility, a Guide to meekness, a Monitor to mourn for sins, a Proclaimer of righteousness, a Requirer of mercy, a Praiser of purity of heart, a Rewarder of peace, a Consoler of those who suffered persecution for righteousness'' sake. Why did they reject, hate, persecute, Him who taught thus? Because they loved all contrary thereto, and wished for a Messiah, who should exalt them in this world, and disturb the peace of nations, until he should by war subdue to their empire all the rest of the world, build for them on earth a Jerusalem of gold and gems, and fulfill their covetousness in all things of this sort.This their mind He once briefly expressed; "How can ye believe which receive honor one of another, and seek not the honor which cometh from God only?" John 5:24. They persecuted Him then who willed to heal them, as madmen strike the physician offering them medicine, nor did they cease, until they required Him their King to be crucified. Thus was the "iniquity of Ephraim and wickedness of Samaria discovered," yet filled up by them; and so they filled up the measure of their fathers, and discovered and testified, that they were of the same mind with their fathers. In all these things they "committed falsehood," lying against, their King whom they denied, and accused as seditious."For they - (i. e. all of them) commit falsehood Falsehood was the whole habit and tissue of their lives. : "They dealt falsely in all their doings both with God and man, being hypocritical and false in all their words and doings, given to fraud and deceit, from the highest to the lowest." Night and day; in silence and in open violence; "within," where all seemed guarded and secure, and "without," in open defiance of law and public justice; these deeds of wrong went on in an unceasing round. In the night, "the thief cometh in," breaking into people''s houses and pillaging secretly; "a troop of robbers spoileth without," spreading their ravages far and wide, and desolating without resistance. It was all one state of anarchy, violence, and disorganization.', NULL, NULL, '''24'':447 ''5'':446 ''7'':216 ''9.apart'':217 ''accus'':533 ''amend'':153 ''among'':85,98,125 ''anarchi'':661 ''anew'':9 ''anoth'':434 ''appeal'':11 ''appear'':202 ''begin'':8 ''believ'':428 ''blasphem'':275 ''break'':631 ''briefli'':423 ''build'':398 ''came'':212 ''ceas'':468 ''chapter'':112 ''chastis'':146 ''chief'':84,96 ''chiefli'':114 ''christ'':296 ''citi'':104 ''cometh'':441,629 ''command'':211 ''commit'':523,543 ''conscienc'':57 ''consol'':340 ''contrari'':363 ''cours'':163 ''covet'':412 ''crucifi'':477 ''dark'':65 ''day'':590 ''dealt'':556 ''deceit'':581 ''deed'':615 ''defianc'':608 ''deni'':531 ''denounc'':109 ''design'':82 ''desol'':652 ''disclos'':63 ''discov'':253,488,505 ''diseas'':165 ''disorgan'':664 ''disturb'':378 ''do'':561,576 ''done'':19 ''e'':539 ''earth'':402 ''empir'':391 ''enhanc'':225 ''enlighten'':58 ''ephraim'':75,87,258,483 ''evid'':31 ''evil'':162,226,268 ''exalt'':372 ''express'':424 ''extent'':185 ''fals'':557,570 ''falsehood'':524,544,545 ''far'':648 ''father'':145,503,517 ''fill'':490,497 ''first'':201 ''flash'':48 ''fraud'':579 ''fulfil'':410 ''gem'':408 ''given'':577 ''goad'':270 ''god'':7,50,131,229,443,564 ''gold'':406 ''good'':223 ''grace'':219 ''great'':119 ''guard'':601 ''guid'':312 ''habit'':549 ''hate'':353 ''heal'':5,21,129,237,455 ''hearken'':150 ''heart'':334 ''highest'':35,584 ''honor'':431,439 ''hose'':108 ''hous'':635 ''human'':207 ''humil'':310 ''hypocrit'':568 ''includ'':69 ''iniqu'':241,256,481 ''irrit'':172 ''israel'':6,13,68,238 ''jerusalem'':404 ''jew'':244 ''john'':445 ''justic'':613 ''king'':474,528 ''knowledg'':221 ''law'':610 ''lay'':182 ''lie'':525 ''light'':52 ''live'':554 ''love'':361 ''lowest'':37,587 ''made'':230 ''madmen'':458 ''make'':27 ''malign'':188 ''man'':231,293,566 ''manner'':41 ''meant'':80 ''measur'':500 ''medicin'':464 ''meek'':314 ''merci'':328 ''messiah'':369 ''method'':130 ''mind'':420,514 ''mock'':273 ''monitor'':316 ''mourn'':318 ''name'':67,74 ''nation'':382