INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('877', '2', '877', NULL, 'The word of the Lord that came to Joel - Joel, like Hosea, mentions the name of his father only, and then is silent about his extraction, his tribe, his family. He leaves even the time when he lived, to be guessed at. He would be known only, as the instrument of God. "The word of the Lord came to" him (see the note at Hosea 1:1), and he willed simply to be the voice which uttered it. He was "content to live under the eyes of God, and, as to people, to be known only in what concerned their salvation." But this he declares absolutely, that the Word of God came to him; in order that we may give faith to his prophecy, being well assured that what he predicted, would come to pass. So the Saviour Himself says, ""My words shall not pass away" Matthew 24:35. For truth admits of nothing false, and what God saith, will certainly be. For "He confirmeth the word of His servant, and performeth the counsel of His messengers" Isaiah 44:26. The prophet claimeth belief then, as speaking not out of his own heart, but out of the mouth of the Lord speaking in the Spirit." Joel signifies, "The Lord is God." It owns that God who had revealed Himself, is alone the God. The prophet''s name itself, embodied the truth, which, after the miraculous answer to Elijah''s prayer, all the people confessed, "The Lord He is the God, The Lord He is the God." Pethuel signifies, "persuaded of God." The addition of his father''s name distinguished the prophet from others of that name, as the son of Samuel, of king Uzziah, and others.', NULL, NULL, '''1'':66,67 ''24'':148 ''26'':180 ''35'':149 ''44'':179 ''absolut'':106 ''addit'':263 ''admit'':152 ''alon'':221 ''answer'':236 ''assur'':127 ''away'':146 ''belief'':184 ''came'':7,58,112 ''certain'':161 ''claimeth'':183 ''come'':133 ''concern'':99 ''confess'':244 ''confirmeth'':165 ''content'':81 ''c