INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('879', '2', '879', NULL, 'For, behold - The prophet by the word, "for," shows that he is about to explain in detail, what he had before spoken of, in sum. By the word, "behold," he stirs up our minds for something great, which he is to set before our eyes, and which we should not be prepared to expect or believe, unless he solemnly told us, "Behold." As the detail, then, of what goes before, the prophecy contains all times of future judgment on those who should oppose God, oppress His Church and people, and sin against Him in them and all times of His blessing upon His own people, until the Last Day. And this it gives in imagery, partly describing nearer events of the same sort, as in the punishments of Tyre and Sidon, such as they endured from the kings of Assyria, from Nebuchadnezzar, from Alexander; partly using these, His earlier judgments, as representatives of the like punishments against the like sins unto the end.In those days and in that time - The whole period of which the prophet had been speaking, was the time from which God called His people to repentance, to the Day of Judgment. The last division of that time was from the beginning of the Gospel unto that Day. He fixes the occasion of which he speaks by the words, "when I shall bring again the captivity of Judah and Jerusalem." This form was used, before there was any general dispersion of the nation. For all captivity of single members of the Jewish people had this sore calamity, that it severed them from the public worship of God, and exposed them to idolatry. So David complains, "they have driven me out this day from abiding in the inheritance of the Lord, saying, go serve other gods" 1 Samuel 26:19. The restoration then of single members, or of smaller bodies of captives, was, at that time, an unspeakable mercy. It was the restoration of those shut out from the worship of God; and so was an image "of the deliverance from the bondage of corruption into the glorious liberty of the sons of God" Romans 8:21, or of any "return" of those who had gone astray, "to the Shepherd and Bishop of their souls 1 Peter 2:25. The grievous captivity of the Jews, now, is to Satan, whose servants they made themselves, when they said, "we have no king but Caesar; His Blood be upon us and upon our children." Their blessed deliverance will be "from the power of Satan unto God" Acts 26:18. It is certain from Paul Romans 11:26, that there shall be a complete conversion of the Jews, before the end of the world, as indeed has always been believed. This shall probably be shortly before the end of the world, and God would here say, "when I shall have brought to an end the "captivity of Judah and Jerusalem," i. e., of that people "to whom were the promises" Romans 9:4, and shall have delivered them from the bondage of sin and from blindness to light and freedom in Christ, then will I gather all nations to judgment."', NULL, NULL, '''1'':299,378 ''11'':436 ''18'':429 ''19'':302 ''2'':380 ''21'':359 ''25'':381 ''26'':301,428,437 ''4'':502 ''8'':358 ''9'':501 ''abid'':287 ''act'':427 ''alexand'':144 ''alway'':457 ''assyria'':140 ''astray'':369 ''begin'':205 ''behold'':2,29,62 ''believ'':56,459 ''bishop'':374 ''bless'':101,416 ''blind'':515 ''blood'':407 ''bodi'':312 ''bondag'':345,510 ''bring'':226 ''brought'':480 ''caesar'':405 ''calam'':260 ''call'':186 ''captiv'':229,249,314,384,485 ''certain'':432 ''children'':414 ''christ'':521 ''church'':87 ''complain'':278 ''complet'':443 ''contain'':73 ''convers'':444 ''corrupt'':347 ''david'':277 ''day'':109,165,193,211,285 ''deliv'':506 ''deliver'':342,417 ''describ'':117 ''detail'':17,65 ''dispers'':243 ''divis'':198 ''driven'':281 ''e'':491 ''earlier'':149 ''end'':450,467,483 ''end.in'':163 ''endur'':135 ''event'':119 ''expect'':54 ''explain'':15 ''expos'':272 ''eye'':45 ''fix'':213 ''form'':235 ''freedom'':519 ''