INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('894', '2', '894', NULL, 'The word of the Lord that came to Micah ... which he saw - No two of the prophets authenticate their prophecy in exactly the same way. They, one and all, have the same simple statement to make, that this which they say is from God, and through them. A later hand, had it added the titles, would have formed all upon one model. The title was an essential part of the prophetic book, as indicating to the people afterward, that it was not written after the event. It was a witness, not to the prophet whose name it bears, but to God. The prophet bare witness to God, that what he delivered came from Him. The event bare witness to the prophet, that he said this truly, in that he knew what God alone could know - futurity. Micah blends in one the facts, that he related in words given him by God, what he had seen spread before him in prophetic vision. His prophecy was, in one, "the word of the Lord which came to him," and "a sight which he saw."Micah omits all mention of his father. His great predecessor was known as Micaiah son of Imlah. Micah, a villager, would be known only by the name of his native village. So Nahum names himself "the Elkoshite;" Jonah is related to be a native "of Gath-hepher;" Elijah, the Tishbite, a sojourner in the despised Gilead 1 Kings 17:1; Elisha, of Abelmeholah; Jeremiah, of Anathoth; forerunners of Him, and taught by His Spirit who willed to be born at Bethlehem, and, since this, although too little to be counted "among the thousands of Judah," was yet a royal city and was to be the birthplace of the Christ, was known only as Jesus of Nazareth, "the Nazarene." No prophet speaks of himself, or is spoken of, as born at Jerusalem, "the holy city." They speak of themselves with titles of lowliness, not of greatness.Micah dates his prophetic office from kings of Judah only, as the only kings of the line appointed by God. Kings of Israel are mentioned in addition, only by prophets of Israel. He names Samaria first, because, its iniquity being most nearly full, its punishment was the nearest.', NULL, NULL, '''1'':239,242 ''17'':241 ''abelmeholah'':245 ''add'':53 ''addit'':353 ''afterward'':78 ''alon'':133 ''although'':267 ''among'':273 ''anathoth'':248 ''appoint'':344 ''authent'':18 ''bare'':104,117 ''bear'':98 ''bethlehem'':263 ''birthplac'':288 ''blend'':138 ''book'':72 ''born'':261,311 ''came'':7,112,173 ''christ'':291 ''citi'':282,316 ''could'':134 ''count'':272 ''date'':328 ''deliv'':111 ''despis'':237 ''elijah'':230 ''elisha'':243 ''elkoshit'':218 ''essenti'':67 ''event'':86,116 ''exact'':22 ''fact'':142 ''father'':188 ''first'':362 ''forerunn'':249 ''form'':58 ''full'':369 ''futur'':136 ''gath'':228 ''gath-heph'':227 ''gilead'':238 ''given'':148 ''god'':44,101,107,132,151,346 ''great'':190 ''greatness.micah'':327 ''hand'':50 ''hepher'':229 ''holi'':315 ''imlah'':198 ''indic'':74 ''iniqu'':365 ''israel'':349,358 ''jeremiah'':246 ''jerusalem'':313 ''jesus'':296 ''jonah'':219 ''judah'':277,335 ''king'':240,333,340,347 ''knew'':130 ''know'':135 ''known'':193,204,293 ''later'':49 ''line'':343 ''littl'':269 ''lord'':5,171 ''lowli'':324 ''make'':36 ''mention'':185,351 ''micah'':9,137,182,199 ''micaiah'':195 ''model'':62 ''nahum'':214 ''name'':96,208,215,360 ''nativ'':211,225 ''nazaren'':300 ''nazareth'':298 ''near'':368 ''nearest'':374 ''offic'':331 ''omit'':183 ''one'':27,61,140,166 ''part'':68 ''peopl'':77 ''predecessor'':191 ''propheci'':20,163 ''prophet'':17,71,94,103,121,160,302,330,356 ''punish'':371 ''relat'':145,221 ''royal'':281 ''said'':124 ''samaria'':361 ''saw'':12,181 ''say'':41 ''seen'':155 ''sight'':178 ''simpl'':33 ''sinc'':265 ''sojourn'':234 ''son'':196 ''speak'':303,318 ''spirit'':256 ''spoken'':308 ''spread'':156 ''statement'':34 ''taught'':253 ''thousand'':275 ''tishbit'':232 ''titl'':55,64,322 ''truli'':126 ''two'':14 ''upon'':60 ''vi