INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('899', '2', '899', NULL, 'Hear ye now what the Lord saith - If ye will not hear the rebuke of man, hear now at last the word of God. "Arise thou, Micah." The prophet was not willing to be the herald of woe to his people; but had to arise at the bidding of God, that he might not "be rebellious like that rebellious house" Ezekiel 2:8. Stand up; as one having all authority to rebuke, and daunted by none. He muses the hearer, as shewing it to be a very grave urgent matter, to be done promptly, urgently, without delay. "Contend thou before (better, as in the English margin with) the mountains." Since man, who had reason, would not use his reason, God calls the mountains and hills, who Romans 8:20 unwillingly, as it were, had been the scenes of their idolatry, as if he would say (Lap.), "Insensate though ye be, ye are more sensible than Israel, whom I endowed with sense; for ye feel the voice and command of God your Creator and obey Him; they do not. I cite you, to represent your guilty inhabitants, that, through you, they may hear My complaint to be just, and own themselves guilty, repent, and ask forgiveness." "The altars and idols, the blood of the sacrifices, the bones and ashes upon them, with unuttered yet clear voice, spoke of the idolatry and guilt of the Jews, and so pronounced God''s charge and expostulation to be just. Ezekiel is bidden, in like way, to prophesy against "the mountains of Israel Ezekiel 6:2-5, "I will bring a sword upon you, and I will destroy your high places, and your altars shall be desolate." : "Lifeless nature without voice tells the glory of God; without ears it hears what the Lord speaks." Psalm 19:3; Luke 19:40.', NULL, NULL, '''-5'':262 ''19'':301,304 ''2'':62,261 ''20'':129 ''3'':302 ''40'':305 ''6'':260 ''8'':63,128 ''altar'':207,279 ''aris'':25,45 ''ash'':218 ''ask'':204 ''author'':70 ''better'':101 