INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('904', '2', '904', NULL, 'The burden - On the word "burden" see the note at Nahum 1:1.Which Habakkuk the prophet did see - The prophet''s name signifies "strong embrace." The word in its intensive form is used both of God''s enfolding the soul within His tender supporting love , and of man clinging and holding fast to divine wisdom Proverbs 4:8. It fits in with the subject of his prophecy, faith, cleaving fast to God amid the perplexities of things seen. Dion.: "He who is spiritually Habakkuk, cleaving fast to God with the arms of love, or enfolding Him after the manner of one holily wrestling, until he is blessed, enlightened, and heard by Him, is the seer here." "Let him who would in such wise fervidly embrace God and plead with Him as a friend, praying earnestly for the deliverance and consolation of himself and others, but who sees not as yet, that his prayer is heard, make the same holy plaint, and appeal to the clemency of the Creator." (Jer. Abarbanel has the like: "He strengthens himself in pleading his cause with God as to the prosperity of Nebuchadnezzar as if he were joined with God for the cause of his people" Preface to Ezekiel). "He is called ''embrace'' either because of his love to the Lord; or because he engages in a contest and strife and (so to speak) wrestling with God." For no one with words so bold ventured to challenge God to a discussion of His justice and to say to Him, "Why, in human affairs and the government of this world is there so great injustice?"The prophet - The title, "the prophet," is added only to the names of Habakkuk, Haggai, Zechariah. Habakkuk may have added it to his name instead because he prominently expostulates with God, like the Psalmists, and does not speak in the name of God to the people. The title asserts that he exercised the pastoral office of the prophets, although not directly in this prophecy.Did see - Cyril: "God multiplied visons, as is written Hosea 12:10, and Himself spoke to the prophets, disclosing to them beforehand what should be, and all but exhibiting them to sight, as if already present. But that they determined not to speak from their own, but rather transmit to us the words from God, he persuades us at the outset, naming himself a prophet, and showing himself full of the grace belonging thereto."', NULL, NULL, '''1'':12 ''1.which'':13 ''10'':344 ''12'':343 ''4'':57 ''8'':58 ''abarbanel'':170 ''add'':277,289 ''affair'':258 ''alreadi'':367 ''although'':328 ''amid'':73 ''appeal'':162 ''arm'':91 ''assert'':318 ''beforehand'':354 ''belong'':405 ''bless'':107 ''bold'':239 ''burden'':2,6 ''call'':207 ''caus'':180,198 ''challeng'':242 ''cleav'':69,85 ''clemenc'':165 ''cling'':49 ''consol'':140 ''contest'':223 ''creator'':168 ''cyril'':335 ''deliver'':138 ''determin'':372 ''dion'':79 ''direct'':330 ''disclos'':351 ''discuss'':246 ''divin'':54 ''earnest'':135 ''either'':209 ''embrac'':25,125,208 ''enfold'':38,95 ''engag'':220 ''enlighten'':108 ''exercis'':321 ''exhibit'':361 ''expostul'':298 ''ezekiel'':204 ''faith'':68 ''fast'':52,70,86 ''fervid'':124 ''fit'':60 ''form'':31 ''friend'':133 ''full'':401 ''god'':36,72,88,126,182,195,232,243,300,312,336,387 ''govern'':261 ''grace'':404 ''great'':268 ''habakkuk'':14,84,283,286 ''haggai'':284 ''heard'':110,155 ''hold'':51 ''holi'':159 ''holili'':102 ''hosea'':342 ''human'':257 ''injustic'':269 ''instead'':294 ''intens'':30 ''jer'':169 ''join'':193 ''justic'':249 ''let'':117 ''like'':173,301 ''lord'':216 ''love'':45,93,213 ''make'':156 ''man'':48 ''manner'':99 ''may'':287 ''multipli'':337 ''nahum'':11 ''name'':22,281,293,310,394 ''nebuchadnezzar'':188 ''note'':9 ''offic'':324 ''one'':101,235 ''other'':144 ''outset'':393 ''pastor'':323 ''peopl'':201,315 ''perplex'':75 ''persuad'':389 ''plaint'':160 ''plead'':128,178 ''pray'':134 ''prayer'':153 ''prefac'':202 ''present'':368 ''promin'':297 ''p