INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('911', '2', '911', NULL, 'In the seventh month, in the one and twentieth day of the month - This was the seventh day of the feast of tabernacles, Leviticus 23:34, Leviticus 23:36, Leviticus 23:40-42. and its close. The eighth day was to be a sabbath, with its  "holy convocation," but the commemorative feast, the dwelling in booths, in memory of God''s bringing them out of Egypt, was to last seven days. The close then of this feast could not but revive their sadness at the glories of their first deliverance by God''s "mighly hand and outstretched arm," and their present fewness and poverty. This depression could not but bring with it heavy thoughts about the work, in which they were, in obedience to God, engaged; and that, all the more, since Isaiah and Ezekiel had prophesied of the glories of the Christian Church under the symbol of the temple. This despondency Haggai is sent to relieve, owning plainly the reality of its present grounds, but renewing, on God''s part, the pledge of the glories of this second temple, which should be thereafter.', NULL, NULL, '''-42'':33 ''23'':25,28,31 ''34'':26 ''36'':29 ''40'':32 ''arm'':98 ''booth'':56 ''bring'':62,110 ''christian'':143 ''church'':144 ''close'':36,73 ''commemor'':51 ''convoc'':48 ''could'':78,107 ''day'':10,18,39,71 ''deliver'':90 ''depress'':106 ''despond'':152 ''dwell'':54 ''egypt'':66 ''eighth'':38 ''engag'':126 ''ezekiel'':135 ''feast'':21,52,77 ''few'':102 ''first'':89 ''glori'':86,140,176 ''god'':60,92,125,169 ''ground'':165 ''haggai'':153 ''hand'':95 ''heavi'':113 ''holi'':47 ''isaiah'':133 ''last'':69 ''leviticus'':24,27,30 ''memori'':58 ''migh'':94 ''month'':4,13 ''obedi'':123 ''one'':7 ''outstretch'':97 ''own'':158 ''part'':171 ''plain'':159 ''pledg'':173 ''poverti'':104 ''present'':101,164 ''prophesi'':137 ''realiti'':161 ''reliev'':157 ''renew'':167 ''reviv'':81 ''sabba