INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('935', '2', '935', NULL, 'ere incorrect, if they were really so; and it is clear that they were fully disposed, if possible, to do it. The fact, therefore, that it is not done, is clear evidence that they thought it to be correct. The same may be said of the acute pagans who wrote against Christianity. None of them have called in question the correctness of these tables. This is full proof that, in a time when it was easy to understand these tables, they were believed to be correct.2. The evangelists are not responsible for the correctness of these tables. They are responsible only for what was their real and professed object to do. What was that object? It was to prove to the satisfaction of the Jews that Jesus was descended from David, and therefore that there was no argument from his ancestry that he was not the', NULL, NULL, '''acut'':47 ''ancestri'':141 ''argument'':138 ''believ'':83 ''call'':57 ''christian'':52 ''clear'':11,31 ''correct'':39,61,94 ''correct.2'':86 ''david'':131 ''descend'':129 ''dispos'':16 ''done'':29 ''easi'':76 ''ere'':1 ''evangelist'':88 ''evid'':32 ''fact'':23 ''full'':67 ''fulli'':15 ''incorrect'':2 ''jesus'':127 ''jew'':125 ''may'':42 ''none'':53 ''object'':109,115 ''pagan'':48 ''possibl'':18 ''profess'':108 ''proof'':68 ''prove'':119 ''question'':59 ''real'':106 ''realli'':6 ''respons'':91,100 ''said'':44 ''satisfact'':122 ''tabl'':64,80,97 ''therefor'':24,133 ''thought'':35 ''time'':72 ''understand'':78 ''wrote'':50', NULL, '930');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('936', '2', '936', NULL, ' promised Messiah. Now to make this out, it was not necessary, nor would it have conduced to their argument, to have formed a new table of genealogy. All that could be done was to go to the family rec', NULL, NULL, '''argument'':19 ''conduc'':16 ''could'':30 ''done'':32 ''famili'':38 ''form'':22 ''genealog'':27 ''go'':35 ''make'':5 ''messiah'':2 ''necessari'':11 ''new'':24 ''promis'':1 ''rec'':39 ''tabl'':25 ''would'':13', NULL, '930');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('933', '2', '933', NULL, 'ohn 7:42.The son of Abraham - The descendant of Abraham. The promise was made to Abraham also. See Genesis 12:3; Genesis 21:12; compare Hebrews 11:13; Galatians 3:16. The Jews expected that the Messiah would be descended from him; and it was important, therefore, to trace the genealogy up to him also. Though Jesus was of humble birth, yet he was descended from most illustrious ancestors. Abraham, the father of the faithful - "the beauteous model of an Eastern prince," and David, the sweet psalmist of Israel, the conqueror, the magnificent and victorious leader of the people of God, were both among his ancestors. From these two persons, the most eminent for piety, and the most renowned for their excellencies of all the people of antiquity, sacred or profane, the Lord Jesus was descended; an', NULL, NULL, '''11'':27 ''12'':20,24 ''13'':28 ''16'':31 ''21'':23 ''3'':21,30 ''42.the'':3 ''7'':2 ''abraham'':6,10,16,70 ''also'':17,55 ''among'':104 ''ancestor'':69,106 ''antiqu'':128 ''beauteous'':77 ''birth'':61 ''compar'':25 ''conqueror'':91 ''david'':84 ''descend'':8,40,65,136 ''eastern'':81 ''emin'':113 ''excel'':122 ''expect'':34 ''faith'':75 ''father'':72 ''galatian'':29 ''genealog'':51 ''genesi'':19,22 ''god'':101 ''hebrew'':26 ''humbl'':60 ''illustri'':68 ''import'':46 ''israel'':89 ''jesus'':57,134 ''jew'':33 ''leader'':96 ''lord'':133 ''made'':14 ''magnific'':93 ''messiah'':37 ''model'':78 ''ohn'':1 ''peopl'':99,126 ''person'':110 ''pieti'':115 ''princ'':82 ''profan'':131 ''promis'':12 ''psalmist'':87 ''renown'':119 ''sacr'':129 ''see'':18 ''son'':4 ''sweet'':86 ''therefor'':47 ''though'':56 ''trace'':49 ''two'':109 ''victori'':95 ''would'':38 ''yet'':62', NULL, '930');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('934', '2', '934', NULL, 'd though his birth and life were humble, yet they who regard an illustrious descent as of value, may find here all that is to be admired in piety, purity, patriotism, splendor, dignity, and renown.', NULL, NULL, '''admir'':27 ''birth'':4 ''d'':1 ''descent'':15 ''digniti'':33 ''find'':20 ''humbl'':8 ''illustri'':14 ''life'':6 ''may'':19 ''patriot'':31 ''pieti'':29 ''puriti'':30 ''regard'':12 ''renown'':35 ''splendor'':32 ''though'':2 ''valu'':18 ''yet'':9', NULL, '930');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('931', '2', '931', NULL, ' or the Christ, meaning the same thing. The Jews speak of the Messiah; Christians speak of him as the Christ. In ancient times, when kings and priests were set apart to their office, they were anointed with oil, Leviticus 4:3; Leviticus 6:20; Exodus 28:41; Exodus 29:7; 1 Samuel 9:16; 1 Samuel 15:1; 2 Samuel 23:1. To anoint, therefore, means often the same as to consecrate, or to set apart to an office. Hence, those thus set apart are said to be anointed, or to be the anointed of God. It is for this reason that the name is given to the Lord Jesus. Compare the notes at Daniel 9:24. He was set apart by God to be the King, and High Priest, and Prophet of his people. Anointing with oil was, moreover, supposed to be emblematic of the influences of the Holy Spirit; and since God gave him the Spir', NULL, NULL, '''1'':51,55,58,62 ''15'':57 ''16'':54 ''2'':59 ''20'':44 ''23'':61 ''24'':117 ''28'':46 ''29'':49 ''3'':41 ''4'':40 ''41'':47 ''6'':43 ''7'':50 ''9'':53,116 ''ancient'':22 ''anoint'':36,64,89,94,136 ''apart'':30,76,84,121 ''christ'':3,20 ''christian'':14 ''compar'':111 ''consecr'':72 ''daniel'':115 ''emblemat'':144 ''exodus'':45,48 ''gave'':155 ''given'':106 ''god'':96,123,154 ''henc'':80 ''high'':129 ''holi'':150 ''influenc'':147 ''jesus'':110 ''jew'':9 ''king'':25,127 ''leviticus'':39,42 ''lord'':109 ''mean'':4,66 ''messiah'':13 ''moreov'':140 ''name'':104 ''note'':113 ''offic'':33,79 ''often'':67 ''oil'':38,138 ''peopl'':135 ''priest'':27,130 ''prophet'':132 ''reason'':101 ''said'':86 ''samuel'':52,56,60 ''set'':29,75,83,120 ''sinc'':153 ''speak'':10,15 ''spir'':158 ''spirit'':151 ''suppos'':141 ''therefor'':65 ''thing'':7 ''thus'':82 ''time'':23', NULL, '930');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('930', '2', '930', NULL, 'The book of the generation - This is the proper title of the chapter. It is the same as to say, "the account of the ancestry or family, or the genealogical table of Jesus Christ." The phrase is common in Jewish writings. Compare Genesis 5:1. "This is the book of the generations of Adam," i. e., the genealogical table of the family or descendants of Adam. See also Genesis 6:9. The Jews, moreover, as we do, kept such tables of their own families. and it is probable that this was copied from the record of the family of Joseph.Jesus - See the notes at Matthew 1:21.Christ - The word "Christ" is a Greek word, &#x3a7;&#x3c1;&#x3b9;&#x3c3;&#x3c4;&#x3bf;&#x3c2;  Christos, signifying "anointed." The Hebrew word,   mashyach, signifying the same is "Messiah." Hence, Jesus is called either the Messiah,', NULL, NULL, '''1'':45,106 ''21.christ'':107 ''5'':44 ''6'':70 ''9'':71 ''account'':22 ''adam'':54,66 ''also'':68 ''ancestri'':25 ''anoint'':117 ''book'':2,49 ''call'':130 ''chapter'':13 ''christ'':34,110 ''christo'':115 ''common'':38 ''compar'':42 ''copi'':92 ''descend'':64 ''e'':56 ''either'':131 ''famili'':27,62,84,98 ''genealog'':30,58 ''generat'':5,52 ''genesi'':43,69 ''greek'':113 ''hebrew'':119 ''henc'':127 ''jesus'':33,128 ''jew'':73 ''jewish'':40 ''joseph.jesus'':100 ''kept'':78 ''mashyach'':121 ''matthew'':105 ''messiah'':126,133 ''moreov'':74 ''note'':103 ''phrase'':36 ''probabl'':88 ''proper'':9 ''record'':95 ''say'':20 ''see'':67,101 ''signifi'':116,122 ''tabl'':31,59,80 ''titl'':10 ''word'':109,114,120 ''write'':41', NULL, '930');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('932', '2', '932', NULL, 'it without measure John 3:34, so he is especially called "the Anointed of God."The Son of David - The word "son" among the Jews had a great variety of significations. It means literally a son; then a grandson; a descendant: an adopted son; a disciple, or one who is an object of tender affection one who is to us as a son. In this place it means a descendant of David; or one who was of the family of David. It was important to trace the genealogy of Jesus up to David, because the promise had been made that the Messiah should be of his family, and all the Jews expected that it would be so. It would be impossible, therefore, to convince a Jew that Jesus was the Messiah, unless it could be shown that he was descended from David. See Jeremiah 23:5; Psalm 132:10-11, compared with Acts 13:23, and J', NULL, NULL, '''-11'':150 ''10'':149 ''13'':154 ''132'':148 ''23'':145,155 ''3'':5 ''34'':6 ''5'':146 ''act'':153 ''adopt'':43 ''affect'':55 ''among'':23 ''anoint'':13 ''call'':11 ''compar'':151 ''convinc'':124 ''could'':134 ''david'':19,72,81,93,142 ''descend'':41,70,140 ''discipl'':46 ''especi'':10 ''expect'':112 ''famili'':79,107 ''genealog'':88 ''god'':15 ''grandson'':39 ''great'':28 ''import'':84 ''imposs'':121 ''j'':157 ''jeremiah'':144 ''jesus'':90,128 ''jew'':25,111,126 ''john'':4 ''liter'':34 ''made'':99 ''mean'':33,68 ''measur'':3 ''messiah'':102,131 ''object'':52 ''one'':48,56,74 ''place'':66 ''promis'':96 ''psalm'':147 ''see'':143 ''shown'':136 ''signif'':31 ''son'':17,22,36,44,63 ''tender'':54 ''therefor'':122 ''trace'':86 ''unless'':132 ''us'':60 ''varieti'':29 ''without'':2 ''word'':21 ''would'':115,119', NULL, '930');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('940', '2', '940', NULL, 'he world. All these circumstances combined to render this a favorable time to introduce the gospel, and to spread it through the earth; and the providence of God was remarkable in preparing the nations in this manner for the easy and rapid spread of the Christian religion.Wise men - The original word here is &#x3bc;&#x3b1;&#x3b3;&#x3bf;&#x3b9;  magoi, from which comes our word magician, now used in a bad sense, but not so in the original. The persons here denoted were philosophers, priests, or astronomers. They lived chiefly in Persia and Arabia. They were the learned men of the Eastern nations. devoted to astronomy, to religion, and to medicine. They were held in high esteem by the Persian court, were admitted as counsellors, and followed the camps in war to give advice.From the east - It', NULL, NULL, '''admit'':117 ''advice.from'':128 ''arabia'':88 ''astronom'':81 ''astronomi'':100 ''bad'':65 ''camp'':123 ''chiefli'':84 ''christian'':46 ''circumst'':5 ''combin'':6 ''come'':57 ''counsellor'':119 ''court'':115 ''denot'':76 ''devot'':98 ''earth'':23 ''easi'':40 ''east'':130 ''eastern'':96 ''esteem'':111 ''favor'':11 ''follow'':121 ''give'':127 ''god'':28 ''gospel'':16 ''held'':108 ''high'':110 ''introduc'':14 ''learn'':92 ''live'':83 ''magician'':60 ''magoi'':54 ''manner'':37 ''medicin'':105 ''men'':48,93 ''nation'':34,97 ''origin'':50,72 ''persia'':86 ''persian'':114 ''person'':74 ''philosoph'':78 ''prepar'':32 ''priest'':79 ''provid'':26 ''rapid'':42 ''religion'':102 ''religion.wise'':47 ''remark'':30 ''render'':8 ''sens'':66 ''spread'':19,43 ''time'':12 ''use'':62 ''war'':125 ''word'':51,59 ''world'':2', NULL, '931');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('937', '2', '937', NULL, 'When Jesus was born - See the full account of his birth in Luke 2:1-20.In Bethlehem of Judea - Bethlehem, the birthplace of Christ, was a small town about six miles south of Jerusalem. The word "Bethlehem" denotes "house of bread" - perhaps given to the place on account of its great fertility. It was also called Ephrata, a word supposed likewise to signify fertility, Genesis 35:19; Ruth 4:11; Psalm 132:6. It was called the city of David Luke 2:4, because it was the city of his nativity, 1 Samuel 16:1, 1 Samuel 16:18. It was called Bethlehem of Judea, to distinguish it from a town of the same name in Galilee, Joshua 19:15. The soil of Bethlehem was noted for its fertility. Ancient travelers frequently spoke of its productions. The town is situated on an eminence, in the midst of hills and v', NULL, NULL, '''1'':91,94,95 ''1-20.in'':15 ''11'':69 ''132'':71 ''15'':119 ''16'':93,97 ''18'':98 ''19'':66,118 ''2'':14,81 ''35'':65 ''4'':68,82 ''6'':72 ''account'':8,47 ''also'':54 ''ancient'':129 ''bethlehem'':16,19,36,102,123 ''birth'':11 ''birthplac'':21 ''born'':4 ''bread'':40 ''call'':55,75,101 ''christ'':23 ''citi'':77,87 ''david'':79 ''denot'':37 ''distinguish'':106 ''emin'':142 ''ephrata'':56 ''fertil'':51,63,128 ''frequent'':131 ''full'':7 ''galile'':116 ''genesi'':64 ''given'':42 ''great'':50 ''hill'':147 ''hous'':38 ''jerusalem'':33 ''jesus'':2 ''joshua'':117 ''judea'':18,104 ''likewis'':60 ''luke'':13,80 ''midst'':145 ''mile'':30 ''name'':114 ''nativ'':90 ''note'':125 ''perhap'':41 ''place'':45 ''product'':135 ''psalm'':70 ''ruth'':67 ''samuel'':92,96 ''see'':5 ''signifi'':62 ''situat'':139 ''six'':29 ''small'':26 ''soil'':121 ''south'':31 ''spoke'':132 ''suppos'':59 ''town'':27,110,137 ''travel'':130 ''v'':149 ''word'':35,58', NULL, '931');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('949', '2', '949', NULL, 'he word "heaven," or "heavens," as it is in the original, means sometimes the place so called; and sometimes it is, by a figure of speech, put for the Great Being whose residence is there, as in Daniel 4:26; "the Heavens do rule." See also Mark 11:30; Luke 15:18. As that kingdom was one of purity, it was proper that the people should prepare themselves for it by turning from their sins, and by bringing their hearts into a state suitable to his reign.', NULL, NULL, '''11'':48 ''15'':51 ''18'':52 ''26'':40 ''30'':49 ''4'':39 ''also'':46 ''bring'':78 ''call'':17 ''daniel'':38 ''figur'':24 ''great'':30 ''heart'':80 ''heaven'':3,5,42 ''kingdom'':55 ''luke'':50 ''mark'':47 ''mean'':12 ''one'':57 ''origin'':11 ''peopl'':65 ''place'':15 ''prepar'':67 ''proper'':62 ''puriti'':59 ''put'':27 ''reign'':87 ''resid'':33 ''rule'':44 ''see'':45 ''sin'':75 ''sometim'':13,19 ''speech'':26 ''state'':83 ''suitabl'':84 ''turn'':72 ''whose'':32 ''word'':2', NULL, '932');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('938', '2', '938', NULL, 'ales. At present (circa 1880''s) it contains about 200 houses, inhabited chiefly by Christians and Muslims, who live together in peace. About 200 paces east of Bethlehem the place is still shown where our Saviour is supposed to have been born. There is a church and a convent there; and beneath the church a subterranean chapel, which is lighted by 32 lamps, which is said to be the place where was the stable in which Jesus was born, though no certain reliance is to be placed on the tradition which makes this the birthplace of the Saviour.Herod the king - Judea, where our Saviour was born, was a province of the Roman Empire. It was taken about 63 years before his birth by Pompey, and placed under tribute. Herod received his appointment from the Romans, and had reigned at the time of the birth ', NULL, NULL, '''1880'':5 ''200'':10,24 ''32'':62 ''63'':118 ''ale'':1 ''appoint'':132 ''beneath'':52 ''bethlehem'':28 ''birth'':122,144 ''birthplac'':95 ''born'':42,79,106 ''certain'':82 ''chapel'':57 ''chiefli'':13 ''christian'':15 ''church'':46,54 ''circa'':4 ''contain'':8 ''convent'':49 ''east'':26 ''empir'':113 ''herod'':129 ''hous'':11 ''inhabit'':12 ''jesus'':77 ''judea'':101 ''king'':100 ''lamp'':63 ''light'':60 ''live'':19 ''make'':92 ''muslim'':17 ''pace'':25 ''peac'':22 ''place'':30,70,87,126 ''pompey'':124 ''present'':3 ''provinc'':109 ''receiv'':130 ''reign'':138 ''relianc'':83 ''roman'':112,135 ''said'':66 ''saviour'':36,104 ''saviour.herod'':98 ''shown'':33 ''stabl'':74 ''still'':32 ''subterranean'':56 ''suppos'':38 ''taken'':116 ''though'':80 ''time'':141 ''togeth'':20 ''tradit'':90 ''tribut'':128 ''year'':119', NULL, '931');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('939', '2', '939', NULL, 'of Jesus for 34 years. Though he was permitted to be called king, yet he was, in all respects, dependent on the Roman emperor. He was commonly called "Herod the Great" because he had distinguished himself in the wars with Antigonus and his other enemies, and because he had evinced great talents in governing and defending his country, in repairing the temple, and in building and ornamenting the cities of his kingdom. He was, however, as much distinguished for his cruelty and his crimes as he was for his greatness. At this time Augustus was Emperor of Rome. The world was at peace. A large part of the known nations of the earth was united under the Roman emperor. Contact between different nations was easy and safe. Similar laws prevailed. The use of the Greek language was general throughout t', NULL, NULL, '''34'':4 ''antigonus'':41 ''augustus'':94 ''build'':65 ''call'':12,28 ''citi'':69 ''common'':27 ''contact'':120 ''countri'':58 ''crime'':84 ''cruelti'':81 ''defend'':56 ''depend'':20 ''differ'':122 ''distinguish'':35,78 ''earth'':113 ''easi'':125 ''emperor'':24,96,119 ''enemi'':45 ''evinc'':50 ''general'':138 ''govern'':54 ''great'':31,51,90 ''greek'':135 ''herod'':29 ''howev'':75 ''jesus'':2 ''king'':13 ''kingdom'':72 ''known'':109 ''languag'':136 ''larg'':105 ''law'':129 ''much'':77 ''nation'':110,123 ''ornament'':67 ''part'':106 ''peac'':103 ''permit'':9 ''prevail'':130 ''repair'':60 ''respect'':19 ''roman'':23,118 ''rome'':98 ''safe'':127 ''similar'':128 ''talent'':52 ''templ'':62 ''though'':6 ''throughout'':139 ''time'':93 ''unit'':115 ''use'':132 ''war'':39 ''world'':100 ''year'':5 ''yet'':14', NULL, '931');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('941', '2', '941', NULL, ' is not known whether they came from Persia or Arabia. Both countries might be denoted by the word East that is, east from Judea.Jerusalem - The capital of Judea. As there is frequent reference in the New Testament to Jerusalem; as it was the place of the public worship of God; as it was the place where many important transactions in the life of the Saviour occurred, and where he died; and as no Sunday school teacher can intelligently explain the New Testament without some knowledge of that city, it seems desirable to present, a brief description of it. A more full description may be seen in Calmet''s Dictionary, and in the common works on Jewish antiquities. Jerusalem was the capital of the kingdom of Judah, and was built on the line dividing that tribe from the tribe of Benjamin. It was o', NULL, NULL, '''antiqu'':117 ''arabia'':10 ''benjamin'':140 ''brief'':95 ''built'':129 ''calmet'':107 ''came'':6 ''capit'':26,121 ''citi'':88 ''common'':113 ''countri'':12 ''denot'':15 ''descript'':96,102 ''desir'':91 ''dictionari'':109 ''die'':70 ''divid'':133 ''east'':19,22 ''explain'':79 ''frequent'':32 ''full'':101 ''god'':50 ''import'':58 ''intellig'':78 ''jerusalem'':39,118 ''jewish'':116 ''judah'':126 ''judea'':28 ''judea.jerusalem'':24 ''kingdom'':124 ''knowledg'':85 ''known'':3 ''life'':62 ''line'':132 ''mani'':57 ''may'':103 ''might'':13 ''new'':36,81 ''o'':143 ''occur'':66 ''persia'':8 ''place'':44,55 ''present'':93 ''public'':47 ''refer'':33 ''saviour'':65 ''school'':75 ''seem'':90 ''seen'':105 ''sunday'':74 ''teacher'':76 ''testament'':37,82 ''transact'':59 ''tribe'':135,138 ''whether'':4 ''without'':83 ''word'':18 ''work'':114 ''worship'':48', NULL, '931');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('942', '2', '942', NULL, 'nce called "Salem" Genesis 14:18; Psalm 76:2, and in the days of Abraham was the home of Melchizedek. When the Israelites took possession of the promised land, they found this stronghold in the possession of the Jebusites, by whom it was called Jebus or Jebusi, Joshua 18:28.The name "Jerusalem" was probably compounded of the two by changing a single letter, and calling it, for the sake of the sound, "Jerusalem" instead of "Jebusalem." The ancient Salem was probably built on Mount Moriah or Acra - the eastern and western mountains on which Jerusalem was subsequently built. When the Jebusites became masters of the place, they erected a fortress in the southern quarter of the city, which was subsequently called Mount Zion, but which they called "Jebus"; and although the Israelites took posses', NULL, NULL, '''14'':5 ''18'':6,49 ''2'':9 ''28.the'':50 ''76'':8 ''abraham'':15 ''acra'':87 ''although'':130 ''ancient'':78 ''becam'':102 ''built'':82,98 ''call'':2,44,65,121,127 ''chang'':60 ''citi'':117 ''compound'':55 ''day'':13 ''eastern'':89 ''erect'':108 ''fortress'':110 ''found'':31 ''genesi'':4 ''home'':18 ''instead'':74 ''israelit'':23,132 ''jebus'':45,128 ''jebusalem'':76 ''jebusi'':47 ''jebusit'':39,101 ''jerusalem'':52,73,95 ''joshua'':48 ''land'':29 ''letter'':63 ''master'':103 ''melchizedek'':20 ''moriah'':85 ''mount'':84,122 ''mountain'':92 ''name'':51 ''nce'':1 ''place'':106 ''poss'':134 ''possess'':25,36 ''probabl'':54,81 ''promis'':28 ''psalm'':7 ''quarter'':114 ''sake'':69 ''salem'':3,79 ''singl'':62 ''sound'':72 ''southern'':113 ''stronghold'':33 ''subsequ'':97,120 ''took'':24,133 ''two'':58 ''western'':91 ''zion'':123', NULL, '931');
