INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('955', '2', '955', NULL, 'emperate, to produce a state of body and mind quite as bad as to be possessed with the devil?3. We still see a multitude of cases that no man can prove not to be produced by the presence of an evil spirit. Who would attempt to say that some evil being may not have much to do in the case of madmen?4. It afforded an opportunity for Christ to show his power over the enemies of himself and of man, and thus to evince himself qualified to meet every enemy of the race, and triumphantly to redeem his people. He came to destroy the power of Satan, Acts 26:18; Romans 16:20-21.Those which were lunatic - This name is given to the disease from the Latin name of the moon (Luna). It has the same origin in Greek. It was given because it was formerly imagined that the patient was affected by the increase o', NULL, NULL, '''16'':114 ''18'':112 ''20-21.those'':115 ''26'':111 ''3'':20 ''4'':64 ''act'':110 ''affect'':153 ''afford'':66 ''attempt'':46 ''bad'':12 ''bodi'':7 ''came'':103 ''case'':27,61 ''christ'':70 ''destroy'':105 ''devil'':19 ''diseas'':125 ''emper'':1 ''enemi'':77,92 ''everi'':91 ''evil'':42,51 ''evinc'':86 ''former'':147 ''given'':122,143 ''greek'':140 ''imagin'':148 ''increas'':156 ''latin'':128 ''luna'':133 ''lunat'':118 ''madmen'':63 ''man'':30,82 ''may'':53 ''meet'':90 ''mind'':9 ''moon'':132 ''much'':56 ''multitud'':25 ''name'':120,129 ''o'':157 ''opportun'':68 ''origin'':138 ''patient'':151 ''peopl'':101 ''possess'':16 ''power'':74,107 ''presenc'':39 ''produc'':3,36 ''prove'':32 ''qualifi'':88 ''quit'':10 ''race'':95 ''redeem'':99 ''roman'':113 ''satan'':109 ''say'':48 ''see'':23 ''show'':72 ''spirit'':43 ''state'':5 ''still'':22 ''thus'':84 ''triumphant'':97 ''would'':45', NULL, '933');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('956', '2', '956', NULL, 'r the decrease of the moon. The name is still retained, although it is certain that the moon has no effect on the disease. The disease is mentioned only in this place, and in Matthew 17:15. It was probably the falling-sickness or epilepsy, the same as the disease mentioned Mark 9:18-20; Luke 9:39-40.And those that had the palsy - Many infirmities were included under the general name of palsy in the New Testament.1. The paralytic shock, affecting the whole body.2. The hemiplegy, affecting only one side of the body; the most frequent form of the disease.3. The paraplegy, affecting all the system below the neck.4. The catalepsy. This is caused by a contraction of the muscles in the whole or a part of the body, and is very dangerous. The effects are very violent and fatal. For instance, if, wh', NULL, NULL, '''-20'':56 ''15'':37 ''17'':36 ''18'':55 ''39-40.and'':59 ''9'':54,58 ''affect'':82,88,104 ''although'':12 ''bodi'':94,130 ''body.2'':85 ''catalepsi'':112 ''caus'':115 ''certain'':15 ''contract'':118 ''danger'':134 ''decreas'':3 ''diseas'':24,26,51 ''disease.3'':101 ''effect'':21,136 ''epilepsi'':46 ''fall'':43 ''falling-sick'':42 ''fatal'':141 ''form'':98 ''frequent'':97 ''general'':71 ''hemiplegi'':87 ''includ'':68 ''infirm'':66 ''instanc'':143 ''luke'':57 ''mani'':65 ''mark'':53 ''matthew'':35 ''mention'':28,52 ''moon'':6,18 ''muscl'':121 ''name'':8,72 ''neck.4'':110 ''new'':77 ''one'':90 ''palsi'':64,74 ''paralyt'':80 ''paraplegi'':103 ''part'':127 ''place'':32 ''probabl'':40 ''r'':1 ''retain'':11 ''shock'':81 ''sick'':44 ''side'':91 ''still'':10 ''system'':107 ''testament.1'':78 ''violent'':139 ''wh'':145 ''whole'':84,124', NULL, '933');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('953', '2', '953', NULL, 'le away from virtue by suggesting motives to evil. This is the meaning here, and this is now the established sense of the word in the English language.The devil - This word originally means an adversary, or an accuser; then, any one opposed to us; then, an enemy of any kind. It is given in the Scriptures, by way of eminence, to the leader of evil angels - a being characterized as full of subtlety, envy, art, and hatred of mankind. He is known, also, by the name Satan, Job 1:6-12; Matthew 12:26; Beelzebub, Matthew 12:24; the old Serpent, Revelation 12:9; and the Prince of the power of the air, Ephesians 2:2. The name is once given to women 1 Timothy 3:11; "Even so must their wives be grave, not slanderers;" in the original, devils.', NULL, NULL, '''-12'':91 ''1'':89,124 ''11'':127 ''12'':93,97,103 ''2'':115,116 ''24'':98 ''26'':94 ''3'':126 ''6'':90 ''9'':104 ''accus'':38 ''adversari'':35 ''air'':113 ''also'':83 ''angel'':66 ''art'':75 ''away'':2 ''beelzebub'':95 ''character'':69 ''devil'':29,140 ''emin'':60 ''enemi'':47 ''english'':27 ''envi'':74 ''ephesian'':114 ''establish'':20 ''even'':128 ''evil'':9,65 ''full'':71 ''given'':53,121 ''grave'':134 ''hatr'':77 ''job'':88 ''kind'':50 ''known'':82 ''language.the'':28 ''le'':1 ''leader'':63 ''mankind'':79 ''matthew'':92,96 ''mean'':13,33 ''motiv'':7 ''must'':130 ''name'':86,118 ''old'':100 ''one'':41 ''oppos'':42 ''origin'':32,139 ''power'':110 ''princ'':107 ''revel'':102 ''satan'':87 ''scriptur'':56 ''sens'':21 ''serpent'':101 ''slander'':136 ''subtleti'':73 ''suggest'':6 ''timothi'':125 ''us'':44 ''virtu'':4 ''way'':58 ''wive'':132 ''women'':123 ''word'':24,31', NULL, '933');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('952', '2', '952', NULL, 'e of holiness which no art or power could estrange from allegiance. Mark Mar 1:12 says that this occurred "immediately" after his baptism; that is, in his case, as not unfrequently happens, the great temptation followed immediately the remarkable manifestation of the divine approbation and favor. In the clearest manifestations of the divine favor to us we may not be far from most powerful temptations, and then may be the time when it is necessary to be most carefully on our guard.Into the wilderness - See the notes at Matthew 3:1.To be tempted - The word "tempt," in the original, means to try, to endeavor, to attempt to do a thing; then, to try the nature of a thing, as metals by fire; then, to test moral qualities by trying them, to see how they will endure; then, to endeavor to draw peop', NULL, NULL, '''1'':15 ''1.to'':92 ''12'':16 ''3'':91 ''allegi'':12 ''approb'':45 ''art'':6 ''attempt'':107 ''baptism'':24 ''care'':80 ''case'':29 ''clearest'':50 ''could'':9 ''divin'':44,54 ''draw'':142 ''e'':1 ''endeavor'':105,140 ''endur'':137 ''estrang'':10 ''far'':62 ''favor'':47,55 ''fire'':123 ''follow'':37 ''great'':35 ''guard.into'':83 ''happen'':33 ''holi'':3 ''immedi'':21,38 ''manifest'':41,51 ''mar'':14 ''mark'':13 ''matthew'':90 ''may'':59,69 ''mean'':101 ''metal'':121 ''moral'':127 ''natur'':116 ''necessari'':76 ''note'':88 ''occur'':20 ''origin'':100 ''peop'':143 ''power'':8,65 ''qualiti'':128 ''remark'':40 ''say'':17 ''see'':86,133 ''tempt'':94,97 ''temptat'':36,66 ''test'':126 ''thing'':111,119 ''time'':72 ''tri'':103,114,130 ''unfrequ'':32 ''us'':57 ''wilder'':85 ''word'':96', NULL, '933');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('976', '2', '976', NULL, 'ion on which others shall build for heaven, he has laid for himself no foundation, and soon an eternal tempest shall beat around his naked soul. How great will be that fall! What will be his emotions when sinking forever in the flood, and when he realizes that he is destined forever to live and writhe in the peltings of that ceaseless storm that shall beat when "God shall rain snares, fire, and a horrible tempest" upon the wicked!', NULL, NULL, '''around'':23 ''beat'':22,66 ''build'':6 ''ceaseless'':62 ''destin'':51 ''emot'':37 ''etern'':19 ''fall'':32 ''fire'':72 ''flood'':43 ''forev'':40,52 ''foundat'':15 ''god'':68 ''great'':28 ''heaven'':8 ''horribl'':75 ''ion'':1 ''laid'':11 ''live'':54 ''nake'':25 ''other'':4 ''pelt'':59 ''rain'':70 ''realiz'':47 ''shall'':5,21,65,69 ''sink'':39 ''snare'':71 ''soon'':17 ''soul'':26 ''storm'':63 ''tempest'':20,76 ''upon'':77 ''wick'':79 ''writh'':56', NULL, '936');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('951', '2', '951', NULL, 'Then was Jesus led up of the Spirit - Led up by the Spirit. Luke says Luke 4:1 that Jesus was "full of the Holy Spirit;" and it was by his influence, therefore, that he went into the desert to be tempted. It was not done by presumption on the part of Jesus, nor was it for a mere display of his power in resisting temptation; but it was evidently that it might be seen that his holiness was such that he could not be seduced from allegiance to God. When the first Adam was created he was subjected to the temptation of the devil, and he fell and involved the race in ruin: it was not improper that the second Adam - the Redeemer of the race - should be subjected to temptation, in order that it might be seen that there was no power that could alienate him from God; that there was a kind and a degre', NULL, NULL, '''1'':18 ''4'':17 ''adam'':94,122 ''alien'':147 ''allegi'':88 ''could'':83,146 ''creat'':96 ''degr'':158 ''desert'':39 ''devil'':105 ''display'':60 ''done'':46 ''evid'':70 ''fell'':108 ''first'':93 ''full'':22 ''god'':90,150 ''holi'':25,78 ''improp'':118 ''influenc'':32 ''involv'':110 ''jesus'':3,20,53 ''kind'':155 ''led'':4,9 ''luke'':14,16 ''mere'':59 ''might'':73,137 ''order'':134 ''part'':51 ''power'':63,144 ''presumpt'':48 ''race'':112,127 ''redeem'':124 ''resist'':65 ''ruin'':114 ''say'':15 ''second'':121 ''seduc'':86 ''seen'':75,139 ''spirit'':8,13,26 ''subject'':99,130 ''tempt'':42 ''temptat'':66,102,132 ''therefor'':33 ''went'':36', NULL, '933');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('958', '2', '958', NULL, 'And seeing the multitudes - The great numbers that came to attend on his ministry. The substance of this discourse is recorded also in Luke 6. It is commonly called the "Sermon on the Mount." It is not improbable that it was repeated, in substance, on different occasions, and to different people. At those times parts of it may have been omitted, and Luke may have recorded it as it was pronounced on one of those occasions. See the notes at Luke 6:17-20.Went up into a mountain - This mountain, or hill, was somewhere in the vicinity of Capernaum, but where precisely is not mentioned. He ascended the hill, doubtless, because it was more convenient to address the multitude from an eminence than if he were on the same level with them. A hill or mountain is still shown a short distance to the nor', NULL, NULL, '''17-20.went'':83 ''6'':25,82 ''address'':116 ''also'':22 ''ascend'':106 ''attend'':11 ''call'':29 ''came'':9 ''capernaum'':98 ''common'':28 ''conveni'':114 ''differ'':46,50 ''discours'':19 ''distanc'':141 ''doubtless'':109 ''emin'':121 ''great'':6 ''hill'':91,108,133 ''improb'':38 ''level'':129 ''luke'':24,63,81 ''may'':58,64 ''mention'':104 ''ministri'':14 ''mount'':34 ''mountain'':87,89,135 ''multitud'':4,118 ''note'':79 ''number'':7 ''occas'':47,76 ''omit'':61 ''one'':73 ''part'':55 ''peopl'':51 ''precis'':101 ''pronounc'':71 ''record'':21,66 ''repeat'':42 ''see'':2,77 ''sermon'':31 ''short'':140 ''shown'':138 ''somewher'':93 ''still'':137 ''substanc'':16,44 ''time'':54 ''vicin'':96', NULL, '934');
