INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('961', '2', '961', NULL, ' which is really beautiful."In rhetorical descriptions of the delivery of the Sermon on the Mount, we often hear the people represented as looking up to the speaker from the sides of the hill, or listening to him from the plain. This would not be possible with reference to the present locality; for it is too precipitous and too elevated to allow of such a position. The Saviour could have sat there, however, in the midst of his hearers, for it affords a platform amply large enough for the accommodation of the hundreds who may have been present on that occasion."And when he was set - This was the common mode of teaching among the Jews, Luke 4:20; Luke 5:3; John 8:2; Acts 13:14; Acts 16:13.His disciples came unto him - The word "disciples" means "learners," those who are taught. Here it is pu', NULL, NULL, '''13'':127 ''13.his'':131 ''14'':128 ''16'':130 ''2'':125 ''20'':119 ''3'':122 ''4'':118 ''5'':121 ''8'':124 ''accommod'':90 ''act'':126,129 ''afford'':82 ''allow'':62 ''among'':114 ''ampli'':85 ''beauti'':4 ''came'':133 ''common'':110 ''could'':69 ''deliveri'':10 ''descript'':7 ''discipl'':132,138 ''elev'':60 ''enough'':87 ''hear'':19 ''hearer'':79 ''hill'':34 ''howev'':73 ''hundr'':93 ''jew'':116 ''john'':123 ''larg'':86 ''learner'':140 ''listen'':36 ''local'':52 ''look'':24 ''luke'':117,120 ''may'':95 ''mean'':139 ''midst'':76 ''mode'':111 ''mount'':16 ''occas'':101 ''often'':18 ''peopl'':21 ''plain'':41 ''platform'':84 ''posit'':66 ''possibl'':46 ''precipit'':57 ''present'':51,98 ''pu'':148 ''realli'':3 ''refer'':48 ''repres'':22 ''rhetor'':6 ''sat'':71 ''saviour'':68 ''sermon'':13 ''set'':106 ''side'':31 ''speaker'':28 ''taught'':144 ''teach'':113 ''unto'':134 ''word'':137 ''would'':43', NULL, '934');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('960', '2', '960', NULL, 'has two summits, with a slight depression between them, and it is from these projecting points, or horns, that it receives the name given to it. From the top the observer has a full view of the Sea of Tiberias. The most pleasing feature of the landscape is that presented by the diversified appearance of the fields. The different plots of ground exhibit various colors, according to the state. of cultivation: some of them are red, where the land has been newly plowed up, the natural appearance of the soil; others yellow or white, where the harvest is beginning to ripen, or is already ripe; and others green, being covered with grass or springing grain. As they are contiguous to each other, or intermixed, these particolored plots present at some distance an appearance of joyful chequered work,', NULL, NULL, '''accord'':66 ''alreadi'':104 ''appear'':54,87,133 ''begin'':99 ''chequer'':136 ''color'':65 ''contigu'':119 ''cover'':110 ''cultiv'':71 ''depress'':7 ''differ'':59 ''distanc'':131 ''diversifi'':53 ''exhibit'':63 ''featur'':44 ''field'':57 ''full'':34 ''given'':24 ''grain'':115 ''grass'':112 ''green'':108 ''ground'':62 ''harvest'':97 ''horn'':18 ''intermix'':124 ''joy'':135 ''land'':79 ''landscap'':47 ''name'':23 ''natur'':86 ''newli'':82 ''observ'':31 ''other'':91,107 ''particolor'':126 ''pleas'':43 ''plot'':60,127 ''plow'':83 ''point'':16 ''present'':50,128 ''project'':15 ''receiv'':21 ''red'':76 ''ripe'':105 ''ripen'':101 ''sea'':38 ''slight'':6 ''soil'':90 ''spring'':114 ''state'':69 ''summit'':3 ''tiberia'':40 ''top'':29 ''two'':2 ''various'':64 ''view'':35 ''white'':94 ''work'':137 ''yellow'':92', NULL, '934');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('959', '2', '959', NULL, 'thwest of the ancient site of Capernaum, which tradition reports to have been the place where this sermon was delivered, and which is called on the maps the Mount of Beatitudes. The hill commonly believed to be that on which the sermon was delivered is on the road from Nazareth to Tiberias, not far from the latter place. The hill is known by the name of Kuran Huttin, the Horns of Huttin. Of this hill Professor Hackett (Illustrations of Scripture, pp. 323, 324) says: "Though a noontide heat was beating down upon us with scorching power, I could not resist the temptation to turn aside and examine a place for which such a claim has been set up, though I cannot say that I have any great confidence in it. The hill referred to is rocky, and rises steeply to a moderate height above the plain. It ', NULL, NULL, '''323'':82 ''324'':83 ''ancient'':4 ''asid'':105 ''beat'':90 ''beatitud'':31 ''believ'':35 ''call'':24 ''cannot'':121 ''capernaum'':7 ''claim'':114 ''common'':34 ''confid'':128 ''could'':98 ''deliv'':20,44 ''examin'':107 ''far'':54 ''great'':127 ''hackett'':77 ''heat'':88 ''height'':143 ''hill'':33,60,75,132 ''horn'':70 ''huttin'':68,72 ''illustr'':78 ''known'':62 ''kuran'':67 ''latter'':57 ''map'':27 ''moder'':142 ''mount'':29 ''name'':65 ''nazareth'':50 ''noontid'':87 ''place'':15,58,109 ''plain'':146 ''power'':96 ''pp'':81 ''professor'':76 ''refer'':133 ''report'':10 ''resist'':100 ''rise'':138 ''road'':48 ''rocki'':136 ''say'':84,122 ''scorch'':95 ''scriptur'':80 ''sermon'':18,42 ''set'':117 ''site'':5 ''steepli'':139 ''temptat'':102 ''though'':85,119 ''thwest'':1 ''tiberia'':52 ''tradit'':9 ''turn'':104 ''upon'':92 ''us'':93', NULL, '934');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('971', '2', '971', NULL, 'ving for the mercies of the day, and to implore forgiveness for what we have said or done amiss? And when about to lie down again to sleep, not knowing but it may be our last sleep and that we may awake in eternity, what more proper than to commend ourselves to the care of Him "who never slumbers nor sleeps?"3. We should pray in times of embarrassment and perplexity. Such times occur in every man''s life, and it is then a privilege and a duty to go to God and seek his direction. In the most difficult and embarrassed time of the American Revolution, Washington was seen to retire to a grove in the vicinity of the camp at Valley Forge. Curiosity led a man to observe him, and the father of his country was seen on his knees supplicating the God of hosts in prayer. Who can tell how much the liber', NULL, NULL, '''3'':62 ''american'':106 ''amiss'':19 ''awak'':42 ''camp'':121 ''care'':54 ''commend'':50 ''countri'':137 ''curios'':125 ''day'':7 ''difficult'':100 ''direct'':96 ''done'':18 ''duti'':88 ''embarrass'':69,102 ''etern'':44 ''everi'':76 ''father'':134 ''forg'':124 ''forgiv'':11 ''go'':90 ''god'':92,145 ''grove'':115 ''host'':147 ''implor'':10 ''knee'':142 ''know'':30 ''last'':36 ''led'':126 ''liber'':156 ''lie'':24 ''life'':79 ''man'':77,128 ''may'':33,41 ''merci'':4 ''much'':154 ''never'':58 ''observ'':130 ''occur'':74 ''perplex'':71 ''pray'':65 ''prayer'':149 ''privileg'':85 ''proper'':47 ''retir'':112 ''revolut'':107 ''said'':16 ''seek'':94 ''seen'':110,139 ''sleep'':28,37,61 ''slumber'':59 ''supplic'':143 ''tell'':152 ''time'':67,73,103 ''valley'':123 ''vicin'':118 ''ving'':1 ''washington'':108', NULL, '935');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('966', '2', '966', NULL, 'Take heed that ye do not your alms - The word "alms" here denotes liberality to the poor and needy. In the margin, as in the best editions of the Greek it is "righteousness;" either referring to almsgiving as eminently a righteous act, or more probably including all that is specified in this and the following verses - almsgiving, prayer, fasting, Matthew 6:2-18. Our Saviour here does not positively command his disciples to aid the poor, but supposes that they would do it of course, and gives them directions how to do it. It is the nature of religion to help those who are really needy; and a real Christian does not wait to be "commanded" to do it, but only asks for the opportunity. See Galatians 2:10; James 1:27; Luke 19:8.Before men ... - Our Lord does not require us never to give alms bef', NULL, NULL, '''-18'':63 ''1'':131 ''10'':129 ''19'':134 ''2'':62,128 ''27'':132 ''6'':61 ''8.before'':135 ''act'':42 ''aid'':74 ''alm'':8,11,146 ''almsgiv'':37,57 ''ask'':122 ''bef'':147 ''best'':26 ''christian'':110 ''command'':70,116 ''cours'':85 ''denot'':13 ''direct'':89 ''discipl'':72 ''edit'':27 ''either'':34 ''emin'':39 ''fast'':59 ''follow'':55 ''galatian'':127 ''give'':87,145 ''greek'':30 ''heed'':2 ''help'':101 ''includ'':46 ''jame'':130 ''liber'':14 ''lord'':138 ''luke'':133 ''margin'':22 ''matthew'':60 ''men'':136 ''natur'':97 ''needi'':19,106 ''never'':143 ''opportun'':125 ''poor'':17,76 ''posit'':69 ''prayer'':58 ''probabl'':45 ''real'':109 ''realli'':105 ''refer'':35 ''religion'':99 ''requir'':141 ''righteous'':33,41 ''saviour'':65 ''see'':126 ''specifi'':50 ''suppos'':78 ''take'':1 ''us'':142 ''vers'':56 ''wait'':113 ''word'':10 ''would'':81 ''ye'':4', NULL, '935');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('967', '2', '967', NULL, 'ore people, but only forbids our doing it "to be seen of them," for the purposes of ostentation and to seek their praise. To a person who is disposed to do good from a right motive, it matters little whether it be in public or in private. The only thing that renders it even desirable that our good deeds should be seen is that God may be glorified. See Matthew 5:16.Otherwise - If your only motive for doing it is to be seen by people, God will not reward you. Take heed, therefore, that you do not do it to be seen, "otherwise" God will not reward you.', NULL, NULL, '''16.otherwise'':72 ''5'':71 ''deed'':59 ''desir'':55 ''dispos'':29 ''even'':54 ''forbid'':5 ''glorifi'':68 ''god'':65,86,104 ''good'':32,58 ''heed'':92 ''littl'':39 ''matter'':38 ''matthew'':70 ''may'':66 ''motiv'':36,76 ''ore'':1 ''ostent'':18 ''otherwis'':103 ''peopl'':2,85 ''person'':26 ''prais'':23 ''privat'':47 ''public'':44 ''purpos'':16 ''render'':52 ''reward'':89,107 ''right'':35 ''see'':69 ''seek'':21 ''seen'':11,62,83,102 ''take'':91 ''therefor'':93 ''thing'':50 ''whether'':40', NULL, '935');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('968', '2', '968', NULL, 's of retirement? I answer, the desire to pray, and the love of prayer, will create such places in abundance. The Saviour had all the difficulties which we can have, but yet he lived in the practice of secret prayer. To be alone, he rose up "a great while before day," and went into a solitary place and prayed, Mark 1:35. With him a grove, a mountain, a garden, furnished such a place, and, though a traveler, and among strangers, and without a house, he lived in the habit of secret prayer. What excuse can they have for not praying who have a home, and who spend the precious hours of the morning in sleep, and who will practice no self-denial that they may be alone with God? O Christian! thy Saviour would have broken in upon these hours, and would have trod his solitary way to the mountain or t', NULL, NULL, '''1'':61 ''35'':62 ''abund'':20 ''alon'':43,129 ''among'':80 ''answer'':5 ''broken'':138 ''christian'':133 ''creat'':16 ''day'':51 ''denial'':124 ''desir'':7 ''difficulti'':26 ''excus'':95 ''furnish'':71 ''garden'':70 ''god'':131 ''great'':48 ''grove'':66 ''habit'':90 ''home'':105 ''hour'':111,142 ''hous'':85 ''live'':34,87 ''love'':12 ''mark'':60 ''may'':127 ''morn'':114 ''mountain'':68,152 ''o'':132 ''place'':18,57,74 ''practic'':37,120 ''pray'':9,59,101 ''prayer'':14,40,93 ''precious'':110 ''retir'':3 ''rose'':45 ''saviour'':22,135 ''secret'':39,92 ''self'':123 ''self-deni'':122 ''sleep'':116 ''solitari'':56,148 ''spend'':108 ''stranger'':81 ''thi'':134 ''though'':76 ''travel'':78 ''trod'':146 ''upon'':140 ''way'':149 ''went'':53 ''without'':83 ''would'':136,144 ''yet'':32', NULL, '935');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('969', '2', '969', NULL, 'he grove that he might pray. He did do it. He did it to pray for thee, too indolent and too unconcerned about thy own salvation and that of the world to practice the least self-denial in order to commune with God! How can religion live thus? How can such a soul be saved?The Saviour does not specify the times when we should pray in secret. He does not say how often it should be done. The reasons may have been:(1) that he designed that his religion should be "voluntary," and there is not a better "test" of true piety than a disposition to engage often in secret prayer. He intended to leave it to his people to show attachment to him by coming to God often, and as often as they chose.(2) an attempt to specify the times when this should be done would tend to make religion formal and heartless. ', NULL, NULL, '''1'':85 ''2'':138 ''attach'':124 ''attempt'':140 ''better'':100 ''chose'':137 ''come'':128 ''commune'':42 ''denial'':38 ''design'':88 ''disposit'':107 ''done'':79,149 ''engag'':109 ''formal'':155 ''god'':44,130 ''grove'':2 ''heartless'':157 ''indol'':19 ''intend'':115 ''least'':35 ''leav'':117 ''live'':48 ''make'':153 ''may'':82 ''might'':5 ''often'':75,110,131,134 ''order'':40 ''peopl'':121 ''pieti'':104 ''practic'':33 ''pray'':6,15,67 ''prayer'':113 ''reason'':81 ''religion'':47,91,154 ''salvat'':26 ''save'':56 ''saviour'':58 ''say'':73 ''secret'':69,112 ''self'':37 ''self-deni'':36 ''show'':123 ''soul'':54 ''specifi'':61,142 ''tend'':151 ''test'':101 ''thee'':17 ''thi'':24 ''thus'':49 ''time'':63,144 ''true'':103 ''unconcern'':22 ''voluntari'':94 ''world'':31 ''would'':150', NULL, '935');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('970', '2', '970', NULL, 'Mohammed undertook to regulate this, and the consequence is a cold and formal prostration at the appointed hours of prayer all over the land where his religion has spread.(3) the periods are so numerous, and the seasons for secret prayer vary so much, that it would nor be easy to fix rules when this should be done.Yet without giving rules, where the Saviour has given none, we may suggest the following as times when secret prayer is proper:1. In the morning. Nothing can be more appropriate when we have been preserved through the night, and when we are about to enter upon the duties and dangers of another day, than to render to our great Preserver thanks, and to commit ourselves to His fatherly care.2. In the evening. When the day has closed, what would be more natural than to offer thanksgi', NULL, NULL, '''1'':80 ''3'':30 ''anoth'':110 ''appoint'':17 ''appropri'':88 ''care.2'':127 ''close'':135 ''cold'':11 ''commit'':122 ''consequ'':8 ''danger'':108 ''day'':111,133 ''done.yet'':58 ''duti'':106 ''easi'':50 ''enter'':103 ''even'':130 ''father'':126 ''fix'':52 ''follow'':72 ''formal'':13 ''give'':60 ''given'':66 ''great'':117 ''hour'':18 ''land'':24 ''may'':69 ''moham'':1 ''morn'':83 ''much'':44 ''natur'':140 ''night'':96 ''none'':67 ''noth'':84 ''numer'':35 ''offer'':143 ''period'':32 ''prayer'':20,41,77 ''preserv'':93,118 ''proper'':79 ''prostrat'':14 ''regul'':4 ''religion'':27 ''render'':114 ''rule'':53,61 ''saviour'':64 ''season'':38 ''secret'':40,76 ''spread'':29 ''suggest'':70 ''thank'':119 ''thanksgi'':144 ''time'':74 ''undertook'':2 ''upon'':104 ''vari'':42 ''without'':59 ''would'':47,137', NULL, '935');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('972', '2', '972', NULL, 'ty of this nation is owing to the answer to the secret prayer of Washington?4. We should pray when we are beset with strong temptations. So the Saviour prayed in the garden of Gethsemane (compare Hebr', NULL, NULL, '''4'':16 ''answer'':9 ''beset'':23 ''compar'':36 ''garden'':33 ''gethseman'':35 ''hebr'':37 ''nation'':4 ''owe'':6 ''pray'':19,30 ''prayer'':13 ''saviour'':29 ''secret'':12 ''strong'':25 ''temptat'':26 ''ty'':1 ''washington'':15', NULL, '935');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('978', '2', '978', NULL, 'ers, and which requires an effort to find it! And how much danger is there that we shall continue to walk in that way until it terminates in our ruin! No one is saved without effort. No one enters on the narrow way without design; no one by following his natural inclination and propensities. And yet how indisposed we are to effort! how unwilling to listen to the exhortations which would call us from the broad path to a narrower and less frequented course! How prone are people to feel that they are safe if they are with the many, and that the multitude that attend them constitute a safeguard from danger!"Encompassed by a throng,On ''numbers'' they depend;They say so many can''t be wrong,And miss a happy end."Yet did God ever spare a guilty city because it was large? Did he save the army of Sen', NULL, NULL, '''armi'':150 ''attend'':106 ''broad'':76 ''call'':72 ''citi'':141 ''constitut'':108 ''continu'':19 ''cours'':84 ''danger'':13,112 ''depend'':120 ''design'':45 ''effort'':6,36,62 ''encompass'':113 ''end'':133 ''enter'':39 ''er'':1 ''ever'':137 ''exhort'':69 ''feel'':90 ''find'':8 ''follow'':49 ''frequent'':83 ''god'':136 ''guilti'':140 ''happi'':132 ''inclin'':52 ''indispos'':58 ''larg'':145 ''less'':82 ''listen'':66 ''mani'':100,124 ''miss'':130 ''much'':12 ''multitud'':104 ''narrow'':42,80 ''natur'':51 ''number'':118 ''one'':32,38,47 ''path'':77 ''peopl'':88 ''prone'':86 ''propens'':54 ''requir'':4 ''ruin'':30 ''safe'':94 ''safeguard'':110 ''save'':34,148 ''say'':122 ''sen'':152 ''shall'':18 ''spare'':138 ''termin'':27 ''throng'':116 ''unwil'':64 ''us'':73 ''walk'':21 ''way'':24,43 ''without'':35,44 ''would'':71 ''wrong'':128 ''yet'':56,134', NULL, '936');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('977', '2', '977', NULL, 'than we ever can of an earthly father. None but God can forgive, enlighten, sanctify, and save us. How strange that many ask favors of an "earthly" parent daily and hourly, and never ask of the Great Universal Father a single blessing for time or eternity!4. There is danger of losing the soul, Matthew 7:13-14. The way to ruin is broad; the path to heaven is narrow. People naturally and readily go in the former; they never go in the latter without design. When we enter on the journey of life, we naturally fall into the broad and thronged way to ruin. Our original propensity, our native depravity, our disinclination to God and religion, lead us to that, and we never leave it without effort. How much more natural to tread in a way in which multitudes go, than in one where there are few travel', NULL, NULL, '''-14'':58 ''13'':57 ''4'':47 ''7'':56 ''ask'':23,34 ''bless'':42 ''broad'':64,100 ''daili'':29 ''danger'':50 ''deprav'':111 ''design'':86 ''disinclin'':113 ''earth'':7,27 ''effort'':128 ''enlighten'':14 ''enter'':89 ''etern'':46 ''ever'':3 ''fall'':97 ''father'':8,39 ''favor'':24 ''forgiv'':13 ''former'':78 ''go'':75,81,141 ''god'':11,115 ''great'':37 ''heaven'':68 ''hour'':31 ''journey'':92 ''latter'':84 ''lead'':118 ''leav'':125 ''life'':94 ''lose'':52 ''mani'':22 ''matthew'':55 ''much'':130 ''multitud'':140 ''narrow'':70 ''nativ'':110 ''natur'':72,96,132 ''never'':33,80,124 ''none'':9 ''one'':144 ''origin'':107 ''parent'':28 ''path'':66 ''peopl'':71 ''propens'':108 ''readili'':74 ''religion'':117 ''ruin'':62,105 ''sanctifi'':15 ''save'':17 ''singl'':41 ''soul'':54 ''strang'':20 ''throng'':102 ''time'':44 ''travel'':149 ''tread'':134 ''univers'':38 ''us'':18,119 ''way'':60,103,137 ''without'':85,127', NULL, '936');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1001', '2', '1001', NULL, 'And it came to pass ... - The directions to the apostles were given in the vicinity of Capernaum. The Saviour went from thence to preach in their cities; that is, in the cities in the vicinity of Capernaum, or in Galilee. He did not yet go into Judea.', NULL, NULL, '''apostl'':10 ''came'':3 ''capernaum'':17,37 ''citi'':27,32 ''direct'':7 ''galile'':40 ''given'':12 ''go'':45 ''judea'':47 ''pass'':5 ''preach'':24 ''saviour'':19 ''thenc'':22 ''vicin'':15,35 ''went'':20 ''yet'':44', NULL, '940');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('973', '2', '973', NULL, 'Judge not ... - This command refers to rash, censorious, and unjust judgment. See Romans 2:1. Luke Luk 6:37 explains it in the sense of "condemning." Christ does not condemn judging as a magistrate, for that, when according to justice, is lawful and necessary. Nor does he condemn our "forming an opinion" of the conduct of others, for it is impossible "not" to form an opinion of conduct that we know to be evil. But what he refers to is a habit of forming a judgment hastily, harshly, and without an allowance for every palliating circumstance, and a habit of "expressing" such an opinion harshly and unnecessarily when formed. It rather refers to private judgment than "judicial," and perhaps primarily to the customs of the scribes and Pharisees.', NULL, NULL, '''1'':15 ''2'':14 ''37'':19 ''6'':18 ''accord'':38 ''allow'':92 ''censori'':8 ''christ'':27 ''circumst'':96 ''command'':4 ''condemn'':26,30,48 ''conduct'':55,68 ''custom'':123 ''everi'':94 ''evil'':74 ''explain'':20 ''express'':101 ''form'':50,64,84,109 ''habit'':82,99 ''harsh'':88,105 ''hastili'':87 ''imposs'':61 ''judg'':1,31 ''judgment'':11,86,115 ''judici'':117 ''justic'':40 ''know'':71 ''law'':42 ''luk'':17 ''luke'':16 ''magistr'':34 ''necessari'':44 ''opinion'':52,66,104 ''other'':57 ''palliat'':95 ''perhap'':119 ''pharise'':128 ''primarili'':120 ''privat'':114 ''rash'':7 ''rather'':111 ''refer'':5,78,112 ''roman'':13 ''scribe'':126 ''see'':12 ''sens'':24 ''unjust'':10 ''unnecessarili'':107 ''without'':90', NULL, '936');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('979', '2', '979', NULL, 'nacherib from the destroying angel because it was mighty? Does he hesitate to cut people down by the plague, the pestilence, and by famine, because they are numerous? Is he deterred from consigning pe', NULL, NULL, '''angel'':5 ''consign'':33 ''cut'':14 ''destroy'':4 ''deter'':31 ''famin'':24 ''hesit'':12 ''mighti'':9 ''nacherib'':1 ''numer'':28 ''pe'':34 ''peopl'':15 ''pestil'':21 ''plagu'':19', NULL, '936');
