INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('983', '2', '983', NULL, 'toms by decayed teeth, by a fetid breath, and by a diseased complexion.Moses gave particular directions by which the real leprosy was to be distinguished from other diseases. See Leviticus 13. The leprous person was, in order to avoid contagion, very properly separated from the congregation. The inspection of the disease was committed to the priest; and a declaration on his part that the person was healed, was sufficient evidence to restore the afflicted man to the congregation. It was required, also, that the leprous person should bring an offering to the priest of two birds, probably "sparrows" (see Leviticus 14:4 ''s margin), one of which was slain and the other dismissed, Leviticus 14:5-7. In compliance with the laws of the land, Jesus directed the man that he had healed to make the cus', NULL, NULL, '''-7'':117 ''13'':31 ''14'':101,115 ''4'':102 ''5'':116 ''afflict'':74 ''also'':82 ''avoid'':39 ''bird'':96 ''breath'':8 ''bring'':88 ''commit'':53 ''complexion.moses'':13 ''complianc'':119 ''congreg'':46,78 ''contagion'':40 ''cus'':137 ''decay'':3 ''declar'':59 ''direct'':16,127 ''diseas'':12,28,51 ''dismiss'':113 ''distinguish'':25 ''evid'':70 ''fetid'':7 ''gave'':14 ''heal'':67,133 ''inspect'':48 ''jesus'':126 ''land'':125 ''law'':122 ''leprosi'':21 ''leprous'':33,85 ''leviticus'':30,100,114 ''make'':135 ''man'':75,129 ''margin'':104 ''offer'':90 ''one'':105 ''order'':37 ''part'':62 ''particular'':15 ''person'':34,65,86 ''priest'':56,93 ''probabl'':97 ''proper'':42 ''real'':20 ''requir'':81 ''restor'':72 ''see'':29,99 ''separ'':43 ''slain'':109 ''sparrow'':98 ''suffici'':69 ''teeth'':4 ''tom'':1 ''two'':95', NULL, '937');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('984', '2', '984', NULL, 'tomary offering, and to obtain the testimony of the priest that he was healed. The leprosy has once, and but once, appeared in America. This loathsome and most painful disease has in all other instances been confined to the Old World, and chiefly to the Eastern nations.It is matter of profound gratitude to a benignant God that this scourge has been permitted but once to visit the New World. That awful calamity was on the island of Guadeloupe, in the West Indies, about the year 1730, and is thus described by an eye-witness:  "Its commencement is imperceptible. There appear only some few white spots on the skin. At first they are attended with no pain or inconvenience, but no means whatever will remove them. The disease imperceptibly increases for many years. The spots become larger, and spr', NULL, NULL, '''1730'':86 ''america'':24 ''appear'':22,101 ''attend'':114 ''aw'':71 ''becom'':136 ''benign'':55 ''calam'':72 ''chiefli'':43 ''commenc'':97 ''confin'':37 ''describ'':90 ''diseas'':30,128 ''eastern'':46 ''eye'':94 ''eye-wit'':93 ''first'':111 ''god'':56 ''gratitud'':52 ''guadeloup'':78 ''heal'':14 ''impercept'':99,129 ''inconveni'':119 ''increas'':130 ''indi'':82 ''instanc'':35 ''island'':76 ''larger'':137 ''leprosi'':16 ''loathsom'':26 ''mani'':132 ''matter'':49 ''mean'':122 ''nations.it'':47 ''new'':68 ''obtain'':5 ''offer'':2 ''old'':40 ''pain'':29,117 ''permit'':62 ''priest'':10 ''profound'':51 ''remov'':125 ''scourg'':59 ''skin'':109 ''spot'':106,135 ''spr'':139 ''testimoni'':7 ''thus'':89 ''tomari'':1 ''visit'':66 ''west'':81 ''whatev'':123 ''white'':105 ''wit'':95 ''world'':41,69 ''year'':85,133', NULL, '937');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('982', '2', '982', NULL, 'th slow and certain ruin. "Life still lingers amid the desolation;" the joints, and hands, and feet lose their power; and the body "collapses," or falls together in a form hideous and awful. There is a form of the disease in which it commences at the extremities: the joints separate; the fingers, toes, and other members one by one fall off; and the malady thus gradually approaches the seat of life. The wretched victim is thus doomed to see himself dying "piecemeal," assured that no human power can arrest for a moment the silent and steady march of this foe to the seat of life.This disease is contagious and hereditary. It is easily communicated from one to another, and is transmitted to the third and fourth generation. The last generation that is afflicted with it commonly exhibits the symp', NULL, NULL, '''afflict'':133 ''amid'':9 ''anoth'':118 ''approach'':67 ''arrest'':89 ''assur'':83 ''aw'':33 ''bodi'':23 ''certain'':4 ''collaps'':24 ''commenc'':44 ''common'':136 ''communic'':114 ''contagi'':108 ''desol'':11 ''die'':81 ''diseas'':40,106 ''doom'':77 ''easili'':113 ''exhibit'':137 ''extrem'':47 ''fall'':26,60 ''feet'':17 ''finger'':52 ''foe'':100 ''form'':30,37 ''fourth'':126 ''generat'':127,130 ''gradual'':66 ''hand'':15 ''hereditari'':110 ''hideous'':31 ''human'':86 ''joint'':13,49 ''last'':129 ''life'':6,71 ''life.this'':105 ''linger'':8 ''lose'':18 ''maladi'':64 ''march'':97 ''member'':56 ''moment'':92 ''one'':57,59,116 ''piecem'':82 ''power'':20,87 ''ruin'':5 ''seat'':69,103 ''see'':79 ''separ'':50 ''silent'':94 ''slow'':2 ''steadi'':96 ''still'':7 ''symp'':139 ''th'':1 ''third'':124 ''thus'':65,76 ''toe'':53 ''togeth'':27 ''transmit'':121 ''victim'':74 ''wretch'':73', NULL, '937');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('981', '2', '981', NULL, ' black, and the red leprosy. These spots, though few at first, gradually spread until they cover the whole body.But, though the "appearance" of the disease is at first in the skin, yet it is deeply seated in the bones, and marrow, and joints of the body. We have reason to suppose that in children it is concealed in the system for a number of years until they arrive at the age of puberty; and in adults for three or four years, until at last it gives fearful indications on the skin of its having gained a well-rooted and permanent existence. A leprous person may live twenty, or thirty, or even fifty years, if he received the disease at his birth, but they will be years of indescribable misery. The bones and marrow are pervaded with the disease. The malady advances from one stage to another wi', NULL, NULL, '''adult'':76 ''advanc'':142 ''age'':71 ''anoth'':147 ''appear'':22 ''arriv'':68 ''birth'':122 ''black'':1 ''bodi'':46 ''body.but'':19 ''bone'':39,132 ''children'':54 ''conceal'':57 ''cover'':16 ''deepli'':35 ''diseas'':25,119,139 ''even'':112 ''exist'':102 ''fear'':87 ''fifti'':113 ''first'':11,28 ''four'':80 ''gain'':95 ''give'':86 ''gradual'':12 ''indescrib'':129 ''indic'':88 ''joint'':43 ''last'':84 ''leprosi'':5 ''leprous'':104 ''live'':107 ''maladi'':141 ''marrow'':41,134 ''may'':106 ''miseri'':130 ''number'':63 ''one'':144 ''perman'':101 ''person'':105 ''pervad'':136 ''puberti'':73 ''reason'':49 ''receiv'':117 ''red'':4 ''root'':99 ''seat'':36 ''skin'':31,91 ''spot'':7 ''spread'':13 ''stage'':145 ''suppos'':51 ''system'':60 ''thirti'':110 ''though'':8,20 ''three'':78 ''twenti'':108 ''well'':98 ''well-root'':97 ''whole'':18 ''wi'':148 ''year'':65,81,114,127 ''yet'':32', NULL, '937');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('980', '2', '980', NULL, 'When he was come down from the mountain - That is, immediately on his descending from the mountain. His discourse had attracted great attention, and the fame of it drew together great multitudes, who were convinced that he had come from God. Then follows, in this chapter and the chapter succeeding, a succession of "miracles" not less remarkable than his teaching was; miracles that tended to confirm beyond a doubt the impression made by his sermon that he was sent from God.Great multitudes followed him - Great numbers of those who had been with him in the mountain, and great numbers of others who were attracted by the fame of that discourse.', NULL, NULL, '''attent'':23 ''attract'':21,104 ''beyond'':67 ''chapter'':46,49 ''come'':4,39 ''confirm'':66 ''convinc'':35 ''descend'':14 ''discours'':19,110 ''doubt'':69 ''drew'':29 ''fame'':26,107 ''follow'':43,83 ''god'':41 ''god.great'':81 ''great'':22,31,85,98 ''immedi'':11 ''impress'':71 ''less'':56 ''made'':72 ''miracl'':54,62 ''mountain'':8,17,96 ''multitud'':32,82 ''number'':86,99 ''other'':101 ''remark'':57 ''sent'':79 ''sermon'':75 ''succeed'':50 ''success'':52 ''teach'':60 ''tend'':64 ''togeth'':30', NULL, '937');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('985', '2', '985', NULL, 'ead over the whole body. When the disease advances, the upper part of the nose swells, the nostrils become enlarged, and the nose itself grows soft. Tumors appear on the jaws; the eyebrows swell; the ears become thick; the points of the fingers, as also the feet and the toes, swell; the nails become scaly; the joints of the hands and feet separate and drop off. In the last stage of the disease the patient becomes a hideous spectacle, and falls to pieces.Worshipped him - Bowed down before him, to show him respect. See the notes at Matthew 2:2.If thou wilt - This was an exhibition of great faith, and also an acknowledgment of his dependence on the will of Jesus, in order to be healed. So every sinner must come. He must feel that Jesus "can" save him. He must also feel that he has no claim on', NULL, NULL, '''2'':98 ''2.if'':99 ''acknowledg'':112 ''advanc'':9 ''also'':45,110,141 ''appear'':28 ''becom'':19,37,54,76 ''bodi'':5 ''bow'':85 ''claim'':147 ''come'':130 ''depend'':115 ''diseas'':8,73 ''drop'':65 ''ead'':1 ''ear'':36 ''enlarg'':20 ''everi'':127 ''exhibit'':105 ''eyebrow'':33 ''faith'':108 ''fall'':81 ''feel'':133,142 ''feet'':47,62 ''finger'':43 ''great'':107 ''grow'':25 ''hand'':60 ''heal'':125 ''hideous'':78 ''jaw'':31 ''jesus'':120,135 ''joint'':57 ''last'':69 ''matthew'':97 ''must'':129,132,140 ''nail'':53 ''nose'':15,23 ''nostril'':18 ''note'':95 ''order'':122 ''part'':12 ''patient'':75 ''pieces.worshipped'':83 ''point'':40 ''respect'':92 ''save'':137 ''scali'':55 ''see'':93 ''separ'':63 ''show'':90 ''sinner'':128 ''soft'':26 ''spectacl'':79 ''stage'':70 ''swell'':16,34,51 ''thick'':38 ''thou'':100 ''toe'':50 ''tumor'':27 ''upper'':11 ''whole'':4 ''wilt'':101', NULL, '937');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('991', '2', '991', NULL, 'me height, the railing was lower, so as to walk from one roof to another. In cities where the houses were constructed in this manner, it was possible to walk through a considerable part of the city on the roofs. A breastwork or railing was of course built in the same manner around the "open space" in the center, to prevent persons from falling into the court below. This railing, or breastwork, is what Luke Luk 5:19 says they let him down through. They removed it, probably, so that the couch could be conveniently let down with cords; and, standing on the roof "over" the Saviour, they let the man down directly before him. The perseverance they had manifested was the evidence of their faith or confidence in his power to heal the sick man.Be of good cheer: thy sins be forgiven thee - It may se', NULL, NULL, '''19'':78 ''5'':77 ''anoth'':15 ''around'':53 ''breastwork'':42,72 ''built'':48 ''center'':59 ''cheer'':139 ''citi'':17,37 ''confid'':128 ''consider'':33 ''construct'':22 ''conveni'':95 ''cord'':99 ''couch'':92 ''could'':93 ''cours'':47 ''court'':67 ''direct'':113 ''evid'':123 ''faith'':126 ''fall'':64 ''forgiven'':143 ''good'':138 ''heal'':133 ''height'':2 ''hous'':20 ''let'':81,96,109 ''lower'':6 ''luk'':76 ''luke'':75 ''man'':111 ''man.be'':136 ''manifest'':120 ''manner'':25,52 ''may'':146 ''one'':12 ''open'':55 ''part'':34 ''persever'':117 ''person'':62 ''possibl'':28 ''power'':131 ''prevent'':61 ''probabl'':88 ''rail'':4,44,70 ''remov'':86 ''roof'':13,40,104 ''saviour'':107 ''say'':79 ''se'':147 ''sick'':135 ''sin'':141 ''space'':56 ''stand'':101 ''thee'':144 ''thi'':140 ''walk'':10,30', NULL, '938');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('987', '2', '987', NULL, 'And he entered into a ship ... - Jesus acceded to the request of the people of Gadara Matthew 8:34, recrossed the Lake of Gennesareth, and returned to his own city. By "his own city" is meant Capernaum Mark 2:1, the city which was at that time his home, or where he had his dwelling. See the notes at Matthew 4:13. This same account, with some additional circumstances, is contained in Mark 2:3-12, and Luke 5:18-26.', NULL, NULL, '''-12'':76 ''-26'':81 ''1'':40 ''13'':62 ''18'':80 ''2'':39,74 ''3'':75 ''34'':19 ''4'':61 ''5'':79 ''8'':18 ''acced'':8 ''account'':65 ''addit'':68 ''capernaum'':37 ''circumst'':69 ''citi'':30,34,42 ''contain'':71 ''dwell'':55 ''enter'':3 ''gadara'':16 ''gennesareth'':24 ''home'':49 ''jesus'':7 ''lake'':22 ''luke'':78 ''mark'':38,73 ''matthew'':17,60 ''meant'':36 ''note'':58 ''peopl'':14 ''recross'':20 ''request'':11 ''return'':26 ''see'':56 ''ship'':6 ''time'':47', NULL, '938');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1014', '2', '1014', NULL, 's seeks. Where that is "he" will strengthen us, and we shall not fail.7. Grace will not be extinguished, Matthew 12:20. Jesus, where he finds it in the feeblest degree, will not destroy it. He will ch', NULL, NULL, '''12'':21 ''20'':22 ''ch'':38 ''degre'':31 ''destroy'':34 ''extinguish'':19 ''fail.7'':14 ''feeblest'':30 ''find'':26 ''grace'':15 ''jesus'':23 ''matthew'':20 ''seek'':2 ''shall'':12 ''strengthen'':8 ''us'':9', NULL, '941');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('988', '2', '988', NULL, 'e door is seen in the center, and usually, directly above it, a single latticed window. This destitution of doors and lights from the streets, though it gives their dwellings a sombre appearance, is yet adapted to the habits of retirement and secrecy among the people of the East, where they are desirous of keeping their "females" from observation. See the notes at Matthew 6:6. On entering the only door in front, the first room is a small square room, surrounded with benches, called the "porch." In this room the master of the family commonly transacts business, and on private occasions receives visits. Passing through the porch, you enter a large square room directly in the center of the building, called the court. Luke says that the "paralytic" was let down "into the midst;" not in the mid', NULL, NULL, '''6'':65,66 ''adapt'':36 ''among'':44 ''appear'':33 ''bench'':84 ''build'':121 ''busi'':98 ''call'':85,122 ''center'':7,118 ''common'':96 ''court'':124 ''desir'':53 ''destitut'':18 ''direct'':10,115 ''door'':2,20,71 ''dwell'':30 ''e'':1 ''east'':49 ''enter'':68,110 ''famili'':95 ''femal'':57 ''first'':75 ''front'':73 ''give'':28 ''habit'':39 ''keep'':55 ''larg'':112 ''lattic'':15 ''let'':131 ''light'':22 ''luke'':125 ''master'':92 ''matthew'':64 ''mid'':139 ''midst'':135 ''note'':62 ''observ'':59 ''occas'':102 ''paralyt'':129 ''pass'':105 ''peopl'':46 ''porch'':87,108 ''privat'':101 ''receiv'':103 ''retir'':41 ''room'':76,81,90,114 ''say'':126 ''secreci'':43 ''see'':60 ''seen'':4 ''singl'':14 ''small'':79 ''sombr'':32 ''squar'':80,113 ''street'':25 ''surround'':82 ''though'':26 ''transact'':97 ''usual'':9 ''visit'':104 ''window'':16 ''yet'':35', NULL, '938');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('989', '2', '989', NULL, 'st of the "people," but of the "building" - the "middle place" of the house. This "court" is paved commonly with marble; and, if possible, a fountain of water is formed in the center, to give it beauty, and to diffuse a grateful coolness. This room is surrounded by a gallery or covered walk on every side. From that covered walk doors open into the other apartments of the house.This center room, or court, is commonly uncovered or open above. In wet weather, however, and in times of great heat of the sun, it is covered with an awning or canvas, stretched on cords and capable of being easily removed or rolled up. This is what Mark means when he says "they uncovered the roof." They "rolled up" or removed this awning.From the court to the roof the ascent is by flights of stairs, either in the c', NULL, NULL, '''apart'':66 ''ascent'':138 ''awn'':98 ''awning.from'':131 ''beauti'':37 ''build'':8 ''c'':147 ''canva'':100 ''capabl'':105 ''center'':33,70 ''common'':19,75 ''cool'':43 ''cord'':103 ''court'':16,73,133 ''cover'':52,59,95 ''diffus'':40 ''door'':61 ''easili'':108 ''either'':144 ''everi'':55 ''flight'':141 ''form'':30 ''fountain'':26 ''galleri'':50 ''give'':35 ''grate'':42 ''great'':88 ''heat'':89 ''hous'':14 ''house.this'':69 ''howev'':83 ''marbl'':21 ''mark'':116 ''mean'':117 ''middl'':10 ''open'':62,78 ''pave'':18 ''peopl'':4 ''place'':11 ''possibl'':24 ''remov'':109,129 ''roll'':111,126 ''roof'':124,136 ''room'':45,71 ''say'':120 ''side'':56 ''st'':1 ''stair'':143 ''stretch'':101 ''sun'':92 ''surround'':47 ''time'':86 ''uncov'':76,122 ''walk'':53,60 ''water'':28 ''weather'':82 ''wet'':81', NULL, '938');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('990', '2', '990', NULL, 'overed walk or gallery or in the porch. The roof is nearly flat. It is made of earth; or, in houses of the rich, is a firmly; constructed flooring, made of coals, chalk, gypsum, and ashes, made hard by repeated blows. On those roofs spears of grass. wheat, or barley sometimes spring up; but these are soon withered by the sun, Psalm 129:6-8. The roof is a favourite place for walking, for repose in the cool of the day, for conversation, and for devotion. See the notes at Matthew 6:6. On such a roof Rahab concealed the spies Joshua 2:6, Samuel talked with Saul 1 Samuel 9:25, David walked at eventide 2 Samuel 11:2), and Peter went up to pray Acts 10:9. This roof was surrounded with a "balustrade," or railing, breast-high, on the sides; but where a house was contiguous to another, and of the sa', NULL, NULL, '''-8'':65 ''1'':109 ''10'':128 ''11'':119 ''129'':63 ''2'':103,117,120 ''25'':112 ''6'':64,92,93,104 ''9'':111,129 ''act'':127 ''anoth'':152 ''ash'':36 ''balustrad'':136 ''barley'':50 ''blow'':41 ''breast'':140 ''breast-high'':139 ''chalk'':33 ''coal'':32 ''conceal'':99 ''construct'':28 ''contigu'':150 ''convers'':83 ''cool'':78 ''david'':113 ''day'':81 ''devot'':86 ''earth'':18 ''eventid'':116 ''favourit'':70 ''firm'':27 ''flat'':13 ''floor'':29 ''galleri'':4 ''grass'':47 ''gypsum'':34 ''hard'':38 ''high'':141 ''hous'':21,148 ''joshua'':102 ''made'':16,30,37 ''matthew'':91 ''near'':12 ''note'':89 ''over'':1 ''peter'':122 ''place'':71 ''porch'':8 ''pray'':126 ''psalm'':62 ''rahab'':98 ''rail'':138 ''repeat'':40 ''repos'':75 ''rich'':24 ''roof'':10,44,67,97,131 ''sa'':156 ''samuel'':105,110,118 ''saul'':108 ''see'':87 ''side'':144 ''sometim'':51 ''soon'':57 ''spear'':45 ''spi'':101 ''spring'':52 ''sun'':61 ''surround'':133 ''talk'':106 ''walk'':2,73,114 ''went'':123 ''wheat'':48 ''wither'':58', NULL, '938');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('992', '2', '992', NULL, 'em remarkable, since the man came only to be "healed," that Jesus should have first declared his sins forgiven. For this the following reasons may be suggested:1. The man might have brought on this disease of the palsy by a long course of vicious indulgence. Conscious of guilt, he may have feared that he was so great a sinner that Christ would not regard him. He therefore assured him that his offences were pardoned, and that he might lay aside his fears.2. Jesus might be willing to show his power to forgive sins. Had he stated it without any miracle, the Jews would not have believed it, and even his disciples might have been staggered. In proof of it, he worked a miracle; and no one, therefore, could doubt that he had the power. The miracle was performed in "express attestation" of the ass', NULL, NULL, '''1'':28 ''asid'':81 ''ass'':145 ''assur'':69 ''attest'':142 ''believ'':107 ''brought'':33 ''came'':6 ''christ'':62 ''conscious'':47 ''could'':129 ''cours'':43 ''declar'':16 ''discipl'':112 ''diseas'':36 ''doubt'':130 ''em'':1 ''even'':110 ''express'':141 ''fear'':53 ''fears.2'':83 ''first'':15 ''follow'':23 ''forgiv'':93 ''forgiven'':19 ''great'':58 ''guilt'':49 ''heal'':10 ''indulg'':46 ''jesus'':12,84 ''jew'':103 ''lay'':80 ''long'':42 ''man'':5,30 ''may'':25,51 ''might'':31,79,85,113 ''miracl'':101,124,137 ''offenc'':73 ''one'':127 ''palsi'':39 ''pardon'':75 ''perform'':139 ''power'':91,135 ''proof'':118 ''reason'':24 ''regard'':65 ''remark'':2 ''show'':89 ''sin'':18,94 ''sinc'':3 ''sinner'':60 ''stagger'':116 ''state'':97 ''suggest'':27 ''therefor'':68,128 ''vicious'':45 ''will'':87 ''without'':99 ''work'':122 ''would'':63,104', NULL, '938');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('993', '2', '993', NULL, 'ertion that he had power to forgive sins. As God would not work a miracle to confirm a falsehood or to deceive people, the miracle was a solemn confirmation, on the part of God, that Jesus had the pow', NULL, NULL, '''confirm'':17,29 ''deceiv'':22 ''ertion'':1 ''falsehood'':19 ''forgiv'':7 ''god'':10,34 ''jesus'':36 ''miracl'':15,25 ''part'':32 ''peopl'':23 ''pow'':39 ''power'':5 ''sin'':8 ''solemn'':28 ''work'':13 ''would'':11', NULL, '938');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('140', '2', '140', NULL, 'Balaam, after the general custom of the pagan, prefaced his divinations by sacrifice. In the number of the altars regard was probably had to the number of the then known planets. Yet Balaam evidently intended his sacrifice as an offering to the true God.', NULL, NULL, '''altar'':19 ''balaam'':1,33 ''custom'':5 ''divin'':11 ''evid'':34 ''general'':4 ''god'':44 ''intend'':35 ''known'':30 ''number'':16,26 ''offer'':40 ''pagan'':8 ''planet'':31 ''prefac'':9 ''probabl'':22 ''regard'':20 ''sacrific'':13,37 ''true'':43 ''yet'':32', NULL, '140');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('994', '2', '994', NULL, 'And when he had called unto him his twelve disciples ... - This account of sending the apostles forth is recorded also in Mark 6:7-11, and Luke 9:1-6. Mark says that he sent them out two and two. This was a kind arrangement, that each one might have a companion, and that thus they might visit more places and accomplish more labor than if they were all together. These twelve were the original number of apostles. The word "apostle" means one that is "sent," and was given to them because they were "sent forth" to preach the gospel. They were ambassadors of Christ. To this number Matthias was afterward added, to supply the place of Judas Acts 1:26, and Paul was specially called to be an apostle to the Gentiles, Romans 1:1; 1 Corinthians 15:8-9; Galatians 1:1. In all, therefore, there were 14 a', NULL, NULL, '''-11'':25 ''-6'':30 ''-9'':141 ''1'':29,120,135,136,137,143,144 ''14'':150 ''15'':139 ''26'':121 ''6'':23 ''7'':24 ''8'':140 ''9'':28 ''accomplish'':62 ''account'':12 ''act'':119 ''add'':112 ''afterward'':111 ''also'':20 ''ambassador'':103 ''apostl'':16,78,81,130 ''arrang'':45 ''call'':5,126 ''christ'':105 ''companion'':52 ''corinthian'':138 ''discipl'':10 ''forth'':17,96 ''galatian'':142 ''gentil'':133 ''given'':89 ''gospel'':100 ''juda'':118 ''kind'':44 ''labor'':64 ''luke'':27 ''mark'':22,31 ''matthia'':109 ''mean'':82 ''might'':49,57 ''number'':76,108 ''one'':48,83 ''origin'':75 ''paul'':123 ''place'':60,116 ''preach'':98 ''record'':19 ''roman'':134 ''say'':32 ''send'':14 ''sent'':35,86,95 ''special'':125 ''suppli'':114 ''therefor'':147 ''thus'':55 ''togeth'':70 ''twelv'':9,72 ''two'':38,40 ''unto'':6 ''visit'':58 ''word'':80', NULL, '939');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('995', '2', '995', NULL, 'postles.In selecting "twelve" at first, it is probable that the Saviour was somewhat guided by the number of the tribes of Israel. Twelve was, with them, a well-known number, and it was natural that he should select one for every tribe. Their office was clearly made known. They were to heal the sick, cast out devils, raise the dead, preach the gospel. They were to be with him to receive his instructions, to learn the nature of his religion, be witnesses to his resurrection, and then to bear his gospel around the globe. The number twelve was the best number for these purposes that could be selected. It was sufficiently "large" to answer the purpose of testimony, and it was "so small" as not to tend to disorder, or that they could easily be divided into parties or factions. They were not lea', NULL, NULL, '''answer'':115 ''around'':93 ''bear'':90 ''best'':101 ''cast'':56 ''clear'':47 ''could'':107,134 ''dead'':61 ''devil'':58 ''disord'':130 ''divid'':137 ''easili'':135 ''everi'':42 ''faction'':141 ''first'':5 ''globe'':95 ''gospel'':64,92 ''guid'':14 ''heal'':53 ''instruct'':74 ''israel'':22 ''known'':30,49 ''larg'':113 ''lea'':145 ''learn'':76 ''made'':48 ''natur'':35,78 ''number'':17,31,97,102 ''offic'':45 ''one'':40 ''parti'':139 ''postles.in'':1 ''preach'':62 ''probabl'':8 ''purpos'':105,117 ''rais'':59 ''receiv'':72 ''religion'':81 ''resurrect'':86 ''saviour'':11 ''select'':2,39,109 ''sick'':55 ''small'':124 ''somewhat'':13 ''suffici'':112 ''tend'':128 ''testimoni'':119 ''tribe'':20,43 ''twelv'':3,23,98 ''well'':29 ''well-known'':28 ''wit'':83', NULL, '939');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('996', '2', '996', NULL, 'rned men, and could not be supposed to spread their religion by art or talents. They were not men of wealth, and could not bribe men to follow them. They were not men of rank and office, and could not compel people to believe. They were just such men as are always found the best witnesses in courts of justice - plain men, of good sense, of fair character, of great honesty, and with favorable opportunities of ascertaining the facts to which they bore witness. Such men everybody believes, and especially when they are willing to lay down their lives to prove their sincerity.It was important that the Saviour should choose them early in his ministry, in order that they might be fully acquainted with him; might treasure up his instructions, and observe his manner of life and his person, so that,', NULL, NULL, '''acquaint'':123 ''alway'':52 ''art'':13 ''ascertain'':77 ''believ'':44,88 ''best'':55 ''bore'':83 ''bribe'':25 ''charact'':68 ''choos'':110 ''compel'':41 ''could'':4,23,39 ''court'':58 ''earli'':112 ''especi'':90 ''everybodi'':87 ''fact'':79 ''fair'':67 ''favor'':74 ''follow'':28 ''found'':53 ''fulli'':122 ''good'':64 ''great'':70 ''honesti'':71 ''import'':105 ''instruct'':130 ''justic'':60 ''lay'':96 ''life'':136 ''live'':99 ''manner'':134 ''men'':2,19,26,33,49,62,86 ''might'':120,126 ''ministri'':115 ''observ'':132 ''offic'':37 ''opportun'':75 ''order'':117 ''peopl'':42 ''person'':139 ''plain'':61 ''prove'':101 ''rank'':35 ''religion'':11 ''rned'':1 ''saviour'':108 ''sens'':65 ''sincerity.it'':103 ''spread'':9 ''suppos'':7 ''talent'':15 ''treasur'':127 ''wealth'':21 ''will'':94 ''wit'':56,84', NULL, '939');
