INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('998', '2', '998', NULL, 'for safety to Samaria, and greatly increased their numbers and the hatred which subsisted between the two nations.5. The Samaritans received only the five books of Moses, and rejected the writings of the prophets and all the Jewish traditions. From these causes arose an irreconcilable difference between them, so that the Jews regarded them as the worst of the human race John 8:48, and had no dealings with them, John 4:9.Our Saviour, however, preached the gospel to them afterward John 4:6-26, and the apostles imitated his example, Acts 8:25. The gospel was, however, first preached to the Jews.', NULL, NULL, '''-26'':85 ''25'':94 ''4'':72,83 ''48'':64 ''6'':84 ''8'':63,93 ''9.our'':73 ''act'':92 ''afterward'':81 ''apostl'':88 ''aros'':43 ''book'':25 ''caus'':42 ''deal'':68 ''differ'':46 ''exampl'':91 ''first'':99 ''five'':24 ''gospel'':78,96 ''great'':6 ''hatr'':12 ''howev'':75,98 ''human'':60 ''imit'':89 ''increas'':7 ''irreconcil'':45 ''jew'':52,103 ''jewish'':38 ''john'':62,71,82 ''mose'':27 ''nations.5'':18 ''number'':9 ''preach'':76,100 ''prophet'':34 ''race'':61 ''receiv'':21 ''regard'':53 ''reject'':29 ''safeti'':2 ''samaria'':4 ''samaritan'':20 ''saviour'':74 ''subsist'':14 ''tradit'':39 ''two'':17 ''worst'':57 ''write'':31', NULL, '939');
