INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('142', '2', '142', NULL, 'The records of the neighboring cities of the plain, and the circumstances of the origin of Moab (Genesis 19:30 ff) suggest that the people among whom Israel was now thrown were more than ordinarily licentious.', NULL, NULL, '''19'':19 ''30'':20 ''among'':26 ''circumst'':12 ''citi'':6 ''ff'':21 ''genesi'':18 ''israel'':28 ''licenti'':36 ''moab'':17 ''neighbor'':5 ''ordinarili'':35 ''origin'':15 ''peopl'':25 ''plain'':9 ''record'':2 ''suggest'':22 ''thrown'':31', NULL, '142');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('999', '2', '999', NULL, ' could do it without denying their Lord. So are we. He that throws away his life when it might have been, and ought to have been preserved, is a self-murderer. He that exposes himself when duty does not require it, and whose life pays the forfeit, goes before God "rushing unbidden into his Maker''s presence," nor can he be held guiltless.8. We are to persevere "in our duty" through all trials, Matthew 10:23. Neither the world, nor pain, nor poverty, nor persecution. nor death is to appal us. He that endures to the end shall be saved. We have but one thing to do - to do the will of God, to "be Christians everywhere," and to leave the event with him.9. God exercises a particular providence, Matthew 10:29-30. He watches the falling sparrow, numbers the hairs of the head, and for the same reaso', NULL, NULL, '''-30'':134 ''10'':76,132 ''23'':77 ''29'':133 ''appal'':91 ''away'':14 ''christian'':117 ''could'':1 ''death'':88 ''deni'':5 ''duti'':38,71 ''end'':98 ''endur'':95 ''event'':123 ''everywher'':118 ''exercis'':127 ''expos'':35 ''fall'':138 ''forfeit'':48 ''god'':51,114,126 ''goe'':49 ''guiltless.8'':64 ''hair'':142 ''head'':145 ''held'':63 ''him.9'':125 ''leav'':121 ''life'':16,45 ''lord'':7 ''maker'':56 ''matthew'':75,131 ''might'':19 ''murder'':32 ''neither'':78 ''number'':140 ''one'':105 ''ought'':23 ''pain'':82 ''particular'':129 ''pay'':46 ''persecut'':86 ''persever'':68 ''poverti'':84 ''presenc'':58 ''preserv'':27 ''provid'':130 ''reaso'':150 ''requir'':41 ''rush'':52 ''save'':101 ''self'':31 ''self-murder'':30 ''shall'':99 ''sparrow'':139 ''thing'':106 ''throw'':13 ''trial'':74 ''unbidden'':53 ''us'':92 ''watch'':136 ''whose'':44 ''without'':4 ''world'':80', NULL, '939');
