INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('120', '2', '120', NULL, 'The "generations" (see Genesis 2:4) now given, though entitled those of Aaron and Moses (Aaron standing first as the older brother), are those of Aaron only. The personal dignity of Moses, though it gave him rank as at the head of his tribe, was not hereditary. He had, and desired to have Numbers 14:12; Exodus 32:10, no successor in his office but the distant prophet like unto himself Deuteronomy 18:18. Aaron was the ancestor of a regular succession of priests.', NULL, NULL, '''10'':59 ''12'':56 ''14'':55 ''18'':73,74 ''2'':5 ''32'':58 ''4'':6 ''aaron'':13,16,26,75 ''ancestor'':78 ''brother'':22 ''desir'':51 ''deuteronomi'':72 ''digniti'':30 ''distant'':67 ''entitl'':10 ''exodus'':57 ''first'':18 ''gave'':35 ''generat'':2 ''genesi'':4 ''given'':8 ''head'':41 ''hereditari'':47 ''like'':69 ''mose'':15,32 ''number'':54 ''offic'':64 ''older'':21 ''person'':29 ''priest'':84 ''prophet'':68 ''rank'':37 ''regular'':81 ''see'':3 ''stand'':17 ''success'':82 ''successor'':61 ''though'':9,33 ''tribe'':44 ''unto'':70', NULL, '120');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('121', '2', '121', NULL, 'About the most holy things - Omit "about." The sense is, "this is the charge of the sons of Kohath, the most holy things:" i. e. the ark of the covenant, the table of showbread, the candlestick, and the golden altar, together with the furniture pertaining thereto. It appears, from a comparison of Numbers 4:16, Numbers 4:28, Numbers 4:33, that the ministry of the Kohathites was superintended by Eleazar, the older of the two surviving sons of Aaron; and that of the two other families by Ithamar.', NULL, NULL, '''16'':55 ''28'':58 ''33'':61 ''4'':54,57,60 ''aaron'':80 ''altar'':40 ''appear'':48 ''ark'':27 ''candlestick'':36 ''charg'':14 ''comparison'':51 ''coven'':30 ''e'':25 ''eleazar'':71 ''famili'':87 ''furnitur'':44 ''golden'':39 ''holi'':4,22 ''ithamar'':89 ''kohath'':19 ''kohathit'':67 ''ministri'':64 ''number'':53,56,59 ''older'':73 ''omit'':6 ''pertain'':45 ''sens'':9 ''showbread'':34 ''son'':17,78 ''superintend'':69 ''surviv'':77 ''tabl'':32 ''thereto'':46 ''thing'':5,23 ''togeth'':41 ''two'':76,85', NULL, '121');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('122', '2', '122', NULL, 'The general purpose of the directions given in this and the next chapter is to attest and to vindicate, by modes in harmony with the spirit of the theocratical law, the sanctity of the people of God. Thus, the congregation of Israel was made to typify the Church of God, within which, in its perfection, nothing that offends can be allowed to remain (compare Matthew 8:22; Revelation 21:27).The general purpose of the directions given in this and the next chapter is to attest and to vindicate, by modes in harmony with the spirit of the theocratical law, the sanctity of the people of God. Thus, the congregation of Israel was made to typify the Church of God, within which, in its perfection, nothing that offends can be allowed to remain (compare Matthew 8:22; Revelation 21:27).Compare the marginal references. The precepts of Leviticus 13 and Leviticus 15 are now first fully carried out. They could hardly have been so earlier, during the hurry and confusion which must have attended the march out of Egypt, and the encampments which next followed.The general purpose of the directions given in this and the next chapter is to attest and to vindicate, by modes in harmony with the spirit of the theocratical law, the sanctity of the people of God. Thus, the congregation of Israel was made to typify the Church of God, within which, in its perfection, nothing that offends can be allowed to remain (compare Matthew 8:22; Revelation 21:27).The general purpose of the directions given in this and the next chapter is to attest and to vindicate, by modes in harmony with the spirit of the theocratical law, the sanctity of the people of God. Thus, the congregation of Israel was made to typify the Church of God, within which, in its perfection, nothing that offends can be allowed to remain (compare Matthew 8:22; Revelation 21:27).Compare the marginal references. The precepts of Leviticus 13 and Leviticus 15 are now first fully carried out. They could hardly have been so earlier, during the hurry and confusion which must have attended the march out of Egypt, and the encampments which next followed.', NULL, NULL, '''13'':149,333 ''15'':152,336 ''21'':69,139,253,323 ''22'':67,137,251,321 ''27'':70,140,254,324 ''8'':66,136,250,320 ''allow'':61,131,245,315 ''attend'':174,358 ''attest'':16,86,200,270 ''carri'':157,341 ''chapter'':13,83,197,267 ''church'':48,118,232,302 ''compar'':64,134,141,248,318,325 ''confus'':170,354 ''congreg'':40,110,224,294 ''could'':160,344 ''direct'':6,76,190,260 ''earlier'':165,349 ''egypt'':179,363 ''encamp'':182,366 ''first'':155,339 ''follow'':369 ''followed.the'':185 ''fulli'':156,340 ''general'':2,72,186,256 ''given'':7,77,191,261 ''god'':37,50,107,120,221,234,291,304 ''hard'':161,345 ''harmoni'':23,93,207,277 ''hurri'':168,352 ''israel'':42,112,226,296 ''law'':30,100,214,284 ''leviticus'':148,151,332,335 ''made'':44,114,228,298 ''march'':176,360 ''margin'':143,327 ''matthew'':65,135,249,319 ''mode'':21,91,205,275 ''must'':172,356 ''next'':12,82,184,196,266,368 ''noth'':56,126,240,310 ''offend'':58,128,242,312 ''peopl'':35,105,219,289 ''perfect'':55,125,239,309 ''precept'':146,330 ''purpos'':3,73,187,257 ''refer'':144,328 ''remain'':63,133,247,317 ''revel'':68,138,252,322 ''sanctiti'':32,102,216,286 ''spirit'':26,96,210,280 ''theocrat'':29,99,213,283 ''thus'':38,108,222,292 ''typifi'':46,116,230,300 ''vindic'':19,89,203,273 ''within'':51,121,235,305', NULL, '122');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('143', '2', '143', NULL, 'After the plague - These words serve to show approximately the date at which the census was taken, and intimate the reason for the great decrease in numbers which was found to have taken place in certain tribes. Compare Deuteronomy 4:3 and Numbers 26:5 note in this chapter.', NULL, NULL, '''26'':44 ''3'':41 ''4'':40 ''5'':45 ''approxim'':9 ''census'':15 ''certain'':36 ''chapter'':49 ''compar'':38 ''date'':11 ''decreas'':25 ''deuteronomi'':39 ''found'':30 ''great'':24 ''intim'':19 ''note'':46 ''number'':27,43 ''place'':34 ''plagu'':3 ''reason'':21 ''serv'':6 ''show'':8 ''taken'':17,33 ''tribe'':37 ''word'':5', NULL, '143');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('135', '2', '135', NULL, 'The iniquity of the sanctuary - i. e. the guilt of the offences which an erring people would be continually committing against the majesty of God, when brought into contact, through the ordinances, with the manifestations of His presence. Compare the marginal reference.The iniquity of your priesthood - As the priests themselves were but men, they were strengthened to bear the iniquity of their own unintentional offences, by being entrusted with the ceremonial means of taking it away (compare Leviticus 16). The word "bear" has, in the Old Testament, this double sense of "enduring" and "removing;" but in the person of Christ, who atoned by His own endurance, the two axe in effect one.', NULL, NULL, '''16'':79 ''aton'':102 ''away'':76 ''axe'':109 ''bear'':58,82 ''brought'':27 ''ceremoni'':71 ''christ'':100 ''commit'':20 ''compar'':39,77 ''contact'':29 ''continu'':19 ''doubl'':89 ''e'':7 ''effect'':111 ''endur'':92,106 ''entrust'':68 ''err'':15 ''god'':25 ''guilt'':9 ''iniqu'':2,43,60 ''leviticus'':78 ''majesti'':23 ''manifest'':35 ''margin'':41 ''mean'':72 ''men'':53 ''offenc'':12,65 ''old'':86 ''one'':112 ''ordin'':32 ''peopl'':16 ''person'':98 ''presenc'':38 ''priest'':49 ''priesthood'':46 ''reference.the'':42 ''remov'':94 ''sanctuari'':5 ''sens'':90 ''strengthen'':56 ''take'':74 ''testament'':87 ''two'':108 ''unintent'':64 ''word'':81 ''would'':17', NULL, '135');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('136', '2', '136', NULL, 'The principle that death and all pertaining to it, as being the manifestation and result of sin Genesis 2:17, are defiling, and so lead to interruption of the living relationship between God and His people, is not now introduced for the first time, nor is it at all peculiar to the Mosaic law. It was, on the contrary, traditional among the Israelites from the earliest times, it is assumed in various enactments made already (compare Numbers 5:2; Numbers 9:6 ff; Leviticus 10:1, Leviticus 10:7; Leviticus 11:8, Leviticus 11:11, Leviticus 11:24; Leviticus 21:1 ff), and it is traceable in various forms among many nations, both ancient and modern. Moses adopted, here as elsewhere, existing and ancient customs, with significant additions, as helps in the spiritual education of his people.The ordinance was probably given at this time because the plague which happened Numbers 16:46-50 about the matter of Korah had spread the defilement of death so widely through the camp as to seem to require some special measures of purification, more particularly as the deaths through it were in an extraordinary manner the penalty of sin.', NULL, NULL, '''-50'':153 ''1'':86,101 ''10'':85,88 ''11'':91,94,95,97 ''16'':151 ''17'':20 ''2'':19,79 ''21'':100 ''24'':98 ''46'':152 ''5'':78 ''6'':82 ''7'':89 ''8'':92 ''9'':81 ''addit'':128 ''adopt'':118 ''alreadi'':75 ''among'':61,110 ''ancient'':114,124 ''assum'':70 ''camp'':169 ''compar'':76 ''contrari'':59 ''custom'':125 ''death'':4,164,184 ''defil'':22,162 ''earliest'':66 ''educ'':134 ''elsewher'':121 ''enact'':73 ''exist'':122 ''extraordinari'':190 ''ff'':83,102 ''first'':43 ''form'':109 ''genesi'':18 ''given'':141 ''god'':33 ''happen'':149 ''help'':130 ''interrupt'':27 ''introduc'':40 ''israelit'':63 ''korah'':158 ''law'':54 ''lead'':25 ''leviticus'':84,87,90,93,96,99 ''live'':30 ''made'':74 ''mani'':111 ''manifest'':13 ''manner'':191 ''matter'':156 ''measur'':177 ''modern'':116 ''mosaic'':53 ''mose'':117 ''nation'':112 ''number'':77,80,150 ''ordin'':138 ''particular'':181 ''peculiar'':50 ''penalti'':193 ''peopl'':36 ''people.the'':137 ''pertain'':7 ''plagu'':147 ''principl'':2 ''probabl'':140 ''purif'':179 ''relationship'':31 ''requir'':174 ''result'':15 ''seem'':172 ''signific'':127 ''sin'':17,195 ''special'':176 ''spiritu'':133 ''spread'':160 ''time'':44,67,144 ''traceabl'':106 ''tradit'':60 ''various'':72,108 ''wide'':166', NULL, '136');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('137', '2', '137', NULL, 'Numbers 20 and Numbers 21 narrate the journey of the people from Kadesh round Mount Seir to the heights of Pisgah, near the Jordan, and the various incidents connected with that journey (compare Numbers 33:37-41). This formed the third and last stage of the progress of Israel from Sinai to Canaan, and took place in the fortieth year of the Exodus.The incidents are apparently not narrated in a strictly chronological order (see Numbers 21:1). The leading purpose of Numbers 20 seems to be to narrate the loss by the people of their original leaders before their entrance into the land of promise.Even the whole congregation - This emphatic expression (compare Numbers 13:26; Numbers 14:1) points to a re-assembling of the people for the purpose of at last resuming the advance to the promised land. During the past 38 years the "congregation" had been bracken up. No doubt round the tabernacle there had continued an organised camp consisting of the Levites and others, which had been moved from time to time up and down the country (compare Numbers 33:18-36). But the mass of the people had been scattered over the face of the wilderness of Paran, and led a nomadic life as best suited the pasturage of the cattle; trafficking in provisions with surrounding tribes (compare Deuteronomy 2:26-29; Psalm 74:14); and availing themselves of the resources of a district which were in ancient times vastly greater than they now are.These natural resources were supplemented, where needful, by miraculous aid. The whole guidance of Israel through the wilderness is constantly referred to God''s special and immediately superintending care (Deuteronomy 8:4 following; Deuteronomy 29:5; Nehemiah 9:21; Isaiah 63:11-14; Amos 2:10, etc.).Yet though God''s extraordinary bounty was vouchsafed to them, it is probable that this period was, among the perishing generation at all events, one of great religious declension, or even apostasy. To it must no doubt be referred such passages as Ezekiel 20:15 ff; Amos 5:25 following; Hosea 9:10.Into the desert of Zin - The northeastern part of the wilderness of Paran (or, now definitely fixed by Palmer as the southeastern corner of the desert of Et-Tih, between Akabah and the head of Wady Garaiyeh.) The place of encampment was no doubt adjacent to the spring of Kadesh.In the first month - i. e. of the fortieth year of the Exodus.', NULL, NULL, '''-14'':292 ''-29'':227 ''-36'':186 ''-41'':37 ''1'':77,118 ''10'':295 ''10.into'':349 ''11'':291 ''13'':114 ''14'':117,230 ''15'':341 ''18'':185 ''2'':225,294 ''20'':2,83,340 ''21'':5,76,288 ''25'':345 ''26'':115,226 ''29'':284 ''33'':35,184 ''37'':36 ''38'':144 ''4'':281 ''5'':285,344 ''63'':290 ''74'':229 ''8'':280 ''9'':287,348 ''adjac'':394 ''advanc'':136 ''aid'':259 ''akabah'':380 ''amo'':293,343 ''among'':314 ''ancient'':243 ''apostasi'':328 ''appar'':66 ''are.these'':250 ''assembl'':124 ''avail'':232 ''best'':210 ''bounti'':302 ''bracken'':150 ''camp'':162 ''canaan'':53 ''care'':278 ''cattl'':216 ''chronolog'':72 ''compar'':33,112,182,223 ''congreg'':108,147 ''connect'':29 ''consist'':163 ''constant'':269 ''continu'':159 ''corner'':371 ''countri'':181 ''declens'':325 ''definit'':364 ''desert'':351,374 ''deuteronomi'':224,279,283 ''district'':239 ''doubt'':153,333,393 ''e'':404 ''emphat'':110 ''encamp'':390 ''entranc'':100 ''et'':377 ''et-tih'':376 ''etc'':296 ''even'':327 ''event'':320 ''exodus'':411 ''exodus.the'':63 ''express'':111 ''extraordinari'':301 ''ezekiel'':339 ''face'':198 ''ff'':342 ''first'':401 ''fix'':365 ''follow'':282,346 ''form'':39 ''fortieth'':59,407 ''garaiyeh'':386 ''generat'':317 ''god'':272,299 ''great'':323 ''greater'':246 ''guidanc'':262 ''head'':383 ''height'':19 ''hosea'':347 ''immedi'':276 ''incid'':28,64 ''isaiah'':289 ''israel'':49,264 ''jordan'':24 ''journey'':8,32 ''kadesh'':13 ''kadesh.in'':399 ''land'':103,140 ''last'':43,133 ''lead'':79 ''leader'':97 ''led'':205 ''levit'':166 ''life'':208 ''loss'':90 ''mass'':189 ''miracul'':258 ''month'':402 ''mount'':15 ''move'':172 ''must'':331 ''narrat'':6,68,88 ''natur'':251 ''near'':22 ''need'':256 ''nehemiah'':286 ''nomad'':207 ''northeastern'':355 ''number'':1,4,34,75,82,113,116,183 ''one'':321 ''order'':73 ''organis'':161 ''origin'':96 ''other'':168 ''palmer'':367 ''paran'':203,361 ''part'':356 ''passag'':337 ''past'':143 ''pasturag'':213 ''peopl'':11,93,127,192 ''period'':312 ''perish'':316 ''pisgah'':21 ''place'':56,388 ''point'':119 ''probabl'':309 ''progress'':47 ''promis'':139 ''promise.even'':105 ''provis'':219 ''psalm'':228 ''purpos'':80,130 ''re'':123 ''re-assembl'':122 ''refer'':270,335 ''religi'':324 ''resourc'':236,252 ''resum'':134 ''round'':14,154 ''scatter'':195 ''see'':74 ''seem'':84 ''seir'':16 ''sinai'':51 ''southeastern'':370 ''special'':274 ''spring'':397 ''stage'':44 ''strict'':71 ''suit'':211 ''superintend'':277 ''supplement'':254 ''surround'':221 ''tabernacl'':156 ''third'':41 ''though'':298 ''tih'':378 ''time'':174,176,244 ''took'':55 ''traffick'':217 ''tribe'':222 ''various'':27 ''vast'':245 ''vouchsaf'':304 ''wadi'':385 ''whole'':107,261 ''wilder'':201,267,359 ''year'':60,145,408 ''yet'':297 ''zin'':353', NULL, '137');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('138', '2', '138', NULL, 'King Arad the Canaanite - Rather, "the Canaanite, the king of Arad." Arad stood on a small hill, now called Tel-Arad, 20 miles south of Hebron.In the south - See Numbers 13:17, Numbers 13:22.By the way of the spies - i. e. through the desert of Zin, the route which the spies sent out by Moses 38 years before had adopted (compare Numbers 13:21).He fought against Israel - This attack (compare Numbers 20:1 and note), can hardly have taken place after the death of Aaron. It was most probably made just when the camp broke up from Kadesh, and the ultimate direction of the march was not as yet pronounced. The order of the narrative in these chapters, as occasionally elsewhere in this book (compare Numbers 9:1, etc.), is not that of time, but of subject matter; and the war against Arad is introduced here as the first of the series of victories gained under Moses, which the historian now takes in hand to narrate.', NULL, NULL, '''1'':76,131 ''13'':32,35,65 ''17'':33 ''20'':23,75 ''21'':66 ''22.by'':36 ''38'':58 ''9'':130 ''aaron'':88 ''adopt'':62 ''arad'':2,11,12,22,146 ''attack'':72 ''book'':127 ''broke'':98 ''call'':19 ''camp'':97 ''canaanit'':4,7 ''chapter'':121 ''compar'':63,73,128 ''death'':86 ''desert'':46 ''direct'':105 ''e'':43 ''elsewher'':124 ''etc'':132 ''first'':152 ''fought'':68 ''gain'':158 ''hand'':167 ''hard'':80 ''hebron.in'':27 ''hill'':17 ''historian'':163 ''introduc'':148 ''israel'':70 ''kadesh'':101 ''king'':1,9 ''made'':93 ''march'':108 ''matter'':141 ''mile'':24 ''mose'':57,160 ''narrat'':118,169 ''note'':78 ''number'':31,34,64,74,129 ''occasion'':123 ''order'':115 ''place'':83 ''probabl'':92 ''pronounc'':113 ''rather'':5 ''rout'':50 ''see'':30 ''sent'':54 ''seri'':155 ''small'':16 ''south'':25,29 ''spi'':41,53 ''stood'':13 ''subject'':140 ''take'':165 ''taken'':82 ''tel'':21 ''tel-arad'':20 ''time'':137 ''ultim'':104 ''victori'':157 ''war'':144 ''way'':38 ''year'':59 ''yet'':112 ''zin'':48', NULL, '138');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('139', '2', '139', NULL, 'The plains - Hebrew   arabah; the word is the plural of that which is used to denote the whole depressed tract along the Jordan and the Dead Sea, and onward, where it is still called the Arabah (compare Numbers 21:4 note), to the Elanitic gulf.On this side Jordan by Jericho - Rather, across the Jordan of Jericho, i. e., that part of Jordan which skirted the territory of Jericho. This form of expression indicates the site of the camp in its relation to the well-known city of Jericho. See Deuteronomy 1:1.', NULL, NULL, '''1'':92,93 ''21'':39 ''4'':40 ''across'':52 ''along'':21 ''arabah'':4,36 ''call'':34 ''camp'':78 ''citi'':87 ''compar'':37 ''dead'':26 ''denot'':16 ''depress'':19 ''deuteronomi'':91 ''e'':58 ''elanit'':44 ''express'':72 ''form'':70 ''gulf.on'':45 ''hebrew'':3 ''indic'':73 ''jericho'':50,56,68,89 ''jordan'':23,48,54,62 ''known'':86 ''note'':41 ''number'':38 ''onward'':29 ''part'':60 ''plain'':2 ''plural'':9 ''rather'':51 ''relat'':81 ''sea'':27 ''see'':90 ''side'':47 ''site'':75 ''skirt'':64 ''still'':33 ''territori'':66 ''tract'':20 ''use'':14 ''well'':85 ''well-known'':84 ''whole'':18 ''word'':6', NULL, '139');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1044', '2', '1044', NULL, 'See this parable explained in the notes at Matthew 21:33-46.See this parable explained in the notes at Matthew 21:33-46.', NULL, NULL, '''-46'':22 ''21'':10,20 ''33'':21 ''33-46.see'':11 ''explain'':4,14 ''matthew'':9,19 ''note'':7,17 ''parabl'':3,13 ''see'':1', NULL, '969');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('144', '2', '144', NULL, 'Women in Israel had not, up to the present time, enjoyed any distinct right of inheritance. Yet a father, whether sons had been born to him or not, had the power, either before or at his death, to cause part of his estate to pass to a daughter; in which case her husband married into her family rather than she into his, and the children were regarded as of the family from which the estate had come. Thus, Machir, ancestor of Zelophehad, although he had a son Gilead, left also, as is probable, an inheritance to his daughter, the wife of Hezron of the tribe of Judah, by reason of which their descendants, among whom was Jair, were reckoned as belonging to the tribe of Manasseh (Numbers 32:41; 1 Chronicles 2:21 ff).', NULL, NULL, '''1'':130 ''2'':132 ''21'':133 ''32'':128 ''41'':129 ''also'':90 ''although'':83 ''among'':114 ''ancestor'':80 ''belong'':121 ''born'':24 ''case'':51 ''caus'':39 ''children'':65 ''chronicl'':131 ''come'':77 ''daughter'':48,98 ''death'':37 ''descend'':113 ''distinct'':13 ''either'':32 ''enjoy'':11 ''estat'':43,75 ''famili'':57,71 ''father'':19 ''ff'':134 ''gilead'':88 ''hezron'':102 ''husband'':53 ''inherit'':16,95 ''israel'':3 ''jair'':117 ''judah'':107 ''left'':89 ''machir'':79 ''manasseh'':126 ''marri'':54 ''number'':127 ''part'':40 ''pass'':45 ''power'':31 ''present'':9 ''probabl'':93 ''rather'':58 ''reason'':109 ''reckon'':119 ''regard'':67 ''right'':14 ''son'':21,87 ''thus'':78 ''time'':10 ''tribe'':105,124 ''whether'':20 ''wife'':100 ''women'':1 ''yet'':17 ''zelophehad'':82', NULL, '144');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('145', '2', '145', NULL, 'The daily offering had been already commanded Exodus 29:38, and no doubt additional offerings had become customary on festivals. But no such elaborate system as is here prescribed was or could possibly have been observed in the wilderness: compare Deuteronomy 12:8-9. The regulations of this and the next chapter therefore point to the immediate prospect of that settlement in Canaan which alone could enable the Israelites to obey them. Compare the ordinances in Numbers 15.', NULL, NULL, '''-9'':44 ''12'':42 ''15'':78 ''29'':9 ''38'':10 ''8'':43 ''addit'':14 ''alon'':65 ''alreadi'':6 ''becom'':17 ''canaan'':63 ''chapter'':52 ''command'':7 ''compar'':40,73 ''could'':32,66 ''customari'':18 ''daili'':2 ''deuteronomi'':41 ''doubt'':13 ''elabor'':24 ''enabl'':67 ''exodus'':8 ''festiv'':20 ''immedi'':57 ''israelit'':69 ''next'':51 ''number'':77 ''obey'':71 ''observ'':36 ''offer'':3,15 ''ordin'':75 ''point'':54 ''possibl'':33 ''prescrib'':29 ''prospect'':58 ''regul'':46 ''settlement'':61 ''system'':25 ''therefor'':53 ''wilder'':39', NULL, '145');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('146', '2', '146', NULL, 'The ordinance of the Feast of Trumpets was to be observed on the opening day of that month within which the great Day of the Atonement and the Feast of Tabernacles fell (compare Leviticus 23:23 ff). The special offering for the day anticipated that of the great Day of Atonement.', NULL, NULL, '''23'':35,36 ''anticip'':44 ''aton'':26,51 ''compar'':33 ''day'':15,23,43,49 ''feast'':5,29 ''fell'':32 ''ff'':37 ''great'':22,48 ''leviticus'':34 ''month'':18 ''observ'':11 ''offer'':40 ''open'':14 ''ordin'':2 ''special'':39 ''tabernacl'':31 ''trumpet'':7 ''within'':19', NULL, '146');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('147', '2', '147', NULL, 'The regulations respecting vows appropriately follow those given respecting sacrifices, since a large proportion of vows would always relate to the presentation of such offerings. Rules had already been given Leviticus 27 for the estimation of things vowed to God. It is probable that this fresh legislation dealing especially with vows made by persons in a state of tutelage, was occasioned by some case of practical difficulty that had recently arisen; and it is addressed by Moses to "the heads of the tribes" Numbers 30:1, who would in their judicial capacity have to determine questions on these subjects.There is no provision in the chapter for annulling vows made by boys and young men; from which it has been inferred that the vows of males were in all cases and circumstances binding.', NULL, NULL, '''1'':86 ''27'':32 ''30'':85 ''address'':75 ''alreadi'':28 ''alway'':18 ''annul'':107 ''appropri'':5 ''arisen'':71 ''bind'':132 ''boy'':111 ''capac'':92 ''case'':64,129 ''chapter'':105 ''circumst'':131 ''deal'':48 ''determin'':95 ''difficulti'':67 ''especi'':49 ''estim'':35 ''follow'':6 ''fresh'':46 ''given'':8,30 ''god'':40 ''head'':80 ''infer'':120 ''judici'':91 ''larg'':13 ''legisl'':47 ''leviticus'':31 ''made'':52,109 ''male'':125 ''men'':114 ''mose'':77 ''number'':84 ''occas'':61 ''offer'':25 ''person'':54 ''practic'':66 ''present'':22 ''probabl'':43 ''proport'':14 ''provis'':102 ''question'':96 ''recent'':70 ''regul'':2 ''relat'':19 ''respect'':3,9 ''rule'':26 ''sacrific'':10 ''sinc'':11 ''state'':57 ''subjects.there'':99 ''thing'':37 ''tribe'':83 ''tutelag'':59 ''vow'':4,16,38,51,108,123 ''would'':17,88 ''young'':113', NULL, '147');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('148', '2', '148', NULL, 'The Midianites - The Moabites are not included. It would thus seem that it was the Midianites, and they only, who deliberately set themselves to work the corruption of Israel.', NULL, NULL, '''corrupt'':27 ''deliber'':21 ''includ'':7 ''israel'':29 ''midianit'':2,16 ''moabit'':4 ''seem'':11 ''set'':22 ''thus'':10 ''work'':25 ''would'':9', NULL, '148');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('149', '2', '149', NULL, 'Jazer - Compare the marginal reference. This district, although included in the land of Gilead, seems to have had special attractions for the Israelite settlers. All travelers in Gilead, the modern Belka, bear witness to its richness as compared with the country to the west of the Jordan. Its general character is that of an upland pasture, undulating and thickly timbered. In the last respect its northern portions excel its southern; but for fertility of soil the southern province is preferred by the Arabs, in whose lips it has passed into a proverb: "Thou canst not find a country like the Belka."', NULL, NULL, '''although'':8 ''arab'':83 ''attract'':20 ''bear'':32 ''belka'':31,101 ''canst'':94 ''charact'':50 ''compar'':2,38 ''countri'':41,98 ''district'':7 ''excel'':68 ''fertil'':73 ''find'':96 ''general'':49 ''gilead'':14,28 ''includ'':9 ''israelit'':23 ''jazer'':1 ''jordan'':47 ''land'':12 ''last'':63 ''like'':99 ''lip'':86 ''margin'':4 ''modern'':30 ''northern'':66 ''pass'':89 ''pastur'':56 ''portion'':67 ''prefer'':80 ''proverb'':92 ''provinc'':78 ''refer'':5 ''respect'':64 ''rich'':36 ''seem'':15 ''settler'':24 ''soil'':75 ''southern'':70,77 ''special'':19 ''thick'':59 ''thou'':93 ''timber'':60 ''travel'':26 ''undul'':57 ''upland'':55 ''west'':44 ''whose'':85 ''wit'':33', NULL, '149');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('150', '2', '150', NULL, 'This list was written out by Moses at God''s command Numbers 33:2, doubtless as a memorial of God''s providential care for His people throughout this long and trying period.Numbers 33:3-6. For these places, see the marginal reference.', NULL, NULL, '''-6'':35 ''2'':14 ''3'':34 ''33'':13,33 ''care'':23 ''command'':11 ''doubtless'':15 ''god'':9,20 ''list'':2 ''long'':29 ''margin'':41 ''memori'':18 ''mose'':7 ''number'':12 ''peopl'':26 ''period.numbers'':32 ''place'':38 ''providenti'':22 ''refer'':42 ''see'':39 ''throughout'':27 ''tri'':31 ''written'':4', NULL, '150');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('151', '2', '151', NULL, 'The southern boundary commenced at the Dead Sea. The broad and desolate valley by which the depressed bed of that sea is protected toward the south, is called the Ghor. A deep narrow glen enters it at its southwest corner; it is called Wady-el-Fikreh, and is continued in the same southwestern direction, under the name of Wady el-Marrah; a wady which loses itself among the hills belonging to "the wilderness of Zin;" and Kadesh-barnea (see Numbers 13:26 note), which is "in the wilderness of Zin," will be, as the text implies, the southernmost point of the southern boundary. Thence, if Kadesh be identical with the present Ain el-Weibeh, westward to the river, or brook of Egypt, now Wady el-Arish, is a distance of about seventy miles. In this interval were Hazar-addar and Azmon; the former being perhaps the general name of a district of Hazerim, or nomad hamlets (see Deuteronomy 2:23), of which Adder was one: and Azmon, perhaps to be identified with Kesam, the modern Kasaimeh, a group of springs situate in the north of one of the gaps in the ridge, and a short distance west of Ain el-Kudeirat.(Others consider the boundary line to have followed the Ghor along the Arabah to the south of the Azazimeh mountains, thence to Gadis round the southeast of that mountain, and thence to Wady el-Arish.)', NULL, NULL, '''13'':84 ''2'':165 ''23'':166 ''26'':85 ''addar'':145 ''adder'':169 ''ain'':115,205 ''along'':219 ''among'':69 ''arabah'':221 ''arish'':131,244 ''azazimeh'':227 ''azmon'':147,173 ''barnea'':81 ''bed'':18 ''belong'':72 ''boundari'':3,106,212 ''broad'':10 ''brook'':124 ''call'':28,43 ''commenc'':4 ''consid'':210 ''continu'':50 ''corner'':40 ''dead'':7 ''deep'':32 ''depress'':17 ''desol'':12 ''deuteronomi'':164 ''direct'':55 ''distanc'':134,202 ''district'':157 ''egypt'':126 ''el'':46,62,117,130,207,243 ''el-arish'':129,242 ''el-kudeirat'':206 ''el-marrah'':61 ''el-weibeh'':116 ''enter'':35 ''fikreh'':47 ''follow'':216 ''former'':149 ''gadi'':231 ''gap'':195 ''general'':153 ''ghor'':30,218 ''glen'':34 ''group'':184 ''hamlet'':162 ''hazar'':144 ''hazar-addar'':143 ''hazerim'':159 ''hill'':71 ''ident'':111 ''identifi'':177 ''impli'':99 ''interv'':141 ''kadesh'':80,109 ''kadesh-barnea'':79 ''kasaimeh'':182 ''kesam'':179 ''kudeirat'':208 ''line'':213 ''lose'':67 ''marrah'':63 ''mile'':138 ''modern'':181 ''mountain'':228,237 ''name'':58,154 ''narrow'':33 ''nomad'':161 ''north'':190 ''note'':86 ''number'':83 ''one'':171,192 ''other'':209 ''perhap'':151,174 ''point'':102 ''present'':114 ''protect'':23 ''ridg'':198 ''river'':122 ''round'':232 ''sea'':8,21 ''see'':82,163 ''seventi'':137 ''short'':201 ''situat'':187 ''south'':26,224 ''southeast'':234 ''southern'':2,105 ''southernmost'':101 ''southwest'':39 ''southwestern'':54 ''spring'':186 ''text'':98 ''thenc'':107,229,239 ''toward'':24 ''valley'':13 ''wadi'':45,60,65,128,241 ''wady-el-fikreh'':44 ''weibeh'':118 ''west'':203 ''westward'':119 ''wilder'':75,91 ''zin'':77,93', NULL, '151');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('152', '2', '152', NULL, 'Suburbs - Rather, "pasture-grounds," required for their large cattle, for their sheep and goats, and for all their beasts whatever they might be Numbers 35:3.', NULL, NULL, '''3'':27 ''35'':26 ''beast'':20 ''cattl'':10 ''goat'':15 ''ground'':5 ''larg'':9 ''might'':23 ''number'':25 ''pastur'':4 ''pasture-ground'':3 ''rather'':2 ''requir'':6 ''sheep'':13 ''suburb'':1 ''whatev'':21', NULL, '152');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('153', '2', '153', NULL, 'The daughters of Zelophehad had obtained an ordinance Numbers 28:6-11 which permitted the daughters of an Israelite dying without male issue to inherit their father''s property. The chiefs of the Machirites, of whom Zelophehad had been one, now obtain a supplemental enactment, directing that heiresses should marry within their own tribe.', NULL, NULL, '''-11'':12 ''28'':10 ''6'':11 ''chief'':31 ''daughter'':2,16 ''die'':20 ''direct'':46 ''enact'':45 ''father'':27 ''heiress'':48 ''inherit'':25 ''israelit'':19 ''issu'':23 ''machirit'':34 ''male'':22 ''marri'':50 ''number'':9 ''obtain'':6,42 ''one'':40 ''ordin'':8 ''permit'':14 ''properti'':29 ''supplement'':44 ''tribe'':54 ''within'':51 ''without'':21 ''zelophehad'':4,37', NULL, '153');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1033', '2', '1033', NULL, 'begotten Son of God - equal with the Father. And,3. Because Jesus was anointed (set apart) to the work of the Messiah, the mediator between God and man.', NULL, NULL, '''3'':10 ''anoint'':14 ''apart'':16 ''begotten'':1 ''equal'':5 ''father'':8 ''god'':4,26 ''jesus'':12 ''man'':28 ''mediat'':24 ''messiah'':22 ''set'':15 ''son'':2 ''work'':19', NULL, '958');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1031', '2', '1031', NULL, 'The beginning of the gospel - The word "gospel" literally signifies good news, and particularly the good tidings respecting the way of salvation by the Lord Jesus Christ. Some have understood the word "gospel" here to mean "history" or "life - the beginning of the history," etc.; but Mark says nothing of the early life of the Saviour. The word "gospel" here has reference rather to the preaching of John, an account of which immediately follows, and means the beginning of the good news, or annunciation respecting the Messiah. It was very customary thus to prefix a title to a book.The Son of God - This title was used here to attract attention, and secure the respect of those who should read the gospel. It is no common history. It does not recount the deeds of man - of a hero or a philosopher ', NULL, NULL, '''account'':70 ''annunci'':84 ''attent'':110 ''attract'':109 ''begin'':2,41,78 ''book.the'':99 ''christ'':27 ''common'':125 ''customari'':91 ''deed'':132 ''earli'':52 ''etc'':45 ''follow'':74 ''god'':102 ''good'':11,16,81 ''gospel'':5,8,33,59,121 ''hero'':137 ''histori'':37,44,126 ''immedi'':73 ''jesus'':26 ''john'':68 ''life'':39,53 ''liter'':9 ''lord'':25 ''man'':134 ''mark'':47 ''mean'':36,76 ''messiah'':87 ''news'':12,82 ''noth'':49 ''particular'':14 ''philosoph'':140 ''preach'':66 ''prefix'':94 ''rather'':63 ''read'':119 ''recount'':130 ''refer'':62 ''respect'':18,85,114 ''salvat'':22 ''saviour'':56 ''say'':48 ''secur'':112 ''signifi'':10 ''son'':100 ''thus'':92 ''tide'':17 ''titl'':96,104 ''understood'':30 ''use'':106 ''way'':20 ''word'':7,32,58', NULL, '958');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1032', '2', '1032', NULL, '- but the doctrines and doings of the Son of God. The history, therefore, "commands" respect.', NULL, NULL, '''command'':14 ''do'':5 ''doctrin'':3 ''god'':10 ''histori'':12 ''respect'':15 ''son'':8 ''therefor'':13', NULL, '958');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1034', '2', '1034', NULL, 'Into Capernaum - See the notes at Matthew 4:13.After some days - The number of days is not known. Jesus probably remained long enough in the desert to heal the sick who were brought to him, and to give instructions to the multitudes who attended his preaching. Capernaum was not "the city" mentioned in Mark 1:45, and it is probable that there was no difficulty in his remaining there and preaching.And it was noised ... - He entered the city, doubtless, privately; but his being there was soon known, and so great had his popularity become that multitudes pressed to hear him.', NULL, NULL, '''1'':55 ''13.after'':9 ''4'':8 ''45'':56 ''attend'':44 ''becom'':94 ''brought'':33 ''capernaum'':2,47 ''citi'':51,78 ''day'':11,15 ''desert'':26 ''difficulti'':65 ''doubtless'':79 ''enough'':23 ''enter'':76 ''give'':38 ''great'':90 ''heal'':28 ''hear'':99 ''instruct'':39 ''jesus'':19 ''known'':18,87 ''long'':22 ''mark'':54 ''matthew'':7 ''mention'':52 ''multitud'':42,96 ''nois'':74 ''note'':5 ''number'':13 ''popular'':93 ''preach'':46 ''preaching.and'':71 ''press'':97 ''privat'':80 ''probabl'':20,60 ''remain'':21,68 ''see'':3 ''sick'':30 ''soon'':86', NULL, '959');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1045', '2', '1045', NULL, 'What manner of stones - The stones here referred to were those used in the building of the temple, and the walls on the sides of Mount Moriah, on which the temple stood. The temple was constructed of white marble, and the blocks were of a prodigious size. Josephus says that these stones were, some of them, 50 feet long, 24 feet broad, and 16 feet in thickness.', NULL, NULL, '''16'':64 ''24'':60 ''50'':57 ''block'':42 ''broad'':62 ''build'':15 ''construct'':36 ''feet'':58,61,65 ''josephus'':48 ''long'':59 ''manner'':2 ''marbl'':39 ''moriah'':27 ''mount'':26 ''prodigi'':46 ''refer'':8 ''say'':49 ''side'':24 ''size'':47 ''stone'':4,6,52 ''stood'':32 ''templ'':18,31,34 ''thick'':67 ''use'':12 ''wall'':21 ''white'':38', NULL, '970');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1046', '2', '1046', NULL, 'See this passage explained in the notes at Matthew 26:1-16.Mark 14:1And of unleavened bread - So called because at that feast no other bread was used but that which had been made without leaven or yeast.By craft - By subtlety (Matthew); that is, by some secret plan that would secure possession of him without exciting the opposition of the people.', NULL, NULL, '''1-16.mark'':11 ''14'':12 ''1and'':13 ''26'':10 ''bread'':16,25 ''call'':18 ''craft'':38 ''excit'':55 ''explain'':4 ''feast'':22 ''leaven'':35 ''made'':33 ''matthew'':9,41 ''note'':7 ''opposit'':57 ''passag'':3 ''peopl'':60 ''plan'':47 ''possess'':51 ''secret'':46 ''secur'':50 ''see'':1 ''subtleti'':40 ''unleaven'':15 ''use'':27 ''without'':34,54 ''would'':49 ''yeast.by'':37', NULL, '971');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1035', '2', '1035', NULL, 'Or to do evil? to save life, or to kill? - It seems to have been a maxim with the Jews that not to do good when we have an opportunity is to do evil; not to save life is to kill or to be guilty of murder. If a man has an opportunity of saving a man''s life when he is in danger, and does not do it, he is evidently guilty of his death. On this principle our Saviour puts this question to the Jews - whether it was better for him, having the power to heal this man, to do it, or to suffer him to remain in this suffering condition; and he illustrates it by an example, showing that in a manner of much less importance - that respecting their cattle - they would do on the Sabbath just as "he" would if he should heal this man. The same remark may apply to all opportunities of doing good. "The ability to do good imposes an obligation to do it" (Cotton Mather) He that has the means of feeding the hungry, and clothing the naked, and instructing the ignorant, and sending the gospel to the destitute, and that does it not, is guilty, for he is practically doing evil; he is suffering evils to exist which he might remove. So the wicked will be condemned in the day of judgment because "they did it not," Matthew 25:45. If this is true, what an obligation rests upon the rich to do good!', NULL, NULL, '''25'':238 ''45'':239 ''abil'':162 ''appli'':154 ''better'':91 ''cattl'':133 ''cloth'':184 ''condemn'':226 ''condit'':113 ''cotton'':172 ''danger'':64 ''day'':229 ''death'':76 ''destitut'':197 ''evid'':72 ''evil'':4,34,210,214 ''exampl'':120 ''exist'':216 ''feed'':180 ''good'':25,160,165,253 ''gospel'':194 ''guilti'':45,73,204 ''heal'':98,147 ''hungri'':182 ''ignor'':190 ''illustr'':116 ''import'':129 ''impos'':166 ''instruct'':188 ''jew'':20,87 ''judgment'':231 ''kill'':10,41 ''less'':128 ''life'':7,38,59 ''man'':50,57,100,149 ''manner'':125 ''mather'':173 ''matthew'':237 ''maxim'':17 ''may'':153 ''mean'':178 ''might'':219 ''much'':127 ''murder'':47 ''nake'':186 ''oblig'':168,246 ''opportun'':30,53,157 ''power'':96 ''practic'':208 ''principl'':79 ''put'':82 ''question'':84 ''remain'':109 ''remark'':152 ''remov'':220 ''respect'':131 ''rest'':247 ''rich'':250 ''sabbath'':139 ''save'':6,37,55 ''saviour'':81 ''seem'':12 ''send'':192 ''show'':121 ''suffer'':106,112,213 ''true'':243 ''upon'':248 ''whether'':88 ''wick'':223 ''would'':135,143', NULL, '960');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1036', '2', '1036', NULL, 'See the parable of the sower explained in the notes at Matthew 13:1-9.See the parable of the sower explained in the notes at Matthew 13:1-9.', NULL, NULL, '''-9'':28 ''1'':27 ''1-9.see'':14 ''13'':13,26 ''explain'':7,20 ''matthew'':12,25 ''note'':10,23 ''parabl'':3,16 ''see'':1 ''sower'':6,19', NULL, '961');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1037', '2', '1037', NULL, 'He had been often bound with fetters and chains - Efforts had been made to confine him, but his great strength - his strength increased by his malady - had prevented it. There often appears to be a great increase of strength produced by insanity, and what is here stated in regard to this maniac often occurs in Palestine and elsewhere now. Dr. Thomson ("The Land and the Book," vol. i. p. 213) says respecting this case: "There are some very similar at the present day - furious and dangerous maniacs, who wander about the mountains, and sleep in tombs and caves. In their worst paroxysms they are quite unmanageable and prodigiously strong." Luke 8:27 says of him that "he were no clothes," or that he was naked, which is also implied in the account in Mark, who tells us that after he was healed he was found "clothed and in his right mind," Mark 4:15. This is often a striking characteristic of insanity. Dr. Pritchard (on "Insanity," p. 26) quotes from an Italian physician''s description of raving madness or mania: "A striking and characteristic circumstance is the propensity to go quite naked. The patient tears his clothes to tatters." So Dr. Thomson ("The Land and the Book," vol. i. p. 213) says: "It is one of the most common traits in this madness that the victims refuse to wear clothes. I have often seen them absolutely naked in the crowded streets of Beirut and Sidon. There are also cases in which they run wildly about the country and frighten the whole neighborhood. These poor wretches are held in the greatest reverence by Muslims, who, through some monstrous perversion of ideas, believe them to be inspired and peculiarly holy."', NULL, NULL, '''15'':154 ''213'':70,211 ''26'':168 ''27'':112 ''4'':153 ''8'':111 ''absolut'':236 ''account'':132 ''also'':128,248 ''appear'':32 ''beirut'':243 ''believ'':281 ''book'':66,207 ''bound'':5 ''case'':74,249 ''cave'':98 ''chain'':9 ''characterist'':160,184 ''circumst'':185 ''cloth'':120,146,197,230 ''common'':219 ''confin'':15 ''countri'':257 ''crowd'':240 ''danger'':86 ''day'':83 ''descript'':175 ''dr'':60,163,201 ''effort'':10 ''elsewher'':58 ''fetter'':7 ''found'':145 ''frighten'':259 ''furious'':84 ''go'':190 ''great'':19,36 ''greatest'':270 ''heal'':142 ''held'':267 ''holi'':288 ''idea'':280 ''impli'':129 ''increas'':23,37 ''insan'':42,162,166 ''inspir'':285 ''italian'':172 ''land'':63,204 ''luke'':110 ''mad'':178,223 ''made'':13 ''maladi'':26 ''mania'':180 ''maniac'':52,87 ''mark'':134,152 ''mind'':151 ''monstrous'':277 ''mountain'':92 ''muslim'':273 ''nake'':125,192,237 ''neighborhood'':262 ''occur'':54 ''often'':4,31,53,157,233 ''one'':215 ''p'':69,167,210 ''palestin'':56 ''paroxysm'':102 ''patient'':194 ''peculiar'':287 ''pervers'':278 ''physician'':173 ''poor'':264 ''present'':82 ''prevent'':28 ''pritchard'':164 ''prodigi'':108 ''produc'':40 ''propens'':188 ''quit'':105,191 ''quot'':169 ''rave'':177 ''refus'':227 ''regard'':49 ''respect'':72 ''rever'':271 ''right'':150 ''run'':253 ''say'':71,113,212 ''seen'':234 ''sidon'':245 ''similar'':79 ''sleep'':94 ''state'':47 ''street'':241 ''strength'':20,22,39 ''strike'':159,182 ''strong'':109 ''tatter'':199 ''tear'':195 ''tell'':136 ''thomson'':61,202 ''tomb'':96 ''trait'':220 ''unmanag'':106 ''us'':137 ''victim'':226 ''vol'':67,208 ''wander'':89 ''wear'':229 ''whole'':261 ''wild'':254 ''worst'':101 ''wretch'':265', NULL, '962');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1038', '2', '1038', NULL, 'In ranks - Literally, in the form of square beds in a garden. By regularly formed companies.By hundreds and by fifties - Some companies had a hundred in them, and some groupings had fifty in them. We do not need to suppose that these were "exactly" formed or arranged, but that this was approximately the number. The expression indicates a "multitude." There were so many that they sat down, by "hundreds" and by "fifties," in separate companies, upon the green grass.', NULL, NULL, '''approxim'':52 ''arrang'':47 ''bed'':9 ''compani'':22,75 ''companies.by'':16 ''exact'':44 ''express'':56 ''fifti'':20,32,72 ''form'':6,15,45 ''garden'':12 ''grass'':79 ''green'':78 ''group'':30 ''hundr'':17,25,69 ''indic'':57 ''liter'':3 ''mani'':63 ''multitud'':59 ''need'':38 ''number'':54 ''rank'':2 ''regular'':14 ''sat'':66 ''separ'':74 ''squar'':8 ''suppos'':40 ''upon'':76', NULL, '963');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1039', '2', '1039', NULL, 'See this passage explained in the notes at Matthew 15:1-20.Mark 7:1Came from Jerusalem - Probably to observe his conduct, and to find matter of accusation against him.', NULL, NULL, '''1-20.mark'':11 ''15'':10 ''1came'':13 ''7'':12 ''accus'':26 ''conduct'':20 ''explain'':4 ''find'':23 ''jerusalem'':15 ''matter'':24 ''matthew'':9 ''note'':7 ''observ'':18 ''passag'':3 ''probabl'':16 ''see'':1', NULL, '964');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1040', '2', '1040', NULL, 'See this passage explained in the notes at Matthew 15:32-39.Mark 8:1In those days - While in the wilderness, where he had cured the deaf-mute man.Having nothing to eat - Having come unprovided, or having consumed what they had brought.', NULL, NULL, '''15'':10 ''1in'':13 ''32-39.mark'':11 ''8'':12 ''brought'':41 ''come'':33 ''consum'':37 ''cure'':23 ''day'':15 ''deaf'':26 ''deaf-mut'':25 ''eat'':31 ''explain'':4 ''man.having'':28 ''matthew'':9 ''mute'':27 ''note'':7 ''noth'':29 ''passag'':3 ''see'':1 ''unprovid'':34 ''wilder'':19', NULL, '965');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1041', '2', '1041', NULL, 'Verily I say ... - See the notes at Matthew 16:28. This verse properly belongs to the preceding chapter and the preceding discourse.', NULL, NULL, '''16'':9 ''28'':10 ''belong'':14 ''chapter'':18 ''discours'':22 ''matthew'':8 ''note'':6 ''preced'':17,21 ''proper'':13 ''say'':3 ''see'':4 ''verili'':1 ''vers'':12', NULL, '966');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1042', '2', '1042', NULL, 'And if a woman shall put away her husband - It would seem, from this, that a woman, among the Jews, had the power of separating herself from her husband, yet this right is not given her by the law of Moses. There is not, however, any positive evidence that females often claimed or exercised this right. Cases had occurred, indeed, in which it had been done. The wife of Herod had rejected her former husband and married Herod. And though instances of this kind "might" have been attempted to be defended by the example of Pagans, yet our Saviour was desirous of showing them that it did not free them from the charge of adultery. The apostles were going forth to teach Pagan nations, and it was proper for Christ to teach them how to act in such cases, and to show them that they were cases of real adultery.', NULL, NULL, '''act'':136 ''adulteri'':115,150 ''among'':18 ''apostl'':117 ''attempt'':88 ''away'':7 ''case'':57,139,147 ''charg'':113 ''christ'':130 ''claim'':52 ''defend'':91 ''desir'':101 ''done'':66 ''evid'':48 ''exampl'':94 ''exercis'':54 ''femal'':50 ''former'':74 ''forth'':120 ''free'':109 ''given'':35 ''go'':119 ''herod'':70,78 ''howev'':45 ''husband'':9,29,75 ''inde'':60 ''instanc'':81 ''jew'':20 ''kind'':84 ''law'':39 ''marri'':77 ''might'':85 ''mose'':41 ''nation'':124 ''occur'':59 ''often'':51 ''pagan'':96,123 ''posit'':47 ''power'':23 ''proper'':128 ''put'':6 ''real'':149 ''reject'':72 ''right'':32,56 ''saviour'':99 ''seem'':12 ''separ'':25 ''shall'':5 ''show'':103,142 ''teach'':122,132 ''though'':80 ''wife'':68 ''woman'':4,17 ''would'':11 ''yet'':30,97', NULL, '967');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1043', '2', '1043', NULL, 'What do ye, loosing the colt? - Or, why do ye do this? What authority have you for doing it?See this passage illustrated in the notes at Matthew 21:1-16.', NULL, NULL, '''-16'':31 ''1'':30 ''21'':29 ''author'':14 ''colt'':6 ''illustr'':23 ''loos'':4 ''matthew'':28 ''note'':26 ''passag'':22 ''see'':20 ''ye'':3,10', NULL, '968');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1048', '2', '1048', NULL, 'See this passage explained in the notes at Matthew 28:1-8.Mark 16:1Sweet spices - "Aromatics." Substances used in embalming. The idea of sweetness is not, however, implied in the original. Many of the substances used for embalming were "bitter" - as, for example, myrrh - and none of them, perhaps, could properly be called "sweet." The word "spices" expresses all that there is in the original.Anoint him - Embalm him, or apply these spices to his body to keep it from putrefaction. This is proof that they did not suppose he would rise again; and the fact that they did not "expect" he would rise, gives more strength to the evidence for his resurrection.', NULL, NULL, '''1-8.mark'':11 ''16'':12 ''1sweet'':13 ''28'':10 ''appli'':69 ''aromat'':15 ''bitter'':39 ''bodi'':74 ''call'':52 ''could'':49 ''embalm'':19,37,66 ''evid'':108 ''exampl'':42 ''expect'':99 ''explain'':4 ''express'':57 ''fact'':94 ''give'':103 ''howev'':26 ''idea'':21 ''impli'':27 ''keep'':76 ''mani'':31 ''matthew'':9 ''myrrh'':43 ''none'':45 ''note'':7 ''origin'':30 ''original.anoint'':64 ''passag'':3 ''perhap'':48 ''proof'':82 ''proper'':50 ''putrefact'':79 ''resurrect'':111 ''rise'':90,102 ''see'':1 ''spice'':14,56,71 ''strength'':105 ''substanc'':16,34 ''suppos'':87 ''sweet'':23,53 ''use'':17,35 ''word'':55 ''would'':89,101', NULL, '973');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1049', '2', '1049', NULL, 'Forasmuch as many - It has been doubted who are referred to here by the word "many." It seems clear that it could not be the other evangelists, for the gospel by "John" was not yet written, and the word "many" denotes clearly more than "two." Besides, it is said that they undertook to record what the "eye-witnesses" had delivered to them, so that the writers did not pretend to be eye-witnesses themselves. It is clear, therefore, that other writings are meant than the gospels which we now have, but what they were is a matter of conjecture. What are now known as spurious gospels were written long after Luke wrote his. It is probable that Luke refers to "fragments" of history, or to narratives of "detached" sayings, acts, or parables of our Lord, which had been made and circulated among the d', NULL, NULL, '''act'':132 ''among'':144 ''besid'':46 ''circul'':143 ''clear'':19,42,79 ''conjectur'':101 ''could'':22 ''d'':146 ''deliv'':61 ''denot'':41 ''detach'':130 ''doubt'':7 ''evangelist'':27 ''eye'':58,74 ''eye-wit'':57,73 ''forasmuch'':1 ''fragment'':123 ''gospel'':30,88,108 ''histori'':125 ''john'':32 ''known'':105 ''long'':111 ''lord'':137 ''luke'':113,120 ''made'':141 ''mani'':3,16,40 ''matter'':99 ''meant'':85 ''narrat'':128 ''parabl'':134 ''pretend'':70 ''probabl'':118 ''record'':54 ''refer'':10,121 ''said'':49 ''say'':131 ''seem'':18 ''spurious'':107 ''therefor'':80 ''two'':45 ''undertook'':52 ''wit'':59,75 ''word'':15,39 ''write'':83 ''writer'':67 ''written'':36,110 ''wrote'':114 ''yet'':35', NULL, '974');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1050', '2', '1050', NULL, 'isciples and others. His doctrines were original, bold, pure, and authoritative. His miracles had been extraordinary, clear, and awful. His life and death had been peculiar; and it is not improbable - indeed it is highly probable that such broken accounts and narratives of detached facts would be preserved. That this is what Luke means appears farther from Luke 1:3, where "he" professes to give a regular, full, and systematic account from the very beginning - "having had perfect understanding of "all things from the very first." The records of the others - the "many" - were broken and incomplete. His were to be regular and full.Taken in hand - Undertaken, attempted.To set forth in order - To compose a narrative. It does not refer to the "order" or "arrangement," but means simply to give a ', NULL, NULL, '''1'':59 ''3'':60 ''account'':40,71 ''appear'':55 ''arrang'':125 ''attempted.to'':108 ''authorit'':11 ''aw'':19 ''begin'':75 ''bold'':8 ''broken'':39,95 ''clear'':17 ''compos'':114 ''death'':23 ''detach'':44 ''doctrin'':5 ''extraordinari'':16 ''fact'':45 ''farther'':56 ''first'':86 ''forth'':110 ''full'':68 ''full.taken'':104 ''give'':65,130 ''hand'':106 ''high'':35 ''improb'':31 ''incomplet'':97 ''inde'':32 ''iscipl'':1 ''life'':21 ''luke'':53,58 ''mani'':93 ''mean'':54,127 ''miracl'':13 ''narrat'':42,116 ''order'':112,123 ''origin'':7 ''other'':3,91 ''peculiar'':26 ''perfect'':78 ''preserv'':48 ''probabl'':36 ''profess'':63 ''pure'':9 ''record'':88 ''refer'':120 ''regular'':67,102 ''set'':109 ''simpli'':128 ''systemat'':70 ''thing'':82 ''understand'':79 ''undertaken'':107 ''would'':46', NULL, '974');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1051', '2', '1051', NULL, 'narrative. The word rendered here "in order" is different from that in the third verse, which "has" reference "to order," or to a full and fair "arrangement" of the principal facts, etc., in the history of our Lord.A declaration - A narrative - an account of.Which are most surely believed among us - Among Christians - among all the Christians then living. Here we may remark:1. That Christians of that day had the best of all opportunities for knowing whether those things were true. Many had seen them, and all others had had the account from those who had witnessed them.2. That infidels now cannot "possibly" be as good judges in the matter as those who lived at the time, and who were thus competent to determine whether these things were true or false.3. That all Christians do "most surely be', NULL, NULL, '''1'':63 ''account'':43,92 ''among'':49,51,53 ''arrang'':27 ''believ'':48 ''best'':71 ''cannot'':102 ''christian'':52,56,65,134 ''compet'':122 ''day'':68 ''declar'':39 ''determin'':124 ''differ'':9 ''etc'':32 ''fact'':31 ''fair'':26 ''false.3'':131 ''full'':24 ''good'':106 ''histori'':35 ''infidel'':100 ''judg'':107 ''know'':76 ''live'':58,114 ''lord.a'':38 ''mani'':82 ''matter'':110 ''may'':61 ''narrat'':1,41 ''of.which'':44 ''opportun'':74 ''order'':7,20 ''other'':88 ''possibl'':103 ''princip'':30 ''refer'':18 ''remark'':62 ''render'':4 ''seen'':84 ''sure'':47,137 ''them.2'':98 ''thing'':79,127 ''third'':14 ''thus'':121 ''time'':117 ''true'':81,129 ''us'':50 ''vers'':15 ''whether'':77,125 ''wit'':97 ''word'':3', NULL, '974');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1052', '2', '1052', NULL, 'lieve" the truth of the gospel. It is their life, their hope, their all. Nor can they doubt that their Saviour lived, bled, died, rose, and still lives; that he was their atoning sacrifice, and that he is God over all, blessed forever.', NULL, NULL, '''aton'':33 ''bled'':23 ''bless'':42 ''die'':24 ''doubt'':18 ''forev'':43 ''god'':39 ''gospel'':6 ''hope'':12 ''liev'':1 ''life'':10 ''live'':22,28 ''rose'':25 ''sacrific'':34 ''saviour'':21 ''still'':27 ''truth'':3', NULL, '974');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1069', '2', '1069', NULL, 'In the mean time - While he was discoursing with the scribes and Pharisees, as recorded in the last chapter.An innumerable multitude - The original word is "myriad''s," or ten thousands. It is used here to signify that there was a great crowd or collection of people, who were anxious to hear him. Multitudes were attracted to the Saviour''s ministry, and it is worthy of remark that he never had more to hear him than when he was most faithful and severe in his reproofs of sinners. Men''s consciences are on the side of the faithful reprover of their sins; and though they deeply feel the reproof, yet they will still respect and hear him that reproves.To his disciples first of all - This does not mean that his disciples were, before all others, to avoid hypocrisy, but that this was the "first" or chief thing of which they were to beware. The meaning is this: "He said to his disciples, "Above all things beware," etc.The leaven - See the notes at Matthew 16:6.Which is hypocrisy - See the notes at Matthew 7:5. Hypocrisy is like leaven or yeast, because:1. It may exist without being immediately detected. Leaven mixed in flour is not known until it produces its effects.2. It is insinuating. Leaven will soon pervade the whole mass. So hypocrisy will, if undetected and unremoved, soon pervade all our exercises and feelings.3. It is swelling. It puffs us up, and fills us with pride and vanity. No man is more proud than the hypocrite, and none is more odious to God. When Jesus cautions them to beware of "the leaven of the Pharisees," he means that they should be cautious about imbibing their spirit and becoming like them. The religion of Jesus is one of sincerity, of humility, of an entire want of disguise. The humblest man is the best Christian, and he who has the least disguise is most like his Master.', NULL, NULL, 