INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1064', '2', '1064', NULL, 'They besought him instantly - Urgently or earnestly.He was worthy - The centurion. He had showed favor to the Jews, and it was not improper to show him a kindness.', NULL, NULL, '''besought'':2 ''centurion'':11 ''earnestly.he'':7 ''favor'':15 ''improp'':23 ''instant'':4 ''jew'':18 ''kind'':28 ''show'':14,25 ''urgent'':5 ''worthi'':9', NULL, '980');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1065', '2', '1065', NULL, 'Every city and village - Of Galilee.Preaching an showing the glad tidings of the kingdom of God - That the kingdom of God was about to come, or that his reign in the gospel was about to be set up over people. See the notes at Matthew 3:2.The twelve - The twelve apostles.', NULL, NULL, '''2.the'':47 ''3'':46 ''apostl'':51 ''citi'':2 ''come'':25 ''everi'':1 ''galilee.preaching'':6 ''glad'':10 ''god'':16,21 ''gospel'':32 ''kingdom'':14,19 ''matthew'':45 ''note'':43 ''peopl'':40 ''reign'':29 ''see'':41 ''set'':37 ''show'':8 ''tide'':11 ''twelv'':48,50 ''villag'':4', NULL, '981');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1066', '2', '1066', NULL, 'See the Matthew 14:13-21 notes, and Mark 6:30-44 notes.Luke 9:10Bethsaida - A city on the east bank of the river Jordan, near where the river enters into the Sea of Tiberias. In the neighborhood of that city were extensive wastes or deserts.', NULL, NULL, '''-21'':6 ''-44'':12 ''10bethsaida'':15 ''13'':5 ''14'':4 ''30'':11 ''6'':10 ''9'':14 ''bank'':21 ''citi'':17,41 ''desert'':46 ''east'':20 ''enter'':30 ''extens'':43 ''jordan'':25 ''mark'':9 ''matthew'':3 ''near'':26 ''neighborhood'':38 ''note'':7 ''notes.luke'':13 ''river'':24,29 ''sea'':33 ''see'':1 ''tiberia'':35 ''wast'':44', NULL, '982');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1067', '2', '1067', NULL, 'After these things - After the appointment of the twelve apostles, and the transactions recorded in the previous chapters.Other seventy - Seventy others besides the apostles. They were appointed for a different purpose from the apostles. The apostles were to be with him; to hear his instructions; to be witnesses of his miracles, his sufferings, his death, his resurrection and ascension, that they might "then" go and proclaim all these things to the world. The seventy were sent out to preach immediately, and chiefly where he himself was about to come. They were appointed for a temporary object. They were to go into the villages and towns, and prepare the way for his coming. The number "seventy" was a favorite number among the Jews. Thus, the family of Jacob that came into Egypt consisted of seventy, Genesis 46:27. The number of elders that Moses appointed to aid him was the same, Numbers 11:16, Numbers 11:25. The number which composed the great Sanhedrin, or council of the nation. was the same. It is not improbable that our Saviour appointed this number with reference to the fact that it so often occurred among the Jews, or after the example of Moses, who appointed seventy to aid him in his work; but it is evident that the office was "temporary" - that it had a specific design - and of course that it would be improper to attempt to find now a "continuation" of it, or a parallel to it, in the Christian ministry.Two and two - There was much wisdom in sending them in this manner. It was done, doubtless, that they might aid one another by mutual counsel, and that they might sustain and comfort one another in their persecutions and trials. Our Lord in this showed the propriety of having "a religious friend," who would be a confidant and help. Every Christian, and especially every Christian minister, needs such a friend, and should seek some one to whom he can unbosom himself, and with whom he can mingle his feelings and prayers.', NULL, NULL, '''11'':152,155 ''16'':153 ''25'':156 ''27'':137 ''46'':136 ''aid'':146,205,270 ''among'':120,192 ''anoth'':272,284 ''apostl'':10,24,34,36 ''appoint'':6,27,92,144,179,202 ''ascens'':59 ''attempt'':234 ''besid'':22 ''came'':129 ''chapters.other'':18 ''chiefli'':82 ''christian'':249,310,314 ''come'':89,112 ''comfort'':282 ''compos'':160 ''confid'':306 ''consist'':132 ''continu'':239 ''council'':165 ''counsel'':275 ''cours'':227 ''death'':55 ''design'':224 ''differ'':30 ''done'':265 ''doubtless'':266 ''egypt'':131 ''elder'':141 ''especi'':312 ''everi'':309,313 ''evid'':213 ''exampl'':198 ''fact'':186 ''famili'':125 ''favorit'':118 ''feel'':338 ''find'':236 ''friend'':301,319 ''genesi'':135 ''go'':64,100 ''great'':162 ''hear'':43 ''help'':308 ''immedi'':80 ''improb'':175 ''improp'':232 ''instruct'':45 ''jacob'':127 ''jew'':122,194 ''lord'':291 ''manner'':262 ''might'':62,269,279 ''mingl'':336 ''minist'':315 ''ministry.two'':250 ''miracl'':51 ''mose'':143,200 ''much'':255 ''mutual'':274 ''nation'':168 ''need'':316 ''number'':114,119,139,151,154,158,181 ''object'':96 ''occur'':191 ''offic'':216 ''often'':190 ''one'':271,283,324 ''other'':21 ''parallel'':244 ''persecut'':287 ''prayer'':340 ''preach'':79 ''prepar'':107 ''previous'':17 ''proclaim'':66 ''proprieti'':296 ''purpos'':31 ''record'':14 ''refer'':183 ''religi'':300 ''resurrect'':57 ''sanhedrin'':163 ''saviour'':178 ''seek'':322 ''send'':258 ''sent'':76 ''seventi'':19,20,74,115,134,203 ''show'':294 ''specif'':223 ''suffer'':53 ''sustain'':280 ''temporari'':95,218 ''thing'':3,69 ''thus'':123 ''town'':105 ''transact'':13 ''trial'':289 ''twelv'':9 ''two'':252 ''unbosom'':329 ''villag'':103 ''way'':109 ''wisdom'':256 ''wit'':48 ''work'':209 ''world'':72 ''would'':230,303', NULL, '983');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1068', '2', '1068', NULL, 'As he was praying - Luke has taken notice of our Saviour''s praying often. Thus, at his baptism Luke 3:21; in the wilderness Luke 5:16; before the appointment of the apostles, he continued all night in prayer Luke 6:12; he was alone praying Luke 9:18; his transfiguration also took place when he went up to pray Luke 9:28-29.Teach us to pray - Probably they had been struck with the excellency and fervor of his prayers, and, recollecting that "John" had taught his disciples to pray, they asked him also to teach "them." We learn, therefore:1. That the gifts and graces of others should lead us to desire the same.2. That the true method of praying can be learned only by our being properly taught. Indeed, we cannot pray acceptably at all unless God shall teach us how to pray.3. That it is proper for us to meditate beforehand what we are to ask of God, and to arrange our thoughts, that we may not come thoughtlessly into his presence.', NULL, NULL, '''1'':100 ''12'':42 ''16'':27 ''18'':49 ''21'':21 ''28-29.teach'':63 ''3'':20 ''5'':26 ''6'':41 ''9'':48,62 ''accept'':134 ''alon'':45 ''also'':52,93 ''apostl'':33 ''appoint'':30 ''arrang'':163 ''ask'':91,158 ''baptism'':18 ''beforehand'':153 ''cannot'':132 ''come'':170 ''continu'':35 ''desir'':112 ''discipl'':87 ''excel'':74 ''fervor'':76 ''gift'':103 ''god'':138,160 ''grace'':105 ''inde'':130 ''john'':83 ''lead'':109 ''learn'':98,123 ''luke'':5,19,25,40,47,61 ''may'':168 ''medit'':152 ''method'':118 ''night'':37 ''notic'':8 ''often'':14 ''other'':107 ''place'':54 ''pray'':4,13,46,60,66,89,120,133 ''pray.3'':144 ''prayer'':39,79 ''presenc'':174 ''probabl'':67 ''proper'':128,148 ''recollect'':81 ''same.2'':114 ''saviour'':11 ''shall'':139 ''struck'':71 ''taken'':7 ''taught'':85,129 ''teach'':95,140 ''therefor'':99 ''thought'':165 ''thoughtless'':171 ''thus'':15 ''took'':53 ''transfigur'':51 ''true'':117 ''unless'':137 ''us'':64,110,141,150 ''went'':57 ''wilder'':24', NULL, '984');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1121', '2', '1121', NULL, 'Leaning on Jesus'' bosom - This does not mean that he was at that time actually lying on his bosom, but that he occupied a situation next to him at the table, so that his head naturally fell back on his bosom when he spoke to him. See the notes at Matthew 23:6.Whom Jesus loved - This was doubtless John himself. The evangelists are not accustomed to mention their own names when any mark of favor or any good deed is recorded. They did not seek publicity or notoriety. In this case the appellation is more tender and honorable than any mere name. John was admitted to special friendship, perhaps, because the natural disposition of our Saviour was more nearly like the amiableness and mildness of John than any of the other disciples (Robert Hall). The highest honor that can be conferred on any man is to say that Jesus loved him. Yet this is an honor which all may possess, but which none can inherit without his spirit and without loving him. It is an honor which cannot be won by wealth or learning, by beauty or accomplishments, by rank or earthly honors, but only by the possession of a meek and quiet spirit, which is in the sight of God of great price, 1 Peter 3:4; compare Romans 8:9.', NULL, NULL, '''1'':215 ''23'':52 ''3'':217 ''4'':218 ''6.whom'':53 ''8'':221 ''9'':222 ''accomplish'':188 ''accustom'':65 ''actual'':15 ''admit'':105 ''amiabl'':122 ''appel'':93 ''back'':38 ''beauti'':186 ''bosom'':4,19,41 ''cannot'':178 ''case'':91 ''compar'':219 ''confer'':141 ''deed'':79 ''discipl'':132 ''disposit'':113 ''doubtless'':58 ''earth'':192 ''evangelist'':62 ''favor'':75 ''fell'':37 ''friendship'':108 ''god'':211 ''good'':78 ''great'':213 ''hall'':134 ''head'':35 ''highest'':136 ''honor'':98,137,156,176,193 ''inherit'':165 ''jesus'':3,54,149 ''john'':59,103,126 ''lean'':1 ''learn'':184 ''lie'':16 ''like'':120 ''love'':55,150,171 ''man'':144 ''mark'':73 ''matthew'':51 ''may'':159 ''mean'':8 ''meek'':201 ''mention'':67 ''mere'':101 ''mild'':124 ''name'':70,102 ''natur'':36,112 ''near'':119 ''next'':26 ''none'':163 ''note'':49 ''notorieti'':88 ''occupi'':23 ''perhap'':109 ''peter'':216 ''possess'':160,198 ''price'':214 ''public'':86 ''quiet'':203 ''rank'':190 ''record'':81 ''robert'':133 ''roman'':220 ''saviour'':116 ''say'':147 ''see'':47 ''seek'':85 ''sight'':209 ''situat'':25 ''special'':107 ''spirit'':168,204 ''spoke'':44 ''tabl'':31 ''tender'':96 ''time'':14 ''wealth'':182 ''without'':166,170 ''won'':180 ''yet'':152', NULL, '1010');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1070', '2', '1070', NULL, 'There were present - That is, some persons who were present, and who had heard his discourse recorded in the previous chapter. There was probably a pause in his discourse, when they mentioned what had been done by Pilate to the Galileans.At that season - At that time - that is the time mentioned in the last chapter. At what period of our Lord''s ministry this was, it is not easy to determine.Some that told him - This was doubtless an event of recent occurrence. Jesus, it is probable, had not before heard of it. Why they told him of it can only be a matter of conjecture. It might be from the desire to get him to express an opinion respecting the conduct of Pilate, and thus to involve him in difficulty with the reigning powers of Judea. It might be as a mere matter of news. But, from the answer of Jesus, it would appear that "they" supposed that the Galileans "deserved" it, and that they meant to pass a judgment on the character of those people, a thing of which they were exceedingly fond. The answer of Jesus is a reproof of their habit of hastily judging the character of others.Galileans - People who lived in Galilee. See the notes at Matthew 2:22. They were not under the jurisdiction of Pilate, but of Herod. The Galileans, in the time of Christ, were very wicked.Whose blood Pilate had mingled ... - That is, while they were sacrificing at Jerusalem, Pilate came suddenly upon them and killed them, and "their" blood was mingled with the blood of the animals that they were slaying for sacrifice. It does not mean that Pilate "offered" their blood in sacrifice, but only that as they were sacrificing he killed them. The fact is not mentioned by Josephus, and nothing more is known of it than what is here recorded. We learn, however, from Josephus that the Galileans were very wicked, and that they were much disposed to broils and seditions. It appears, also, that Pilate and Herod had a quarrel with each other Luke 23:12, and it is not improbable that Pilate might feel a particular enmity to the subjects of Herod. It is likely that the Galileans excited a tumult in the temple, and that Pilate took occasion to come suddenly upon them, and show his opposition to them and Herod by slaying them. "Pilate." The Roman governor of Judea. See the notes at Matthew 27:2.', NULL, NULL, '''12'':348 ''2'':212,411 ''22'':213 ''23'':347 ''27'':410 ''also'':335 ''anim'':265 ''answer'':149,186 ''appear'':154,334 ''blood'':235,257,262,280 ''broil'':330 ''came'':248 ''chapter'':21,55 ''charact'':173,199 ''christ'':231 ''come'':384 ''conduct'':121 ''conjectur'':105 ''deserv'':161 ''desir'':111 ''determine.some'':71 ''difficulti'':130 ''discours'':16,29 ''dispos'':328 ''done'':36 ''doubtless'':77 ''easi'':69 ''enmiti'':360 ''event'':79 ''exceed'':183 ''excit'':372 ''express'':116 ''fact'':294 ''feel'':357 ''fond'':184 ''galile'':206 ''galilean'':160,226,319,371 ''galileans.at'':41 ''get'':113 ''governor'':402 ''habit'':194 ''hastili'':196 ''heard'':14,90 ''herod'':224,339,365,395 ''howev'':314 ''improb'':353 ''involv'':127 ''jerusalem'':246 ''jesus'':83,151,188 ''josephus'':299,316 ''judea'':136,404 ''judg'':197 ''judgment'':170 ''jurisdict'':219 ''kill'':253,291 ''known'':304 ''last'':54 ''learn'':313 ''like'':368 ''live'':204 ''lord'':61 ''luke'':346 ''matter'':103,143 ''matthew'':211,409 ''mean'':275 ''meant'':166 ''mention'':32,51,297 ''mere'':142 ''might'':107,138,356 ''mingl'':238,259 ''ministri'':63 ''much'':327 ''news'':145 ''note'':209,407 ''noth'':301 ''occas'':382 ''occurr'':82 ''offer'':278 ''opinion'':118 ''opposit'':391 ''others.galileans'':201 ''particular'':359 ''pass'':168 ''paus'':26 ''peopl'':176,202 ''period'':58 ''person'':7 ''pilat'':38,123,221,236,247,277,337,355,380,399 ''power'':134 ''present'':3,10 ''previous'':20 ''probabl'':24,86 ''quarrel'':342 ''recent'':81 ''record'':17,311 ''reign'':133 ''reproof'':191 ''respect'':119 ''roman'':401 ''sacrif'':244,289 ''sacrific'':271,282 ''season'':43 ''sedit'':332 ''see'':207,405 ''show'':389 ''slay'':269,397 ''subject'':363 ''sudden'':249,385 ''suppos'':157 ''templ'':377 ''thing'':178 ''thus'':125 ''time'':46,50,229 ''told'':73,95 ''took'':381 ''tumult'':374 ''upon'':250,386 ''wick'':322 ''wicked.whose'':234 ''would'':153', NULL, '986');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1071', '2', '1071', NULL, 'It came to pass - It so happened or occurred.As he went ... - It is probable that he was invited to go, being in the neighborhood Luke 14:12; and it is also probable that the Pharisee invited him for the purpose of getting him to say something that would involve him in difficulty.One of the chief Pharisees - One of the Pharisees who were "rulers," or members of the great council or the Sanhedrin. See the notes at Matthew 5:22. It does not mean that he was the head of the "sect" of the Pharisees, but one of those who happened to be a member of the Sanhedrin. He was, therefore, a man of influence and reputation.To eat bread - To dine. To partake of the hospitalities of his house.On the sabbath-day - It may seem strange that our Saviour should have gone to dine with a man who was a stranger on the Sabbath; but we are to remember:1. That he was traveling, having no home of his own, and that it was no more improper to go there than to any other place.2. That he did not go there for the purpose of feasting and amusement, but to do good.3. That as several of that class of persons were together, it gave him an opportunity to address them on the subject of religion, and to reprove their vices.If, therefore, the example of Jesus should be pled to authorize accepting an invitation to dine on the Sabbath, it should be pled just as it was. If we can go "just as he did," it is right. If when away from home; if we go to do good; if we make it an occasion to discourse on the subject of religion and to persuade people to repent, then it is not improper. Farther than this we cannot plead the example of Christ. And surely this should be the last instance in the world to be adduced to justify dinner-parties, and scenes of riot and gluttony on the Sabbath.They watched him - They malignantly fixed their eyes on him, to see if he did anything on which they could lay hold to accuse him.', NULL, NULL, '''1'':160 ''12'':27 ''14'':26 ''22'':79 ''5'':78 ''accept'':241 ''accus'':363 ''address'':219 ''adduc'':326 ''also'':31 ''amus'':198 ''anyth'':355 ''author'':240 ''away'':270 ''bread'':118 ''came'':2 ''cannot'':307 ''chief'':55 ''christ'':312 ''class'':208 ''could'':359 ''council'':69 ''day'':132 ''difficulty.one'':52 ''dine'':120,144,245 ''dinner'':330 ''dinner-parti'':329 ''discours'':286 ''eat'':117 ''exampl'':233,310 ''eye'':347 ''farther'':303 ''feast'':196 ''fix'':345 ''gave'':214 ''get'':42 ''gluttoni'':337 ''go'':20,179,190,260,275 ''gone'':142 ''good'':278 ''good.3'':202 ''great'':68 ''happen'':7,100 ''head'':88 ''hold'':361 ''home'':167,272 ''hospit'':125 ''house.on'':128 ''improp'':177,302 ''influenc'':114 ''instanc'':320 ''invit'':18,36,243 ''involv'':49 ''jesus'':235 ''justifi'':328 ''last'':319 ''lay'':360 ''luke'':25 ''make'':281 ''malign'':344 ''man'':112,147 ''matthew'':77 ''may'':134 ''mean'':83 ''member'':65,104 ''neighborhood'':24 ''note'':75 ''occas'':284 ''occurred.as'':9 ''one'':57,96 ''opportun'':217 ''partak'':122 ''parti'':331 ''pass'':4 ''peopl'':295 ''person'':210 ''persuad'':294 ''pharise'':35,56,60,94 ''place.2'':185 ''plead'':308 ''pled'':238,252 ''probabl'':14,32 ''purpos'':40,194 ''religion'':225,291 ''rememb'':159 ''repent'':297 ''reprov'':228 ''reputation.to'':116 ''right'':267 ''riot'':335 ''ruler'':63 ''sabbath'':131,154,248 ''sabbath-day'':130 ''sabbath.they'':340 ''sanhedrin'':72,107 ''saviour'':139 ''say'':45 ''scene'':333 ''sect'':91 ''see'':73,351 ''seem'':135 ''sever'':205 ''someth'':46 ''strang'':136 ''stranger'':151 ''subject'':223,289 ''sure'':314 ''therefor'':110,231 ''togeth'':212 ''travel'':164 ''vices.if'':230 ''watch'':341 ''went'':11 ''world'':323 ''would'':48', NULL, '987');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1072', '2', '1072', NULL, 'Murmured - They affected to suppose that if Jesus treated sinners kindly he must be fond of their society, and be a man of similar character. "They" considered it disgraceful to be with them or to eat with them, and they, therefore, brought a charge against him for it. They "would" not suppose that he admitted them to his society for the purpose of doing them good; nor did they remember that the very object of his coming was to call the wicked from their ways and to save them from death.Receiveth sinners - Receives them in a tender manner; treats them with kindness; does not drive them from his presence.And eateth with them - Contrary to the received maxims of the scribes. By eating with them he showed that he did not despise or overlook them.', NULL, NULL, '''admit'':55 ''affect'':3 ''brought'':42 ''call'':80 ''charact'':25 ''charg'':44 ''come'':77 ''consid'':27 ''contrari'':113 ''death.receiveth'':91 ''despis'':131 ''disgrac'':29 ''drive'':105 ''eat'':36,122 ''eateth'':110 ''fond'':15 ''good'':66 ''jesus'':8 ''kind'':11,102 ''man'':22 ''manner'':98 ''maxim'':117 ''murmur'':1 ''must'':13 ''object'':74 ''overlook'':133 ''presence.and'':109 ''purpos'':62 ''receiv'':93,116 ''rememb'':70 ''save'':88 ''scribe'':120 ''show'':126 ''similar'':24 ''sinner'':10,92 ''societi'':18,59 ''suppos'':5,52 ''tender'':97 ''therefor'':41 ''treat'':9,99 ''way'':85 ''wick'':82 ''would'':50', NULL, '988');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1074', '2', '1074', NULL, 'It is impossible - It cannot but happen. Such is the state of things that "it will be." See these verses explained in the notes at Matthew 18:6-7.', NULL, NULL, '''-7'':29 ''18'':27 ''6'':28 ''cannot'':5 ''explain'':21 ''happen'':7 ''imposs'':3 ''matthew'':26 ''note'':24 ''see'':18 ''state'':11 ''thing'':13 ''vers'':20', NULL, '990');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1075', '2', '1075', NULL, 'A parable - See the notes at Matthew 13:3.To this end - To show this.Always - At all times. That is, we must not neglect regular stated seasons of prayer; we must seize on occasions of remarkable providences as afflictions or signal blessings to seek God in prayer; we must "always" maintain a spirit of prayer, or be in a proper frame to lift up our hearts to God for his blessing, and we must not grow weary though our prayer seems not to be answered.Not to faint - Not to grow weary or give over. The parable is designed to teach us that, though our prayers should long appear to be unanswered, we should persevere, and not grow weary in supplication to God.', NULL, NULL, '''13'':8 ''3.to'':9 ''afflict'':38 ''alway'':49 ''answered.not'':84 ''appear'':107 ''bless'':41,70 ''design'':97 ''end'':11 ''faint'':86 ''frame'':60 ''give'':92 ''god'':44,67,121 ''grow'':75,89,116 ''heart'':65 ''lift'':62 ''long'':106 ''maintain'':50 ''matthew'':7 ''must'':21,30,48,73 ''neglect'':23 ''note'':5 ''occas'':33 ''parabl'':2,95 ''persever'':113 ''prayer'':28,46,54,79,104 ''proper'':59 ''provid'':36 ''regular'':24 ''remark'':35 ''season'':26 ''see'':3 ''seek'':43 ''seem'':80 ''seiz'':31 ''show'':13 ''signal'':40 ''spirit'':52 ''state'':25 ''supplic'':119 ''teach'':99 ''this.always'':14 ''though'':77,102 ''time'':17 ''unansw'':110 ''us'':100 ''weari'':76,90,117', NULL, '991');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1076', '2', '1076', NULL, 'And Jesus entered ... - See the notes at Matthew 20:29. This means, perhaps, "he was passing" through Jericho when Zacchaeus saw him. His house was "in" Jericho.', NULL, NULL, '''20'':9 ''29'':10 ''enter'':3 ''hous'':24 ''jericho'':18,27 ''jesus'':2 ''matthew'':8 ''mean'':12 ''note'':6 ''pass'':16 ''perhap'':13 ''saw'':21 ''see'':4 ''zacchaeus'':20', NULL, '992');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1077', '2', '1077', NULL, 'Notes on the Bible by Albert Barnes [1834].
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1078', '2', '1078', NULL, 'Goodly stones - Beautiful stones. Either referring to the large, square, and well-finished stones of which the eastern wall was built, or to the precious stones which might have been used in decorating the temple itself. See the notes at Mark 13:1.Gifts - This word properly denotes anything devoted or dedicated to God. Anciently warriors dedicated to their gods the spoils of war - the shields, and helmets, and armor, and garments of those slain in battle. These were suspended in the temples. It would seem that something of this kind had occurred in the temple of Jerusalem, and that the people, to express their gratitude to God, had suspended on the pillars and perches of the temple gifts and offerings. Josephus mentions particularly a golden "vine" with which Herod the Great had adorned the columns of the temple ("Antiq." xiii. 8). See also 2 Macc. 5:16; 9:16.', NULL, NULL, '''1.gifts'':44 ''13'':43 ''16'':148,150 ''2'':145 ''5'':147 ''8'':142 ''9'':149 ''adorn'':134 ''also'':144 ''ancient'':55 ''antiq'':140 ''anyth'':49 ''armor'':70 ''battl'':77 ''beauti'':3 ''built'':22 ''column'':136 ''decor'':34 ''dedic'':52,57 ''denot'':48 ''devot'':50 ''eastern'':19 ''either'':5 ''express'':104 ''finish'':14 ''garment'':72 ''gift'':119 ''god'':54,60,108 ''golden'':126 ''good'':1 ''gratitud'':106 ''great'':132 ''helmet'':68 ''herod'':130 ''jerusalem'':98 ''josephus'':122 ''kind'':91 ''larg'':9 ''macc'':146 ''mark'':42 ''mention'':123 ''might'':29 ''note'':40 ''occur'':93 ''offer'':121 ''particular'':124 ''peopl'':102 ''perch'':115 ''pillar'':113 ''precious'':26 ''proper'':47 ''refer'':6 ''see'':38,143 ''seem'':86 ''shield'':66 ''slain'':75 ''someth'':88 ''spoil'':62 ''squar'':10 ''stone'':2,4,15,27 ''suspend'':80,110 ''templ'':36,83,96,118,139 ''use'':32 ''vine'':127 ''wall'':20 ''war'':64 ''warrior'':56 ''well'':13 ''well-finish'':12 ''word'':46 ''would'':85 ''xiii'':141', NULL, '994');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1079', '2', '1079', NULL, 'Simon - Peter. Jesus, foreseeing the danger of Peter, and knowing that he was about to deny him, took occasion to forewarn him and put him on his guard, and also to furnish him with a solace when he should be brought to repentance.Satan hath desired - Satan is the prince of evil. One of his works is to try the faith of believers to place temptations and trials in their way, that they may be tested. Thus God gave Job into his hands, that it might be seen whether he would be found faithful, or would apostatize. See the notes at Job 1:7-12. So Satan desired to have Peter in his hands, that he might also try him.May sift you as wheat - Grain was agitated or shaken in a kind of fan or sieve. The grain remained in the fan, and the chaff and dust were thrown off. So Christ says that Satan desired to try Peter; to place trials and temptations before him; "to agitate him" to see whether anything of faith would remain, or whether all would not be found to be chaff - mere natural ordor and false professions.', NULL, NULL, '''-12'':104 ''1'':102 ''7'':103 ''agit'':126,167 ''also'':30,117 ''anyth'':172 ''apostat'':96 ''believ'':62 ''brought'':41 ''chaff'':144,186 ''christ'':151 ''danger'':6 ''deni'':16 ''desir'':45,107,155 ''dust'':146 ''evil'':51 ''faith'':60,93,174 ''fals'':191 ''fan'':133,141 ''forese'':4 ''forewarn'':21 ''found'':92,183 ''furnish'':32 ''gave'':78 ''god'':77 ''grain'':124,137 ''guard'':28 ''hand'':82,113 ''hath'':44 ''him.may'':119 ''jesus'':3 ''job'':79,101 ''kind'':131 ''know'':10 ''may'':73 ''mere'':187 ''might'':85,116 ''natur'':188 ''note'':99 ''occas'':19 ''one'':52 ''ordor'':189 ''peter'':2,8,110,158 ''place'':64,160 ''princ'':49 ''profess'':192 ''put'':24 ''remain'':138,176 ''repentance.satan'':43 ''satan'':46,106,154 ''say'':152 ''see'':97,170 ''seen'':87 ''shaken'':128 ''siev'':135 ''sift'':120 ''simon'':1 ''solac'':36 ''temptat'':65,163 ''test'':75 ''thrown'':148 ''thus'':76 ''took'':18 ''tri'':58,118,157 ''trial'':67,161 ''way'':70 ''wheat'':123 ''whether'':88,171,178 ''work'':55 ''would'':90,95,175,180', NULL, '995');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1080', '2', '1080', NULL, 'This fellow - The word "fellow" is not in the original. It conveys a notion of "contempt," which no doubt they "felt," but which is not expressed in the "Greek," and which it is not proper should be expressed in the translation. It might be translated, "We found this man."Perverting the nation - That is, exciting them to sedition and tumults. This was a mere wanton accusation, but it was plausible before a Roman magistrate; for,1. The Galileans, as Josephus testifies, were prone to seditions and tumults.2. Jesus drew multitudes after him, and they thought it was easy to show that this was itself promoting tumults and seditions.Forbidding ... - About their charges they were very cautious and cunning. They did not say that he "taught" that people should not give tribute - that would have been too gross a charge, and would have been easily refuted; but it was an "inference" which they drew. They said it "followed" from his doctrine. He professed to be a king. They "inferred," therefore, if "he" was "a king," that he must hold that it was not right to acknowledge allegiance to any foreign prince; and if they could make "this" out, they supposed that Pilate "must" condemn him of course.Tribute - Taxes.Caesar - The Roman emperor, called also Tiberius. The name "Caesar" was common to the Roman emperors, as "Pharaoh" was to the Egyptian kings. "All" the kings of Egypt were called Pharaoh, or "the" Pharaoh; so all the Roman emperors were called "Caesar."', NULL, NULL, '''1'':76 ''accus'':66 ''acknowledg'':184 ''allegi'':185 ''also'':211 ''caesar'':215,247 ''call'':210,235,246 ''cautious'':115 ''charg'':111,138 ''common'':217 ''condemn'':202 ''contempt'':16 ''convey'':12 ''could'':193 ''course.tribute'':205 ''cun'':117 ''doctrin'':159 ''doubt'':19 ''drew'':89,152 ''easi'':98 ''easili'':143 ''egypt'':233 ''egyptian'':227 ''emperor'':209,221,244 ''excit'':55 ''express'':26,38 ''fellow'':2,5 ''felt'':21 ''follow'':156 ''foreign'':188 ''found'':47 ''galilean'':78 ''give'':129 ''greek'':29 ''gross'':136 ''hold'':177 ''infer'':149,167 ''jesus'':88 ''josephus'':80 ''king'':165,173,228,231 ''magistr'':74 ''make'':194 ''man'':49 ''mere'':64 ''might'':43 ''multitud'':90 ''must'':176,201 ''name'':214 ''nation'':52 ''notion'':14 ''origin'':10 ''peopl'':126 ''pervert'':50 ''pharaoh'':223,236,239 ''pilat'':200 ''plausibl'':70 ''princ'':189 ''profess'':161 ''promot'':105 ''prone'':83 ''proper'':35 ''refut'':144 ''right'':182 ''roman'':73,208,220,243 ''said'':154 ''say'':121 ''sedit'':58,85 ''seditions.forbidding'':108 ''show'':100 ''suppos'':198 ''taught'':124 ''taxes.caesar'':206 ''testifi'':81 ''therefor'':168 ''thought'':95 ''tiberius'':212 ''translat'':41,45 ''tribut'':130 ''tumult'':60,106 ''tumults.2'':87 ''wanton'':65 ''word'':4 ''would'':132,140', NULL, '996');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1082', '2', '1082', NULL, 'In the beginning - This expression is used also in Genesis 1:1. John evidently has allusion here to that place, and he means to apply to "the Word" an expression which is there applied "to God." In both places it clearly means before creation, before the world was made, when as yet there was nothing. The meaning is: that the "Word" had an existence before the world was created. This is not spoken of the man Jesus, but of that which "became" a man, or was incarnate, John 1:14. The Hebrews, by expressions like this, commonly denoted eternity. Thus. the eternity of God is described Psalm 90:2; "Before the mountains were brought forth, etc.;" and eternity is commonly expressed by the phrase, before the foundation of the world." Whatever is meant by the term "Word," it is clear that it had an e', NULL, NULL, '''1'':11,12,89 ''14'':90 ''2'':109 ''90'':108 ''allus'':16 ''also'':8 ''appli'':25,34 ''becam'':82 ''begin'':3 ''brought'':114 ''clear'':41,140 ''common'':97,120 ''creat'':69 ''creation'':44 ''denot'':98 ''describ'':106 ''e'':145 ''etc'':116 ''etern'':99,102,118 ''evid'':14 ''exist'':64 ''express'':5,30,94,121 ''forth'':115 ''foundat'':127 ''genesi'':10 ''god'':36,104 ''hebrew'':92 ''incarn'':87 ''jesus'':77 ''john'':13,88 ''like'':95 ''made'':49 ''man'':76,84 ''mean'':23,42,57 ''meant'':133 ''mountain'':112 ''noth'':55 ''phrase'':124 ''place'':20,39 ''psalm'':107 ''spoken'':73 ''term'':136 ''thus'':100 ''use'':7 ''whatev'':131 ''word'':28,61,137 ''world'':47,67,130 ''yet'':52', NULL, '998');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1083', '2', '1083', NULL, 'xistence before "creation." It is not, then, a "creature" or created being, and must be, therefore, uncreated and eternal. There is only one Being that is uncreated, and Jesus must be therefore divine. Compare the Saviour''s own declarations respecting himself in the following places: John 8:58; John 17:5; John 6:62; John 3:13; John 6:46; John 8:14; John 16:28.Was the Word - Greek, "was the &#x3bb;&#x3bf;&#x3b3;&#x3bf;&#x3c2;  Logos." This name is given to him who afterward became "flesh," or was incarnate (John 1:14 - that is, to the Messiah. Whatever is meant by it, therefore, is applicable to the Lord Jesus Christ. There have been many opinions about the reason why this name was given to the Son of God. It is unnecessary to repeat those opinions. The opinion which seems most plausible ma', NULL, NULL, '''1'':87 ''13'':57 ''14'':63,88 ''16'':65 ''17'':50 ''28.was'':66 ''3'':56 ''46'':60 ''5'':51 ''58'':48 ''6'':53,59 ''62'':54 ''8'':47,62 ''afterward'':80 ''applic'':101 ''becam'':81 ''christ'':106 ''compar'':34 ''creat'':11 ''creation'':3 ''creatur'':9 ''declar'':39 ''divin'':33 ''etern'':19 ''flesh'':82 ''follow'':44 ''given'':76,119 ''god'':124 ''greek'':69 ''incarn'':85 ''jesus'':29,105 ''john'':46,49,52,55,58,61,64,86 ''logo'':72 ''lord'':104 ''ma'':138 ''mani'':110 ''meant'':96 ''messiah'':93 ''must'':14,30 ''name'':74,117 ''one'':23 ''opinion'':111,131,133 ''place'':45 ''plausibl'':137 ''reason'':114 ''repeat'':129 ''respect'':40 ''saviour'':36 ''seem'':135 ''son'':122 ''therefor'':16,32,99 ''uncreat'':17,27 ''unnecessari'':127 ''whatev'':94 ''word'':68 ''xistenc'':1', NULL, '998');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('229', '2', '229', NULL, 'This identity of locality with the scene of Samson''s birth and death indicates that both narratives are drawn from the same source, probably the annals of the tribe of Dan.', NULL, NULL, '''annal'':26 ''birth'':11 ''dan'':31 ''death'':13 ''drawn'':19 ''ident'':2 ''indic'':14 ''local'':4 ''narrat'':17 ''probabl'':24 ''samson'':9 ''scene'':7 ''sourc'':23 ''tribe'':29', NULL, '229');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1084', '2', '1084', NULL, 'y be expressed as follows:1. A "word" is that by which we communicate our will; by which we convey our thoughts; or by which we issue commands the medium of communication with others.2. The Son of God may be called "the Word," because he is the medium by which God promulgates His will and issues His commandments. See Hebrews 1:1-3.3. This term was in use before the time of John.(a) It was used in the Aramaic translation of the Old Testament, as, "e. g.," Isaiah 45:12; "I have made the earth, and created man upon it." In the Aramaic it is, "I, ''by my word,'' have made," etc. Isaiah 48:13; "mine hand also hath laid the foundation of the earth." In the Aramaic, "''By my word'' I have founded the earth." And so in many other places.(b) This term was used by the Jews as applicable to the Messiah. ', NULL, NULL, '''-3.3'':63 ''1'':6,61,62 ''12'':91 ''13'':116 ''45'':90 ''48'':115 ''also'':119 ''applic'':153 ''arama'':80,104,129 ''b'':144 ''call'':41 ''command'':28,58 ''communic'':14,32 ''convey'':20 ''creat'':98 ''e'':87 ''earth'':96,126,137 ''etc'':113 ''express'':3 ''follow'':5 ''found'':135 ''foundat'':123 ''g'':88 ''god'':38,51 ''hand'':118 ''hath'':120 ''hebrew'':60 ''isaiah'':89,114 ''issu'':27,56 ''jew'':151 ''john'':73 ''laid'':121 ''made'':94,112 ''man'':99 ''mani'':141 ''may'':39 ''medium'':30,48 ''messiah'':156 ''mine'':117 ''old'':84 ''others.2'':34 ''place'':143 ''promulg'':52 ''see'':59 ''son'':36 ''term'':65,146 ''testament'':85 ''thought'':22 ''time'':71 ''translat'':81 ''upon'':100 ''use'':68,77,148 ''word'':8,43,110,132 ''y'':1', NULL, '998');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1085', '2', '1085', NULL, 'In their writings he was commonly known by the term "Mimra" - that is, "Word;" and no small part of the interpositions of God in defense of the Jewish nation were declared to be by "the Word of God." Thus, in their Targum on Deuteronomy 26:17-18, it is said, "Ye have appointed the word of God a king over you this day, that he may be your God."(c) The term was used by the Jews who were scattered among the Gentiles, and especially those who were conversant with the Greek philosophy.(d) The term was used by the followers of Plato among the Greeks, to denote the Second Person of the Trinity. The Greek term &#x3bd;&#x3bf;&#x3c5;&#x3c2;  nous or "mind," was commonly given to this second person, but it was said that this nous was "the word" or "reason" of the First Person of the Trinity. The term', NULL, NULL, '''-18'':47 ''17'':46 ''26'':45 ''among'':81,104 ''appoint'':53 ''c'':70 ''common'':6,122 ''convers'':89 ''d'':94 ''day'':63 ''declar'':31 ''defens'':25 ''denot'':108 ''deuteronomi'':44 ''especi'':85 ''first'':142 ''follow'':101 ''gentil'':83 ''given'':123 ''god'':23,38,57,69 ''greek'':92,106,116 ''interposit'':21 ''jew'':77 ''jewish'':28 ''king'':59 ''known'':7 ''may'':66 ''mimra'':11 ''mind'':120 ''nation'':29 ''nous'':118,134 ''part'':18 ''person'':111,127,143 ''philosophi'':93 ''plato'':103 ''reason'':139 ''said'':50,131 ''scatter'':80 ''second'':110,126 ''small'':17 ''targum'':42 ''term'':10,72,96,117,148 ''thus'':39 ''triniti'':114,146 ''use'':74,98 ''word'':14,36,55,137 ''write'':3 ''ye'':51', NULL, '998');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1086', '2', '1086', NULL, ' was therefore extensively in use among the Jews and Gentiles before John wrote his Gospel, and it was certain that it would be applied to the Second Person of the Trinity by Christians. whether converted from Judaism or Paganism. It was important, therefore, that the meaning of the term should be settled by an inspired man, and accordingly John, in the commencement of his Gospel, is at much pains to state clearly what is the true doctrine respecting the &#x3bb;&#x3bf;&#x3b3;&#x3bf;&#x3c2;  Logos, or Word. It is possible, also, that the doctrines of the Gnostics had begun to spread in the time of John. They were an Oriental sect, and held that the &#x3bb;&#x3bf;&#x3b3;&#x3bf;&#x3c2;  Logos or "Word" was one of the "Aeones" that had been created, and that this one had been united to the man', NULL, NULL, '''accord'':58 ''aeon'':118 ''also'':86 ''among'':6 ''appli'':24 ''begun'':94 ''certain'':19 ''christian'':33 ''clear'':72 ''commenc'':62 ''convert'':35 ''creat'':122 ''doctrin'':77,89 ''extens'':3 ''gentil'':10 ''gnostic'':92 ''gospel'':15,65 ''held'':108 ''import'':42 ''inspir'':55 ''jew'':8 ''john'':12,59,101 ''judaism'':37 ''logo'':80,111 ''man'':56,132 ''mean'':46 ''much'':68 ''one'':115,126 ''orient'':105 ''pagan'':39 ''pain'':69 ''person'':28 ''possibl'':85 ''respect'':78 ''second'':27 ''sect'':106 ''settl'':52 ''spread'':96 ''state'':71 ''term'':49 ''therefor'':2,43 ''time'':99 ''triniti'':31 ''true'':76 ''unit'':129 ''use'':5 ''whether'':34 ''word'':82,113 ''would'':22 ''wrote'':13', NULL, '998');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1087', '2', '1087', NULL, ' Jesus. If that doctrine had begun then to prevail, it was of the more importance for John to settle the truth in regard to the rank of the Logos or Word. This he has done in such a way that there need be no doubt about its meaning.Was with God - This expression denotes friendship or intimacy. Compare Mark 9:19. John affirms that he was "with God" in the beginning - that is, before the world was made. It implies, therefore, that he was partaker of the divine glory; that he was blessed and happy with God. It proves that he was intimately united with the Father, so as to partake of his glory and to be appropriately called by the name God. He has himself explained it. See John 17:5; "And now, O Father, glorify thou we with thine own self, with the glory which I had with thee before the world ', NULL, NULL, '''17'':130 ''19'':60 ''5'':131 ''9'':59 ''affirm'':62 ''appropri'':117 ''begin'':70 ''begun'':6 ''bless'':92 ''call'':118 ''compar'':57 ''denot'':53 ''divin'':87 ''doctrin'':4 ''done'':35 ''doubt'':45 ''explain'':126 ''express'':52 ''father'':106,135 ''friendship'':54 ''glori'':88,113,145 ''glorifi'':136 ''god'':50,67,96,122 ''happi'':94 ''impli'':79 ''import'':15 ''intim'':102 ''intimaci'':56 ''jesus'':1 ''john'':17,61,129 ''logo'':29 ''made'':77 ''mark'':58 ''meaning.was'':48 ''name'':121 ''need'':42 ''o'':134 ''partak'':84,110 ''prevail'':9 ''prove'':98 ''rank'':26 ''regard'':23 ''see'':128 ''self'':142 ''settl'':19 ''thee'':150 ''therefor'':80 ''thine'':140 ''thou'':137 ''truth'':21 ''unit'':103 ''way'':39 ''word'':31 ''world'':75,153', NULL, '998');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1088', '2', '1088', NULL, 'was." See also John 1:18; "No man hath seen God at any time; the only-begotten Son, which is in the bosom of the Father, he hath declared him." See also John 3:13; "The Son of man, which is in heaven.', NULL, NULL, '''1'':5 ''13'':36 ''18'':6 ''3'':35 ''also'':3,33 ''begotten'':18 ''bosom'':24 ''declar'':30 ''father'':27 ''god'':11 ''hath'':9,29 ''heaven'':44 ''john'':4,34 ''man'':8,40 ''only-begotten'':16 ''see'':2,32 ''seen'':10 ''son'':19,38 ''time'':14', NULL, '998');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1127', '2', '1127', NULL, 'Behold, I bring him forth ... - Pilate, after examining Jesus, had gone forth and declared to the Jews that he found no fault in him, John 18:38. At that time Jesus remained in the judgment hall. The Jews were not satisfied with that, but demanded still that he should be put to death, John 19:39-40. Pilate, disposed to gratify the Jews, returned to Jesus and ordered him to be scourged, as if preparatory to death, John 19:1. The patience and meekness with which Jesus bore this seem to have convinced him still more that he was innocent, and he again went forth to declare his conviction of this; and, to do it more effectually, he said, "Behold, I bring him forth to you, that ye may know," etc. - that they might themselves see, and be satisfied, as he had been, of his innocence. All this shows his anxiety to release him, and also shows that the meekness, purity, and sincerity of Jesus had power to convince a Roman governor that he was not guilty. Thus, the highest evidence was given that the charges were false, even when he was condemned to die.', NULL, NULL, '''-40'':57 ''1'':80 ''18'':26 ''19'':55,79 ''38'':27 ''39'':56 ''also'':156 ''anxieti'':151 ''behold'':1,120 ''bore'':88 ''bring'':3,122 ''charg'':186 ''condemn'':193 ''convict'':109 ''convinc'':93,169 ''death'':53,77 ''declar'':14,107 ''demand'':45 ''die'':195 ''dispos'':59 ''effectu'':117 ''etc'':131 ''even'':189 ''evid'':181 ''examin'':8 ''fals'':188 ''fault'':22 ''forth'':5,12,105,124 ''found'':20 ''given'':183 ''gone'':11 ''governor'':172 ''gratifi'':61 ''guilti'':177 ''hall'':36 ''highest'':180 ''innoc'':100,146 ''jesus'':9,31,66,87,165 ''jew'':17,38,63 ''john'':25,54,78 ''judgment'':35 ''know'':130 ''may'':129 ''meek'':84,160 ''might'':134 ''order'':68 ''patienc'':82 ''pilat'':6,58 ''power'':167 ''preparatori'':75 ''puriti'':161 ''put'':51 ''releas'':153 ''remain'':32 ''return'':64 ''roman'':171 ''said'':119 ''satisfi'':41,139 ''scourg'':72 ''see'':136 ''seem'':90 ''show'':149,157 ''sincer'':163 ''still'':46,95 ''thus'':178 ''time'':30 ''went'':104 ''ye'':128', NULL, '1016');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1093', '2', '1093', NULL, 'he word, and go with it to the interpretation of the Scriptures. We should endeavor to place ourselves in the exact circumstances of those times, ascertain precisely what idea the word would convey to those who used it then, and apply that sense to the word in the interpretation of the Bible; and there is not the slightest evidence that the word so used would have conveyed any idea but that of the pure juice of the grape, nor the slightest circumstance mentioned in this account that would not be fully met by such a supposition.No man should adduce This instance in favor of drinking wine unless he can prove that the wine made in the waterpots of Cana was just like the wine which he proposes to drink. The Saviour''s example may be always pleaded just as it was; but it is a matter of obvious a', NULL, NULL, '''account'':86 ''adduc'':99 ''alway'':136 ''appli'':41 ''ascertain'':26 ''bibl'':52 ''cana'':119 ''circumst'':22,82 ''convey'':33,67 ''drink'':105,129 ''endeavor'':15 ''evid'':59 ''exact'':21 ''exampl'':133 ''favor'':103 ''fulli'':91 ''go'':4 ''grape'':78 ''idea'':29,69 ''instanc'':101 ''interpret'':9,49 ''juic'':75 ''like'':122 ''made'':114 ''man'':97 ''matter'':146 ''may'':134 ''mention'':83 ''met'':92 ''obvious'':148 ''place'':17 ''plead'':137 ''precis'':27 ''propos'':127 ''prove'':110 ''pure'':74 ''saviour'':131 ''scriptur'':12 ''sens'':43 ''slightest'':58,81 ''supposition.no'':96 ''time'':25 ''unless'':107 ''use'':37,64 ''waterpot'':117 ''wine'':106,113,124 ''word'':2,31,46,62 ''would'':32,65,88', NULL, '999');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1095', '2', '1095', NULL, 'therefore, that has been said about the Redeemer''s furnishing a large quantity of wine for the newly-married pair, and about his benevolence in doing it, is wholly gratuitous. There is no evidence of', NULL, NULL, '''benevol'':25 ''evid'':35 ''furnish'':10 ''gratuit'':31 ''larg'':12 ''marri'':20 ''newli'':19 ''newly-marri'':18 ''pair'':21 ''quantiti'':13 ''redeem'':8 ''said'':5 ''therefor'':1 ''wholli'':30 ''wine'':15', NULL, '999');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1094', '2', '1094', NULL, 'nd simple justice that we should find out exactly what the example was before we plead it. There is, moreover, no evidence that any other part of the water was converted into wine than that which was "drawn out" of the water-casks for the use of the guests. On this supposition, certainly, all the circumstances of the case are met, and the miracle would be more striking. All that was needed was to furnish a "supply" when the wine that had been prepared was nearly exhausted. The object was not to furnish a large quantity for future use. The miracle, too, would in this way be more apparent and impressive. On this supposition, the casks would appear to be filled with water only; as it was drawn out, it was pure wine. Who could doubt, then, that there was the exertion of miraculous power? All, ', NULL, NULL, '''appar'':110 ''appear'':119 ''case'':60 ''cask'':44,117 ''certain'':54 ''circumst'':57 ''convert'':31 ''could'':136 ''doubt'':137 ''drawn'':38,129 ''evid'':22 ''exact'':9 ''exampl'':12 ''exert'':143 ''exhaust'':88 ''fill'':122 ''find'':7 ''furnish'':76,94 ''futur'':99 ''guest'':50 ''impress'':112 ''justic'':3 ''larg'':96 ''met'':62 ''miracl'':65,102 ''miracul'':145 ''moreov'':20 ''nd'':1 ''near'':87 ''need'':73 ''object'':90 ''part'':26 ''plead'':16 ''power'':146 ''prepar'':85 ''pure'':133 ''quantiti'':97 ''simpl'':2 ''strike'':69 ''suppli'':78 ''supposit'':53,115 ''use'':47,100 ''water'':29,43,124 ''water-cask'':42 ''way'':107 ''wine'':33,81,134 ''would'':66,104,118', NULL, '999');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1092', '2', '1092', NULL, 't was destitute of spirit (lib. iv. c. 13). It should not be assumed, therefore, that the "good wine" was "stronger" than the other: it is rather to be presumed that it was milder.The wine referred to here was doubtless such as was commonly drunk in Palestine. That was the pure juice of the grape. It was not brandied wine, nor drugged wine, nor wine compounded of various substances, such as we drink in this land. The common wine drunk in Palestine was that which was the simple juice of the grape. we use the word "wine" now to denote the kind of liquid which passes under that name in this country - always containing a considerable portion of alcohol not only the alcohol produced by fermentation, but alcohol "added" to keep it or make it stronger. But we have no right to take that sense of t', NULL, NULL, '''13'':9 ''add'':129 ''alcohol'':119,123,128 ''alway'':113 ''assum'':14 ''brandi'':59 ''c'':8 ''common'':44,78 ''compound'':66 ''consider'':116 ''contain'':114 ''countri'':112 ''denot'':100 ''destitut'':3 ''doubtless'':40 ''drink'':73 ''drug'':62 ''drunk'':45,80 ''ferment'':126 ''good'':18 ''grape'':55,92 ''iv'':7 ''juic'':52,89 ''keep'':131 ''kind'':102 ''land'':76 ''lib'':6 ''liquid'':104 ''make'':134 ''milder.the'':34 ''name'':109 ''palestin'':47,82 ''pass'':106 ''portion'':117 ''presum'':30 ''produc'':124 ''pure'':51 ''rather'':27 ''refer'':36 ''right'':141 ''sens'':145 ''simpl'':88 ''spirit'':5 ''stronger'':21,136 ''substanc'':69 ''take'':143 ''therefor'':15 ''use'':94 ''various'':68 ''wine'':19,35,60,63,65,79,97 ''word'':96', NULL, '999');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1091', '2', '1091', NULL, 'presence and miraculous assistance, the all-important and world-wide institution of marriage." It was called "Cana of Galilee" to distinguish it from another Cana in the tribe of Ephraim, Joshua 16:9. This was the native place of Nathanael, John 21:2.The mother of Jesus - Mary. It is not improbable that she was a relative of the family where the marriage took place.', NULL, NULL, '''16'':34 ''2.the'':45 ''21'':44 ''9'':35 ''all-import'':6 ''anoth'':26 ''assist'':4 ''call'':18 ''cana'':19,27 ''distinguish'':23 ''ephraim'':32 ''famili'':61 ''galile'':21 ''import'':8 ''improb'':53 ''institut'':13 ''jesus'':48 ''john'':43 ''joshua'':33 ''mari'':49 ''marriag'':15,64 ''miracul'':3 ''mother'':46 ''nathanael'':42 ''nativ'':39 ''place'':40,66 ''presenc'':1 ''relat'':58 ''took'':65 ''tribe'':30 ''wide'':12 ''world'':11 ''world-wid'':10', NULL, '999');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1090', '2', '1090', NULL, 'd, in obedience to our call, and unlocked the doors of the church. It is a low stone building, pair." "The houses," says Dr. Thomson (''The Land and the Book,'' vol. ii. p. 126), "were built of limestone, cut and laid up after the fashion still common in this region, and some of them may have been inhabited within the last fifty years. There are many ancient cisterns about it, and fragments of water-jars in abundance, and both reminded us of the ''beginning of miracles.'' Some of my companions gathered bits of these water-jars as mementoes witnesses they could hardly be, for those of the narrative were of ''stone,'' while these were baked earth." The place is now quite deserted. Dr. Thomson says: "There is not now a habitable house in the humble village where our blessed Lord sanctioned, by his ', NULL, NULL, '''126'':34 ''abund'':78 ''ancient'':67 ''bake'':117 ''begin'':85 ''bit'':93 ''bless'':141 ''book'':30 ''build'':19 ''built'':36 ''call'':6 ''church'':13 ''cistern'':68 ''common'':47 ''companion'':91 ''could'':103 ''cut'':39 ''d'':1 ''desert'':124 ''door'':10 ''dr'':24,125 ''earth'':118 ''fashion'':45 ''fifti'':62 ''fragment'':72 ''gather'':92 ''habit'':133 ''hard'':104 ''hous'':22,134 ''humbl'':137 ''ii'':32 ''inhabit'':58 ''jar'':76,98 ''laid'':41 ''land'':27 ''last'':61 ''limeston'':38 ''lord'':142 ''low'':17 ''mani'':66 ''may'':55 ''memento'':100 ''miracl'':87 ''narrat'':110 ''obedi'':3 ''p'':33 ''pair'':20 ''place'':120 ''quit'':123 ''region'':50 ''remind'':81 ''sanction'':143 ''say'':23,127 ''still'':46 ''stone'':18,113 ''thomson'':25,126 ''unlock'':8 ''us'':82 ''villag'':138 ''vol'':31 ''water'':75,97 ''water-jar'':74,96 ''wit'':101 ''within'':59 ''year'':63', NULL, '999');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1089', '2', '1089', NULL, 'And the third day - On the third day after his conversation with Nathanael.Cana - This was a small town about 15 miles northwest of Tiberias and 6 miles northeast of Nazareth. It is now called Kerr Kenna, is under the government of a Turkish officer, and contains perhaps 300 inhabitants, chiefly Catholics. The natives still pretend to show the place where the water was turned into wine, and even one of the large stone water-pots. "A Greek church," says Professor Hackett (''Illustrations of Scripture,'' p. 322), "stands at the entrance of the town, deriving its special sanctity, as I understood, from its being supposed to occupy the site of the house in which the marriage was celebrated to which Jesus and his friends were invited. A priest to whom we were referred as the custodian soon arrive', NULL, NULL, '''15'':20 ''300'':48 ''322'':87 ''6'':26 ''arriv'':138 ''call'':34 ''cathol'':51 ''celebr'':118 ''chiefli'':50 ''church'':79 ''contain'':46 ''convers'':11 ''custodian'':136 ''day'':4,8 ''deriv'':95 ''entranc'':91 ''even'':68 ''friend'':124 ''govern'':40 ''greek'':78 ''hackett'':82 ''hous'':112 ''illustr'':83 ''inhabit'':49 ''invit'':126 ''jesus'':121 ''kenna'':36 ''kerr'':35 ''larg'':72 ''marriag'':116 ''mile'':21,27 ''nathanael.cana'':13 ''nativ'':53 ''nazareth'':30 ''northeast'':28 ''northwest'':22 ''occupi'':107 ''offic'':44 ''one'':69 ''p'':86 ''perhap'':47 ''place'':59 ''pot'':76 ''pretend'':55 ''priest'':128 ''professor'':81 ''refer'':133 ''sanctiti'':98 ''say'':80 ''scriptur'':85 ''show'':57 ''site'':109 ''small'':17 ''soon'':137 ''special'':97 ''stand'':88 ''still'':54 ''stone'':73 ''suppos'':105 ''third'':3,7 ''tiberia'':24 ''town'':18,94 ''turkish'':43 ''turn'':64 ''understood'':101 ''water'':62,75 ''water-pot'':74 ''wine'':66', NULL, '999');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1098', '2', '1098', NULL, 'to favor the Lord Jesus, it might provoke more opposition against him and endanger his life. Since no bad motive is imputed to him, it is most in accordance with Christian charity to suppose that his motives were such as God would approve, especially as the Saviour did not reprove him. We should not be disposed to blame men where Jesus did not, and we should desire to find goodness in every man rather than be ever on the search for evil motives. See 1 Corinthians 13:4-7. We may learn here:1. That our Saviour, though engaged during the day, did nor refuse to converse with an inquiring sinner at night. Ministers of the gospel at all times should welcome those who are asking the way to life.2. That it is proper for men, even those of elevated rank, to inquire on the subject of religion. Nothi', NULL, NULL, '''-7'':89 ''1'':85,94 ''13'':87 ''4'':88 ''accord'':29 ''approv'':43 ''ask'':126 ''bad'':19 ''blame'':58 ''chariti'':32 ''christian'':31 ''convers'':107 ''corinthian'':86 ''day'':102 ''desir'':67 ''dispos'':56 ''elev'':140 ''endang'':14 ''engag'':99 ''especi'':44 ''even'':137 ''ever'':77 ''everi'':72 ''evil'':82 ''favor'':2 ''find'':69 ''god'':41 ''good'':70 ''gospel'':117 ''imput'':22 ''inquir'':110,143 ''jesus'':5,61 ''learn'':92 ''life'':16 ''life.2'':130 ''lord'':4 ''man'':73 ''may'':91 ''men'':59,136 ''might'':7 ''minist'':114 ''motiv'':20,37,83 ''night'':113 ''nothi'':149 ''opposit'':10 ''proper'':134 ''provok'':8 ''rank'':141 ''rather'':74 ''refus'':105 ''religion'':148 ''reprov'':50 ''saviour'':47,97 ''search'':80 ''see'':84 ''sinc'':17 ''sinner'':111 ''subject'':146 ''suppos'':34 ''though'':98 ''time'':120 ''way'':128 ''welcom'':122 ''would'':42', NULL, '1000');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1096', '2', '1096', NULL, 'A man of the Pharisees - A Pharisee. See the notes at Matthew 3:7.Nicodemus, a ruler of the Jews - One of the "Sanhedrin," or great council of the nation. He is twice mentioned after this as being friendly to our Saviour; in the first instance as advocating his cause, and defending him against the unjust suspicion of the Jews John 7:50, and in the second instance as one who came to aid in embalming his body, John 19:39. It will be recollected that the design of John in writing this gospel was to show that Jesus was the Messiah. To do this he here adduces the testimony of one of the rulers of the Jews, who early became convinced of it, and who retained the belief of it until the death of Jesus.', NULL, NULL, '''19'':79 ''3'':13 ''39'':80 ''50'':62 ''7'':61 ''7.nicodemus'':14 ''adduc'':107 ''advoc'':47 ''aid'':73 ''becam'':120 ''belief'':128 ''bodi'':77 ''came'':71 ''caus'':49 ''convinc'':121 ''council'':26 ''death'':133 ''defend'':51 ''design'':87 ''earli'':119 ''embalm'':75 ''first'':44 ''friend'':38 ''gospel'':93 ''great'':25 ''instanc'':45,67 ''jesus'':98,135 ''jew'':19,59,117 ''john'':60,78,89 ''man'':2 ''matthew'':12 ''mention'':33 ''messiah'':101 ''nation'':29 ''note'':10 ''one'':20,69,111 ''pharise'':5,7 ''recollect'':84 ''retain'':126 ''ruler'':16,114 ''sanhedrin'':23 ''saviour'':41 ''second'':66 ''see'':8 ''show'':96 ''suspicion'':56 ''testimoni'':109 ''twice'':32 ''unjust'':55 ''write'':91', NULL, '1000');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1097', '2', '1097', NULL, 'illing to converse on the great subjects of judgment and eternity. Thus Paul says Galatians 2:2, "privately to them which are of reputation," evincing his consummate prudence, and his profound knowledge of human nature.By night - It is not mentioned why he came by night. It might have been that, being a member of the Sanhedrin, he was engaged all the day; or it may have been because the Lord Jesus was occupied all the day in teaching publicly and in working miracles, and that there was no opportunity for conversing with him as freely as he desired; or it may have been that he was afraid of the ridicule and contempt of those in power, and fearful that it might involve him in danger if publicly known; or it may have been that he was afraid that if it were publicly known that he was disposed ', NULL, NULL, '''2'':16,17 ''afraid'':107,137 ''came'':43 ''consumm'':27 ''contempt'':112 ''convers'':3,91 ''danger'':125 ''day'':62,76 ''desir'':98 ''dispos'':147 ''engag'':59 ''etern'':11 ''evinc'':25 ''fear'':118 ''freeli'':95 ''galatian'':15 ''great'':6 ''human'':34 ''ill'':1 ''involv'':122 ''jesus'':71 ''judgment'':9 ''knowledg'':32 ''known'':128,143 ''lord'':70 ''may'':65,101,131 ''member'':53 ''mention'':40 ''might'':47,121 ''miracl'':83 ''nature.by'':35 ''night'':36,45 ''occupi'':73 ''opportun'':89 ''paul'':13 ''power'':116 ''privat'':18 ''profound'':31 ''prudenc'':28 ''public'':79,127,142 ''reput'':24 ''ridicul'':110 ''sanhedrin'':56 ''say'':14 ''subject'':7 ''teach'':78 ''thus'':12 ''work'':82', NULL, '1000');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1128', '2', '1128', NULL, 'The scripture - See Luke 24:26, Luke 24:46. The sense or meaning of the various predictions that foretold his death, as, for example, Psalm 2:7, compare Acts 13:33; Psalm 16:9-10, compare Acts 2:25-32; Psalm 110:1, compare Acts 2:34-35.For an account of the resurrection of Christ, see the notes at Matthew 28.', NULL, NULL, '''-10'':35 ''-32'':40 ''1'':43 ''110'':42 ''13'':30 ''16'':33 ''2'':26,38,46 ''24'':5,8 ''25'':39 ''26'':6 ''28'':60 ''33'':31 ''34-35.for'':47 ''46'':9 ''7'':27 ''9'':34 ''account'':49 ''act'':29,37,45 ''christ'':54 ''compar'':28,36,44 ''death'':21 ''exampl'':24 ''foretold'':19 ''luke'':4,7 ''matthew'':59 ''mean'':13 ''note'':57 ''predict'':17 ''psalm'':25,32,41 ''resurrect'':52 ''scriptur'':2 ''see'':3,55 ''sens'':11 ''various'':16', NULL, '1017');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('230', '2', '230', NULL, 'A concubine - See the margin. The name does not imply any moral reproach. A concubine was as much the man''s wife as the woman so called, though she had not the same rights. See Judges 19:3-4.', NULL, NULL, '''-4'':39 ''19'':37 ''3'':38 ''call'':27 ''concubin'':2,15 ''impli'':10 ''judg'':36 ''man'':20 ''margin'':5 ''moral'':12 ''much'':18 ''name'':7 ''reproach'':13 ''right'':34 ''see'':3,35 ''though'':28 ''wife'':22 ''woman'':25', NULL, '230');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1099', '2', '1099', NULL, 'ng is so important as religion, and no temper of mind is more lovely than a disposition to ask the way to heaven. At all times men should seek the way of salvation, and especially in times of great religions excitement they should make inquiry. At Jerusalem, at the time referred to here, there was great solicitude. Many believed on Jesus. He performed miracles, and preached, and many were converted. There was what would now be called a revival of religion, having all the features of a work of grace. At such a season it was proper, as it is now, that not only the poor, but the rich and great, should inquire the path to life.Rabbi - This was a title of respect conferred on distinguished Jewish teachers, somewhat in the way that the title "Doctor of Divinity" is now conferred. See the notes a', NULL, NULL, '''ask'':19 ''believ'':59 ''call'':77 ''confer'':124,141 ''convert'':70 ''disposit'':17 ''distinguish'':126 ''divin'':138 ''doctor'':136 ''especi'':35 ''excit'':41 ''featur'':85 ''grace'':90 ''great'':39,56,111 ''heaven'':23 ''import'':4 ''inquir'':113 ''inquiri'':45 ''jerusalem'':47 ''jesus'':61 ''jewish'':127 ''life.rabbi'':117 ''love'':14 ''make'':44 ''mani'':58,68 ''men'':27 ''mind'':11 ''miracl'':64 ''ng'':1 ''note'':144 ''path'':115 ''perform'':63 ''poor'':106 ''preach'':66 ''proper'':97 ''refer'':51 ''religion'':6,40,81 ''respect'':123 ''reviv'':79 ''rich'':109 ''salvat'':33 ''season'':94 ''see'':142 ''seek'':29 ''solicitud'':57 ''somewhat'':129 ''teacher'':128 ''temper'':9 ''time'':26,37,50 ''titl'':121,135 ''way'':21,31,132 ''work'':88 ''would'':74', NULL, '1000');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1100', '2', '1100', NULL, 't John 1:38. Our Saviour forbade his disciples to wear that title (see the notes at Matthew 23:8), though it was proper for Him to do it, as being the great Teacher of mankind. It literally signifies great, and was given by Nicodemus, doubtless, because Jesus gave distinguished proofs that he came as a teacher from God.We know - I know, and those with whom I am connected. Perhaps he was acquainted with some of the Pharisees who entertained the same opinion about Jesus that he did, and he came to be more fully confirmed in the belief.Come from God - Sent by God. This implies his readiness to hear him, and his desire to be instructed. He acknowledges the divine mission of Jesus, and delicately asks him to instruct him in the truth of religion. When we read the words of Jesus in the Bible, it', NULL, NULL, '''1'':3 ''23'':19 ''38'':4 ''8'':20 ''acknowledg'':119 ''acquaint'':73 ''ask'':127 ''belief.come'':99 ''bibl'':146 ''came'':54,91 ''confirm'':96 ''connect'':69 ''delic'':126 ''desir'':114 ''discipl'':9 ''distinguish'':50 ''divin'':121 ''doubtless'':46 ''entertain'':80 ''forbad'':7 ''fulli'':95 ''gave'':49 ''given'':43 ''god'':101,104 ''god.we'':59 ''great'':33,40 ''hear'':110 ''impli'':106 ''instruct'':117,130 ''jesus'':48,85,124,143 ''john'':2 ''know'':60,62 ''liter'':38 ''mankind'':36 ''matthew'':18 ''mission'':122 ''nicodemus'':45 ''note'':16 ''opinion'':83 ''perhap'':70 ''pharise'':78 ''proof'':51 ''proper'':24 ''read'':139 ''readi'':108 ''religion'':136 ''saviour'':6 ''see'':14 ''sent'':102 ''signifi'':39 ''teacher'':34,57 ''though'':21 ''titl'':13 ''truth'':134 ''wear'':11 ''word'':141', NULL, '1000');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1101', '2', '1101', NULL, ' should be with a belief that he came from God, and was therefore qualified and authorized to teach us the way of life.These miracles - The miracles which he performed in the Temple and at Jerusalem, John 2:23.Except God be with him - Except God aid him, and except his instructions are approved by God. Miracles show that a prophet or religious teacher comes from God, because God would nor work a miracle in attestation of a falsehood or to give countenance to a false teacher. If God gives a man power to work a miracle, it is proof that he approves the teaching of that man, and the miracle is the proof or the credential that he came from God.', NULL, NULL, '''2'':37 ''23.except'':38 ''aid'':45 ''approv'':52,101 ''attest'':74 ''author'':16 ''belief'':5 ''came'':8,118 ''come'':63 ''counten'':81 ''credenti'':115 ''except'':43,48 ''fals'':84 ''falsehood'':77 ''give'':80,88 ''god'':10,39,44,54,65,67,87,120 ''instruct'':50 ''jerusalem'':35 ''john'':36 ''life.these'':23 ''man'':90,106 ''miracl'':24,26,55,72,95,109 ''perform'':29 ''power'':91 ''proof'':98,112 ''prophet'':59 ''qualifi'':14 ''religi'':61 ''show'':56 ''teach'':18,103 ''teacher'':62,85 ''templ'':32 ''therefor'':13 ''us'':19 ''way'':21 ''work'':70,93 ''would'':68', NULL, '1000');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1103', '2', '1103', NULL, 'The Lord knew - When Jesus knew. how he knew this we are not informed; whether by that power of omniscience by which he knew all things, or whether some person had informed him of it.How the Pharisees had heard - The Pharisees, here, seem to denote either the members of the Sanhedrin or those who were in authority. They claimed the authority to regulate the rites and ceremonies of religion, and hence they supposed they had a right to inquire into the conduct of both John and our Lord. They had on a former occasion sent to inquire of John to know by what authority he had introduced such a rite into the religion of the Jewish people. See the notes at John 1:25.More disciples than John - Though many of the Pharisees came to his baptism Matthew 3, yet those who were in authority were displease', NULL, NULL, '''1'':123 ''25.more'':124 ''3'':138 ''author'':57,61,104,144 ''baptism'':136 ''came'':133 ''ceremoni'':67 ''claim'':59 ''conduct'':82 ''denot'':45 ''discipl'':125 ''displeas'':146 ''either'':46 ''former'':93 ''heard'':39 ''henc'':71 ''inform'':14,32 ''inquir'':79,97 ''introduc'':107 ''it.how'':35 ''jesus'':5 ''jewish'':116 ''john'':85,99,122,127 ''knew'':3,6,9,24 ''know'':101 ''lord'':2,88 ''mani'':129 ''matthew'':137 ''member'':48 ''note'':120 ''occas'':94 ''omnisci'':20 ''peopl'':117 ''person'':30 ''pharise'':37,41,132 ''power'':18 ''regul'':63 ''religion'':69,113 ''right'':77 ''rite'':65,110 ''sanhedrin'':51 ''see'':118 ''seem'':43 ''sent'':95 ''suppos'':73 ''thing'':26 ''though'':128 ''whether'':15,28 ''yet'':139', NULL, '1001');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1104', '2', '1104', NULL, 'd with the success of John, John 1:25. The reasons of this were, probably, the severity and justness of his reproofs Matthew 3:7, and the fact that by drawing many after him he weakened their authority and influence. As they were displeased with John, so they were with Jesus, who was doing the same thing on a larger scale - not only making disciples, but baptizing also without their authority, and drawing away the people after him.', NULL, NULL, '''1'':8 ''25'':9 ''3'':24 ''7'':25 ''also'':68 ''author'':38,71 ''away'':74 ''baptiz'':67 ''d'':1 ''discipl'':65 ''displeas'':44 ''draw'':31,73 ''fact'':28 ''influenc'':40 ''jesus'':51 ''john'':6,7,46 ''just'':19 ''larger'':60 ''make'':64 ''mani'':32 ''matthew'':23 ''peopl'':76 ''probabl'':15 ''reason'':11 ''reproof'':22 ''scale'':61 ''sever'':17 ''success'':4 ''thing'':57 ''weaken'':36 ''without'':69', NULL, '1001');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1105', '2', '1105', NULL, 'f Jacob. The well was near to this. There is now, E. Smith mentioned to me in conversation, a place near this well called Shalem.', NULL, NULL, '''call'':24 ''convers'':18 ''e'':12 ''f'':1 ''jacob'':2 ''mention'':14 ''near'':6,21 ''place'':20 ''shalem'':25 ''smith'':13 ''well'':4,23', NULL, '1001');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1109', '2', '1109', NULL, 'ich the sick descended after the troubling of the water, and were healed, John 5:1 ff. It is 360 feet long, 130 feet wide, and 75 deep. The evangelist says that this pool was near the sheep-gate, as the Greek probably signifies, rather than sheep-market, as rendered in the English version. That gate, according to Nehemiah 3:1 ff, was on the north side of the temple, and hence, the situation of this reservoir would agree with that of Bethesda. The present name, Birket Israil, Pool of Israil, indicates the opinion of the native inhabitants in regard to the object of the excavation. The general opinion of the most accurate travelers is that the so-called pool was originally part of a trench or fosse which protected the temple on the north.Though it contains no water at present except a little', NULL, NULL, '''1'':16,63 ''130'':23 ''3'':62 ''360'':20 ''5'':15 ''75'':27 ''accord'':59 ''accur'':115 ''agre'':81 ''bethesda'':85 ''birket'':89 ''call'':122 ''contain'':140 ''deep'':28 ''descend'':4 ''english'':55 ''evangelist'':30 ''excav'':108 ''except'':145 ''feet'':21,24 ''ff'':17,64 ''foss'':131 ''gate'':40,58 ''general'':110 ''greek'':43 ''heal'':13 ''henc'':74 ''ich'':1 ''indic'':94 ''inhabit'':100 ''israil'':90,93 ''john'':14 ''littl'':147 ''long'':22 ''market'':50 ''name'':88 ''nativ'':99 ''near'':36 ''nehemiah'':61 ''north'':68 ''north.though'':138 ''object'':105 ''opinion'':96,111 ''origin'':125 ''part'':126 ''pool'':34,91,123 ''present'':87,144 ''probabl'':44 ''protect'':133 ''rather'':46 ''regard'':102 ''render'':52 ''reservoir'':79 ''say'':31 ''sheep'':39,49 ''sheep-gat'':38 ''sheep-market'':48 ''sick'':3 ''side'':69 ''signifi'':45 ''situat'':76 ''so-cal'':120 ''templ'':72,135 ''travel'':116 ''trench'':129 ''troubl'':7 ''version'':56 ''water'':10,142 ''wide'':25 ''would'':80', NULL, '1002');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1108', '2', '1108', NULL, 'guage then spoken, which did not differ essentially from the ancient Hebrew.Bethesda - The house of mercy. It was so called on account of its strong healing properties - the property of restoring health to the sick and infirm.Five porches - The word "porch" commonly means a covered place surrounding a building, in which people can walk or sit in hot or wet weather. Here it probably means that there were five covered places, or apartments, in which the sick could remain, from each one of which they could have access to the water. This "pool" is thus described by Professor Hackett ("Illustrations of Scripture," pp. 291, 292): "Just to the east of the Turkish garrison, and under the northern wall of the mosque, is a deep excavation, supposed by many to be the ancient pool of Bethesda, into wh', NULL, NULL, '''291'':104 ''292'':105 ''access'':88 ''account'':22 ''ancient'':11,132 ''apart'':73 ''bethesda'':135 ''build'':49 ''call'':20 ''common'':42 ''could'':78,86 ''cover'':45,70 ''deep'':124 ''describ'':96 ''differ'':7 ''east'':109 ''essenti'':8 ''excav'':125 ''five'':69 ''garrison'':113 ''guag'':1 ''hackett'':99 ''heal'':26 ''health'':32 ''hebrew.bethesda'':12 ''hot'':58 ''hous'':14 ''illustr'':100 ''infirm.five'':37 ''mani'':128 ''mean'':43,65 ''merci'':16 ''mosqu'':121 ''northern'':117 ''one'':82 ''peopl'':52 ''place'':46,71 ''pool'':93,133 ''porch'':38,41 ''pp'':103 ''probabl'':64 ''professor'':98 ''properti'':27,29 ''remain'':79 ''restor'':31 ''scriptur'':102 ''sick'':35,77 ''sit'':56 ''spoken'':3 ''strong'':25 ''suppos'':126 ''surround'':47 ''thus'':95 ''turkish'':112 ''walk'':54 ''wall'':118 ''water'':91 ''weather'':61 ''wet'':60 ''wh'':137 ''word'':40', NULL, '1002');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1107', '2', '1107', NULL, 'A feast - Probably the Passover, though it is not certain. There were two other feasts - the Pentecost and the Feast of Tabernacles - at which all the males were required to be present, and it might have been one of them. It is of no consequence, however, which of them is intended.', NULL, NULL, '''certain'':10 ''consequ'':45 ''feast'':2,15,20 ''howev'':46 ''intend'':51 ''male'':27 ''might'':35 ''one'':38 ''passov'':5 ''pentecost'':17 ''present'':32 ''probabl'':3 ''requir'':29 ''tabernacl'':22 ''though'':6 ''two'':13', NULL, '1002');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1113', '2', '1113', NULL, 'mbling, and dissipation! How melancholy that amid the very places Where there is most evidence of the goodness of God, and of the misery of the poor, the sick, the afflicted, men should forget all the', NULL, NULL, '''afflict'':31 ''amid'':7 ''dissip'':3 ''evid'':15 ''forget'':34 ''god'':20 ''good'':18 ''mbling'':1 ''melancholi'':5 ''men'':32 ''miseri'':24 ''place'':10 ''poor'':27 ''sick'':29', NULL, '1002');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1112', '2', '1112', NULL, 'njecture would be useless. We may remark, however, that such a place anywhere is an evidence of the great goodness of God. Springs or fountains having healing properties abound on earth, and nowhere more than in our own country. Diseases are often healed in such places which no human skill could remove. The Jews regarded such a provision as proof of the mercy of God. They gave this healing spring the name of a "house of mercy." They regarded it as under the care of an angel. And there is no place where man should be more sensible of the goodness of God, or be more disposed to render him praise as in a "house of mercy," than when at such a healing fountain. And yet how lamentable is it that such places - watering places - should be mere places of gaiety and thoughtlessness, of balls, and ga', NULL, NULL, '''abound'':29 ''angel'':87 ''anywher'':13 ''ball'':145 ''care'':84 ''could'':51 ''countri'':39 ''diseas'':40 ''dispos'':107 ''earth'':31 ''evid'':16 ''fountain'':25,124 ''ga'':147 ''gaieti'':141 ''gave'':67 ''god'':22,65,103 ''good'':20,101 ''great'':19 ''heal'':27,43,69,123 ''hous'':75,115 ''howev'':8 ''human'':49 ''jew'':54 ''lament'':128 ''man'':94 ''may'':6 ''merci'':63,77,117 ''mere'':138 ''name'':72 ''njectur'':1 ''nowher'':33 ''often'':42 ''place'':12,46,92,133,135,139 ''prais'':111 ''proof'':60 ''properti'':28 ''provis'':58 ''regard'':55,79 ''remark'':7 ''remov'':52 ''render'':109 ''sensibl'':98 ''skill'':50 ''spring'':23,70 ''thoughtless'':143 ''useless'':4 ''water'':134 ''would'':2 ''yet'':126', NULL, '1002');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1111', '2', '1111', NULL, '509). In the time of Sandys (1611) the spring was found running, but in small quantities; in the time of Maundrell (1697) the stream did not run. Probably in his time, as now, the water which had formerly filtered through the rocks was dammed up by the rubbish.', NULL, NULL, '''1611'':7 ''1697'':22 ''509'':1 ''dam'':44 ''filter'':39 ''former'':38 ''found'':11 ''maundrel'':21 ''probabl'':28 ''quantiti'':16 ''rock'':42 ''rubbish'':48 ''run'':12,27 ''sandi'':6 ''small'':15 ''spring'':9 ''stream'':24 ''time'':4,19,31 ''water'':35', NULL, '1002');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1139', '2', '1139', NULL, 'In Cesarea - See the notes on Acts 8:40.Cornelius - This is a Latin name, and shows that the man was doubtless a Roman. It has been supposed by many interpreters that he was "a proselyte of the gate"; that is, one who had renounced idolatry, and who observed some of the Jewish rites, though not circumcised, and not called a Jew. But there is no sufficient evidence of this. The reception of the narrative of I Peter Acts 11:1-3 shows that the other apostles regarded him as a Gentile. In Acts 10:28, Peter evidently regards him as a foreigner - one who did not in any sense esteem himself to be a Jew. In Acts 11:1, it is expressly said that "the Gentiles" had received the Word of God, evidently alluding to Cornelius and to those who were with him.A centurion - One who was the commander of a division in the Roman army, consisting of 100 men. A captain of 100. See the notes on Matthew 8:5.Of the band - A division of the Roman army, consisting of from 400 to 600 men. See the notes on Matthew 27:27.The Italian band - Probably a band or regiment that was composed of soldiers from Italy, in distinction from those which were composed of soldiers born in provinces. It is evident that many of the soldiers in the Roman army would be those who were born in other parts of the world; and it is altogether probable that those who were born in Rome or Italy would claim pre-eminence over those enlisted in other places.', NULL, NULL, '''-3'':81 ''1'':80,119 ''10'':94 ''100'':159,164 ''11'':79,118 ''27'':192 ''27.the'':193 ''28'':95 ''40.cornelius'':9 ''400'':183 ''5.of'':171 ''600'':185 ''8'':8,170 ''act'':7,78,93,117 ''allud'':134 ''altogeth'':247 ''apostl'':86 ''armi'':156,179,231 ''band'':173,195,198 ''born'':217,237,253 ''call'':59 ''captain'':162 ''centurion'':144 ''cesarea'':2 ''circumcis'':56 ''claim'':259 ''command'':149 ''compos'':203,214 ''consist'':157,180 ''cornelius'':136 ''distinct'':209 ''divis'':152,175 ''doubtless'':21 ''emin'':262 ''enlist'':265 ''esteem'':110 ''evid'':67,97,133,222 ''expressli'':122 ''foreign'':102 ''gate'':38 ''gentil'':91,126 ''god'':132 ''him.a'':143 ''idolatri'':45 ''interpret'':30 ''itali'':207,257 ''italian'':194 ''jew'':61,115 ''jewish'':52 ''latin'':13 ''man'':19 ''mani'':29,224 ''matthew'':169,191 ''men'':160,186 ''name'':14 ''narrat'':74 ''note'':5,167,189 ''observ'':48 ''one'':41,103,145 ''part'':240 ''peter'':77,96 ''place'':268 ''pre'':261 ''pre-emin'':260 ''probabl'':196,248 ''proselyt'':35 ''provinc'':219 ''receiv'':128 ''recept'':71 ''regard'':87,98 ''regiment'':200 ''renounc'':44 ''rite'':53 ''roman'':23,155,178,230 ''rome'':255 ''said'':123 ''see'':3,165,187 ''sens'':109 ''show'':16,82 ''soldier'':205,216,227 ''suffici'':66 ''suppos'':27 ''though'':54 ''word'':130 ''world'':243 ''would'':232,258', NULL, '1028');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1110', '2', '1110', NULL, ' which trickles through the stones at the west end, it has evidently been used at some period as a reservoir. It is lined with cement, and adapted in other respects to hold water." Dr. Robinson established by personal inspection the fact of the subterranean connection of the pool of "Siloam" with the "Fountain of the Virgin," and made it probable that the fountain under the mosque of Omar is connected with them. This spring is, as he himself witnessed, an "intermittent" one, and there "may" have been some artificially constructed basin in connection with this spring to which was given the name of "Bethesda." He supposes, however, that there is not the slightest evidence that the place or reservoir now pointed out as "Bethesda" was the Bethesda of the New Testament (Bib. Res., i. 501, 506, ', NULL, NULL, '''501'':135 ''506'':136 ''adapt'':27 ''artifici'':89 ''basin'':91 ''bethesda'':104,124,127 ''bib'':132 ''cement'':25 ''connect'':45,70,93 ''construct'':90 ''dr'':34 ''end'':9 ''establish'':36 ''evid'':12,114 ''fact'':41 ''fountain'':53,63 ''given'':100 ''hold'':32 ''howev'':107 ''inspect'':39 ''intermitt'':81 ''line'':23 ''made'':58 ''may'':85 ''mosqu'':66 ''name'':102 ''new'':130 ''omar'':68 ''one'':82 ''period'':17 ''person'':38 ''place'':117 ''point'':121 ''pool'':48 ''probabl'':60 ''res'':133 ''reservoir'':20,119 ''respect'':30 ''robinson'':35 ''siloam'':50 ''slightest'':113 ''spring'':74,96 ''stone'':5 ''subterranean'':44 ''suppos'':106 ''testament'':131 ''trickl'':2 ''use'':14 ''virgin'':56 ''water'':33 ''west'':8 ''wit'':79', NULL, '1002');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1114', '2', '1114', NULL, 'I am the bread of life - I am the support of spiritual life; or my doctrines will give life and peace to the soul.Shall never hunger - See the notes at John 4:14.', NULL, NULL, '''14'':33 ''4'':32 ''bread'':4 ''doctrin'':16 ''give'':18 ''hunger'':26 ''john'':31 ''life'':6,13,19 ''never'':25 ''note'':29 ''peac'':21 ''see'':27 ''soul.shall'':24 ''spiritu'':12 ''support'':10', NULL, '1003');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1115', '2', '1115', NULL, 'After these things - After the transactions which are recorded in the last chapters had taken place, and after the offence he had given the Jews. See John 5:18.Jesus walked - Or Jesus lived, or taught. He traveled around Galilee teaching.In Jewry - In Judea, the southern division of Palestine. Compare the notes at John 4:3.The Jews sought - That is, the rulers of the Jews. It does not appear that the common people ever attempted to take his life.', NULL, NULL, '''18.jesus'':29 ''3.the'':55 ''4'':54 ''5'':28 ''appear'':68 ''around'':38 ''attempt'':74 ''chapter'':13 ''common'':71 ''compar'':49 ''divis'':46 ''ever'':73 ''galile'':39 ''given'':23 ''jesus'':32 ''jew'':25,56,64 ''jewri'':41 ''john'':27,53 ''judea'':43 ''last'':12 ''life'':78 ''live'':33 ''note'':51 ''offenc'':20 ''palestin'':48 ''peopl'':72 ''place'':16 ''record'':9 ''ruler'':61 ''see'':26 ''sought'':57 ''southern'':45 ''take'':76 ''taken'':15 ''taught'':35 ''teaching.in'':40 ''thing'':3 ''transact'':6 ''travel'':37 ''walk'':30', NULL, '1004');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1116', '2', '1116', NULL, 'Mount of Olives - The mountain about a mile directly east of Jerusalem. See the notes at Matthew 21:1. This was the place in which he probably often passed the night when attending the feasts at Jerusalem. The Garden of Gethsemane, to which he was accustomed to resort John 18:2, was on the western side of that mountain, and Bethany, the abode of Martha and Mary, on its east side, John 11:1.', NULL, NULL, '''1'':19,74 ''11'':73 ''18'':50 ''2'':51 ''21'':18 ''abod'':63 ''accustom'':46 ''attend'':33 ''bethani'':61 ''direct'':9 ''east'':10,70 ''feast'':35 ''garden'':39 ''gethseman'':41 ''jerusalem'':12,37 ''john'':49,72 ''mari'':67 ''martha'':65 ''matthew'':17 ''mile'':8 ''mount'':1 ''mountain'':5,59 ''night'':31 ''note'':15 ''often'':28 ''oliv'':3 ''pass'':29 ''place'':23 ''probabl'':27 ''resort'':48 ''see'':13 ''side'':56,71 ''western'':55', NULL, '1005');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1117', '2', '1117', NULL, 'As Jesus passed by - As he was leaving the temple, John 8:59. This man was in the way in which Jesus was going to escape from the Jews.', NULL, NULL, '''59'':13 ''8'':12 ''escap'':26 ''go'':24 ''jesus'':2,22 ''jew'':29 ''john'':11 ''leav'':8 ''man'':15 ''pass'':3 ''templ'':10 ''way'':19', NULL, '1006');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1118', '2', '1118', NULL, 'Verily, verily - See the notes at John 3:3.I say unto you - Some have supposed that what follows here was delivered on some other occasion than the one mentioned in the last chapter; but the expression verily, verily, is one which is not used at the commencement of a discourse, and the discourse itself seems to be a continuation of what was said before. The Pharisees professed to be the guides or shepherds of the people. Jesus, in the close of the last chapter, had charged them with being blind, and of course of being unqualified to lead the people. He proceeds here to state the character of a true shepherd, to show what was a hireling, and to declare that he was the true shepherd and guide of his people. This is called John 10:6 a parable, and it is an eminently beautiful illustration of the office of the Messiah, drawn from an employment well known in Judea. The Messiah was predicted under the image of a shepherd. Ezekiel 34:23; Ezekiel 37:24; Zechariah 13:7. Hence, at the close of the discourse they asked him whether he were the Messiah, John 10:24.Into the sheepfold - The sheepfold was an inclosure made in fields where the sheep were collected by night to defend them from robbers, wolves, etc. It was not commonly covered, as the seasons in Judea were mild. By the figure here we are to understand the Jewish people, or the church of God, which is often likened to a flock, Ezekiel 34:1-19; Jeremiah 23:1-4; Zechariah 13:1-9. By the door, here, is meant the Lord Jesus Christ, John 10:7, John 10:9. He is "the way, the truth, and the life," John 14:6. And, as the only proper way of entering the fold was by the door, so the only way of entering the church of God is by believing on him and obeying his commandments. The particular application of this place, however, is to religious teachers, who cannot enter properly on the duties of teaching and guarding the flock except by the Lord Jesus that is, in the way which he has appointed. The Pharisees claimed to be pastors, but not under his appointment. They entered some other way. The true pastors of the church are those who enter by the influences of the Spirit of Jesus, and in the manner which he has appointed.Some other way - Either at a window or over the wall.A thief - One who silently and secretly takes away the property of another.A robber - One who does it by violence or bloodshed. Jesus here designates those pastors or ministers of religion who are influenced not by love to him, but who seek the office from ambition, or the love of power, or wealth, or ease; who come, not to promote the welfare of the church, but to promote their own interests. Alas! in all churches there have been many - many who for no better ends have sought the pastoral office. To all such Jesus gives the names of thieves and robbers.', NULL, NULL, '''-19'':261 ''-4'':265 ''-9'':269 ''1'':260,264,268 ''10'':137,197,281,284 ''13'':179,267 ''14'':296 ''23'':174,263 ''24'':177 ''24.into'':198 ''3'':8,9 ''34'':173,259 ''37'':176 ''6'':138,297 ''7'':180,282 ''9'':285 ''ala'':491 ''ambit'':465 ''another.a'':432 ''applic'':333 ''appoint'':368,379 ''appointed.some'':410 ''ask'':189 ''away'':428 ''beauti'':146 ''believ'':324 ''better'':503 ''blind'':91 ''bloodsh'':441 ''call'':135 ''cannot'':343 ''chapter'':34,85 ''charact'':108 ''charg'':87 ''christ'':279 ''church'':248,319,390,484,494 ''claim'':371 ''close'':81,184 ''collect'':213 ''come'':476 ''command'':330 ''commenc'':48 ''common'':226 ''continu'':60 ''cours'':94 ''cover'':227 ''declar'':121 ''defend'':217 ''deliv'':22 ''design'':444 ''discours'':51,54,187 ''door'':272,311 ''drawn'':154 ''duti'':348 ''eas'':474 ''either'':413 ''emin'':145 ''employ'':157 ''end'':504 ''enter'':305,317,344,381,394 ''etc'':222 ''except'':355 ''express'':37 ''ezekiel'':172,175,258 ''field'':208 ''figur'':237 ''flock'':25