INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1119', '2', '1119', NULL, 'Saying, She goeth unto the grave - Syriac, "They thought that she went to weep." They had not heard Martha call her. The first days of mourning among the Jews were observed with great solemnity and many ceremonies of grief.', NULL, NULL, '''among'':27 ''call'':20 ''ceremoni'':37 ''day'':24 ''first'':23 ''goeth'':3 ''grave'':6 ''great'':33 ''grief'':39 ''heard'':18 ''jew'':29 ''mani'':36 ''martha'':19 ''mourn'':26 ''observ'':31 ''say'':1 ''solemn'':34 ''syriac'':7 ''thought'':9 ''unto'':4 ''weep'':14 ''went'':12', NULL, '1008');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1120', '2', '1120', NULL, 'Then Jesus came to Bethany - This was near to Jerusalem, and it was from this place that he made his triumphant entry into the city. See the notes at Matthew 21:1.', NULL, NULL, '''1'':32 ''21'':31 ''bethani'':5 ''came'':3 ''citi'':25 ''entri'':22 ''jerusalem'':10 ''jesus'':2 ''made'':19 ''matthew'':30 ''near'':8 ''note'':28 ''place'':16 ''see'':26 ''triumphant'':21', NULL, '1009');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('231', '2', '231', NULL, 'Fasted until even - The regular time for ending a fast among the Hebrews was sunset (compare 1 Samuel 14:24; 2 Samuel 1:12). Such national fasts are called by the rabbis "fasts of the congregation," and were enjoined in times of great affliction.On the offerings, see Lev. i., 3.', NULL, NULL, '''1'':17,23 ''12'':24 ''14'':19 ''2'':21 ''24'':20 ''3'':50 ''affliction.on'':44 ''among'':11 ''call'':29 ''compar'':16 ''congreg'':36 ''end'':8 ''enjoin'':39 ''even'':3 ''fast'':1,10,27,33 ''great'':43 ''hebrew'':13 ''lev'':48 ''nation'':26 ''offer'':46 ''rabbi'':32 ''regular'':5 ''samuel'':18,22 ''see'':47 ''sunset'':15 ''time'':6,41', NULL, '231');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1122', '2', '1122', NULL, 'Let not your heart be troubled - The disciples had been greatly distressed at what Jesus had said about leaving them. Compare John 16:6, John 16:22. Perhaps they had indicated their distress to him in some manner by their countenance or their expressions, and he proceeds new to administer to them such consolations as their circumstances made proper. The discourse in this chapter was delivered, doubtless, while they were sitting at the table partaking of the Lord''s Supper (see John 14:31); that in John 15-16, and the prayer in John 17, were while they were on their way to the Mount of Olives. There is nowhere to be found a discourse so beautiful, so tender, so full of weighty thoughts, and so adapted to produce comfort, as that which occurs in these three chapters of John. It is the consolatory part of our religion, where Christ brings to bear on the mind full of anxiety, and perplexity, and care, the tender and inimitably beautiful truths of his gospel - truths fitted to allay every fear, silence every complaint, and give every needed consolation to the soul. In the case of the disciples there was much to trouble them. They were about to part with their beloved, tender friend. They were to be left alone to meet persecutions and trials. They were without wealth, without friends, without honors. And it is not improbable that they felt that his death would demolish all their schemes, for they had not yet fully learned the doctrine that the Messiah must suffer and die, Luke 24:21.Ye believe in God - This may be read either in the indicative mood or the imperative. Probably it should be read in the imperative - "Believe on God, and believe on me." If there were no other reason for it, this is sufficient, that there was no more evidence that they did believe in God than that they believed in Jesus. All the ancient versions except the Latin read it thus. The Saviour told them that their consolation was to be found at this time in confidence in God and in him; and he intimated what he had so often told them and the Jews, that there was an indissoluble union between him and the Father. This union he takes occasion to explain to them more fully, John 14:7-12.Believe in - Put confidence in, rely on for support and consolation.', NULL, NULL, '''-16'':89 ''14'':83,392 ''15'':88 ''16'':23,26 ''17'':95 ''21.ye'':265 ''22'':27 ''24'':264 ''31'':84 ''6'':24 ''7-12.believe'':393 ''adapt'':127 ''administ'':50 ''allay'':176 ''alon'':217 ''ancient'':327 ''anxieti'':159 ''bear'':153 ''beauti'':117,168 ''believ'':266,289,293,316,322 ''belov'':209 ''bring'':151 ''care'':163 ''case'':192 ''chapter'':64,138 ''christ'':150 ''circumst'':57 ''comfort'':130 ''compar'':21 ''complaint'':181 ''confid'':350,396 ''consol'':54,186,341,403 ''consolatori'':144 ''counten'':41 ''death'':241 ''deliv'':66 ''demolish'':243 ''die'':262 ''discipl'':8,195 ''discours'':61,115 ''distress'':12,33 ''doctrin'':255 ''doubtless'':67 ''either'':273 ''everi'':177,180,184 ''evid'':312 ''except'':329 ''explain'':386 ''express'':44 ''father'':379 ''fear'':178 ''felt'':238 ''fit'':174 ''found'':113,345 ''friend'':211,228 ''full'':121,157 ''fulli'':252,390 ''give'':183 ''god'':268,291,318,352 ''gospel'':172 ''great'':11 ''heart'':4 ''honor'':230 ''imper'':280,288 ''improb'':235 ''indic'':31,276 ''indissolubl'':373 ''inimit'':167 ''intim'':358 ''jesus'':15,324 ''jew'':368 ''john'':22,25,82,87,94,140,391 ''latin'':331 ''learn'':253 ''leav'':19 ''left'':216 ''let'':1 ''lord'':78 ''luke'':263 ''made'':58 ''manner'':38 ''may'':270 ''meet'':219 ''messiah'':258 ''mind'':156 ''mood'':277 ''mount'':105 ''much'':198 ''must'':259 ''need'':185 ''new'':48 ''nowher'':110 ''occas'':384 ''occur'':134 ''often'':363 ''oliv'':107 ''part'':145,206 ''partak'':75 ''perhap'':28 ''perplex'':161 ''persecut'':220 ''prayer'':92 ''probabl'':281 ''proc