INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1123', '2', '1123', NULL, 'I am the true vine - Some have supposed that this discourse was delivered in the room where the Lord''s Supper was instituted, and that, as they had made use of wine, Jesus took occasion from that to say that he was the true vine, and to intimate that his blood was the real wine that was to give strength to the soul. Others have supposed that it was delivered in the temple, the entrance to which was adorned with a golden vine (Josephus), and that Jesus took occasion thence to say that he was the true vine; but it is most probable that it was spoken while they were going from the paschal supper to the Mount of Olives. Whether it was suggested by the sight of vines by the way, or by the wine of which they had just partaken, cannot now be determined. The comparison was frequent among the Jews, for Palestine abounded in vineyards, and the illustration was very striking. Thus, the Jewish people are compared to a vine which God had planted, Isaiah 5:1-7; Psalm 80:8-16; Joel 1:7; Jeremiah 2:21; Ezekiel 19:10. When Jesus says he was the true vine, perhaps allusion is had to Jeremiah 2:21. The word "true," here, is used in the sense of real, genuine. He really and truly gives what is emblematically represented by a vine. The point of the comparison or the meaning of the figure is this: A vine yields proper juice and nourishment to all the branches, whether these are large or small. All the nourishment of each branch and tendril passes through the main stalk, or the vine, that springs from the earth. So Jesus is the source of all real strength and grace to his disciples. He is their leader and teacher, and imparts to them, as they need, grace and strength to bear the fruits of holiness.And my Father is the husbandman - The word "vine-dresser" more properly expresses the sense of the original word than husbandman. It means one who has the care of a vineyard; whose office it is to nurture, trim, and defend the vine, and who of course feels a deep interest in its growth and welfare. See the notes at Matthew 21:33. The figure means that God gave, or appointed his Son to be, the source of blessings to man; that all grace descends through him; and that God takes care of all the branches of this vine - that is, of all who are by faith united to the Lord Jesus Christ. In Jesus and all his church he feels the deepest interest, and it is an object of great solicitude that his church should receive these blessings and bear much fruit.', NULL, NULL, '''-16'':185 ''-7'':181 ''1'':180,187 ''10'':194 ''19'':193 ''2'':190,209 ''21'':191,210,382 ''33'':383 ''5'':179 ''7'':188 ''8'':184 ''80'':183 ''abound'':156 ''adorn'':79 ''allus'':204 ''among'':151 ''appoint'':391 ''bear'':317,461 ''bless'':399,459 ''blood'':51 ''branch'':258,270,416 ''cannot'':143 ''care'':349,412 ''christ'':433 ''church'':439,455 ''compar'':170 ''comparison'':148,239 ''cours'':367 ''deep'':370 ''deepest'':443 ''defend'':361 ''deliv'':13,70 ''descend'':405 ''determin'':146 ''discipl'':299 ''discours'':11 ''dresser'':331 ''earth'':285 ''emblemat'':230 ''entranc'':75 ''express'':334 ''ezekiel'':192 ''faith'':427 ''father'':323 ''feel'':368,441 ''figur'':245,385 ''frequent'':150 ''fruit'':319,463 ''gave'':389 ''genuin'':222 ''give'':59,227 ''go'':111 ''god'':175,388,410 ''golden'':82 ''grace'':296,313,404 ''great'':451 ''growth'':374 ''holiness.and'':321 ''husbandman'':326,342 ''illustr'':161 ''impart'':307 ''institut'':23 ''interest'':371,444 ''intim'':48 ''isaiah'':178 ''jeremiah'':189,208 ''jesus'':33,87,196,287,432,435 ''jew'':153 ''jewish'':167 ''joel'':186 ''josephus'':84 ''juic'':252 ''larg'':262 ''leader'':303 ''lord'':19,431 ''made'':29 ''main'':276 ''man'':401 ''matthew'':381 ''mean'':242,344,386 ''mount'':118 ''much'':462 ''need'':312 ''note'':379 ''nourish'':254,267 ''nurtur'':358 ''object'':449 ''occas'':35,89 ''offic'':354 ''oliv'':120 ''one'':345 ''origin'':339 ''other'':64 ''palestin'':155 ''partaken'':142 ''paschal'':114 ''pass'':273 ''peopl'':168 ''perhap'':203 ''plant'':177 ''point'':236 ''probabl'':103 ''proper'':251,333 ''psalm'':182 ''real'':54,221,293 ''realli'':224 ''receiv'':457 ''repres'':231 ''room'':16 ''say'':39,92,197 ''see'':377 ''sens'':219,336 ''sight'':127 ''small'':264 ''solicitud'':452 ''son'':393 ''soul'':63 ''sourc'':290,397 ''spoken'':107 ''spring'':282 ''stalk'':277 ''strength'':60,294,315 ''strike'':164 ''suggest'':124 ''supper'':21,115 ''suppos'':8,66 ''take'':411 ''teacher'':305 ''templ'':73 ''tendril'':272 ''thenc'':90 ''thus'':165 ''took'':34,88 ''trim'':359 ''true'':4,44,97,201,213 ''truli'':226 ''unit'':428 ''use'':30,216 ''vine'':5,45,83,98,129,173,202,234,249,280,330,363,419 ''vine-dress'':329 ''vineyard'':158,352 ''way'':132 ''welfar'':376 ''whether'':121,259 ''whose'':353 ''wine'':32,55,136 ''word'':212,328,340 ''yield'':250', NULL, '1012');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1124', '2', '1124', NULL, 'These things - These things which are about to happen, John 16:1-2. He had foretold them that they would take place.Ye may remember ... - By calling to mind that he had foretold these things they would perceive that he was omniscient, and would remember, also, the consolations which he had afforded them and the instructions which he had given them. Had these calamities come upon them without their having been foretold, their faith might have failed; they might have been tempted to suppose that Jesus was not aware of them, and of course that he was not the Messiah. God does not suffer his people to fall into trials without giving them sufficient warning, and without giving all the grace that is needful to bear them.At the beginning - In the early part of the ministry of Jesus. The expression these things here refers, probably, to all the topics contained in these chapters. He had, in the early part of his ministry, forewarned them of calamities and persecutions Matthew 10:16; Matthew 5:10-12; Matthew 9:15, but he had not so fully acquainted them with the nature, and design, and sources of their trials; he had not so fully apprised them of the fact, the circumstances, and the object of his death and of his ascension to heaven; he had not revealed to them so clearly that the Holy Spirit would descend, and sanctify, and guide them; and especially he had not, in one continued discourse, grouped all these things together, and placed their sorrows and consolations so fully before their minds. All these are included, it is supposed, in the expression "these things."Because I was with you - This is the reason which he gives why he had not at first made known to them clearly the certainty of their calamities and their joys; and it implies:1. that it was not needful to do it at once, as he was to be with them for more than three years, and could have abundant opportunity gradually to teach these things, and to prepare them for the more full announcement when he was about to leave them.2. that while he was with them he would go before them, and the weight of calamities would fall on him, and consequently they did not so much then need the presence and aid of the Holy Spirit as they would when he was gone.3. that his presence was to them what the presence of the Holy Spirit would be after his death, John 16:7. He could teach them all needful truth. He could console and guide them. Now that he was to leave them, he fully apprised them of what was before them, and of the descent of the Holy Spirit to do for them what he had done when with them.', NULL, NULL, '''-12'':174 ''-2'':13 ''1'':12,310 ''10'':169,173 ''15'':177 ''16'':11,170,422 ''5'':172 ''7'':423 ''9'':176 ''abund'':336 ''acquaint'':184 ''afford'':51 ''aid'':391 ''also'':45 ''announc'':351 ''appris'':201,446 ''ascens'':217 ''awar'':88 ''bear'':125 ''begin'':128 ''calam'':63,165,303,374 ''call'':26 ''certainti'':300 ''chapter'':152 ''circumst'':207 ''clear'':227,298 ''come'':64 ''consequ'':380 ''consol'':47,258,433 ''contain'':149 ''continu'':246 ''could'':334,425,432 ''cours'':93 ''death'':213,420 ''descend'':233 ''descent'':456 ''design'':190 ''discours'':247 ''done'':468 ''earli'':131,157 ''especi'':240 ''express'':139,273 ''fact'':205 ''fail'':76 ''faith'':73 ''fall'':107,376 ''first'':293 ''foretold'':16,32,71 ''forewarn'':162 ''full'':350 ''fulli'':183,200,260,445 ''give'':111,117,287 ''given'':59 ''go'':367 ''god'':100 ''gone.3'':402 ''grace'':120 ''gradual'':338 ''group'':248 ''guid'':237,435 ''happen'':9 ''heaven'':219 ''holi'':230,394,414,459 ''impli'':309 ''includ'':267 ''instruct'':55 ''jesus'':85,137 ''john'':10,421 ''joy'':306 ''known'':295 ''leav'':357,442 ''made'':294 ''matthew'':168,171,175 ''may'':23 ''messiah'':99 ''might'':74,78 ''mind'':28,263 ''ministri'':135,161 ''much'':385 ''natur'':188 ''need'':1