INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1125', '2', '1125', NULL, 'These words - The words addressed to them in the preceding chapters. They were proceeding to the garden of Gethsemane. It adds much to the interest of this prayer that it was offered in the stillness of the night, in the open air, and in the especially tender circumstances in which Jesus and his apostles were. It is the longest prayer recorded in the New Testament. It was offered on the most tender and solemn occasion that has ever occurred in our world, and it is perhaps the most sublime composition to be found anywhere. Jesus was about to die. Having expressed his love to his disciples, and made known to them his last desires, he now commends them to the protection and blessing of the God of grace. This prayer is moreover a specimen of the manner of his intercession, and evinces the interest which he felt in behalf of all who should become his followers in all ages of the world.Lifted up his eyes - This was the common attitude of prayer. Compare Luke 18:13.The hour is come - That is, the appointed time for his sufferings and death. Compare the notes at John 12:27.Glorify thy Son - Honor thy Son. See John 11:4. Give to the world demonstration that I am thy Son. So sustain me, and so manifest thy power in my death, resurrection, and ascension, as to afford indubitable evidence that I am the Son of God.That thy Son also may glorify thee - This refers clearly to the manifestation of the honor of God which would be made by the spread of the gospel among men, John 17:2. Jesus prayed that God would so honor him in his death that striking proof might be furnished that he was the Messiah, and men thus be brought to honor God. By his death the law, the truth, and the mercy of God were honored. By the spread of his gospel and the conversion of sinners; by all that Christ will do, now that he is glorified, to spread his gospel, God will be honored. The conversion of a single sinner honors God; a revival of religion is an eminent means of promoting his honor; and the spread of the gospel among all nations shall yet do more than all other things to promote the honor of God among men. Whatever honors the Saviour honors God. Just as he is exalted in view of the mind, so will God be honored and obeyed.', NULL, NULL, '''11'':204 ''12'':195 ''13.the'':176 ''17'':272 ''18'':175 ''2'':273 ''27.glorify'':196 ''4'':205 ''add'':21 ''address'':5 ''afford'':232 ''age'':159 ''air'':42 ''also'':244 ''among'':269,374,391 ''anywher'':94 ''apostl'':54 ''appoint'':183 ''ascens'':229 ''attitud'':170 ''becom'':154 ''behalf'':149 ''bless'':123 ''brought'':300 ''chapter'':11 ''christ'':332 ''circumst'':48 ''clear'':250 ''come'':179 ''commend'':117 ''common'':169 ''compar'':173,190 ''composit'':90 ''convers'':326,349 ''death'':189,226,284,306 ''demonstr'':210 ''desir'':114 ''die'':99 ''discipl'':106 ''emin'':362 ''especi'':46 ''ever'':78 ''evid'':234 ''evinc'':142 ''exalt'':403 ''express'':101 ''eye'':165 ''felt'':147 ''follow'':156 ''found'':93 ''furnish'':290 ''garden'':17 ''gethseman'':19 ''give'':206 ''glorifi'':246,339 ''god'':126,258,277,303,315,344,355,390,398,411 ''god.that'':241 ''gospel'':268,323,343,373 ''grace'':128 ''honor'':199,256,280,302,317,347,354,367,388,394,397,413 ''hour'':177 ''indubit'':233 ''intercess'':140 ''interest'':25,144 ''jesus'':51,95,274 ''john'':194,203,271 ''known'':109 ''last'':113 ''law'':308 ''longest'':59 ''love'':103 ''luke'':174 ''made'':108,262 ''manifest'':221,253 ''manner'':137 ''may'':245 ''mean'':363 ''men'':270,297,392 ''merci'':313 ''messiah'':295 ''might'':288 ''mind'':408 ''moreov'':132 ''much'':22 ''nation'':376 ''new'':64 ''night'':38 ''note'':192 ''obey'':415 ''occas'':75 ''occur'':79 ''offer'':32,68 ''open'':41 ''perhap'':86 ''power'':223 ''pray'':275 ''prayer'':28,60,130,172 ''preced'':10 ''proceed'':14 ''promot'':365,386 ''proof'':287 ''protect'