INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1136', '2', '1136', NULL, 'Then said the high priest - See the notes on Matthew 2:4. In this case the high priest seems to have presided in the council.Are these things so? - To wit, the charge alleged against him of blasphemy against Moses and the temple, Acts 6:13-14.', NULL, NULL, '''-14'':46 ''13'':45 ''2'':11 ''4'':12 ''6'':44 ''act'':43 ''alleg'':33 ''blasphemi'':37 ''case'':15 ''charg'':32 ''council.are'':25 ''high'':4,17 ''matthew'':10 ''mose'':39 ''note'':8 ''presid'':22 ''priest'':5,18 ''said'':2 ''see'':6 ''seem'':19 ''templ'':42 ''thing'':27 ''wit'':30', NULL, '1025');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1137', '2', '1137', NULL, 'And Saul was consenting ... - Was pleased with his being put to death and approved it. Compare Acts 22:20. This part of the verse should have been connected with the previous chapter.And at that time. - That is, immediately following the death of Stephen. The persecution arose on account of Stephen, Acts 11:19. The tumult did not subside when Stephen was killed. The anger of his persecutors continued to be excited against all Christians. They had become so embittered by the zeal and success of the apostles, and by their frequent charges of murder in putting the Son of God to death, that they resolved at once to put a period to their progress and success. This was the first persecution against Christians; the first in a series that terminated only when the religion which they wished to destroy was fully established on the ruins of both Judaism and paganism.The church - The collection of Christians which were now organized into a church. The church at Jerusalem was the first that was collected.All scattered - That is, the great mass of Christians.The regions of Judea ... - See the notes on Matthew 2:22.Except the apostles - Probably the other Christians fled from fear. Why the apostles, who were particularly in danger, did not flee also, is not stated by the historian. Having been, however, more fully instructed than the others, and having been taught their duty by the example and teaching of the Saviour, they resolved, it seems, to remain and brave the fury of the persecutors. For them to have fled then would have exposed them, as leaders and founders of the new religion, to the charge of timidity and weakness. They therefore resolved to remain in the midst of their persecutors; and a merciful Providence watched over them, and defended them from harm. The dispersion extended not only to Judea and Samaria, but those who fled carried the gospel also to Phenice, Cyprus, and Antioch, Acts 11:19. There was a reason why this was permitted. The early converts were Jews. They had strong feelings of attachment to the city of Jerusalem, to the temple, and to the land of their fathers. Yet it was the design of the Lord Jesus that the gospel should be preached everywhere. To accomplish this, he suffered a persecution to rage; and they were scattered abroad, and bore his gospel to other cities and lands. Good thus came out of evil; and the first persecution resulted, as all others have done, in advancing the cause which was intended to be destroyed.', NULL, NULL, '''11'':52,325 ''19'':53,326 ''2'':189 ''20'':19 ''22'':18 ''22.except'':190 ''abroad'':390 ''accomplish'':378 ''account'':48 ''act'':17,51,324 ''advanc'':417 ''also'':211,318 ''anger'':64 ''antioch'':323 ''apostl'':87,192,202 ''approv'':14 ''aros'':46 ''attach'':345 ''becom'':77 ''bore'':392 ''brave'':248 ''came'':402 ''carri'':315 ''caus'':419 ''chapter.and'':32 ''charg'':92,274 ''christian'':74,123,155,196 ''christians.the'':180 ''church'':151,162,164 ''citi'':348,397 ''collect'':153 ''collected.all'':172 ''compar'':16 ''connect'':28 ''consent'':4 ''continu'':68 ''convert'':337 ''cyprus'':321 ''danger'':207 ''death'':12,41,102 ''defend'':298 ''design'':365 ''destroy'':139,425 ''dispers'':303 ''done'':415 ''duti'':232 ''earli'':336 ''embitt'':79 ''establish'':142 ''everywher'':376 ''evil'':405 ''exampl'':235 ''excit'':71 ''expos'':262 ''extend'':304 ''father'':360 ''fear'':199 ''feel'':343 ''first'':120,125,169,408 ''fled'':197,258,314 ''flee'':210 ''follow'':39 ''founder'':267 ''frequent'':91 ''fulli'':141,222 ''furi'':250 ''god'':100 ''good'':400 ''gospel'':317,372,394 ''great'':177 ''harm'':301 ''historian'':217 ''howev'':220 ''immedi'':38 ''instruct'':223 ''intend'':422 ''jerusalem'':166,350 ''jesus'':369 ''jew'':339 ''judaism'':148 ''judea'':183,308 ''kill'':62 ''land'':357,399 ''leader'':265 ''lord'':368 ''mass'':178 ''matthew'':188 ''merci'':292 ''midst'':286 ''murder'':94 ''new'':270 ''note'':186 ''organ'':159 ''other'':226,413 ''paganism.the'':150 ''part'':21 ''particular'':205 ''period'':111 ''permit'':334 ''persecut'':45,121,383,409 ''persecutor'':67,253,289 ''phenic'':320 ''pleas'':6 ''preach'':375 ''previous'':31 ''probabl'':193 ''progress'':114 ''provid'':293 ''put'':10,96,109 ''rage'':385 ''reason'':330 ''region'':181 ''religion'':134,271 ''remain'':246,283 ''resolv'':105,242,281 ''result'':410 ''ruin'':145 ''samaria'':310 ''saul'':2 ''saviour'':240 ''scatter'':173,389 ''see'':184 ''seem'':244 ''seri'':128 ''son'':98 ''state'':214 ''stephen'':43,50,60 ''strong'':342 ''subsid'':58 ''success'':84,116 ''suffer'':381 ''taught'':230 ''teach'':237 ''templ'':353 ''termin'':130 ''therefor'':280 ''thus'':401 ''time'':35 ''timid'':276 ''tumult'':55 ''vers'':24 ''watch'':294 ''weak'':278 ''wish'':137 ''would'':260 ''yet'':361 ''zeal'':82', NULL, '1026');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1138', '2', '1138', NULL, 'And Saul - See the notes on Acts 7:58; Acts 8:3. He had been engaged be fore in persecuting the Christians, but he now sought opportunity to gratify his insatiable desire on a larger scale.Yet breathing out - Not satisfied with what he had done, Acts 8:3. The word breathing out is expressive often of any deep, agitating emotion, as we then breathe rapidly and violently. It is thus expressive of violent anger. The emotion is absorbing, agitating, exhausting, and demands a more rapid circulation of blood to supply the exhausted vitality; and this demands an increased supply of oxygen, or vital air, which leads to the increased action of the lungs. The word is often used in this sense in the Classics (Schleusner). It is a favorite expression with Homer. Euripides has the same expression: "Breathing out fire and slaughter." So Theocritus: "They came unto the assembly breathing mutual slaughter" (Idyll. 22:82).Threatening - Denunciation; threatening them with every breath the action of a man violently enraged, and who was bent on vengeance. It denotes also "intense activity and energy in persecution."Slaughter - Murder. Intensely desiring to put to death as many Christians as possible. He rejoiced in their death, and joined in condemning them, Acts 26:10-11. From this latter place it seems that he had been concerned in putting many of them to death.The disciples of the Lord - Against Christians.Went unto the high priest - See the notes on Matthew 2:4. The letters were written and signed in the name and by the authority of the Sanhedrin, or written and signed in the name and by the authority of the Sanhedrin, or Great Council of the nation. The high priest did it as president of that council. See Acts 9:14, and Acts 22:5. The high priest at that time was Theophilus, son of Ananus, who had been appointed at the feast of Pentecost, 37 a.d., by Vitellius, the Roman governor. His brother Jonathan had been removed from that office the same year (Kuinoel).', NULL, NULL, '''-11'':211 ''10'':210 ''14'':296 ''2'':245 ''22'':154,299 ''26'':209 ''3'':12,48 ''37'':321 ''4'':246 ''5'':300 ''58'':9 ''7'':8 ''8'':11,47 ''82'':155 ''9'':295 ''a.d'':322 ''absorb'':78 ''act'':7,10,46,208,294,298 ''action'':110,164 ''activ'':180 ''agit'':59,79 ''air'':104 ''also'':178 ''ananus'':311 ''anger'':74 ''appoint'':315 ''assembl'':149 ''author'':259,273 ''bent'':173 ''blood'':88 ''breath'':37,51,64,138,150,162 ''brother'':329 ''came'':146 ''christian'':22,195 ''christians.went'':235 ''circul'':86 ''classic'':124 ''concern'':222 ''condemn'':206 ''council'':279,292 ''death'':192,202 ''death.the'':229 ''deep'':58 ''demand'':82,96 ''denot'':177 ''denunci'':157 ''desir'':32,188 ''discipl'':230 ''done'':45 ''emot'':60,76 ''energi'':182 ''engag'':16 ''enrag'':169 ''euripid'':133 ''everi'':161 ''exhaust'':80,92 ''express'':54,71,130,137 ''favorit'':129 ''feast'':318 ''fire'':140 ''fore'':18 ''governor'':327 ''gratifi'':29 ''great'':278 ''high'':238,284,302 ''homer'':132 ''idyl'':153 ''increas'':98,109 ''insati'':31 ''intens'':179,187 ''join'':204 ''jonathan'':330 ''kuinoel'':340 ''larger'':35 ''latter'':214 ''lead'':106 ''letter'':248 ''lord'':233 ''lung'':113 ''man'':167 ''mani'':194,225 ''matthew'':244 ''murder'':186 ''mutual'':151 ''name'':255,269 ''nation'':282 ''note'':5,242 ''offic'':336 ''often'':55,117 ''opportun'':27 ''oxygen'':101 ''pentecost'':320 ''persecut'':20,184 ''place'':215 ''possibl'':197 ''presid'':289 ''priest'':239,285,303 ''put'':190,224 ''rapid'':65,85 ''rejoic'':199 ''remov'':333 ''roman'':326 ''sanhedrin'':262,276 ''satisfi'':40 ''saul'':2 ''scale.yet'':36 ''schleusner'':125 ''see'':3,240,293 ''seem'':217 ''sens'':121 ''sign'':252,266 ''slaughter'':142,152,185 ''son'':309 ''sought'':26 ''suppli'':90,99 ''theocritus'':144 ''theophilus'':308 ''threaten'':156,158 ''thus'':70 ''time'':306 ''unto'':147,236 ''use'':118 ''vengeanc'':175 ''violent'':67,73,168 ''vital'':93,103 ''vitellius'':324 ''word'':50,115 ''written'':250,264 ''year'':339', NULL, '1027');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1141', '2', '1141', NULL, 'Now about that time - That is, during the time that the famine existed, or the time when Barnabas and Saul went up to Jerusalem. This was probably about the fifth or sixth year of the reign of Claudius, not far from 47 ad.Herod the king - This was Herod Agrippa. The Syriac so renders it expressly, and the chronology requires us so to understand it. He was a grandson of Herod the Great, and one of the sons of Aristobulus, whom Herod put to death (Josephus, Antiq., 18, 5). Herod the Great left three sons, between whom his kingdom was divided - Archelaus, Philip, and Antipas. See the notes on Matthew 2:19. To Philip was left Iturea and Trachonitis. See Luke 3:1. To Antipas, Galilee and Perea; and to Archclaus, Judea, Idumea, and Samaria. Archclaus, being accused of cruelty, was banished by Augustus to Vienna in Gaul, and Judea was reduced to a province, and united with Syria. When Philip died, this region was granted by the Emperor Caligula to Herod Agrippa. Herod Antipas was driven as an exile also into Gaul, and then into Spain, and Herod Agrippa received also his tetrarchy. In the reign of Claudius also, the dominions of Herod Agrippa were still further enlarged. When Caligula was slain, he was at Rome, and having ingratiated himself into the favor of Claudius, he conferred on him also Judea and Samaria, so that his dominions were equal in extent to those of his grandfather, Herod the Great. See Josephus, Antiq., book 19, chapter 5, section 1.Stretched forth his hands - A figurative expression, denoting that "he laid his hands on them, or that he endeavored violently to oppress the church."To vex - To injure, to do evil to - &#x3ba;&#x3b1;&#x3ba;&#x3c9;&#x3c3;&#x3b1;&#x3b9;  kakosai.Certain - Some of the church. Who they were the writer immediately specifies.', NULL, NULL, '''1'':122 ''1.stretched'':258 ''18'':87 ''19'':111,254 ''2'':110 ''3'':121 ''47'':42 ''5'':88,256 ''accus'':137 ''ad.herod'':43 ''agrippa'':49,172,189,204 ''also'':180,191,199,230 ''antipa'':104,124,174 ''antiq'':86,252 ''archclaus'':130,135 ''archelaus'':101 ''aristobulus'':79 ''augustus'':143 ''banish'':141 ''barnaba'':18 ''book'':253 ''caligula'':169,210 ''chapter'':255 ''chronolog'':58 ''church'':281,294 ''claudius'':38,198,225 ''confer'':227 ''cruelti'':139 ''death'':84 ''denot'':265 ''die'':161 ''divid'':100 ''dominion'':201,237 ''driven'':176 ''emperor'':168 ''endeavor'':276 ''enlarg'':208 ''equal'':239 ''evil'':288 ''exil'':179 ''exist'':13 ''express'':264 ''expressli'':55 ''extent'':241 ''famin'':12 ''far'':40 ''favor'':223 ''fifth'':30 ''figur'':263 ''forth'':259 ''galile'':125 ''gaul'':147,182 ''grandfath'':246 ''grandson'':68 ''grant'':165 ''great'':72,91,249 ''hand'':261,270 ''herod'':48,70,81,89,171,173,188,203,247 ''idumea'':132 ''immedi'':300 ''ingrati'':219 ''injur'':285 ''iturea'':116 ''jerusalem'':24 ''josephus'':85,251 ''judea'':131,149,231 ''kakosai.certain'':290 ''king'':45 ''kingdom'':98 ''laid'':268 ''left'':92,115 ''luke'':120 ''matthew'':109 ''note'':107 ''one'':74 ''oppress'':279 ''perea'':127 ''philip'':102,113,160 ''probabl'':27 ''provinc'':154 ''put'':82 ''receiv'':190 ''reduc'':151 ''region'':163 ''reign'':36,196 ''render'':53 ''requir'':59 ''rome'':216 ''samaria'':134,233 ''saul'':20 ''section'':257 ''see'':105,119,250 ''sixth'':32 ''slain'':212 ''son'':77,94 ''spain'':186 ''specifi'':301 ''still'':206 ''syria'':158 ''syriac'':51 ''tetrarchi'':193 ''three'':93 ''time'':4,9,16 ''trachon'':118 ''understand'':63 ''unit'':156 ''us'':60 ''vex'':283 ''vienna'':145 ''violent'':277 ''went'':21 ''writer'':299 ''year'':33', NULL, '1030');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1142', '2', '1142', NULL, 'The church that was at Antioch - See the notes on Acts 11:20.Certain prophets - See the notes on Acts 11:27.And teachers - Teachers are several times mentioned in the New Testament as an order of ministers, 1 Corinthians 12:28-29; Ephesians 4:11; 2 Peter 2:1. Their precise rank and duty are not known. It is probable that those mentioned here as prophets were the same persons as the teachers. They might discharge both offices, predicting future events, and instructing the people.As Barnabas - Barnabas was a preacher Acts 4:35-36; Acts 9:27; Acts 11:22, Acts 11:26; and it is not improbable that the names "prophets and teachers" here simply designate the preachers of the gospel.Simeon that was called Niger - "Niger" is a Latin name meaning "black." Why the name was given is not known. Nothing more is known of him than is mentioned here.Lucius of Cyrene - Cyrene was in Africa. See the notes on Matthew 27:32. Lucius is afterward mentioned as with the apostle Paul when he wrote the Epistle to the Romans, Revelation 16:21.And Manaen - He is not mentioned elsewhere in the New Testament.Which had been brought up with Herod the tetrarch - Herod Antipas, not Herod Agrippa. Herod was tetrarch of Galilee, Luke 3:1. The word translated here as "which had been brought up," &#x3c3;&#x3c5;&#x3bd;&#x3c4;&#x3c1;&#x3bf;&#x3c6;&#x3bf;&#x3c2;  suntrophos, denotes "one who is educated or nourished at the same time with another." It is not used elsewhere in the New Testament. He might have been connected with the royal family, and, being nearly of the same age, was educated by the father of Herod Antipas with him. He was, therefore, a man of rank and education, and his conversion shows that the gospel was not confined entirely in its influence to the poor.And Saul - Saul was an apostle; and yet he is mentioned here among the "prophets and teachers," showing that these words denote "ministers of the gospel" in general, without reference to any particular order or rank.', NULL, NULL, '''-29'':41 ''-36'':93 ''1'':37,48,214 ''11'':12,20,44,98,101 ''12'':39 ''16'':182 ''2'':45,47 ''20.certain'':13 ''21.and'':183 ''22'':99 ''26'':102 ''27'':96,162 ''27.and'':21 ''28'':40 ''3'':213 ''32'':163 ''35'':92 ''4'':43,91 ''9'':95 ''act'':11,19,90,94,97,100 ''africa'':156 ''afterward'':166 ''age'':263 ''agrippa'':206 ''among'':311 ''anoth'':238 ''antioch'':6 ''antipa'':203,271 ''apostl'':171,304 ''barnaba'':85,86 ''black'':132 ''brought'':196,223 ''call'':124 ''church'':2 ''confin'':292 ''connect'':252 ''convers'':285 ''corinthian'':38 ''cyren'':152,153 ''denot'':226,320 ''design'':116 ''discharg'':75 ''duti'':53 ''educ'':230,265,282 ''elsewher'':189,243 ''entir'':293 ''ephesian'':42 ''epistl'':177 ''event'':80 ''famili'':256 ''father'':268 ''futur'':79 ''galile'':211 ''general'':326 ''given'':137 ''gospel'':289,324 ''gospel.simeon'':121 ''here.lucius'':150 ''herod'':199,202,205,207,270 ''improb'':107 ''influenc'':296 ''instruct'':82 ''known'':56,140,144 ''latin'':129 ''lucius'':164 ''luke'':212 ''man'':278 ''manaen'':184 ''matthew'':161 ''mean'':131 ''mention'':27,62,149,167,188,309 ''might'':74,249 ''minist'':36,321 ''name'':110,130,135 ''near'':259 ''new'':30,192,246 ''niger'':125,126 ''note'':9,17,159 ''noth'':141 ''nourish'':232 ''offic'':77 ''one'':227 ''order'':34,332 ''particular'':331 ''paul'':172 ''people.as'':84 ''person'':69 ''peter'':46 ''poor.and'':299 ''preacher'':89,118 ''precis'':50 ''predict'':78 ''probabl'':59 ''prophet'':14,65,111,313 ''rank'':51,280,334 ''refer'':328 ''revel'':181 ''roman'':180 ''royal'':255 ''saul'':300,301 ''see'':7,15,157 ''sever'':25 ''show'':286,316 ''simpli'':115 ''suntropho'':225 ''teacher'':22,23,72,113,315 ''testament'':31,247 ''testament.which'':193 ''tetrarch'':201,209 ''therefor'':276 ''time'':26,236 ''translat'':217 ''use'':242 ''without'':327 ''word'':2