INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1145', '2', '1145', NULL, 'Then came he - That is, Paul in company with Silas. Luke does not give us the history of Barnabas, but confines his narrative to the journey of Paul.To Derbe and Lystra - See the notes on Acts 14:6.And behold, a certain disciple named Timotheus - It was to this disciple that Paul afterward addressed the two epistles which bear his name. It is evident that he was a native of one of these places, but whether of Derbe or Lystra it is impossible to determine.The son of a certain woman ... - Her name was Eunice, 2 Timothy 1:5.And believed - And was a Christian. It is stated also that her mother was a woman of distinguished Christian piety, 2 Timothy 1:5. It was not lawful for a Jew to marry a woman of another nation, or to give his daughter in marriage to a Gentile, Ezra 9:12. But it is probable that this law was not regarded very strictly by the Jews who lived in the midst of pagan nations. It is evident that Timothy, at this time, was very young; for when Paul besought him to abide at Ephesus, to take charge of the church there 1 Timothy 1:3, he addressed him then as a young man, 1 Timothy 4:12, "Let no man despise thy youth."But his father was a Greek - Evidently, a man who had not been circumcised, for had he been Timothy would have been also.', NULL, NULL, '''1'':96,119,198,200,210 ''12'':147,213 ''14'':37 ''2'':94,117 ''3'':201 ''4'':212 ''5'':120 ''5.and'':97 ''6.and'':38 ''9'':146 ''abid'':188 ''act'':36 ''address'':53,203 ''afterward'':52 ''also'':106,242 ''anoth'':133 ''barnaba'':19 ''bear'':58 ''behold'':39 ''believ'':98 ''besought'':185 ''came'':2 ''certain'':41,88 ''charg'':193 ''christian'':102,115 ''church'':196 ''circumcis'':233 ''compani'':8 ''confin'':21 ''daughter'':139 ''derb'':29,77 ''despis'':217 ''determine.the'':84 ''discipl'':42,49 ''distinguish'':114 ''ephesus'':190 ''epistl'':56 ''eunic'':93 ''evid'':63,173,226 ''ezra'':145 ''father'':222 ''gentil'':144 ''give'':14,137 ''greek'':225 ''histori'':17 ''imposs'':82 ''jew'':127,162 ''journey'':26 ''law'':124,154 ''let'':214 ''live'':164 ''luke'':11 ''lystra'':31,79 ''man'':209,216,228 ''marri'':129 ''marriag'':141 ''midst'':167 ''mother'':109 ''name'':43,60,91 ''narrat'':23 ''nation'':134,170 ''nativ'':68 ''note'':34 ''one'':70 ''pagan'':169 ''paul'':6,51,184 ''paul.to'':28 ''pieti'':116 ''place'':73 ''probabl'':151 ''regard'':157 ''see'':32 ''sila'':10 ''son'':85 ''state'':105 ''strict'':159 ''take'':192 ''thi'':218 ''time'':178 ''timotheus'':44 ''timothi'':95,118,175,199,211,238 ''two'':55 ''us'':15 ''whether'':75 ''woman'':89,112,131 ''would'':239 ''young'':181,208 ''youth'':219', NULL, '1034');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1147', '2', '1147', NULL, 'After these things - After what occurred at Athens, as recorded in the previous chapter.Came to Corinth - Corinth was the capital of Achaia, called anciently Ephyra, and was seated on the isthmus which divides the Peloponnesus from Attica. The city itself stood on a little island; it had two ports, Lecheeum on the west, and Cenchrea on the east. It was one of the most populous and wealthy cities of Greece, and at the same time one of the most luxurious, effeminate, ostentatious, and dissolute. Lasciviousness here was not only practiced and allowed, but was consecrated by the worship of Venus; and no small part of the wealth and splendor of the city arose from the offerings made by licentious passion in the very temples of this goddess. No city of ancient times was more profligate. It was the Paris of antiquity; the seat of splendor, and show, and corruption. Yet even here, notwithstanding all the disadvantages of splendor, gaiety, and dissoluteness, Paul entered on the work of rearing a church; and here he was eminently successful. The two epistles which he afterward wrote to this church show the extent of his success; and the well-known character and propensities of the people will account for the general drift of the admonitions and arguments in those epistles. Corinth was destroyed by the Romans 146 years before Christ; and during the conflagration several metals in a fused state, running together, produced the composition known as Corinthian brass. It was afterward restored by Julius Caesar, who planted in it a Roman colony. It soon regained its ancient splendor, and relapsed into its former dissipation and licentiousness. Paul arrived there in 52 or 53 ad.', NULL, NULL, '''146'':224 ''52'':279 ''53'':281 ''account'':205 ''achaia'':22 ''ad'':282 ''admonit'':212 ''afterward'':182,249 ''allow'':92 ''ancient'':24,131,265 ''antiqu'':141 ''argument'':214 ''aros'':113 ''arriv'':276 ''athen'':8 ''attica'':37 ''brass'':246 ''caesar'':253 ''call'':23 ''capit'':20 ''cenchrea'':55 ''chapter.came'':14 ''charact'':198 ''christ'':227 ''church'':170,186 ''citi'':39,68,112,129 ''coloni'':260 ''composit'':242 ''conflagr'':231 ''consecr'':95 ''corinth'':16,17,218 ''corinthian'':245 ''corrupt'':149 ''destroy'':220 ''disadvantag'':156 ''dissip'':272 ''dissolut'':84,161 ''divid'':33 ''drift'':209 ''east'':58 ''effemin'':81 ''emin'':175 ''enter'':163 ''ephyra'':25 ''epistl'':179,217 ''even'':151 ''extent'':189 ''former'':271 ''fuse'':236 ''gaieti'':159 ''general'':208 ''goddess'':127 ''greec'':70 ''island'':45 ''isthmus'':31 ''julius'':252 ''known'':197,243 ''lascivi'':85 ''lecheeum'':50 ''licenti'':119,274 ''littl'':44 ''luxuri'':80 ''made'':117 ''metal'':233 ''notwithstand'':153 ''occur'':6 ''offer'':116 ''one'':61,76 ''ostentati'':82 ''pari'':139 ''part'':104 ''passion'':120 ''paul'':162,275 ''peloponnesus'':35 ''peopl'':203 ''plant'':255 ''popul'':65 ''port'':49 ''practic'':90 ''previous'':13 ''produc'':240 ''proflig'':135 ''propens'':200 ''rear'':168 ''record'':10 ''regain'':263 ''relaps'':268 ''restor'':250 ''roman'':223,259 ''run'':238 ''seat'':28,143 ''sever'':232 ''show'':147,187 ''small'':103 ''soon'':262 ''splendor'':109,145,158,266 ''state'':237 ''stood'':41 ''success'':176,192 ''templ'':124 ''thing'':3 ''time'':75,132 ''togeth'':239 ''two'':48,178 ''venus'':100 ''wealth'':107 ''wealthi'':67 ''well'':196 ''well-known'':195 ''west'':53 ''work'':166 ''worship'':98 ''wrote'':183 ''year'':225 ''yet'':150', NULL, '1036');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('169', '2', '169', NULL, 'The cardinal point on which the whole of the prescriptions in this chapter turn, is evidently the same as has been so often insisted on in the previous chapters, namely, the concentration of the religious services of the people round one common sanctuary. The prohibition against observing the great Feasts of Passover, Pentecost, and tabernacle, the three annual epochs in the sacred year of the Jew, at home and in private, is reiterated in a variety of words no less than six times in the first sixteen verses of this chapter Deuteronomy 16:2, Deuteronomy 16:6-7, Deuteronomy 16:11, Deuteronomy 16:15-16. Hence, it is easy to see why nothing is here said of the other holy days.The Feast of Passover Exodus 12:1-27; Numbers 9:1-14; Leviticus 23:1-8. A re-enforcement of this ordinance was the more necessary because its observance had clearly been intermitted for thirty-nine years (see Joshua 6:10). One Passover only had been kept in the wilderness, that recorded in Numbers 9, where see the notes.', NULL, NULL, '''-14'':132 ''-16'':105 ''-27'':128 ''-7'':98 ''-8'':136 ''1'':127,131,135 ''10'':163 ''11'':101 ''12'':126 ''15'':104 ''16'':93,96,100,103 ''2'':94 ''23'':134 ''6'':97,162 ''9'':130,177 ''annual'':58 ''cardin'':2 ''chapter'':13,29,91 ''clear'':152 ''common'':42 ''concentr'':32 ''days.the'':121 ''deuteronomi'':92,95,99,102 ''easi'':109 ''enforc'':140 ''epoch'':59 ''evid'':16 ''exodus'':125 ''feast'':50,122 ''first'':86 ''great'':49 ''henc'':106 ''holi'':120 ''home'':68 ''insist'':24 ''intermit'':154 ''jew'':66 ''joshua'':161 ''kept'':169 ''less'':80 ''leviticus'':133 ''name'':30 ''necessari'':147 ''nine'':158 ''note'':181 ''noth'':113 ''number'':129,176 ''observ'':47,150 ''often'':23 ''one'':41,164 ''ordin'':143 ''passov'':52,124,165 ''pentecost'':53 ''peopl'':39 ''point'':3 ''prescript'':10 ''previous'':28 ''privat'':71 ''prohibit'':45 ''re'':139 ''re-enforc'':138 ''record'':174 ''reiter'':73 ''religi'':35 ''round'':40 ''sacr'':62 ''said'':116 ''sanctuari'':43 ''see'':111,160,179 ''servic'':36 ''six'':82 ''sixteen'':87 ''tabernacl'':55 ''thirti'':157 ''thirty-nin'':156 ''three'':57 ''time'':83 ''turn'':14 ''varieti'':76 ''vers'':88 ''whole'':7 ''wilder'':172 ''word'':78 ''year'':63,159', NULL, '169');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1148', '2', '1148', NULL, 'While Apollos was at Corinth - It is probable that he remained there a considerable time.Paul, having passed through the upper coasts - The upper, or more elevated regions of Asia Minor. The writer refers here particularly to the provinces of Phrygia and Galatia, Acts 18:23. These regions were called upper, because they were situated on the high table-land in the interior of Asia Minor, while Ephesus was in the low maritime regions, and called the low country.Came to Ephesus - Agreeably to his promise, Acts 18:21.And finding certain disciples - Certain persons who had been baptized into John''s baptism, and who had embraced John''s doctrine that the Messiah was soon to appear, Acts . Acts 19:3-4. It is very clear that they had not yet heard that he had come, or that the Holy Spirit was given. They were evidently in the same situation as Apollos. See the notes on Acts 18:25.', NULL, NULL, '''-4'':120 ''18'':44,87,156 ''19'':118 ''21.and'':88 ''23'':45 ''25'':157 ''3'':119 ''act'':43,86,116,117,155 ''agreeabl'':82 ''apollo'':2,150 ''appear'':115 ''asia'':29,65 ''baptism'':101 ''baptiz'':97 ''call'':49,76 ''certain'':90,92 ''clear'':124 ''coast'':21 ''come'':134 ''consider'':14 ''corinth'':5 ''country.came'':79 ''discipl'':91 ''doctrin'':108 ''elev'':26 ''embrac'':105 ''ephesus'':68,81 ''evid'':144 ''find'':89 ''galatia'':42 ''given'':141 ''heard'':130 ''high'':57 ''holi'':138 ''interior'':63 ''john'':99,106 ''land'':60 ''low'':72,78 ''maritim'':73 ''messiah'':111 ''minor'':30,66 ''note'':153 ''particular'':35 ''pass'':17 ''person'':93 ''phrygia'':40 ''probabl'':8 ''promis'':85 ''provinc'':38 ''refer'':33 ''region'':27,47,74 ''remain'':11 ''see'':151 ''situat'':54,148 ''soon'':113 ''spirit'':139 ''tabl'':59 ''table-land'':58 ''time.paul'':15 ''upper'':20,23,50 ''writer'':32 ''yet'':129', NULL, '1037');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1149', '2', '1149', NULL, 'The uproar - The tumult excited, by Demetrius and the workmen. After it had been quieted by the town-clerk, Acts 19:40-41.Embraced them - Saluted them; gave them parting expressions of kindness. Compare the Luke 7:45 note; Romans 16:16 note; 1 Corinthians 16:20 note; 2 Corinthians 13:12 note; 1 Thessalonians 5:26 note; 1 Peter 5:14 note. The Syriac translates this, "Paul caned the disciples, and consoled them, and kissed them."To go into Macedonia - On his way to Jerusalem, agreeably to his purpose, as recorded in Acts 19:21.', NULL, NULL, '''1'':43,53,58 ''12'':51 ''13'':50 ''14'':61 ''16'':40,41,45 ''19'':22,94 ''2'':48 ''20'':46 ''21'':95 ''26'':56 ''40-41.embraced'':23 ''45'':37 ''5'':55,60 ''7'':36 ''act'':21,93 ''agreeabl'':86 ''cane'':68 ''clerk'':20 ''compar'':33 ''consol'':72 ''corinthian'':44,49 ''demetrius'':7 ''discipl'':70 ''excit'':5 ''express'':30 ''gave'':27 ''go'':78 ''jerusalem'':85 ''kind'':32 ''kiss'':75 ''luke'':35 ''macedonia'':80 ''note'':38,42,47,52,57,62 ''part'':29 ''paul'':67 ''peter'':59 ''purpos'':89 ''quiet'':15 ''record'':91 ''roman'':39 ''salut'':25 ''syriac'':64 ''thessalonian'':54 ''town'':19 ''town-clerk'':18 ''translat'':65 ''tumult'':4 ''uproar'':2 ''way'':83 ''workmen'':10', NULL, '1038');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1150', '2', '1150', NULL, 'After we were gotten from them - After we had left the elders at Miletus, Acts 20:38. They were on their way to Jerusalem.Unto Coos - This was a small island in the Grecian Archipelago, a short distance from the southwestern point of Asia Minor. It is now called "Stan-co." It was celebrated for its fertility, and for the wine and silk-worms which it produced. It was about 40 miles south of Miletus.Unto Rhodes - This was also an island in the Grecian Archipelago. On the island was a city of the same name, which was principally distinguished for its brass Colossus, which was built by Chares of Lyndus. It stood across the mouth of the harbor, and was so high that vessels could pass between its legs. It stood for 56 years, and was then thrown down by an earthquake. It was reckoned as one of the seven wonders of the world. When the Saracens took possession of this island they sold this prostrate image to a Jew, who loaded 900 camels with the brass from it. This was 600 a.d., about 900 years after it had been thrown down. The ancient name of the island was Asteria. Its name, Rhodes, was given from the great quantity of roses which it produced.Unto Patara - This was a maritime city of Lycia, in Asia Minor, over against Rhodes.', NULL, NULL, '''20'':16 ''38'':17 ''40'':72 ''56'':134 ''600'':183 ''900'':174,186 ''a.d'':184 ''across'':114 ''act'':15 ''also'':80 ''ancient'':195 ''archipelago'':34,86 ''asia'':43,225 ''asteria'':201 ''brass'':103,178 ''built'':107 ''call'':48 ''camel'':175 ''celebr'':54 ''chare'':109 ''citi'':92,221 ''co'':51 ''colossus'':104 ''coo'':25 ''could'':126 ''distanc'':37 ''distinguish'':100 ''earthquak'':143 ''elder'':12 ''fertil'':57 ''given'':206 ''gotten'':4 ''great'':209 ''grecian'':33,85 ''harbor'':119 ''high'':123 ''imag'':168 ''island'':30,82,89,163,199 ''jerusalem.unto'':24 ''jew'':