INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1177', '2', '1177', NULL, 'Let a man - Let all; let this be the estimate formed of us by each one of you.So account of us - So think of us, the apostles.As the ministers of Christ - As the servants of Christ. Let them form a true estimate of us and our office - not as the head of a faction; not as designing to form parties, but as unitedly and entirely the servants of Christ; see 1 Corinthians 3:5.And stewards - Stewards were those who presided over the affairs of a family, and made provision for it, etc.; see the note at Luke 16:1. It was an office of much responsibility; and the apostle by using the term here seems to have designed to elevate those whom he seemed to have depreciated in 1 Corinthians 3:5.Of the mysteries of God - Of the gospel; see the note at 1 Corinthians 2:7. The office of steward was to provide those things which were necessary for the use of a family. And so the office of a minister of the gospel, and a steward of its mysteries, is to dispense such instructions, guidance, counsel, etc., as may be requisite to build up the church of Christ; to make known those sublime truths which are contained in the gospel, but which had not been made known before the revelation of Jesus Christ, and which are, therefore, called "mysteries." It is implied in this verse:(1) That the office of a minister is one that is subordinate to Christ - they are his servants.(2) that those in the office should not attempt to be the head of sect or party in the church.(3) that the office is honorable as that of a steward is; and,(4) That Christians should endeavor to form and cherish just ideas of ministers; to give them their TRUE honor; but not to overrate their importance.', NULL, NULL, '''1'':71,99,129,144,238 ''16'':98 ''2'':146,256 ''3'':73,131,276 ''4'':289 ''5.and'':74 ''5.of'':132 ''7'':147 ''account'':19 ''affair'':83 ''apostl'':109 ''apostles.as'':27 ''attempt'':264 ''build'':195 ''call'':230 ''cherish'':297 ''christ'':31,36,69,200,225,251 ''christian'':291 ''church'':198,275 ''contain'':209 ''corinthian'':72,130,145 ''counsel'':188 ''depreci'':127 ''design'':57,118 ''dispens'':184 ''elev'':120 ''endeavor'':293 ''entir'':65 ''estim'':10,42 ''etc'':92,189 ''faction'':54 ''famili'':86,165 ''form'':11,39,59,295 ''give'':303 ''god'':136 ''gospel'':139,175,212 ''guidanc'':187 ''head'':51,268 ''honor'':281,307 ''idea'':299 ''impli'':234 ''import'':313 ''instruct'':186 ''jesus'':224 ''known'':203,219 ''let'':1,4,6,37 ''luke'':97 ''made'':88,218 ''make'':202 ''man'':3 ''may'':191 ''minist'':29,172,244,301 ''much'':105 ''mysteri'':134,181,231 ''necessari'':159 ''note'':95,142 ''offic'':47,103,149,169,241,261,279 ''one'':16,246 ''overr'':311 ''parti'':60,272 ''presid'':80 ''provid'':154 ''provis'':89 ''requisit'':193 ''respons'':106 ''revel'':222 ''sect'':270 ''see'':70,93,140 ''seem'':115,124 ''servant'':34,67,255 ''steward'':75,76,151,178,286 ''sublim'':205 ''subordin'':249 ''term'':113 ''therefor'':229 ''thing'':156 ''think'':23 ''true'':41,306 ''truth'':206 ''unit'':63 ''us'':13,21,25,44 ''use'':111,162 ''vers'':237 ''you.so'':18', NULL, '1066');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1189', '2', '1189', NULL, 'Now concerning the collection for the saints - The use of the article here shows that he had mentioned it to them before, and that it was a subject which they would readily understand. It was not new to them, but it was needful only to give some instructions in regard to the manner in which it should be done, and not in regard to the occasion for the collection, or the duty of making it. Accordingly, all his instructions relate simply to the manner in which the collection should be made. The word rendered "collection" (&#x3bb;&#x3bf;&#x3b3;&#x3b9;&#x3b1;  logia) does not occur anywhere else in the New Testament, and is not found in the classic writers. It is from &#x3bb;&#x3b5;&#x3b3;&#x3c9;  lego, to collect, and, undoubtedly, here refers to a contribution, or collection of money for a charitable purpose. The word "saints" (&#x3b1;&#x3b3;&#x3b9;&#x3bf;&#x3c5;&#x3c2;  hagious) here refers, doubtless, to "Christians;" to the persecuted Christians in Judea. There were many there; and they were generally poor, and exposed to various trials. In regard to the meaning of this word, and the circumstances and occasion of this collection; see the notes on Romans 15:25-26.As I have given order - (&#x3b4;&#x3b9;&#x3b5;&#x3c4;&#x3b1;&#x3be;&#x3b1;  dietaxa). As I have directed, enjoined, commanded, arranged. It does not mean that he had assumed the authority to tax them, or that he had commanded them to make a collection, but that he had left directions as to the best manner and time in which it should be done. The collection was voluntary and cheerful in all the churches Romans 15:26-27; 2 Corinthians 9:2; and Paul did not assume authority to impose it on them as a tax. Nor was it necessary. Self-denial and liberality were among the distinguishing virtues of the early Christians; and to be a Christian then implied that a man would freely impart of his property to aid the poor and the needy. The order related solely to the manner of making the collection; and as Paul had suggested one mode to the churches in Galatia, he recommended the same now to the Corinthians.To the churches of Galatia - Galatia was a province in Asia Minor. On its situation, see the note on Acts 16:6. There were evidently several churches planted in that region; see Galatians 1:2. At what time he gave this order to the churches there is not mentioned; though it was doubtless on occasion of a visit to the churches there; see Acts 16:6.', NULL, NULL, '''-27'':254 ''1'':377 ''15'':185,252 ''16'':364,408 ''2'':255,258,378 ''25-26.as'':186 ''26'':253 ''6'':365,409 ''9'':257 ''accord'':76 ''act'':363,407 ''aid'':308 ''among'':283 ''anywher'':100 ''arrang'':198 ''articl'':12 ''asia'':354 ''assum'':206,263 ''author'':208,264 ''best'':231 ''charit'':133 ''cheer'':246 ''christian'':143,147,290,295 ''church'':250,334,346,370,388,404 ''circumst'':174 ''classic'':112 ''collect'':4,69,88,95,119,128,179,221,242,324 ''command'':197,216 ''concern'':2 ''contribut'':126 ''corinthian'':256 ''corinthians.to'':344 ''denial'':279 ''dietaxa'':191 ''direct'':195,227 ''distinguish'':285 ''done'':59,240 ''doubtless'':141,396 ''duti'':72 ''earli'':289 ''els'':101 ''enjoin'':196 ''evid'':368 ''expos'':160 ''found'':109 ''freeli'':302 ''galatia'':336,348,349 ''galatian'':376 ''gave'':383 ''general'':157 ''give'':46 ''given'':189 ''hagious'':138 ''impart'':303 ''impli'':297 ''impos'':266 ''instruct'':48,79 ''judea'':149 ''left'':226 ''lego'':117 ''liber'':281 ''logia'':96 ''made'':91 ''make'':74,219,322 ''man'':300 ''mani'':152 ''manner'':53,84,232,320 ''mean'':168,202 ''mention'':18,392 ''minor'':355 ''mode'':331 ''money'':130 ''necessari'':276 ''need'':43 ''needi'':313 ''new'':37,104 ''note'':182,361 ''occas'':66,176,398 ''occur'':99 ''one'':330 ''order'':190,315,385 ''paul'':260,327 ''persecut'':146 ''plant'':371 ''poor'':158,310 ''p