INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1191', '2', '1191', NULL, 'But I determined this with myself - I made up my mind on this point; I formed this resolution in regard to my course.That I would not come again to you in heaviness - In grief (&#x3b5;&#x3bd;&#x3b7; &#x3bb;&#x3c5;&#x3c0;  ene lup). "I would not come, if I could avoid it, in circumstances which must have grieved both me and you. I would not come while there existed among you such irregularities as must have pained my heart, and as must have compelled me to resort to such acts of discipline as would be painful to you. I resolved, therefore, to endeavor to remove these evils before I came, that when I did come, my visit might be mutually agreeable to us both. For that reason I changed my purpose about visiting you, when I heard of those disorders, and resolved to send an epistle. If that should be successful, then the way would be open for an agreeable visit to you." This verse, therefore, contains the statement of the principal reason why he had not come to them as he had at first proposed. It was really from no fickleness, but it was from love to them, and a desire that his visit should be mutually agreeable, compare the notes, 2 Corinthians 1:23.', NULL, NULL, '''1'':208 ''2'':206 ''23'':209 ''act'':83 ''agreeabl'':114,153,202 ''among'':63 ''avoid'':44 ''came'':103 ''chang'':122 ''circumst'':47 ''come'':27,40,59,108,171 ''compar'':203 ''compel'':77 ''contain'':160 ''corinthian'':207 ''could'':43 ''course.that'':23 ''desir'':195 ''determin'':3 ''disciplin'':85 ''disord'':133 ''endeavor'':96 ''ene'':35 ''epistl'':139 ''evil'':100 ''exist'':62 ''fickl'':185 ''first'':178 ''form'':16 ''grief'':34 ''griev'':51 ''heard'':130 ''heart'':72 ''heavi'':32 ''irregular'':66 ''love'':190 ''lup'':36 ''made'':8 ''might'':111 ''mind'':11 ''must'':49,68,75 ''mutual'':113,201 ''note'':205 ''open'':150 ''pain'':70,89 ''point'':14 ''princip'':165 ''propos'':179 ''purpos'':124 ''realli'':182 ''reason'':120,166 ''regard'':20 ''remov'':98 ''resolut'':18 ''resolv'':93,135 ''resort'':80 ''send'':137 ''statement'':162 ''success'':144 ''therefor'':94,159 ''us'':116 ''vers'':158 ''visit'':110,126,154,198 ''way'':147 ''would'':25,38,57,87,148', NULL, '1080');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1192', '2', '1192', NULL, 'Do we begin again - This is designed evidently to meet an objection. He had been speaking of his triumph in the ministry 2 Corinthians 2:14, and of his sincerity and honesty, as contrasted with the conduct of many who corrupted the Word of God, 2 Corinthians 2:17. It might be objected that he was magnifying himself in these statements, and designed to commend himself in this manner to the Corinthians. To this he replies in the following verses.To commend ourselves? - To recommend ourselves; do we speak this in our own praise, in order to obtain your favor.Or need we, as some others - Probably some who had brought letters of recommendation to them from Judea. The false teachers at Corinth had been originally introduced there by commendatory letters from abroad. These were letters of introduction, and were common among the Greeks, the Romans, and the Jews, as they are now. They were usually given to persons who were about to travel, as there were no inns. and as travelers were dependent on the hospitality of those among whom they traveled.Of commendation from you - To other congregations. It is implied here by Paul, that he sought no such letter; that he traveled without them; and that he depended on his zeal, and self-denial, and success to make him known, and to give him the affections of those to whom he ministered - a much better recommendation than mere introductory letters. Such letters were, however, sometimes given by Christians, and are by no means improper, Acts 18:27. Yet, they do not appear to have been sought or used by the apostles generally. They depended on their miraculous endowments, and on the attending grace of God to make them known.', NULL, NULL, '''14'':26 ''17'':49 ''18'':257 ''2'':23,25,46,48 ''27'':258 ''abroad'':131 ''act'':256 ''affect'':227 ''among'':140,178 ''apostl'':272 ''appear'':263 ''attend'':283 ''begin'':3 ''better'':236 ''brought'':109 ''christian'':249 ''commend'':65,81,182 ''commendatori'':128 ''common'':139 ''conduct'':37 ''congreg'':187 ''contrast'':34 ''corinth'':121 ''corinthian'':24,47,72 ''corrupt'':41 ''denial'':215 ''depend'':172,208,275 ''design'':7,63 ''endow'':279 ''evid'':8 ''fals'':118 ''favor.or'':99 ''follow'':79 ''general'':273 ''give'':224 ''given'':155,247 ''god'':45,286 ''grace'':284 ''greek'':142 ''honesti'':32 ''hospit'':175 ''howev'':245 ''impli'':190 ''improp'':255 ''inn'':167 ''introduc'':125 ''introduct'':136 ''introductori'':240 ''jew'':147 ''judea'':116 ''known'':221,290 ''letter'':110,129,134,199,241,243 ''magnifi'':57 ''make'':219,288 ''mani'':39 ''manner'':69 ''mean'':254 ''meet'':10 ''mere'':239 ''might'':51 ''minist'':233 ''ministri'':22 ''miracul'':278 ''much'':235 ''need'':100 ''object'':12,53 ''obtain'':97 ''order'':95 ''origin'':124 ''other'':104 ''paul'':193 ''person'':157 ''prais'':93 ''probabl'':105 ''recommend'':84,112,237 ''repli'':76 ''roman'':144 ''self'':214 ''self-deni'':213 ''sincer'':30 ''sometim'':246 ''sought'':196,267 ''speak'':16,88 ''statement'':61 ''success'':217 ''teacher'':119 ''travel'':162,170,202 ''traveled.of'':181 ''triumph'':19 ''use'':269 ''usual'':154 ''verses.to'':80 ''without'':203 ''word'':43 ''yet'':259 ''zeal'':211', NULL, '1081');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1193', '2', '1193', NULL, 'Therefore - &#x394;&#x3b9;&#x3b1; &#x3c4;&#x3bf;&#x3c5;&#x3c4;&#x3bf;  Dia touto. On account of this. That is, because the light of the gospel is so clear; because it reveals so glorious truths, and all obscurity is taken away, and we are permitted to behold as in a mirror the glory of the Lord, 2 Corinthians 3:18. Since the glories of the gospel dispensation are so great, and its effects on the heart are so transforming and purifying. The object is, to show the "effect" of being entrusted with such a ministry, on the character of his preaching.Seeing we have this ministry - The gospel ministry, so much more glorious than that of Moses 2 Corinthians 3:6; which is the ministry by which the Holy Spirit acts on the hearts of people 2 Corinthians 3:8; which is the ministry of that system by which people are justified 2 Corinthians 3:9; and which is the ministry of a system so pure and unclouded, 2 Corinthians 3:9-11, 2 Corinthians 3:18.As we have received mercy - Tyndale renders this: "even as mercy is sure in us." The idea is, that it was by the mere mercy and favor of God, that he had been entrusted with the ministry, and the object of Paul is doubtless to prevent the "appearance" of arrogance and self-confidence by stating that it was to be traced entirely to God that he was put into the ministry. He doubtless had his eye on the fact that he had been a persecutor and blasphemer; and that it was by the mere favor of God that he had been converted and entrusted with the ministry, 1 Timothy 1:13. Nothing will more effectually humble a minister, and prevent his assuming any arrogant and self-confident airs, than to look over his past life; especially if his life was one of blasphemy, vice, or infidelity; and to remember that it is by the mere mercy of God that he is entrusted with the high office of an ambassador of Jesus Christ. Paul never forgot to trace his hope, his appointment to the ministerial office, and his success, to the mere grace of God.We faint not - This is one of the effects of being entrusted with such a ministry. The word used here (&#x3b5;&#x3ba;&#x3ba;&#x3b1;&#x3ba;&#x3bf;&#x3c5;&#x3bc;&#x3b5;&#x3bd;  ekkakoumen) means, properly, to turn out a coward; to lose one''s courage; then to be fainthearted, to faint, to despond, in view of trial, difficulty, etc. - Robinson. Here it means, that by the mercy of God, he was not disheartened by the difficulties which he met; his faith and zeal did not flag; he was enabled to be faithful, and laborious, and his courage always kept up, and his mind was filled with cheerfulness; see note on 2 Corinthians 2:14. He was deterred by no difficulties; embarrassed by no opposition; driven from his purpose by no persecution; and his strength did not fail under any trials. The consciousness of being entrusted with "such" a ministry animated him; and the mercy and grace of God sustained him.', NULL, NULL, '''-11'':161 ''1'':273,275 ''13'':276 ''14'':461 ''18'':49 ''18.as'':165 ''2'':46,106,125,141,157,162,458,460 ''3'':48,108,127,143,159,164 ''6'':109 ''8'':128 ''9'':144,160 ''account'':5 ''act'':119 ''air'':294 ''alway'':445 ''ambassador'':335 ''anim'':497 ''appear'':212 ''appoint'':347 ''arrog'':214,289 ''assum'':287 ''away'':30 ''behold'':36 ''blasphem'':252 ''blasphemi'':309 ''charact'':87 ''cheer'':454 ''christ'':338 ''clear'':18 ''confid'':218,293 ''conscious'':489 ''convert'':267 ''corinthian'':47,107,126,142,158,163,459 ''courag'':392,444 ''coward'':387 ''despond'':400 ''deter'':464 ''dia'':2 ''difficulti'':405,423,467 ''dishearten'':420 ''dispens'':56 ''doubtless'':208,238 ''driven'':472 ''effect'':62,77,368 ''effectu'':280 ''ekkakoumen'':380 ''embarrass'':468 ''enabl'':436 ''entir'':227 ''entrust'':80,198,269,328,371,492 ''especi'':302 ''etc'':406 ''even'':173 ''eye'':241 ''fact'':244 ''fail'':484 ''faint'':361,398