INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1195', '2', '1195', NULL, 'We then, as workers together with him - On the meaning of this expression, see the note, 1 Corinthians 3:9. The Greek here is (&#x3c3;&#x3c5;&#x3bd;&#x3b5;&#x3c1;&#x3b3;&#x3bf;&#x3c5;&#x3bd;&#x3c4;&#x3b5;&#x3c2;  sunergountes) "working together," and may mean either that the apostles and ministers to whom Paul refers were joint-laborers in entreating them not to receive the grace of God in vain; or it may mean that they cooperated with God, or were engaged with him in endeavoring to secure the reconciliation of the world to himself. Tyndale renders it: "we as helpers." Doddridge, "we then as the joint-laborers of God." Most expositors have concurred in this interpretation. The word properly means, to work together; to cooperate in producing any result. Macknight supposes that the word here is in the vocative, and is an address to the fellow-laborers of Paul, entreating them not to receive the grace of God in vain. In this opinion he is probably alone, and has manifestly departed from the scope and design of the passage. Probably the most obvious meaning is that of our translators, who regard it as teaching that Paul was a joint-worker with God in securing the salvation of people.That ye receive not the grace of God in vain - The "grace of God" here means evidently the gracious offer of reconciliation and pardon. And the sense is, "We entreat you not to neglect or slight this offer of pardon, so as to lose the benefit of it, and be lost. It is offered freely and fully. It may be partaken of by all, and all may be saved. But it may also be slighted, and all the benefits of it will then be lost." The sense is, that it was possible that this offer might be made to them, they might hear of a Saviour, be told of the plan of reconciliation and have the offers of mercy pressed on their attention and acceptance, and yet all be in vain. They might notwithstanding all this be lost, for simply to hear of the plan of salvation or the offers of mercy, will no more save a sinner than to hear of medicine will save the sick. It must be embraced and applied, or it will be in vain. It is true that Paul probably addressed this to those who were professors of religion; and the sense is, that they should use all possible care and anxiety lest these offers should have been made in vain. They should examine their own hearts; they should inquire into their own condition; they should guard against self-deception. The same persons 2 Corinthians 5:20 Paul had exhorted also to be reconciled to God; and the idea is, that he would earnestly entreat even professors of religion to give all diligence to secure an interest in the saving mercy of the gospel, and to guard against the possibility of being self-deceived and ruined.', NULL, NULL, '''1'':17 ''2'':437 ''20'':440 ''3'':19 ''5'':439 ''9'':20 ''accept'':322 ''address'':131,383 ''alon'':156 ''also'':270,444 ''anxieti'':404 ''apostl'':34 ''appli'':370 ''attent'':320 ''benefit'':243,276 ''care'':402 ''concur'':101 ''condit'':426 ''cooper'':63,113 ''corinthian'':18,438 ''deceiv'':488 ''decept'':433 ''depart'':160 ''design'':165 ''dilig'':466 ''doddridg'':88 ''earnest'':457 ''either'':31 ''embrac'':368 ''endeavor'':72 ''engag'':68 ''entreat'':46,139,227,458 ''even'':459 ''evid'':214 ''examin'':416 ''exhort'':443 ''expositor'':99 ''express'':13 ''fellow'':135 ''fellow-labor'':134 ''freeli'':252 ''fulli'':254 ''give'':464 ''god'':54,65,97,147,192,205,211,449 ''gospel'':477 ''grace'':52,145,203,209 ''gracious'':216 ''greek'':22 ''guard'':429,480 ''hear'':300,339,358 ''heart'':419 ''helper'':87 ''idea'':452 ''inquir'':422 ''interest'':470 ''interpret'':104 ''joint'':43,94,189 ''joint-labor'':42,93 ''joint-work'':188 ''labor'':44,95,136 ''lest'':405 ''lose'':241 ''lost'':248,282,335 ''macknight'':118 ''made'':295,411 ''manifest'':159 ''may'':29,59,256,264,269 ''mean'':10,30,60,108,173,213 ''medicin'':360 ''merci'':316,349,474 ''might'':293,299,330 ''minist'':36 ''must'':366 ''neglect'':231 ''note'':16 ''notwithstand'':331 ''obvious'':172 ''offer'':217,235,251,292,314,347,407 ''opinion'':152 ''pardon'':221,237 ''partaken'':258 ''passag'':168 ''paul'':39,138,185,381,441 ''people.that'':198 ''person'':436 ''plan'':308,342 ''possibl'':289,401,483 ''press'':317 ''probabl'':155,169,382 ''produc'':115 ''professor'':389,460 ''proper'':107 ''receiv'':50,143,200 ''reconcil'':447 ''reconcili'':76,219,310 ''refer'':40 ''regard'':180 ''religion'':391,462 ''render'':83 ''result'':117 ''ruin'':490 ''salvat'':196,344 ''save'':266,353,362,473 ''saviour'':303 ''scope'':163 ''secur'':74,194,468 ''see'':14 ''self'':432,487 ''self-deceiv'':486 ''self-decept'':431 ''sens'':224,284,394 ''sick'':364 ''simpli'':337 ''sinner'':355 ''slight'':233,272 ''sunergount'':25 ''suppos'':119 ''teach'':183 ''togeth'':5,27,111 ''told'':305 ''translat'':178 ''true'':379 ''tyndal'':82 ''use'':399 ''vain'':56,149,207,328,376,413 ''vocat'':127 ''word'':106,122 ''work'':26,110 ''worker'':4,190 ''world'':79 ''would'':456 ''ye'':199 ''yet'':324', NULL, '1084');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1197', '2', '1197', NULL, 'Moreover, brethren, we do you to wit - We make known to you; we inform you. The phrase "we do you to wit," is used in Tyndale''s translation, and means "we cause you to know." The purpose for which Paul informed them of the liberality of the churches of Macedonia was to excite them to similar liberality.Of the grace of God ... - The favor which God had shown them in exciting a spirit of liberality, and in enabling them to contribute to the fund for supplying the needs of the poor saints at Jerusalem. The word "grace" (&#x3c7;&#x3b1;&#x3c1;&#x3b9;&#x3c2;  charis) is sometimes used in the sense of gift, and the phrase "gift of God" some have supposed may mean very great gift, where the words "of God" may be designed to mark anything very eminent or excellent, as in the phrase "cedars of God," "mountains of God," denoting very great cedars, very great mountains. Some critics (as Macknight, Bloomfield, Locke, and others) have supposed that this means that the churches of Macedonia had been able to contribute largely to the aid of the saints of Judea. But the more obvious and correct interpretation, as I apprehend, is that which is implied in the common version, that the phrase "grace of God," means that God had bestowed on them grace to give according to their ability in this cause. According to this it is implied:(1) That a disposition to contribute to the cause of benevolence is to be traced to God. He is its author. He excites it. It is not a plant of native growth in the human heart, but a large and liberal spirit of benevolence is one of the effects of his grace, and is to be traced to him.(2) it is a favor bestowed on a church when God excites in it a spirit of benevolence. It is one of the evidences of his love. And indeed there cannot be a higher proof of the favor of God than when by his grace he inclines and enables us to contribute largely to meliorate the condition, and to alleviate the needs of our fellowmen. Perhaps the apostle here meant delicately to hint this. He did not therefore say coldly that the churches of Macedonia had contributed to this object, but he speaks of it as a favor shown to them by God that they were able to do it. And he meant, probably, gently to intimate to the Corinthians that it would be an evidence that they were enjoying the favor of God if they should contribute in like manner.The churches of Macedonia - Philippi, Thessalonica, Berea. For an account of Macedonia, see the Acts 16:9 note; Romans 15:26 note. Of these churches, that at Philippi seems to have been most distinguished for liberality Philippians 4:10, Philippians 4:15-16, Philippians 4:18, though it is probable that other churches contributed according to their ability, as they are commended (compare 2 Corinthians 9:2) without distinction.', NULL, NULL, '''-16'':473 ''1'':232 ''10'':469 ''15'':450,472 ''16'':446 ''18'':476 ''2'':291,494,497 ''26'':451 ''4'':468,471,475 ''9'':447,496 ''abil'':222,488 ''abl'':172,397 ''accord'':219,226,485 ''account'':440 ''act'':445 ''aid'':178 ''allevi'':350 ''anyth'':130 ''apostl'':358 ''apprehend'':193 ''author'':252 ''benevol'':242,275,308 ''berea'':437 ''bestow'':213,296 ''bloomfield'':156 ''brethren'':2 ''cannot'':321 ''caus'':32,225,240 ''cedar'':139,148 ''chari'':97 ''church'':48,167,299,373,432,455,483 ''cold'':370 ''commend'':492 ''common'':201 ''compar'':493 ''condit'':347 ''contribut'':80,174,237,342,377,428,484 ''corinthian'':410,495 ''correct'':189 ''critic'':153 ''delic'':361 ''denot'':145 ''design'':127 ''disposit'':235 ''distinct'':499 ''distinguish'':464 ''effect'':280 ''emin'':132 ''enabl'':77,339 ''enjoy'':420 ''evid'':314,416 ''excel'':134 ''excit'':53,70,254,302 ''favor'':63,295,328,388,422 ''fellowmen'':355 ''fund'':83 ''gentl'':405 ''gift'':105,109,119 ''give'':218 ''god'':61,65,111,124,141,144,208,211,248,301,330,393,424 ''grace'':59,96,206,216,283,335 ''great'':118,147,150 ''growth'':263 ''heart'':267 ''higher'':324 ''hint'':363 ''human'':266 ''impli'':198,231 ''inclin'':337 ''inde'':319 ''inform'':14,41 ''interpret'':190 ''intim'':407 ''jerusalem'':93 ''judea'':183 ''know'':35 ''known'':10 ''larg'':175,270,343 ''liber'':45,74,272,466 ''liberality.of'':57 ''like'':430 ''lock'':157 ''love'':317 ''macedonia'':50,169,375,434,442 ''macknight'':155 ''make'':9 ''manner.the'':431 ''mark'':129 ''may'':115,125 ''mean'':30,116,164,209 ''meant'':360,403 ''melior'':345 ''moreov'':1 ''mountain'':142,151 ''nativ'':262 ''need'':87,352 ''note'':448,452 ''object'':380 ''obvious'':187 ''one'':277,311 ''other'':159 ''paul'':40 ''perhap'':356 ''philippi'':435,458 ''philippian'':467,470,474 ''phrase'':17,108,138,205 ''plant'':260 ''poor'':90 ''probabl'':404,480 ''proof'':325 ''purpos'':37 ''roman'':449 ''saint'':91,181 ''say'':369 ''see'':443 ''seem'':459 ''sens'':103 ''shown'':67,389 ''similar'':56 ''sometim'':99 ''speak'':383 ''spirit'':72,273,306 ''suppli'':85 ''suppos'':114,161 ''therefor'':368 ''thessalonica'':436 ''though'':477 ''trace'':246,288 ''translat'':28 ''tyndal'':26 ''us'':340 ''use'':24,100 ''version'':202 ''wit'':7,22 ''without'':498 ''word'':95,122 ''would'':413', NULL, '1086');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1198', '2', '1198', NULL, 'For as touching the ministering to the saints - In regard to the collection that was to be taken up for the aid of the poor Christians in Judea; see the notes on Romans 15:26; 1 Corinthians 16:1; 2 Corinthians 8.It is superfluous ... - It is needless to urge that matter on you, because I know that you acknowledge the obligation to do it, and have already purposed it.For me to write to you - That is, to write more, or to write largely on the subject. It is unnecessary for me to urge arguments why it should be done; and all that is proper is to offer some suggestions in regard to the manner in which it shall be accomplished.', NULL, NULL, '''1'':36,39 ''15'':34 ''16'':38 ''2'':40 ''26'':35 ''8.it'':42 ''accomplish'':120 ''acknowledg'':59 ''aid'':22 ''alreadi'':67 ''argument'':94 ''christian'':26 ''collect'':13 ''corinthian'':37,41 ''done'':99 ''it.for'':69 ''judea'':28 ''know'':56 ''larg'':83 ''manner'':114 ''matter'':51 ''minist'':5 ''needless'':47 ''note'':31 ''oblig'':61 ''offer'':107 ''poor'':25 ''proper'':104 ''purpos'':68 ''regard'':10,111 ''roman'':33 ''saint'':8 ''see'':29 ''shall'':118 ''subject'':86 ''suggest'':109 ''superflu'':44 ''taken'':18 ''touch'':3 ''unnecessari'':89 ''urg'':49,93 ''write'':72,78,82', NULL, '1087');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1199', '2', '1199', NULL, 'Now I Paul myself beseech you - I entreat you who are members of the church not to give me occasion for the exercise of severity in discipline. I have just expressed my confidence in the church in general, and my belief that you will act in accordance with the rules of the gospel. But I cannot thus speak of all. There are some among you who have spoken with contempt of my authority and my claims as an apostle. Of them I cannot speak in this manner; but instead of commanding them I entreat them not to give me occasion for the exercise of discipline.By the meekness and gentleness of Christ - In view of the meekness and mildness of the Redeemer; or desiring to imitate his gentleness and kindness. Paul wished to imitate that. He did not wish to have occasion for severity. He desired at all times to imitate, and to exhibit the gentle feelings of the Saviour. He had no pleasure in severity; and he did not desire to exhibit it.Who in presence - Margin, In outward appearance. It may either mean that when present among them he appeared, according to their representation, to be humble, mild, gentle 2 Corinthians 10:10; or that in his external appearance he had this aspect; see on 2 Corinthians 10:10. Most probably it means that they had represented him, as timid when among them, and afraid to exercise discipline, however much he had threatened it.Am base among you - The word used here (&#x3c4;&#x3b1;&#x3c0;&#x3b5;&#x3b9;&#x3bd;&#x3bf;&#x3c2;  tapeinos) usually means low, humble, poor. Here it means timid, modest, the opposite of boldness. Such was formerly the meaning of the English word base. It was applied to those of low degree or rank; of humble birth; and stood opposed to those of elevated rank or dignity. Now it is commonly used to denote that which is degraded or worthless; of mean spirit; vile; and stands opposed to that which is manly and noble. But Paul did not mean to use it here in that sense. He meant to say that they regarded him as timid and afraid to execute the punishment which he had threatened, and as manifesting a spirit which was the opposite of boldness. This was doubtless a charge which they brought against him; but we are not necessarily to infer that it was true. All that it proves is, that he was modest and unobtrusive, and that they interpreted this as timidity and lack of spirit.But being absent am bold toward you - That is, in my letters; see on 2 Corinthians 10:10. This they charged him with, that he was bold enough when away from them, but that he would be tame enough when he should meet them face to face, and that they had nothing to fear from him.', NULL, NULL, '''10'':202,203,218,219,428,429 ''2'':200,216,426 ''absent'':414 ''accord'':47,191 ''act'':45 ''afraid'':235,350 ''among'':64,187,232,246 ''apostl'':79 ''appear'':179,190,209 ''appli'':279 ''aspect'':213 ''author'':73 ''away'':441 ''base'':245,276 ''belief'':41 ''beseech'':5 ''birth'':289 ''bold'':266,369,416,438 ''brought'':377 ''cannot'':56,83 ''charg'':374,432 ''christ'':111 ''church'':15,36 ''claim'':76 ''command'':91 ''common'':303 ''confid'':33 ''contempt'':70 ''corinthian'':201,217,427 ''degrad'':310 ''degre'':284 ''denot'':306 ''desir'':123,145,170 ''digniti'':299 ''disciplin'':27,238 ''discipline.by'':105 ''doubtless'':372 ''either'':182 ''elev'':296 ''english'':274 ''enough'':439,450 ''entreat'':8,94 ''execut'':352 ''exercis'':23,103,237 ''exhibit'':153,172 ''express'':31 ''extern'':208 ''face'':456,458 ''fear'':465 ''feel'':156 ''former'':269 ''general'':38 ''gentl'':109,127,155,199 ''give'':18,98 ''gospel'':53 ''howev'':239 ''humbl'':197,256,288 ''imit'':125,133,150 ''infer'':386 ''instead'':89 ''interpret'':405 ''it.am'':244 ''it.who'':173 ''kind'':129 ''lack'':410 ''letter'':423 ''low'':255,283 ''man'':324 ''manifest'':361 ''manner'':87 ''margin'':176 ''may'':181 ''mean'':183,223,254,260,271,314,331 ''meant'':340 ''meek'':107,116 ''meet'':454 ''member'':12 ''mild'':118,198 ''modest'':262,399 ''much'':240 ''necessarili'':384 ''nobl'':326 ''noth'':463 ''occas'':20,100,141 ''oppos'':292,319 ''opposit'':264,367 ''outward'':178 ''paul'':3,130,328 ''pleasur'':163 ''poor'':257 ''presenc'':175 ''present'':186 ''probabl'':221 ''prove'':394 ''punish'':354 ''rank'':286,297 ''redeem'':121 ''regard'':345 ''repres'':227 ''represent'':194 ''rule'':50 ''saviour'':159 ''say'':342 ''see'':214,424 ''sens'':338 ''sever'':25,143,165 ''speak'':58,84 ''spirit'':315,363 ''spirit.but'':412 ''spoken'':68 ''stand'':318 ''stood'':291 ''tame'':449 ''tapeino'':252 ''threaten'':243,358 ''thus'':57 ''time'':148 ''timid'':230,261,348,408 ''toward'':417 ''true'':390 ''unobtrus'':401 ''use'':250,304,333 ''usual'':253 ''view'':113 ''vile'':316 ''wish'':131,138 ''word'':249,275 ''worthless'':312 ''would'':447', NULL, '1088');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1200', '2', '1200', NULL, 'Would to God - Greek, "I would" (&#x39f;&#x3c6;&#x3b5;&#x3bb;&#x3bf;&#x3bd;  Ophelon). This expresses earnest desire, but in the Greek there is no appeal to God. The sense would be well expressed by "O that," or "I earnestly wish."Ye could bear with me - That you would bear patiently with me; that you would hear me patiently, and suffer me to speak of myself.In my folly - Folly in boasting. The idea seems to be, "I know that boasting is generally foolish, and that it is not to be indulged in. But though it is to be generally regarded as folly, yet circumstances compel me to it, and I ask your indulgence in it." It is possible also that his opponents accused him of folly in boasting so much of himself.And indeed bear with me - Margin, "Ye do bear." But the text has probably the correct rendering. It is the expression of an earnest wish that they would tolerate him a little in this. He entreats them to bear with him because he was constrained to it.', NULL, NULL, '''accus'':116 ''also'':112 ''appeal'':19 ''ask'':104 ''bear'':37,43,127,133,163 ''boast'':64,73,121 ''circumst'':97 ''compel'':98 ''constrain'':169 ''correct'':140 ''could'':36 ''desir'':11 ''earnest'':10,33,148 ''entreat'':160 ''express'':9,27,145 ''folli'':61,62,95,119 ''foolish'':76 ''general'':75,92 ''god'':3,21 ''greek'':4,15 ''hear'':50 ''himself.and'':125 ''idea'':66 ''inde'':126 ''indulg'':84,106 ''know'':71 ''littl'':156 ''margin'':130 ''much'':123 ''myself.in'':59 ''o'':29 ''ophelon'':7 ''oppon'':115 ''patient'':44,52 ''possibl'':111 ''probabl'':138 ''regard'':93 ''render'':141 ''seem'':67 ''sens'':23 ''speak'':57 ''suffer'':54 ''text'':136 ''though'':87 ''toler'':153 ''well'':26 ''wish'':34,149 ''would'':1,6,24,42,49,152 ''ye'':35,131 ''yet'':96', NULL, '1089');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1202', '2', '1202', NULL, 'This is the third time ... - see the note on 2 Corinthians 12:14. For an interesting view of this passage, see Paley''s Horae Paulinae on this Epistle, No. 11: It is evident that Paul had been to Corinth but once before this, but he had resolved to go before a second time, but had been disappointed.In the mouth of two or three witnesses ... - This was what the Law of Moses required; Deuteronomy 20:16; see the note on John 8:17; compare Matthew 18:16. But in regard to its application here, commentators are not agreed. Some suppose that Paul refers to his own epistles which he had sent to them as the two or three witnesses by which his promise to them would be made certain; that he had purposed it and promised it two or three times, and that as this was all that was required by the Law, it would certainly be established. This is the opinion of Bloomfield, Rosenmuller, Grotius, Hammond, Locke, and some others. But, with all the respect due to such great names, it seems to me that this would be trifling and childish in the extreme. Lightfoot supposes that he refers to Stephanas, Fortunatus, and Achaicus, who would be witnesses to them of his purpose; see 1 Corinthians 16:17. But the more probable opinion, it seems to me, is that of Doddridge, Macknight, and others, that he anticipated that there wound be necessity for the administration of discipline there, but that he would feel himself under obligation in administering it to adhere to the reasonable maxim of the Jewish Law. No one should be condemned or punished where there was not at least two or three witnesses to prove the offence. But where there were, discipline would be administered according to the nature of the crime.', NULL, NULL, '''1'':215 ''11'':30 ''12'':12 ''14'':13 ''16'':75,86,217 ''17'':82,218 ''18'':85 ''2'':10 ''20'':74 ''8'':81 ''accord'':299 ''achaicus'':204 ''adher'':261 ''administ'':258,298 ''administr'':245 ''agre'':97 ''anticip'':237 ''applic'':92 ''bloomfield'':163 ''certain'':128,155 ''childish'':191 ''comment'':94 ''compar'':83 ''condemn'':274 ''corinth'':39 ''corinthian'':11,216 ''crime'':305 ''deuteronomi'':73 ''disappointed.in'':57 ''disciplin'':247,295 ''doddridg'':231 ''due'':176 ''epistl'':28,106 ''establish'':157 ''evid'':33 ''extrem'':194 ''feel'':253 ''fortunatus'':202 ''go'':49 ''great'':179 ''grotius'':165 ''hammond'':166 ''hora'':24 ''interest'':16 ''jewish'':268 ''john'':80 ''law'':69,152,269 ''least'':282 ''lightfoot'':195 ''lock'':167 ''macknight'':232 ''made'':127 ''matthew'':84 ''maxim'':265 ''mose'':71 ''mouth'':59 ''name'':180 ''natur'':302 ''necess'':242 ''note'':8,78 ''oblig'':256 ''offenc'':290 ''one'':271 ''opinion'':161,223 ''other'':170,234 ''paley'':22 ''passag'':20 ''paul'':35,101 ''paulina'':25 ''probabl'':222 ''promis'':122,135 ''prove'':288 ''punish'':276 ''purpos'':132,213 ''reason'':264 ''refer'':102,199 ''regard'':89 ''requir'':72,149 ''resolv'':47 ''respect'':175 ''rosenmul'':164 ''second'':52 ''see'':6,21,76,214 ''seem'':182,225 ''sent'':110 ''stephana'':201 ''suppos'':99,196 ''third'':4 ''three'':63,117,139,285 ''time'':5,53,140 ''trifl'':189 ''two'':61,115,137,283 ''view'':17 ''wit'':64,118,208,286 ''would'':125,154,187,206,252,296 ''wound'':240', NULL, '1091');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1206', '2', '1206', NULL, 'Now I say - He had before said Galatians 3:24-25 that while they were under the Law they were in a state of minority. This sentiment he proceeds further to illustrate by showing the true condition of one who was a minor.That the heir - Any heir to an estate, or one who has a prospect of an inheritance. No matter how great is the estate; no matter how wealthy his father; no matter to how elevated a rank he may be raised on the moment that he enters on his inheritance, yet until that time he is in the condition of a servant.As long as he is a child - Until he arrives at the age. The word rendered "child" (&#x3bd;&#x3b7;&#x3c0;&#x3b9;&#x3bf;&#x3b9;  nepioi) properly means an infant; literally, "one not speaking" (&#x3bd;&#x3b7;  ne insep. un, &#x3b5;&#x3c0;&#x3bf;&#x3c2;  epos), and hence, a child or babe, but without any definite limitation - Robinson. It is used as the word "infant" is with us in law, to denote "a minor."Differeth nothing from a servant - That is, he has no more control of his property; he has it not at his command. This does not mean that he does not differ in any respect, but only that in the matter under consideration he does not differ. He differs in his prospects of inheriting the property, and in the affections of the father, and usually in the advantages of education, and in the respect and attention shown him. but in regard to property, he does not differ, and he is like a servant, under the control and direction of others.Though he be lord of all - That is, in prospect. He has a prospective right to all the property, which no one else has. The word "lord" here (&#x3ba;&#x3c5;&#x3c1;&#x3b9;&#x3bf;&#x3c2;  kurios), is used in the same sense in which it is often in the Scriptures, to denote master or owner. The idea which this is designed to illustrate is, that the condition of the Jews before the coming of the Messiah was inferior in many respects to what the condition of the friends of God would be under him - as inferior as the condition of an heir was before he was of age, to what it would be when he should enter on his inheritance. The Jews claimed, indeed, that they were the children or the sons of God, a title which the apostle would not withhold from the pious part of the nation; but it was a condition in which they had not entered on the full inheritance, and which was far inferior to that of those who had embraced the Messiah, and who were admitted to the full privileges of sonship. They were indeed heirs. They were interested in the promises. But still they were in a condition of comparative servitude, and could be made free only by the gospel.', NULL, NULL, '''-25'':11 ''24'':10 ''3'':9 ''admit'':434 ''advantag'':228 ''affect'':220 ''age'':116,360 ''apostl'':391 ''arriv'':113 ''attent'':236 ''babe'':139 ''child'':110,120,137 ''children'':381 ''claim'':375 ''come'':325 ''command'':183 ''compar'':459 ''condit'':37,101,319,337,351,406,457 ''consider'':203 ''control'':173,256 ''could'':462 ''definit'':143 ''denot'':159,304 ''design'':313 ''differ'':192,207,209,247 ''differeth'':162 ''direct'':258 ''educ'':230 ''elev'':77 ''els'':282 ''embrac'':428 ''enter'':89,369,412 ''epo'':133 ''estat'':50,66 ''far'':420 ''father'':72,223 ''free'':465 ''friend'':340 ''full'':415,437 ''galatian'':8 ''god'':342,386 ''gospel'':469 ''great'':63 ''heir'':45,47,354,444 ''henc'':135 ''idea'':309 ''illustr'':32,315 ''inde'':376,443 ''infant'':125,152 ''inferior'':330,348,421 ''inherit'':59,92,214,372,416 ''insep'':131 ''interest'':447 ''jew'':322,374 ''kurio'':288 ''law'':18,157 ''like'':251 ''limit'':144 ''liter'':126 ''long'':105 ''lord'':263,286 ''made'':464 ''mani'':332 ''master'':305 ''matter'':61,68,74,201 ''may'':81 ''mean'':123,187 ''messiah'':328,430 ''minor'':25,161 ''minor.that'':43 ''moment'':86 ''nation'':401 ''ne'':130 ''nepioi'':121 ''noth'':163 ''often'':299 ''one'':39,52,127,281 ''others.though'':260 ''owner'':307 ''part'':398 ''pious'':397 ''privileg'':438 ''proceed'':29 ''promis'':450 ''proper'':122 ''properti'':176,216,243,278 ''prospect'':56,212,269,273 ''rais'':83 ''rank'':79 ''regard'':241 ''render'':119 ''respect'':195,234,333 ''right'':274 ''robinson'':145 ''said'':7 ''say'':3 ''scriptur'':302 ''sens'':294 ''sentiment'':27 ''servant'':166,253 ''servant.as'':104 ''servitud'':460 ''show'':34 ''shown'':237 ''son'':384 ''sonship'':440 ''speak'':129 ''state'':23 ''still'':452 ''time'':96 ''titl'':388 ''true'':36 ''un'':132 ''us'':155 ''use'':148,290 ''usual'':225 ''wealthi'':70 ''withhold'':394 ''without'':141 ''word'':118,151,285 ''would'':343,364,392 ''yet'':93', NULL, '1095');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1207', '2', '1207', NULL, 'Stand fast, therefore - Be firm and unwavering. This verse properly belongs to the previous chapter, and should not have been separated from it. The sense is, that they were to be firm and unyielding in maintaining the great principles of Christian liberty. They had been freed from the bondage of rites and ceremonies; and they should by no means, and in no form, yield to them again.In the liberty ... - Compare John 8:32, John 8:36; Romans 6:18; Notes, Galatians 4:3-5.And be not entangled again - Tyndale renders this, "And wrap not yourselves again." The sense is, do not again allow such a yoke to be put on you; do not again become slaves to any rites, and customs, and habits.The yoke of bondage - Of servitude to the Jewish laws; see the note at Acts 15:10.', NULL, NULL, '''10'':138 ''15'':137 ''18'':79 ''3-5.and'':83 ''32'':73 ''36'':76 ''4'':82 ''6'':78 ''8'':72,75 ''act'':136 ''again.in'':67 ''allow'':102 ''becom'':114 ''belong'':11 ''bondag'':49,125 ''ceremoni'':53 ''chapter'':15 ''christian'':41 ''compar'':70 ''custom'':120 ''entangl'':86 ''fast'':2 ''firm'':5,32 ''form'':63 ''freed'':46 ''galatian'':81 ''great'':38 ''habits.the'':122 ''jewish'':130 ''john'':71,74 ''law'':131 ''liberti'':42,69 ''maintain'':36 ''mean'':59 ''note'':80,134 ''previous'':14 ''principl'':39 ''proper'':10 ''put'':108 ''render'':89 ''rite'':51,118 ''roman'':77 ''see'':132 ''sens'':25,97 ''separ'':21 ''servitud'':127 ''slave'':115 ''stand'':1 ''therefor'':3 ''tyndal'':88 ''unwav'':7 ''unyield'':34 ''vers'':9 ''wrap'':92 ''yield'':64 ''yoke'':105,123', NULL, '1096');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1208', '2', '1208', NULL, 'Brethren, if a man be overtaken - Margin, "Although." It is a case which the apostle supposes might happen. Christians were not perfect; and it was possible that they who were true Christians might be surprised by temptation, and fall into sin. The word rendered "be overtaken" (&#x3c0;&#x3c1;&#x3bf;&#x3bb;&#x3b7;&#x3bc;&#x3c6;&#x3b8;&#x3b7;  prolemphthe from &#x3c0;&#x3c1;&#x3bf;&#x3bb;&#x3b1;&#x3bc;&#x3b2;&#x3b1;&#x3bd;&#x3c9;  prolambano), means properly "to take before another, to anticipate" 1 Corinthians 11:21; then "to be before taken or caught"; and may here mean either that one had been formerly guilty of sin or had been recently hurried on by his passions or by temptations to commit a fault. It is probable that the latter here is the true sense, and that it means, if a man is found to be overtaken by any sin; if his passions, or if temptation get the better of him. Tyndale renders it: "If any man be fallen by chance into any fault." It refers to cases of surprise, or of sudden temptation. Christians do not commit sin deliberately, and as a part of the plan of life; but they may be surprised by sudden temptation, or urged on by impetuous or headstrong passion, as David and Peter were. Paul does not speak of the possibility of restoring one who deliberately forms the plan of sinning; he does not suppose that such a man could be a Christian, and that it would be proper to speak of restoring such a man.Ye which are spiritual - Who are under the influences of the Holy Spirit; see the note at Galatians 5:22-23. The apostle, in this verse, refers evidently to those who have fallen into some sensual indulgence Galatians 5:19-21, and says that they who have escaped these temptations, and who are under the influences of the Spirit, should recover such persons. It is a very important qualification for those who would recover others from sin, that they should not be guilty of the same sin themselves. Reformers should be holy persons; people who exercise discipline in the church should be "spiritual" men - people in whom implicit confidence may be properly reposed.Restore such an one - On the meaning of the word used here, see the note at 2 Corinthians 13:11. Here it means, not to restore him to the church after he has been excluded, but set him right, bring him back, recover him from his errors and his faults. The apostle does not say in what manner this is to be done; but it is usually to be done doubtless by affectionate admonition, by faithful instruction, and by prayer. Discipline or punishment should not be resorted to until the other methods are tried in vain; Matthew 18:15-17.In the spirit of meekness - With a kind, forbearing, and forgiving spirit; see the note at Matthew 5:5. Not with anger; not with a lordly and overbearing mind; not with a love of finding others in fault, and with a desire for inflicting the discipline of the church; not with a harsh and unforgiving temper, but with love, and gentleness, and humility, and patience, and with a readiness to forgive when wrong has been done. This is an essential qualification for restoring and recovering an offending brother. No one should attempt to rebuke or admonish another who cannot do it in the spirit of meekness; no man should engage in any way in the work of reform who has not such a temper of mind.Considering thyself ... - Remembering how liable you are yourself to err; and how much kindness and indulgence should therefore be shown to others. You are to act as if you felt it possible that you might also be overtaken with a fault; and you should act as you would wish that others should do toward you. Pliny (Epis. viii. 22) has expressed a similar sentiment in the following beautiful language. "Atque ego optimum et emendatissimum existimo, qui caeteris ita ignoscit, tanquam ipse quotidie peccet; ita peccatis abstinet, tanquam nemini ignoscat. Prolade hoc domi, hoc foris, hoc in omni vitae genere teneamus, ut nobis implacabiles simus, exorabiles istis etiam, qui dare veniam nisi sibi nesciunt." The doctrine taught by Paul is, that such is human infirmity, and such the strength of human depravity, that no one knows into what sins he may himself fall. He may be tempted to commit; the same sins which he endeavors to amend in others; he may be left to commit even worse sins. If this is the case, we should be tender while we are firm; forgiving while we set our faces against evil; prayerful while we rebuke; and compassionate when we are compelled to inflict on others the discipline of the church. Everyone who has any proper feelings, when he attempts to recover an erring brother should pray for him and for himself also; and will regard his duty as only half done, and that very imperfectly, if he does not "consider also that he himself may be tempted."', NULL, NULL, '''-21'':275 ''-23'':255 ''1'':58 ''11'':60,366 ''13'':365 ''15-17.in'':445 ''18'':444 ''19'':274 ''2'':363 ''21'':61 ''22'':254,628 ''5'':253,273,462,463 ''abstinet'':655 ''act'':595,614 ''admonish'':540 ''admonit'':420 ''affection'':419 ''also'':605,798,817 ''although'':8 ''amend'':725 ''anger'':466 ''anoth'':55,541 ''anticip'':57 ''apostl'':15,257,398 ''atqu'':639 ''attempt'':536,785 ''back'':388 ''beauti'':637 ''better'':132 ''brethren'':1 ''bring'':386 ''brother'':532,790 ''caeteri'':646 ''cannot'':543 ''case'':12,151,741 ''caught'':68 ''chanc'':144 ''christian'':19,32,158,222 ''church'':334,376,493,776 ''commit'':95,161,717,733 ''compassion'':763 ''compel'':767 ''confid'':343 ''consid'':816 ''corinthian'':59,364 ''could'':219 ''dare'':678 ''david'':190 ''deliber'':163,205 ''deprav'':700 ''desir'':486 ''disciplin'':331,427,490,773 ''doctrin'':684 ''domi'':661 ''done'':409,416,520,807 ''doubtless'':417 ''duti'':803 ''ego'':640 ''either'':73 ''emendatissimum'':643 ''endeavor'':723 ''engag'':554 ''epi'':626 