INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1209', '2', '1209', NULL, 'Paul, an apostle; - see the notes at Romans 1:1.By the will of God - see the notes at 1 Corinthians 1:1.To the saints - A name often given to Christians because they are holy; see the notes at 1 Corinthians 1:2.In Ephesus - see the introduction, sections 1 and 5.And to the faithful in Christ Jesus - This evidently refers to others than to those who were in Ephesus, and it is clear that Paul expected that this Epistle would be read by others. He gives it a general character, as if he supposed that it might be transcribed, and become the property of the church at large. It was not uncommon for him thus to give a general character to the epistles which he addressed to particular churches, and so to write that others than those to whom they were particularly directed, might feel that they were addressed to them. Thus, the First Epistle to the Corinthians was addressed to "the church of God in Corinth - with all that in every place call upon the name of Christ Jesus our Lord." The Second Epistle to the Corinthians in like manner was addressed to "the church of God which is at Corinth, with all the saints which are in all Achaia." Perhaps, in the Epistle before us, the apostle referred particularly to the churches of Asia Minor which he had not visited, but there is no reason for confining the address to them.All who are "faithful in Christ Jesus" may regard the Epistle as addressed by the Holy Spirit to them, and may feel that they are as much interested in the doctrines, promises, and duties set forth in this Epistle, as were the ancient Christians of Ephesus. The word "faithful" here is not used in the sense of "trustworthy," or in the sense of "fidelity," as it is often employed, but in the sense of "believing," or "having faith" in the Lord Jesus. The apostle addresses those who were firm in the faith - another name for true Christians. The Epistle contains great doctrines about the divine purposes and decrees in which they, as Christians, were particularly concerned; important "mysteries" Ephesians 1:9, of importance for them to understand, and which the apostle proceeds to communicate to them as such. The fact that the letter was designed to be published, shows that he was not unwilling that those high doctrines should be made known to the world at large; still they pertained particularly to the church, and they are doctrines which should be particularly addressed to the church. They are rather suited to comfort the hearts of "Christians," than to bring "sinners" to repentance. These doctrines may be addressed to the church with more prospect of securing a happy effect than to the world. In the church they will excite gratitude, and produce the hope which results from assured promises and eternal purposes; in the minds of sinners they may arouse envy, and hatred, and opposition to God.', NULL, NULL, '''1'':9,19,21,39,41,48,361 ''1.by'':10 ''1.to'':22 ''2.in'':42 ''5.and'':50 ''9'':362 ''achaia'':210 ''address'':125,148,159,192,240,254,326,424,448 ''ancient'':284 ''anoth'':334 ''apostl'':3,218,325,372 ''arous'':490 ''asia'':225 ''assur'':478 ''becom'':100 ''believ'':316 ''bring'':440 ''call'':173 ''charact'':89,119 ''christ'':55,178,247 ''christian'':30,285,338,354,437 ''church'':105,128,162,195,223,415,427,451,466 ''clear'':72 ''comfort'':433 ''communic'':375 ''concern'':357 ''confin'':238 ''contain'':341 ''corinth'':166,201 ''corinthian'':20,40,157,187 ''decre'':349 ''design'':386 ''direct'':142 ''divin'':346 ''doctrin'':272,343,399,419,445 ''duti'':275 ''effect'':459 ''employ'':310 ''envi'':491 ''ephesian'':360 ''ephesus'':43,68,287 ''epistl'':78,122,154,184,214,252,280,340 ''etern'':481 ''everi'':171 ''evid'':58 ''excit'':469 ''expect'':75 ''fact'':381 ''faith'':53,245,290,319,333 ''feel'':144,263 ''fidel'':305 ''firm'':330 ''first'':153 ''forth'':277 ''general'