INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1219', '2', '1219', NULL, 'Paul, an apostle of Jesus Christ - See the notes. at Romans 1:1By the will of God - Notes, 1 Corinthians 1:1.And Timotheus our brother - On the question as to why Paul associated others with him in his epistles, see the notes at 1 Corinthians 1:1. There was a particular reason why Timothy should be associated with him in writing this Epistle. He was a native of the region where the church was situated Acts 16:1-3, and had been with Paul when be preached there, and was doubtless well known to the church there; Acts 16:6. It is evident, however, from the manner in which Paul mentions him here, that he did not regard him as "an apostle," and did not wish the church at Colosse to consider him as such. It is not "Paul and Timothy, apostles of Jesus Christ," but "Paul, an apostle of Jesus Christ, and Timothy our brother." Paul is careful never to apply the term "apostle" to Timothy; Philippians 1:1. "Paul and Timotheus, the servants of Jesus Christ;" compare 1 Thessalonians 1:1; 2 Thessalonians 1:1. If he had regarded Timothy as an apostle, or as having apostolic authority, it is not easy to conceive why he should not have referred to him as such in these letters to the churches. Could he have failed to see that the manner in which he referred to him was adapted to produce a very important difference in file estimate in which he and Timothy would be held by the Colossians?', NULL, NULL, '''-3'':79 ''1'':12,19,21,44,46,47,78,169,170,180,182,183,186,187 ''1.and'':22 ''16'':77,99 ''1by'':13 ''2'':184 ''6'':100 ''act'':76,98 ''adapt'':239 ''apostl'':3,122,142,149,165,195 ''apostol'':199 ''appli'':162 ''associ'':33,57 ''author'':200 ''brother'':25,156 ''care'':159 ''christ'':6,145,152,178 ''church'':73,96,128,222 ''coloss'':130 ''colossian'':259 ''compar'':179 ''conceiv'':206 ''consid'':132 ''corinthian'':20,45 ''could'':223 ''differ'':245 ''doubtless'':91 ''easi'':204 ''epistl'':39,63 ''estim'':248 ''evid'':103 ''fail'':226 ''file'':247 ''god'':17 ''held'':256 ''howev'':104 ''import'':244 ''jesus'':5,144,151,177 ''known'':93 ''letter'':219 ''manner'':107,231 ''mention'':111 ''nativ'':67 ''never'':160 ''note'':9,18,42 ''other'':34 ''particular'':51 ''paul'':1,32,84,110,139,147,157,171 ''philippian'':168 ''preach'':87 ''produc'':241 ''question'':28 ''reason'':52 ''refer'':212,235 ''regard'':118,191 ''region'':70 ''roman'':11 ''see'':7,40,228 ''servant'':175 ''situat'':75 ''term'':164 ''thessalonian'':181,185 ''timotheus'':23,173 ''timothi'':54,141,154,167,192,253 ''well'':92 ''wish'':126 ''would'':254 ''write'':61', NULL, '1108');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1211', '2', '1211', NULL, 'For this cause - On account of preaching this doctrine; that is, the doctrine that the gospel was to be proclaimed to the Gentiles.I Paul, the prisoner of Jesus Christ - A prisoner in the service of the Lord Jesus; or made a prisoner in his cause. Not a prisoner for crime or debt, or as a captive in war, but a captive in the service of the Redeemer. This proves that at the time of writing this, Paul was in bonds, and there can he no question that he was in Rome. This would be more correctly rendered, "For this cause I, Paul, am the prisoner," etc. So Tyndale renders it, "For this cause I, Paul, the servant of Jesus, am in bonds." So also Locke, Rosenmuller, Doddridge, Whitby, Koppe, and others understand it. By this construction the abruptness now manifest in our common version is avoided.For you Gentiles - Made a prisoner at Rome on your behalf, because I maintained that the gospel was to be preached to the Gentiles; see Acts 22:21-23. He was taken first to Cesarea, and then to Rome. The cause of his imprisonment and of all his difficulties was, that he maintained that the gospel was to be preached to the Gentiles; that when the Jews rejected it God rejected them; and that he was specially called to carry the message of salvation to the pagan world.', NULL, NULL, '''-23'':174 ''21'':173 ''22'':172 ''abrupt'':138 ''account'':5 ''act'':171 ''also'':124 ''avoided.for'':146 ''behalf'':156 ''bond'':80,122 ''call'':223 ''captiv'':56,61 ''carri'':225 ''caus'':3,45,100,113,186 ''cesarea'':180 ''christ'':29 ''common'':143 ''construct'':136 ''correct'':96 ''crime'':50 ''debt'':52 ''difficulti'':194 ''doctrin'':9,13 ''doddridg'':127 ''etc'':106 ''first'':178 ''gentil'':148,169,208 ''gentiles.i'':23 ''god'':215 ''gospel'':16,162,201 ''imprison'':189 ''jesus'':28,38,119 ''jew'':212 ''kopp'':129 ''lock'':125 ''lord'':37 ''made'':40,149 ''maintain'':159,198 ''manifest'':140 ''messag'':227 ''other'':131 ''pagan'':232 ''paul'':24,77,102,115 ''preach'':7,166,205 ''prison'':26,31,42,48,105,151 ''proclaim'':20 ''prove'':69 ''question'':86 ''redeem'':67 ''reject'':213,216 ''render'':97,109 ''rome'':91,153,184 ''rosenmul'':126 ''salvat'':229 ''see'':170 ''servant'':117 ''servic'':34,64 ''special'':222 ''taken'':177 ''time'':73 ''tyndal'':108 ''understand'':132 ''version'':144 ''war'':58 ''whitbi'':128 ''world'':233 ''would'':93 ''write'':75', NULL, '1100');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1213', '2', '1213', NULL, 'Be ye therefore followers of God - Greek, "Be imitators - &#x3bc;&#x3b9;&#x3bc;&#x3b7;&#x3c4;&#x3b1;&#x3b9;  mimetai - of God." The idea is not that they were to be the friends of God, or numbered among his followers, but that they were to imitate him in the particular thing under consideration. The word "therefore" - &#x3bf;&#x3c5;&#x3bd;  oun - connects this with the previous chapter, where he had been exhorting them to kindness, and to a spirit of forgiveness, and he here entreats them to imitate God, who was always kind and ready to forgive; compare Matthew 5:44-47; As he forgives us Ephesians 4:32, we should be ready to forgive others; as he has borne with our faults, we should bear with theirs; as he is ever ready to hear our cry when we ask for mercy, we should be ready to hear others when they desire to be forgiven; and as he is never weary with doing us good, we should never be weary in benefiting them.As dear children - The meaning is, "as those children which are beloved follow the example of a father, so we, who are beloved of God, should follow his example." What a simple rule this is! And how much contention and strife would be avoided if it were followed! If every Christian who is angry, unforgiving, and unkind, would just ask himself the question, "How does God treat me?" it would save all the trouble and heart-burning which ever exists in the church.', NULL, NULL, '''-47'':88 ''32'':95 ''4'':94 ''44'':87 ''5'':86 ''alway'':78 ''among'':28 ''angri'':212 ''ask'':126,218 ''avoid'':202 ''bear'':112 ''belov'':170,181 ''benefit'':158 ''born'':106 ''burn'':236 ''chapter'':53 ''children'':161,167 ''christian'':209 ''church'':242 ''compar'':84 ''connect'':48 ''consider'':43 ''content'':197 ''cri'':123 ''dear'':160 ''desir'':138 ''entreat'':71 ''ephesian'':93 ''ever'':118,238 ''everi'':208 ''exampl'':173,187 ''exhort'':58 ''exist'':239 ''father'':176 ''fault'':109 ''follow'':4,30,171,185,206 ''forgiv'':67,83,91,101 ''forgiven'':141 ''friend'':23 ''god'':6,12,25,75,183,224 ''good'':151 ''greek'':7 ''hear'':121,134 ''heart'':235 ''heart-burn'':234 ''idea'':14 ''imit'':9,36,74 ''kind'':61,79 ''matthew'':85 ''mean'':163 ''merci'':128 ''mimetai'':10 ''much'':196 ''never'':146,154 ''number'':27 ''other'':102,135 ''oun'':47 ''particular'':40 ''previous'':52 ''question'':221 ''readi'':81,99,119,132 ''rule'':191 ''save'':229 ''simpl'':190 ''spirit'':65 ''strife'':199 ''them.as'':159 ''therefor'':3,46 ''thing'':41 ''treat'':225 ''troubl'':232 ''unforgiv'':213 ''unkind'':215 ''us'':92,150 ''weari'':147,156 ''word'':45 ''would'':200,216,228 ''ye'':2', NULL, '1102');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1218', '2', '1218', NULL, 'Therefore, my brethren dearly beloved and longed for - Doddridge unites this verse with the previous chapter, and supposes that it is the proper close of the solemn statement which the apostle makes there. The word "therefore" - &#x3c9;&#x3c3;&#x3c4;&#x3b5;  hoste - has undoubted reference to the remarks made there; and the meaning is, that in view of the fact that there were many professed Christians who were not sincere - that the "citizenship" of all true Christians was in heaven, and that Christians looked for the coming of the Lord Jesus, who would make them like to himself, the apostle exhorts them to stand fast in the Lord. The accumulation of epithets of endearment in this verse shows his tender regard for them, and is expressive of his earnest solicitude for their welfare, and his deep conviction of their danger. The term "longed for" is expressive of strong affection; see Philippians 1:8, and Philippians 2:26.My joy - The source of my joy. He rejoiced in the fact that they had been converted under him; and in their holy walk, and their friendship. Our chief joy is in our friends; and the chief happiness of a minister of the gospel is in the pure lives of those to whom he ministers; see 3 John 1:4.And crown - Compare 1 Thessalonians 2:19. The word "crown" means a circlet, chaplet, or diadem:(1) as the emblem of royal dignity - the symbol of office;(2) as the prize conferred on victors in the public games, 1 Corinthians 9:25, and hence, as an emblem of the rewards of a future life; 2 Timothy 4:8; James 1:12; 1 Peter 5:4;(3) anything that is an ornament or honor, as one glories in a crown; compare Proverbs 12:4, "A virtuous woman is a crown to her husband;" Proverbs 14:24, "The crown of the wise is their riches;" Proverbs 16:31, "The hoary head is a crown of glory;" Proverbs 17:6, "Children''s children are the crown of old men."The idea here is, that the church at Philippi was that in which the apostle gloried. He regarded it as a high honor to have been the means of founding such a church, and he looked upon it with the same interest with which a monarch looks upon the diadem which he wears.So stand fast in the Lord - In the service of the Lord, and in the strength which he imparts; see the notes at Ephesians 6:13-14.', NULL, NULL, '''-14'':415 ''1'':147,210,214,227,249,270,272 ''12'':271,292 ''13'':414 ''14'':304 ''16'':315 ''17'':326 ''19'':217 ''2'':151,216,238,265 ''24'':305 ''25'':252 ''26.my'':152 ''3'':208,276 ''31'':316 ''4'':267,275,293 ''4.and'':211 ''5'':274 ''6'':327,413 ''8'':148,268 ''9'':251 ''accumul'':105 ''affect'':144 ''anyth'':277 ''apostl'':31,95,351 ''belov'':5 ''brethren'':3 ''chaplet'':224 ''chapter'':16 ''chief'':180,188 ''children'':328,330 ''christian'':61,72,78 ''church'':343,369 ''circlet'':223 ''citizenship'':68 ''close'':24 ''come'':82 ''compar'':213,290 ''confer'':242 ''convert'':168 ''convict'':132 ''corinthian'':250 ''crown'':212,220,289,299,307,322,333 ''danger'':135 ''dear'':4 ''deep'':131 ''diadem'':226,386 ''digniti'':233 ''doddridg'':9 ''earnest'':124 ''emblem'':230,257 ''endear'':109 ''ephesian'':412 ''epithet'':107 ''exhort'':96 ''express'':121,141 ''fact'':55,163 ''fast'':100,391 ''found'':366 ''friend'':185 ''friendship'':178 ''futur'':263 ''game'':248 ''glori'':286,324,352 ''gospel'':195 ''happi'':189 ''head'':319 ''heaven'':75 ''henc'':254 ''high'':358 ''hoari'':318 ''holi'':174 ''honor'':283,359 ''host'':37 ''husband'':302 ''idea'':338 ''impart'':407 ''interest'':378 ''jame'':269 ''jesus'':86 ''john'':209 ''joy'':153,158,181 ''life'':264 ''like'':91 ''live'':200 ''long'':7,138 ''look'':79,372,383 ''lord'':85,103,394,400 ''made'':44 ''make'':32,89 ''mani'':59 ''mean'':48,221,364 ''men'':336 ''minist'':192,206 ''monarch'':382 ''note'':410 ''offic'':237 ''old'':335 ''one'':285 ''ornament'':281 ''peter'':273 ''philip