INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('154', '2', '154', NULL, 'These verses are prefixed as a connecting link between the contents of the preceding books and that of Deuteronomy now to follow. The sense of the passage might be given thus: "The discourses of Moses to the people up to the eleventh month of the fortieth year" (compare Deuteronomy 1:3) "have now been recorded." The proper names which follow seem to belong to places where "words" of remarkable importance were spoken. They are by the Jewish commentators referred to the spots which witnessed the more special sins of the people, and the mention of them here is construed as a pregnant rebuke. The Book of Deuteronomy is known among the Jews as "the book of reproofs."On this side of Jordan - Rather, "beyond Jordan" (as in Deuteronomy 3:20, Deuteronomy 3:25). The phrase was a standing designation for the district east of Jordan, and at times, when Greek became commonly spoken in the country, was exactly represented by the proper name Peraea.In the wilderness, in the plain - The former term denotes the Desert of Arabia generally; the latter was the sterile tract (''Arabah,'' Numbers 21:4  note) which stretches along the lower Jordan to the Dead Sea, and is continued thence to the Gulf of Akaba.Over against the Red Sea - Render it: "over against Suph." "Sea" is not in the original text. "Suph" is either the pass Es Sufah near Ain-el-Weibeh (Numbers 13:26 note), or the name of the alluvial district (the Numbers 21:14 note).Tophel is identified with Tufileh, the Tafyle of Burckhardt, still a considerable place - some little distance southeast of the Dead Sea. Paran is probably "Mount Paran" Deuteronomy 33:2; or a city of the same name near the mountain. Compare Genesis 14:6.Laban is generally identified with Libnah Numbers 33:20, and Hazeroth with Ain Hadherah (Numbers 11:34 note); but the position of Dizahab is uncertain.', NULL, NULL, '''1'':50 ''11'':310 ''13'':238 ''14'':251,294 ''2'':281 ''20'':130,303 ''21'':187,250 ''25'':133 ''26'':239 ''3'':51,129,132 ''33'':280,302 ''34'':311 ''4'':188 ''6.laban'':295 ''ain'':234,307 ''ain-el-weibeh'':233 ''akaba.over'':208 ''alluvi'':246 ''along'':192 ''among'':110 ''arabah'':185 ''arabia'':177 ''becam'':151 ''belong'':63 ''beyond'':124 ''book'':15,105,115 ''burckhardt'':261 ''citi'':284 ''comment'':78 ''common'':152 ''compar'':48,292 ''connect'':7 ''consider'':264 ''constru'':99 ''content'':11 ''continu'':202 ''countri'':156 ''dead'':198,272 ''denot'':173 ''desert'':175 ''design'':139 ''deuteronomi'':19,49,107,128,131,279 ''discours'':33 ''distanc'':268 ''district'':142,247 ''dizahab'':317 ''east'':143 ''either'':227 ''el'':235 ''eleventh'':42 ''es'':230 ''exact'':158 ''follow'':22,60 ''former'':171 ''fortieth'':46 ''general'':178,297 ''genesi'':293 ''given'':30 ''greek'':150 ''gulf'':206 ''hadherah'':308 ''hazeroth'':305 ''identifi'':255,298 ''import'':70 ''jew'':112 ''jewish'':77 ''jordan'':122,125,145,195 ''known'':109 ''latter'':180 ''libnah'':300 ''link'':8 ''littl'':267 ''lower'':194 ''mention'':94 ''might'':28 ''month'':43 ''mose'':35 ''mount'':277 ''mountain'':291 ''name'':58,163,243,288 ''near'':232,289 ''note'':189,240,252,312 ''number'':186,237,249,301,309 ''origin'':223 ''paran'':274,278 ''pass'':229 ''passag'':27 ''peopl'':38,91 ''peraea.in'':164 ''phrase'':135 ''place'':65,265 ''plain'':169 ''posit'':315 ''preced'':14 ''prefix'':4 ''pregnant'':102 ''probabl'':276 ''proper'':57,162 ''rather'':123 ''rebuk'':103 ''record'':55 ''red'':211 ''refer'':79 ''remark'':69 ''render'':213 ''repres'':159 ''reproof'':117 ''sea'':199,212,218,273 ''seem'':61 ''sens'':24 ''side'':120 ''sin'':88 ''southeast'':269 ''special'':87 ''spoken'':72,153 ''spot'':82 ''stand'':138 ''steril'':183 ''still'':262 ''stretch'':191 ''sufah'':231 ''suph'':217,225 ''tafyl'':259 ''term'':172 ''text'':224 ''thenc'':203 ''thus'':31 ''time'':148 ''tophel'':253 ''tract'':184 ''tufileh'':257 ''uncertain'':319 ''vers'':2 ''weibeh'':236 ''wilder'':166 ''wit'':84 ''word'':67 ''year'':47', NULL, '154');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('155', '2', '155', NULL, 'Deuteronomy 2:1 seems to refer in general terms to the long years of wandering, the details of which were not for Moses'' present purpose. The command of Deuteronomy 2:2-3 relates to their journey from Kadesh to Mount Hor Numbers 20:22; Numbers 33:37, and directs their march around to the southern extremity of Mount Seir, so as to "compass the land of Edom" Judges 11:18; Numbers 21:4, and so northward toward the Arnon, i. e., "by the way of the wilderness of Moab," Deuteronomy 2:8. This circuitous path was followed because of the refusal of the Edomites to allow the people to pass through their territory.', NULL, NULL, '''-3'':32 ''1'':3 ''11'':69 ''18'':70 ''2'':2,30,31,91 ''20'':43 ''21'':72 ''22'':44 ''33'':46 ''37'':47 ''4'':73 ''8'':92 ''allow'':106 ''arnon'':79 ''around'':52 ''circuit'':94 ''command'':27 ''compass'':63 ''detail'':17 ''deuteronomi'':1,29,90 ''direct'':49 ''e'':81 ''edom'':67 ''edomit'':104 ''extrem'':56 ''follow'':97 ''general'':8 ''hor'':41 ''journey'':36 ''judg'':68 ''kadesh'':38 ''land'':65 ''long'':12 ''march'':51 ''moab'':89 ''mose'':23 ''mount'':40,58 ''northward'':76 ''number'':42,45,71 ''pass'':110 ''path'':95 ''peopl'':108 ''present'':24 ''purpos'':25 ''refer'':6 ''refus'':101 ''relat'':33 ''seem'':4 ''seir'':59 ''southern'':55 ''term'':9 ''territori'':113 ''toward'':77 ''wander'':15 ''way'':84 ''wilder'':87 ''year'':13', NULL, '155');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('156', '2', '156', NULL, 'Threescore cities - Probably the cities of Jair in Bashan described in Deuteronomy 3:14 as Bashan-havoth-jair.All the region of Argob - The Hebrew word here rendered "region," means literally "rope" or "cable"; and though undoubtedly used elsewhere in a general topographical sense for portion or district (e. g. Joshua 17:5), has a special propriety in reference to Argob (mod. Lejah). The name Argob means "stone-heap," and is paraphrased by the Targums, Trachonitis Luke 3:1, or "the rough country;" titles designating the more striking features of the district. Its borders are compared to a rugged shore-line; hence, its description in the text as "the girdle of the stony country," would seem especially appropriate. (Others identify Argob with the east quarter of the Hauran.)', NULL, NULL, '''1'':77 ''14'':14 ''17'':49 ''3'':13,76 ''5'':50 ''appropri'':117 ''argob'':20,58,63,120 ''bashan'':9 ''bashan-havoth-jair.all'':16 ''border'':92 ''cabl'':31 ''citi'':2,5 ''compar'':94 ''countri'':81,113 ''describ'':10 ''descript'':103 ''design'':83 ''deuteronomi'':12 ''district'':45,90 ''e'':46 ''east'':123 ''elsewher'':36 ''especi'':116 ''featur'':87 ''g'':47 ''general'':39 ''girdl'':109 ''hauran'':127 ''heap'':67 ''hebrew'':22 ''henc'':101 ''identifi'':119 ''jair'':7 ''joshua'':48 ''lejah'':60 ''line'':100 ''liter'':28 ''luke'':75 ''mean'':27,64 ''mod'':59 ''name'':62 ''other'':118 ''paraphras'':70 ''portion'':43 ''probabl'':3 ''proprieti'':54 ''quarter'':124 ''refer'':56 ''region'':18,26 ''render'':25 ''rope'':29 ''rough'':80 ''rug'':97 ''seem'':115 ''sens'':41 ''shore'':99 ''shore-lin'':98 ''special'':53 ''stone'':66 ''stone-heap'':65 ''stoni'':112 ''strike'':86 ''targum'':73 ''text'':106 ''though'':33 ''threescor'':1 ''titl'':82 ''topograph'':40 ''trachon'':74 ''undoubt'':34 ''use'':35 ''word'':23 ''would'':114', NULL, '156');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('157', '2', '157', NULL, 'The general entreaty contained in this chapter is pointed by special mention and enforcement of the fundamental principles of the whole covenant Deuteronomy 4:9-40, the spiritual nature of the Deity, His exclusive right to their allegiance, His abhorrence of idolatry in every form, His choice of them for His elect people. Compare further Moses'' third and last address, Deuteronomy 27-30.', NULL, NULL, '''-30'':63 ''-40'':26 ''27'':62 ''4'':24 ''9'':25 ''abhorr'':40 ''address'':60 ''allegi'':38 ''chapter'':7 ''choic'':47 ''compar'':54 ''contain'':4 ''coven'':22 ''deiti'':32 ''deuteronomi'':23,61 ''elect'':52 ''enforc'':14 ''entreati'':3 ''everi'':44 ''exclus'':34 ''form'':45 ''fundament'':17 ''general'':2 ''idolatri'':42 ''last'':59 ''mention'':12 ''mose'':56 ''natur'':29 ''peopl'':53 ''point'':9 ''principl'':18 ''right'':35 ''special'':11 ''spiritu'':28 ''third'':57 ''whole'':21', NULL, '157');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('158', '2', '158', NULL, 'The "fathers" are, as in Deuteronomy 4:37, the patriarchs, Abraham, Isaac, and Jacob. With them God did indeed make a covenant, but not the particular covenant now in question. The responsibilites of this later covenant, made at Sinai by the nation as a nation, attached in their day and generation to those whom Moses was addressing.', NULL, NULL, '''37'':8 ''4'':7 ''abraham'':11 ''address'':57 ''attach'':46 ''coven'':22,27,36 ''day'':49 ''deuteronomi'':6 ''father'':2 ''generat'':51 ''god'':17 ''inde'':19 ''isaac'':12 ''jacob'':14 ''later'':35 ''made'':37 ''make'':20 ''mose'':55 ''nation'':42,45 ''particular'':26 ''patriarch'':10 ''question'':30 ''responsibilit'':32 ''sinai'':39', NULL, '158');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('159', '2', '159', NULL, 'Moses proceeds to set forth more particularly and to enforce the cardinal and essential doctrines of the Decalogue, the nature and attributes of God, and the fitting mode of honoring and worshipping Him. Two objects are indicated Deuteronomy 6:2-3, the glory of God and the welfare of man, as the grand aims that he has in view.', NULL, NULL, '''-3'':41 ''2'':40 ''6'':39 ''aim'':54 ''attribut'':22 ''cardin'':12 ''decalogu'':18 ''deuteronomi'':38 ''doctrin'':15 ''enforc'':10 ''essenti'':14 ''fit'':27 ''forth'':5 ''glori'':43 ''god'':24,45 ''grand'':53 ''honor'':30 ''indic'':37 ''man'':50 ''mode'':28 ''mose'':1 ''natur'':20 ''object'':35 ''particular'':7 ''proceed'':2 ''set'':4 ''two'':34 ''view'':59 ''welfar'':48 ''worship'':32', NULL, '159');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('160', '2', '160', NULL, 'Their groves - Render, their idols of wood: the reference is to the wooden trunk used as a representation of Ashtaroth; see Deuteronomy 7:13 and Exodus 34:13 note.', NULL, NULL, '''13'':24,28 ''34'':27 ''7'':23 ''ashtaroth'':20 ''deuteronomi'':22 ''exodus'':26 ''grove'':2 ''idol'':5 ''note'':29 ''refer'':9 ''render'':3 ''represent'':18 ''see'':21 ''trunk'':14 ''use'':15 ''wood'':7 ''wooden'':13', NULL, '160');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('161', '2', '161', NULL, 'But by every word that proceedeth out of the mouth of the Lord - literally, "every outgoing of the mouth of the Lord." Compare Deuteronomy 29:5-6. The term "word" is inserted by the King James Version after the Septuagint, which is followed by Matthew and Luke (see the marginal references). On the means of subsistence available to the people during the wandering, see Numbers 20:1 note. The lesson was taught, that it is not nature which nourishes man, but God the Creator by and through nature: and generally that God is not tied to the particular channels ("bread only," i. e. the ordinary means of earthly sustenance) through which He is usually pleased to work.', NULL, NULL, '''-6'':27 ''1'':67 ''20'':66 ''29'':25 ''5'':26 ''avail'':57 ''bread'':100 ''channel'':99 ''compar'':23 ''creator'':84 ''deuteronomi'':24 ''e'':103 ''earth'':108 ''everi'':3,15 ''follow'':43 ''general'':90 ''god'':82,92 ''insert'':32 ''jame'':36 ''king'':35 ''lesson'':70 ''liter'':14 ''lord'':13,22 ''luke'':47 ''man'':80 ''margin'':50 ''matthew'':45 ''mean'':54,106 ''mouth'':10,19 ''natur'':77,88 ''note'':68 ''nourish'':79 ''number'':65 ''ordinari'':105 ''outgo'':16 ''particular'':98 ''peopl'':60 ''pleas'':115 ''proceedeth'':6 ''refer'':51 ''see'':48,64 ''septuagint'':40 ''subsist'':56 ''susten'':109 ''taught'':72 ''term'':29 ''tie'':95 ''usual'':114 ''version'':37 ''wander'':63 ''word'':4,30 ''work'':117', NULL, '161');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('162', '2', '162', NULL, 'The lesson of this chapter is exactly that of Ephesians 2:8, "By grace are ye saved through faith; and that not of yourselves; it is the gift of God: not of works, lest any man should boast."In referring to their various rebellions, Moses here, as elsewhere, has regard not so much for the order of time as to that of subject. (Compare Deuteronomy 1:9-15 note.) Such reasons as convenience and fitness to his argument sufficiently explain the variations observable when the statements of this chapter are minutely compared with those of Exodus 32-34. In these variations we have simply such treatment of facts as is usual and warrantable between parties personally acquainted with the matters.', NULL, NULL, '''-15'':68 ''-34'':98 ''1'':66 ''2'':11 ''32'':97 ''8'':12 ''9'':67 ''acquaint'':117 ''argument'':78 ''boast'':38 ''chapter'':5,89 ''compar'':64,92 ''conveni'':73 ''deuteronomi'':65 ''elsewher'':48 ''ephesian'':10 ''exact'':7 ''exodus'':96 ''explain'':80 ''fact'':108 ''faith'':19 ''fit'':75 ''gift'':28 ''god'':30 ''grace'':14 ''lesson'':2 ''lest'':34 ''man'':36 ''matter'':120 ''minut'':91 ''mose'':45 ''much'':53 ''note'':69 ''observ'':83 ''order'':56 ''parti'':115 ''person'':116 ''reason'':71 ''rebellion'':44 ''refer'':40 ''regard'':50 ''save'':17 ''simpli'':104 ''statement'':86 ''subject'':63 ''suffici'':79 ''time'':58 ''treatment'':106 ''usual'':111 ''variat'':82,101 ''various'':43 ''warrant'':113 ''work'':33 ''ye'':16', NULL, '162');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('163', '2', '163', NULL, 'These verses are closely connected with the preceding chapter, and state very briefly the results of the intercession of Moses recorded in Deuteronomy 9:25-29. The people are reminded that all their blessings and privileges, forfeited by apostasy as soon as bestowed, were only now their own by a new and most unmerited act of grace on the part of God, won from Him by the self-sacrificing mediation of Moses himself Deuteronomy 10:10.Deuteronomy 10:1-5. The order for making the ark and tabernacle was evidently given before the apostasy of the people (Exodus 25ff); but the tables were not put in the ark until the completion and dedication of the tabernacle Exodus 40. But here as elsewhere (compare the Deuteronomy 9:1 note) Moses connects transactions closely related to each other and to his purpose without regard to the order of occurrence.', NULL, NULL, '''-29'':26 ''-5'':80 ''1'':79,127 ''10'':76,78 ''10.deuteronomy'':77 ''25'':25 ''25ff'':99 ''40'':118 ''9'':24,126 ''act'':55 ''apostasi'':39,94 ''ark'':86,108 ''bestow'':43 ''bless'':34 ''briefli'':13 ''chapter'':9 ''close'':4,132 ''compar'':123 ''complet'':111 ''connect'':5,130 ''dedic'':113 ''deuteronomi'':23,75,125 ''elsewher'':122 ''evid'':90 ''exodus'':98,117 ''forfeit'':37 ''given'':91 ''god'':62 ''grace'':57 ''intercess'':18 ''make'':84 ''mediat'':71 ''mose'':20,73,129 ''new'':51 ''note'':128 ''occurr'':147 ''order'':82,145 ''part'':60 ''peopl'':28,97 ''preced'':8 ''privileg'':36 ''purpos'':140 ''put'':105 ''record'':21 ''regard'':142 ''relat'':133 ''remind'':30 ''result'':15 ''sacrif'':70 ''self'':69 ''self-sacrif'':68 ''soon'':41 ''state'':11 ''tabernacl'':88,116 ''tabl'':102 ''transact'':131 ''unmerit'':54 ''vers'':2 ''without'':141 ''won'':63', NULL, '163');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('164', '2', '164', NULL, 'And know ... - Render it: And own ye this day (for I have not to do with your children which have not known and which have not seen) the chastisement of the Lord, his greatness, etc.The "chastisement" consisted in the many mighty acts, both of punishment and mercy, through which God had guided them from Egypt to the borders of the promised land.', NULL, NULL, '''act'':42 ''border'':58 ''chastis'':29,36 ''children'':18 ''consist'':37 ''day'':9 ''egypt'':55 ''etc.the'':35 ''god'':50 ''great'':34 ''guid'':52 ''know'':2 ''known'':22 ''land'':62 ''lord'':32 ''mani'':40 ''merci'':47 ''mighti'':41 ''promis'':61 ''punish'':45 ''render'':3 ''seen'':27 ''ye'':7', NULL, '164');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('165', '2', '165', NULL, 'Moses now passes on to apply Deuteronomy 12-26 the leading principles of the Decalogue to the ecclesiastical, civil, and social life of the people. Particulars will be noticed which are unique to the Law as given in Deuteronomy; and even in laws repeated from the earlier books various new circumstances and details are introduced. This is only natural. The Sinaitic legislation was nearly 40 years old and had been given under conditions of time, place, and circumstance different and distant from those now present. Yet the Sinaitic system, far from being set aside or in any way abrogated, is on the contrary throughout presupposed and assumed. Its existence and authority are taken as the starting-point for what is here prescribed, and an accurate acquaintance with it on the part of the people is taken for granted.', NULL, NULL, '''-26'':9 ''12'':8 ''40'':65 ''abrog'':99 ''accur'':126 ''acquaint'':127 ''appli'':6 ''asid'':94 ''assum'':107 ''author'':111 ''book'':48 ''circumst'':51,78 ''civil'':19 ''condit'':73 ''contrari'':103 ''decalogu'':15 ''detail'':53 ''deuteronomi'':7,39 ''differ'':79 ''distant'':81 ''earlier'':47 ''ecclesiast'':18 ''even'':41 ''exist'':109 ''far'':90 ''given'':37,71 ''grant'':139 ''introduc'':55 ''law'':35,43 ''lead'':11 ''legisl'':62 ''life'':22 ''mose'':1 ''natur'':59 ''near'':64 ''new'':50 ''notic'':29 ''old'':67 ''part'':132 ''particular'':26 ''pass'':3 ''peopl'':25,135 ''place'':76 ''point'':118 ''prescrib'':123 ''present'':85 ''presuppos'':105 ''principl'':12 ''repeat'':44 ''set'':93 ''sinait'':61,88 ''social'':21 ''start'':117 ''starting-point'':116 ''system'':89 ''taken'':113,137 ''throughout'':104 ''time'':75 ''uniqu'':32 ''various'':49 ''way'':98 ''year'':66 ''yet'':86', NULL, '165');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('166', '2', '166', NULL, 'A prophet, or a dreamer of dreams - Compare Numbers 12:6. The "prophet" received his revelations by vision or direct oral communication Numbers 24:16; 2 Samuel 7:4; 2 Corinthians 12:2; "the dreamer of dreams" through the medium of a dream 1 Kings 3:5; Matthew 2:13.', NULL, NULL, '''1'':44 ''12'':10,32 ''13'':50 ''16'':25 ''2'':26,30,33,49 ''24'':24 ''3'':46 ''4'':29 ''5'':47 ''6'':11 ''7'':28 ''communic'':22 ''compar'':8 ''corinthian'':31 ''direct'':20 ''dream'':7,37,43 ''dreamer'':5,35 ''king'':45 ''matthew'':48 ''medium'':40 ''number'':9,23 ''oral'':21 ''prophet'':2,13 ''receiv'':14 ''revel'':16 ''samuel'':27 ''vision'':18', NULL, '166');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('167', '2', '167', NULL, 'Make any baldness between your eyes - i. e. by shaving the forepart of the head and the eyebrows. The practices named in this verse were common among the pagan, and seem to be forbidden, not only because such wild excesses of grief (compare 1 Kings 18:28) would be inconsistent in those who as children of a heavenly Father had prospects beyond this world, but also because these usages themselves arose out of idolatrous notions.', NULL, NULL, '''1'':44 ''18'':46 ''28'':47 ''also'':66 ''among'':27 ''aros'':71 ''bald'':3 ''beyond'':62 ''children'':55 ''common'':26 ''compar'':43 ''e'':8 ''excess'':40 ''eye'':6 ''eyebrow'':18 ''father'':59 ''forbidden'':34 ''forepart'':12 ''grief'':42 ''head'':15 ''heaven'':58 ''idolatr'':74 ''inconsist'':50 ''king'':45 ''make'':1 ''name'':21 ''notion'':75 ''pagan'':29 ''practic'':20 ''prospect'':61 ''seem'':31 ''shave'':10 ''usag'':69 ''vers'':24 ''wild'':39 ''world'':64 ''would'':48', NULL, '167');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('168', '2', '168', NULL, 'The year of release is no doubt identical with the sabbatical year of the earlier legislation (Exodus 23:10 ff, and Leviticus 25:2 ff), the command of the older legislation being here amplified. The release was probably for the year, not total and final, and had reference only to loans lent because of poverty (compare Deuteronomy 15:4, Deuteronomy 15:7). Yet even so the law was found to be too stringent for the avarice of the people, because it was one of those which the rabbis "made of none effect by their traditions."', NULL, NULL, '''10'':19 ''15'':58,61 ''2'':24 ''23'':18 ''25'':23 ''4'':59 ''7'':62 ''amplifi'':34 ''avaric'':76 ''command'':27 ''compar'':56 ''deuteronomi'':57,60 ''doubt'':7 ''earlier'':15 ''effect'':92 ''even'':64 ''exodus'':17 ''ff'':20,25 ''final'':45 ''found'':69 ''ident'':8 ''law'':67 ''legisl'':16,31 ''lent'':52 ''leviticus'':22 ''loan'':51 ''made'':89 ''none'':91 ''older'':30 ''one'':83 ''peopl'':79 ''poverti'':55 ''probabl'':38 ''rabbi'':88 ''refer'':48 ''releas'':4,36 ''sabbat'':11 ''stringent'':73 ''total'':43 ''tradit'':95 ''year'':2,12,41 ''yet'':63', NULL, '168');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('243', '2', '243', NULL, 'This verse belongs more properly to 1 Samuel 6. Abinadab and his sons were probably of the house of Levi. The catastrophe at Bethshemesh must inevitably have made the Israelites very careful to pay due honor to the ark in accordance with the Law: but to give the care of the ark to those who were not of the house of Levi would be a gross violation of the Law.', NULL, NULL, '''1'':7 ''6'':9 ''abinadab'':10 ''accord'':41 ''ark'':39,52 ''belong'':3 ''bethshemesh'':24 ''care'':32,49 ''catastroph'':22 ''due'':35 ''give'':47 ''gross'':66 ''honor'':36 ''hous'':18,60 ''inevit'':26 ''israelit'':30 ''law'':44,70 ''levi'':20,62 ''made'':28 ''must'':25 ''pay'':34 ''probabl'':15 ''proper'':5 ''samuel'':8 ''son'':13 ''vers'':2 ''violat'':67 ''would'':63', NULL, '243');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('172', '2', '172', NULL, 'This and the next two chapters contain enactments designed to protect human life, and to impress its sanctity on Israel.In Deuteronomy 19:1-13 the directions respecting the preparation of the roads to the cities of refuge, the provision of additional cities in case of an extension of territory, and the intervention of the elders as representing the congregation, are unique to Deuteronomy and supplementary to the laws on the same subject given in the earlier books (compare the marginal reference).Deuteronomy 19:1, Deuteronomy 19:2The three cities of refuge for the district east of Jordan had been already named. Moses now directs that when the territory on the west of Jordan had been conquered, a like allotment of three other cities in it should be made. This was accordingly done; compare Joshua 20:1 ff,', NULL, NULL, '''-13'':24 ''1'':23,84,136 ''19'':22,83,86 ''20'':135 ''2the'':87 ''accord'':131 ''addit'':41 ''allot'':119 ''alreadi'':100 ''book'':77 ''case'':44 ''chapter'':6 ''citi'':35,42,89,123 ''compar'':78,133 ''congreg'':59 ''conquer'':116 ''contain'':7 ''design'':9 ''deuteronomi'':21,63,82,85 ''direct'':26,104 ''district'':94 ''done'':132 ''earlier'':76 ''east'':95 ''elder'':55 ''enact'':8 ''extens'':47 ''ff'':137 ''given'':73 ''human'':12 ''impress'':16 ''intervent'':52 ''israel.in'':20 ''jordan'':97,113 ''joshua'':134 ''law'':68 ''life'':13 ''like'':118 ''made'':128 ''margin'':80 ''mose'':102 ''name'':101 ''next'':4 ''prepar'':29 ''protect'':11 ''provis'':39 ''refer'':81 ''refug'':37,91 ''repres'':57 ''respect'':27 ''road'':32 ''sanctiti'':18 ''subject'':72 ''supplementari'':65 ''territori'':49,108 ''three'':88,121 ''two'':5 ''uniqu'':61 ''west'':111', NULL, '172');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('173', '2', '173', NULL, 'Horses, and chariots - The most formidable elements of an Oriental host, which the Canaanites possessed in great numbers; compare Joshua 17:16; Judges 4:3; 1 Samuel 13:5. Israel could not match these with corresponding forces (compare Deuteronomy 17:16 note and references), but, having the God of battles on its side, was not to be dismayed by them; the assumption being that the war had the sanction of God, and was consequently just.', NULL, NULL, '''1'':26 ''13'':28 ''16'':22,41 ''17'':21,40 ''3'':25 ''4'':24 ''5'':29 ''assumpt'':62 ''battl'':50 ''canaanit'':14 ''chariot'':3 ''compar'':19,38 ''consequ'':74 ''correspond'':36 ''could'':31 ''deuteronomi'':39 ''dismay'':58 ''element'':7 ''forc'':37 ''formid'':6 ''god'':48,71 ''great'':17 ''hors'':1 ''host'':11 ''israel'':30 ''joshua'':20 ''judg'':23 ''match'':33 ''note'':42 ''number'':18 ''orient'':10 ''possess'':15 ''refer'':44 ''samuel'':27 ''sanction'':69 ''side'':53 ''war'':66', NULL, '173');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('174', '2', '174', NULL, 'The elders represented the citizens at large, the judges the magistracy: priests Deuteronomy 21:5 from the nearest priestly town, were likewise to be at hand. Thus, all classes would be represented at the purging away of that blood-guiltiness which until removed attached to the whole community.', NULL, NULL, '''21'':14 ''5'':15 ''attach'':45 ''away'':36 ''blood'':40 ''blood-guilti'':39 ''citizen'':5 ''class'':29 ''communiti'':49 ''deuteronomi'':13 ''elder'':2 ''guilti'':41 ''hand'':26 ''judg'':9 ''larg'':7 ''likewis'':22 ''magistraci'':11 ''nearest'':18 ''priest'':12,19 ''purg'':35 ''remov'':44 ''repres'':3,32 ''thus'':27 ''town'':20 ''whole'':48 ''would'':30', NULL, '174');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('175', '2', '175', NULL, 'That which pertaineth unto a man - i. e. not only his dress but all that especially pertains distinctively to his sex; arms, domestic and other utensils, etc.The distinction between the sexes is natural and divinely established, and cannot be neglected without indecorum and consequent danger to purity (compare 1 Corinthians 11:3-15).', NULL, NULL, '''-15'':53 ''1'':49 ''11'':51 ''3'':52 ''arm'':22 ''cannot'':38 ''compar'':48 ''consequ'':44 ''corinthian'':50 ''danger'':45 ''distinct'':18,28 ''divin'':35 ''domest'':23 ''dress'':12 ''e'':8 ''especi'':16 ''establish'':36 ''etc.the'':27 ''indecorum'':42 ''man'':6 ''natur'':33 ''neglect'':40 ''pertain'':17 ''pertaineth'':3 ''puriti'':47 ''sex'':21,31 ''unto'':4 ''utensil'':26 ''without'':41', NULL, '175');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('176', '2', '176', NULL, 'Compare Leviticus 21:17-24. Such persons, exhibiting a mutilation of that human nature which was made in God''s image, were rejected from the covenant entirely. However, they could be proselytes (compare Acts 8:27). The Old Testament itself foretells Isaiah 56:3-5 the removal of this ban when under the kingdom of Messiah the outward and emblematic perfection and sanctity of Israel should be fulfilled in their inner meaning by the covenanted presence and work of the Holy Spirit in the Church.', NULL, NULL, '''-24'':5 ''-5'':45 ''17'':4 ''21'':3 ''27'':36 ''3'':44 ''56'':43 ''8'':35 ''act'':34 ''ban'':50 ''church'':85 ''compar'':1,33 ''could'':30 ''coven'':26,75 ''emblemat'':60 ''entir'':27 ''exhibit'':8 ''foretel'':41 ''fulfil'':68 ''god'':19 ''holi'':81 ''howev'':28 ''human'':13 ''imag'':21 ''inner'':71 ''isaiah'':42 ''israel'':65 ''kingdom'':54 ''leviticus'':2 ''made'':17 ''mean'':72 ''messiah'':56 ''mutil'':10 ''natur'':14 ''old'':38 ''outward'':58 ''perfect'':61 ''person'':7 ''presenc'':76 ''proselyt'':32 ''reject'':23 ''remov'':47 ''sanctiti'':63 ''spirit'':82 ''testament'':39 ''work'':78', NULL, '176');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('177', '2', '177', NULL, 'In this and the next chapter certain particular rights and duties, domestic, social, and civil, are treated. The cases brought forward have often no definite connection, and seem selected in order to illustrate the application of the great principles of the Law in certain important events and circumstances.These four verses contain only one sentence, and should be rendered thus: If a man hath taken a wife, etc., and given her a bill of divorcement and Deuteronomy 24:2 if she has departed out of his house and become another man''s wife; and Deuteronomy 24:3 if the latter husband hates her, then Deuteronomy 24:4 her former husband, etc.Moses neither institutes nor enjoins divorce. The exact spirit of the passage is given in our Lord''s words to the Jews'', "Moses because of the hardness of your hearts suffered you to put away your wives" Matthew 19:8. Not only does the original institution of marriage as recorded by Moses Genesis 2:24 set forth the perpetuity of the bond, but the verses before us plainly intimate that divorce, while tolerated for the time, contravenes the order of nature and of God. The divorced woman who marries again is "defiled" Deuteronomy 24:4, and is grouped in this particular with the adulteress (compare Leviticus 18:20). Our Lord then was speaking according to the spirit of the law of Moses when he declared, "Whoso marrieth her which is put away doth commit adultery" Matthew 19:9. He was speaking too not less according to the mind of the prophets (compare Malachi 2:14-16). But Moses could not absolutely put an end to a practice which was traditional, and common to the Jews with other Oriental nations. His aim is therefore to regulate and thus to mitigate an evil which he could not extirpate.', NULL, NULL, '''-16'':265 ''14'':264 ''18'':216 ''19'':148,246 ''2'':78,163,263 ''20'':217 ''24'':77,95,105,164,203 ''3'':96 ''4'':106,204 ''8'':149 ''9'':247 ''absolut'':270 ''accord'':223,254 ''adulteress'':213 ''adulteri'':244 ''aim'':290 ''anoth'':89 ''applic'':35 ''away'':144,241 ''becom'':88 ''bill'':72 ''bond'':171 ''brought'':20 ''case'':19 ''certain'':7,44 ''chapter'':6 ''circumstances.these'':48 ''civil'':15 ''commit'':243 ''common'':281 ''compar'':214,261 ''connect'':26 ''contain'':51 ''contraven'':186 ''could'':268,303 ''declar'':234 ''defil'':201 ''definit'':25 ''depart'':82 ''deuteronomi'':76,94,104,202 ''divorc'':74,115,180,195 ''domest'':12 ''doth'':242 ''duti'':11 ''end'':273 ''enjoin'':114 ''etc'':67 ''etc.moses'':110 ''event'':46 ''evil'':300 ''exact'':117 ''extirp'':305 ''former'':108 ''forth'':166 ''forward'':21 ''four'':49 ''genesi'':162 ''given'':69,123 ''god'':193 ''great'':38 ''group'':207 ''hard'':136 ''hate'':101 ''hath'':63 ''heart'':139 ''hous'':86 ''husband'':100,109 ''illustr'':33 ''import'':45 ''institut'':112,155 ''intim'':178 ''jew'':131,284 ''latter'':99 ''law'':42,229 ''less'':253 ''leviticus'':215 ''lord'':126,219 ''malachi'':262 ''man'':62,90 ''marri'':198 ''marriag'':157 ''marrieth'':236 ''matthew'':147,245 ''mind'':257 ''mitig'':298 ''mose'':132,161,231,267 ''nation'':288 ''natur'':190 ''neither'':111 ''next'':5 ''often'':23 ''one'':53 ''order'':31,188 ''orient'':287 ''origin'':154 ''particular'':8,210 ''passag'':121 ''perpetu'':168 ''plain'':177 ''practic'':276 ''principl'':39 ''prophet'':260 ''put'':143,240,271 ''record'':159 ''regul'':294 ''render'':58 ''right'':9 ''seem'':28 ''select'':29 ''sentenc'':54 ''set'':165 ''social'':13 ''speak'':222,250 ''spirit'':118,226 ''suffer'':140 ''taken'':64 ''therefor'':292 ''thus'':59,296 ''time'':185 ''toler'':182 ''tradit'':279 ''treat'':17 ''us'':176 ''vers'':50,174 ''whoso'':235 ''wife'':66,92 ''wive'':146 ''woman'':196 ''word'':128', NULL, '177');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('178', '2', '178', NULL, 'Render it:(1) If there be a controversy between men, and they come to judgment, and the judges judge them, and justify the righteous and condemn the wicked (compare the marginal reference. and Exodus 23:7; Proverbs 17:15);(2) then it shall be, etc.', NULL, NULL, '''1'':3 ''15'':39 ''17'':38 ''2'':40 ''23'':35 ''7'':36 ''come'':13 ''compar'':29 ''condemn'':26 ''controversi'':8 ''etc'':45 ''exodus'':34 ''judg'':18,19 ''judgment'':15 ''justifi'':22 ''margin'':31 ''men'':10 ''proverb'':37 ''refer'':32 ''render'':1 ''righteous'':24 ''shall'':43 ''wick'':28', NULL, '178');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('180', '2', '180', NULL, 'Moses in a third discourse Deuteronomy 27-30, proceeds more specifically to dwell upon the sanctions of the Law. In these chapters he sets before Israel in striking and elaborate detail the blessings which would ensue upon faithfulness to the covenant, and the curses which disobedience would involve. Deuteronomy 27 introduces this portion of the book by enjoining the erection of a stone monument on which the Law should be inscribed as soon as the people took possession of the promised inheritance Deuteronomy 27:1-10; and by next prescribing the liturgical form after which the blessings and cursings should be pronounced Deuteronomy 27:11-26.', NULL, NULL, '''-10'':86 ''-26'':106 ''-30'':8 ''1'':85 ''11'':105 ''27'':7,50,84,104 ''bless'':33,97 ''book'':56 ''chapter'':22 ''coven'':41 ''curs'':44,99 ''detail'':31 ''deuteronomi'':6,49,83,103 ''discours'':5 ''disobedi'':46 ''dwell'':13 ''elabor'':30 ''enjoin'':58 ''ensu'':36 ''erect'':60 ''faith'':38 ''form'':93 ''inherit'':82 ''inscrib'':71 ''introduc'':51 ''involv'':48 ''israel'':26 ''law'':19,68 ''liturg'':92 ''monument'':64 ''mose'':1 ''next'':89 ''peopl'':76 ''portion'':53 ''possess'':78 ''prescrib'':90 ''proceed'':9 ''promis'':81 ''pronounc'':102 ''sanction'':16 ''set'':24 ''soon'':73 ''specif'':11 ''stone'':63 ''strike'':28 ''third'':4 ''took'':77 ''upon'':14,37 ''would'':35,47', NULL, '180');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('181', '2', '181', NULL, 'A comparison of this chapter with Exodus 23:20-23 and Leviticus 26 will show how Moses here resumes and amplifies the promises and threats already set forth in the earlier records of the Law. The language rises in this chapter to the sublimest strains, especially in the latter part of it; and the prophecies respecting the dispersion and degradation of the Jewish nation in its later days are among the most remarkable in scripture. They are plain, precise, and circumstantial; and the fulfillment of them has been literal, complete, and undeniable.The Blessing. The six repetitions of the word "blessed" introduce the particular forms which the blessing would take in the various relations of life.', NULL, NULL, '''-23'':10 ''20'':9 ''23'':8 ''26'':13 ''alreadi'':26 ''among'':70 ''amplifi'':21 ''bless'':93,100,107 ''chapter'':5,41 ''circumstanti'':81 ''comparison'':2 ''complet'':90 ''day'':68 ''degrad'':60 ''dispers'':58 ''earlier'':31 ''especi'':46 ''exodus'':7 ''form'':104 ''forth'':28 ''fulfil'':84 ''introduc'':101 ''jewish'':63 ''languag'':37 ''later'':67 ''latter'':49 ''law'':35 ''leviticus'':12 ''life'':115 ''liter'':89 ''mose'':17 ''nation'':64 ''part'':50 ''particular'':103 ''plain'':78 ''precis'':79 ''promis'':23 ''propheci'':55 ''record'':32 ''relat'':113 ''remark'':73 ''repetit'':96 ''respect'':56 ''resum'':19 ''rise'':38 ''scriptur'':75 ''set'':27 ''show'':15 ''six'':95 ''strain'':45 ''sublimest'':44 ''take'':109 ''threat'':25 ''undeniable.the'':92 ''various'':112 ''word'':99 ''would'':108', NULL, '181');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('182', '2', '182', NULL, 'This and the following chapter contain the address of Moses to the people on the solemn renewal of the covenant. Consult the marginal references for proof of historical statements or explanation of obscure words.', NULL, NULL, '''address'':8 ''chapter'':5 ''consult'':21 ''contain'':6 ''coven'':20 ''explan'':31 ''follow'':4 ''histor'':28 ''margin'':23 ''mose'':10 ''obscur'':33 ''peopl'':13 ''proof'':26 ''refer'':24 ''renew'':17 ''solemn'':16 ''statement'':29 ''word'':34', NULL, '182');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('183', '2', '183', NULL, 'The rejection of Israel and the desolation of the promised inheritance were not to be the end of God''s dispensations. The closing words of the address therefore are words of comfort and promise. Compare marginal reference and Deuteronomy 4:29 ff; 1 Kings 8:46-50.The chastisements of God would lead the nation to repent, and thereupon God would again bless them.', NULL, NULL, '''1'':43 ''29'':41 ''4'':40 ''46-50.the'':46 ''8'':45 ''address'':27 ''bless'':61 ''chastis'':47 ''close'':23 ''comfort'':32 ''compar'':35 ''desol'':7 ''deuteronomi'':39 ''dispens'':21 ''end'':17 ''ff'':42 ''god'':19,49,58 ''inherit'':11 ''israel'':4 ''king'':44 ''lead'':51 ''margin'':36 ''nation'':53 ''promis'':10,34 ''refer'':37 ''reject'':2 ''repent'':55 ''therefor'':28 ''thereupon'':57 ''word'':24,30 ''would'':50,59', NULL, '183');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('184', '2', '184', NULL, 'I am an hundred and twenty years old - The 40 years of the wandering had passed since Moses, then 80 years old, "spake unto Pharaoh" (Exodus 7:7; Compare Deuteronomy 34:7).I can, no more go out and come in - Render I shall not longer be able to go out and come in: i. e., discharge my duties among you. There is no inconsistency with Deuteronomy 34:7. Moses here adverts to his own age as likely to render him in future unequal to the active discharge of his office as leader of the people: the writer of Deuteronomy 34:1-12, one of Moses'' contemporaries, remarks of him that up to the close of life "his eye was not dim, nor his natural force abated" Deuteronomy 31:7; i. e. that he was to the last, in the judgment of others, in full possession of faculties and strength.', NULL, NULL, '''-12'':103 ''1'':102 ''31'':129 ''34'':31,68,101 ''40'':10 ''7'':27,28,32,69,130 ''80'':20 ''abat'':127 ''abl'':48 ''activ'':87 ''advert'':72 ''age'':76 ''among'':60 ''close'':115 ''come'':40,53 ''compar'':29 ''contemporari'':107 ''deuteronomi'':30,67,100,128 ''dim'':122 ''discharg'':57,88 ''duti'':59 ''e'':56,132 ''exodus'':26 ''eye'':119 ''faculti'':148 ''forc'':126 ''full'':145 ''futur'':83 ''go'':37,50 ''hundr'':4 ''inconsist'':65 ''judgment'':141 ''last'':138 ''leader'':93 ''life'':117 ''like'':78 ''longer'':46 ''mose'':18,70,106 ''natur'':125 ''offic'':91 ''old'':8,22 ''one'':104 ''other'':143 ''pass'':16 ''peopl'':96 ''pharaoh'':25 ''possess'':146 ''remark'':108 ''render'':42,80 ''shall'':44 ''sinc'':17 ''spake'':23 ''strength'':150 ''twenti'':6 ''unequ'':84 ''unto'':24 ''wander'':14 ''writer'':98 ''year'':7,11,21', NULL, '184');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('185', '2', '185', NULL, 'Song of MosesIf Deuteronomy 32:1-3 be regarded as the introduction, and Deuteronomy 32:43 as the conclusion, the main contents of the song may be grouped under three heads, namely,-1Deu 32:4-18, the faithfulness of God, the faithlessness of Israel;-2Deu 32:19-33, the chastisement and the need of its infliction by God;-3Deu 32:34-42, God''s compassion upon the low and humbled state of His people.The Song differs signally in diction and idiom from the preceding chapters; just as a lyrical passage is conceived in modes of thought wholly unlike those which belong to narrative or exhortation, and is uttered in different phraseology.There are, however, in the Song numerous coincidences both in thoughts and words with other parts of the Pentateuch, and especially with Deuteronomy; while the resemblances between it and Psalm 90:"A Prayer of Moses," have been rightly regarded as important.The Song has reference to a state of things which did not ensue until long after the days of Moses. In this it resembles other parts of Deuteronomy and the Pentateuch which no less distinctly contemplate an apostasy (e. g. Deuteronomy 28:15; Leviticus 26:14), and describe it in general terms. If once we admit the possibility that Moses might foresee the future apostasy of Israel, it is scarcely possible to conceive how such foresight could be turned to better account by him than by the writing of this Song. Exhibiting as it does God''s preventing mercies, His people''s faithlessness and ingratitude, God''s consequent judgments, and the final and complete triumph of the divine counsels of grace, it forms the summary of all later Old Testament prophecies, and gives as it were the framework upon which they are laid out. Here as elsewhere the Pentateuch presents itself as the foundation of the religious life of Israel in after times. The currency of the Song would be a standing protest against apostasy; a protest which might well check waverers, and warn the faithful that the revolt of others was neither unforeseen nor unprovided for by Him in whom they trusted.That this Ode must on every ground take the very first rank in Hebrew poetry is universally allowed.Deuteronomy 32:1-3Introduction. Heaven and earth are here invoked, as elsewhere (see the marginal references), in order to impress on the hearers the importance of what is to follow.', NULL, NULL, '''-1'':33 ''-18'':37 ''-2'':46 ''-3'':7,61,376 ''-33'':50 ''-42'':65 ''1'':6,375 ''14'':199 ''15'':196 ''19'':49 ''26'':198 ''28'':195 ''32'':5,15,35,48,63,374 ''34'':64 ''4'':36 ''43'':16 ''90'':144 ''account'':235 ''admit'':209 ''allowed.deuteronomy'':373 ''apostasi'':191,218,328 ''belong'':104 ''better'':234 ''chapter'':88 ''chastis'':52 ''check'':334 ''coincid'':121 ''compass'':68 ''complet'':267 ''conceiv'':95,226 ''conclus'':19 ''consequ'':261 ''contempl'':189 ''content'':22 ''could'':230 ''counsel'':272 ''currenc'':318 ''day'':171 ''describ'':201 ''deu'':34,47,62 ''deuteronomi'':4,14,136,181,194 ''diction'':82 ''differ'':79,113 ''distinct'':188 ''divin'':271 ''e'':192 ''earth'':380 ''elsewher'':300,385 ''ensu'':166 ''especi'':134 ''everi'':361 ''exhibit'':245 ''exhort'':108 ''faith'':39,339 ''faithless'':43,256 ''final'':265 ''first'':366 ''follow'':403 ''forese'':215 ''foresight'':229 ''form'':276 ''foundat'':307 ''framework'':291 ''futur'':217 ''g'':193 ''general'':204 ''give'':286 ''god'':41,60,66,249,259 ''grace'':274 ''ground'':362 ''group'':28 ''head'':31 ''hearer'':396 ''heaven'':378 ''hebrew'':369 ''howev'':116 ''humbl'':73 ''idiom'':84 ''import'':398 ''important.the'':154 ''impress'':393 ''inflict'':58 ''ingratitud'':258 ''introduct'':12,377 ''invok'':383 ''israel'':45,220,313 ''judgment'':262 ''laid'':296 ''later'':281 ''less'':187 ''leviticus'':197 ''life'':311 ''long'':168 ''low'':71 ''lyric'':92 ''main'':21 ''margin'':388 ''may'':26 ''merci'':252 ''might'':214,332 ''mode'':97 ''mose'':148,173,213 ''mosesif'':3 ''must'':359 ''name'':32 ''narrat'':106 ''need'':55 ''neither'':346 ''numer'':120 ''ode'':358 ''old'':282 ''order'':391 ''other'':344 ''part'':129,179 ''passag'':93 ''pentateuch'':132,184,302 ''peopl'':254 ''people.the'':77 ''phraseology.there'':114 ''poetri'':370 ''possibl'':211,224 ''prayer'':146 ''preced'':87 ''present'':303 ''prevent'':251 ''propheci'':284 ''protest'':326,330 ''psalm'':143 ''rank'':367 ''refer'':157,389 ''regard'':9,152 ''religi'':310 ''resembl'':139,177 ''revolt'':342 ''right'':151 ''scarc'':223 ''see'':386 ''signal'':80 ''song'':1,25,78,119,155,244,321 ''stand'':325 ''state'':74,160 ''summari'':278 ''take'':363 ''term'':205 ''testament'':283 ''thing'':162 ''thought'':99,124 ''three'':30 ''time'':316 ''triumph'':268 ''trusted.that'':356 ''turn'':232 ''unforeseen'':347 ''univers'':372 ''unlik'':101 ''unprovid'':349 ''upon'':69,292 ''utter'':111 ''warn'':337 ''waver'':335 ''well'':333 ''wholli'':100 ''word'':126 ''would'':322 ''write'':241', NULL, '185');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1220', '2', '1220', NULL, 'For I would that ye knew - I wish you knew or fully understood. He supposes that this would deeply affect them if they understood the solicitude which he had had on their account.What great conflict - Margin, fear, or care. The Greek word is "agony" - &#x3b1;&#x3b3;&#x3c9;&#x3bd;&#x3b1;  agona. It is not, however, the word rendered "agony" in Luke 22:44 - &#x3b1;&#x3b3;&#x3c9;&#x3bd;&#x3b9;&#x3b1;  agonia - though that is derived from this. The word is rendered conflict in Philippians 1:30; contention, 1 Thessalonians 2:2; fight, 1 Timothy 6:12; 2 Timothy 4:7; and race, Hebrews 12:1. It properly refers to the combats, contests, struggles, efforts at the public games; the toil and conflict to obtain a victory. It refers here to the anxious care, the mental conflict, the earnest solicitude which he had in their behalf, in view of the dangers to which they were exposed from Judaizing Christians and Pagan philosophy. This mental struggle resembled that which the combatants had at the public games; compare the 1 Corinthians 9:25, note, 27, note. And for them at Laodicea For Christians there, who were exposed to similar danger. Laodicea was the capital of Phrygia, in Asia Minor, and a little south of Colossae. See Introduction, Section 1. 6. Notes, Colossians 4:16. There was a church early planted there - the "lukewarm" church mentioned in Revelation 3:14. Being in the vicinity of Colossae, the church there would be exposed to the same perils, and the rebuke in Revelation 3:14, showed that the fears of Paul were well founded, and that the arts of the false teachers were too successful.And for as many as have not seen my face in the flesh - That is, evidently in that region. He had, doubtless, a general solicitude for all Christians, but his remark here has reference to those in the neighborhood of the church at Colossae, or in that church. On the question which has been raised, whether this proves that the apostle Paul had never been at Colossae or Laodicea, see Introduction, Section 2, 4. This passage does not seem to me to prove that he had not been there. It may mean that he had great solicitude for those Christians there whom he knew, and for all others there, or in the vicinity, even though he was not personally acquainted with them. He may refer:(1) to some churches in the neighborhood formed since he was there; or.(2) to strangers who had come in there since he was with them; or.(3) to those who had been converted since he was there, and with whom he had no personal acquaintance. For all these he would feel the same solicitude, for they were all exposed to the same danger. To "see one''s face in the flesh," is a Hebraism, meaning to become personally acquainted with him.', NULL, NULL, '''1'':72,75,80,92,164,203,391 ''12'':83,91 ''14'':223,246 ''16'':208 ''2'':77,78,84,338,404 ''22'':56 ''25'':167 ''27'':169 ''3'':222,245,418 ''30'':73 ''4'':86,207,339 ''44'':57 ''6'':82,204 ''7'':87 ''9'':166 ''account.what'':33 ''acquaint'':385,436,470 ''affect'':20 ''agona'':45 ''agoni'':44,53 ''agonia'':58 ''anxious'':119 ''apostl'':326 ''art'':259 ''asia'':192 ''becom'':468 ''behalf'':132 ''capit'':188 ''care'':39,120 ''christian'':145,177,293,365 ''church'':212,218,231,307,313,394 ''colossa'':199,229,309,332 ''colossian'':206 ''combat'':98,156 ''come'':409 ''compar'':162 ''conflict'':35,69,109,123 ''content'':74 ''contest'':99 ''convert'':424 ''corinthian'':165 ''danger'':137,184,454 ''deepli'':19 ''deriv'':62 ''doubtless'':287 ''earli'':213 ''earnest'':125 ''effort'':101 ''even'':379 ''evid'':281 ''expos'':142,181,235,450 ''face'':275,459 ''fals'':262 ''fear'':37,250 ''feel'':442 ''fight'':79 ''flesh'':278,462 ''form'':398 ''found'':255 ''fulli'':12 ''game'':105,161 ''general'':289 ''great'':34,361 ''greek'':41 ''hebraism'':465 ''hebrew'':90 ''howev'':49 ''introduct'':201,336 ''judaiz'':144 ''knew'':6,10,369 ''laodicea'':175,185,334 ''littl'':196 ''luke'':55 ''lukewarm'':217 ''mani'':269 ''margin'':36 ''may'':356,389 ''mean'':357,466 ''mental'':122,150 ''mention'':219 ''minor'':193 ''neighborhood'':304,397 ''never'':329 ''note'':168,170,205 ''obtain'':111 ''one'':457 ''other'':373 ''pagan'':147 ''passag'':341 ''paul'':252,327 ''peril'':239 ''person'':384,435,469 ''philippian'':71 ''philosophi'':148 ''phrygia'':190 ''plant'':214 ''proper'':94 ''prove'':323,348 ''public'':104,160 ''question'':316 ''race'':89 ''rais'':320 ''rebuk'':242 ''refer'':95,115,299,390 ''region'':284 ''remark'':296 ''render'':52,68 ''resembl'':152 ''revel'':221,244 ''section'':202,337 ''see'':200,335,456 ''seem'':344 ''seen'':273 ''show'':247 ''similar'':183 ''sinc'':399,412,425 ''solicitud'':26,126,290,362,445 ''south'':197 ''stranger'':406 ''struggl'':100,151 ''successful.and'':266 ''suppos'':15 ''teacher'':263 ''thessalonian'':76 ''though'':59,380 ''timothi'':81,85 ''toil'':107 ''understood'':13,24 ''vicin'':227,378 ''victori'':113 ''view'':134 ''well'':254 ''whether'':321 ''wish'':8 ''word'':42,51,66 ''would'':3,18,233,441 ''ye'':5', NULL, '1109');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1221', '2', '1221', NULL, 'If ye then be risen with Christ - The apostle in this place evidently founds the argument on what he had said in Colossians 2:12; see the notes at that passage. The argument is, that there was such an union between Christ and his people, that in virtue of his death they become dead to sin; that in virtue of his resurrection they rise to spiritual life, and that, therefore, as Christ now lives in heaven, they should live for heaven, and fix their affections there.Seek those things which are above - That is, seek them as the objects of pursuit and affection; strive to secure them.Where Christ sitteth on the right hand of God - Notes, Mark 16:19. The argument here is, that since Christ is there, and since he is the object of our supreme attachment, we should fix our affections on heavenly things, and seek to be prepared to dwell with him.', NULL, NULL, '''12'':25 ''16'':117 ''19'':118 ''2'':24 ''affect'':85,102,142 ''apostl'':9 ''argument'':16,33,120 ''attach'':137 ''becom'':53 ''christ'':7,42,72,107,125 ''colossian'':23 ''dead'':54 ''death'':51 ''dwell'':152 ''evid'':13 ''fix'':83,140 ''found'':14 ''god'':114 ''hand'':112 ''heaven'':76,81,144 ''life'':67 ''live'':74,79 ''mark'':116 ''note'':28,115 ''object'':98,133 ''passag'':31 ''peopl'':45 ''place'':12 ''prepar'':150 ''pursuit'':100 ''resurrect'':62 ''right'':111 ''rise'':64 ''risen'':5 ''said'':21 ''secur'':105 ''see'':26 ''seek'':94,147 ''sin'':56 ''sinc'':124,129 ''sitteth'':108 ''spiritu'':66 ''strive'':103 ''suprem'':136 ''them.where'':106 ''there.seek'':86 ''therefor'':70 ''thing'':88,145 ''union'':40 ''virtu'':48,59 ''ye'':2', NULL, '1110');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1223', '2', '1223', NULL, 'Paul, and Silvanus, and Timotheus - On the reasons why Paul associated other names with his in his epistles, see the 1 Corinthians 1:1 note, and 2 Corinthians 2:1 note. Silvanus, or Silas, and Timothy were properly united with him on this occasion, because they had been with him when the church was founded there, Acts 17, and because Timothy had been sent by the apostle to visit them after he had himself been driven away; 1 Thessalonians 2:1-2. Silas is first mentioned in the New Testament as one who was sent by the church at Jerusalem with Paul to Antioch (notes, Acts 15:22); and he afterward became his traveling companion.Which is in God the Father, and in the Lord Jesus Christ - Who are united to the true God and to the Redeemer; or who sustain an intimate relation to the Father and the Lord Jesus. This is strong language, denoting, that they were a true church; compare 1 John 5:20. "Grace be unto you," etc.; see the notes, Romans 1:7.', NULL, NULL, '''-2'':82 ''1'':21,23,24,30,78,81,163,176 ''15'':107 ''17'':58 ''2'':27,29,80 ''20'':166 ''22'':108 ''5'':165 ''7'':177 ''act'':57,106 ''afterward'':111 ''antioch'':104 ''apostl'':67 ''associ'':11 ''away'':77 ''becam'':112 ''christ'':126 ''church'':53,98,161 ''companion.which'':115 ''compar'':162 ''corinthian'':22,28 ''denot'':155 ''driven'':76 ''epistl'':18 ''etc'':171 ''father'':120,146 ''first'':85 ''found'':55 ''god'':118,133 ''grace'':167 ''intim'':142 ''jerusalem'':100 ''jesus'':125,150 ''john'':164 ''languag'':154 ''lord'':124,149 ''mention'':86 ''name'':13 ''new'':89 ''note'':25,31,105,174 ''occas'':44 ''one'':92 ''paul'':1,10,102 ''proper'':38 ''reason'':8 ''redeem'':137 ''relat'':143 ''roman'':175 ''see'':19,172 ''sent'':64,95 ''sila'':34,83 ''silvanus'':3,32 ''strong'':153 ''sustain'':140 ''testament'':90 ''thessalonian'':79 ''timotheus'':5 ''timothi'':36,61 ''travel'':114 ''true'':132,160 ''unit'':39,129 ''unto'':169 ''visit'':69', NULL, '1112');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1224', '2', '1224', NULL, 'For yourselves, brethren, know our entrance in unto you - notes, 1 Thessalonians 1:9. Paul appeals to themselves for proof that they had not come among them as impostors. They had had a full opportunity to see them, and to know what influenced them. Paul frequently appeals to his own life, and to what they, among whom he labored, knew of it, as a full refutation of the slanderous accusations of his enemies; compare notes, 1 Corinthians 4:10-16; 1 Corinthians 9:19-27; 2 Corinthians 6:3-10. Every minister of the gospel ought so to live as to be able, when slanderously attacked, to make such an appeal to his people.That it was not in vain - &#x3ba;&#x3b5;&#x3bd;&#x3b7;  kene This word means:(1) "empty, vain, fruitless," or without success;(2) that in which there is no truth or reality - "false, fallacious;" Ephesians 5:6; Colossians 2:8.Here it seems, from the connection 1 Thessalonians 2:3-5, to be used in the latter sense, as denoting that they were not deceivers. The object does not appear to be so much to show that their ministry was successful, as to meet a charge of their adversaries that they were impostors. Paul tells them that from their own observation they knew that this was not so.', NULL, NULL, '''-10'':90 ''-16'':80 ''-27'':85 ''-5'':158 ''1'':11,13,76,81,124,154 ''10'':79 ''19'':84 ''2'':86,131,147,156 ''3'':89,157 ''4'':78 ''5'':144 ''6'':88,145 ''8.here'':148 ''9'':14,83 ''abl'':103 ''accus'':70 ''adversari'':196 ''among'':26,56 ''appeal'':16,47,111 ''appear'':177 ''attack'':106 ''brethren'':3 ''charg'':193 ''colossian'':146 ''come'':25 ''compar'':74 ''connect'':153 ''corinthian'':77,82,87 ''deceiv'':172 ''denot'':167 ''empti'':125 ''enemi'':73 ''entranc'':6 ''ephesian'':143 ''everi'':91 ''fallaci'':142 ''fals'':141 ''frequent'':46 ''fruitless'':127 ''full'':34,65 ''gospel'':95 ''impostor'':29,200 ''influenc'':43 ''kene'':120 ''knew'':60,210 ''know'':4,41 ''labor'':59 ''latter'':164 ''life'':51 ''live'':99 ''make'':108 ''mean'':123 ''meet'':191 ''minist'':92 ''ministri'':186 ''much'':181 ''note'':10,75 ''object'':174 ''observ'':208 ''opportun'':35 ''ought'':96 ''paul'':15,45,201 ''people.that'':114 ''proof'':20 ''realiti'':140 ''refut'':66 ''see'':37 ''seem'':150 ''sens'':165 ''show'':183 ''slander'':69,105 ''success'':130,188 ''tell'':202 ''thessalonian'':12,155 ''truth'':138 ''unto'':8 ''use'':161 ''vain'':119,126 ''without'':129 ''word'':122', NULL, '1113');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1231', '2', '1231', NULL, 'Paul, an apostle of Jesus Christ; - see the notes on Romans 1:1.By the commandment of God - See the notes at 1 Corinthians 1:1.Our Saviour - The name Saviour is as applicable to God the Father as to the Lord Jesus Christ, since God is the great Author of salvation; see the notes, Luke 1:47; compare 1 Timothy 4:10; Titus 2:10; Jde 1:25.And Lord Jesus Christ - The apostle Paul had received his commission directly from him; see the notes, Galatians 1:11-12.Which is our hope - See the notes at Colossians 1:27.', NULL, NULL, '''1'':12,22,24,55,58,66,85,95 ''1.by'':13 ''1.our'':25 ''10'':61,64 ''11-12.which'':86 ''2'':63 ''25.and'':67 ''27'':96 ''4'':60 ''47'':56 ''apostl'':3,72 ''applic'':32 ''author'':48 ''christ'':6,42,70 ''colossian'':94 ''command'':15 ''commiss'':77 ''compar'':57 ''corinthian'':23 ''direct'':78 ''father'':36 ''galatian'':84 ''god'':17,34,44 ''great'':47 ''hope'':89 ''jde'':65 ''jesus'':5,41,69 ''lord'':40,68 ''luke'':54 ''name'':28 ''note'':9,20,53,83,92 ''paul'':1,73 ''receiv'':75 ''roman'':11 ''salvat'':50 ''saviour'':26,29 ''see'':7,18,51,81,90 ''sinc'':43 ''timothi'':59 ''titus'':62', NULL, '1120');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1232', '2', '1232', NULL, 'I exhort, therefore - Margin, "desire." The word exhort, however, better expresses the sense of the original. The exhortation here is not addressed particularly to Timothy, but relates to all who were called to lead in public prayer; 1 Timothy 2:8. This exhortation, it may be observed, is inconsistent with the supposition that a liturgy was then in use, or with the supposition that there ever would be a liturgy - since, in that case, the objects to be prayed for would be prescribed. How singular would it be now for an Episcopal bishop to "exhort" his presbyters to pray "for the President of the United States and for all who are in authority." When the prayer is prescribed, do they not do this as a matter of course?First of all - That is, as the first duty to be enjoined; the thing that is to be regarded with primary concern; compare Luke 12:1; 2 Peter 1:20. It does not mean that this was to be the first thing in public worship in the order of time, but that it was to be regarded as a duty of primary importance. The duty of praying for the salvation of the whole world was not to be regarded as a subordinate and secondary thing.Supplications - It is not entirely easy to mark the difference in the meaning of the words used here, and it is not essential. They all relate to prayer, and refer only to the different parts of prayer, or to distinct classes of thought and desire which come before the mind in pleading for others. On the difference between the words supplications and prayers, see notes on Hebrews 5:7.Intercessions - The noun used occurs only in this place and in 1 Timothy 4:5, of this Epistle. The verb, however &#x3b5;&#x3bd;&#x3c4;&#x3c5;&#x3b3;&#x3c7;&#x3b1;&#x3bd;&#x3c9;  entungchano, occurs in Acts 25:4; Romans 8:27, Romans 8:34; Romans 11:2; Hebrews 7:25. See the meaning explained in the  Romans 8:26 note; Hebrews 7:25 note. There is one great Intercessor between God and man, who pleads for our salvation on the ground of what he himself has done, but we are permitted to intercede for others, not on the ground of any merit which they or we possess, but on the ground of the merit of the great Advocate and Intercessor. It is an inestimable privilege to be permitted to plead for the salvation of our fellow-men.Giving of thanks - That is, in behalf of others. We ought to give thanks for the mercy of God to ourselves; it is right and proper also that we should give thanks for the goodness of God to others. We should render praise that there is a way of salvation provided; that no one is excluded from the offer of mercy; and that God is using so many means to call lost sinners to himself.For all men - Prayers should be made for all people - for all need the grace and mercy of God; thanks should be rendered for all, for all may be saved. Does not this direction imply that Christ died for all mankind? How could we give thanks in their behalf if there were no mercy for them, and no way had been provided by which they could be saved? It may be observed here, that the direction to pray and to give thanks for all people, showed the large and catholic nature of Christianity. It was opposed entirely to the narrow and bigoted feelings of the Jews, who regarded the whole Gentile world as excluded from covenant mercies, and as having no offer of life. Christianity threw down all these barriers, and all people are on a level; and since Christ has died for all, there is ample ground for thanksgiving and praise in behalf of the whole human race.See Supplementary note, 2 Corinthians 5:14.', NULL, NULL, '''1'':38,154,157,292 ''11'':315 ''12'':153 ''14'':643 ''2'':40,155,316,640 ''20'':158 ''25'':306,319,332 ''26'':328 ''27'':310 ''34'':313 ''4'':294,307 ''5'':280,295,642 ''7'':318,331 ''7.intercessions'':281 ''8'':41,309,312,327 ''act'':305 ''address'':22 ''advoc'':387 ''also'':