INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1225', '2', '1225', NULL, 'Wherefore - See 1 Thessalonians 2:18. This particle (&#x3b4;&#x3b9;&#x3bf;  dio) is designed here to refer to another proof of his affection for them. One evidence had been referred to in his strong desire to visit them, which he had been unable to accomplish 1 Thessalonians 2:18, and he here refers to another - to wit, the fact that he had sent Timothy to them.We could no longer forbear - That is, when I could not 1 Thessalonians 3:5, for there is every evidence that Paul refers to himself only though he uses the plural form of the word. There was no one with him at Athens after he had sent Timothy away Acts 17:15; Acts 18:5, and this shows that when, in 1 Thessalonians 2:6, he uses the term apostles in the plural number, he refers to himself only, and does not mean to give the name to Timothy and Silas. If this be so, Timothy and Silas are nowhere called "apostles" in the New Testament. The word rendered here "could forbear" (&#x3c3;&#x3c4;&#x3b5;&#x3b3;&#x3bf;&#x3bd;&#x3c4;&#x3b5;&#x3c2;  stegontes), means, properly, "to cover, to conceal;" and then to hide or conceal anger, impatience, weariness, etc.; that is, to hold out as to anything, to bear with, to endure. It is rendered suffer in 1 Corinthians 9:12; beareth, 1 Corinthians 13:7; and forbear, 1 Thessalonians 3:1, 1 Thessalonians 3:5. It is not elsewhere used in the New Testament. It means that he could no longer bear up under, hide, or suppress his impatience in regard to them - his painful emotions - his wish to know of their state; and he therefore sent Timothy to them.We thought it good - I was willing to suffer the inconvenience of parting with him in order to show my concern for you.To be left at Athens alone - Paul had been conducted to Athens from Berea, where he remained until Silas and Timothy could come to him; Acts 17:15. It appears from the statement here that Timothy had joined him there, but such was his solicitude for the church at Thessalonica, that he very soon after sent him there, and chose to remain himself alone at Athens. Why he did not himself return to Thessalonica, is not stated. It is evidently implied here that it was a great personal inconvenience for him thus to part with Timothy, and to remain alone at Athens, and that he evinced the strong love which he had for the church at Thessalonica by being willing to submit to it. What that inconvenience consisted in, he has not stated, but it is not difficult to understand,(1) he was among total strangers, and, when Timothy was gone, without an acquaintance or friend.(2) the aid of Timothy was needed in order to prosecute the work which he contemplated. He had requested that Timothy should join him as soon as possible when he left Berea Acts 17:15, and he evidently felt it desirable that in preaching the gospel in that city he should have all the assistance he could obtain. Yet he was willing to forego those comforts and advantages in order to promote the edification of the church at Thessalonica.', NULL, NULL, '''1'':3,43,74,124,210,215,221,224,225,435 ''12'':213 ''13'':217 ''15'':114,322,485 ''17'':113,321,484 ''18'':6,46,116 ''2'':5,45,126,451 ''3'':76,223,227 ''5'':77,117,228 ''6'':127 ''7'':218 ''9'':212 ''accomplish'':42 ''acquaint'':448 ''act'':112,115,320,483 ''advantag'':518 ''affect'':20 ''aid'':453 ''alon'':300,358,394 ''among'':438 ''anger'':188 ''anoth'':16,52 ''anyth'':199 ''apostl'':132,164 ''appear'':324 ''assist'':505 ''athen'':105,299,306,360,396 ''away'':111 ''bear'':201,245 ''beareth'':214 ''berea'':308,482 ''call'':163 ''chose'':354 ''church'':342,409,527 ''citi'':499 ''come'':317 ''comfort'':516 ''conceal'':181,187 ''concern'':293 ''conduct'':304 ''consist'':422 ''contempl'':466 ''corinthian'':211,216 ''could'':64,72,173,242,316,507 ''cover'':179 ''design'':11 ''desir'':32,491 ''difficult'':432 ''dio'':9 ''edif'':524 ''elsewher'':232 ''emot'':259 ''endur'':204 ''etc'':191 ''everi'':81 ''evid'':24,82,374,488 ''evinc'':400 ''fact'':56 ''felt'':489 ''forbear'':67,174,220 ''forego'':514 ''form'':94 ''friend'':450 ''give'':147 ''gone'':445 ''good'':276 ''gospel'':496 ''great'':381 ''hide'':185,248 ''hold'':195 ''impati'':189,252 ''impli'':375 ''inconveni'':283,383,421 ''join'':332,473 ''know'':263 ''left'':297,481 ''longer'':66,244 ''love'':403 ''mean'':145,176,239 ''name'':149 ''need'':457 ''new'':167,236 ''nowher'':162 ''number'':136 ''obtain'':508 ''one'':23,101 ''order'':289,459,520 ''pain'':258 ''part'':285,388 ''particl'':8 ''paul'':84,301 ''person'':382 ''plural'':93,135 ''possibl'':478 ''preach'':494 ''promot'':522 ''proof'':17 ''proper'':177 ''prosecut'':461 ''refer'':14,27,50,85,138 ''regard'':254 ''remain'':311,356,393 ''render'':171,207 ''request'':469 ''return'':366 ''see'':2 ''sent'':60,109,270,350 ''show'':120,291 ''sila'':153,160,313 ''solicitud'':339 ''soon'':348,476 ''state'':266,371,427 ''statement'':327 ''stegont'':175 ''stranger'':440 ''strong'':31,402 ''submit'':416 ''suffer'':208,281 ''suppress'':250 ''term'':131 ''testament'':168,237 ''them.we'':63,273 ''therefor'':269 ''thessalonian'':4,44,75,125,222,226 ''thessalonica'':344,368,411,529 ''though'':89 ''thought'':274 ''thus'':386 ''timothi'':61,110,151,158,271,315,330,390,443,455,471 ''total'':439 ''unabl'':40 ''understand'':434 ''use'':91,129,233 ''visit'':34 ''weari'':190 ''wherefor'':1 ''will'':279,414,512 ''wish'':261 ''wit'':54 ''without'':446 ''word'':97,170 ''work'':463 ''yet'':509 ''you.to'':295', NULL, '1114');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1226', '2', '1226', NULL, 'Furthermore then - &#x3a4;&#x3bf; &#x3bb;&#x3bf;&#x3b9;&#x3c0;&#x3bf;&#x3bd;  To loipon. "As to what remains." That is, all that remains is to offer these exhortations; see the 2 Corinthians 13:11 note; Galatians 6:17 note; Ephesians 6:10 note; Philippians 4:8 note. The phrase is a formula appropriate to the end of an argument or discourse.We beseech you - Margin, "request." The Greek is, "we ask you" -  &#x3b5;&#x3c1;&#x3c9;&#x3c4;&#x3c9;&#x3bc;&#x3b5;&#x3bd;  erotomen. It is not as strong a word as that which follows.And exhort you - Marg, "beseech." This is the word which is commonly used to denote earnest exhortation. The use of these words here implies that Paul regarded the subject as of great importance. He might have commanded them - but kind exhortation usually accomplishes more than a command,By the Lord Jesus - In his name and by his authority.That as ye have received of us - As you were taught by us. Paul doubtless had given them repeated instructions as to their duty as Christians.How ye ought to walk - That is, how ye ought to live. Life is often represented as a journey; Romans 6:4; Romans 8:1; 1 Corinthians 5:7; Galatians 6:16, Ephesians 4:1.So ye would abound more and more - "That is, follow the directions which they had received more and more fully." Abbott.', NULL, NULL, '''1'':179,180 ''1.so'':189 ''10'':32 ''11'':24 ''13'':23 ''16'':186 ''17'':28 ''2'':21 ''4'':35,176,188 ''5'':182 ''6'':27,31,175,185 ''7'':183 ''8'':36,178 ''abbott'':209 ''abound'':192 ''accomplish'':115 ''appropri'':43 ''argument'':49 ''ask'':60 ''authority.that'':130 ''beseech'':52,77 ''christians.how'':155 ''command'':109,119 ''common'':84 ''corinthian'':22,181 ''denot'':87 ''direct'':200 ''discourse.we'':51 ''doubtless'':144 ''duti'':153 ''earnest'':88 ''end'':46 ''ephesian'':30,187 ''erotomen'':62 ''exhort'':18,74,89,113 ''follow'':198 ''follows.and'':73 ''formula'':42 ''fulli'':208 ''furthermor'':1 ''galatian'':26,184 ''given'':146 ''great'':104 ''greek'':57 ''impli'':96 ''import'':105 ''instruct'':149 ''jesus'':123 ''journey'':173 ''kind'':112 ''life'':167 ''live'':166 ''loipon'':4 ''lord'':122 ''marg'':76 ''margin'':54 ''might'':107 ''name'':126 ''note'':25,29,33,37 ''offer'':16 ''often'':169 ''ought'':157,164 ''paul'':98,143 ''philippian'':34 ''phrase'':39 ''receiv'':134,204 ''regard'':99 ''remain'':8,13 ''repeat'':148 ''repres'':170 ''request'':55 ''roman'':174,177 ''see'':19 ''strong'':67 ''subject'':101 ''taught'':140 ''us'':136,142 ''use'':85,91 ''usual'':114 ''walk'':159 ''word'':69,81,94 ''would'':191 ''ye'':132,156,163,190', NULL, '1115');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1227', '2', '1227', NULL, 'But of the times and the seasons - See the notes, Acts 1:7. The reference here is to the coming of the Lord Jesus, and to the various events connected with his advent; see the close of 1 Thessalonians 4.Ye have no need that I write unto you - That is, they had received all the information on the particular point to which he refers, which it was necessary they should have. He seems to refer particularly to the suddenness of his coming. It is evident from this, as well as from other parts of this Epistle, that this had been, from some cause, a prominent topic which he had dwelt on when he was with them; see the notes on 1 Thessalonians 1:10.', NULL, NULL, '''1'':12,38,121,123 ''10'':124 ''4.ye'':40 ''7'':13 ''act'':11 ''advent'':33 ''caus'':103 ''close'':36 ''come'':20,82 ''connect'':30 ''dwelt'':110 ''epistl'':96 ''event'':29 ''evid'':85 ''inform'':56 ''jesus'':24 ''lord'':23 ''necessari'':68 ''need'':43 ''note'':10,119 ''part'':93 ''particular'':59,76 ''point'':60 ''promin'':105 ''receiv'':53 ''refer'':15,64,75 ''season'':7 ''see'':8,34,117 ''seem'':73 ''sudden'':79 ''thessalonian'':39,122 ''time'':4 ''topic'':106 ''unto'':47 ''various'':28 ''well'':89 ''write'':46', NULL, '1116');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1228', '2', '1228', NULL, 'We are bound to thank God always for you; - See the notes on 1 Thessalonians 1:2. "As it is meet." Since it is fit or proper. "Because that your faith groweth exceedingly." It would seem probable from this that Paul had heard from them since his First Epistle was written. He had doubtless received intelligence of the error which prevailed among them respecting his views of the coming of the Lord Jesus, and of the progress which the truth was making, at the same time. "And the charity of every one of you all toward each other." Your mutual love.', NULL, NULL, '''1'':14,16 ''2'':17 ''alway'':7 ''among'':62 ''bound'':3 ''chariti'':89 ''come'':69 ''doubtless'':54 ''epistl'':49 ''error'':59 ''everi'':91 ''exceed'':33 ''faith'':31 ''first'':48 ''fit'':25 ''god'':6 ''groweth'':32 ''heard'':43 ''intellig'':56 ''jesus'':73 ''lord'':72 ''love'':101 ''make'':82 ''meet'':21 ''mutual'':100 ''note'':12 ''one'':92 ''paul'':41 ''prevail'':61 ''probabl'':37 ''progress'':77 ''proper'':27 ''receiv'':55 ''respect'':64 ''see'':10 ''seem'':36 ''sinc'':22,46 ''thank'':5 ''thessalonian'':15 ''time'':86 ''toward'':96 ''truth'':80 ''view'':66 ''would'':35 ''written'':51', NULL, '1117');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1229', '2', '1229', NULL, 'Now we beseech you, brethren, by the coming of our Lord Jesus Christ - The phrase "by the coming," is not here, as our translators seem to have supposed, a form of solemn adjuration. It is not common, if it ever occurs, in the Scriptures, to make a solemn adjuration in view of an event, and the connection here demands that we give to the phrase a different sense. It means, respecting his coming; and the idea of Paul is: "In regard to that great event of which I spoke to you in my former epistle - the coming of the Saviour - I beseech you not to be troubled, as if it were soon to happen. As his views had been misunderstood or misrepresented, he now proposes to show them that there was nothing in the true doctrine which should create alarm, as if he were about to appear.And by our gathering together unto him - There is manifest allusion here to what is said in the First Epistle 1 Thessalonians 4:17, "then we shall be caught up together with them in the clouds;" and the meaning is: "in reference to our being gathered unto him, I beseech you not to be shaken in mind, as if that event were near."', NULL, NULL, '''1'':167 ''17'':170 ''4'':169 ''adjur'':33,49 ''alarm'':140 ''allus'':157 ''appear.and'':147 ''beseech'':3,102,196 ''brethren'':5 ''caught'':175 ''christ'':13 ''cloud'':182 ''come'':8,18,73,97 ''common'':37 ''connect'':57 ''creat'':139 ''demand'':59 ''differ'':67 ''doctrin'':136 ''epistl'':95,166 ''event'':54,85,207 ''ever'':40 ''first'':165 ''form'':30 ''former'':94 ''gather'':150,192 ''give'':62 ''great'':84 ''happen'':114 ''idea'':76 ''jesus'':12 ''lord'':11 ''make'':46 ''manifest'':156 ''mean'':70,185 ''mind'':203 ''misrepres'':122 ''misunderstood'':120 ''near'':209 ''noth'':132 ''occur'':41 ''paul'':78 ''phrase'':15,65 ''propos'':125 ''refer'':188 ''regard'':81 ''respect'':71 ''said'':162 ''saviour'':100 ''scriptur'':44 ''seem'':25 ''sens'':68 ''shaken'':201 ''shall'':173 ''show'':127 ''solemn'':32,48 ''soon'':112 ''spoke'':89 ''suppos'':28 ''thessalonian'':168 ''togeth'':151,177 ''translat'':24 ''troubl'':107 ''true'':135 ''unto'':152,193 ''view'':51,117', NULL, '1118');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1230', '2', '1230', NULL, 'Finally, brethren, pray for us - That is, for Paul, Silas, and Timothy, then engaged in arduous labors at Corinth. This request for the prayers of Christians is one which Paul often makes; see the notes, 1 Thessalonians 5:25.That the word of the Lord may have free course - That is, the gospel. The margin is "run." So also the Greek. The idea is, that it might meet with no obstruction, but that it might be carried abroad with the rapidity of a racer out of whose way every hindrance was removed. The gospel would spread rapidly in the earth if all the obstructions which men have put in its way were removed; and that they may be removed should be one of the constant subjects of prayer.And be glorified - Be honored; or appear to be glorious.As it is with you - It is evident from this that Paul met with some obstructions in preaching the gospel where he was then laboring. What they were, he mentions in the next verse. He was then at Corinth (see the introduction), and the history in the Acts of the Apostles informs us of the difficulties which he had to encounter there; see Acts 18.', NULL, NULL, '''1'':36 ''18'':200 ''25.that'':39 ''5'':38 ''abroad'':77 ''act'':183,199 ''also'':58 ''apostl'':186 ''appear'':133 ''arduous'':16 ''brethren'':2 ''carri'':76 ''christian'':26 ''constant'':124 ''corinth'':19,174 ''cours'':48 ''difficulti'':191 ''earth'':99 ''encount'':196 ''engag'':14 ''everi'':88 ''evid'':143 ''final'':1 ''free'':47 ''glorifi'':129 ''glorious.as'':136 ''gospel'':52,93,155 ''greek'':60 ''hindranc'':89 ''histori'':180 ''honor'':131 ''idea'':62 ''inform'':187 ''introduct'':177 ''labor'':17,160 ''lord'':44 ''make'':32 ''margin'':54 ''may'':45,116 ''meet'':67 ''men'':105 ''mention'':165 ''met'':148 ''might'':66,74 ''next'':168 ''note'':35 ''obstruct'':70,103,151 ''often'':31 ''one'':28,121 ''paul'':9,30,147 ''pray'':3 ''prayer'':24 ''prayer.and'':127 ''preach'':153 ''put'':107 ''racer'':83 ''rapid'':80,96 ''remov'':91,112,118 ''request'':21 ''run'':56 ''see'':33,175,198 ''sila'':10 ''spread'':95 ''subject'':125 ''thessalonian'':37 ''timothi'':12 ''us'':5,188 ''vers'':169 ''way'':87,110 ''whose'':86 ''word'':41 ''would'':94', NULL, '1119');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1235', '2', '1235', NULL, 'Rebuke not an elder - The word "elder" here is not used in the sense in which it often is, to denote an officer of the church, a presbyter, but in its proper and usual sense, to denote an aged man. This is evident, because the apostle immediately mentions in contradistinction from the elder, "the younger men," where it cannot be supposed that he refers to them as officers. The command to treat the "elder" as a "father," also shows the same thing. By the direction not to rebuke, it is not to be supposed that the minister of the gospel is not to admonish the aged, or that he is not to show them their sins when they go astray, but that he is to do this as he would to a father. He is not to assume a harsh, dictatorial, and denunciatory manner. The precepts of religion always respect the proprieties of life, and never allow us to transgress them, even when the object is to reclaim a soul from error, and to save one who is wandering. Besides, when this is the aim, it will always be most certainly accomplished by observing the respect due to others on account of office, relation, rank, or age.But entreat him as a father - As you would a father. That is, do not harshly denounce him. Endeavor to persuade him to lead a more holy life. One of the things for which the ancients were remarkable above most of the moderns, and for which the Orientals are still distinguished, was respect for age. Few things are enjoined with more explicitness and emphasis in the Bible than this; Leviticus 19:32; Job 29; Proverbs 20:20; Proverbs 30:17; compare Daniel 7:9-10; Revelation 1:14-15. The apostle would have Timothy, and, for the same reason, every other minister of the gospel, a model of this virtue.And the younger men as brethren - That is, treat them as you would your own brothers. Do not consider them as aliens, strangers, or enemies, but entertain toward them, even when they go astray, the kindly feelings of a brother. This refers more particularly to his private conversation with them, and to his personal efforts to reclaim them when they had fallen into sin. When these efforts were ineffectual, and they sinned openly, he was to "rebuke them before all" 1 Timothy 5:20, that others might be deterred from following their example.', NULL, NULL, '''-10'':291 ''-15'':295 ''1'':293,396 ''14'':294 ''17'':286 ''19'':277 ''20'':282,283,399 ''29'':280 ''30'':285 ''32'':278 ''5'':398 ''7'':289 ''9'':290 ''accomplish'':192 ''account'':201 ''admonish'':104 ''age'':39,106,261 ''age.but'':207 ''aim'':185 ''alien'':337 ''allow'':157 ''also'':78 ''alway'':149,188 ''ancient'':242 ''apostl'':46,297 ''assum'':138 ''astray'':120,349 ''besid'':180 ''bibl'':273 ''brethren'':321 ''brother'':331,355 ''cannot'':59 ''certain'':191 ''church'':26 ''command'':70 ''compar'':287 ''consid'':334 ''contradistinct'':50 ''convers'':363 ''daniel'':288 ''denot'':21,37 ''denounc'':223 ''denunciatori'':143 ''deter'':404 ''dictatori'':141 ''direct'':85 ''distinguish'':257 ''due'':197 ''effort'':370,382 ''elder'':4,7,53,74 ''emphasi'':270 ''endeavor'':225 ''enemi'':340 ''enjoin'':265 ''entertain'':342 ''entreat'':208 ''error'':172 ''even'':162,345 ''everi'':306 ''evid'':43 ''exampl'':408 ''explicit'':268 ''fallen'':377 ''father'':77,133,212,217 ''feel'':352 ''follow'':406 ''go'':119,348 ''gospel'':100,311 ''harsh'':140,222 ''holi'':233 ''immedi'':47 ''ineffectu'':384 ''job'':279 ''kind'':351 ''lead'':230 ''leviticus'':276 ''life'':154,234 ''man'':40 ''manner'':144 ''men'':56,319 ''mention'':48 ''might'':402 ''minist'':97,308 ''model'':313 ''modern'':249 ''never'':156 ''object'':165 ''observ'':194 ''offic'':23,68,203 ''often'':18 ''one'':176,235 ''open'':388 ''orient'':254 ''other'':199,401 ''particular'':359 ''person'':369 ''persuad'':227 ''precept'':146 ''presbyt'':28 ''privat'':362 ''proper'':32 ''proprieti'':152 ''proverb'':281,284 ''rank'':205 ''reason'':305 ''rebuk'':1,88,392 ''reclaim'':168,372 ''refer'':64,357 ''relat'':204 ''religion'':148 ''remark'':244 ''respect'':150,196,259 ''revel'':292 ''save'':175 ''sens'':14,35 ''show'':79,113 ''sin'':116,379,387 ''soul'':170 ''still'':256 ''stranger'':338 ''suppos'':61,94 ''thing'':82,238,263 ''timothi'':300,397 ''toward'':343 ''transgress'':160 ''treat'':72,324 ''us'':158 ''use'':11 ''usual'':34 ''virtue.and'':316 ''wander'':179 ''word'':6 ''would'':130,215,298,328 ''younger'':55,318', NULL, '1124');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1236', '2', '1236', NULL, 'Let as many servants - On the word here rendered "servants" - &#x3b4;&#x3bf;&#x3c5;&#x3bb;&#x3bf;&#x3b9;  douloi - see the notes on Ephesians 6:5. The word is that which was commonly applied to a slave, but it is so extensive in its signification as to be applicable to any species of servitude, whether voluntary or involuntary. If slavery existed in Ephesus at the time when this Epistle was written, it would be applicable to slaves; if any other kind of servitude existed, the word would be equally applicable to that. There is nothing in the word itself which essentially limits it to slavery; examine Matthew 13:27; Matthew 20:27; Mark 10:44; Luke 2:29; John 15:15; Acts 2:18; Acts 4:29; Acts 16:17; Romans 1:1; 2 Corinthians 4:5; Jde 1:1; Revelation 1:1; Revelation 2:20; Revelation 7:3. The addition of the phrase "under the yoke," however, shows undoubtedly that it is to be understood here of slavery.As are under the yoke - On the word yoke, see the notes on Matthew 11:29. The phrase here properly denotes slavery, as it would not be applied to any other species of servitude; see Leviticus 26:13; Dem. 322, 12. &#x3b6;&#x3b5;&#x3c5;&#x3b3;&#x3bf;&#x3c2; &#x3b4;&#x3bf;&#x3c5;&#x3bb;&#x3bf;&#x3c3;&#x3c5;&#x3bd;&#x3b7;&#x3c2;  zeugos doulosunes. Robinson''s Lexicon. It sometimes denotes the bondage of the Mosaic law as being a severe and oppressive burden; Acts 15:10; Galatians 5:1. It may be remarked here that the apostle did not regard slavery as a light or desirable thing. He would not have applied this term to the condition of a wife or of a child.Count their own masters worthy of all honour - Treat them with all proper respect. They were to manifest the right spirit themselves, whatever their masters did; they were not to do anything that would dishonor religion. The injunction here would seem to have particular reference to those whose masters were not Christians. In the following verse, the apostle gives particular instructions to those who had pious masters. The meaning here is, that the slave ought to show the Christian spirit toward his master who was not a Christian; he ought to conduct himself so that religion would not be dishonored; he ought not to give his master occasion to say that the only effect of the Christian religion on the mind of a servant was to make him restless, discontented, dissatisfied, and disobedient. In the humble and trying situation in which he confessedly was - under the yoke of bondage - he ought to evince patience, kindness, and respect for his master, and as long as the relation continued he was to be obedient. This command, however, was by no means inconsistent with his desiring his freedom, and securing it, if the opportunity presented itself; see the notes on 1 Corinthians 7:21; compare, on the passage before us, the Ephesians 6:5-8 notes, and 1 Peter 2:18 note.That the name of God and his doctrine be not blasphemed - That religion be not dishonored and reproached, and that there may be no occasion to say that Christianity tends to produce discontent and to lead to insurrection. If the effect of religion had been to teach all who were servants that they should no longer obey their masters, or that they should rise upon them and assert their freedom by violence, or that their masters were to be treated with indignity on account of their usurped rights over others, the effect would have been obvious. There would have been a loud and united outcry against the new religion, and it could have made no progress in the world. Instead of this, Christianity taught the necessity of patience, and meekness, and forbearance in the endurance of all wrong - whether from private individuals Matthew 5:39-41; 1 Corinthians 6:7, or under the oppressions and exactions of Nero Romans 13:1-7, or amidst the hardships and cruelties of slavery. These peaceful injunctions, however, did not demonstrate that Christ approved the act of him "that smote on the one cheek," or that Paul regarded the government of Nero as a good government, - and as little do they prove that Paul or the Saviour approved of slavery.', NULL, NULL, '''-41'':626 ''-7'':642 ''-8'':474 ''1'':124,125,131,132,134,135,228,460,477,627,641 ''10'':106,225 ''11'':175 ''12'':201 ''13'':100,198,640 ''15'':112,113,224 ''16'':121 ''17'':122 ''18'':116,480 ''2'':109,115,126,137,479 ''20'':103,138 ''21'':463 ''26'':197 ''27'':101,104 ''29'':110,119,176 ''3'':141 ''322'':200 ''39'':625 ''4'':118,128 ''44'':107 ''5'':18,129,227,473,624 ''6'':17,472,629 ''7'':140,462,630 ''account'':564 ''act'':114,117,120,223,662 ''addit'':143 ''amidst'':644 ''anyth'':294 ''apostl'':236,320 ''appli'':26,188,251 ''applic'':41,67,82 ''approv'':660,694 ''assert'':548 ''blasphem'':491 ''bondag'':211,411 ''burden'':222 ''cheek'':670 ''child.count'':263 ''christ'':659 ''christian'':314,341,350,379,509,603 ''command'':436 ''common'':25 ''compar'':464 ''condit'':256 ''conduct'':354 ''confess'':405 ''continu'':429 ''corinthian'':127,461,628 ''could'':592 ''cruelti'':648 ''dem'':199 ''demonstr'':657 ''denot'':181,209 ''desir'':245,445 ''discont'':392,513 ''dishonor'':297,362,496 ''disobedi'':395 ''dissatisfi'':393 ''doctrin'':488 ''douloi'':11 ''doulosun'':203 ''effect'':376,521,572 ''endur'':615 ''ephesian'':16,471 ''ephesus'':55 ''epistl'':61 ''equal'':81 ''essenti'':93 ''evinc'':415 ''exact'':636 ''examin'':98 ''exist'':53,76 ''extens'':34 ''follow'':317 ''forbear'':612 ''freedom'':447,550 ''galatian'':226 ''give'':321,367 ''god'':485 ''good'':681 ''govern'':676,682 ''hardship'':646 ''honour'':270 ''howev'':150,437,654 ''humbl'':398 ''inconsist'':442 ''indign'':562 ''individu'':622 ''injunct'':300,653 ''instead'':600 ''instruct'':323 ''insurrect'':518 ''involuntari'':50 ''jde'':130 ''john'':111 ''kind'':73,417 ''law'':215 ''lead'':516 ''let'':1 ''leviticus'':196 ''lexicon'':206 ''light''