INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1252', '2', '1252', NULL, 'Now of the things which we have spoken - Or, "of the things of which we are speaking" (Stuart); or as we should say, "of what is said." The Greek does not necessarily mean things that "had been" spoken, but may refer to all that he was saying, taking the whole subject into consideration.This is the sum - Or this is the principal thing; referring to what he was about to say, not what he had said. Our translators seem to have understood this as referring to a "summing up," or recapitulation of what he had said, and there can be no doubt that the Greek would bear this interpretation. But another exposition has been proposed, adopted by Bloomfield, Stuart, Michaelis, and Storr, among the moderns, and found also in Suidas, Theodoret, Theophylact, and others, among the ancients. It is what regards the word rendered "sum" - &#x3ba;&#x3b5;&#x3c6;&#x3b1;&#x3bb;&#x3b1;&#x3b9;&#x3bf;&#x3bd;  kephalaion - as meaning the "principal thing;" the chief matter; the most important point. The reason for this interpretation is, that the apostle in fact goes into no recapitulation of what he had said, but enters on a new topic relating to the priesthood of Christ. Instead of going over what he had demonstrated, he enters on a more important point, that the priesthood of Christ is performed in heaven, and that he has entered into the true tabernacle there. All which preceded was type and shadow; this was that which the former economy had adumbrated. In the previous chapters the apostle had shown that he who sustained this office was superior in rank to the Jewish priests; that they were frail and dying, and that the office in their hands was changing from one to another, but that that of Christ was permanent and abiding. He now comes to consider the real nature of the office itself; the sacrifice which was offered; the substance of which all in the former dispensation was the type. This was the "principal thing" - &#x3ba;&#x3b5;&#x3c6;&#x3b1;&#x3bb;&#x3b1;&#x3b9;&#x3bf;&#x3bd;  kephalaion - the "head," the most important matter; and the consideration of this is pursued through theHeb 8:1, Hebrews 9:1, and Hebrews 10:1 chapters Hebrews 8-10.We have such an high priest - That is settled; proved; indisputable. The Christian system is not destitute of what was regarded as so essential to the old dispensation - the office of a high priest.Who is set on the right hand of a throne ... - He is exalted to honor and glory before God. The right hand was regarded as the place of principal honor, and when it is said that Christ is at the right hand of God, the meaning is, that he is exalted to the highest honor in the universe; see the note at Mark 16:19. Of course the language is figurative - as God has no hands literally - but the language conveys an important meaning, that he is near to God; is high in his affection and love, and is raised to the most elevated situation in heaven; see Philippians 2:9; notes Ephesians 1:21-22.', NULL, NULL, '''-22'':499 ''1'':341,344,348,497 ''10'':347 ''16'':447 ''19'':448 ''2'':493 ''21'':498 ''8'':340 ''8-10.we'':351 ''9'':343,494 ''abid'':289 ''adopt'':115 ''adumbr'':239 ''affect'':478 ''also'':127 ''among'':122,134 ''ancient'':136 ''anoth'':110,280 ''apostl'':166,245 ''bear'':106 ''bloomfield'':117 ''chang'':276 ''chapter'':243,349 ''chief'':152 ''christ'':189,209,285,420 ''christian'':363 ''come'':292 ''consid'':294 ''consider'':333 ''consideration.this'':53 ''convey'':464 ''cours'':450 ''demonstr'':197 ''destitut'':367 ''die'':267 ''dispens'':315,378 ''doubt'':101 ''economi'':237 ''elev'':487 ''enter'':179,199,218 ''ephesian'':496 ''essenti'':374 ''exalt'':396,434 ''exposit'':111 ''fact'':168 ''figur'':454 ''former'':236,314 ''found'':126 ''frail'':265 ''glori'':400 ''go'':192 ''god'':402,427,456,473 ''goe'':169 ''greek'':29,104 ''hand'':274,390,405,425,459 ''head'':326 ''heaven'':213,490 ''hebrew'':342,346,350 ''high'':355,383,475 ''highest'':437 ''honor'':398,413,438 ''import'':156,203,329,466 ''indisput'':361 ''instead'':190 ''interpret'':108,162 ''jewish'':260 ''kephalaion'':145,324 ''languag'':452,463 ''liter'':460 ''love'':480 ''mark'':446 ''matter'':153,330 ''may'':40 ''mean'':33,147,429,467 ''micha'':119 ''modern'':124 ''natur'':297 ''near'':471 ''necessarili'':32 ''new'':182 ''note'':444,495 ''offer'':306 ''offic'':253,271,300,380 ''old'':377 ''one'':278 ''other'':133 ''perform'':211 ''perman'':287 ''philippian'':492 ''place'':410 ''point'':157,204 ''preced'':226 ''previous'':242 ''priest'':261,356 ''priest.who'':384 ''priesthood'':187,207 ''princip'':61,149,322,412 ''propos'':114 ''prove'':360 ''pursu'':337 ''rais'':483 ''rank'':257 ''real'':296 ''reason'':159 ''recapitul'':90,172 ''refer'':41,63,84 ''regard'':140,371,407 ''relat'':184 ''render'':143 ''right'':389,404,424 ''sacrific'':303 ''said'':27,75,95,177,418 ''say'':23,47,70 ''see'':442,491 ''seem'':78 ''set'':386 ''settl'':359 ''shadow'':230 ''shown'':247 ''situat'':488 ''speak'':17 ''spoken'':8,38 ''storr'':121 ''stuart'':18,118 ''subject'':51 ''substanc'':308 ''suida'':129 ''sum'':56,87,144 ''superior'':255 ''sustain'':251 ''system'':364 ''tabernacl'':222 ''take'':48 ''theheb'':339 ''theodoret'':130 ''theophylact'':131 ''thing'':4,12,34,62,150,323 ''throne'':393 ''topic'':183 ''translat'':77 ''true'':221 ''type'':228,318 ''understood'':81 ''univers'':441 ''whole'':50 ''word'':142 ''would'':105', NULL, '1141');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1253', '2', '1253', NULL, 'Then verily - Or, moreover. The object is to describe the tabernacle in which the service of God was celebrated under the former dispensation, and to show that it had a reference to what was future, and was only an imperfect representation of the reality. It was important to show this, as the Jews regarded the ordinances of the tabernacle and of the whole Levitical service as of divine appointment, and of perpetual obligation. The object of Paul is to prove that they were to give place to a more perfect system, and hence, it was necessary to discuss their real nature.The first covenant - The word "covenant" is not in the Greek, but is not improperly supplied. The meaning is, that the former arrangement or dispensation had religious rites and services connected with it.Had also ordinances - Margin, "Ceremonies." The Greek word means "laws, precepts, ordinances;" and the idea is, that there were laws regulating the worship of God. The Jewish institutions abounded with such laws.And a worldly sanctuary - The word "sanctuary" means a holy place, and is applied to a house of worship, or a temple. Here it may refer either to the temple or to the tabernacle. As the temple was constructed after the same form as the tabernacle, and had the same furniture, the description of the apostle may be regarded as applicable to either of them, and it is difficult to determine which he had in his eye. The term "worldly," applied to "sanctuary," here means that it pertained to this world; it was contradistinguished from the heavenly sanctuary not made with hands where Christ was now gone; compare Hebrews 9:11-24. It does not mean that it was "worldly" in the sense in which that word is now used as denoting the opposite of spiritual, serious, religious; but worldly in the sense that it belonged to the earth rather than to heaven; it was made by human hands, not directly by the hands of God.', NULL, NULL, '''-24'':275 ''11'':274 ''9'':273 ''abound'':161 ''also'':134 ''apostl'':219 ''appli'':177,244 ''applic'':224 ''appoint'':69 ''arrang'':123 ''belong'':309 ''celebr'':19 ''ceremoni'':137 ''christ'':267 ''compar'':271 ''connect'':131 ''construct'':202 ''contradistinguish'':257 ''coven'':103,106 ''denot'':295 ''describ'':9 ''descript'':216 ''determin'':234 ''difficult'':232 ''direct'':324 ''discuss'':98 ''dispens'':23,125 ''divin'':68 ''earth'':312 ''either'':190,226 ''eye'':240 ''first'':102 ''form'':206 ''former'':22,122 ''furnitur'':214 ''futur'':35 ''give'':85 ''god'':17,157,329 ''gone'':270 ''greek'':111,139 ''hand'':265,322,327 ''heaven'':260,316 ''hebrew'':272 ''henc'':93 ''holi'':173 ''hous'':180 ''human'':321 ''idea'':147 ''imperfect'':40 ''import'':47 ''improp'':115 ''institut'':160 ''it.had'':133 ''jew'':53 ''jewish'':159 ''law'':142,152 ''laws.and'':164 ''levit'':64 ''made'':263,319 ''margin'':136 ''may'':188,220 ''mean'':118,141,171,248,279 ''moreov'':4 ''nature.the'':101 ''necessari'':96 ''object'':6,75 ''oblig'':73 ''opposit'':297 ''ordin'':56,135,144 ''paul'':77 ''perfect'':90 ''perpetu'':72 ''pertain'':251 ''place'':86,174 ''precept'':143 ''prove'':80 ''rather'':313 ''real'':100 ''realiti'':44 ''refer'':31,189 ''regard'':54,222 ''regul'':153 ''religi'':127,301 ''represent'':41 ''rite'':128 ''sanctuari'':167,170,246,261 ''sens'':286,306 ''serious'':300 ''servic'':15,65,130 ''show'':26,49 ''spiritu'':299 ''suppli'':116 ''system'':91 ''tabernacl'':11,59,197,209 ''templ'':185,193,200 ''term'':242 ''use'':293 ''verili'':2 ''whole'':63 ''word'':105,140,169,290 ''world'':166,243,254,283,303 ''worship'':155,182', NULL, '1142');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('210', '2', '210', NULL, 'This and the next chapter contain the last addresses of Joshua. These addresses were no doubt among the closing acts of Joshua''s life, but were evidently given on different occasions, and are of different character and scope. In the former Joshua briefly reminds the princes of the recent benefits of God toward them and their people, declares that God had fulfilled all His promises, and exhorts to faithfulness on their side to God that so His mercies may not be withdrawn: in the latter he takes a wider range, rehearses the gracious dealings of God with the nation from its very origin, and upon these as his grounds, he claims for God their sincere and entire service. But he grants them the option of withdrawing from the covenant if they so choose; and when they elect still to abide by it, it is solemnly renewed by the free consent of the whole people. Joshua''s reproofs and warnings are in sum and substance identical with those with which Moses closed his career (Deuteronomy 31, etc.). Compare throughout the marginal references.', NULL, NULL, '''31'':175 ''abid'':140 ''act'':20 ''address'':9,13 ''among'':17 ''benefit'':50 ''briefli'':43 ''career'':173 ''chapter'':5 ''charact'':36 ''choos'':133 ''claim'':111 ''close'':19,171 ''compar'':177 ''consent'':150 ''contain'':6 ''coven'':129 ''deal'':94 ''declar'':58 ''deuteronomi'':174 ''differ'':30,35 ''doubt'':16 ''elect'':137 ''entir'':117 ''etc'':176 ''evid'':27 ''exhort'':67 ''faith'':69 ''former'':41 ''free'':149 ''fulfil'':62 ''given'':28 ''god'':52,60,74,96,113 ''gracious'':93 ''grant'':121 ''ground'':109 ''ident'':165 ''joshua'':11,22,42,155 ''last'':8 ''latter'':85 ''life'':24 ''margin'':180 ''may'':79 ''merci'':78 ''mose'':170 ''nation'':99 ''next'':4 ''occas'':31 ''option'':124 ''origin'':103 ''peopl'':57,154 ''princ'':46 ''promis'':65 ''rang'':90 ''recent'':49 ''refer'':181 ''rehears'':91 ''remind'':44 ''renew'':146 ''reproof'':157 ''scope'':38 ''servic'':118 ''side'':72 ''sincer'':115 ''solemn'':145 ''still'':138 ''substanc'':164 ''sum'':162 ''take'':87 ''throughout'':178 ''toward'':53 ''upon'':105 ''warn'':159 ''whole'':153 ''wider'':89 ''withdraw'':126 ''withdrawn'':82', NULL, '210');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1254', '2', '1254', NULL, 'For the law having a shadow - That is, the whole of the Mosaic economy was a shadow; for so the word "Law" is often used. The word "shadow" here refers to a rough outline of anything, a mere sketch, such as a carpenter draws with a piece of chalk, or such as an artist delineates when he is about to make a picture. He sketches an outline of the object which he designs to draw, which has "some" resemblance to it, but is not the "very image;" for it is not yet complete. The words rendered "the very image" refer to a painting or statue which is finished, where every part is an exact copy of the original. The "good things to come" here refer to the future blessings which would be conferred on man by the gospel. The idea is, that under the ancient sacrifices there was an imperfect representation; a dim outline of the blessings which the gospel would impart to people. They were a typical representation; they were not such that it could be pretended that they would answer the purpose of the things themselves which they were to represent, and would make those who offered them perfect. Such a rude outline; such a mere sketch, or imperfect delineation, could no more answer the purpose of saving the soul than the rough sketch which an architect makes would answer the purpose of a house, or than the first outline which a painter draws would answer the purpose of a perfect and finished portrait. All that could be done by either would be to convey some distant and obscure idea of what the house or the picture might be, and this was all that was done by the Law of Moses.Can never with those sacrifices which they offered year by year continually - The sacrifices here particularly referred to were those which were offered on the great day of atonement. These were regarded as the most sacred and efficacious of all, and yet the apostle says that the very fact that they were offered every year showed that there must be some deficiency about them, or they would have ceased to be offered.Make the comers thereunto perfect - They could not free them from the stains of guilt; they could not give ease to a troubled conscience; there was in them no efficacy by which sin could be put away; compare the notes on Hebrews 7:11; Hebrews 9:9.', NULL, NULL, '''11'':407 ''7'':406 ''9'':409,410 ''ancient'':145 ''answer'':182,216,232,248 ''anyth'':36 ''apostl'':336 ''architect'':229 ''artist'':54 ''aton'':321 ''away'':400 ''bless'':129,157 ''carpent'':43 ''ceas'':361 ''chalk'':49 ''come'':123 ''comer'':366 ''compar'':401 ''complet'':93 ''confer'':133 ''conscienc'':387 ''continu'':304 ''convey'':267 ''copi'':115 ''could'':176,213,259,370,380,397 ''day'':319 ''defici'':354 ''delin'':55,212 ''design'':73 ''dim'':153 ''distant'':269 ''done'':261,288 ''draw'':44,75,246 ''eas'':383 ''economi'':14 ''efficaci'':330,393 ''either'':263 ''everi'':110,346 ''exact'':114 ''fact'':341 ''finish'':108,255 ''first'':241 ''free'':372 ''futur'':128 ''give'':382 ''good'':120 ''gospel'':138,160 ''great'':318 ''guilt'':378 ''hebrew'':405,408 ''hous'':237,276 ''idea'':140,272 ''imag'':87,99 ''impart'':162 ''imperfect'':150,211 ''law'':3,22,291 ''make'':61,196,230 ''man'':135 ''mere'':38,208 ''might'':280 ''mosaic'':13 ''moses.can'':293 ''must'':351 ''never'':294 ''note'':403 ''object'':70 ''obscur'':271 ''offer'':199,300,315,345 ''offered.make'':364 ''often'':24 ''origin'':118 ''outlin'':34,67,154,205,242 ''paint'':103 ''painter'':245 ''part'':111 ''particular'':308 ''peopl'':164 ''perfect'':201,253,368 ''pictur'':63,279 ''piec'':47 ''portrait'':256 ''pretend'':178 ''purpos'':184,218,234,250 ''put'':399 ''refer'':30,100,125,309 ''regard'':324 ''render'':96 ''repres'':193 ''represent'':151,169 ''resembl'':79 ''rough'':33,225 ''rude'':204 ''sacr'':328 ''sacrific'':146,297,306 ''save'':220 ''say'':337 ''shadow'':6,17,28 ''show'':348 ''sin'':396 ''sketch'':39,65,209,226 ''soul'':222 ''stain'':376 ''statu'':105 ''thereunto'':367 ''thing'':121,187 ''troubl'':386 ''typic'':168 ''use'':25 ''whole'':10 ''word'':21,27,95 ''would'':131,161,181,195,231,247,264,359 ''year'':301,303,347 ''yet'':92,334', NULL, '1143');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1257', '2', '1257', NULL, 'Let brotherly love continue - Implying that it now existed among them. The apostle had no occasion to reprove them for the want of it, as he had in regard to some to whom he wrote, but he aims merely to impress on them the importance of this virtue, and to caution them against the danger of allowing it ever to be interrupted; see the notes on John 13:34.', NULL, NULL, '''13'':68 ''34'':69 ''aim'':38 ''allow'':57 ''among'':10 ''apostl'':13 ''brother'':2 ''caution'':51 ''continu'':4 ''danger'':55 ''ever'':59 ''exist'':9 ''impli'':5 ''import'':45 ''impress'':41 ''interrupt'':62 ''john'':67 ''let'':1 ''love'':3 ''mere'':39 ''note'':65 ''occas'':16 ''regard'':29 ''reprov'':18 ''see'':63 ''virtu'':48 ''want'':22 ''wrote'':35', NULL, '1146');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1259', '2', '1259', NULL, 'My brethren - Perhaps meaning brethren in two respects - as Jews, and as Christians. In both respects the form of address would be proper.Have not the faith of our Lord Jesus Christ - Faith is the distinguishing thing in the Christian religion, for it is this by which man is justified, and hence, it comes to be put for religion itself. Notes, 1 Timothy 3:9. The meaning here is, "do not hold such views of the religion of Christ, as to lead you to manifest partiality to others on account of their difference of rank or outward circumstances."The Lord of glory - The glorious Lord; he who is glorious himself, and who is encompassed with glory. See the notes at 1 Corinthians 2:8. The design here seems to be to show that the religion of such a Lord should be in no way dishonored.With respect of persons - That is, you are not to show respect of persons, or to evince partiality to others on account of their rank, wealth, apparel, etc. Compare Proverbs 24:23; Proverbs 28:21; Leviticus 19:15; Deuteronomy 1:17; Deuteronomy 10:17; 2 Chronicles 19:7; Psalm 40:4. See the subject explained in the Acts 10:34 note; Romans 2:11 note.', NULL, NULL, '''1'':61,120,183 ''10'':186,202 ''11'':207 ''15'':181 ''17'':184,187 ''19'':180,190 ''2'':122,188,206 ''21'':178 ''23'':175 ''24'':174 ''28'':177 ''3'':63 ''34'':203 ''4'':194 ''40'':193 ''7'':191 ''8'':123 ''9'':64 ''account'':89,165 ''act'':201 ''address'':20 ''apparel'':170 ''brethren'':2,5 ''christ'':31,78 ''christian'':13,39 ''chronicl'':189 ''circumst'':97 ''come'':53 ''compar'':172 ''corinthian'':121 ''design'':125 ''deuteronomi'':182,185 ''differ'':92 ''dishonored.with'':144 ''distinguish'':35 ''encompass'':113 ''etc'':171 ''evinc'':160 ''explain'':198 ''faith'':26,32 ''form'':18 ''glori'':101,115 ''glorious'':103,108 ''henc'':51 ''hold'':71 ''jesus'':30 ''jew'':10 ''justifi'':49 ''lead'':81 ''leviticus'':179 ''lord'':29,99,104,138 ''man'':47 ''manifest'':84 ''mean'':4,66 ''note'':60,118,204,208 ''other'':87,163 ''outward'':96 ''partial'':85,161 ''perhap'':3 ''person'':147,157 ''proper.have'':23 ''proverb'':173,176 ''psalm'':192 ''put'':56 ''rank'':94,168 ''religion'':40,58,76,134 ''respect'':8,16,145,155 ''roman'':205 ''see'':116,195 ''seem'':127 ''show'':131,154 ''subject'':197 ''thing'':36 ''timothi'':62 ''two'':7 ''view'':73 ''way'':143 ''wealth'':169 ''would'':21', NULL, '1148');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1262', '2', '1262', NULL, 'Go to now - Notes, James 4:13.Ye rich men - Not all rich men, but only that class of them who are specified as unjust and oppressive. There is no sin in merely being rich; where sin exists peculiarly among the rich, it arises from the manner in which wealth is acquired, the spirit which it tends to engender in the heart, and the way in which it is used. Compare the Luke 6:24 note; 1 Timothy 6:9 note.Weep and howl - Greek: "Weep howling." This would be expressive of very deep distress. The language is intensive in a high degree, showing that the calamities which were coming upon them were not only such as would produce tears, but tears accompanied with loud lamentations. In the East, it is customary to give expression to deep sorrow by loud outcries. Compare Isaiah 13:6; Isaiah 14:31; Isaiah 15:2; Isaiah 16:7; Jeremiah 4:8; Jeremiah 47:2; Joel 1:5.For your miseries that shall come upon you - Many expositors, as Benson, Whitby, Macknight, and others, suppose that this refers to the approaching destruction of Jerusalem by the Romans, and to the miseries which would be brought in the siege upon the Jewish people, in which the rich would be the peculiar objects of cupidity and vengeance. They refer to passages in Josephus, which describe particularly the sufferings to which the rich were exposed; the searching of their houses by the zealots, and the heavy calamities which came upon them and their families. But there is no reason to suppose that the apostle referred particularly to those events. The poor as well as the rich suffered in that siege, and there were no such special judgments then brought upon the rich as to show that they were the marked objects of the divine displeasure. It is much more natural to suppose that the apostle means to say that such men as he here refers to exposed themselves always to the wrath of God, and that they had great reason to weep in the anticipation of his vengeance. The sentiments here expressed by the apostle are not applicable merely to the Jews of his time. If there is any class of men which has special reason to dread the wrath of God at all times, it is just the class of men here referred to.', NULL, NULL, '''1'':76,160 ''13'':142 ''13.ye'':7 ''14'':145 ''15'':148 ''16'':151 ''2'':149,158 ''24'':74 ''31'':146 ''4'':6,154 ''47'':157 ''5.for'':161 ''6'':73,78,143 ''7'':152 ''8'':155 ''9'':79 ''accompani'':121 ''acquir'':51 ''alway'':328 ''among'':39 ''anticip'':344 ''apostl'':263,314,354 ''applic'':357 ''approach'':183 ''aris'':43 ''benson'':172 ''brought'':197,288 ''calam'':105,246 ''came'':248 ''class'':17,369,389 ''come'':108,166 ''compar'':70,140 ''cupid'':215 ''customari'':130 ''deep'':92,135 ''degre'':101 ''describ'':225 ''destruct'':184 ''displeasur'':304 ''distress'':93 ''divin'':303 ''dread'':377 ''east'':127 ''engend'':58 ''event'':268 ''exist'':37 ''expos'':234,326 ''expositor'':170 ''express'':89,133,351 ''famili'':253 ''give'':132 ''go'':1 ''god'':333,381 ''great'':338 ''greek'':83 ''heart'':61 ''heavi'':245 ''high'':100 ''hous'':239 ''howl'':82,85 ''intens'':97 ''isaiah'':141,144,147,150 ''jame'':5 ''jeremiah'':153,156 ''jerusalem'':186 ''jew'':361 ''jewish'':203 ''joel'':159 ''josephus'':223 ''judgment'':286 ''lament'':124 ''languag'':95 ''loud'':123,138 ''luke'':72 ''macknight'':174 ''mani'':169 ''manner'':46 ''mark'':299 ''mean'':315 ''men'':9,13,320,371,391 ''mere'':32,358 ''miseri'':163,193 ''much'':307 ''natur'':309 ''note'':4,75 ''note.weep'':80 ''object'':213,300 ''oppress'':26 ''other'':176 ''outcri'':139 ''particular'':226,265 ''passag'':221 ''peculiar'':38,212 ''peopl'':204 ''poor'':270 ''produc'':117 ''reason'':258,339,375 ''refer'':180,219,264,324,393 ''rich'':8,12,34,41,208,232,275,291 ''roman'':189 ''say'':317 ''search'':236 ''sentiment'':349 ''shall'':165 ''show'':102,294 ''sieg'':200,279 ''sin'':30,36 ''sorrow'':136 ''special'':285,374 ''specifi'':22 ''spirit'':53 ''suffer'':228,276 ''suppos'':177,260,311 ''tear'':118,120 ''tend'':56 ''time'':364,384 ''timothi'':77 ''unjust'':24 ''upon'':109,167,201,249,289 ''use'':69 ''vengeanc'':217,347 ''way'':64 ''wealth'':49 ''weep'':84,341 ''well'':272 ''whitbi'':173 ''would'':87,116,195,209 ''wrath'':331,379 ''zealot'':242', NULL, '1151');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1265', '2', '1265', NULL, 'Likewise, ye wives, be in subjection to your own husbands - On the duty here enjoined, see the 1 Corinthians 11:3-9 notes, and Ephesians 5:22 note.That, if any obey not the word - The word of God; the gospel. That is, if any wives have husbands who are not true Christians. This would be likely to occur when the gospel was first preached, as it does now, by the fact that wives might be converted, though their husbands were not. It cannot be inferred from this, that after they themselves had become Christians they had married unbelieving husbands. The term "word" here refers particularly to the gospel as preached; and the idea is, that if they were regardless of that gospel when preached - if they would not attend on preaching, or if they were unaffected by it, or if they openly rejected it, there might be hope still that they would be converted by the Christian influence of a wife at home. In such cases, a duty of special importance devolves on the wife.They also may without the word be won - In some other way than by preaching. This I does not mean that they would be converted independently of the influence of truth - for truth is always the instrument of conversion, James 1:18; John 17:17; but that it was to be by another influence than preaching.By the conversation of the wives - By the conduct or deportment of their wives. See the notes at Philippians 1:27. The word conversation, in the Scriptures, is never confined, as it is now with us, to oral discourse, but denotes conduct in general. It includes indeed "conversation" as the word is now used, but it embraces also much more - including everything that we do. The meaning here is, that the habitual deportment of the wife was to be such as to show the reality and power of religion; to show that it had such influence on her temper, her words, her whole deportment, as to demonstrate that it was from God.', NULL, NULL, '''-9'':22 ''1'':18,215,249 ''11'':20 ''17'':218,219 ''18'':216 ''22'':27 ''27'':250 ''3'':21 ''5'':26 ''also'':176,287 ''alway'':209 ''anoth'':227 ''attend'':129 ''becom'':93 ''cannot'':83 ''case'':166 ''christian'':52,94,157 ''conduct'':238,271 ''confin'':259 ''convers'':213,232,253,277 ''convert'':76,154,199 ''corinthian'':19 ''demonstr'':336 ''denot'':270 ''deport'':240,302,333 ''devolv'':172 ''discours'':268 ''duti'':13,168 ''embrac'':286 ''enjoin'':15 ''ephesian'':25 ''everyth'':291 ''fact'':71 ''first'':63 ''general'':273 ''god'':38,341 ''gospel'':40,61,108,122 ''habitu'':301 ''home'':163 ''hope'':148 ''husband'':10,47,79,99 ''idea'':113 ''import'':171 ''includ'':275,290 ''inde'':276 ''independ'':200 ''infer'':85 ''influenc'':158,203,228,325 ''instrument'':211 ''jame'':214 ''john'':217 ''like'':56 ''likewis'':1 ''marri'':97 ''may'':177 ''mean'':194,296 ''might'':74,146 ''much'':288 ''never'':258 ''note'':23,246 ''note.that'':28 ''obey'':31 ''occur'':58 ''open'':142 ''oral'':267 ''particular'':105 ''philippian'':248 ''power'':316 ''preach'':64,110,124,131,189 ''preaching.by'':230 ''realiti'':314 ''refer'':104 ''regardless'':119 ''reject'':143 ''religion'':318 ''scriptur'':256 ''see'':16,244 ''show'':312,320 ''special'':170 ''still'':149 ''subject'':6 ''temper'':328 ''term'':101 ''though'':77 ''true'':51 ''truth'':205,207 ''unaffect'':136 ''unbeliev'':98 ''us'':265 ''use'':283 ''way'':186 ''whole'':332 ''wife'':161,305 ''wife.they'':175 ''without'':178 ''wive'':3,45,73,235,243 ''won'':182 ''word'':34,36,102,180,252,280,330 ''would'':54,127,152,197 ''ye'':2', NULL, '1154');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1266', '2', '1266', NULL, 'Forasmuch then as Christ hath suffered for us in the flesh - Since he as a man has died for us. See the notes at 1 Peter 3:18. The design was to set the suffering Redeemer before them as an example in their trials.Arm yourselves likewise with the same mind - That is, evidently, the same mind that he evinced - a readiness to suffer in the cause of religion, a readiness to die as he had done. This readiness to suffer and die, the apostle speaks of as armour, and having this is represented as being armed. Armour is put on for offensive or defensive purposes in war; and the idea of the apostle here is, that that state of mind when we are ready to meet with persecution and trial, and when we are ready to die, will answer the purpose of armour in engaging in the conflicts and strifes which pertain to us as Christians, and especially in meeting with persecutions and trials. We are to put on the same fortitude which the Lord Jesus had, and this will be the best defense against our foes, and the best security of victory.For he that hath suffered in the flesh hath ceased from sin - Compare the notes at Romans 6:7. To "suffer in the flesh" is to die. The expression here has a proverbial aspect, and seems to have meant something like this: "when a man is dead, he will sin no more;" referring of course to the present life. So if a Christian becomes dead in a moral sense - dead to this world, dead by being crucified with Christ (see the notes at Galatians 2:20) - he may be expected to cease from sin. The reasoning is based on the idea that there is such a union between Christ and the believer that his death on the cross secured the death of the believer to the world. Compare 2 Timothy 2:11; Colossians 2:20; Colossians 3:3.', NULL, NULL, '''1'':25 ''11'':324 ''18'':28 ''2'':277,321,323,326 ''20'':278,327 ''3'':27,329,330 ''6'':210 ''7'':211 ''answer'':139 ''apostl'':84,113 ''arm'':96 ''armour'':88,97,143 ''aspect'':226 ''base'':290 ''becom'':256 ''believ'':304,316 ''best'':183,190 ''caus'':66 ''ceas'':202,284 ''christ'':4,271,301 ''christian'':156,255 ''colossian'':325,328 ''compar'':205,320 ''conflict'':148 ''cours'':247 ''cross'':310 ''crucifi'':269 ''dead'':239,257,262,266 ''death'':307,313 ''defens'':104,184 ''design'':30 ''die'':18,72,82,137,219 ''done'':76 ''engag'':145 ''especi'':158 ''evid'':53 ''evinc'':59 ''exampl'':41 ''expect'':282 ''express'':221 ''flesh'':11,200,216 ''foe'':187 ''forasmuch'':1 ''fortitud'':172 ''galatian'':276 ''hath'':5,196,201 ''idea'':110,293 ''jesus'':176 ''life'':251 ''like'':233 ''likewis'':46 ''lord'':175 ''man'':16,237 ''may'':280 ''meant'':231 ''meet'':126,160 ''mind'':50,56,120 ''moral'':260 ''note'':23,207,274 ''offens'':102 ''persecut'':128,162 ''pertain'':152 ''peter'':26 ''present'':250 ''proverbi'':225 ''purpos'':105,141 ''put'':99,168 ''readi'':61,70,78,124,135 ''reason'':288 ''redeem'':36 ''refer'':245 ''religion'':68 ''repres'':93 ''roman'':209 ''secur'':191,311 ''see'':21,272 ''seem'':228 ''sens'':261 ''set'':33 ''sin'':204,242,286 ''sinc'':12 ''someth'':232 ''speak'':85 ''state'':118 ''strife'':150 ''suffer'':6,35,63,80,197,213 ''timothi'':322 ''trial'':130,164 ''trials.arm'':44 ''union'':299 ''us'':8,20,154 ''victory.for'':193 ''war'':107 ''world'':265,319', NULL, '1155');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('188', '2', '188', NULL, 'Now ... - Hebrew: "and, ..." The statement following is thus connected with some previous one, which is assumed to be known to the reader. So Judges, Ruth, 1 Samuel, etc., are by the same means linked on to the books preceding them. The connection here is the closer, since the Book of Deuteronomy concludes, and the book of Joshua opens, by referring to the death of Moses.Moses, the servant of the Lord - On the epithet, see the marginal reference "b."Moses'' minister - It is impossible altogether to pass by the typical application of this verse. Moses, representing the law, is dead; Joshua, or, as that name is written in Greek, Jesus, is now bidden by God to do what Moses could not - lead the people into the promised land. Joshua was "Moses'' minister," just as Christ was "made under the Law;" but it was Joshua, not Moses, who worked out the accomplishment of the blessings which the Law promised. On the name Joshua, see Exodus 17:9 note, and Numbers 13:16.Saying - No doubt directly, by an immediate revelation, but not as God spake to Moses, "mouth to mouth" Numbers 12:8. Though upon Joshua''s appointment to be Moses'' successor (Numbers 27:18 ff), it had been directed that "counsel should be asked" for him through the medium of Eleazar "after the judgment of Urim," yet this was evidently a resource provided to meet cases of doubt and difficulty. Here there was no such case; but the appointed leader, knowing well the purpose of God, needed to be stirred up to instant execution of it; and the people too might require the encouragement of a renewed divine command to set out at once upon the great enterprise before them (compare Joshua 1:13).', NULL, NULL, '''1'':26,291 ''12'':189 ''13'':169,292 ''16.saying'':170 ''17'':164 ''18'':202 ''27'':201 ''8'':190 ''9'':165 ''accomplish'':150 ''altogeth'':84 ''applic'':90 ''appoint'':195,247 ''ask'':212 ''assum'':16 ''b'':78 ''bidden'':112 ''bless'':153 ''book'':38,49,55 ''case'':234,244 ''christ'':134 ''closer'':46 ''command'':277 ''compar'':289 ''conclud'':52 ''connect'':9,42 ''could'':119 ''counsel'':209 ''dead'':99 ''death'':63 ''deuteronomi'':51 ''difficulti'':238 ''direct'':173,207 ''divin'':276 ''doubt'':172,236 ''eleazar'':219 ''encourag'':272 ''enterpris'':286 ''epithet'':73 ''etc'':28 ''evid'':228 ''execut'':262 ''exodus'':163 ''ff'':203 ''follow'':6 ''god'':114,181,254 ''great'':285 ''greek'':108 ''hebrew'':2 ''immedi'':176 ''imposs'':83 ''instant'':261 ''jesus'':109 ''joshua'':57,100,128,143,161,193,290 ''judg'':24 ''judgment'':222 ''know'':249 ''known'':19 ''land'':127 ''law'':97,139,156 ''lead'':121 ''leader'':248 ''link'':34 ''lord'':70 ''made'':136 ''margin'':76 ''mean'':33 ''medium'':217 ''meet'':233 ''might'':269 ''minist'':80,131 ''mose'':79,94,118,130,145,184,198 ''moses.moses'':65 ''mouth'':185,187 ''name'':104,160 ''need'':255 ''note'':166 ''number'':168,188,200 ''one'':13 ''open'':58 ''pass'':86 ''peopl'':123,267 ''preced'':39 ''previous'':12 ''promis'':126,157 ''provid'':231 ''purpos'':252 ''reader'':22 ''refer'':60,77 ''renew'':275 ''repres'':95 ''requir'':270 ''resourc'':230 ''revel'':177 ''ruth'':25 ''samuel'':27 ''see'':74,162 ''servant'':67 ''set'':279 ''sinc'':47 ''spake'':182 ''statement'':5 ''stir'':258 ''successor'':199 ''though'':191 ''thus'':8 ''typic'':89 ''upon'':192,283 ''urim'':224 ''vers'':93 ''well'':250 ''work'':147 ''written'':106 ''yet'':225', NULL, '188');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('189', '2', '189', NULL, 'An harlot''s house - In the face of the parallel passages (e. g. Leviticus 21:7 : Jeremiah 5:7) the rendering advocated for obvious reasons, namely, "the house of a woman, an innkeeper," cannot be maintained. Rahab must remain an example under the Law similar to that Luke 7:37 under the Gospel, of "a woman that was a sinner," yet, because of her faith, not only pardoned, but exalted to the highest honor. Rahab was admitted among the people of God; she intermarried into a chief family of a chief tribe, and found a place among the best remembered ancestors of King David and of Christ; thus receiving the temporal blessings of the covenant in largest measure. The spies would of course betake themselves to such a house in Jericho as they could visit without exciting suspicion; and the situation of Rahab''s, upon the wall Joshua 2:15, rendered it especially suitable. It appears from Joshua 2:4 that Rahab hid them before the King''s messengers reached her house, and probably as soon as the spies had come to her house. It is therefore most likely that they met with Rahab outside of Jericho (compare Genesis 38:14), and ascertained where in the city she dwelt, and that they might entrust themselves to her care. Rahab (i. e. "spacious," "wide." Compare the name "Japheth" and Genesis 9:27, note) is regarded by the fathers as a type of the Christian Church, which was gathered out of converts from the whole vast circle of pagan nations.', NULL, NULL, '''14'':201 ''15'':150 ''2'':149,159 ''21'':15 ''27'':231 ''37'':50 ''38'':200 ''4'':160 ''5'':18 ''7'':16,19,49 ''9'':230 ''admit'':77 ''advoc'':22 ''among'':78,97 ''ancestor'':101 ''appear'':156 ''ascertain'':203 ''best'':99 ''betak'':124 ''bless'':112 ''cannot'':34 ''care'':218 ''chief'':87,91 ''christ'':107 ''christian'':243 ''church'':244 ''circl'':255 ''citi'':207 ''come'':181 ''compar'':198,224 ''convert'':250 ''could'':134 ''cours'':123 ''coven'':115 ''david'':104 ''dwelt'':209 ''e'':12,221 ''entrust'':214 ''especi'':153 ''exalt'':70 ''exampl'':41 ''excit'':137 ''face'':7 ''faith'':65 ''famili'':88 ''father'':237 ''found'':94 ''g'':13 ''gather'':247 ''genesi'':199,229 ''god'':82 ''gospel'':53 ''harlot'':2 ''hid'':163 ''highest'':73 ''honor'':74 ''hous'':4,28,129,172,184 ''innkeep'':33 ''intermarri'':84 ''japheth'':227 ''jeremiah'':17 ''jericho'':131,197 ''joshua'':148,158 ''king'':103,167 ''largest'':117 ''law'':44 ''leviticus'':14 ''like'':189 ''luke'':48 ''maintain'':36 ''measur'':118 ''messeng'':169 ''met'':192 ''might'':213 ''must'':38 ''name'':26,226 ''nation'':258 ''note'':232 ''obvious'':24 ''outsid'':195 ''pagan'':257 ''parallel'':10 ''pardon'':68 ''passag'':11 ''peopl'':80 ''place'':96 ''probabl'':174 ''rahab'':37,75,143,162,194,219 ''reach'':170 ''reason'':25 ''receiv'':109 ''regard'':234 ''remain'':39 ''rememb'':100 ''render'':21,151 ''similar'':45 ''sinner'':60 ''situat'':141 ''soon'':176 ''spacious'':222 ''spi'':120,179 ''suitabl'':154 ''suspicion'':138 ''tempor'':111 ''therefor'':187 ''thus'':108 ''tribe'':92 ''type'':240 ''upon'':145 ''vast'':254 ''visit'':135 ''wall'':147 ''whole'':253 ''wide'':223 ''without'':136 ''woman'':31,56 ''would'':121 ''yet'':61', NULL, '189');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('190', '2', '190', NULL, '"The acacia groves" (Exodus 25:5 note) of Shittim on both sides of Jordan line the upper terraces of the valley (compare 2 Kings 6:4). They would be in this part at some six miles distance from the river itself.', NULL, NULL, '''2'':23 ''25'':5 ''4'':26 ''5'':6 ''6'':25 ''acacia'':2 ''compar'':22 ''distanc'':37 ''exodus'':4 ''grove'':3 ''jordan'':14 ''king'':24 ''line'':15 ''mile'':36 ''note'':7 ''part'':32 ''river'':40 ''shittim'':9 ''side'':12 ''six'':35 ''terrac'':18 ''upper'':17 ''valley'':21 ''would'':28', NULL, '190');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('191', '2', '191', NULL, 'Take you twelve men - The order is given in the plural, because no doubt the tribes themselves were to choose their own representatives, the choice being approved by Joshua Jos 4:4. These twelve would be left with Joshua on the hither bank of the river, waiting to receive his orders after the rest of the people had made their way across Joshua 3:17; Joshua 4:1.', NULL, NULL, '''1'':68 ''17'':65 ''3'':64 ''4'':31,32,67 ''across'':62 ''approv'':27 ''bank'':43 ''choic'':25 ''choos'':20 ''doubt'':14 ''given'':8 ''hither'':42 ''jos'':30 ''joshua'':29,39,63,66 ''left'':37 ''made'':59 ''men'':4 ''order'':6,51 ''peopl'':57 ''plural'':11 ''receiv'':49 ''repres'':23 ''rest'':54 ''river'':46 ''take'':1 ''tribe'':16 ''twelv'':3,34 ''wait'':47 ''way'':61 ''would'':35', NULL, '191');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('192', '2', '192', NULL, 'The Amorites were the principal of those nations which occupied the hill country of Judaea (Genesis 10:16 note); the Canaanites of those that dwelt on the coast and low lands. These words are therefore equivalent to "all the kings of the highlanders, and all the kings of the lowlanders:" i. e. the kings of all the tribes of the country.Until we were passed over - The use of the first person has been noted here, and in Joshua 5:6 (compare Acts 16:10), as suggesting the hand of one who himself shared in what he describes. But the text as read (though not written) by the Jewish authorities here, has the third person; as have some manuscripts, Septuagint, Vulgate, etc.: and a change of person like this in Hebrew, even if the text stand, does not of itself warrant the inference. (Compare Psalm 66:6.)', NULL, NULL, '''10'':17,84 ''16'':18,83 ''5'':79 ''6'':80,146 ''66'':145 ''act'':82 ''amorit'':2 ''author'':109 ''canaanit'':21 ''chang'':124 ''coast'':28 ''compar'':81,143 ''countri'':13 ''country.until'':61 ''describ'':97 ''dwelt'':25 ''e'':52 ''equival'':36 ''etc'':121 ''even'':131 ''first'':70 ''genesi'':16 ''hand'':88 ''hebrew'':130 ''highland'':43 ''hill'':12 ''infer'':142 ''jewish'':108 ''joshua'':78 ''judaea'':15 ''king'':40,47,54 ''land'':31 ''like'':127 ''low'':30 ''lowland'':50 ''manuscript'':118 ''nation'':8 ''note'':19,74 ''occupi'':10 ''one'':90 ''pass'':64 ''person'':71,114,126 ''princip'':5 ''psalm'':144 ''read'':102 ''septuagint'':119 ''share'':93 ''stand'':135 ''suggest'':86 ''text'':100,134 ''therefor'':35 ''third'':113 ''though'':103 ''tribe'':58 ''use'':67 ''vulgat'':120 ''warrant'':140 ''word'':33 ''written'':105', NULL, '192');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('193', '2', '193', NULL, 'This verse is strictly parenthetical. It is inserted to explain the declaration commenced Joshua 5:14, and interrupted by Joshua''s question and obeisance Joshua 5:14-15, but resumed in Joshua 6:2.Straitly shut up - See the margin, i. e., not only shut, but barred and bolted.', NULL, NULL, '''-15'':28 ''14'':16,27 ''2.straitly'':34 ''5'':15,26 ''6'':33 ''bar'':46 ''bolt'':48 ''commenc'':13 ''declar'':12 ''e'':41 ''explain'':10 ''insert'':8 ''interrupt'':18 ''joshua'':14,20,25,32 ''margin'':39 ''obeis'':24 ''parenthet'':5 ''question'':22 ''resum'':30 ''see'':37 ''shut'':35,44 ''strict'':4 ''vers'':2', NULL, '193');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('240', '2', '240', NULL, 'Some attach the opening words to the close of 1 Samuel 3, as the complement of what is there said, "The Lord revealed himself to Samuel ... in Shiloh, and the word of Samuel went forth to all Israel." If placed at the commencement of 1 Samuel 4, and in connection with what follows, they are to be understood in the sense that Samuel called all Israel to battle against the Philistines. (Compare 1 Samuel 7:5.) But this is not the natural interpretation of the words, which seem clearly to belong to what went before.The mention of the Philistines connects the narrative with Judges 13-16. Since the Philistine servitude lasted forty years Judges 13:1, and seems to have terminated in the days of Samuel 1 Samuel 7:13-14 in about the 20th year of his judgeship 1 Samuel 7:2; and since it had already begun before the birth of Samson Judges 13:5, and Samson judged Israel for 20 years "in the days of the Philistines" Judges 15:20, it seems to follow that the latter part of the judgeship of Eli and the early part of that of Samuel must have been coincident with the lifetime of Samson.Eben-ezer - (or, the stone of help) The place was afterward so named by Samuel. See the marginal references. "Aphek," or the "fortress," was probably the same as the "Aphek" of Joshua 12:18. It would be toward the western frontier of Judah, not very far from Mizpeh of Benjamin, and near Shiloh 1 Samuel 4:4.', NULL, NULL, '''-14'':131 ''-16'':106 ''1'':10,45,73,116,127,140,256 ''12'':235 ''13'':105,115,130,156 ''15'':172 ''18'':236 ''2'':143 ''20'':163,173 ''20th'':135 ''3'':12 ''4'':47,258,259 ''5'':76,157 ''7'':75,129,142 ''afterward'':213 ''alreadi'':148 ''aphek'':222,232 ''attach'':2 ''battl'':68 ''before.the'':95 ''begun'':149 ''belong'':91 ''benjamin'':252 ''birth'':152 ''call'':64 ''clear'':89 ''close'':8 ''coincid'':198 ''commenc'':43 ''compar'':72 ''complement'':15 ''connect'':50,100 ''day'':124,167 ''earli'':189 ''eli'':186 ''ezer'':204 ''far'':248 ''follow'':53,177 ''forth'':35 ''forti'':112 ''fortress'':225 ''frontier'':243 ''help'':209 ''interpret'':83 ''israel'':38,66,161 ''joshua'':234 ''judah'':245 ''judg'':104,114,155,160,171 ''judgeship'':139,184 ''last'':111 ''latter'':180 ''lifetim'':201 ''lord'':22 ''margin'':220 ''mention'':96 ''mizpeh'':250 ''must'':195 ''name'':215 ''narrat'':102 ''natur'':82 ''near'':254 ''open'':4 ''part'':181,190 ''philistin'':71,99,109,170 ''place'':40,211 ''probabl'':227 ''refer'':221 ''reveal'':23 ''said'':20 ''samson'':154,159 ''samson.eben'':203 ''samuel'':11,26,33,46,63,74,126,128,141,194,217,257 ''see'':218 ''seem'':88,118,175 ''sens'':61 ''servitud'':110 ''shiloh'':28,255 ''sinc'':107,145 ''stone'':207 ''termin'':121 ''toward'':240 ''understood'':58 ''went'':34,94 ''western'':242 ''word'':5,31,86 ''would'':238 ''year'':113,136,164', NULL, '240');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('194', '2', '194', NULL, 'Committed a trespass - (compare Leviticus 5:15 note), "acted treacherously and committed a breach of faith." This suitably describes the sin of Achan, who had purloined and hidden away that which had been dedicated to God by the ban Joshua 6:19.The "trespass" was the act of one man, yet is imputed to all Israel, who also share in the penalty of it Joshua 7:5. This is not to be explained as though all the people participated in the covetousness which led to Achan''s sin Joshua 7:21. The nation as a nation was in covenant with God, and is treated by Him not merely as a number of individuals living together for their own purposes under common institutions, but as a divinely-constituted organic whole. Hence, the sin of Achan defiled the other members of the community as well as himself. and robbed the people collectively of holiness before God and acceptableness with Him. Israel had in the person of Achan broken the covenant Joshua 7:11; God therefore would no more drive out the Canaanites before them.The accursed thing - Rather "in that which had been devoted or dedicated." Achan in diverting any of these devoted things to his own purposes, committed the sin of sacrilege, that of Ananias and Sapphira. Acts 5:2-3.Achan or Achar - (the marginal reference) the "n" and "r" being interchanged, perhaps for the sake of accommodating the name to   akar, "trouble" Joshua 7:25. Zabdi is generally identified with the Zimri of 1 Chronicles 2:6. Zerah was twin brother of Pharez and son of Judah Genesis 38:30. In this genealogy, as in others, several generations are omitted, most likely those which intervened between Zerah and Zabdi, and which covered the space between the migration of Jacob''s household to Egypt and the Exodus. (Numbers 26:5, see the note).', NULL, NULL, '''1'':252 ''11'':171 ''15'':7 ''19.the'':42 ''2'':254 ''2-3.achan'':218 ''21'':90 ''25'':243 ''26'':306 ''30'':268 ''38'':267 ''5'':6,66,217,307 ''6'':41,255 ''7'':65,89,170,242 ''accept'':156 ''accommod'':235 ''accurs'':183 ''achan'':23,85,134,165,194 ''achar'':220 ''act'':9,46,216 ''akar'':239 ''also'':57 ''anania'':213 ''away'':29 ''ban'':39 ''breach'':14 ''broken'':166 ''brother'':259 ''canaanit'':180 ''chronicl'':253 ''collect'':150 ''commit'':1,12,206 ''common'':120 ''communiti'':141 ''compar'':4 ''constitut'':127 ''coven'':98,168 ''cover'':290 ''covet'':81 ''dedic'':34,193 ''defil'':135 ''describ'':19 ''devot'':191,200 ''divert'':196 ''divin'':126 ''divinely-constitut'':125 ''drive'':177 ''egypt'':301 ''exodus'':304 ''explain'':72 ''faith'':16 ''genealog'':271 ''general'':246 ''generat'':276 ''genesi'':266 ''god'':36,100,154,172 ''henc'':130 ''hidden'':28 ''holi'':152 ''household'':299 ''identifi'':247 ''imput'':52 ''individu'':112 ''institut'':121 ''interchang'':229 ''interven'':283 ''israel'':55,159 ''jacob'':297 ''joshua'':40,64,88,169,241 ''judah'':265 ''led'':83 ''leviticus'':5 ''like'':280 ''live'':113 ''man'':49 ''margin'':222 ''member'':138 ''mere'':107 ''migrat'':295 ''n'':225 ''name'':237 ''nation'':92,95 ''note'':8,310 ''number'':110,305 ''omit'':278 ''one'':48 ''organ'':128 ''other'':274 ''particip'':78 ''penalti'':61 ''peopl'':77,149 ''perhap'':230 ''person'':163 ''pharez'':261 ''purloin'':26 ''purpos'':118,205 ''r'':227 ''rather'':185 ''refer'':223 ''rob'':147 ''sacrileg'':210 ''sake'':233 ''sapphira'':215 ''see'':308 ''sever'':275 ''share'':58 ''sin'':21,87,132,208 ''son'':263 ''space'':292 ''suitabl'':18 ''them.the'':182 ''therefor'':173 ''thing'':184,201 ''though'':74 ''togeth'':114 ''treacher'':10 ''treat'':103 ''trespass'':3,43 ''troubl'':240 ''twin'':258 ''well'':143 ''whole'':129 ''would'':174 ''yet'':50 ''zabdi'':244,287 ''zerah'':256,285 ''zimri'':250', NULL, '194');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('195', '2', '195', NULL, 'God rouses Joshua from his dejection Joshua 7:6, and bids him lmarch against Ai with the main body. Though Ai was but a small city (compare Joshua 8:25 and Joshua 7:3), yet the discouragement of the people rendered it inexpedient to send a second time a mere detachment against it; and the people of Ai had, as appears from Joshua 8:17, help from Bethel, and possibly from other places also. It was fitting too that all the people should witness with their own eyes the happy consequences of having faithfully put away the sin which had separated them from God.', NULL, NULL, '''17'':65 ''25'':30 ''3'':34 ''6'':9 ''7'':8,33 ''8'':29,64 ''ai'':15,21,58 ''also'':74 ''appear'':61 ''away'':96 ''bethel'':68 ''bid'':11 ''bodi'':19 ''citi'':26 ''compar'':27 ''consequ'':91 ''deject'':6 ''detach'':51 ''discourag'':37 ''eye'':88 ''faith'':94 ''fit'':77 ''god'':1,104 ''happi'':90 ''help'':66 ''inexpedi'':43 ''joshua'':3,7,28,32,63 ''lmarch'':13 ''main'':18 ''mere'':50 ''peopl'':40,56,82 ''place'':73 ''possibl'':70 ''put'':95 ''render'':41 ''rous'':2 ''second'':47 ''send'':45 ''separ'':101 ''sin'':98 ''small'':25 ''though'':20 ''time'':48 ''wit'':84 ''yet'':35', NULL, '195');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('196', '2', '196', NULL, 'In the hills - See the Numbers 13:17 note.The valleys - Or "the vale" (the Shephelah, Deuteronomy 1:7), which imports the lowland country between the mountains and the sea coast.', NULL, NULL, '''1'':17 ''13'':7 ''17'':8 ''7'':18 ''coast'':30 ''countri'':23 ''deuteronomi'':16 ''hill'':3 ''import'':20 ''lowland'':22 ''mountain'':26 ''note.the'':9 ''number'':6 ''sea'':29 ''see'':4 ''shephelah'':15 ''vale'':13 ''valley'':10', NULL, '196');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('197', '2', '197', NULL, 'For Hebron, see Genesis 13:18. Jarmuth, afterward one of the cities of Judah Joshua 15:35, is probably identified with the modern Yarmuk. Lachish was also a city of Judah Joshua 15:39, and, like Jarmuth, occupied by Jews after the captivity, Nehemiah 11:39. It was fortified by Rehoboam after the revolt of the Ten tribes 2 Chronicles 11:9, and seems to have been regarded as one of the safest places of refuge 2 Kings 14:19. Through Lachish the idolatry of Israel was imported into Judah Micah 1:13, and of this sin the capture of the city by Sennacherib was the punishment 2 Kings 18:14-17; 2 Kings 19:8. Lachish is by most authorities identified with Um Lakis, lying some twenty miles west of Eleutheropolis, on the road to Gaza (and by Conder with El Hesy).Eglon is the modern Ajlan.', NULL, NULL, '''-17'':112 ''1'':92 ''11'':45,61 ''13'':5,93 ''14'':79,111 ''15'':16,33 ''18'':6,110 ''19'':80,115 ''2'':59,77,108,113 ''35'':17 ''39'':34,46 ''8'':116 ''9'':62 ''afterward'':8 ''ajlan'':148 ''also'':27 ''author'':121 ''captiv'':43 ''captur'':99 ''chronicl'':60 ''citi'':12,29,102 ''conder'':140 ''eglon'':144 ''el'':142 ''eleutheropoli'':132 ''fortifi'':49 ''gaza'':137 ''genesi'':4 ''hebron'':2 ''hesi'':143 ''identifi'':20,122 ''idolatri'':84 ''import'':88 ''israel'':86 ''jarmuth'':7,37 ''jew'':40 ''joshua'':15,32 ''judah'':14,31,90 ''king'':78,109,114 ''lachish'':25,82,117 ''laki'':125 ''lie'':126 ''like'':36 ''micah'':91 ''mile'':129 ''modern'':23,147 ''nehemiah'':44 ''occupi'':38 ''one'':9,70 ''place'':74 ''probabl'':19 ''punish'':107 ''refug'':76 ''regard'':68 ''rehoboam'':51 ''revolt'':54 ''road'':135 ''safest'':73 ''see'':3 ''seem'':64 ''sennacherib'':104 ''sin'':97 ''ten'':57 ''tribe'':58 ''twenti'':128 ''um'':124 ''west'':130 ''yarmuk'':24', NULL, '197');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('198', '2', '198', NULL, 'Jabin - Probably the hereditary and official title of the kings of Hazor (see Judges 4:2). The word means literally "he shall understand," and is equivalent to "the wise" or "intelligent."Hazor - This name, which means "enclosed or "fortified," belonged also to two other towns in the south of Judah (compare Joshua 15:23, Joshua 15:25). The Hazor here in question, the head of the principalities of Northern Canaan Joshua 11:10 overlooked the lake of Merom, and was afterward assigned to the tribe of Naphtali Joshua 19:36. It doubtless was one of the strongest fortresses in the north, both by nature and art. It is mentioned in Egyptian inscriptions of an early date. Its situation in the midst of a plain, though itself on a hill, rendered it especially suitable as a stronghold for people whose main reliance was on horses and chariots Joshua 11:4; Judges 4:3. Its position on the northern frontier led to its being fortified by Solomon 1 Kings 9:15. Its people were carried away captive, with those of the other cities of Naphtali, by Tiglath-Pileser 2 Kings 15:29. By the "plain of Nasor," where (1 Macc. 11:67) Jonathan gained a victory over the Syrians, is doubtless to be understood "the plain of Asor" (i. e. Hazor). Hazor is conjecturally identified with the modern Tell Kuraibeh.Had heard those things - i. e. of the defeat of the southern Canaanites at Beth-horon and of the conquest of their country.The sites of Madon, Shimron, and of Achshaph, are unknown.', NULL, NULL, '''1'':166,198 ''10'':73 ''11'':72,148,200 ''15'':53,56,169,190 ''19'':89 ''2'':16,188 ''23'':54 ''25'':57 ''29'':191 ''3'':152 ''36'':90 ''4'':15,149,151 ''67'':201 ''9'':168 ''achshaph'':259 ''afterward'':81 ''also'':41 ''art'':106 ''asor'':217 ''assign'':82 ''away'':174 ''belong'':40 ''beth'':244 ''beth-horon'':243 ''canaan'':70 ''canaanit'':241 ''captiv'':175 ''carri'':173 ''chariot'':146 ''citi'':181 ''compar'':51 ''conjectur'':223 ''conquest'':249 ''country.the'':252 ''date'':116 ''defeat'':237 ''doubtless'':92,210 ''e'':219,234 ''earli'':115 ''egyptian'':111 ''enclos'':37 ''equival'':26 ''especi'':132 ''fortifi'':39,163 ''fortress'':98 ''frontier'':158 ''gain'':203 ''hazor'':12,32,59,220,221 ''head'':64 ''heard'':230 ''hereditari'':4 ''hill'':129 ''horon'':245 ''hors'':144 ''identifi'':224 ''inscript'':112 ''intellig'':31 ''jabin'':1 ''jonathan'':202 ''joshua'':52,55,71,88,147 ''judah'':50 ''judg'':14,150 ''king'':10,167,189 ''kuraibeh.had'':229 ''lake'':76 ''led'':159 ''liter'':20 ''macc'':199 ''madon'':255 ''main'':140 ''mean'':19,36 ''mention'':109 ''merom'':78 ''midst'':121 ''modern'':227 ''name'':34 ''naphtali'':87,183 ''nasor'':196 ''natur'':104 ''north'':101 ''northern'':69,157 ''offici'':6 ''one'':94 ''overlook'':74 ''peopl'':138,171 ''piles'':187 ''plain'':124,194,215 ''posit'':154 ''princip'':67 ''probabl'':2 ''question'':62 ''relianc'':141 ''render'':130 ''see'':13 ''shall'':22 ''shimron'':256 ''site'':253 ''situat'':118 ''solomon'':165 ''south'':48 ''southern'':240 ''strongest'':97 ''stronghold'':136 ''suitabl'':133 ''syrian'':208 ''tell'':228 ''thing'':232 ''though'':125 ''tiglath'':186 ''tiglath-piles'':185 ''titl'':7 ''town'':45 ''tribe'':85 ''two'':43 ''understand'':23 ''understood'':213 ''unknown'':261 ''victori'':205 ''whose'':139 ''wise'':29 ''word'':18', NULL, '198');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('200', '2', '200', NULL, 'Joshua is bidden to allot the whole of the promised land among the twelve tribes in faith that God would perfect in due time that expulsion of the Canaanites which Joshua himself could not carry further (see Joshua 11:23).', NULL, NULL, '''11'':39 ''23'':40 ''allot'':5 ''among'':12 ''bidden'':3 ''canaanit'':29 ''carri'':35 ''could'':33 ''due'':23 ''expuls'':26 ''faith'':17 ''god'':19 ''joshua'':1,31,38 ''land'':11 ''perfect'':21 ''promis'':10 ''see'':37 ''time'':24 ''tribe'':15 ''twelv'':14 ''whole'':7 ''would'':20', NULL, '200');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('241', '2', '241', NULL, 'They brought it into the house of Dagon (see the marginal reference) in order to enhance the triumph of the gods of the Philistines over the God of Israel. (Compare 1 Samuel 31:9; Judges 16:23; Isaiah 37:12.)', NULL, NULL, '''1'':31 ''12'':40 ''16'':36 ''23'':37 ''31'':33 ''37'':39 ''9'':34 ''brought'':2 ''compar'':30 ''dagon'':8 ''enhanc'':16 ''god'':21,27 ''hous'':6 ''isaiah'':38 ''israel'':29 ''judg'':35 ''margin'':11 ''order'':14 ''philistin'':24 ''refer'':12 ''samuel'':32 ''see'':9 ''triumph'':18', NULL, '241');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('201', '2', '201', NULL, 'Forty and five years - The word of God to Moses was spoken after the return of the spies in the autumn of the second year after the Exodus Num 13:25; subsequently, 38 years elapsed before the people reached the Jordan Numbers 20:1; after the passage of the Jordan seven more years had passed, when Caleb claimed Hebron, before the partition of the land among the nine tribes and a half. These seven years then correspond to the "long time" Joshua 11:18 during which Joshua was making war with the Canaanites. They are in the sequel of this verse added by Caleb to the years of wandering, since during them the people had no settled abodes.', NULL, NULL, '''1'':44 ''11'':83 ''13'':30 ''18'':84 ''20'':43 ''25'':31 ''38'':33 ''abod'':118 ''add'':102 ''among'':66 ''autumn'':21 ''caleb'':57,104 ''canaanit'':93 ''claim'':58 ''correspond'':77 ''elaps'':35 ''exodus'':28 ''five'':3 ''forti'':1 ''god'':8 ''half'':72 ''hebron'':59 ''jordan'':41,50 ''joshua'':82,87 ''land'':65 ''long'':80 ''make'':89 ''mose'':10 ''nine'':68 ''num'':29 ''number'':42 ''partit'':62 ''pass'':55 ''passag'':47 ''peopl'':38,114 ''reach'':39 ''return'':15 ''second'':24 ''sequel'':98 ''settl'':117 ''seven'':51,74 ''sinc'':110 ''spi'':18 ''spoken'':12 ''subsequ'':32 ''time'':81 ''tribe'':69 ''vers'':101 ''wander'':109 ''war'':90 ''word'':6 ''year'':4,25,34,53,75,107', NULL, '201');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('202', '2', '202', NULL, 'The inheritance of the tribe of Judah is described first by its general boundaries on all four sides Joshua 15:1-12; then reference is again made, for the sake of completeness, to the special inheritance of Caleb which lay within these boundaries Joshua 15:13-20; and lastly a list of the towns is given Joshua 15:21-63. Consult the marginal references.', NULL, NULL, '''-12'':22 ''-20'':47 ''-63'':60 ''1'':21 ''13'':46 ''15'':20,45,58 ''21'':59 ''boundari'':14,43 ''caleb'':38 ''complet'':32 ''consult'':61 ''describ'':9 ''first'':10 ''four'':17 ''general'':13 ''given'':56 ''inherit'':2,36 ''joshua'':19,44,57 ''judah'':7 ''last'':49 ''lay'':40 ''list'':51 ''made'':27 ''margin'':63 ''refer'':24,64 ''sake'':30 ''side'':18 ''special'':35 ''town'':54 ''tribe'':5 ''within'':41', NULL, '202');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('203', '2', '203', NULL, 'To the wilderness - Strike out "to," for the word is in apposition to "lot." The wilderness is Joshua 18:12 "the wilderness of Bethaven."', NULL, NULL, '''12'':20 ''18'':19 ''apposit'':12 ''bethaven'':24 ''joshua'':18 ''lot'':14 ''strike'':4 ''wilder'':3,16,22 ''word'':9', NULL, '203');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('204', '2', '204', NULL, 'Manasseh, as the "first-born," was to receive not only the territory on the east of Jordan won by the valor of the Machirites, but also a portion with the other tribes on the west of Jordan, the holy land of promise strictly so called. Thus, though Ephraim took precedence of Manasseh, according to the prediction of Joseph Genesis 48:20, yet Manasseh received "the double portion" which was the special privilege of the first-born Deuteronomy 21:17.', NULL, NULL, '''17'':81 ''20'':62 ''21'':80 ''48'':61 ''accord'':54 ''also'':27 ''born'':6,78 ''call'':46 ''deuteronomi'':79 ''doubl'':67 ''east'':16 ''ephraim'':49 ''first'':5,77 ''first-born'':4,76 ''genesi'':60 ''holi'':40 ''jordan'':18,38 ''joseph'':59 ''land'':41 ''machirit'':25 ''manasseh'':1,53,64 ''portion'':29,68 ''preced'':51 ''predict'':57 ''privileg'':73 ''promis'':43 ''receiv'':9,65 ''special'':72 ''strict'':44 ''territori'':13 ''though'':48 ''thus'':47 ''took'':50 ''tribe'':33 ''valor'':22 ''west'':36 ''won'':19 ''yet'':63', NULL, '204');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('205', '2', '205', NULL, 'After all overt resistance was overcome, the tabernacle with its sacred contents was removed from its place of safety at Gilgal, in a corner of the land near the Jordan, to a central place, Shiloh, the modern Scilun, which is two or three miles east of the main road, and rather more than half way between Jerusalem and Nablous. Its choice as the national sanctuary may indeed have been determined by Joshua, no doubt under divine direction Deuteronomy 12:11, because of its insignificance, in order to avoid local jealousies, as well as because of its position in the very center of the whole land, and perhaps also because of its seclusion. Its very name ("rest") was probably bestowed at this juncture when God had given the people rest from their enemies. The tabernacle with its contents continued at Shiloh during the whole period of the Judges, until its capture by the Philistines. Shiloh 1 Samuel 4:3-4 seems to have fallen into desolation at an early date Jeremiah 7:12; Jeremiah 26:6.', NULL, NULL, '''-4'':159 ''1'':155 ''11'':80 ''12'':79,172 ''26'':174 ''3'':158 ''4'':157 ''6'':175 ''7'':171 ''also'':108 ''avoid'':88 ''bestow'':119 ''captur'':150 ''center'':101 ''central'':33 ''choic'':61 ''content'':12,137 ''continu'':138 ''corner'':24 ''date'':169 ''desol'':165 ''determin'':70 ''deuteronomi'':78 ''direct'':77 ''divin'':76 ''doubt'':74 ''earli'':168 ''east'':45 ''enemi'':132 ''fallen'':163 ''gilgal'':21 ''given'':126 ''god'':124 ''half'':54 ''inde'':67 ''insignific'':84 ''jealousi'':90 ''jeremiah'':170,173 ''jerusalem'':57 ''jordan'':30 ''joshua'':72 ''judg'':147 ''junctur'':122 ''land'':27,105 ''local'':89 ''main'':48 ''may'':66 ''mile'':44 ''modern'':37 ''nablous'':59 ''name'':115 ''nation'':64 ''near'':28 ''order'':86 ''overcom'':6 ''overt'':3 ''peopl'':128 ''perhap'':107 ''period'':144 ''philistin'':153 ''place'':17,34 ''posit'':97 ''probabl'':118 ''rather'':51 ''remov'':14 ''resist'':4 ''rest'':116,129 ''road'':49 ''sacr'':11 ''safeti'':19 ''samuel'':156 ''sanctuari'':65 ''scilun'':38 ''seclus'':112 ''seem'':160 ''shiloh'':35,140,154 ''tabernacl'':8,134 ''three'':43 ''two'':41 ''way'':55 ''well'':92 ''whole'':104,143', NULL, '205');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('206', '2', '206', NULL, 'The inheritance of Simeon was taken out of the portion of Judah, which proved on experience to be larger than the numbers of that tribe required. The Simeonite territory is described by its towns, of which fourteen were in the Negeb, and four others Joshua 19:7 partly in the Negeb and partly in "the valley." On the narrow confines here assigned to Simeon, and its insignificant position altogether among the Twelve tribes, see Deuteronomy 33:6 note.', NULL, NULL, '''19'':46 ''33'':76 ''6'':77 ''7'':47 ''altogeth'':69 ''among'':70 ''assign'':62 ''confin'':60 ''describ'':31 ''deuteronomi'':75 ''experi'':16 ''four'':43 ''fourteen'':37 ''inherit'':2 ''insignific'':67 ''joshua'':45 ''judah'':12 ''larger'':19 ''narrow'':59 ''negeb'':41,51 ''note'':78 ''number'':22 ''other'':44 ''part'':48,53 ''portion'':10 ''posit'':68 ''prove'':14 ''requir'':26 ''see'':74 ''simeon'':4,64 ''simeonit'':28 ''taken'':6 ''territori'':29 ''town'':34 ''tribe'':25,73 ''twelv'':72 ''valley'':56', NULL, '206');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('207', '2', '207', NULL, 'As soon as the manslayer presented himself at the city of refuge, the elders of the city were to hold an inquiry, and receive him provisionally into the city. Afterward, when the avenger of blood should have tracked his victim to the city, and appear to claim him, a more formal and thorough investigation Joshua 20:6 was to be made. Consult the marginal references.', NULL, NULL, '''20'':56 ''6'':57 ''afterward'':30 ''appear'':45 ''aveng'':33 ''blood'':35 ''citi'':10,17,29,43 ''claim'':47 ''consult'':62 ''elder'':14 ''formal'':51 ''hold'':20 ''inquiri'':22 ''investig'':54 ''joshua'':55 ''made'':61 ''manslay'':5 ''margin'':64 ''present'':6 ''provision'':26 ''receiv'':24 ''refer'':65 ''refug'':12 ''soon'':2 ''thorough'':53 ''track'':38 ''victim'':40', NULL, '207');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('208', '2', '208', NULL, 'A list of the Levitical cities, varying in some particulars from that given in this chapter, is also, given in 1 Chronicles 6:54-81.', NULL, NULL, '''-81'':25 ''1'':21 ''54'':24 ''6'':23 ''also'':18 ''chapter'':16 ''chronicl'':22 ''citi'':6 ''given'':13,19 ''levit'':5 ''list'':2 ''particular'':10 ''vari'':7', NULL, '208');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('209', '2', '209', NULL, 'The events of this chap. are no doubt recorded in their proper historical order. The auxiliary forces of the trans-Jordanic tribes were not sent away immediately after the campaigns against the Canaanites were over. They set forth from Shiloh, Joshua 22:9, to which place the sanctuary had been removed Joshua 18:1 after the conquest and the settlement of the children of Judah and of Joseph in their possessions, and after the appointment of the Levitical cities.', NULL, NULL, '''1'':55 ''18'':54 ''22'':43 ''9'':44 ''appoint'':76 ''auxiliari'':16 ''away'':27 ''campaign'':31 ''canaanit'':34 ''chap'':5 ''children'':64 ''citi'':80 ''conquest'':58 ''doubt'':8 ''event'':2 ''forc'':17 ''forth'':39 ''histor'':13 ''immedi'':28 ''jordan'':22 ''joseph'':69 ''joshua'':42,53 ''judah'':66 ''levit'':79 ''order'':14 ''place'':47 ''possess'':72 ''proper'':12 ''record'':9 ''remov'':52 ''sanctuari'':49 ''sent'':26 ''set'':38 ''settlement'':61 ''shiloh'':41 ''tran'':21 ''trans-jordan'':20 ''tribe'':23', NULL, '209');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('211', '2', '211', NULL, 'Shechem, situated between those mountains, Ebal and Gerizim, which had already been the scene of a solemn rehearsal of the covenant soon after the first entry of the people into the promised land Joshua 8:30-35, was a fitting scene for the solemn renewal on the part of the people of that covenant with God which had been on His part so signally and so fully kept. The spot itself suggested the allusions to Abraham, Isaac, and Jacob, etc., in Joshua''s address; and its associations could not but give special force and moving effect to his appeals. This address was not made to the rulers only but to the whole nation, not of course to the tribes assembled in mass, but to their representatives.', NULL, NULL, '''-35'':37 ''30'':36 ''8'':35 ''abraham'':76 ''address'':84,101 ''allus'':74 ''alreadi'':11 ''appeal'':99 ''assembl'':120 ''associ'':87 ''could'':88 ''cours'':116 ''coven'':21,54 ''ebal'':6 ''effect'':96 ''entri'':26 ''etc'':80 ''first'':25 ''fit'':40 ''forc'':93 ''fulli'':67 ''gerizim'':8 ''give'':91 ''god'':56 ''isaac'':77 ''jacob'':79 ''joshua'':34,82 ''kept'':68 ''land'':33 ''made'':104 ''mass'':122 ''mountain'':5 ''move'':95 ''nation'':113 ''part'':48,62 ''peopl'':29,51 ''promis'':32 ''rehears'':18 ''renew'':45 ''repres'':126 ''ruler'':107 ''scene'':14,41 ''shechem'':1 ''signal'':64 ''situat'':2 ''solemn'':17,44 ''soon'':22 ''special'':92 ''spot'':70 ''suggest'':72 ''tribe'':119 ''whole'':112', NULL, '211');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1268', '2', '1268', NULL, 'Simon Peter - Margin, "Symeon." The name is written either "Simon" or "Simeon" - &#x3a3;&#x3b9;&#x3bc;&#x3c9;&#x3bd;  Simon or &#x3a3;&#x3c5;&#x3bc;&#x3b5;&#x3c9;&#x3bd;  Sumeon. Either word properly means "hearing;" and perhaps, like other names, was at first significant. The first epistle 1 Peter 1:1 begins simply, "Peter, an apostle," etc. The name Simon, however, was, his proper name -  "Peter," or "Cephas," having been added to it by the Saviour, John 1:42. Compare Matthew 16:18.A servant and an apostle of Jesus Christ - In the first epistle the word "apostle" only is used. Paul, however, uses the word "servant" as applicable to himself in Romans 1:1, and to himself and Timothy in the commencement of the epistle to the Philippians, Philippians 1:1. See the notes at Romans 1:1.To them that have obtained like precious faith with us - With us who are of Jewish origin. This epistle was evidently written to the same persons as the former (Introduction, Section 3), and that was intended to embrace many who were of Gentile origin. Notes, 1 Peter 1:1. The apostle addresses them all now, whatever was their origin, as heirs of the common faith, and as in all respects brethren.Through the righteousness of God - Through the method of justification which God has adopted. See this fully explained in the notes at Romans 1:17.(The original is &#x3b5;&#x3bd; &#x3b4;&#x3b9;&#x3ba;&#x3b1;&#x3b9;&#x3bf;&#x3c3;&#x3c5;&#x3bd;&#x3b7;  en dikaiosune, in the righteousness, etc., which makes the righteousness the object of faith. We cannot but regard the author''s rendering of the famous phrase here used by Peter, and by Paul, Romans 1:17; Romans 3:21, as singularly unhappy. That Newcome used it and the Socinian version adopted it, would not make us reject it; but when the apostles state specially the ground of justification, why should they be made to speak indefinitely of its general "plan," or method. The rendering of Stuart, namely, "justification of God," is not more successful; it confounds the "thing itself" with the "ground" of it. Why not prefer the apostle''s own words to any change or periphrasis? See the supplementary note at Romans 1:17).God and our Saviour Jesus Christ - Margin, "our God and Saviour." The Greek will undoubtedly bear the construction given in the margin; and if this be the true rendering, it furnishes an argument for the divinity of the Lord Jesus Christ. Middleton, Slade, Valpy, Bloomfield, and others, contend that this is the true and proper rendering. It is doubted, however, by Wetstein, Grotius, and others. Erasmus supposes that it may be taken in either sense. The construction, though certainly not a violation of the laws of the Greek language, is not so free from all doubt as to make it proper to use the passage as a proof-text in an argument for the divinity of the Saviour. It is easier to prove the doctrine from other texts that are plain, than to show that this must be the meaning here.', NULL, NULL, '''1'':33,35,36,63,99,100,116,117,123,169,171,172,217,256,345 ''1.to'':124 ''16'':67 ''17'':218,257,346 ''18'':68 ''21'':260 ''3'':155,259 ''42'':64 ''add'':56 ''address'':175 ''adopt'':207,272 ''apostl'':41,73,83,174,283,330 ''applic'':94 ''argument'':379,459 ''author'':241 ''bear'':362 ''begin'':37 ''bloomfield'':391 ''brethren.through'':194 ''cannot'':237 ''cepha'':53 ''certain'':425 ''chang'':336 ''christ'':76,352,387 ''commenc'':108 ''common'':187 ''compar'':65 ''confound'':317 ''construct'':364,423 ''contend'':394 ''dikaiosun'':223 ''divin'':382,462 ''doctrin'':472 ''doubt'':405,442 ''easier'':468 ''either'':9,16,420 ''embrac'':161 ''en'':222 ''epistl'':32,80,111,142 ''erasmus'':412 ''etc'':42,227 ''evid'':144 ''explain'':211 ''faith'':131,188,235 ''famous'':246 ''first'':28,31,79 ''former'':152 ''free'':439 ''fulli'':210 ''furnish'':377 ''general'':300 ''gentil'':166 ''given'':365 ''god'':198,205,311,347,355 ''greek'':359,434 ''grotius'':409 ''ground'':287,323 ''hear'':20 ''heir'':184 ''howev'':46,88,406 ''indefinit'':297 ''intend'':159 ''introduct'':153 ''jesus'':75,351,386 ''jewish'':139 ''john'':62 ''justif'':203,289,309 ''languag'':435 ''law'':431 ''like'':23,129 ''lord'':385 ''made'':294 ''make'':229,276,445 ''mani'':162 ''margin'':3,353,368 ''matthew'':66 ''may'':416 ''mean'':19,487 ''method'':201,303 ''middleton'':388 ''must'':484 ''name'':6,25,44,50,308 ''newcom'':265 ''note'':120,168,214,342 ''object'':233 ''obtain'':128 ''origin'':140,167,182,220 ''other'':393,411 ''passag'':451 ''paul'':87,254 ''perhap'':22 ''periphrasi'':338 ''person'':149 ''peter'':2,34,39,51,170,251 ''philippian'':114,115 ''phrase'':247 ''plain'':478 ''plan'':301 ''precious'':130 ''prefer'':328 ''proof'':455 ''proof-text'':454 ''proper'':18,49,401,447 ''prove'':470 ''regard'':239 ''reject'':278 ''render'':243,305,375,402 ''respect'':193 ''righteous'':196,226,231 ''roman'':98,122,216,255,258,344 ''saviour'':61,350,357,465 ''section'':154 ''see'':118,208,339 ''sens'':421 ''servant'':70,92 ''show'':481 ''signific'':29 ''simeon'':12 ''simon'':1,10,13,45 ''simpli'':38 ''singular'':262 ''slade'':389 ''socinian'':270 ''speak'':296 ''special'':285 ''state'':284 ''stuart'':307 ''success'':315 ''sumeon'':15 ''supplementari'':341 ''suppos'':413 ''symeon'':4 ''taken'':418 ''text'':456,475 ''thing'':319 ''though'':424 ''timothi'':105 ''true'':374,399 ''undoubt'':361 ''unhappi'':263 ''us'':133,135,277 ''use'':86,89,249,266,449 ''valpi'':390 ''version'':271 ''violat'':428 ''wetstein'':408 ''whatev'':179 ''word'':17,82,91,333 ''would'':274 ''written'':8,145', NULL, '1157');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1270', '2', '1270', NULL, 'This second epistle, beloved, I now write unto you - This expression proves that he had written a former epistle, and that it was addressed to the same persons as this. Compare Introduction, Section 3.In both which I stir up your pure minds ... - That is, the main object of both epistles is the same - to call to your remembrance important truths which you have before heard, but which you are in danger of forgetting, or from which you are in danger of being turned away by prevailing errors. Compare the notes at 2 Peter 1:12-15. The word rendered "pure" (&#x3b5;&#x3b9;&#x3bb;&#x3b9;&#x3ba;&#x3c1;&#x3b9;&#x3bd;&#x3b7;&#x3c2;  eilikrines) occurs only here and in Philippians 1:10, where it is rendered "sincere." The word properly refers to "that which may be judged of in sunshine;" then it means "clear, manifest;" and then "sincere, pure" - as that in which there is no obscurity. The idea here perhaps is, that their minds were open, frank, candid, sincere, rather than that they were "pure." The apostle regarded them as "disposed" to see the truth, and yet as liable to be led astray by the plausible errors of others. Such minds need to have truths often brought fresh to their remembrance, though they are truths with which they had before been familiar.', NULL, NULL, '''-15'':96 ''1'':94,108 ''10'':109 ''12'':95 ''2'':92 ''3.in'':34 ''address'':24 ''apostl'':165 ''astray'':181 ''away'':84 ''belov'':4 ''brought'':195 ''call'':55 ''candid'':156 ''clear'':131 ''compar'':31,88 ''danger'':71,80 ''dispos'':169 ''eilikrin'':101 ''epistl'':3,19,50 ''error'':87,185 ''express'':11 ''familiar'':210 ''forget'':73 ''former'':18 ''frank'':155 ''fresh'':196 ''heard'':65 ''idea'':146 ''import'':59 ''introduct'':32 ''judg'':124 ''led'':180 ''liabl'':177 ''main'':46 ''manifest'':132 ''may'':122 ''mean'':130 ''mind'':42,152,189 ''need'':190 ''note'':90 ''object'':47 ''obscur'':144 ''occur'':102 ''often'':194 ''open'':154 ''other'':187 ''perhap'':148 ''person'':28 ''peter'':93 ''philippian'':107 ''plausibl'':184 ''prevail'':86 ''proper'':117 ''prove'':12 ''pure'':41,100,136,163 ''rather'':158 ''refer'':118 ''regard'':166 ''remembr'':58,199 ''render'':99,113 ''second'':2 ''section'':33 ''see'':171 ''sincer'':114,135,157 ''stir'':38 ''sunshin'':127 ''though'':200 ''truth'':60,173,193,203 ''turn'':83 ''unto'':8 ''word'':98,116 ''write'':7 ''written'':16 ''yet'':175', NULL, '1159');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1271', '2', '1271', NULL, 'That which was from the beginning - There can be no doubt that the reference here is to the Lord Jesus Christ, or the "Word" that was made flesh. See the notes at John 1:1. This is such language as John would use respecting him, and indeed the phrase "the beginning," as applicable to the Lord Jesus, is unique to John in the writings of the New Testament: and the language here may be regarded as one proof that this Epistle was written by him, for it is just such an expression as "he" would use, but not such as one would be likely to adopt who should attempt to palm off his own writings as those of John. One who should have attempted that would have been likely to introduce the name "John" in the beginning of the Epistle, or in some way to have claimed his authority. The apostle, in speaking of "that which was from the beginning," uses a word in the neuter gender instead of the masculine, (&#x3bf;  ho.) It is not to be supposed, I think, that he meant to apply this term "directly" to the Son of God, for if he had he would have used the masculine pronoun; but though he had the Son of God in view, and meant to make a strong affirmation respecting him, yet the particular thing here referred to was "whatever" there was respecting that incarnate Saviour that furnished testimony to any of the senses, or that pertained to his character and doctrine, he had borne witness to.He was looking rather at the evidence that he was incarnate; the proofs that he was manifested; and he says that those proofs had been subjected to the trial of the senses, and he had borne witness to them, and now did it again. This is what is referred to, it seems to me, by the phrase "that which," (&#x3bf;  ho.) The sense may be this: "Whatever there was respecting the Word of life, or him who is the living Word, the incarnate Son of God, from the very beginning, from the time when he was first manifested in the flesh; whatever there was respecting his exalted nature, his dignity, his character, that could be subjected to the testimony of the senses, to be the object of sight, or hearing, or touch, that I was permitted to see, and that I declare to you respecting him." John claims to be a competent witness in reference to everything which occurred as a manifestation of what the Son of God was.If this be the correct interpretation, then the phrase "from the beginning" (&#x3b1;&#x3c0;  &#x3b1;&#x3c1;&#x3c7;&#x3b7;&#x3c2;  ap'' arches does not here refer to his eternity, or his being in the beginning of all things, as the phrase "in the beginning" (&#x3b5;&#x3bd; &#x3b1;&#x3c1;&#x3c7;&#x3b7;  en arche) does in John 1:1; but rather means from the very commencement of his manifestation as the Son of God, the very first indications on earth of what he was as the Messiah. When the writer says 1 John 1:3 that he "declares" this to them, it seems to me that he has not reference merely to what he would say in this Epistle, for he does not go extensively into it here, but that he supposes that they had his Gospel in their possession, and that he also means to refer to that, or presumes that they were familiar with the testimony which he had borne in that Gospel respecting the evidence that the "Word became flesh." Many have indeed supposed that this Epistle accompanied the Gospel when it was published, and was either a part of it that became subsequently detached from it, or was a letter that accompanied it. See Hug, Introduction P. II. Section 68. There is, it seems to me, no certain evidence of that; but no one can doubt that he supposed that those to whom he wrote had access to that Gospel, and that he refers here to the testimony which he had borne in that respecting the incarnate Word.Which we have heard - John was with the Saviour through the whole of his ministry, and he has recorded more that the Saviour said than either of the other evangelists. It is on what he said of himself that he grounds much of the evidence that he was the Son of God.Which we have seen with our eyes - That is, pertaining to his person, and to what he did. "I have seen him; seen what he was as a man; how he appeared on earth; and I have seen whatever there was in his works to indicate his character and origin." John professes here to have seen enough in this respect to furnish evidence that he was the Son of God. It is not hearsay on which he relies, but he had the testimony of his own eyes in the case. Compare the notes at 2 Peter 1:16.Which we have looked upon - The word used here seems designed to be more emphatic or intensive than the one occurring before. He had just said that he had "seen him with his eyes," but he evidently designs to include an idea in this word which would imply something more than mere beholding or seeing. The additional idea which is couched in this word seems to be that of desire or pleasure; that is, that he had looked on him with desire, or satisfaction, or with the pleasure with which one beholds a beloved object. Compare Matthew 11:7; Luke 7:', NULL, NULL, '''1'':34,35,467,468,501,503,818 ''11'':916 ''16.which'':819 ''2'':816 ''3'':504 ''68'':623 ''7'':917,919 ''access'':650 ''accompani'':590,615 ''addit'':875 ''adopt'':106 ''affirm'':221 ''also'':553 ''ap'':438 ''apostl'':151 ''appear'':753 ''appli'':185 ''applic'':53 ''arch'':439,463 ''attempt'':109,124 ''author'':149 ''becam'':581,605 ''begin'':6,51,137,160,347,437,452,461 ''behold'':871,910 ''belov'':912 ''born'':257,294,571,665 ''case'':811 ''certain'':631 ''charact'':252,369,769 ''christ'':21 ''claim'':147,405 ''commenc'':475 ''compar'':812,914 ''compet'':409 ''correct'':430 ''couch'':879 ''could'':371 ''declar'':399,507 ''design'':829,856 ''desir'':888,900 ''detach'':607 ''digniti'':367 ''direct'':188 ''doctrin'':254 ''doubt'':11,639 ''earth'':489,755 ''either'':599,696 ''emphat'':833 ''en'':462 ''enough