INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1273', '2', '1273', NULL, 'Behold, what manner of love - What love, in "kind" and in "degree." In kind the most tender and the most ennobling, in adopting us into His family, and in permitting us to address Him as our Father; in "degree" the most exalted, since there is no higher love that can be shown than in adopting a poor and friendless orphan, and giving him a parent and a home. Even God could bestow upon us no more valuable token of affection than that we should be adopted into His family, and permitted to regard Him as our Father. When we remember how insignificant we are as creatures, and how ungrateful, rebellious, and vile we have been as sinners, we may well be amazed at the love which would adopt us into the holy family of God, so that we may be regarded and treated as the children of the Most High. A prince could manifest no higher love for a wandering, ragged, vicious orphan boy, found in the streets, than by adopting him into his own family, and admitting him to the same privileges and honors as his own sons; and yet this would be a trifle compared with the honor which God has bestowed on us.The Father hath bestowed upon us - God, regarded as a Father, or as at the head of the universe considered as one family.That we should be called the sons of God - That is, that we should "be" the sons of God - the word "called" being often used in the sense of "to be." On the nature and privileges of adoption, see the Romans 8:15-17 notes; 2 Corinthians 6:18 note, and practical remarks on that chapter.Therefore the world knoweth us not - Does not understand our principles; the reasons of our conduct; the sources of our comforts and joys. The people of the world regard us as fanatics or enthusiasts; as foolish in abandoning the pleasures and pursuits which they engage in; as renouncing certain happiness for that which is uncertain; as cherishing false and delusive hopes in regard to the future, and as practicing needless austerities, with nothing to compensate for the pleasures which are abandoned. There is nothing which the frivolous, the ambitious, and the selfish "less" understand than they do the elements which go into the Christian''s character, and the nature and source of the Christian''s joys.Because it knew him not - It did not know the Lord Jesus Christ. That is, the world had no right views of the real character of the Lord Jesus when he was on the earth. They mistook him for an enthusiast or an impostor; and it is no wonder that, having wholly mistaken his character, they should mistake ours. On the fact that the world did not know him, see the 1 Corinthians 2:8 note; Acts 3:17 note. Compare John 17:25. On the fact that Christians may be expected to be regarded and treated as their Saviour was, see the notes at John 15:18-20. Compare Matthew 10:24-25.', NULL, NULL, '''-17'':271 ''-20'':506 ''-25'':511 ''1'':469 ''10'':509 ''15'':270,504 ''17'':476,480 ''18'':276,505 ''2'':273,471 ''24'':510 ''25'':481 ''3'':475 ''6'':275 ''8'':269,472 ''abandon'':320,363 ''act'':474 ''address'':33 ''admit'':178 ''adopt'':23,55,86,128,171,265 ''affect'':80 ''amaz'':122 ''ambiti'':371 ''auster'':353 ''behold'':1 ''bestow'':72,204,209 ''boy'':164 ''call'':232,249 ''certain'':331 ''chapter.therefore'':283 ''charact'':388,422,452 ''cherish'':339 ''children'':146 ''christ'':410 ''christian'':386,396,486 ''comfort'':303 ''compar'':197,478,507 ''compens'':357 ''conduct'':298 ''consid'':225 ''corinthian'':274,470 ''could'':71,153 ''creatur'':106 ''degre'':12,39 ''delus'':342 ''earth'':432 ''element'':381 ''engag'':327 ''ennobl'':21 ''enthusiast'':316,438 ''even'':69 ''exalt'':42 ''expect'':489 ''fact'':459,484 ''fals'':340 ''famili'':27,89,133,176 ''family.that'':228 ''fanat'':314 ''father'':37,97,207,216 ''foolish'':318 ''found'':165 ''friendless'':59 ''frivol'':369 ''futur'':348 ''give'':62 ''go'':383 