INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('216', '2', '216', NULL, 'Deborah, as "a prophetess," both composed and sang this noble ode, which, for poetic spirit and lyric fire, is not surpassed by any of the sacred songs in the Bible. And, as Miriam took up the first verse of the song of Moses Exodus 15:21, and sang it as an antiphony, so Barak, with the chorus of men, answered the song of Deborah by singing Judges 5:2, which is also exactly suited for an antiphon, summing up as it does the subject matter of the whole ode. Compare David''s example 2 Samuel 6:15.', NULL, NULL, '''15'':45,97 ''2'':69,94 ''21'':46 ''5'':68 ''6'':96 ''also'':72 ''answer'':60 ''antiphon'':77 ''antiphoni'':52 ''barak'':54 ''bibl'':30 ''chorus'':57 ''compar'':90 ''compos'':6 ''david'':91 ''deborah'':1,64 ''exact'':73 ''exampl'':93 ''exodus'':44 ''fire'':18 ''first'':37 ''judg'':67 ''lyric'':17 ''matter'':85 ''men'':59 ''miriam'':33 ''mose'':43 ''nobl'':10 ''ode'':11,89 ''poetic'':14 ''prophetess'':4 ''sacr'':26 ''samuel'':95 ''sang'':8,48 ''sing'':66 ''song'':27,41,62 ''spirit'':15 ''subject'':84 ''suit'':74 ''sum'':78 ''surpass'':21 ''took'':34 ''vers'':38 ''whole'':88', NULL, '216');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1274', '2', '1274', NULL, 'Beloved, believe not every spirit - Do not confide implicitly in everyone who professes to be under the influences of the Holy Spirit. Compare Matthew 24:4-5. The true and the false teachers of religion alike claimed to be under the influence of the Spirit of God, and it was of importance that all such pretensions should be examined. It was not to be admitted because anyone claimed to have been sent from God that therefore he was sent. Every such claim should be subjected to the proper proof before it was conceded. All pretensions to divine inspiration, or to being authorised teachers of religion, were to be examined by the proper tests, because there were many false and delusive teachers who set up such claims in the world.But try the spirits whether they are of God - There were those in the early Christian church who had the gift of "discerning spirits," (see the notes at 1 Corinthians 12:10), but it is not certain that the apostle refers here to any such supernatural power. It is more probable, as he addresses this command to Christians in general, that he refers to the ability of doing this by a comparison of the doctrines which they professed to hold with what was revealed, and by the fruits of their doctrines in their lives. If they taught what God had taught in his word, and if their lives corresponded with his requirements, and if their doctrines agreed with what had been inculcated by those who were admitted to be true apostles, 1 John 4:6, they were to receive them as what they professed to be. If not, they were to reject them, and hold them to be impostors. It may be remarked, that it is just as proper and as important now to examine the claims of all who profess to be teachers of religion, as it was then. In a matter so momentous as religion, and where there is so much at stake, it is important that all pretensions of this kind should be subjected to a rigid examination. No one should be received as a religious teacher without the clearest evidence that he has come in accordance with the will of God, nor unless he inculcates the very truth which God has revealed. See the Isaiah 8:20 note, and Acts 17:11 note.Because many false prophets are gone out into the world - The word prophet is often used in the New Testament to denote religious instructors or preachers. See the notes at Romans 12:6. Compare the notes at 2 Peter 2:1. Such false teachers evidently abounded in the times here referred to. See the notes at 1 John 2:18. The meaning is, that many had gone out into the world pretending to be true teachers of religion, but who inculcated most dangerous doctrines; and it was their duty to be on their guard against them, for they had the very spirit of antichrist, 1 John 4:3.', NULL, NULL, '''-5'':27 ''1'':157,260,435,451,499 ''10'':160 ''11'':394 ''12'':159,426 ''17'':393 ''18'':454 ''2'':432,434,453 ''20'':389 ''24'':25 ''3'':502 ''4'':26,262,501 ''6'':263,427 ''8'':388 ''abil'':194 ''abound'':440 ''accord'':368 ''act'':392 ''address'':182 ''admit'':65,255 ''agre'':245 ''alik'':36 ''antichrist'':498 ''anyon'':67 ''apostl'':168,259 ''authoris'':102 ''believ'':2 ''belov'':1 ''certain'':165 ''christian'':144,186 ''church'':145 ''claim'':37,68,82,126,305 ''clearest'':361 ''come'':366 ''command'':184 ''compar'':23,428 ''comparison'':200 ''conced'':93 ''confid'':8 ''corinthian'':158 ''correspond'':237 ''danger'':477 ''delus'':120 ''denot'':416 ''discern'':151 ''divin'':97 ''doctrin'':203,219,244,478 ''duti'':483 ''earli'':143 ''everi'':4,80 ''everyon'':11 ''evid'':362,439 ''examin'':59,109,303,349 ''fals'':32,118,397,437 ''fruit'':216 ''general'':188 ''gift'':149 ''god'':47,74,137,227,373,382 ''gone'':400,461 ''guard'':488 ''hold'':208,283 ''holi'':21 ''implicit'':9 ''import'':52,300,336 ''impostor'':287 ''inculc'':250,377,475 ''influenc'':18,42 ''inspir'':98 '