INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1275', '2', '1275', NULL, 'Whosoever believeth that Jesus is the Christ - Is the Messiah; the anointed of God. On the meaning of the word Christ, see the notes at Matthew 1:1. Of course, it is meant here that the proposition, that "Jesus is the Christ," should be believed or received in the true and proper sense, in order to furnish evidence that anyone is born of God. Compare the notes at 1 John 4:3. It cannot be supposed that a mere intellectual acknowledgment of the proposition that Jesus is the Messiah is all that is meant, for that is not the proper meaning of the word believe in the Scriptures. That word, in its just sense, implies that the truth which is believed should make its fair and legitimate impression on the mind, or that we should feel and act as if it were true. See the notes at Mark 16:16. If, in the proper sense of the phrase, a man does believe that Jesus "is the Christ," receiving him as he is revealed as the Anointed of God, and a Saviour, it is undoubtedly true that that constitutes him a Christian, for that is what is required of a man in order that he may be saved. See the notes at Acts 8:37.Is born of God - Or rather, "is begotten of God." See the notes at John 3:3And everyone that loveth him that begat - That loves that God who has thus begotten those whom he has received as his children, and to whom he sustains the endearing relation of Father.Loveth him also that is begotten of him - That is, he will love all the true children of God; all Christians. See the notes at 1 John 4:20. The general idea is, that as all Christians are the children of the same Father; as they constitute one family; as they all bear the same image; as they share his favor alike; as they are under the same obligation of gratitude to him, and are bound to promote the same common cause, and are to dwell together in the same home forever, they should therefore love one another. As all the children in a family love their common father, so it should be in the great family of which God is the Head.', NULL, NULL, '''1'':27,28,69,287 ''16'':149,150 ''20'':290 ''3'':72,229 ''37.is'':214 ''3and'':230 ''4'':71,289 ''8'':213 ''acknowledg'':81 ''act'':138,212 ''alik'':323 ''also'':264 ''anoint'':12,176 ''anoth'':359 ''anyon'':60 ''bear'':314 ''begat'':236 ''begotten'':221,244,267 ''believ'':45,105,121,162 ''believeth'':2 ''born'':62,215 ''bound'':337 ''cannot'':74 ''caus'':343 ''children'':252,278,301,363 ''christ'':7,21,42,167 ''christian'':191,282,298 ''common'':342,369 ''compar'':65 ''constitut'':188,308 ''cours'':30 ''dwell'':347 ''endear'':259 ''everyon'':231 ''evid'':58 ''fair'':125 ''famili'':310,366,378 ''father'':305,370 ''father.loveth'':262 ''favor'':322 ''feel'':136 ''forev'':353 ''furnish'':57 ''general'':292 ''god'':14,64,178,217,223,240,280,381 ''gratitud'':332 ''great'':377 ''head'':384 ''home'':352 ''idea'':293 ''imag'':317 ''impli'':115 ''impress'':128 ''intellectu'':80 ''jesus'':4,39,86,164 ''john'':70,228,288 ''legitim'':127 ''love'':238,274,357,367 ''loveth'':233 ''make'':123 ''man'':160,200 ''mark'':148 ''matthew'':26 ''may'':205 ''mean'':17,101 ''meant'':33,94 ''mere'':79 ''messiah'':10,89 ''mind'':131 ''note'':24,67,146,210,226,285 ''oblig'':330 ''one'':309,358 ''order'':55,202 ''phrase'':158 ''promot'':339 ''proper'':52,100,154 ''proposit'':37,84 ''rather'':219 ''receiv'':47,168,249 ''relat'':260 ''requir'':197 ''reveal'':173 ''save'':207 ''saviour'':181 ''scriptur'':108 ''see'':22,144,208,224,283 ''sens'':53,114,155 ''share'':320 ''suppos'':76 ''sustain'':257 ''therefor'':356 ''thus'':243 ''togeth'':348 ''true'':50,143,185,277 ''truth'':118 ''undoubt'':184 ''whosoev'':1 ''word'':20,104,110', NULL, '1164');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1276', '2', '1276', NULL, 'The elder - See the introduction, Section 1, (2,d).Unto the elect lady - The elect or chosen Kyria. See the introduction, Section 2. He addresses her as one chosen of God to salvation, in the use of a term often applied to Christians in the New Testament.And her children - The word here rendered "children" (&#x3c4;&#x3b5;&#x3ba;&#x3bd;&#x3bf;&#x3b9;&#x3c2;  teknois) would include in itself both sons and daughters, but since the apostle immediately uses a masculine pronoun, &#x3c4;&#x3bf;&#x3b9;&#x3c2;  tois it would seem more probable that sons only were intended. At all events, the use of such a pronoun proves that some at least of her children were sons. Of their number and character we have no information, except that (the notes at 2 John 1:4) a part of them were Christians.Whom I love in the truth - See the notes, John 3:18. The meaning here is, that he "truly" or "sincerely" loved them. The introduction of the article the here, which is not in the original, (&#x3b5;&#x3bd; &#x3b1;&#x3bb;&#x3b7;&#x3b8;&#x3b9;&#x3b1;  en alethia) somewhat obscures the sense, as if the meaning were that he loved them so far as they embraced the truth. The meaning however is, that he was sincerely attached to them. The word "whom" here, (&#x3bf;&#x3c5;&#x3c2;  hous,) embraces both the mother and her children, though the pronoun is in the masculine gender, in accordance with the usage of the Greek language. No mention is made of her husband, and it may thence be inferred that she was a widow. Had he been living, though he might not have been a Christian, it is to be presumed that some allusion would have been made to him as well as to the children, especially since there is reason to believe that only some of her children were pious. See the notes, 2 John 1:4.And not I only, but also all they that have known the truth - That is, all those Christians who had had an opportunity of knowing them, were sincerely attached to them. It would seem, from a subsequent part of the Epistle 2 John 1:10, that this female was of a hospitable character, and was accustomed to entertain at her house the professed friends of religion, especially religious teachers, and it is probable that she was the more extensively known from this fact. The commendation of the apostle here shows that it is possible that a family shall be extensively known as one of order, peace, and religion, so that all who know it or hear of it shall regard it with interest, respect, and love.', NULL, NULL, '''1'':7,119,294,338 ''10'':339 ''18'':137 ''2'':8,23,117,292,336 ''3'':136 ''4'':120 ''4.and'':295 ''accord'':216 ''accustom'':350 ''address'':25 ''alethia'':163 ''allus'':261 ''also'':300 ''apostl'':67,382 ''appli'':41 ''articl'':153 ''attach'':192,323 ''believ'':280 ''charact'':107,347 ''children'':49,54,100,206,273,286 ''chosen'':17,29 ''christian'':43,253,312 ''christians.whom'':126 ''commend'':379 ''d'':9 ''daughter'':63 ''elder'':2 ''elect'':12,15 ''embrac'':181,200 ''en'':162 ''entertain'':352 ''epistl'':335 ''especi'':274,361 ''event'':86 ''except'':112 ''extens'':373,394 ''fact'':377 ''famili'':391 ''far'':178 ''femal'':342 ''friend'':358 ''gender'':214 ''god'':31 ''greek'':222 ''hear'':410 ''hospit'':346 ''hous'':199,355 ''howev'':186 ''husband'':230 ''immedi'':68 ''includ'':57 ''infer'':236 ''inform'':111 ''intend'':83 ''interest'':417 ''introduct'':5,21,150 ''john'':118,135,293,337 ''know'':319,407 ''known'':305,374,395 ''kyria'':18 ''ladi'':13 ''languag'':223 ''least'':97 ''live'':245 ''love'':128,147,175,420 ''made'':227,265 ''masculin'':71,213 ''may'':233 ''mean'':139,171,185 ''mention'':225 ''might'':248 ''mother'':203 ''new'':46 ''note'':115,134,291 ''number'':105 ''obscur'':165 ''often'':40 ''one'':28,397 ''opportun'':317 ''order'':399 ''origin'':161 ''part'':122,332 ''peac'':400 ''pious'':288 ''possibl'':388 ''presum'':258 ''probabl'':78,367 ''profess'':357 ''pronoun'':72,92,209 ''prove'':93 ''reason'':278 ''regard'':414 ''religi'':362 ''religion'':360,402 ''render'':53 ''respect'':418 ''salvat'':33 ''section'':6,22 ''see'':3,19,132,289 ''seem'':76,328 ''sens'':167 ''shall'':392,413 ''show'':384 ''sinc'':65,275 ''sincer'':146,191,322 ''somewhat'':164 ''son'':61,80,102 ''subsequ'':331 ''teacher'':363 ''teknoi'':55 ''term'':39 ''testament.and'':47 ''thenc'':234 ''though'':207,246 ''toi'':73 ''truli'':144 ''truth'':131,183,307 ''unto'':10 ''usag'':219 ''use'':36,69,88 ''well'':269 ''widow'':241 ''word'':51,196 ''would'':56,75,262,327', NULL, '1165');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1277', '2', '1277', NULL, 'This brief Epistle, written to a Christian whose name was Gaius, of whom nothing more is known (compare the notes at 3 John 1:1), and in respect to which the time and place of writing it are equally unknown, embraces the following subjects:I. The address, with an expression of tender attachment, and an earnest wish for his welfare and happiness, 3 John 1:1-2.II. A commendation of his character and doings, as the writer had learned it from some brethren who had visited him particularly;(a) for his attachment to the truth, and,(b) for his kindness shown to the members of his own church, and to strangers who had gone forth to some work of charity, 3 John 1:3-8.III. The writer then adverts to the fact that he had written upon this subject to the church, commending these strangers to their attention, but that Diotrephes would not acknowledge his authority, or receive those whom he introduced to them. This conduct, he said, demanded rebuke; and he says that when he himself came, he would take proper measures to assert his own authority, and show to him and to the church the duty of receiving Christian brethren commended to them from abroad, 3 John 1:9-10.IV. He exhorts Gaius to persevere in that which was good - in a life of love and kindness, in an imitation of the benevolent God, 3 John 1:11.V. Of another person - Demetrius - who, it would seem, had been associated with Gaius in the honorable course which he had pursued, in opposition to what the church had done, he also speaks in terms of commendation, and says that the same honorable testimony had been borne of him which had been of Gaius, 3 John 1:12.VI. As in the second Epistle, he says, in the close, that there were many things which he would be glad to say to him, but there were reasons why they should not be set down "with ink and pen," but he hoped soon to confer with him freely on those subjects face to face, and the Epistle is closed by kind salutations, 3 John 1:13-14.The occasion upon which the Epistle was written is no further known than appears from the Epistle itself. From this, the following facts are all that can now be ascertained:(1) That Gaius was a Christian man, and evidently a member of the church, but of what church is unknown.(2) that there were certain persons known to the writer of the Epistle, and who either lived where he did, or who had been commended to him by others who proposed to travel to the place where Gaius lived. Their particular object is not known, further than that it is said 3 John 1:7 that they "went for his name''s sake;" that is, in the cause of religion. It further appears that they had resolved not to be dependent upon the pagan for their support, but wished the favor and friendship of the church - perhaps designing to preach to the pagan, and yet apprehending that if they desired their maintenance from them, it would be charged on them that they were mercenary in their ends.(3) in these circumstances, and with this view, the author of this Epistle wrote to the church, commending these brethren to their kind and fraternal regards.(4) this recommendation, so far as appears, would have been successful, had it not been for one man, Diotrephes, who had so much influence, and who made such violent opposition, that the church refused to receive them, and they became dependent upon private charity. The ground of the opposition of Diotrephes is not fully stated, but it seems to have arisen from two sources:(a) a desire to rule in the church; and,(b) a particular opposition to the writer of this Epistle, and a denial of any obligation to recognize his instructions or commendations as binding. The idea seems to have been that the church was entirely independent, and might receive or reject any whom it pleased, though they were commended to them by an apostle.(5) in these circumstances, Gaius, as an individual, and against the action of the church, received and hospitably entertained these strangers, and aided them in the prosecution of their work. In this office of hospitality another member of the church, Demetrius, also shared; and to commend them for this work, particularly Gaius, at whose house probably they were entertained, is the design of this Epistle.(6) after having returned to the writer of this Epistle, who had formerly commended them to the church, and having borne honorable testimony to the hospitality of Gaius, it would seem that they resolved to repeat their journey for the same purpose, and that the writer of the Epistle commended them now to the renewed hospitality of Gaius. On this occasion, probably, they bore this Epistle to him. See the notes at 3 John 1:6-7. Nothing more is known of Diotrephes than is here specified. Erasmus and Bede supposed that he was the author of a new sect; but of this there is no evidence, and if he had been, it is probable that John would have cautioned Gaius against his influence. Many have supposed that he was a self-appointed "Bishop" or "Pastor" in the church where he resid', NULL, NULL, '''-7'':832 ''1'':24,25,65,122,208,236,294,360,391,464,830 ''1-2.ii'':66 ''11'':237 ''12.vi'':295 ''13-14.the'':361 ''2'':411 ''3'':22,63,120,206,234,292,358,462,538,828 ''3-8.iii'':123 ''4'':564 ''5'':691 ''6'':756,831 ''7'':465 ''9-10.iv'':209 ''abroad'':205 ''acknowledg'':152 ''action'':702 ''address'':47 ''advert'':127 ''aid'':713 ''also'':269,732 ''anoth'':240,726 ''apostl'':690 ''appear'':374,483,570 ''appoint'':889 ''apprehend'':516 ''arisen'':624 ''ascertain'':390 ''assert'':183 ''associ'':249 ''attach'':53,91 ''attent'':146 ''author'':154,186,547,851 ''b'':96,637 ''becam'':603 ''bede'':845 ''benevol'':232 ''bind'':660 ''bishop'':890 ''bore'':819 ''born'':284,776 ''brethren'':82,200,557 ''brief'':2 ''came'':176 ''caus'':478 ''caution'':875 ''certain'':415 ''charact'':71 ''charg'':528 ''chariti'':119,6