INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1278', '2', '1278', NULL, 'Jude, the servant of Jesus Christ - If the view taken in the Introduction to the Epistle is correct, Jude sustained a near relation to the Lord Jesus, being, as James was, "the Lord''s brother," Galatians 1:19. The reasons why he did not advert to this fact here, as an appellation which would serve to designate him, and as showing his authority to address others in the manner in which he proposed to do in this Epistle, probably were,(1) that the right to do this did not rest on his mere "relationship" to the Lord Jesus, but on the fact that he had called certain persons to be his apostles, and had authorized them to do it; and,(2) that a reference to this relationship, as a ground of authority, might have created jealousies among the apostles themselves. We may learn from the fact that Jude merely calls himself "the servant of the Lord Jesus," that is, a Christian,(a) that this is a distinction more to be desired than, would be a mere natural relationship to the Saviour, and consequently.(b) that it is a higher honor than any distinction arising from birth or family. Compare Matthew 12:46-50.And brother of James - See the introduction, Section 1.To them that are sanctified by God the Father - To those who are "holy," or who are "saints." Compare the Romans 1:7 note; Philippians 1:1 note. Though this title is general, it can hardly be doubted that he had some particular saints in his view, to wit, those who were exposed to the dangers to which he refers in the Epistle. See Introduction, Section 3. As the Epistle was probably "sent" to Christians residing in a certain place, it was not necessary to designate them more particularly, though it was often done. The Syriac version adds here: "To the Gentiles who are called, beloved of God the Father," etc.And preserved in Jesus Christ - See the notes, 1 Peter 1:5. The meaning is, that they owed their preservation wholly to him; and if they were brought to everlasting life, it would be only by him. What the apostle here says of those to whom he wrote, is true of all Christians. They would all fall away and perish if it were not for the grace of God keeping them.And called - Called to be saints. See Romans 1:7 note; Ephesians 4:1 note.', NULL, NULL, '''1'':37,81,231,235,236,328,330,398,403 ''1.to'':210 ''12'':201 ''19'':38 ''2'':121 ''3'':276 ''4'':402 ''46-50.and'':202 ''5'':331 ''7'':232,399 ''add'':307 ''address'':65 ''advert'':45 ''among'':137 ''apostl'':112,139,359 ''appel'':52 ''aris'':194 ''author'':63,115,132 ''away'':377 ''b'':184 ''belov'':315 ''birth'':196 ''brother'':35,203 ''brought'':347 ''call'':106,150,314,391,392 ''certain'':107,288 ''christ'':6,324 ''christian'':161,284,372 ''compar'':199,228 ''consequ'':183 ''correct'':18 ''creat'':135 ''danger'':265 ''design'':57,295 ''desir'':171 ''distinct'':167,193 ''done'':303 ''doubt'':247 ''ephesian'':401 ''epistl'':16,78,272,279 ''etc.and'':320 ''everlast'':349 ''expos'':262 ''fact'':48,102,146 ''fall'':376 ''famili'':198 ''father'':218,319 ''galatian'':36 ''general'':242 ''gentil'':311 ''god'':216,317,388 ''grace'':386 ''ground'':130 ''hard'':245 ''higher'':189 ''holi'':223 ''honor'':190 ''introduct'':13,208,274 ''jame'':30,205 ''jealousi'':136 ''jesus'':5,27,98,157,323 ''jude'':1,19,148 ''keep'':389 ''learn'':143 ''life'':350 ''lord'':26,33,97,156 ''manner'':69 ''matthew'':200 ''may'':142 ''mean'':333 ''mere'':93,149,176 ''might'':133 ''natur'':177 ''near'':22 ''necessari'':293 ''note'':233,237,327,400,404 ''often'':302 ''other'':66 ''owe'':337 ''particular'':252,298 ''perish'':379 ''person'':108 ''peter'':329 ''philippian'':234 ''place'':289 ''preserv'':321,339 ''probabl'':79,281 ''propos'':73 ''reason'':40 ''refer'':124,269 ''relat'':23 ''relationship'':94,127,178 ''resid'':285 ''rest'':90 ''right'':84 ''roman'':230,397 ''saint'':227,253,395 ''sanctifi'':214 ''saviour'':181 ''say'':361 ''section'':209,275 ''see'':206,273,325,396 ''sent'':282 ''serv'':55 ''servant'':3,153 ''show'':61 ''sustain'':20 ''syriac'':305 ''taken'':10 ''them.and'':390 ''though'':238,299 ''titl'':240 ''true'':369 ''version'':306 ''view'':9,256 ''wholli'':340 ''wit'':258 ''would'':54,173,352,374 ''wrote'':367', NULL, '1167');
INSERT INTO sections (id, source_id, ordinal, heading, body, period_start_year, period_end_year, tsv, source_url, unit_ordinal) VALUES ('1279', '2', '1279', NULL, 'The Revelation of Jesus Christ - This is evidently a title or caption of the whole book, and is designed to comprise the substance of the whole; for all that the book contains would be embraced in the general declaration that it is a revelation of Jesus Christ. The word rendered "Revelation" - &#x391;&#x3c0;&#x3bf;&#x3ba;&#x3b1;&#x3bb;&#x3c5;&#x3c8;&#x3b9;&#x3c2;  Apokalupsis, whence we have derived our word "Apocalypse" - means properly an that is, nakedness; from &#x3b1;&#x3c0;&#x3bf;&#x3ba;&#x3b1;&#x3bb;&#x3c5;&#x3c0;&#x3c4;&#x3c9;  apokalupto, to uncover. It would apply to anything which had been covered up so as to be bidden from the view, as by a veil, a darkness, in an ark or chest, and then made manifest by removing the covering. It comes then to be used in the sense of disclosing or revealing, by removing the veil of darkness or ignorance. "There is nothing covered that shall not be revealed." It may be applied to the disclosing or manifesting of anything which was before obscure or unknown. This may be done:(a) by instruction in regard to what was before obscure; that is, by statements of what was unknown before the statements were made; as in Luke 2:32, where it is said that Christ would be "a light to lighten the Gentiles" - &#x3c6;&#x3c9;&#x3c2; &#x3b5;&#x3b9;&#x3c2; &#x3b1;&#x3c0;&#x3bf;&#x3ba;&#x3b1;&#x3bb;&#x3c5;&#x3c8;&#x3b9;&#x3bd; &#x3b5;&#x3b8;&#x3bd;&#x3c9;&#x3bd;  phos eis apokalupsin ethnon; or when it is applied to the divine mysteries, purposes, or doctrines, before obscure or unknown, but made clear by light revealed in the gospel, Romans 16:25; 1 Corinthians 2:10; 1 Corinthians 14:6; Ephesians 3:5.(b) by the event itself; as the manifestation of the wrath of God at the day of judgment will disclose the true nature of his wrath. "After thy hardness and impenitent heart treasurest up unto thyself wrath against the day of wrath and "revelation" of the righteous judgment of God," Revelation 2:5. "For the earnest expectation of the creature waiteth for the manifestation (Greek revelation) of the sons of God," Romans 8:19; that is until it shall be manifest by the event what they who are the children of God are to be. In this sense the word is frequently applied to the second advent or appearing of the Lord Jesus Christ, as disclosing him in his glory, or showing what he truly is; "When the Lord Jesus shall be revealed," 2 Thessalonians 1:7 - &#x3b5;&#x3bd; &#x3c4;&#x3b7; &#x3b1;&#x3c0;&#x3bf;&#x3ba;&#x3b1;&#x3bb;&#x3c5;&#x3c8;&#x3b5;&#x3b9;  en ten apokalupsei - in the revelation of Jesus Christ; "Waiting for the coming (the revelation - &#x3c4;&#x3b7;&#x3bd; &#x3b1;&#x3c0;&#x3bf;&#x3ba;&#x3b1;&#x3bb;&#x3c5;&#x3c8;&#x3b9;&#x3bd;  ten apokalupsin of our Lord Jesus Christ," 1 Corinthians 1:7; "At the appearing (Greek revelation) of Jesus Christ," 1 Peter 1:7; "When his glory shall be revealed," 1 Peter 4:13.(c) It is used in the sense of making known what is to come, whether by words, signs, or symbols, as if a veil were lifted from what is hidden from human vision, or which is covered by the darkness of the unknown future. This is called a revelation, because the knowledge of the event is in fact made known to the world by Him who alone can see it, and in such a manner as he pleases to employ; though many of the terms or the symbols may be, from the necessity of the case, obscure, and though their full meaning may be disclosed only by the event. It is in this sense, evidently, that the word is used here: and in this sense that it is more commonly employed when we speak of a revelation. Thus, the word   gaalaah is used in Amos 3:7, "Surely the Lord God will do nothing, but he revealeth his secret unto his servants." So Job 33:16, "Then he openeth (margin, revealeth or uncovereth; Heb.   yigleh the ears of men"; that is, in a dream, he discloses to their ears his truth before concealed or unknown. Compare Daniel 2:22, Daniel 2:28-29; Daniel 10:1; Deuteronomy 29:29. These ideas enter into the word as used in the passage before us. The idea is that of a disclosure of an extraordinary character, beyond the mere ability of man, by a special communication from heaven. This is manifest, not only from the usual meaning of this word, but by the word "prophecy," in Revelation 1:3, and by all the arrangements by which these things were made known. The ideas which would be naturally conveyed by the use of this word in this connection are two:(1) that there was something which was before hidden, obscure, or unknown; and,(2) that this was so disclosed by these communications as to be seen or known.The things hidden or unknown were those which pertained to the future; the method of disclosing them was mainly by symbols. In the Greek, in this passage, the article is missing - &#x3b1;&#x3c0;&#x3bf;&#x3ba;&#x3b1;&#x3bb;&#x3c5;&#x3c8;&#x3b9;&#x3c2;  apokalupsis - a Revelation, not &#x3b7;  he, the Revelation. This is omitted because it is the title of a book, and because the use of the article might imply ', NULL, NULL, '''-29'':630 ''1'':232,236,378,402,404,414,416,424,633,692,724 ''10'':235,632 ''13'':427 ''14'':238 ''16'':230,593 ''19'':316 ''2'':184,234,294,376,625,628,737 ''22'':626 ''25'':231 ''28'':629 ''29'':635,636 ''3'':241,573,693 ''32'':185 ''33'':592 ''4'':426 ''5'':242,295 ''6'':239 ''7'':379,405,417,574 ''8'':315 ''abil'':664 ''advent'':349 ''alon'':494 ''amo'':572 ''anyth'':74,147 ''apocalyps'':59 ''apokalupsei'':382 ''apokalupsi'':52,782 ''apokalupsin'':202,396 ''apokalupto'':67 ''appear'':351,408 ''appli'':72,140,208,345 ''ark'':96 ''arrang'':698 ''articl'':779,806 ''b'':243 ''beyond'':661 ''bidden'':84 ''book'':16,31,799 ''c'':428 ''call'':474 ''caption'':12 ''case'':523 ''charact'':660 ''chest'':98 ''children'':332 ''christ'':5,47,191,356,388,401,413 ''clear'':222 ''come'':108,392,441 ''common'':557 ''comm